local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:99129"] = {n="A Man About a Murloc",s="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",h="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",kw={"a man about a murloc","艾尔文森林","鱼","杰森","鱼人","雷米"},ang={["faction:Alliance"]="像湖岸和码头这样的当地定居点经常遭受鱼人的入侵，使艾尔文森林及附近联盟领地的居民和卫兵倍感压力。"},sec={{t="水域危机",b="一位叫杰森的当地渔夫对鱼人抢劫他鱼货的行为感到厌倦。由于知道雷米同样憎恨这些两栖生物，杰森指引旅行者去咨询雷米，看看他是否想出了什么有效的办法将它们从水域中驱逐出去。"},{t="雷米的报复",b="当被问及此事时，雷米发泄着他的不满，称当地卫兵拒绝理会他关于鱼人威胁的持续警告。雷米没有等待官方的援助，而是准备了自己针对这些生物的报复措施，并招募能干的旅行者来协助他的计划。"}},faq={{q="谁发布了“A Man About a Murloc”这个任务？",a="当地渔夫杰森派遣冒险者执行此任务，寻求阻止鱼人抢夺他鱼货的方法。",al={"谁发布了a man about a murloc","谁开启了a man about a murloc","杰森鱼人任务"}},{q="雷米是谁？",a="雷米是一位以不断抱怨和警告鱼人威胁而闻名的居民，杰森向他咨询对抗鱼人的实际方案。",al={"雷米是谁","艾尔文森林的雷米","雷米在哪里"}},{q="为什么杰森要咨询雷米？",a="鱼人一直在侵扰杰森的捕鱼点并偷窃他的鱼，这促使他寻求外部帮助来保护他的生计。",al={"为什么杰森需要帮助","杰森 鱼 鱼人","杰森的鱼人问题"}},{q="雷米打算如何对付鱼人？",a="雷米声称镇上的卫兵无视他的警告，因此他制定了自己针对这些生物的报复计划，并需要冒险者协助收集材料。",al={"雷米的点子","雷米的计划是什么","雷米鱼人计划"}},{q="为什么卫兵没有处理鱼人的问题？",a="根据雷米的说法，他曾多次尝试向当地卫兵警告日益严重的鱼人威胁，但他们拒绝认真对待他的警告。",al={"艾尔文森林的卫兵与鱼人","为什么卫兵不帮助雷米","雷米的卫兵警告"}},{q="和雷米交谈后会发生什么？",a="与雷米的交谈直接引出了他反击当地鱼人的个人计划，从而引发了后续代表他进行的任务。",al={"a man about a murloc指向哪里","a man about a murloc之后","雷米之后的下一个任务"}}},fp="20,273,20.278.0,18.288.0,41.127.0,24.148.0,36.139.0,44.176.0,46.155.0,36.135.0"}
P.entries["quest:99130"] = {n="An Enticing Offer",s="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",h="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",kw={"an enticing offer","duskweed","jason","鱼人诱饵","鱼人","有毒诱饵"},ang={["class:Hunter"]="追踪者和驯兽师应注意duskweed的毒性，因为如果误食，由此制成的诱饵会对家养野兽和狩猎伙伴构成严重威胁。",["profession:Herbalism"]="熟悉当地植物的采集者会认识到duskweed的双重性质，这种讨人厌的杂草在调制强效诱饵时需要小心处理其有毒花瓣。"},sec={{t="一举两得的方案",b="对付鱼人泛滥通常需要更有创意的害虫防治手段，而不是无休止的正面冲突。“An Enticing Offer”提出了一种巧妙的解决方案，可以一举解决两个当地难题：制作一种掺有duskweed的特制诱饵，以阻止鱼人侵入定居点，同时在此过程中清除邻近农田中的杂草。"},{t="Duskweed的特性",b="这种合剂的核心成分是duskweed，一种困扰附近农田的顽固野生杂草。大量duskweed的花瓣中含有对大多数野兽有害的强力毒素。通过直接从受困扰的农户那里收集这种杂草，既能清除田地里肆虐的害虫植物，其有毒的产物又能为训练鱼人种群远离此地提供必要的原材料。"},{t="水域诱饵",b="虽然所得的合剂制备起来相对简单，但duskweed无差别的毒性使得处理它具有一定的危险性。家畜和宠物必须严格远离成品混合物，任务发布者临走前还提醒确保当地的熟人，也就是那个叫Jason的人，不会把这种刺鼻的诱饵当成食物。"}},faq={{q="任务“An Enticing Offer”是什么？",a="“An Enticing Offer”是一项旨在应对当地鱼人威胁，同时协助附近农户的任务。它涉及收集材料来调制一种专门用来驱赶这些生物的特殊有毒诱饵。",al={"什么是an enticing offer","这个任务是什么"}},{q="Duskweed是什么？",a="Duskweed是一种侵扰当地农田的常见杂草。虽然它通常被视为一种农业害虫，但其花瓣在大量堆积时对大多数动物有毒，这使得它在被浓缩成诱饵后成为一种有效的害虫威慑物。",al={"什么是duskweed","duskweed植物","duskweed的效果"}},{q="这种鱼人诱饵是如何起作用的？",a="该计划是制作注入了有毒duskweed花瓣的诱饵。目标不是常规的消灭，而是让诱饵变得足够令人不快或有害，从而训练当地的鱼人种群避开该区域。",al={"诱饵是如何起作用的","鱼人毒饵","为什么要制作诱饵"}},{q="Jason是谁？",a="Jason是一位因为鱼人骚扰而把你派去找Remy的渔夫。一旦有毒的duskweed诱饵制作完成，Remy嘱咐要告诉Jason千万别吃它。",al={"jason是谁","不要让jason吃掉它","关于诱饵给jason的警告"}},{q="这种鱼人诱饵对其他生物有危险吗？",a="是的。虽然它是针对鱼人的，但大量duskweed花瓣对大多数动物都有毒。任务发布者特别提醒，必须让家养宠物和狩猎伙伴远离这种混合物。",al={"duskweed诱饵有危险吗","宠物误食诱饵"}},{q="为什么说收集duskweed是双赢的？",a="Duskweed会疯狂入侵耕地，让当地农户头疼不已。收集这种杂草来酿制诱饵既能清理农田，又能同时提供击退鱼人所需的材料。",al={"为什么要帮助农户","双赢局面"}}},fp="17,283,18.401.0,22.404.0,18.369.0,36.216.0,17.240.0,40.208.0,13.152.0,48.210.0,47.224.0"}
P.entries["quest:99131"] = {n="Baited for Success",s="“Baited for Success”的任务内容是协助当地渔夫Jason Mathers处理棘手的鱼人骚扰问题。通过与Remy合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",h="“Baited for Success”的任务内容是协助当地渔夫Jason Mathers处理棘手的鱼人骚扰问题。通过与Remy合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",kw={"baited for success","钓鱼","jason mathers","鱼人","毒饵","remy"},ang={["class:Rogue"]="使用定制毒药作为控制麻烦鱼人的害虫防治手段，体现了一种务实、低调的解决问题方式。",["faction:Alliance"]="确保水域安全并恢复渔业等当地贸易，可以在减少鱼人威胁的同时，维持定居点的物资供应。"},sec={{t="渔夫的困境",b="Jason Mathers依靠开阔水域维持渔业贸易，但一群极具攻击性的鱼人扰乱了他的工作。由于无法安全地出售渔获，他试图寻找一种解决方法来清除该地区的生物。Remy介入并制作了一种专门的毒饵，旨在减少当地的鱼人数量，以便恢复正常的捕鱼作业。"},{t="定向解决方案",b="Remy准备了这种有毒混合物，并承诺会告知正确的使用方法，确保毒药只会针对鱼人，而不会污染鱼类。收到消息后，Mathers计划在当天晚些时候去收集混合物，希望它最终能清理水域并恢复他的生计。"}},faq={{q="是谁为Jason Mathers准备了诱饵？",a="Remy为Jason Mathers准备了专用诱饵，并承诺在Mathers当天晚些时候过来时，向他说明其正确的使用方法。",al={"谁发布baited for success","remy诱饵任务","谁制作了诱饵"}},{q="为什么Jason Mathers需要这种诱饵？",a="Jason Mathers是一位渔夫，由于当地鱼人的存在，他难以出售自己的渔获。这种毒饵旨在捕杀鱼人，同时又不伤害他打算捕捞和出售的鱼类。",al={"为什么jason mathers需要诱饵","mathers渔业生意","为什么使用毒饵"}},{q="毒饵会伤害鱼类吗？",a="Mathers特别提到了他对鱼类可能会误食毒饵的担忧。该计划依赖于毒药只针对鱼人而不伤害鱼类的特性，这样Mathers就能恢复他的生计。",al={"诱饵对鱼类安全吗","毒饵会杀死鱼类吗"}},{q="这项任务在哪里完成？",a="这项任务是通过直接将更新带回给Jason Mathers来完成的，让他知道Remy的准备工作正在进行中。",al={"在哪里交付baited for success","baited for success任务终点"}},{q="鱼人对Mathers构成了什么威胁？",a="鱼人扰乱了当地的捕鱼水域，使得像Mathers这样的渔夫在鱼人数量减少之前，无法正常谋生或谋生存在危险。",al={"为什么在这里消灭鱼人","mathers的鱼人问题"}},{q="Mathers在收到Remy的消息后有什么打算？",a="一旦消息送达，Mathers决定在当天晚些时候去找Remy领取毒饵，并接受关于如何安全部署它的指导。",al={"交付信息后会发生什么","mathers拿到了诱饵吗"}}},fp="18,253,21.332.0,19.287.1,40.131.0,38.184.0,37.189.0,29.127.0,43.148.0,49.152.0"}
P.entries["quest:99134"] = {n="Discipline",s="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",h="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",kw={"黑暗女王","死亡卫士","纪律","执行官塞加德","被遗忘者","激励棒","提瑞斯法林地","亡灵"},ang={["faction:Horde"]="被遗忘者指挥官们冷酷的手段展现了部落北部领地在生活和治理上那严苛且不留情面的现实。",["race:Undead"]="对于被遗忘者来说，军事纪律关乎种族的生存。屈服于冷漠的哨兵会危及整个提瑞斯法林地。"},sec={{t="在亡灵状态下强制执行秩序",b="死亡卫士构成了被遗忘者在洛丹伦的军事脊梁，但脱离了巫妖王的铁腕意志也带来了一些并发症：冷漠、疲劳和玩忽职守。像执行官塞加德这样的监工对于松懈的纪律几乎没有耐心，尤其是考虑到血色十字军和天灾军团的威胁正在提瑞斯法林地的边界徘徊。为了让部队保持敏锐，军官们依靠钝器和强硬的监督来维持军事战备状态。"},{t="执行官的账簿",b="执行官塞加德故意聘请独立的行动者，而不是驻军内部的士兵来执行惩罚。利用执行官的“激励棒”，外来者提醒玩忽职守的死亡卫士，在为黑暗女王服务时，生存需要绝对的警惕。那些玩忽职守的人很快就会明白，亡灵的身份并不能让他们逃脱惩罚。"}},faq={{q="谁发布了“纪律”任务？",a="“纪律”任务由执行官塞加德发布，他是一位驻扎在提瑞斯法林地的严苛的被遗忘者军官，负责监督区域防御，并要求部队绝对服从。",al={"纪律任务发布者","谁开启纪律任务","执行官塞加德任务"}},{q="执行官塞加德为什么要惩罚死亡卫士？",a="塞加德认为他指挥下的死亡卫士能力不足且缺乏应有的动力。因为自满威胁着被遗忘者在提瑞斯法林地的生存，他实施严厉的纪律，以震慑哨兵，使其保持警觉。",al={"为什么要惩罚死亡卫士","为什么要激励死亡卫士","塞加德惩罚死亡卫士的原因"}},{q="为什么塞加德使用冒险者而不是其他士兵？",a="塞加德指出，作为一个尚未成为死亡卫士一员的外来者，你还没有机会让他失望。",al={"为什么要我执行纪律","塞加德为什么使用外来者"}},{q="什么是执行官的“激励棒”？",a="执行官的“激励棒”是执行官塞加德提供的一种惩戒工具。它被用来对驻扎在提瑞斯法林地各处的懒散死亡卫士进行痛苦的训诫。",al={"执行官的激励棒","什么是执行官的激励棒"}},{q="如果你拒绝塞加德的命令会发生什么？",a="塞加德警告说，犹豫或拒绝会导致你的名字被记入他的账簿，标记你为下一个被他人惩戒的目标。",al={"塞加德的威胁","账簿威胁"}},{q="被遗忘者如何看待痛苦？",a="塞加德认为痛苦是他死后仅存的少数乐趣之一。他对于惩罚的热衷反映了他严酷的性格。",al={"亡灵是否会感到痛苦","被遗忘者痛苦背景"}}},fx={ae86ed1b={q="你要惩戒的亡灵卫兵是谁？",a="亡灵卫兵是被遗忘者的常备军与哨兵，负责保卫提瑞斯法林地，并执行黑暗女王的统治。执行官塞加德认为驻扎在布瑞尔及其外围哨所的卫兵懒惰无能，要求用体罚提醒他们肩负的誓言：保护被遗忘者的土地。",al={"亡灵卫兵是谁","惩戒亡灵卫兵的对象","我要惩戒谁"}}},fp="10,234,26.467.0,21.367.0,31.174.0,54.215.0,61.123.0,33.183.0,42.162.0,30.139.0"}
P.entries["quest:99141"] = {n="Patience",s="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所执行的那种严苛、不妥协的纪律。",h="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所...",kw={"布瑞尔","黑暗女王","亡灵卫兵","迪林格尔","戈多","克里斯托夫","耐心","静水池","提瑞斯法林地","塞加德"},ang={["faction:Horde"]="这项任务让到访的部落盟友得以一窥希尔瓦娜斯·风行者的军官们在整个提瑞斯法执行的那种冷酷、高度纪律化的指挥结构。",["race:Undead"]="对于新解放的被遗忘者来说，执行塞加德的命令强化了洛丹伦残酷的生存现实：对黑暗女王的绝对忠诚，以及对失败的零容忍。"},sec={{t="执行黑暗女王的意志",b="执行官塞加德负责指挥提瑞斯法林地的当地防务，他不容许任何疏忽。在塞加德看来，效忠希尔瓦娜斯女士必须时刻保持绝对的效率。当常规战场派遣报告没能按时送达他的哨岗时，他将其视为一次不可接受的失职，而非简单的延迟。他并没有离开岗位去亲自调查，而是派新来的被遗忘者特工去纠正那些玩忽职守的下属，确保边境依然稳固。"},{t="林地的哨兵",b="这些派遣任务涉及到驻守在布瑞尔周围关键观察点的哨兵。亡灵卫兵迪林格尔负责监视西边的墓地，那里经常有不法亡灵和天灾军团的残党在活动。在东边，亡灵卫兵克里斯托夫负责看守一处哨所，守卫着通往洛丹伦王城和东部道路的入口。而在他们之中最不寻常的要数戈多，一个在静水池附近游荡的庞大缝合怪，其单纯的思维让他去进行军事记录显得非常荒谬。"}},faq={{q="执行官塞加德是谁？",a="执行官塞加德是一名高级被遗忘者军官，负责维持提瑞斯法林地布瑞尔周边的秩序和防御。他直接向效忠于希尔瓦娜斯女士的指挥层负责，并要求他所监管的所有部队必须完美地执行任务。",al={"塞加德","谁是塞加德","执行官塞加德职责"}},{q="为什么塞加德要派冒险者去收集报告？",a="几名战场哨兵没能按时提交预定的报告。塞加德没有耐心等待，也不愿离开他的中央哨岗，于是他雇佣新获得自由的被遗忘者去乡野间找回那些逾期的派遣报告。",al={"为什么要完成耐心任务","为什么要收集报告"}},{q="戈多是谁，为什么他会有报告？",a="戈多是一个在静水池西边游荡的缝合怪。塞加德像对待其他战场哨兵一样期待从他那里得到状态报告，尽管在收到报告后，这位执行官很快意识到期待一个缝合怪写出书面情报是一个尴尬的判断失误。",al={"戈多","为什么缝合怪会有报告","谁是戈多"}},{q="亡灵卫兵迪林格尔在哪里？",a="亡灵卫兵迪林格尔驻扎在布瑞尔西侧，守卫着当地的墓地，监视徘徊的天灾活动和新复活的尸体。",al={"迪林格尔位置","找到迪林格尔","迪林格尔在哪里"}},{q="亡灵卫兵克里斯托夫驻扎在哪里？",a="亡灵卫兵克里斯托夫驻扎在布瑞尔以东道路旁的哨所，守卫入口以防入侵者，并监视路上的交通。",al={"克里斯托夫位置","找到克里斯托夫","克里斯托夫在哪里"}},{q="当戈多的报告被上交后会发生什么？",a="执行官塞加德承认期待一个缝合怪写出一份连贯的书面报告是一个愚蠢的错误。他默默接受了结果，并要求你将这次尴尬的疏忽仅限于你和他之间知道。",al={"戈多报告的结果","戈多书写"}}},fx={e0ff4089={q="执行官塞加德为什么要收集这些报告？",a="执行官塞加德肩负着维护黑暗女王意志、严格监督布瑞尔防务的职责。哨兵和斥候若未能按时提交情况报告，就会损害被遗忘者的战备，还可能惹得希尔瓦娜斯不悦。塞加德要求他们迅速照办，以维持铁一般的纪律。",al={"塞加德的动机","塞加德为什么要报告","耐心任务为什么"}},cb8b3e87={q="亡灵卫兵迪林格尔的报告有什么用？",a="迪林格尔的报告说明了镇子以西布瑞尔墓地周边当前的安全状况。亡灵卫兵迪林格尔驻扎在墓地附近，负责留意威胁和骚乱；他应当向执行官塞加德通报当地动乱和外围防线的稳定情况。",al={"迪林格尔的报告","迪林格尔的报告是什么","迪林格尔报告的用途"}},["744f946d"]={q="亡灵卫兵克里斯托夫的报告有什么用？",a="克里斯托夫的报告详细说明了东部驿站周边的巡逻活动和道路状况。亡灵卫兵克里斯托夫负责监视穿过提瑞斯法林地向东延伸的道路，他提交的报告为执行官塞加德提供有关道路通行和逼近的危险的重要情报。",al={"克里斯托夫的报告","克里斯托夫的报告是什么","克里斯托夫报告的用途"}},["79b1ee7a"]={q="戈尔多的报告有什么用？",a="戈尔多的报告本该汇报西边静水池周边的情况，那只憎恶正在那里巡逻。执行官塞加德期待收到书面侦察报告，可这个头脑简单的庞然大物很难理解军情报告的概念。",al={"戈尔多的报告","戈尔多的报告是什么","戈尔多报告的用途"}}},fp="8,361,30.486.0,23.490.0,23.260.0,54.244.0,43.288.1,38.153.0,38.157.0,46.224.1"}
P.entries["quest:99142"] = {n="Tomb Weed",s="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",h="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",kw={"巴尼尔农场","厄运草","戈多","药剂师助理霍兰德","皇家药剂师学会","提瑞斯法林地","tomb weed"},ang={["profession:Herbalism"]="Tomb Weed展示了人工炼金操纵如何能从根本上改变像厄运草这样枯萎草药的特性和行为。",["race:Undead"]="药剂师助理霍兰德的研究表明，被遗忘者药剂师们一直致力于将提瑞斯法枯萎的植物群重塑为定制的炼金工具。"},sec={{t="霍兰德的培育",b="药剂师助理霍兰德并不满足于仅仅为皇家药剂师学会采集原生草药；他有着自己的宏大抱负。通过收集厄运草并对其进行细微的炼金改造，他将这些草药重新种植在巴尼尔农场的土壤中，培育出了一种他命名为Tomb Weed的进化样本。霍兰德将这种混合植物视为他工作的核心，也是他个人命运的前兆。"},{t="意外的吸引力",b="虽然霍兰德预料到了炼金效力，但将Tomb Weed移植到巴尼尔农场产生了意想不到的副作用。在枯萎的田野中游荡的天灾军团残余对这种茁壮成长的植物表现出了不可思议的普遍吸引力。霍兰德依靠路过的旅行者来突破这些入侵的亡灵并收获成熟的作物，以便他能继续他的实验。"}},faq={{q="什么是Tomb Weed？",a="Tomb Weed是由药剂师助理霍兰德培育的一种经炼金改良的厄运草变种。他采集原生的厄运草，用化学试剂对其进行改造，并将其种植在巴尼尔农场枯萎的土壤中。",al={"什么是tomb weed","tomb weed背景故事","tomb weed植物"}},{q="药剂师助理霍兰德是谁？",a="霍兰德是皇家药剂师学会的一员，在提瑞斯法林地工作。他雄心勃勃，经常被像憎恶戈多这样的助手弄得心烦意乱，霍兰德进行私人园艺和炼金实验，旨在提升自己的地位。",al={"霍兰德是谁","药剂师助理霍兰德","药剂师霍兰德"}},{q="Tomb Weed种植在哪里？",a="霍兰德将他改良的作物种植在巴尼尔农场，这是一处位于提瑞斯法林地东部的废弃庄园，现已陷入枯萎和荒废之中。",al={"去哪里找tomb weed","tomb weed位置","巴尼尔农场的杂草"}},{q="为什么天灾军团会被Tomb Weed吸引？",a="霍兰德观察到，游荡在巴尼尔农场中毫无意识的天灾军团似乎本能地被这种改良植物所吸引，尽管他不知道原因；他只是觉得这很奇怪。",al={"为什么天灾军团想要tomb weed","天灾军团被tomb weed吸引","天灾军团的反应"}},{q="Tomb Weed与普通厄运草有何不同？",a="厄运草是一种在布瑞尔墓地北部的乱葬岗附近自然生长的植物。Tomb Weed是在霍兰德的指导下，将厄运草进行人工炼金改造并选择性地重新种植在农场土壤中而产生的。",al={"厄运草与tomb weed的区别","厄运草和tomb weed的差异"}},{q="霍兰德提到的戈多是谁？",a="戈多是被遗忘者制造的一只游荡的憎恶，在提瑞斯法林地的道路上徘徊，通常被霍兰德分配一些对他迟钝的大脑来说很困难的简单任务。",al={"戈多是谁","戈多行踪","戈多提瑞斯法"}}},fp="9,263,21.442.0,21.406.0,18.223.0,33.257.0,25.149.0,43.180.0,48.250.0,34.179.0"}
P.entries["quest:99143"] = {n="Bottles and Baubles",s="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",h="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",kw={"鱼饵","bottles and baubles","钓鱼","假饵","鱼人","鱼人营地","闪亮垃圾"},sec={{t="鱼类逻辑与海岸拾荒",b="Bottles and Baubles 从一个非常奇特的海洋生物学理论开始：既然鱼人是类鱼生物，它们的思维方式一定和深海中游动的鱼类一样。基于这种逻辑，一位古怪的垂钓者断言，任何能吸引鱼人目光的好奇之物，也一定能引诱饥饿的鱼儿上钩。冒险者们受命前往附近的鱼人营地，搜刮它们的囤积物，收集闪闪发光的废弃垃圾，以验证这一假说。"},{t="闪亮的小玩意作为鱼饵",b="沿海水道和河岸上的鱼人是臭名昭著的拾荒者，它们在小屋周围杂乱地堆积着明亮的石头、贝壳、抛光的玻璃碎片和金属残渣。翻找这些泥泞的堆积物，可以找到各种各样闪闪发光的废品，机会主义的渔夫可以将它们制成简陋的假饵和闪光片。一旦收回并上交，这些奇怪的杂物足以让冒险者获得一套入门钓鱼用品。"}},faq={{q="为什么要从鱼人那里收集垃圾？",a="任务发布者认为，既然鱼人长得像鱼，它们的思维也一定和鱼一样。基于“吸引鱼人的东西也能吸引水底的鱼”这一理论，冒险者们被派往鱼人营地搜刮饰品和闪亮的废品，将其改造成鱼饵。",al={"为什么要收集垃圾","bottles and baubles有什么用","鱼人闪亮垃圾"}},{q="哪里可以找到闪亮的垃圾？",a="闪亮的垃圾散落在附近的鱼人营地周围。鱼人是臭名昭著的拾荒者，它们会在海岸线和水道沿岸囤积闪闪发光的碎片、废弃的饰品和玻璃，这些可以直接从它们的地盘上获取。",al={"在哪里找到垃圾","鱼人营地位置","如何获得闪亮垃圾"}},{q="谁发布了这个任务，他们想要什么？",a="该任务由一位当地的垂钓者委托，他正想储备一些假饵和鱼饵。虽然他对鱼人心理学的理论有些古怪，但他会用多余的垂钓装备奖励热心的拾荒者，以鼓励新手们学习这门手艺。",al={"谁发布了bottles and baubles","任务发布者是谁","任务交还"}},{q="鱼人真的像鱼一样思考吗？",a="尽管任务发布者有这种推理，但鱼人是两栖的部落类人生物，而不是简单的无脑鱼类。然而，就像许多生物和捕食者一样，它们天生会被闪闪发光的物品、抛光的贝壳和明亮的小玩意所吸引，从而形成了恰好包含闪亮材料的囤积堆。",al={"鱼人像鱼一样思考吗","鱼人的智力","鱼人真的是鱼吗"}},{q="鱼人的垃圾将如何被用作鱼饵？",a="收集到的垃圾包括反光玻璃、金属碎片和抛光的零碎物件。这位垂钓者打算将这些反光碎片制成假饵和临时鱼饵，希望它们的光泽能模仿小鱼，或者引起觅食鱼类的好奇。",al={"闪亮垃圾的用途","闪亮垃圾是鱼饵吗","鱼人垃圾能当鱼饵吗"}},{q="任务发布者提供什么奖励？",a="在带回足够多合适的闪亮碎片后，任务发布者会交出他以前的个人垂钓用品。这些基础工具和补给旨在帮助有抱负的渔夫们站稳脚跟，并在水边试手。",al={"bottles and baubles的奖励是什么","你能得到什么","钓鱼用品奖励"}}},fp="19,280,35.496.0,24.470.0,45.303.0,30.252.0,42.241.0,36.299.0,41.262.0,43.233.0"}
P.entries["quest:99144"] = {n="Seeking Refuge",s="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's Outpost。他的挣扎凸显了一个非传统教派的出现，该教派尽管受到了当地狂热分子的严重偏见，却依然虔诚于圣光。将他逃脱的消息安全传回布瑞尔，为这个初生的圣所确立了至关重要的联系。",h="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's...",kw={"班达里安堡","bareth dawnstone","布瑞尔","crusader's outpost","十字军","圣光","seeking refuge","shari stilwell","索利丹农场","提瑞斯法林地"},ang={["class:Paladin"]="圣骑士们可以留意一下Crusader's Outpost的狂热分子与Bareth Dawnstone之间的对比：前者怀着仇恨运用圣光，而后者追求仁慈与保护。",["class:Priest"]="牧师们会发现班达里安堡的哲学非常迷人，因为尽管周围对亡灵施法者存在偏见，其成员仍在追求纯粹的冥想和圣光的指引。",["faction:Horde"]="确保班达里安堡和布瑞尔之间的信使安全，可以确保新兴的中立或盟友教派在提瑞斯法林地站稳脚跟，以对抗敌对的十字军。",["race:Undead"]="依然崇敬圣光的被遗忘者既面临来自活人狂热分子的敌意，也面临来自怀疑论同胞的敌意，这使得班达里安堡不断壮大的兄弟会成为了一个罕见的圣所。"},sec={{t="危险的旅程",b="Seeking Refuge讲述了班达里安堡隐秘修道院派遣的信使Bareth Dawnstone的惊险旅程。在前往布瑞尔与Shari Stilwell商议的途中，Bareth在Crusader's Outpost被狂热的战士拦截并俘虏。尽管他的亡灵身份招致了仇恨，但Bareth对圣光的虔诚始终如一，他唯一的渴望就是逃离折磨者，并确保他的信息送达目的地。"},{t="复仇与虔诚",b="Bareth的被囚突显了笼罩在提瑞斯法林地的痛苦意识形态分歧。Crusader's Outpost的狂热分子通过复仇的愤怒和教条式的正义来引导圣光，将Bareth的存在视为一种冒犯。相比之下，Dawnstone将圣光视为保护和内在纯洁的源泉，他感叹捕获者的残忍扭曲了他所珍视的神圣教义。"},{t="山崖上的圣所",b="逃脱后，Bareth在布瑞尔向Shari Stilwell确认了安全。Stilwell透露，他们的修道会仍在索利丹农场西北部的山崖上扎根。失去像Dawnstone这样有前途的修行者，对他们年轻的团体来说将是沉重的打击，该团体向任何寻求真正精神指引的旅行者敞开大门。"}},faq={{q="Bareth Dawnstone是谁？",a="Bareth Dawnstone是班达里安堡的一位圣光信徒。在前往布瑞尔传递信息的途中，他遭到了厌恶他这一类的狂热十字军的伏击并被监禁。尽管他身为亡灵，但他仍冥想圣光，并努力利用圣光进行保护。",al={"bareth dawnstone是谁","bareth dawnstone背景故事","dawnstone"}},{q="谁俘虏了Bareth Dawnstone，为什么？",a="驻扎在Crusader's Outpost的狂热分子在从班达里安堡通往布瑞尔的路上伏击了Bareth Dawnstone。他感叹道，他的捕获者内心怀着强烈的仇恨运用圣光，扭曲了他所冥想的仁慈美德，并迫害那些他们视为憎恶之物的人。",al={"谁俘虏了bareth dawnstone","crusader's outpost捕获者","他为何被俘"}},{q="Shari Stilwell是谁？",a="Shari Stilwell是驻扎在被遗忘者城镇布瑞尔的修道会代表。她接待旅行者，并与从班达里安堡派遣的使者进行协调，欢迎任何寻求圣光指引的人。",al={"shari stilwell是谁","stilwell 布瑞尔","shari 布瑞尔"}},{q="什么是班达里安堡？",a="班达里安堡是一座隐秘的修道院，位于提瑞斯法林地的索利丹农场西北部的山崖上。它是一个蓬勃发展的宗教教派的圣所和训练场，致力于对圣光的纯粹冥想和研究。",al={"什么是班达里安堡","班达里安堡在哪里","索利丹西北部的修道院"}},{q="为什么Bareth的捕获者会对他的种族有意见？",a="Bareth Dawnstone提到了“我仅存的血液”，并承认了针对他这一类的偏见，这表明他是一位圣光的亡灵修行者。提瑞斯法的狂热十字军鄙视所有亡灵，拒绝相信他们的意图或虔诚可能是纯洁的。",al={"为什么他们仇恨他这类人","亡灵使用圣光","bareth我仅存的血液"}},{q="班达里安堡驻扎的是什么样的教派？",a="驻扎在班达里安堡的教派是一个年轻、不断发展的修道兄弟会，正在提瑞斯法的山崖上扎根。与附近充满仇恨的十字军不同，他们宣扬和平的冥想和保护，并向任何寻求圣光真正指引的人敞开大门。",al={"班达里安堡的教派是什么","班达里安堡僧侣","班达里安信仰"}}},fp="14,381,18.460.0,25.409.0,23.384.0,24.289.0,39.284.0,22.241.0,23.253.0,49.282.0,46.265.0"}
P.entries["quest:99152"] = {n="As Above, So Below",s="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",h="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",kw={"as above so below","班达里安堡","发光的骸骨","破击者希尔达","复生魔法","天灾军团","影谷","玷污者"},ang={["class:Mage"]="法师们会注意到附着在发光骸骨上的残留复生魔法，这暗示了隐藏在城镇下方的特定死灵技术。",["class:Paladin"]="圣骑士将任何未被察觉的天灾势力视为迫在眉睫的危险，因此调查影谷下方的复生魔法是一项紧迫的职责。",["class:Priest"]="受过反亡灵训练的牧师们对于在定居点下方滋生的黑暗复生艺术感到十分忧虑。"},sec={{t="隐秘的威胁",b="在班达里安堡，破击者希尔达负责监督防御者们针对周边险境进行的严格训练。尽管地表的目光都集中在西南方向动荡不安的影谷定居点——那里有一个被称为“玷污者”的敌对势力频繁制造事端——但在视线之外，更大的危险已经扎根。在城镇下方的阴暗地窖中，一股未被察觉的天灾力量正在积蓄，如果任其发展，随时可能对堡垒发动突袭。"},{t="地窖中的魔法",b="希尔达不愿让毫无经验的学员盲目闯入地下墓穴，因此派遣经验丰富的冒险者直接进入影谷下方的地窖。这不仅仅是一次清剿行动，其首要目标是收集情报：回收那些仍带有残留复生魔法的骸骨残骸。研究这些微弱发光的骨头，能让防御者们有机会破解这种黑暗死灵术是如何在眼皮底下悄然运作的。"}},faq={{q="什么是“As Above, So Below”？",a="“As Above, So Below”是破击者希尔达委派的一项任务，旨在调查潜伏在影谷定居点下方的天灾军团势力。在班达里安堡的学员们接受操练的同时，一位冒险者被派往城镇下方收集复生的骸骨样本。",al={"什么是 as above so below","as above so below 任务"}},{q="是谁发布了“As Above, So Below”任务？",a="破击者希尔达是班达里安堡一位严苛的教官，负责训练新兵。她坚韧且不妥协，对指挥下的任何人都有严格的要求，她宁愿新兵躺着被抬回来，也不愿他们空手而归。",al={"谁发布了 as above so below","谁是破击者希尔达","任务发布者希尔达"}},{q="影谷位于哪里？",a="影谷位于班达里安堡的西南方。虽然地表的麻烦主要源于一个名为“玷污者”的团体，但其地下的地窖中却隐藏着更阴险的亡灵侵害。",al={"影谷在哪里","影谷位置"}},{q="潜伏在影谷下方的是什么威胁？",a="影谷下方的地窖已被复生的亡灵所占据。如果放任不管，这股隐藏的天灾势力随时可能引发一场针对附近班达里安堡的全面暴乱。",al={"影谷下方的地窖是什么","影谷地窖中的天灾军团","影谷下方的威胁"}},{q="希尔达为什么需要微弱发光的骸骨？",a="希尔达需要那些仍带有复生魔法残留气息的骸骨。通过研究这些发光的残骸，防御者们希望能够理解死灵法师是如何在未被发现的情况下策划这场暴乱的。",al={"为什么要收集发光的骸骨","微弱发光骸骨的用途","复生魔法骸骨"}},{q="影谷的“玷污者”是谁？",a="“玷污者”是一个活跃在影谷地表的敌对势力。尽管他们对该地区构成了现实威胁，但希尔达认为城镇下方隐藏的天灾巢穴才是更加危险的敌人。",al={"谁是玷污者","影谷的玷污者"}}},fp="18,295,17.496.0,20.498.1,27.266.0,39.230.0,28.201.0,37.200.0,42.225.0,36.219.0"}
P.entries["quest:99153"] = {n="The One That Got Away",s="The One That Got Away 是一个由 Ephram Barbaro 发布的任务，旨在追踪一名从纳克萨玛斯残骸附近的冲突中逃脱的邪教徒。这名逃犯带着一块活跃的聚焦水晶碎片逃进了影谷下方，该水晶碎片可能会强化亡灵或使其复活。",h="The One That Got Away 是一个由 Ephram Barbaro...",kw={"水晶碎片","邪教徒","ephram barbaro","聚焦水晶","纳克萨玛斯","影谷","the one that got away"},ang={["class:Paladin"]="发誓要清除死灵威胁的圣骑士会意识到任由天灾军团聚焦水晶保持活跃的危险性，特别是那些能够复活或增强地下亡灵的碎片。",["class:Priest"]="熟悉对抗黑暗魔法的牧师们明白，如果不及时回收和净化，亵渎的圣物可能会腐蚀周围的区域。"},sec={{t="影中的逃犯",b="在纳克萨玛斯战役的残骸周围与邪教徒发生冲突后，消息很快在队伍中传开了。Ephram Barbaro 在得知一名落单的邪教徒带着一块活跃的天灾军团聚焦水晶碎片潜逃出包围圈后，开始寻找有能力的冒险者。"},{t="影谷之下的威胁",b="情报显示这名逃跑的邪教徒逃进了影谷下方的地下通道。这块碎片仍然蕴含着黑暗的死灵能量，据推测它要么正在复活亡灵，要么在增强潜伏在地下深处的敌对势力。Barbaro 指派冒险者去追踪并收回这块隐藏的水晶，以免其力量引发更大的灾难。"}},faq={{q="谁发布了任务 The One That Got Away？",a="该任务由 Ephram Barbaro 发布，他在听闻你之前处理纳克萨玛斯战役残骸附近邪教徒的事迹后联系了你。",al={"谁发布了 the one that got away","谁开启了这个任务","the one that got away 任务发布者"}},{q="什么是聚焦水晶碎片？",a="这是由一名逃脱的邪教徒带走的天灾军团聚焦水晶的残留碎片。Ephram Barbaro 指出它仍然具有力量，并且正在影谷下方复活亡灵或增强现有亡灵的力量。",al={"什么是水晶碎片","水晶有什么用","为什么水晶很危险"}},{q="水晶碎片在哪里？",a="根据 Ephram Barbaro 的情报，那名逃亡的邪教徒带着圣物逃到了影谷下方，并将其藏在了地下的某个地方，其力量正不断从中渗出。",al={"水晶藏在哪里","影谷水晶位置","哪里寻找水晶碎片"}},{q="谁是“The One That Got Away”（漏网之鱼）？",a="这个称号指的是一名在纳克萨玛斯战役残骸的冲突后成功溜走的邪教徒，他们带走了一块活跃的聚焦水晶碎片。",al={"谁带着水晶逃跑了","持有水晶的邪教徒","the one that got away 含义"}},{q="当你把水晶交给 Ephram Barbaro 时会发生什么？",a="在归还回收的水晶碎片后，Ephram Barbaro 会称赞你的速度，并表示是时候进行处理这一情况时他最喜欢的部分了。",al={"归还水晶后发生什么","交付 the one that got away","ephram barbaro 最喜欢的部分"}},{q="Ephram Barbaro 是如何认识你的？",a="Ephram 提到消息在队伍中传得很快，特别提到了之前在纳克萨玛斯战役残骸周围对付邪教徒的工作。",al={"纳克萨玛斯战役残骸邪教徒","ephram 是怎么认识你的","the one that got away 前置条件"}}},fp="21,272,25.290.0,29.365.0,42.165.0,38.217.0,38.175.0,31.184.0,59.167.0,39.172.0"}
P.entries["quest:99156"] = {n="Rear Guard Patrol",s="Rear Guard Patrol 是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",h="Rear Guard Patrol 是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",kw={"缝合怪","亡灵壁垒","亡灵卫兵林奈","rear guard patrol","撕裂者","提瑞斯法林地","毒蛛峡谷"},ang={["faction:Horde"]="确保提瑞斯法东部边境的安全，可以保证供给亡灵壁垒和幽暗城的补给线不会受到流浪恐怖生物的威胁。",["race:Undead"]="被遗忘者无法承受两线作战的代价；任何在他们防线后方游荡的天灾构装体，对其王国而言都是一种生存威胁。"},sec={{t="边境的缺口",b="亡灵壁垒是提瑞斯法林地与西瘟疫之地恐怖势力之间唯一的坚固屏障。被遗忘者军队的战略完全建立在严格的单线战争基础上。如果这些毫无理智的亡灵溜到了防线后方，供给前线的补给线可能会瞬间被切断。虽然偶尔会有流浪的幽灵或食尸鬼绕过路障，但有报告称一只缝合怪正在林地中游荡，这标志着防御工作的严重失败。"},{t="撕裂者的威胁",b="那只名为撕裂者的游荡怪物被发现正笨重地在毒蛛峡谷附近移动，位于亡灵壁垒的前沿堡垒后方。缝合怪是巨大的杀戮机器，由尸体和黑暗死灵法术缝合而成。它们不可能在毫无察觉的情况下穿过严密防守的关隘，这让亡灵卫兵林奈对于这个生物如何穿过防御圈感到非常不安。林奈要求取得撕裂者的心脏，以此作为其被彻底消灭的终极证明。"}},faq={{q="谁提供了 Rear Guard Patrol 这个任务？",a="巡逻指令由亡灵卫兵林奈发布，她是提瑞斯法林地的一名被遗忘者亡灵卫兵，直接向执行官塞加德汇报。",al={"谁发布 rear guard patrol","rear guard patrol 任务发布者","谁发布了这个任务"}},{q="撕裂者是什么？",a="撕裂者是一只流窜的缝合怪，被发现在毒蛛峡谷附近的东部林地游荡，位于前沿防线后方。",al={"谁是撕裂者","撕裂者是什么","撕裂者背景"}},{q="为什么缝合怪出现在毒蛛峡谷附近如此令人担忧？",a="缝合怪是巨大的构装体，制造它们需要黑暗死灵法术和繁重的劳作。在不知不觉中穿过戒备森严的亡灵壁垒理应是不可能的，这意味着在被遗忘者的防线后方存在一个令人震惊的缺口，或是一条未被发现的通道。",al={"为什么撕裂者是个大麻烦","为什么缝合怪在这里很危险","亡灵壁垒缺口"}},{q="这头野兽通常在哪里出没？",a="目击报告显示，撕裂者一直在提瑞斯法林地东部的树林和空地中游荡，就在毒蛛峡谷附近。",al={"撕裂者在哪里","撕裂者位置","去哪里找缝合怪"}},{q="完成巡逻需要什么证明？",a="亡灵卫兵林奈需要撕裂者的心脏来验证这只巨大的怪物已被永久消灭。",al={"我该给林奈带什么","任务提交物品","撕裂者死亡证明"}},{q="谁负责监管亡灵壁垒的防御？",a="任务中没有提到亡灵壁垒的指挥官。亡灵卫兵林奈听命于她在布瑞尔的上级执行官塞加德，后者会接收她因成功抵御天灾军团而获得的嘉奖。",al={"谁负责亡灵壁垒","林奈的上级","执行官塞加德"}}},fp="17,285,24.457.0,21.441.1,39.121.0,16.124.0,53.248.0,33.117.0,44.112.0,40.189.0"}
P.entries["quest:99158"] = {n="Dawn in the Mountains",s="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",h="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",kw={"银色黎明","dawn in the mountains","加文神父","圣烛","雾松避难所","牧师","避难所"},ang={["class:Priest"]="加文神父体现了牧师更温和、更具修复力的道路，他选择关怀旅人和包扎伤口，而不是在银色黎明的前线挥舞武器。",["faction:Alliance"]="向雾松避难所这样的银色黎明庇护所提供物资，有助于在危险且充满争议的山地地形中开展中立的人道主义工作。",["faction:Horde"]="银色黎明接受援助并提供避难所，不论其立场如何，这使得加文神父的这类前哨站成为荒野中罕见的安全港湾。"},sec={{t="群峰中的庇护所",b="尽管许多银色黎明的成员拿起武器去清除艾泽拉斯的邪恶恐怖，但有些人选择了圣光更温和的召唤。加文神父是一位居住在崎岖山野中的牧师，他远离了刀剑，全心全意地致力于治愈伤痛和照料疲惫之人。他利用一处废弃的建筑，将其改造成了雾松避难所，为面对高海拔山口危险的旅人们提供了一个安全的驻足点。"},{t="为了圣光的蜡烛",b="在山中维护一个与世隔绝的避难所需要持续的维护和务实的奉献。为了维持他的神职工作并保持灯火和祭坛常亮，加文神父依赖远方盟友的慈善。一箱圣烛的运抵确保了这座避难所能在无情的荒野中继续作为光明、温暖和希望的灯塔。"}},faq={{q="谁是加文神父？",a="加文神父是银色黎明的一名牧师，驻扎在群山之中。与许多圣职人员拿起武器对抗邪恶不同，加文主要致力于治愈伤痛、慰藉旅人，并在雾松避难所提供庇护。",al={"谁是加文神父","加文神父的背景故事","雾松避难所的牧师是谁"}},{q="什么是雾松避难所？",a="雾松避难所是由加文神父建立的供山中旅人休憩的站点。他翻新了荒野中的一栋旧建筑，创造了一个宁静的庇护所，流浪者可以在此恢复体力、休息并接受治疗。",al={"什么是雾松避难所","雾松避难所在哪里","雾松避难所的背景故事"}},{q="什么是银色黎明？",a="银色黎明是一个致力于在艾泽拉斯全境搜寻并摧毁邪恶与非自然威胁的圣职组织，同时也为那些在困苦之地的挣扎求生者提供援助与慰藉。",al={"什么是银色黎明","银色黎明的宗旨","谁是银色黎明"}},{q="为什么加文神父需要一箱圣烛？",a="这箱圣烛旨在补充加文神父在雾松避难所的物资。在圣职事奉和偏远的避难所中，这些祝圣过的蜡烛对于宗教仪式、祈祷以及为疲惫的旅人照亮避难所至关重要。",al={"为什么要蜡烛","圣烛的用途","运送一箱圣烛"}},{q="加文神父会像其他银色黎明成员一样拿起武器吗？",a="加文神父更倾向于治愈和庇护旅人，而不是拿起武器。尽管银色黎明以对抗黑暗的武装十字军闻名，但加文通过同情心、好客和精神关怀来服务该组织。",al={"加文神父会战斗吗","加文神父是战士吗"}},{q="任务Dawn in the Mountains的目的是什么？",a="该任务要求前往山区的旅人将一箱圣烛直接运送给雾松避难所的加文神父，以支持他那简朴的山中庇护所。",al={"谁发布了这个任务","dawn in the mountains通向哪里"}}},fp="21,253,24.429.0,21.363.0,20.261.0,26.218.0,24.210.0,54.244.0,62.223.0,55.176.0"}
P.entries["quest:99159"] = {n="Finding Warmth",s="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",h="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",kw={"finding warmth","木柴","炉火","圣光","温暖","木材"},sec={{t="温暖的炉火",b="Finding Warmth是一项为了维持温暖炉火而进行的简单琐事。任务发布者随时保持炉火通明，以温暖任何路过的灵魂，但日益繁重的责任使他们无暇亲自收集燃料。通过代为收集木柴，旅人们确保了炉火能为任何寻求庇护与慰藉的人继续燃烧。"},{t="照看炉火",b="并非所有从周边收集的木料都能立即燃烧。运回后，太潮湿而无法点燃的木头会被放在一边晾干，而干燥的木材则会立即投入火中。主人对这及时的帮助感到满意，并迅速转向其他仍需关注的紧迫事务。"}},faq={{q="任务Finding Warmth的内容是什么？",a="Finding Warmth是一项当地任务，要求冒险者收集木柴以维持温暖的炉火。任务发布者通常会亲自照看火堆，但由于忙于其他紧迫的杂务，不得不寻求外界的帮助。",al={"finding warmth任务","什么是finding warmth","finding warmth木柴"}},{q="为什么需要这些木柴？",a="这些木柴用于维持一个开放的炉火，为路过的旅人和当地居民提供温暖与慰藉。收集木柴原本是一项普通的琐事，但由于主人忙于其他职责而耽搁了。",al={"为什么需要木材","木柴 finding warmth","炉火 木柴"}},{q="带来的湿木柴会怎么样？",a="收集到的一些原木在送达时可能太潮湿或太湿而无法立即燃烧。任务发布者会将潮湿的部分放在一边晾干，同时使用干燥的木材立即添火。",al={"finding warmth 湿木头","潮湿的木柴"}},{q="是什么样的人发布这个任务的？",a="虽然主人的具体身份未作详细说明，但他们那句“愿圣光指引你的任务”表明，这是一个根植于对圣光的信仰或敬畏的人，他们提供开放的炉火来温暖每一个灵魂。",al={"谁发布finding warmth","finding warmth 愿圣光指引你"}},{q="完成Finding Warmth后还有更多任务吗？",a="是的。在交付木柴后，主人提到手头还有其他任务，如果旅人愿意进一步帮忙，他们需要一双能干的手。",al={"finding warmth后的更多任务","finding warmth后续"}},{q="谁可以在这个炉火旁休息？",a="主人保持炉火燃烧，是为了给任何路过、可能需要从寒冷或疲惫的旅途中得到片刻休憩的人提供庇护、慰藉和温暖。",al={"炉火 开放 灵魂","开放的炉火 finding warmth"}}},fp="14,309,18.337.0,16.324.0,39.254.0,27.200.0,40.195.0,37.219.0,53.160.0,30.157.0"}
P.entries["quest:99160"] = {n="Rime's Wrath",s="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",h="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",kw={"元素","冰霜","冰元素","小型冰元素","安抚","rime's wrath"},ang={["class:Mage"]="冰霜法师研究冰霜魔法的原始塑形与召唤，这使得狂野的小型冰元素成为了一种引人入胜却又难以驾驭的元素力量展示。",["class:Shaman"]="萨满祭司致力于理解并与元素之灵沟通，但这些敌对的冰霜实体显然超出了和平安抚的范畴，只能通过武力予以平息。"},sec={{t="苦涩的显现",b="Rime's Wrath 涉及处理局部小型冰元素涌动的问题。这些由刺骨严寒构成的元素之灵已成为该地区切实存在的危险，必须迅速采取干预措施，以免它们的寒气进一步蔓延或伤害过往行人。这并非有组织的突袭，而是一种针对狂暴、敌对元素显现的遏制手段。"},{t="无法安抚",b="虽然理想的结果是安抚那些狂躁的霜冻之灵，但安抚它们所需的知识遥不可及。由于没有实际可行的和平手段，且这些元素之灵变得日益危险，剩下的唯一选择便是消灭它们，以保护周边地区。"}},faq={{q="什么是 Rime's Wrath？",a="Rime's Wrath 是一个要求消灭构成直接威胁的小型冰元素的任务。由于不知晓或无法使用和平手段来平息这些狂躁的元素之灵，直接动武成为了维持安全的唯一选择。",al={"什么是 rime's wrath","rime's wrath 任务","rime's wrath 概述"}},{q="为什么必须消灭小型冰元素？",a="这些小型冰元素变得过于不稳定且危险，不能放任不管。虽然和平安抚是首选，但缺乏让它们平静下来的知识，因此消灭它们成为了必要的手段。",al={"为什么要消灭冰元素","为什么要与它们战斗","不能安抚这些元素吗"}},{q="是谁要求消灭这些元素的？",a="该任务由一位关心控制局势的人发起，他本希望和平地安抚这些元素之灵。由于缺乏安抚它们所需的奥术或精神知识，他只能求助于冒险者来消除威胁。",al={"谁发布了 rime's wrath","谁想要消灭这些元素","任务发布者是谁"}},{q="这些元素可以和平解决吗？",a="任务发布者指出，安抚它们超出了他的认知范围。元素之灵有时可以被平衡或安抚，但若没有相关的专业知识，它们的攻击性使得除了战斗之外别无他法。",al={"冰元素可以被安抚吗","安抚冰元素","为什么不平息元素"}},{q="小型冰元素是什么样的生物？",a="小型冰元素是不稳定的冰霜元素显现。尽管被归类为小型元素之灵，但如果任其自由游荡，它们周围的严寒和攻击性仍会对旅行者和当地居民造成危险。",al={"什么是小型冰元素","冰元素的危险性","小型冰元素有多强"}},{q="处理这些元素的结果是什么？",a="在击败十个小型冰元素后，眼前的危险便被平息了。任务发布者感叹暴力是必要的手段，因为他也意识到放任不管风险实在太大。",al={"rime's wrath 之后会发生什么","rime's wrath 结局"}}},fp="12,226,22.367.0,16.307.0,21.246.0,53.217.0,47.232.0,53.212.0,48.224.0,51.192.0"}
P.entries["quest:99161"] = {n="Rime's Wrath",s="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒冬之灾。",h="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒...",kw={"avala","avala核心","元素生物","元素核心","rime's wrath","山崩","天气","冬季"},ang={["class:Paladin"]="圣骑士肩负着保护旅行者和平民免受突发灾难的职责。任务给予者在任务完成后祈求圣光的祝福，以感谢冒险者避免了不必要的死亡。",["class:Shaman"]="萨满祭司认识到像Avala这样不受约束的元素生物所构成的危险，其动荡的存在扭曲了当地的天气并撼动着岩石。平息这些躁动的生物对于恢复元素之间的和谐至关重要。"},sec={{t="山崩的余波",b="这些骚乱始于一次突如其来的山崩，山崩动摇了山口，为元素生物的活动打开了通道。在浮现出的众多生物中，有一个特殊的元素生物脱颖而出，以其巨大的体型和原始的力量凌驾于同类之上。警觉的任务给予者为它起了个非正式的绰号“Avala”。这个强大的实体不仅仅是一个令人望而生畏的存在，它还直接加剧了局部的天气动荡，并使周围的悬崖变得不稳定。它的存在对任何试图通过该地区的人来说都是一种直接的威胁，因为不稳定的地面和突如其来的严寒使正常的通行变得致命。"},{t="平息Avala",b="由于认识到Avala对地形的影响所带来的日益严重的危险，有人发出了号召，要求在更多的塌方造成伤亡之前消灭这头野兽。击杀该生物需要同时面对它的元素狂暴和它所制造的恶劣环境，最终还要取回它的核心作为其死亡的明确证据。随着Avala被击败，其生命之心被收回，剧烈的天气变化随之平息，这使周围的山口恢复了一定的安全，并保护未来的旅行者免受不必要的灾难。"}},faq={{q="什么是Rime's Wrath？",a="Rime's Wrath是一个任务，要求冒险者消灭Avala。这是一个在突然的山崩后显现的、巨大且危险的元素生物。通过猎杀该元素生物并回收其核心，冒险者终结了威胁着山口旅行者的反常天气干扰和反复发生的山崩。",al={"rimes wrath","什么是rimes wrath","rime's wrath任务"}},{q="Avala是谁，或者是什么？",a="Avala是一个在重大山崩后浮现的特别巨大的元素生物。Avala比它的元素同类体型更大，它主动在区域内引发突然的天气变化、严寒以及危险的二次地震。“Avala”这个名字是监视山口的观察者给它起的。",al={"什么是avala","avala是谁","avala元素生物"}},{q="为什么要摧毁Avala？",a="Avala持续存在导致不可预知的天气紊乱和小型山崩，使周围的山坡变得不稳定。如果不加制止，这个元素生物对冬季气候和地形的超自然影响将有引发进一步塌方的风险，并导致穿越山口的旅行者发生可避免的死亡。",al={"为什么要击杀avala","击杀avala的原因","为什么要摧毁avala"}},{q="完成Rime's Wrath需要什么证据？",a="冒险者必须在战斗中击败该生物后取回Avala的核心。将此元素核心交给任务给予者，证实该威胁已被彻底消除，区域气候可以恢复正常。",al={"avala的证明","掉落什么物品","avala核心证明"}},{q="Avala最初是如何出现的？",a="Avala是在一场扰乱该地区的最初山崩后出现的。它在塌方后的余波中与其他元素生物一同出现，由于其体型和元素力量，很快确立了自己是其中最突出、最危险的生物。",al={"avala从何而来","avala起源","avala如何生成"}},{q="谁提供了Rime's Wrath这个任务？",a="该任务由驻扎在危险山口附近的一名当地观察者提供，他密切监视着山崩和元素生物的出现。在任务完成后，这位观察者会祈求圣光的祝福，他试图通过招募有能力的勇士来消灭Avala，以防止不必要的死亡。",al={"谁给予rimes wrath任务","rimes wrath任务给予者"}},{q="Avala被击败后会发生什么？",a="一旦Avala被杀且其核心被带回，由该生物的存在所引发的剧烈天气变化和局部震动便会减弱。任务给予者会赐予圣光的祝福和奖励，并指出该地区对未来的旅行者来说已经变得更加安全。",al={"avala死后发生什么","rimes wrath完成","rimes wrath之后"}}},fp="12,362,25.601.0,14.552.0,21.328.0,21.309.0,36.333.0,46.235.0,27.265.0,34.315.0,37.275.0"}
P.entries["quest:99162"] = {n="Treacherous Cold",s="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",h="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",kw={"雪崩","丹莫罗","铁炉堡","登山者","步枪","山体滑坡","treacherous cold"},ang={["class:Hunter"]="登山者在冰冻荒野中依靠他们值得信赖的步枪，将名字刻在木质枪托上，这样他们的身份和功绩便永远不会被遗忘。",["faction:Alliance"]="回收阵亡登山者的装备，能确保铁炉堡给予那些为了守护高地而牺牲挚亲的家庭一份慰藉。",["race:Dwarf"]="丹莫罗的山峰是矮人的家园，但即便是老练的登山者也可能在高地山道上丧命于突发的雪崩和充满敌意的元素手中。"},sec={{t="群峰之险",b="丹莫罗崎岖的雪崖对旅行者和士兵来说始终是一种危险。即使是经验丰富的铁炉堡登山者也可能在突如其来的雪崩和坠落的冰层中措手不及，而新兵更是在毫无预警的寒冬袭击中丧命。"},{t="严酷的搜救",b="当山体滑坡掩埋了巡逻队，搜寻险峻地形便成了一场严酷的与时间赛跑。该地区加剧的元素活动使得彻底的救援行动困难重重，迫使侦察兵招募勇敢的漫步者，在雪堆中寻找失踪的登山者，并在大雪将其永远掩盖之前取回他们的铭文步枪。"},{t="刻字的枪托",b="每一位铁炉堡登山者都会将自己的名字刻在步枪的枪托上，作为在最严酷环境下的永久身份标识。通过从雪堆中找回这些武器，搜寻者能确保阵亡者得到确认，且他们受人尊崇的事迹能被铁炉堡的家人知晓。"}},faq={{q="什么是 Treacherous Cold？",a="Treacherous Cold 是一项任务，旨在搜寻被突如其来的雪崩困住的登山者，并回收他们的制式步枪。",al={"什么是 treacherous cold","treacherous cold 任务"}},{q="为什么要收集登山者的步枪？",a="登山者会将名字直接刻在步枪的枪托上。在极寒的雪堆中，遗体可能已被掩埋或无法找回，取回他们的武器能让铁炉堡确认阵亡者身份并通知其家人。",al={"为什么收集步枪","登山者步枪","为什么要拿走他们的枪"}},{q="谁在雪中遇难了？",a="在丹莫罗巡逻的新手登山者特别容易受到突发雪崩、坠冰和高海拔地区极端天气的影响。",al={"受害者是谁","谁在丹莫罗失踪了"}},{q="为什么之前没有进行搜寻？",a="虽然任务发布者通常会在雪崩后进行救援和搜寻工作，但丹莫罗最近的元素动荡使得深入山道执行任务变得过于危险，无法独自应对。",al={"为什么任务发布者不能去寻找","为什么需要冒险者"}},{q="步枪被回收后会怎样？",a="回收的步枪会被收集并送回铁炉堡，当地官方会确保这些个人武器归还给阵亡登山者的家属。",al={"步枪会被送去哪里","回收的步枪有什么用途"}},{q="丹莫罗的高海拔山道为何如此危险？",a="丹莫罗的高海拔地区充斥着严寒、致盲的雪崩和不稳定的悬崖。再加上动荡的元素活动，即使是训练有素的矮人巡逻队也可能迅速倒在恶劣的环境下。",al={"丹莫罗有多危险","丹莫罗的危险因素"}}},fp="16,294,19.299.0,13.352.0,16.314.0,25.162.0,43.245.0,30.153.0,45.210.0,42.172.0,54.203.0"}
P.entries["quest:992"] = {n="加基森水业公司",s="加基森的高级勘探员菲兹杜瑟正在为加基森水业公司招聘一名临时初级勘探员。由于游牧民占领了公司的水井，他交给你一个探水装置，让你去流沙岗哨附近的水潭取样。",h="加基森的高级勘探员菲兹杜瑟正在为加基森水业公司招聘一名临时初级勘探员。由于游牧民占领了公司的水井，他交给你一个探水装置，让你去流沙岗哨附近的水潭取样。",kw={"探水装置","菲兹杜瑟","加基森","加基森水业公司","流沙岗哨","塔纳利斯"},sec={{t="急需水源的公司",b="游牧民占领了加基森水业公司的所有水井，因此公司必须寻找更多免费的水源。高级勘探员菲兹杜瑟相信沙漠中还有水源，只是需要足够聪明的人先行勘探，他希望能有一名临时初级勘探员来提供帮助。"},{t="在流沙岗哨取样",b="你领到一个未使用的探水装置，并被派往流沙岗哨附近的水潭。水潭位于加基森的正西方，祖尔法拉克南面，在那里可以看见附近的巨魔。你的目标是用探水装置取一瓶水样，并将装有水样的装置带回给菲兹杜瑟。"},{t="回到菲兹杜瑟身边",b="当你回来时，菲兹杜瑟听说你遭到了某种恶毒的爬虫生物伏击，并承认确实不断有报告称，奇怪的虫形生物正在吸干沙漠里的水。菲兹杜瑟起初以为这只是胡言乱语，多半是那些游牧民惹的麻烦，但现在真相大白了。"}},faq={{q="是谁在加基森提供勘探工作？",a="高级勘探员菲兹杜瑟，他正在为加基森水业公司招聘一名临时初级勘探员。",al={"谁提供加基森水业调查任务","加基森水业调查任务发布者","菲兹杜瑟是谁"}},{q="为什么加基森水业公司要寻找新的水源？",a="游牧民占领了公司所有的水井，因此它需要寻找其他免费的水源。",al={"为什么要进行水质调查","为什么加基森需要水"}},{q="需要取样的水潭在哪里？",a="在流沙岗哨附近的水潭，它位于加基森正西方，祖尔法拉克南面，在那里可以看见附近的巨魔。",al={"水潭在哪里","流沙岗哨水潭位置","在哪里使用探水装置"}},{q="提供了什么工具来进行采集？",a="一个探水装置，你可以在水潭处用它来采集水样。",al={"探水装置","使用什么物品"}},{q="接下来要做什么？",a="这开启了后续任务链，接下来是调查腐化之巢。",al={"接下来是什么任务","加基森水业调查任务链"}}},fp="22,248,26.288.0,28.285.0,22.304.1,40.110.0,59.88.0,40.126.0,47.73.0,23.72.0"}
P.entries["quest:99260"] = {n="Fillion's Mission",s="Fillion's Mission 讲述了一次勘察行动后的余波，该行动旨在绘制眺望台立石的元素流图。所收集的数据原本旨在为往返于天空之墙与艾泽拉斯之间的破空船规划安全的航线，但侦察员的伤残却使整个计划陷入了危机。",h="Fillion's Mission 讲述了一次勘察行动后的余波，该行动旨在绘制眺望台立石的元素流图。所收集的数据原本旨在为往返于天空之墙与艾泽拉斯之间的破空船规划安全的航线，但侦察员的伤残却使整个计划陷入了危机。",kw={"elaadrin evengale","元素位面","fillion","瞰台立石","破空船","天空之墙","瓦拉纳尔","塑风者"},ang={["class:Mage"]="遵循至高法师计划的奥术师们将会理解，驾驶破空船穿过位面乱流所需的精细魔法计算是何等重要。",["race:Skyborne"]="这个任务直接触及了你们的族人在派系摩擦中努力建立往返于天空之墙与艾泽拉斯之间安全航线的挣扎。"},sec={{t="危险的任务",b="Fillion 被派遣前往眺望台立石收集关于元素能量流的关键读数。这些读数构成了操纵破空船往返于天空之墙与艾泽拉斯之间所需的计算基础。在经历了一场迫切需要救援的磨难后，Fillion 发现自己无法完成任务，而那些重要数据也被认为已经丢失。由于受伤无法继续任务，他指引救命恩人去向至高法师报告。"},{t="瓦拉纳尔的位面纷争",b="在瓦拉纳尔定居点，至高法师 Elaadrin Evengale 收到了 Fillion 生还的报告，感到一丝宽慰，但同时也为丢失的研究感到惋惜。没有可靠的导航数据，开辟穿梭于元素位面的安全通道面临着极大的困难。更糟糕的是，有报告称敌对的塑风者已经获得了他们自己的位面通行手段，却拒绝分享，将派系私利置于集体福祉之上。"}},faq={{q="Fillion 是谁？",a="Fillion 是至高法师派遣的一名特使或侦察员，负责从眺望台立石收集关于元素能量流的重要读数。在被一名冒险者救出后，他因身体过于虚弱而无法完成最初的任务。",al={"fillion 是谁","fillion 背景故事","fillion 魔兽世界"}},{q="至高法师 Elaadrin Evengale 是谁？",a="Elaadrin Evengale 是驻扎在瓦拉纳尔的至高法师。他指导着安全穿越元素位面的工作，并协调位面数据的回收，以保障往返于天空之墙与艾泽拉斯之间的旅行。",al={"至高法师是谁","elaadrin evengale","elaadrin 是谁"}},{q="为什么 Fillion 的数据如此重要？",a="这些数据记录了在眺望台立石收集到的元素能量流。这对于通过数学计算来安全引导破空船穿越元素位面到达艾泽拉斯至关重要，否则船只将会被摧毁。",al={"为什么数据很重要","fillion 丢失了什么数据","元素数据 天空之墙"}},{q="塑风者是谁？",a="塑风者是一个据称已经掌握了自己位面旅行方法的派系。根据 Evengale 至高法师的说法，他们由于教条式的傲慢而极力保守这一秘密，而不是为了族人的共同利益而分享它。",al={"塑风者是谁","塑风者传说","塑风者竞争对手"}},{q="什么是破空船？",a="破空船是专门设计用于在元素位面中飞行的船只。引导它们需要精确的元素能量流读数；否则，尝试在天空之墙与艾泽拉斯之间驾驶它们将会导致灾难性的后果。",al={"什么是破空船","破空船"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是 Evengale 至高法师所提及的一个敌对或受轻视的派系。他直接将塑风者那种自私和教条的行为与他们相提并论。",al={"奥拉凯斯是谁","奥拉凯斯","奥拉凯斯传说"}}},fp="17,310,21.471.0,25.464.1,15.246.0,42.212.0,36.240.0,24.247.0,20.233.0,21.177.0"}
P.entries["quest:993"] = {n="丢失的主人",s="收集到精良的月夜猛虎皮后，你带着完成的附魔月夜猛虎斗篷前往黑海岸的荒野，寻找失踪的暗夜精灵沃科尔。在忠诚的白熊格里姆爪的指引下，你必须追踪这名受伤的哨兵，以免他在被敌对的熊怪杀害前遭遇不测。",h="收集到精良的月夜猛虎皮后，你带着完成的附魔月夜猛虎斗篷前往黑海岸的荒野，寻找失踪的暗夜精灵沃科尔。在忠诚的白熊格里姆爪的指引下，你必须追踪这名受伤的哨兵，以免他在被敌对的熊怪杀害前遭遇不测。",kw={"奥伯丁","黑海岸","熊怪","格里姆爪","月夜猛虎斗篷","夜刃豹","特伦希斯","沃科尔"},ang={["class:Hunter"]="看着格里姆爪在道路上穿行以寻找救援沃科尔的行为，突显了卡利姆多训练有素的野兽所具备的卓越智慧与忠诚。",["faction:Alliance"]="奥伯丁依靠像沃科尔这样的哨兵来监视黑海岸熊怪部落日益严重的腐蚀，这使得营救他成为前哨站的一项重要优先事项。",["race:NightElf"]="格里姆爪为寻找主人沃科尔的援助而表现出的坚定忠诚，展现了暗夜精灵哨兵与其动物伙伴之间的羁绊。"},sec={{t="林中的灯塔",b="特伦希斯在奥伯丁缝制好附魔月夜猛虎斗篷后，寻找失踪哨兵沃科尔的工作便正式开始了。他的熊伙伴格里姆爪回到了定居点南面的道路上，时刻守候着特伦希斯派来的盟友。只要向这头忠诚的野兽打个招呼，旅行者就能直接离开大路，前往沃科尔藏身的洞穴。"},{t="隐匿于暗影",b="沃科尔在被当地受腐蚀的熊怪打成重伤后，躲进了一个洞穴中。他被困在此处且伤势严重，只能完全依靠潜行和格里姆爪的机智来避免被彻底包围。附魔斗篷为他提供了必要的隐蔽和希望，让他得以计划撤离，尽管他的伤势使他在返回奥伯丁的旅途中处于岌岌可危的状态。"}},faq={{q="沃科尔是谁？",a="沃科尔是一名常驻黑海岸的暗夜精灵哨兵，在靠近敌对熊怪营地冒险时失踪。他在冲突中受了重伤，设法爬进了附近的一个洞穴，而他的伙伴熊格里姆爪则外出寻找援助。",al={"沃科尔背景故事","失踪的主人是谁"}},{q="如何找到沃科尔的藏身处？",a="格里姆爪守在奥伯丁南面的道路旁。向这头野兽挥手示意，让他知道你是特伦希斯派来的帮手，格里姆爪便会径直跑向沃科尔疗伤的隐秘洞穴。",al={"沃科尔在哪里","寻找沃科尔的洞穴","如何跟随格里姆爪"}},{q="附魔月夜猛虎斗篷的用途是什么？",a="特伦希斯用精良的月夜猛虎皮制作斗篷并附上魔法，以提供短暂但强大的潜行效果。它的魔法能让你在搜寻沃科尔的过程中不被黑海岸的生物发现，之后斗篷会交给沃科尔。",al={"月夜猛虎斗篷","斗篷魔法"}},{q="是谁袭击了沃科尔？",a="沃科尔在黑海岸游荡时遭到了受腐蚀的熊怪部落的伏击并负伤。尽管他设法躲过了直接的杀戮，但伤势使他无法在无人协助的情况下独自回到奥伯丁。",al={"谁伤害了沃科尔","为什么沃科尔在流血"}},{q="找到沃科尔后会发生什么？",a="沃科尔收到附魔斗篷后会喘口气，并请求你协助他逃离荒野。你可以选择引导他通过潜行悄悄离开，或是凭借武力杀出一条通往熊怪群的道路。",al={"沃科尔后续任务","失踪的主人任务后续"}}},fx={["49342a22"]={q="特伦希斯为什么这么急着找到沃科尔？",a="特伦希斯担心留给自己暗夜精灵同胞的时间不多了。沃科尔遭到腐化熊怪伏击，只有忠诚的熊格里姆克劳回来求援。特伦希斯知道沃科尔独自藏身，撑不了多久。他已经制成能掩盖气味和踪迹的附魔斗篷，现在需要你赶在熊怪猎杀沃科尔或伤势要了他的命之前找到他。",al={"特伦希斯的动机","为什么救沃科尔","特伦希斯为什么关心沃科尔"}}},fp="13,277,21.399.0,18.402.1,14.248.0,37.223.0,55.230.0,20.211.0,34.243.1"}
P.entries["quest:994"] = {n="杀出重围",s="“以武脱困”是黑海岸的一项联盟任务，在任务中，冒险者需要通过正面战斗帮助沃科尔突破周围的威胁。在杀出重围到达大路并与他忠实的伙伴格里姆爪重聚后，玩家将返回奥伯丁向特伦希斯报告沃科尔已安全逃脱的消息。",h="“以武脱困”是黑海岸的一项联盟任务，在任务中，冒险者需要通过正面战斗帮助沃科尔突破周围的威胁。在杀出重围到达大路并与他忠实的伙伴格里姆爪重聚后，玩家将返回奥伯丁向特伦希斯报告沃科尔已安全逃脱的消息。",kw={"奥伯丁","黑海岸","护送","格里姆爪","塞拉伊","特伦希斯","沃科尔"},ang={["faction:Alliance"]="协助当地斥候加深了年轻的联盟与暗夜精灵之间的纽带，证明了该阵营在保卫卡利姆多北部边境方面的价值。",["race:NightElf"]="营救像沃科尔这样的斥候对于卡多雷在黑海岸那岌岌可危的控制权至关重要，那里野兽、腐蚀和外来入侵者正威胁着他们祖传的林地。"},sec={{t="直接的脱困之路",b="当被困在黑海岸危险的荒野中时，潜行并非总是首选。面对危险，暗夜精灵沃科尔采取了一种简单粗暴的策略：直接杀出一条血路，穿过周围的敌对生物以求生。沃科尔没有试图悄无声息地溜走，而是依靠武力开辟了一条通往大路的直行通道。"},{t="路上的重逢",b="安全抵达大道让沃科尔得以与他的忠诚熊伙伴格里姆爪重聚，格里姆爪一直守在路边等待着他。逃出生天后，沃科尔在准备接下来的旅程时，敦促冒险者直接向奥伯丁的特伦希斯汇报。传达沃科尔安全的消息不仅让暗夜精灵领导层感到安心，也立即引起了哨兵塞拉伊的注意，这指向了南方灰谷正在酝酿的更深层的麻烦。"}},faq={{q="沃科尔是谁？",a="沃科尔是黑海岸的一名暗夜精灵斥候或护林人，他与他的伙伴格里姆爪一同失踪了。在接受特伦希斯委托的冒险者找到他后，他需要帮助以摆脱敌对的野生生物和危险的地形。",al={"沃科尔身份","谁是沃科尔","沃科尔黑海岸"}},{q="格里姆爪是谁？",a="格里姆爪是沃科尔忠诚的熊伙伴。在沃科尔被困期间，格里姆爪一直独自待在路边，并作为沃科尔逃生路线上的汇合点。",al={"格里姆爪","沃科尔的熊","沃科尔的宠物"}},{q="特伦希斯为什么关心沃科尔的回归？",a="特伦希斯负责统筹奥伯丁的斥候行动和当地的防御工作。追踪失踪的盟友并评估沿海岸的威胁，对于维持暗夜精灵在局势不断动荡的黑海岸的控制权至关重要。",al={"特伦希斯沃科尔","为什么帮助沃科尔","特伦希斯任务"}},{q="完成该任务后会发生什么？",a="向奥伯丁的特伦希斯报告沃科尔已安全撤离。随后任务线将引导至“前往灰谷”。",al={"以武脱困之后","what comes next","沃科尔的下一个任务"}},{q="有其他方式来完成沃科尔的护送任务吗？",a="是的。在营救沃科尔时，冒险者可以选择不同的方式：通过“以武脱困”正面杀出重围，或者利用潜行引导他悄悄避开危险。",al={"以武脱困的其他方法","通过潜行脱困","沃科尔的选择"}},{q="该任务在更宏大的剧情中起什么作用？",a="确保沃科尔的生还起到了连接黑海岸局部冲突与暗夜精灵领地更大规模区域防御的桥梁作用，并直接开启了灰谷的任务。",al={"沃科尔剧情","黑海岸到灰谷任务线"}}},fx={["8bb9ddbb"]={q="沃科尔为什么要杀出一条路？",a="沃科尔被困在黑海岸的荒野中，身陷险境，离开同伴格里姆克劳已经太久了。他决定直接突围，而不是悄悄溜走；无论什么敌人挡住通往道路的去路，他都要杀出一条路来。他唯一的目标就是抵达安全之地，与忠诚的熊团聚，然后再向奥伯丁方向报告。",al={"沃科尔的动机","为什么强行突围","沃科尔为什么想这么做"}},["365007a7"]={q="沃科尔为什么需要你帮忙逃出去？",a="沃科尔与格里姆克劳失散，身处荒野，被敌人团团包围。他孤身一人，毫无遮掩，强行杀出荒野风险极高。有你提供战斗支援，他活着闯过重围、抵达安全的大路的机会就大得多，远胜于独自杀出一条路。",al={"沃科尔为什么需要我","沃科尔为什么不能独自逃走","为什么帮助沃科尔"}}},fp="20,323,16.372.0,19.463.1,14.245.0,16.175.0,46.236.0,41.98.1,52.179.0,52.188.1"}
P.entries["quest:99411"] = {n="Kyle's Gone Missing!",s="Kyle's Gone Missing!是血蹄村的一个当地任务，阿哈布·麦蹄请求过往的冒险者寻找他那走失的爱犬——“狂暴的”凯尔。喂给这只饥饿的小狗一块嫩陆行鸟肉可以平息他的脾气，并确保他能平安回家。",h="Kyle's Gone Missing!是血蹄村的一个当地任务，阿哈布·麦蹄请求过往的冒险者寻找他那走失的爱犬——“狂暴的”凯尔。喂给这只饥饿的小狗一块嫩陆行鸟肉可以平息他的脾气，并确保他能平安回家。",kw={"阿哈布·麦蹄","血蹄村","凯尔","“狂暴的”凯尔","kyle's gone missing!","莫高雷","平原陆行鸟","嫩陆行鸟肉"},ang={["faction:Horde"]="协助血蹄村的当地村民处理日常事务，可以加强与舒哈鲁的联系，帮助他们在定居和保卫家园时获得支持。",["race:Tauren"]="阿哈布·麦蹄是血蹄村的居民，这桩私事成了在莫高雷牧场中一种常见的社区互助行为。"},sec={{t="丢失的猎犬",b="在血蹄村，长者阿哈布·麦蹄正在为他那走失的宠物——“狂暴的”凯尔而担忧。虽然这个头衔对局外人来说可能听起来很吓人，但凯尔其实是阿哈布珍视的小狗，他溜到了莫高雷的草原上。阿哈布请求路过此地的旅行者追踪他那不听话的伙伴，并提供一顿丰盛的餐食来安抚他狂野的性情。"},{t="一个简单的办法",b="平息凯尔的怒火需要一块嫩陆行鸟肉，这种肉取自游荡在莫高雷的敏捷平原陆行鸟。拿出这顿美食可以满足饥饿的小狗，抚平他狂暴的情绪，并引导他安全地回到血蹄村和感激他的主人身边。"}},faq={{q="阿哈布·麦蹄是谁？",a="阿哈布·麦蹄是居住在莫高雷血蹄村的一位牛头人长者。他非常疼爱自己的宝贝狗凯尔，每当凯尔离家太远时，阿哈布就会求助于过往的冒险者，请他们帮忙找到并喂食这只走失的犬类。",al={"阿哈布·麦蹄","阿哈布 莫高雷","任务发布者 凯尔"}},{q="“狂暴的”凯尔是谁？",a="凯尔是阿哈布·麦蹄心爱的犬类宠物，被称为“狂暴的”凯尔。尽管他的头衔听起来很凶猛，但他其实是阿哈布珍视的伙伴，只需喂他嫩陆行鸟肉就能平息他的怒火并将他引诱回来。",al={"凯尔是谁","凯尔 狗","“狂暴的”凯尔"}},{q="这个任务发生在哪里？",a="血蹄村是一个位于莫高雷中心地带的牛头人定居点，在雷霆崖的南面。它是当地部落、商人和牧民的重要聚集地。",al={"血蹄村在哪里","血蹄村位置"}},{q="为什么凯尔需要嫩陆行鸟肉？",a="凯尔对游荡在莫高雷的平原陆行鸟身上切下的鲜肉情有独钟。提供嫩陆行鸟肉可以平息这只饥饿猎犬的怒火，并说服他安全地回到阿哈布身边。",al={"为什么需要嫩陆行鸟肉","陆行鸟肉 凯尔","如何安抚凯尔"}},{q="为什么凯尔被称为“狂暴的”？",a="凯尔在当地被称为“狂暴的”，当他走失或饥饿时就会在平原上徘徊。一旦有耐心的旅行者为他提供食物，他的狂暴状态就会消退。",al={"为什么凯尔会狂暴","凯尔生气"}},{q="在哪里可以找到凯尔？",a="凯尔在莫高雷血蹄村周围的开阔平原上徘徊。旅行者通常会通过搜索附近的草原找到他，直到能为他提供一顿食物。",al={"凯尔位置","凯尔在哪里"}}},fp="20,253,15.366.0,15.260.0,22.227.0,25.209.0,32.181.0,39.190.0,32.149.0,24.168.0"}
P.entries["quest:995"] = {n="偷偷溜走",s="“通过潜行逃脱”是一个发生在黑海岸的联盟护送任务。在熊怪巢穴深处找到被困的暗夜精灵斥候沃科尔后，玩家将协助他避开敌对野兽，安全抵达目的地，随后向奥伯丁的特伦希斯报告。",h="“通过潜行逃脱”是一个发生在黑海岸的联盟护送任务。在熊怪巢穴深处找到被困的暗夜精灵斥候沃科尔后，玩家将协助他避开敌对野兽，安全抵达目的地，随后向奥伯丁的特伦希斯报告。",kw={"灰谷","奥伯丁","黑海岸","护送","熊怪","潜行","特伦希斯","沃科尔"},ang={["class:Rogue"]="潜行者们很欣赏沃科尔的战术直觉，即绕过固守的敌人，而不是在鲁莽的正面交锋中浪费时间和鲜血。",["faction:Alliance"]="成功救出沃科尔，向奥伯丁的暗夜精灵领导层证明了非卡多雷的联盟盟友可以被委以荒野行动的重任。",["race:NightElf"]="对于暗夜精灵来说，帮助沃科尔巩固了重要的斥候网络，这些斥候守护着卡利姆多遭受侵扰的森林，而腐蚀正从那些被腐化的兽穴和巢穴中不断向外蔓延。"},sec={{t="被困的斥候",b="沃科尔被派遣深入黑海岸，调查该地区日益严重的威胁，却最终被困在了一处熊怪洞穴中。他因寡不敌众且与大路隔绝，不得不依靠一名路过的盟友来协调撤离，赶在敌对的熊怪发现他潜逃之前逃离。"},{t="谨慎的撤离",b="沃科尔没有选择自杀式的正面突围，而是采取了谨慎的行动。他依靠阴影和审慎的走位，悄然滑过洞穴中那些被腐蚀的生物。因为深知速度与安静至关重要，沃科尔在离开洞穴入口后便与救援者分道扬镳，独自先行奔跑，并指示救命恩人在奥伯丁定居点与其汇合。"},{t="向奥伯丁报告",b="在回到奥伯丁后，玩家向特伦希斯传达了救援的消息。特伦希斯是一位负责协调保护这片多灾多难海岸线的暗夜精灵领袖。特伦希斯认为沃科尔的平安归来证明了只要纪律严明、通力合作，就能够抵御黑海岸及其周边荒野中不断蔓延的黑暗。"}},faq={{q="沃科尔是谁？",a="沃科尔是一名暗夜精灵斥候，他为了执行上级的任务深入了黑海岸的荒野。他在一个敌对的熊怪巢穴中被困，直到被一名联盟冒险者救出。",al={"沃科尔背景故事","沃科尔是谁","沃科尔黑海岸"}},{q="为什么沃科尔在离开洞穴后独自跑掉？",a="沃科尔指出，一旦离开洞穴狭窄的通道，他独自一人行动会更快。他指示冒险者在奥伯丁重聚，而不是在开阔的道路上一同前行。",al={"为什么沃科尔要离开","沃科尔分开行动"}},{q="特伦希斯是谁？",a="特伦希斯是一位驻扎在奥伯丁的知名暗夜精灵协调员。他负责监督当地的侦查工作，并组织应对威胁黑海岸的腐蚀力量和敌对生物。",al={"特伦希斯奥伯丁","特伦希斯是谁"}},{q="这次救援发生在什么地方？",a="救援行动始于一处熊怪洞穴，该洞穴位于黑海岸荒凉且充满争端的森林深处，远离安全的奥伯丁。",al={"沃科尔洞穴位置","沃科尔洞穴在哪里"}},{q="完成这个任务后会发生什么？",a="在确认沃科尔安全并向特伦希斯汇报后，玩家会被指引前往下一个阶段，向南前往灰谷，执行任务“前往灰谷的跋涉”。",al={"通过潜行逃脱后是什么任务","沃科尔后的下一个任务"}},{q="这次救援中，除了潜行还有其他选择吗？",a="沃科尔提供了另一种方案：冒险者可以选择不通过潜行溜走，而是通过战斗，以纯粹的武力杀出重围，这是另一种以战斗为核心的护送选择。",al={"武力逃脱","沃科尔的其他任务","潜行与武力"}}},fx={b4a3f8fd={q="沃科尔为什么想悄悄逃出去？",a="沃科尔被困在敌对的熊怪巢穴深处，最要紧的是活着回到奥伯丁，向特伦希斯报告。只要不惊动腐化熊怪，悄悄溜过它们就是离开巢穴最稳妥的办法，也能避免在狭窄的空间里陷入一场寡不敌众的恶战。",al={"为什么悄悄逃走","沃科尔悄悄逃走的动机","为什么和沃科尔一起悄悄离开"}}},fp="22,259,17.293.0,16.380.0,22.325.0,14.196.0,52.198.0,17.191.0,34.137.0,41.179.0,50.190.0"}
P.entries["quest:997"] = {n="德纳兰的泥土",s="“德纳兰的泥土”是一项从多兰纳尔定居点向南前往宁静的奥拉密斯湖的差事。塞拉尔·刃叶请求旅行者将一批迟到的稀有富含养分的泥土送交给她的植物学同事德纳兰，他正在研究这棵新的世界之树的枝干和植物。",h="“德纳兰的泥土”是一项从多兰纳尔定居点向南前往宁静的奥拉密斯湖的差事。塞拉尔·刃叶请求旅行者将一批迟到的稀有富含养分的泥土送交给她的植物学同事德纳兰，他正在研究这棵新的世界之树的枝干和植物。",kw={"达纳苏斯","德纳兰","多兰纳尔","奥拉密斯湖","稀土","塞拉尔·刃叶","泰达希尔","树人"},ang={["class:Druid"]="德鲁伊与德纳兰的研究工作有着天然的亲和力，因为追踪泰达希尔植物群的生长和平衡对于守护这根新枝干上的自然至关重要。",["profession:Herbalism"]="草药师会很欣赏德纳兰的湖畔休憩处，因为他的实验中心在于了解这棵新生的世界之树所独有的、脆弱且正在萌芽的植物生命。",["race:NightElf"]="对于从幽影谷出来的暗夜精灵来说，协助塞拉尔和德纳兰是让他们初步了解维持泰达希尔所需的更广泛的守护工作。"},sec={{t="多兰纳尔的信使",b="当旅行者途经多兰纳尔向南前往奥拉密斯湖时，塞拉尔·刃叶会拦住他们，请他们帮一个过期的忙。她的同行研究员德纳兰从达纳苏斯订购了一批特殊的稀土，用于支持他正在进行的植物学研究。这批货物在运输途中延误了，最近才抵达多兰纳尔。塞拉尔不想让这些肥沃的泥土变质或闲置，因此她寻找一位乐于助人的信使，愿意沿着森林小径把东西送到德纳兰的湖边营地。"},{t="培育泰达希尔",b="德纳兰在奥拉密斯湖东岸设有一个孤立的工作站，他在那里观察泰达希尔的树苗生态系统是如何扎根的。泰达希尔还很年轻，在海加尔山之战后迅速生长，其植物群的表现也出人意料。德纳兰利用独特的土壤混合物和样本来测试岛上树人及原生植物的生命力和行为，因此这批新鲜的稀土对于他的实验至关重要。"}},faq={{q="谁是德纳兰？",a="德纳兰是一位暗夜精灵研究员和草药师，他在奥拉密斯湖东岸建立了营地。他致力于研究、培育泰达希尔独特的植物群，并对其进行实验。",al={"德纳兰背景故事","德纳兰是谁","德纳兰npc"}},{q="塞拉尔·刃叶在哪里？",a="塞拉尔·刃叶居住在多兰纳尔，这是泰达希尔中部主要的暗夜精灵前哨站，她在那里协调研究物资并协助穿梭于枝干间的旅行者。",al={"塞拉尔·刃叶位置","塞拉尔在哪里"}},{q="稀土是用来做什么的？",a="这批货物包含了从首都达纳苏斯寄来的经过特殊富养的泥土。德纳兰依靠它来培育实验性植被，并测试像树人这样的泰达希尔原生树苗如何应对多样的生长条件。",al={"德纳兰为什么需要泥土","稀土用途"}},{q="奥拉密斯湖在哪里？",a="奥拉密斯湖位于多兰纳尔以南，是一片坐落在泰达希尔南侧根部之间宁静的水域。",al={"奥拉密斯湖位置","如何前往奥拉密斯湖"}},{q="为什么货物会迟到？",a="这批包裹必须从达纳苏斯运出，在沿着泰达希尔蜿蜒的道路运输过程中遇到了未指明的延误，最后才到达多兰纳尔的配送中心。",al={"为什么泥土会迟到","延误的包裹"}},{q="运送这些泥土会有什么后续？",a="收到这些稀有泥土后，德纳兰会招募信使帮助他在湖岸收集树人幼芽和种子，从而开启一系列更深入的植物学实地研究。",al={"德纳兰泥土后续任务","what comes next"}}},fx={["77a156f9"]={q="塞拉尔·刃叶为什么要把稀土送过去？",a="德纳兰一直热切盼望这批从达纳苏斯运来的货物，以便继续研究泰达希尔的当地植物。稀土在运输途中耽搁，最近才抵达多兰纳尔。塞拉尔希望你尽快把它送到湖边营地，免得材料失去效力。",al={"为什么要运送稀土","塞拉尔·刃叶的动机","为什么把稀土送给德纳兰"}},["2b5476f7"]={q="塞拉尔为什么让你送货？",a="塞拉尔·刃叶留在多兰纳尔处理自己的职责，而她恰好看到你是一位正要南下前往奥拉密斯湖的能干旅人。这批货物已经耽搁了很久，托付给正好要去德纳兰隐居处的人，是最快把东西送到他手里的办法。",al={"塞拉尔为什么需要我","为什么不派信使","德纳兰的稀土为什么找我"}}},fp="15,297,22.508.0,22.471.0,15.208.0,33.178.0,32.234.0,23.118.0,26.178.0,40.181.1"}
P.entries["quest:cutting-teeth"] = {n="小试身手",s="“小试身手”是新兵抵达杜隆塔尔的试炼谷后所面临的最初考验。监督者高内克会指派新兵去削减在附近仙人掌农场出没的花斑野猪的数量，以测试他们的基本战斗准备情况。在这一简单的成人礼中幸存下来，证明了立志成为战士或施法者的新兵拥有效忠部落所必需的骨气。",h="“小试身手”是新兵抵达杜隆塔尔的试炼谷后所面临的最初考验。监督者高内克会指派新兵去削减在附近仙人掌农场出没的花斑野猪的数量，以测试他们的基本战斗准备情况。在这一简单的成人礼中幸存下来，证明了立志成为战士或施法者的新兵拥有...",kw={"贫瘠之地","野猪","小试身手","杜隆塔尔","高内克","部落","花斑野猪","新兵","试炼谷"},ang={["faction:Horde"]="每一位踏入杜隆塔尔的年轻勇士都必须从最底层做起，证明部落的未来建立在鲜血与汗水之上，而非不劳而获的声望。",["race:Orc"]="兽人文化将实际的生存和尚武荣誉置于一切之上；即便是卑微的野猪清理工作，也是迈向成年、服务萨尔新国家的庄严第一步。",["race:Troll"]="随着暗矛部族与他们的兽人盟友一同重建家园，年轻的巨魔斥候和巫医也必须在杜隆塔尔残酷的捕食者中证明自己的自立能力。"},sec={{t="骨气的衡量",b="试炼谷从不纵容虚荣的幻想。虽然年轻的新兵可能梦想着在贫瘠之地追逐巨兽，或是战场上赢得荣耀，但监督者高内克却以更为脚踏实地的事物开始对他们的评估。削减山谷农场周围的花斑野猪是作为一项基础评估：它能确保新兵知道如何挥舞武器或施放法术，能够应对野兽的攻击，并具备在最初的小规模战斗中存活下来的必要常识。"},{t="驯服红尘",b="除了考验新手外，猎杀花斑野猪对这个红色沙漠定居点还有实际的民生用途。这些野蛮的猪群在营地北面和东北面的泥土农场游荡，刨食仙人掌地，威胁着在杜隆塔尔贫瘠土壤中培育出的稀缺物资。通过派遣有志之士去清除它们，营地既控制了当地的害虫，又将年轻的兽人和巨魔锻造成了保卫这个新生国家的称职守卫。"}},faq={{q="为什么高内克派遣新兵去对付野猪，而不是更大的野兽？",a="正如高内克自己承认的那样，活着的新兵对部落来说远比死了的更有用。虽然贫瘠之地有着强大的科多兽和捕食者，但派遣未经考验的新手去对付它们只会导致不必要的牺牲。野猪提供了一种可靠的基本战斗能力测试，而不会造成无谓的伤亡。",al={"为什么要打野猪","为什么要杀野猪","高内克野猪狩猎"}},{q="花斑野猪位于哪里？",a="花斑野猪在试炼谷中心空地北面和东北面的灌木丛和泥土农场中刨食。",al={"野猪位置","野猪在哪里","寻找花斑野猪"}},{q="“小试身手”这个短语有什么意义？",a="这个短语指的是在某一技艺或职业中获得最初的实践经验。对于部落的未来卫士来说，这标志着从木桩训练和空谈转向在真实的生存斗争中见血。",al={"小试身手是什么意思","小试身手的含义"}},{q="谁指派了这项试炼？",a="这项任务由高内克指派，他是一位驻扎在试炼谷中心的监督者，负责评估并指导进入杜隆塔尔训练场的新兵。",al={"谁给予小试身手任务","小试身手任务发布者","高内克试炼"}},{q="这就完成了试炼谷的训练吗？",a="不。高内克警告说，猎杀野猪仅仅是热身而已。完成这项任务后，紧接着就是更危险的挑战，包括对抗人形入侵者和收集山谷的重要资源。",al={"这是最后一个任务吗","小试身手之后是什么"}},{q="为什么野猪会在山谷中造成问题？",a="这些野猪在当地的泥土农场和灌木丛中横冲直撞，危及工人，并消耗着像仙人掌果实这样维持营地生存的少数几种坚韧作物。",al={"野猪困扰","试炼谷野猪"}}},fx={["852f533a"]={q="高内克为什么派我去，而不是派经验丰富的战士？",a="试炼谷的唯一目的，就是淘汰弱者，把新兵锻造成能干的部落防卫者。经验丰富的老兵还有更要紧的职责：保卫杜隆塔尔、巩固奥格瑞玛。对未经考验的新手来说，与当地野兽搏斗能证明你具备足够的胆识和骨气，这样别人才会把真正的军务交给你。",al={"为什么派我去完成磨牙任务","高内克为什么需要新兵","为什么不派经验丰富的卫兵"}}},fp="13,382,21.488.0,19.449.0,67.301.0,36.136.0,55.225.0,23.166.0,56.205.0,46.182.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="戈加尔的清凉果",s="“戈加尔的仙人掌果”是年轻的战士和新手在炎热的试炼谷中必须完成的一项简单任务。为了从杜隆塔尔酷热难耐的考验中获得解脱，兽人戈加尔会雇佣旅行者收集野生的仙人掌果，以便他制作那道著名的清凉果。这项任务能让新兵们学会如何在荒凉的土地上采集资源并生存下去。",h="“戈加尔的仙人掌果”是年轻的战士和新手在炎热的试炼谷中必须完成的一项简单任务。为了从杜隆塔尔酷热难耐的考验中获得解脱，兽人戈加尔会雇佣旅行者收集野生的仙人掌果，以便他制作那道著名的清凉果。这项任务能让新兵们学会如何在荒凉...",kw={"仙人掌","仙人掌果","杜隆塔尔","食物","采集","戈加尔","部落","试炼谷"},ang={["faction:Horde"]="每一个踏入试炼谷的新兵都会很快了解到，忍受杜隆塔尔那惩罚般的烈日是他们训练的一部分，与战斗同等重要。",["profession:Cooking"]="戈加尔的菜肴突显了将坚硬、带刺的沙漠植物转化为滋养食物和清凉点心所需的足智多谋。",["race:Orc"]="定居杜隆塔尔意味着必须适应干旱的景观，而由原生仙人掌制成的简单菜肴代表了兽人在新家园中繁衍生息的实用能力。"},sec={{t="在赤色荒野中生存",b="试炼谷那赤红的土地以无情而闻名。在严苛的战斗演练和针对当地野兽的残酷试炼之间，疲惫和脱水接踵而至。对于那些迈出作为部落保卫者第一步的年轻兽人和暗矛巨魔来说，学会就地取材与挥舞斧头一样重要。生长在山谷各处的仙人掌结出的成熟果实富含水分，能让人从令人窒息的沙漠烈日下获得即时的慰藉。"},{t="山谷佳肴",b="驻扎在训练场内的戈加尔已将当地的采集工作转化为一门艺术。他那著名的“清凉果”在山谷居民中颇具传奇色彩，因为它能让人在酷暑中迅速降温，效果比跳进河水里还要好。通过雇佣热切的新兵采集附近仙人掌上的带刺果实，戈加尔既保证了厨房的供应，又能确保新来的流浪者不会饿着肚子踏上杜隆塔尔的旅程。"}},faq={{q="戈加尔是谁？",a="戈加尔是一名驻扎在杜隆塔尔试炼谷中的兽人居民。他没有监督正式的战斗演练，而是将时间花在准备降温的补给品和诸如他那著名的清凉果之类的美食上，以帮助新兵抵御沙漠的酷热。",al={"戈加尔是谁","戈加尔背景故事","谁发布仙人掌果任务"}},{q="什么是清凉果？",a="这是一种受欢迎的当地甜点和清凉零食，由戈加尔使用从荒野沙漠仙人掌上采集的新鲜仙人掌果制作而成。它因能在杜隆塔尔灼热的阳光下提供快速的解脱和至关重要的水分而受到学员们的推崇。",al={"清凉果食物","什么是清凉果","戈加尔的食谱"}},{q="仙人掌果在哪里可以找到？",a="仙人掌果生长在散布于试炼谷红色悬崖和峡谷各处的开花仙人掌根部的地面上，通常成簇分布。",al={"仙人掌果在哪里","寻找仙人掌果","如何获得仙人掌果"}},{q="为什么戈加尔要求新兵收集它们？",a="试炼谷内酷热难耐，而戈加尔无法离开岗位去亲自在沙漠中游荡。他提出与任何愿意前往灌木丛中为他收集原材料的过路新手分享他珍贵的成品。",al={"为什么要采集仙人掌果","戈加尔为什么需要果子"}},{q="这个任务与更大的故事情节有关联吗？",a="没有。这是一个独立的采集任务，旨在让新兵在完成部落的初步试炼时，熟悉从当地环境中收集资源。",al={"是否有任务线","清凉果后续","清凉果之后是什么"}},{q="为什么在试炼谷中采集很重要？",a="杜隆塔尔是一片由干旱岩石和灌木丛开垦出来的严酷而无情的土地。部落领袖们认为，学会利用杜隆塔尔稀缺的自然资源生存，是任何想要在更广阔的世界中经受考验的人所必备的基础训练。",al={"为什么要采集","杜隆塔尔生存"}}},fx={e97f8b04={q="戈加尔为什么要收集仙人掌果？",al={"戈加尔为什么要仙人掌果","戈加尔的动机","为什么收集仙人掌果"}}},fp="30,363,24.470.0,17.431.0,14.265.0,30.242.0,30.154.0,44.257.0,46.178.0,50.231.0"}
P.entries["quest:lazy-peons"] = {n="懒惰的苦工",s="工头塔兹利尔受够了试炼谷的劳工在工作时打瞌睡。他将他那沉重的木棒交给年轻的新兵，并指派他们去试炼谷各处管教偷懒的苦工，以确保重要的木材能持续运往杜隆塔尔的定居点。",h="工头塔兹利尔受够了试炼谷的劳工在工作时打瞌睡。他将他那沉重的木棒交给年轻的新兵，并指派他们去试炼谷各处管教偷懒的苦工，以确保重要的木材能持续运往杜隆塔尔的定居点。",kw={"木棒","杜隆塔尔","工头塔兹利尔","偷懒的苦工","木材","苦工","试炼谷"},ang={["faction:Horde"]="杜隆塔尔的每一个前哨站都依赖于这些苦工采集的木材，因此最基本的劳工纪律也是集体生存的关键。",["race:Orc"]="对于成年的年轻兽人来说，管教自己族人的劳动力是他们上的第一课，让他们了解在荒野中开创一个国家所需的残酷现实和实际纪律。",["race:Troll"]="与盟友并肩训练的暗矛巨魔们亲眼目睹了这种兽人建筑风格中特有的蛮力和管理上的无奈。"},sec={{t="烈日下的偷懒者",b="在杜隆塔尔干旱的平原上建立新家园需要大量的木材、石料和艰苦的体力劳动。大部分负担都落在了苦工阶层身上——他们是兽人中缺乏武艺的一群，但却是部落勤劳的脊梁。不幸的是，对于工头塔兹利尔来说，试炼谷炙热的天气和繁重的劳动让这些劳工很容易溜到树荫下打个非法的小盹。"},{t="迅速的叫醒服务",b="为了避免生产停滞，工头塔兹利尔采取了一种非常直接的管理策略：使用工头的木棒。他将这件钝器纪律工具交给新来的部落新兵，并派他们穿过谷底，去敲醒那些正在睡觉的劳工。被惊醒的苦工们晕头转向地赶回去砍木头，因为他们明白在杜隆塔尔的生存之战中，懒汉是没有立足之地的。"}},faq={{q="苦工们为什么会打瞌睡？",a="在杜隆塔尔烈日的炙烤下采集沉重的木材是一项残酷而耗费体力的工作。如果没有监工在旁边盯着，苦工们经常会溜到大树底下休息。",al={"为什么苦工会偷懒","正在睡觉的苦工","工作时睡觉的苦工"}},{q="工头塔兹利尔是谁？",a="工头塔兹利尔是驻扎在试炼谷的一名兽人监工。他管理着负责采集木材和部落新建设所需物资的劳动团队。",al={"塔兹利尔","谁给予偷懒的苦工任务"}},{q="什么是工头的木棒？",a="这是一根由工头塔兹利尔使用的重皮短棍，用来管教偷懒的劳工。在头上迅速敲一下足以唤醒睡觉的苦工，且不会造成永久性伤害。",al={"木棒","苦工木棍","木棒工具"}},{q="苦工在部落中扮演什么角色？",a="苦工代表了兽人社会的劳动阶层。虽然他们身体强壮，但被认为不适合参加军事战争，而是充当建筑工、矿工和伐木工，为部落的战争机器和定居点提供燃料。",al={"兽人苦工的角色","什么是苦工","苦工阶层"}},{q="我去哪里寻找睡觉的苦工？",a="他们遍布试炼谷，在大兽穴的南北两边都能找到。去那些枝叶茂密的大树底下找，那是劳工们躲避阳光的地方。",al={"偷懒苦工的位置","偷懒的苦工在哪里","寻找睡觉的苦工"}},{q="苦工被唤醒后会发生什么？",a="当你把木棒还给工头塔兹利尔后，他会派你去干另一件杂活：从附近的一个深洞里找回他丢失的矿工锄。",al={"完成偷懒的苦工之后","偷懒的苦工后续任务","苦工任务之后的下一个任务"}}},fx={["088600b8"]={q="你被派去对付谁？",a="你被派去对付试炼谷的苦工，他们是部落中等级最低的劳工，负责砍伐山谷里的树木获取木材。许多人却丢下斧头，在树荫下打盹，而不是干活。尽管他们对山谷的补给至关重要，但他们出了名的懒散，必须严厉提醒他们守在岗位上。",al={"我该打谁","懒惰的苦工是谁","懒惰苦工的目标"}},["94fa6eb4"]={q="为什么工头塔兹利尔需要你管教这些苦工？",a="工头塔兹利尔负责监督试炼谷的多项事务，无法离开岗位去每片树林搜寻偷懒的人。山谷里的战士训练师和守卫都忙着训练新兵或防范当地威胁，把一根棍棒交给你这样能干的年轻新兵，是最快让劳工守规矩的办法。",al={"为什么让我对付懒惰的苦工","塔兹利尔为什么不打他们","为什么不让守卫去"}},a41786ab={q="工头塔兹利尔为什么要把苦工叫醒？",a="工头塔兹利尔负责为试炼谷供应木材，而建造工作需要持续不断的劳力。苦工要是偷懒，在树下打盹，伐木就会停摆。塔兹利尔需要管束他们，让他们积极伐木，确保部落营地的物资和防御工事所需的木材供应充足。",al={"塔兹利尔的动机","为什么叫醒苦工","为什么打苦工"}}},fp="10,277,19.426.0,20.419.0,33.197.0,25.186.0,32.185.0,37.227.0,35.162.0,42.146.1"}
P.entries["quest:sarkoth"] = {n="萨科斯",s="在试炼谷南侧的一处高地上潜伏着萨科斯，这是一只异常凶猛的蝎虫，它那带毒的蜇刺已将一位年轻的暗矛猎人逼入死亡的边缘。在树下受伤濒死的巨魔哈纳祖恳求一位路过的勇士杀掉这只野兽，并取回它残缺的螯，以此挽回自己的荣誉。",h="在试炼谷南侧的一处高地上潜伏着萨科斯，这是一只异常凶猛的蝎虫，它那带毒的蜇刺已将一位年轻的暗矛猎人逼入死亡的边缘。在树下受伤濒死的巨魔哈纳祖恳求一位路过的勇士杀掉这只野兽，并取回它残缺的螯，以此挽回自己的荣誉。",kw={"暗矛","杜隆塔尔","哈纳祖","残缺的螯","萨科斯","蝎虫","试炼谷"},ang={["faction:Horde"]="在试炼谷这种残酷的环境中，向倒下的同伴伸出援手正是萨尔的部落致力于培养的共同力量的体现。",["race:Orc"]="兽人们理解在没有胜利的情况下死去的痛苦；为哈纳祖复仇赋予了一位未经考验的斥候勇士般的满足感，即看到他的敌人被击败。",["race:Troll"]="对于暗矛部族的同胞而言，响应哈纳祖的恳求是亲情的庄严职责，确保族人的英勇表现得到认可，而不是消逝在杜隆塔尔的风沙之中。"},sec={{t="荣誉之事",b="试炼谷中的试炼旨在磨练部落的年轻勇士，但残酷的荒漠却很少给予第二次机会。当年轻的巨魔斥候哈纳祖在追踪谷中带毒的本土生物时，他遇到了一只比其他同类大得多、也更致命的蝎虫。尽管他成功发起了一次重击，毁掉了它的一只螯，但萨科斯的尾巴还是刺入了哈纳祖的胸口，让他倒在干燥的红土上鲜血直流。在面对生命的终点时，他唯一的愿望就是这只野兽不要活得比他更久。"},{t="高地恐怖",b="萨科斯在俯瞰试炼谷南端的高耸平原上游荡。这只怪兽以哈纳祖攻击留下的破碎螯为标志，盘踞在高高的山脊上，攻击任何胆敢攀爬岩石小径的人。杀掉这只生物并将它伤痕累累的螯带回给哈纳祖，能给这位受伤的斥候带来一些苦涩的慰藉——这证明了他最后那次绝望的攻击确实重创了怪物，让它最终得以被除掉。"}},faq={{q="我在哪里可以找到萨科斯？",a="萨科斯在哈纳祖倒下的地方南面的高地顶部游荡。要找到它，请寻找一条盘旋在峡谷岩壁上的土坡路，那只巨大的蝎虫就在山脊上漫步。",al={"萨科斯位置","萨科斯在哪里","如何到达萨科斯那里"}},{q="谁是哈纳祖？",a="哈纳祖是一位正在试炼谷进行狩猎试炼的年轻暗矛巨魔。他被萨科斯抓伤并中了毒，正瘫倒在一棵树下，绝望地寻找冒险者在他伤重不治前为他复仇。",al={"哈纳祖","濒死的巨魔 试炼谷","萨科斯任务发布者"}},{q="为什么哈纳祖想要萨科斯的螯？",a="在战斗中，哈纳祖在被刺中前发起了猛烈的一击，震碎了萨科斯的螯。取回那只残缺的螯不仅是怪物已死的证明，也能让哈纳祖感到自豪，因为他知道他最后的战斗并非完全徒劳。",al={"为什么需要萨科斯的螯","残缺的螯 证明","哈纳祖 荣誉"}},{q="哈纳祖会死于毒素吗？",a="虽然身受重伤且对自己眼中的失败感到苦涩，但除掉萨科斯给了哈纳祖足够的希望，让他能够派遣你去大兽穴寻求医疗援助，而不是在那棵树下等待死亡。",al={"哈纳祖是否幸存","哈纳祖 命运","哈纳祖死了吗"}},{q="萨科斯与其他蝎虫有什么不同？",a="与在低处谷底匆忙爬行的普通蝎虫工兵不同，萨科斯体型明显更大、更具攻击性，并且带有近期战斗的明显痕迹，包括一只受损的螯。",al={"萨科斯 区别","为什么萨科斯很特别","蝎虫首领 杜隆塔尔"}},{q="杀掉萨科斯后的后续任务是什么？",a="一旦你将萨科斯的螯带回给哈纳祖，他会敦促你尽快赶回大兽穴，将他的困境告知营地领导者，并在他的毒伤导致致命后果之前带回援助。",al={"萨科斯之后的任务","哈纳祖 下一步","回到大兽穴 任务"}}},fx={["2909716d"]={q="哈纳祖为什么想杀死 Sarkoth？",a="哈纳祖觉得自己正被蝎子的毒液夺去性命，他不愿蒙受耻辱而死。他的父亲总说他成不了大器；若他没能杀死对手，就独自死在泥地里，那便证明了这些刻薄话都是真的。为自己的败北复仇，是他维护战士荣誉、确保最后的敌人不会比他活得更久的最后机会。",al={"为什么要杀 sarkoth","哈纳祖的动机","哈纳祖为什么想杀死 sarkoth"}},["3ecf0257"]={q="哈纳祖为什么不能亲自杀死 Sarkoth？",a="哈纳祖身受重伤，倒在树下不断流血。在南部高原上的交锋中，他击中了 Sarkoth 的爪子，但那头野兽却把毒刺深深扎进了他的胸膛。他中了毒，虚弱得无法站起，也没法回大兽穴求援，只能全靠你在他的生命流逝殆尽前完成这场狩猎。",al={"哈纳祖为什么需要我","哈纳祖为什么不能战斗","为什么让我对付 sarkoth"}}},fp="7,323,17.545.0,18.451.0,25.181.0,16.238.0,38.247.0,33.217.1,49.201.0,49.183.1"}
P.entries["quest:your-place-in-the-world"] = {n="起点",s="这个简单的成年仪式标志着年轻的勇士踏前一步，誓言效忠部落。该任务由试炼谷的卡尔图克发布，旨在将未经考验的新兵直接送往高内克处，开始他们的基础战斗训练。这代表了在杜隆塔尔这片严酷土地上，迈向荣誉与生存的第一步。",h="这个简单的成年仪式标志着年轻的勇士踏前一步，誓言效忠部落。该任务由试炼谷的卡尔图克发布，旨在将未经考验的新兵直接送往高内克处，开始他们的基础战斗训练。这代表了在杜隆塔尔这片严酷土地上，迈向荣誉与生存的第一步。",kw={"cutting teeth","杜隆塔尔","高内克","部落","卡尔图克","新兵","试炼谷","大酋长"},ang={["faction:Horde"]="杜隆塔尔的每一位年轻部落新兵都必须在以大酋长的名义拿起武器之前，证明他们拥有捍卫这个新兴国家的勇气。",["race:Orc"]="对于兽人来说，成年并前往试炼谷报到是一个深刻的文化里程碑，其核心是个人荣誉和战斗准备。",["race:Troll"]="在与兽人盟友一同在杜隆塔尔定居后，暗矛巨魔与他们的兄弟们一起在这里训练，以建立团结并实现共同生存。"},sec={{t="Coming of Age在杜隆塔尔",b="在试炼谷干旱的峡谷中，年轻的兽人和暗矛巨魔必须证明自己的价值，才能踏入外面的世界。在大酋长萨尔的领导下，生活需要力量、警惕和纪律。卡尔图克评估着每一位渴望上阵的新兵，适度地浇灭他们想要与恶魔和巨龙肉搏的梦想，引导他们承担现实的职责。新兵们在这里开始他们的训练，在获得荣耀之前先学会谦逊。"},{t="向高内克报到",b="在距离卡尔图克几步之遥的地方，坐着高内克，这是一位驻扎在篝火旁的粗鲁老兵。高内克以怀疑的眼光评估着这些刚到的新兵，经常抱怨营地里补给匮乏。然而，他的职责是通过严格的试炼来磨练这些初出茅庐的战士，首先就是清除威胁营地补给的当地害虫。"}},faq={{q="这个任务的目的是什么？",a="它作为试炼谷年轻新兵的入门成年仪式。它正式让你加入部落服役，并将你介绍给高内克，由他为你指派第一次真正的战斗任务。",al={"为什么要做这个任务","部落的首个任务","你的世界定位"}},{q="卡尔图克是谁？",a="卡尔图克是一位驻扎在试炼谷入口处的兽人监工。他负责迎接进行成年仪式的新兵，观察他们的情况，并将他们引导至营地内合适的训练师和领导者那里。",al={"卡尔图克的职责","谁发布这个任务"}},{q="高内克是谁？",a="高内克是一位经验丰富的部落训练师，坐在试炼谷的篝火旁。他的任务是测试新来的新兵，并在允许他们离开峡谷之前将他们磨练成合格的士兵。",al={"高内克的职责","高内克在哪里"}},{q="这个任务接下来会引导到哪里？",a="向高内克报到后，将立即开启“Cutting Teeth”试炼，新兵们会被送往泥地中去猎杀斑点野猪，以证明他们基本的战斗能力。",al={"下一个任务是什么","你的世界定位之后的任务"}},{q="为什么要将新兵留在试炼谷？",a="试炼谷是杜隆塔尔内一处隐蔽且受保护的峡谷，旨在训练、评估并淘汰新兵，以免他们在遇到更广阔领地中致命的野兽、野猪人和敌方侦察兵时丧命。",al={"为什么要在试炼谷","为什么要从这里开始"}},{q="这个任务在兽人和巨魔之间有区别吗？",a="年轻的兽人和暗矛巨魔都在试炼谷一起开始他们的训练，并从卡尔图克那里接到同样的入伍征召。",al={"巨魔入门任务","兽人入门任务"}}},fx={["4ca14302"]={q="卡尔图克为什么派你去找高内克？",a="你终于到了可以为部落而战、为大酋长萨尔赢得荣耀的年纪。卡尔图克看出了你的潜力，但他知道，满腔热血的新兵往往还没学会基本功，就梦想着屠龙。他让你去找高内克接受适合新手的任务考验，确保你能活下来，最终成为试炼谷真正的助力。",al={"卡尔图克为什么要你完成这件事","卡尔图克的动机","卡尔图克为什么派你去"}}},fp="23,330,24.449.0,19.377.0,34.217.0,15.200.0,14.215.0,32.168.0,46.216.0,47.152.0"}
P.entries["subzone:addle-s-stead"] = {n="腐草农场",s="腐草农场是位于暮色森林西南部的一处废弃农庄，静静地坐落在乌鸦岭以南那阴暗的森林深处。尽管最初的农场主早已逃离，但这里已成为迪菲亚潜行者的一处隐秘补给站。",h="腐草农场是位于暮色森林西南部的一处废弃农庄，静静地坐落在乌鸦岭以南那阴暗的森林深处。尽管最初的农场主早已逃离，但这里已成为迪菲亚潜行者的一处隐秘补给站。",kw={"腐草农场","迪菲亚","迪菲亚潜行者","暮色森林","乌鸦岭"},ang={["class:Rogue"]="这座隐秘的前哨站显示出迪菲亚组织是多么深入地潜入各个领地，将他们的特工埋藏在暮色森林阴暗的帷幕之下。",["faction:Alliance"]="对于追踪失踪的瓦里安·乌瑞恩国王的联盟调查员来说，这座破败的农舍里保存着迪菲亚潜行者留下的至关重要的阴谋案卷。"},sec={{t="黑暗中的前哨",b="像散布在暮色森林各处的许多被遗忘的家园一样，腐草农场在黑暗与废墟笼罩该地区后逐渐荒废。这里并没有空置太久，而是被迪菲亚潜行者改作他用。迪菲亚的特工们在农场周边游荡，潜伏在破败的农舍内，并将补给品藏在谷仓里，利用暮色森林西南部阴影的掩护，躲避守夜人和暴风城当局的耳目。"},{t="国王失踪之谜",b="迪菲亚潜行者在此的存在已不仅是简单的劫掠。腐草农场充当了一个作战安全屋，保存着兄弟会的重要机密记录。将该地区的阴谋分子与瓦里安·乌瑞恩国王失踪事件联系起来的关键文件和案卷都可以追溯到这片土地上，这使得这座毫不起眼的破败农场成为了揭开联盟内部叛乱阴谋的关键线索。"}},faq={{q="腐草农场在哪里？",a="腐草农场位于暮色森林西南部，坐落在乌鸦岭镇的正南面，沃古尔食人魔山的西侧。",al={"腐草农场位置","腐草农场在哪里","寻找腐草农场"}},{q="现在是谁控制着腐草农场？",a="该农庄目前被迪菲亚潜行者重兵占据，包括夜行者、夜刃刺客和附魔师，他们将旧农舍和谷仓当作一处偏远的藏身点。",al={"谁在腐草农场","腐草农场怪物","腐草农场敌人"}},{q="为什么这座农场被废弃了？",a="和暮色森林的大部分地区一样，当森林陷入黑暗、野兽和亡灵的诅咒之中时，原住居民纷纷逃离，导致该农场被遗弃。",al={"农场发生了什么","addle是谁","为什么腐草农场荒废了"}},{q="是什么让联盟的冒险者来到腐草农场？",a="在暮色森林追踪线索的联盟冒险者有时会被派往腐草农场，搜查这座迪菲亚据点，寻找一份重要的案卷。",al={"为什么去腐草农场","腐草农场任务","暮色森林失踪的国王"}}},fx={["84087cc5"]={q="什么是腐草农场？",a="腐草农场是暮色森林西南部的一处废弃农庄，位于乌鸦岭以南、沃古尔食人魔山以西。和这片地区的许多宅院一样，它被蔓延的阴霾吞噬，原来的主人也弃它而去，只留下杂草丛生的田地和破败的农舍。",al={"什么是腐草农场","腐草农场","关于腐草农场"}},c80be076={q="腐草农场发生过什么？",a="这座农庄曾是一处宁静的家园，但暮色森林遭受黑暗诅咒、居民被迫离开后，它便逐渐荒废。迪菲亚潜行者的成员后来占据了谷仓和农舍，将这里用作据点。",al={"腐草农场的历史","这里发生过什么"}},["67874313"]={q="腐草农场危险吗？",a="非常危险。这处废弃地产由敌对的迪菲亚成员巡逻，其中包括擅长潜行的夜行者、致命的夜刃，以及潜伏在农舍附近的附魔师。",al={"腐草农场有多危险","腐草农场安全吗","腐草农场的威胁"}}},fp="13,242,21.445.0,35.406.1,31.134.0,37.166.0,26.177.0,50.154.1"}
P.entries["subzone:agama-gor"] = {n="阿迦玛戈",s="阿迦玛戈是位于南贫瘠之地的一处大型刺鬃野猪人营地，坐落在从陶拉祖营地向西前往莫高雷的道路正北方。它是附近部落哨站的心头大患，充满了敌对的野猪人，它们拼死守卫着这片崎岖的领地。",h="阿迦玛戈是位于南贫瘠之地的一处大型刺鬃野猪人营地，坐落在从陶拉祖营地向西前往莫高雷的道路正北方。它是附近部落哨站的心头大患，充满了敌对的野猪人，它们拼死守卫着这片崎岖的领地。",kw={"阿迦玛戈","贫瘠之地","血岩碎片","刺鬃","陶拉祖营地","碎牙","野猪人"},ang={["faction:Horde"]="陶拉祖营地的安全取决于对阿迦玛戈的刺鬃野猪人的有效压制，因此消灭它们的战士是路过此地的部落守卫者的优先任务。",["race:Tauren"]="阿迦玛戈坐落在通往大门和莫高雷的道路上，其劫掠者对牛头人的补给线和朝圣者构成了长期的威胁。"},sec={{t="刺鬃要塞",b="阿迦玛戈横跨南贫瘠之地尘土飞扬的平原，是好战的刺鬃野猪人部落的防御定居点。这里距离陶拉祖营地极近，野猪人在当地维持着密集的荆棘网、茅屋和粗糙的图腾。它们庞大的存在对往来于贫瘠之地和莫高雷青草山丘之间的旅人构成了严重威胁，促使部落的斥候和猎人必须对它们进行持续不断的遏制战。"},{t="血岩碎片与流放者",b="除了部落与野猪人之间普遍的敌意之外，阿迦玛戈还是被称为“血岩碎片”的神秘绯红色矿石的主要来源。这些地质矿物在栖息于村庄的刺鬃野猪人身上可以找到，是被关押在陶拉祖营地的野猪人流放者碎牙所珍视的物品。在与阿迦玛甘的神圣本质相关的古老信仰驱使下，冒险者们经常突袭阿迦玛戈，收集这些碎片并用它们换取强大的部落护符。"}},faq={{q="阿迦玛戈是什么地方？",a="阿迦玛戈是南贫瘠之地的一处大型刺鬃野猪人定居点。它位于从陶拉祖营地向西通往莫高雷的主路正北方。",al={"阿迦玛戈概览","这个野猪人营地是什么","陶拉祖附近的野猪人营地"}},{q="为什么这里的刺鬃野猪人如此敌对？",a="野猪人认为，所有受过倒下的野猪半神阿迦玛甘触碰过的土地都理应属于它们。因此，刺鬃野猪人将陶拉祖营地附近的牛头人和兽人视为侵犯它们祖传土地的不速之客。",al={"为什么野猪人会攻击","野猪人的敌意","为什么刺鬃野猪人如此愤怒"}},{q="在阿迦玛戈能找到什么？",a="阿迦玛戈各处的刺鬃野猪人经常携带血岩碎片——这些充斥着原始力量的结晶沉积物可以交给陶拉祖营地的被流放野猪人碎牙进行交易。",al={"在这里能获得什么","阿迦玛戈掉落物品","为什么要杀这里的刺鬃野猪人"}},{q="碎牙是谁？他与这个地方有什么关系？",a="碎牙是一只被囚禁在陶拉祖营地牢笼里的被流放野猪人。它对自己的族人怀恨在心，只要部落冒险者能从阿迦玛戈的旧日同类身上带来血岩碎片，它就乐于为他们提供防护护符。",al={"与碎牙的关系","谁是碎牙","陶拉祖的猪人囚犯"}}},fx={["62d1d1e5"]={q="谁住在阿迦玛戈？",a="阿迦玛戈是刺背野猪人的居所。他们将陶拉祖营地以北的这片领地变成了坚固的聚居地，凶狠地抵御任何接近他们的荆棘丛与居所的外来者。",al={"谁住在阿迦玛戈","阿迦玛戈的居民","阿迦玛戈有什么人"}},def0ef2e={q="阿迦玛戈危险吗？",a="危险。阿迦玛戈到处都是敌对的刺背野猪人，他们一见到旅人就会发动攻击。这里靠近陶拉祖营地通往西方的道路，若是偏离大路，任何没有准备好应对成群野猪人守卫的旅人都会陷入险境。",al={"阿迦玛戈有多危险","阿迦玛戈安全吗","阿迦玛戈的危险"}}},fp="9,311,24.479.0,22.458.0,18.164.0,49.247.0,31.194.0,56.247.0"}
P.entries["subzone:agamand-family-crypt"] = {n="阿加曼德家族墓穴",s="阿加曼德家族墓穴坐落在阿加曼德磨坊北侧的山丘中，是提瑞斯法最富有的农场主家族之一的古老安息地。如今，这里已被达戈尔队长率领的天灾军团占据，墓穴遭到破坏，沉睡的祖先被复活，成为了毫无心智的恐怖怪物。",h="阿加曼德家族墓穴坐落在阿加曼德磨坊北侧的山丘中，是提瑞斯法最富有的农场主家族之一的古老安息地。如今，这里已被达戈尔队长率领的天灾军团占据，墓穴遭到破坏，沉睡的祖先被复活，成为了毫无心智的恐怖怪物。",kw={"阿加曼德家族墓穴","阿加曼德磨坊","达戈尔队长","墓穴","陵墓","天灾军团","骷髅","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者来说，达戈尔队长对墓穴的占领是天灾军团在提瑞斯法的一种不可容忍的存在，不仅亵渎了死者，还威胁到了幽暗城的北部边境。"},sec={{t="不安的先祖",b="在第三次战争之前，阿加曼德家族在提瑞斯法林地北部拥有广阔的地产，并将他们的先辈埋葬在这座山坡陵墓中。当瘟疫摧毁王国时，这座墓穴落入了天灾军团的走狗——达戈尔队长的魔爪之中。达戈尔并没有让这个富有家族的先人们安息，而是利用黑暗通灵术唤醒了墓穴中的骷髅和充满怨恨的幽灵，将这片神圣的墓地变成了一个位于被遗忘者领地边缘的侵略性天灾据点。"}},faq={{q="阿加曼德家族墓穴在哪里？",a="墓穴开凿在提瑞斯法林地北部的山坡上，位于阿加曼德磨坊的正北方。",al={"阿加曼德墓穴位置","墓穴在哪里","如何找到阿加曼德墓穴"}},{q="现在是谁控制着这座墓穴？",a="这座陵墓由天灾军团的仆从达戈尔队长把守，他策划了墓穴内的黑暗魔法并指挥着那些复活的死尸。",al={"阿加曼德墓穴里有什么人","墓穴首领","达戈尔队长"}},{q="我会在墓穴里遇到什么？",a="墓穴里充满了被唤醒的骷髅和不安的阿加曼德先祖之灵。在黑暗魔法的驱使下，这些复仇心切的亡灵会攻击任何踏入墓穴的人。",al={"墓穴敌人","阿加曼德墓穴里有什么","阿加曼德墓穴怪物"}},{q="墓穴里的亡灵是被遗忘者的盟友吗？",a="不是。里面的生物是听命于达戈尔队长的天灾奴仆，因此它们对被遗忘者和生者旅行者都怀有敌意。",al={"他们是被遗忘者吗","阿加曼德墓穴友好度","为什么要攻击亡灵"}}},fx={["1e347eab"]={q="什么是阿加曼德家族墓穴？",a="阿加曼德家族墓穴是阿加曼德家族祖先的安葬之所，位于他们在提瑞斯法林地的大型磨坊以北。它曾是一处宁静的圣所，原本是为了让这个贵族家族永享安息；洛丹伦被天灾军团征服后，这里却陷入了黑暗。",al={"什么是阿加曼德家族墓穴","阿加曼德墓穴信息","这座墓穴是什么"}},["2b90d8b5"]={q="阿加曼德家族墓穴发生过什么？",a="天灾军团席卷洛丹伦北部时，阿加曼德庄园遭到摧毁，墓地也被亵渎。一名名叫 Captain Dargol 的巫妖王仆从占据了墓穴，用通灵术唤醒阿加曼德家族的尸体与先祖之灵，让他们成为没有心智、满怀仇恨的奴仆。",al={"阿加曼德墓穴的历史","阿加曼德墓穴发生了什么"}},["1ce0db9b"]={q="阿加曼德家族墓穴危险吗？",a="危险至极。尘封的墓穴走廊里遍布被唤起的亡灵，以及受通灵魔法扭曲、满怀怨恨的幽魂。在 Captain Dargol 的控制下，这些幽魂和行尸会猛烈攻击任何擅自闯入墓穴的人。",al={"阿加曼德墓穴危险吗","阿加曼德墓穴的危险","阿加曼德墓穴有多危险"}},["02ac6c6f"]={q="为什么叫阿加曼德家族墓穴？",a="它以阿加曼德家族命名。这个洛丹伦显赫的人类家族拥有并经营着附近的阿加曼德磨坊。王国覆灭前，这座墓穴是为安葬他们数代祖先而建造的。",al={"为什么叫阿加曼德墓穴","阿加曼德家族墓穴名称的由来","阿加曼德家族是什么人"}}},fp="20,295,18.535.0,42.109.0,33.129.0,39.175.0,57.144.0"}
P.entries["subzone:agamand-mills"] = {n="阿加曼德磨坊",s="阿加曼德磨坊是一处位于提瑞斯法林地北部高地的庞大农场与风车群。这里曾是富有的阿加曼德家族引以为傲的庄园，如今却已荒废，成为了该地区最大的天灾军团据点。",h="阿加曼德磨坊是一处位于提瑞斯法林地北部高地的庞大农场与风车群。这里曾是富有的阿加曼德家族引以为傲的庄园，如今却已荒废，成为了该地区最大的天灾军团据点。",kw={"阿加曼德","阿加曼德家族墓穴","阿加曼德磨坊","达格尔队长","德夫林·阿加曼德","格雷戈尔·阿加曼德","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者而言，收复阿加曼德磨坊不仅是战术上的需要，更是对天灾军团的私人复仇，以及像库勒曼·法席恩这样的前庄园仆从清算旧账的时刻。"},sec={{t="分裂的家族",b="富有的阿加曼德家族在提瑞斯法北部建立了一套庞大的磨坊网络。当第三次战争爆发，天灾军团席卷洛丹伦时，族长格雷戈尔·阿加曼德拒绝逃离，他加固了庄园，并说服了他的家臣和劳工坚守阵地。他们的补给和石墙本可以支撑住，但他们最小的儿子德夫林·阿加曼德背叛了自己的血脉。德夫林屠杀了庄园的守卫，并将行尸走肉放进了寝室。从内部瓦解后，剩余的防御者被消灭，整个家族也加入了毫无意识的亡灵行列。"},{t="腐朽的堡垒",b="如今，阿加曼德磨坊已成为提瑞斯法林地中最根深蒂固的天灾军团堡垒，对被遗忘者的领地构成了直接威胁。腐朽的风车在布满尸妖、僵尸和骷髅怪的田野上空转动。在庄园地下，达格尔队长在深处的阿加曼德家族墓穴中指挥着驻军，练习着死灵法术，复活了一代又一代的阿加曼德先祖。在布瑞尔，执政官塞弗伦和死亡卫士们正积极发起战役，试图在天灾军团进军幽暗城之前清理磨坊，清除那里的天灾势力。"}},faq={{q="为什么阿加曼德磨坊会被天灾军团占领？",a="当天灾军团蹂躏洛丹伦时，阿加曼德家族加固了他们的庄园，试图抵御亡灵大军。然而，最小的儿子德夫林·阿加曼德背叛了家族，打开大门迎接天灾军团，导致庄园内的所有人都被屠杀并复活。",al={"阿加曼德磨坊发生了什么","为什么磨坊里有亡灵","阿加曼德磨坊背景故事"}},{q="现在是谁控制着这些磨坊？",a="这座庄园是天灾军团的一个地区前哨站，由达格尔队长领导。达格尔在戒备森严的阿加曼德家族墓穴深处活动，利用黑暗魔法将先祖的尸体复活为新的士兵。",al={"谁领导着阿加曼德磨坊","提瑞斯法的天灾领袖","谁负责磨坊"}},{q="为什么被遗忘者关心这个地方？",a="这些磨坊代表了提瑞斯法林地中残存的天灾军团无意识部队的最大聚集地。如果任其发展，达格尔队长的部队将威胁到布瑞尔，并可能切断通往南方幽暗城的道路。",al={"为什么布瑞尔要攻击阿加曼德","被遗忘者对阿加曼德磨坊的兴趣"}},{q="阿加曼德家族是谁？",a="他们曾是洛丹伦一个富有的地主家族，拥有提瑞斯法北部境内的磨坊和周边农田。如今，其复活后的后裔——包括格雷戈尔、尼莎、瑟曼和德夫林——正作为毫无意识的奴仆在庄园里游荡。",al={"阿加曼德家族是谁","阿加曼德家族血统","格雷戈尔·阿加曼德"}}},fx={["9a335608"]={q="什么是阿加曼德磨坊？",a="阿加曼德磨坊是位于提瑞斯法林地北部高地的一大片风车和农田。瘟疫席卷洛丹伦之前，这里是富有的阿加曼德贵族家族拥有的繁荣农庄。如今，这里已破败不堪，成了该地区规模最大的天灾军团据点。",al={"阿加曼德磨坊的背景","阿加曼德磨坊以前是什么","这个地方是什么"}},ef38e774={q="阿加曼德磨坊发生过什么？",a="天灾军团入侵提瑞斯法时，Gregor Agamand 决定加固磨坊，并说服家人和工人留下来抵抗。防御工事坚固，物资也很充足，直到他们的小儿子 Devlin 背叛了他们。Devlin 杀死哨兵，让一支亡灵突击队进入营地，在防御者睡梦中屠杀了三分之一的人。之后的攻击接连不断，幸存者寡不敌众，最终染上瘟疫，变成了巫妖王麾下没有心智的爪牙。",al={"阿加曼德磨坊的陷落","阿加曼德磨坊的历史","阿加曼德磨坊是如何陷落的"}},["513094d3"]={q="阿加曼德磨坊危险吗？",a="这里危险至极。庄园里到处都是复活的农夫、骷髅守卫，以及死而复生的阿加曼德家族成员。家族墓穴深处，天灾军团指挥官 Captain Dargol 施展黑暗通灵术唤醒长眠已久的祖先，使磨坊成为一个武装据点，直接威胁提瑞斯法的被遗忘者。",al={"阿加曼德磨坊安全吗","阿加曼德磨坊有多危险","阿加曼德磨坊的威胁"}},["4d06011e"]={q="为什么叫阿加曼德磨坊？",a="这座庄园以阿加曼德家族命名。这个洛丹伦富有的人类家族拥有磨坊和周围的农田，庄园一直沿用他们的名字，直到他们惨遭覆灭。",al={"为什么叫阿加曼德","阿加曼德磨坊名称的由来","谁给阿加曼德磨坊命名"}}},fp="13,244,15.623.0,16.563.0,42.290.0,33.222.0,42.218.0,27.234.0"}
P.entries["subzone:agmond-s-end"] = {n="埃格蒙德的营地",s="埃格蒙德的营地是位于荒芜之地南部丘陵中的一处废弃矮人挖掘场。这里曾经是一处充满希望的勘探点，由勘探员埃格蒙德领导，但在穴居怪破土而出并 overrun 了营地、杀害了领队之后，这里变成了一座屠宰场。",h="埃格蒙德的营地是位于荒芜之地南部丘陵中的一处废弃矮人挖掘场。这里曾经是一处充满希望的勘探点，由勘探员埃格蒙德领导，但在穴居怪破土而出并 overrun 了营地、杀害了领队之后，这里变成了一座屠宰场。",kw={"埃格蒙德","埃格蒙德的营地","荒芜之地","挖掘场","勘探员","迷失者塞尔杜林","穴居怪"},ang={["race:Dwarf"]="这座营地严酷地提醒着人们，在没有足够军事支援的情况下挖掘古老的大地是有多么危险。"},sec={{t="恐怖的挖掘场",b="和荒芜之地干旱地区中的许多地点一样，埃格蒙德的营地最初是一项矮人企图发掘古代遗物并深入探索大地埋藏历史的冒险。当野蛮的穴居怪从周围的裂隙中涌出并淹没矿工时，那个梦想戛然而止。埃格蒙德本人在袭击中被杀，这个地点因此得名。今天，这座被毁的挖掘场仍然完全被石库穴居怪所占据，破碎的板条箱和废弃的工具依然留在它们当初掉落的地方。"},{t="孤独的邻居",b="在被毁的挖掘场附近坐落着一座孤零零的营地，居住着迷失者塞尔杜林，一位理智早已丧失的矮人。他是少数几个愿意在这处注定的毁灭之地附近的南部沙漠中冒险的人之一。"}},faq={{q="埃格蒙德是谁？",a="埃格蒙德是一位矮人勘探员，他领导了一次进入荒芜之地南部的挖掘行动。他的勘探工作在地下穴居怪出现并屠杀了包括他在内的整个探险队后，以灾难告终。",al={"埃格蒙德是谁","埃格蒙德背景故事"}},{q="什么生物居住在埃格蒙德的营地？",a="这座被毁的挖掘场被敌对的穴居怪彻底占据，它们屠杀了矮人矿工，并将被毁的营地及周围的岩架据为己有。",al={"埃格蒙德的营地的怪物","谁住在这里"}},{q="谁住在埃格蒙德的营地附近？",a="一位名为迷失者塞尔杜林的矮人隐士在附近的南部丘陵中维持着一个营地，警惕地注视着这片荒凉的土地。",al={"附近的npc","塞尔杜林的位置"}},{q="为什么矮人最初要在这里挖掘？",a="矮人勘探员经常在荒芜之地进行勘探，以寻找泰坦遗物、古代遗迹和丰富的矿脉，尽管许多此类探险队都低估了潜伏在地下的野蛮生物。",al={"为什么矮人要挖掘","挖掘的目的"}}},fp="12,266,21.475.0,17.215.0,15.181.0,36.158.0,28.137.0,49.204.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Aku'mai's Lair",s="Aku'mai's Lair是黑暗深渊中最深、最黑暗的洞穴。它位于Moonshrine Sanctum之后，这个被淹没的空洞是阿库麦尔的巢穴，这是一只被尊为上古之神仆从的恐怖多头蛇。",h="Aku'mai's Lair是黑暗深渊中最深、最黑暗的洞穴。它位于Moonshrine Sanctum之后，这个被淹没的空洞是阿库麦尔的巢穴，这是一只被尊为上古之神仆从的恐怖多头蛇。",kw={"aku'mai's lair","阿库麦尔","黑暗深渊","多头蛇","moonshrine sanctum","纳迦","上古之神","暮光之锤"},ang={["class:Druid"]="从阿库麦尔的水下巢穴中散发出的邪恶变异和非自然腐蚀，对卡利姆多的自然水道和野兽构成了严重的破坏。",["race:NightElf"]="对于暗夜精灵来说，看到一座被亵渎的艾露恩神庙最终沦为邪恶上古之神孽种的肮脏巢穴，是对神圣的灰谷土地不可容忍的玷污。"},sec={{t="深渊之心",b="Aku'mai's Lair被封印在Moonshrine Sanctum之后，代表了席卷黑暗深渊的腐蚀的顶峰。要进入洞穴，必须通过点燃纳迦雕像两旁的四个火盆来进行黑暗仪式，从而唤醒誓死保卫入口的守护者。在这些沉重的双开门之后是一个不见天日的洪水淹没的洞穴。在这里，暮光之锤教徒和入侵的纳迦聚集在一起，崇拜着阿库麦尔——一只被认为是上古之神活仆从的古老三头多头蛇。"},{t="毁灭的先驱",b="阿库麦尔在巢穴中的存在使其成为了暮光之锤末日计划的焦点。教徒们将这只巨兽视为预示着黑暗时代的到来，认为它的出现和持续的滋养将预示着囚禁他们古老神祇的地底监狱的破碎。在献祭供品的滋养和黑魔法的狂热守护下，这个地下水潭成为了古老邪恶试图重返卡利姆多的阴森象征。"}},faq={{q="Aku'mai's Lair位于哪里？",a="Aku'mai's Lair位于灰谷黑暗深渊洞穴群的最深处，就在Moonshrine Sanctum的封印之门后面。",al={"aku'mai's lair在哪里","如何到达阿库麦尔的房间","aku'mai's lair位置"}},{q="如何打开通往Aku'mai's Lair的大门？",a="通往巢穴的双开门需要通过点燃Moonshrine Sanctum内环绕纳迦雕像的四个仪式火盆，并击败被召唤出来保护它们的生物波次来解锁。",al={"打开aku'mai's lair大门","如何解锁aku'mai's lair","点燃阿库麦尔火盆"}},{q="这个洞穴里栖息着什么？",a="该洞穴栖息着阿库麦尔，这是一只被远古黑暗力量污染的巨大三头多头蛇，也是上古之神的仆从。",al={"aku'mai's lair里有什么","aku'mai's lair里栖息着什么","aku'mai's lair的头目"}},{q="为什么暮光之锤教派在这里进行崇拜？",a="暮光之锤将阿库麦尔尊为上古之神的仆从，其教徒们相信增强这头野兽的力量将有助于带回上古之神统治世界的时代。",al={"为什么教徒崇拜阿库麦尔","暮光之锤与aku'mai's lair","为什么暮光之锤在这里"}}},fx={d1c19121={q="什么是 Aku'mai's Lair？",a="Aku'mai's Lair 是黑暗深渊水下废墟中最深、最黑暗的洞穴。它曾是供奉艾露恩的古代暗夜精灵神殿的一部分，如今这片被水淹没的空洞成了一个三头巨型九头蛇的圣所。这头生物深受上古之神邪恶力量的影响。",al={"什么是 aku'mai's lair","aku'mai's lair 信息","关于 aku'mai's lair"}},b75b148a={q="这里为何变成了 Aku'mai's Lair？",a="上古的大分裂之后，黑暗深渊神殿沉入海底，逐渐被人遗忘，沦为废墟。数百年间，腐化之力渗入水淹的深处，使可怖的九头蛇 Aku'mai 将这些水下洞室据为巢穴，黑暗教徒和纳迦也聚集于此崇拜它。",al={"aku'mai's lair 的历史","aku'mai's lair 发生过什么","aku'mai's lair 是如何形成的"}},["7d86eb37"]={q="Aku'mai's Lair危险吗？",a="这里极其危险。除了守卫着Moonshrine Sanctum的狂热者和娜迦之外，巢穴中还栖居着一位古神的庞大仆从。阿库麦尔会喷吐腐蚀性气息，发动毁灭性的狂暴攻击，并释放原始而邪恶的力量，足以撕碎毫无准备的冒险者。",al={"aku'mai's lair危险吗","aku'mai's lair有多危险","aku'mai's lair的危险"}},["39ca825a"]={q="这座洞穴为什么叫Aku'mai's Lair？",a="这座洞穴以其中的怪物阿库麦尔命名。这头庞大而堕落的多头蛇在此栖居已久，早已将洞穴据为自己的巢穴。暮光之锤和娜迦敬奉着它，等待它在黑暗中苏醒。",al={"为什么叫aku'mai's lair","aku'mai's lair名称含义","谁给aku'mai's lair命名"}}},fp="14,235,19.521.0,17.489.0,32.158.0,44.209.0,31.127.0,50.184.0"}
P.entries["subzone:aldrassil"] = {n="奥达希尔",s="奥达希尔是位于泰达希尔东北部幽影谷中心地带的巨大枝树和定居点。作为年轻卡多雷的主要避难所和训练场，它那雕琢出的树洞中安置着训练师、商人和当地的领导者。",h="奥达希尔是位于泰达希尔东北部幽影谷中心地带的巨大枝树和定居点。作为年轻卡多雷的主要避难所和训练场，它那雕琢出的树洞中安置着训练师、商人和当地的领导者。",kw={"奥达希尔","巨树","卡多雷","暗夜精灵起始","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="奥达希尔展示了卡多雷对活体建筑的偏好，它们由活木塑形而成，且没有破坏森林的平衡。",["race:NightElf"]="对于许多年轻的卡多雷来说，奥达希尔雕刻出的树洞和坡道是他们对城市生活的第一记忆，也是他们早期训练的基础。"},sec={{t="幽影谷之心",b="奥达希尔高耸于幽影谷僻静的山谷之上，既是年轻暗夜精灵踏入世界第一步时的避难所，也是他们的市政中心。这座古老植被的巨大树干被建筑所环绕，蜿蜒的坡道通向各处的职业训练师和工匠，并最终到达高处的栖木，特纳隆·雷拳就在那里统筹整个幽影谷的防务。当世界之树泰达希尔横跨地平线时，奥达希尔提供了一处安全、稳固的树冠，新手们在此学习技艺，随后才踏入卡利姆多动荡的荒野。"}},faq={{q="奥达希尔是什么？",a="奥达希尔是位于泰达希尔东北部幽影谷中心的一棵巨大的空心树和定居点。它是年轻暗夜精灵聚集在一起获取训练、物资和指导的起始避难所。",al={"奥达希尔树","奥达希尔是什么","幽影谷大树"}},{q="谁领导着奥达希尔的定居点？",a="特纳隆·雷拳从他位于奥达希尔顶端的栖木上统筹幽影谷，协调山谷的防御，并指导新觉醒的卡多雷。",al={"谁领导奥达希尔","奥达希尔领袖","特纳隆·雷拳位置"}},{q="这里有哪些服务？",a="这棵树为年轻的暗夜精灵战士、潜行者、德鲁伊、猎人和牧师提供了职业训练师，此外还有当地的补给商人、护甲商和任务发布者，以满足山谷的直接需求。",al={"奥达希尔的训练师","奥达希尔商人","奥达希尔里有什么"}}},fx={f93f81e4={q="谁住在奥达希尔？",a="奥达希尔是守护、训练并照料幽影谷的暗夜精灵的家园。艾露恩的牧师、德鲁伊、潜行者和战士在树干内部雕出的房间及周围的平台上安居，而幽影谷的首领特纳隆·雷拳则住在树冠之上。",al={"这里住着谁","奥达希尔居民","奥达希尔人口"}},["1582ff91"]={q="奥达希尔危险吗？",a="这棵树本身是安全的庇护所，也是幽影谷繁忙的中心，受到警惕的暗夜精灵哨兵保护。不过，附近的树枝和林地正日益受到逼近的格雷尔、染病的夜刃豹以及潜伏在树荫之外的堕落林地野兽威胁。",al={"奥达希尔安全吗","奥达希尔的危险","奥达希尔有什么危险"}}},fp="9,254,19.549.0,18.215.0,38.156.0,32.205.0"}
P.entries["subzone:alexston-farmstead"] = {n="阿历克斯顿农场",s="阿历克斯顿农场是西部荒野中一座荒废的农场，杂草丛生，到处都是失控的收割守卫。这里曾经是暴风城首席建筑师巴隆斯·阿历克斯顿儿时的家，如今像这片谷仓地区的大部分地方一样，已沦为废墟。",h="阿历克斯顿农场是西部荒野中一座荒废的农场，杂草丛生，到处都是失控的收割守卫。这里曾经是暴风城首席建筑师巴隆斯·阿历克斯顿儿时的家，如今像这片谷仓地区的大部分地方一样，已沦为废墟。",kw={"阿历克斯顿","建筑师","巴隆斯","指南针","农场","收割守卫","西部荒野"},ang={["faction:Alliance"]="这座农场不仅提醒着人们，暴风城那些杰出大脑亦出身于勤劳朴实的根基，也反映了联盟在保护自身边境时所面临的持续斗争。"},sec={{t="衰败的家园",b="阿历克斯顿农场坐落在西部荒野干旱的平原上，是王国疏于治理的又一个惨痛见证。像邻近的地产一样，当乡村地区匪患爆发时，农场的看护人便弃之而去。如今，田地已荒芜，留下来照料庄稼的机械收割守卫也已失控，疯狂地攻击任何靠近这座荒废农舍的人。"},{t="卑微的出身",b="尽管农场现状凄凉，它却与暴风城最显赫的公民之一有着渊源。巴隆斯·阿历克斯顿，那位参与设计了重建后的暴风城部分区域的建筑大师，年轻时曾在这片田地上劳作。他在动荡开始前很久就离开了农场，前往首都从事石匠和建筑行业，只留下了关于他早年生活的一件纪念品，藏在废墟之中。"}},faq={{q="谁拥有阿历克斯顿农场？",a="这座农场以暴风城建筑师巴隆斯·阿历克斯顿的家族命名。巴隆斯年幼时曾在这里耕作，后来前往首都投身于建筑事业。",al={"谁拥有这座农场","阿历克斯顿农场主","这是谁的农场"}},{q="为什么农场会被废弃？",a="像西部荒野的大部分地区一样，该农场是在迪菲亚潜行者引发的大规模动荡和匪患之后被废弃的。由于王国无法提供保护，农民们被迫逃离，任由家园腐朽。",al={"为何废弃","阿历克斯顿农场发生了什么","谁摧毁了农场"}},{q="为什么这里的机械稻草人会攻击人？",a="机械收割守卫最初是被制造出来用于耕作和保护庄稼免受食腐动物侵害的。在农民逃离后，由于无人维护，它们的内部发条装置发生故障，导致它们对任何活着的生物都变得极具攻击性。",al={"为何收割守卫会攻击","敌对的稻草人","收割傀儡敌对"}},{q="农舍里有什么隐藏的东西吗？",a="巴隆斯·阿历克斯顿在农舍里留下了一件他年轻时的个人指南针。在暴风城做事的旅行者有时会被要求从这座荒废的家园中取回它。",al={"这里的任务","农场里的战利品","巴隆斯的物品"}}},fx={["3df1ed7f"]={q="阿历克斯顿农场是什么地方？",a="阿历克斯顿农场是一座位于西部荒野北部的废弃乡间农场。和当地许多农庄一样，它曾为暴风城王国提供粮食，直到无法无天的乱象席卷这片地区。这里也是巴隆斯·阿历克斯顿儿时的家；他年幼时曾在这片田地劳作，后来成为暴风城的城市建筑师。",al={"这是什么地方","阿历克斯顿农场","阿历克斯顿农场简介"}},["10e8b118"]={q="阿历克斯顿农场发生了什么？",a="这片土地曾是一座宁静而富饶的家族农场，后来却遭逢西部荒野的种种祸患。迪菲亚潜行者控制乡野后，农场遭到占据，居民也被迫离开。随着时间推移，原先的工人被失控的收割傀儡取代，农场渐渐荒废，杂草丛生，田地仍处于敌对势力的控制之下。",al={"阿历克斯顿农场历史","阿历克斯顿农场的历史","这里发生了什么"}},["6ef1debd"]={q="阿历克斯顿农场危险吗？",a="危险，旅人经过这处地产时应当格外小心。致命的机械收割傀儡在田间巡逻，一旦有人靠近，这些失控的自动机械就会发动攻击。此外，迪菲亚潜行者仍在这一带活动，敌意十足，因此这座废弃农场对毫无戒备的行人来说并不安全。",al={"这里危险吗","阿历克斯顿农场的威胁","阿历克斯顿农场的怪物"}}},fp="18,240,18.427.0,12.388.0,32.191.0,26.216.0,52.246.0,46.182.0"}
P.entries["subzone:algaz-station"] = {n="奥加兹岗哨",s="奥加兹岗哨是一座位于洛克莫丹西北部的矮人军事哨所，就在丹奥加兹防守严密的关口正南方。哨所的巡山人把守着通往北方隧道的入口，保护过往旅客并监视通往沼泽地的边境。",h="奥加兹岗哨是一座位于洛克莫丹西北部的矮人军事哨所，就在丹奥加兹防守严密的关口正南方。哨所的巡山人把守着通往北方隧道的入口，保护过往旅客并监视通往沼泽地的边境。",kw={"奥加兹岗哨","丹奥加兹","gothor brumn","铁炉堡","洛克莫丹","巡山人卡尔·雷矛","巡山人","北门小径"},ang={["faction:Alliance"]="对于往返于洛克莫丹和北部沼泽地之间的联盟冒险者来说，这座哨所提供了一个安全的集结地和维修站。",["race:Dwarf"]="对于矮人旅行者而言，奥加兹岗哨是铁炉堡势力范围的熟悉标志，确保了国王的公路时刻受到守卫，免受来自山脉威胁的侵扰。"},sec={{t="监视北门小径",b="奥加兹岗哨位于北门小径正东方，丹奥加兹正南方，是铁炉堡王国的关键战略观察点。一队矮人巡山人在此长期驻守，确保洛克莫丹与北方低地之间这条至关重要的道路畅通无阻，以供贸易和军队通行。鉴于周边丘陵地区常有威胁，从游荡的野兽到入侵的穴居人，这里为疲惫的旅人在冒险穿越山间隧道之前提供了休憩、维修和武力支援。"}},faq={{q="奥加兹岗哨是什么地方？",a="这是位于洛克莫丹西北部的一座铁炉堡军事哨所。它作为警卫站和中转站，供巡逻通往丹奥加兹的山口的巡山人使用。",al={"这是什么地方","奥加兹岗哨的用途","谁在管理奥加兹岗哨"}},{q="这个哨所的名字从何而来？",a="它的名字源于丹奥加兹，即位于哨所正北方，连接洛克莫丹与沼泽地的巨大矮人关口和隧道系统。",al={"为什么叫奥加兹岗哨","与丹奥加兹的关系","名字含义"}},{q="谁驻扎在奥加兹岗哨？",a="这座哨所由矮人巡山人把守，其中包括巡山人卡尔·雷矛，以及像护甲商Gothor Brumn这样的后勤人员，他为旅客提供现场维修服务。",al={"谁在这里","奥加兹岗哨的npc","巡山人卡尔·雷矛的位置"}}},fx={c8a5caec={q="奥加兹岗哨危险吗？",a="岗哨本身由警惕的矮人山地巡逻兵驻守，是一处安全的庇护所，但周围的道路危机四伏。岗哨位于丹奥加兹以南、北门小径以东，在此歇脚的旅人仍须提防在洛克莫丹北部游荡的敌对穴居人、野兽和绿皮兽人。",al={"奥加兹岗哨的危险","奥加兹岗哨安全吗","奥加兹岗哨的威胁"}}},fp="13,284,26.539.0,22.180.0,36.153.0,34.178.0"}
P.entries["subzone:altar-of-storms-burning-steppes"] = {n="风暴祭坛 (燃烧平原)",s="风暴祭坛坐落在燃烧平原的锯齿状山崖中，是一座专门用于邪能仪式和恶魔之力的黑暗纪念碑。黑石氏族的术士们占据了这个险恶之地，在黑石塔的阴影下施展邪恶魔法。它散发的黑暗光环吸引了来自艾泽拉斯各地的暗影法术追求者。",h="风暴祭坛坐落在燃烧平原的锯齿状山崖中，是一座专门用于邪能仪式和恶魔之力的黑暗纪念碑。黑石氏族的术士们占据了这个险恶之地，在黑石塔的阴影下施展邪恶魔法。它散发的黑暗光环吸引了来自艾泽拉斯各地的暗影法术追求者。",kw={"风暴祭坛","黑石","燃烧平原","邪能","gorzeeki wildeyes","mor'zul bloodbringer","术士"},ang={["class:Warlock"]="风暴祭坛及其附近的隐士Mor'zul Bloodbringer和Gorzeeki Wildeyes，是术士们寻找召唤恐惧战马所需材料和仪式的关键渠道。",["race:Orc"]="这座祭坛令人不快地提醒着人们旧部落的黑暗历史，当时古尔丹的暗影议会使用类似的邪恶神龛，将黑暗巫术注入食人魔和士兵体内。"},sec={{t="阴影与火焰的遗产",b="风暴祭坛建于早期的战争期间，用于引导腐蚀性的邪能魔法，它是一座黑暗契约的阴森纪念碑。在燃烧平原，充满敌意的黑石氏族术士控制着这片土地，进行神秘的仪式并汲取恶魔力量。附近，隐士Gorzeeki Wildeyes和他的导师Mor'zul Bloodbringer的营地俯瞰着这里，叛逆的修行者们研究着其狂暴的能量，并为寻求更强大黑暗力量的野心勃勃的施法者们调制高难度的仪式。"}},faq={{q="风暴祭坛是什么？",a="这是一座被腐蚀的石质纪念碑，用于黑暗邪能仪式和引导恶魔能量。它建于旧部落战争时期，至今仍是黑石术士利用黑暗力量的核心枢纽。",al={"风暴祭坛背景故事","这个祭坛是什么","燃烧平原祭坛"}},{q="现在是谁控制着这座祭坛？",a="属于黑石兽人氏族的敌对术士和侍僧占据了祭坛周围的区域，执行黑暗仪式并守卫着该地点，抵御入侵者。",al={"风暴祭坛里有什么人","风暴祭坛的敌人","谁住在这里"}},{q="Gorzeeki Wildeyes是谁？",a="Gorzeeki Wildeyes是一位古怪的黑暗艺术地精学者，他和他的导师Mor'zul Bloodbringer一起住在俯瞰祭坛的山丘上。他协助那些寻求掌握更强大恶魔契约的强大术士。",al={"gorzeeki wildeyes","山上的兽人","gorzeeki是谁"}}},fp="33,324,28.524.0,28.203.0,33.181.0,25.235.0"}
P.entries["subzone:alterac-mountains"] = {n="奥特兰克山脉",s="奥特兰克山脉是一片崎岖的雪冠山岭，耸立在希尔斯布莱德那连绵起伏的牧场之上。这里曾是一个骄傲的人类王国的核心，如今山坡上只剩下废弃的定居点、强盗派系和危险的荒野，鲜有旅客敢于在无人护卫的情况下踏足此地。",h="奥特兰克山脉是一片崎岖的雪冠山岭，耸立在希尔斯布莱德那连绵起伏的牧场之上。这里曾是一个骄傲的人类王国的核心，如今山坡上只剩下废弃的定居点、强盗派系和危险的荒野，鲜有旅客敢于在无人护卫的情况下踏足此地。",kw={"奥特兰克","石拳","希尔斯布莱德","山脉","匹瑞诺德","斯坦恩布莱德","辛迪加"},ang={["class:Rogue"]="山口充满了辛迪加特工和雇佣来的杀手，使这些山丘成为了考验生存能力和反间谍能力的绝佳场所。",["faction:Alliance"]="对于联盟而言，奥特兰克是背叛带来的痛苦纪念碑，匹瑞诺德的背信弃义在第二次战争中险些将人类推入毁灭的深渊。"},sec={{t="一个陨落的王国",b="在这些山丘陷入混乱的很久以前，这些高地组成了奥特兰克这个主权国家，它是源自古老阿拉索的七个王国之一。然而，这一遗产在第二次战争中破碎了，当时奥特兰克国王艾登·匹瑞诺德与旧部落达成了秘密协议，允许兽人军队穿过山峰，以换取其王国的安全。洛丹伦联盟发现了这场背叛并废黜了匹瑞诺德，使得该地区陷入了军事管制和领土争端的破碎状态。"},{t="荒野与强盗",b="第三次战争的浩劫过后，群山完全陷入了无法无天的境地。该国被剥夺了继承权的贵族们结成辛迪加，以斯坦恩布莱德的废墟为基地，企图通过破坏和暗杀夺回他们失去的领土。在占据着破碎首都的残暴石拳食人魔、四处劫掠的豺狼人，以及达拉然周围破碎的魔法废墟之间，奥特兰克的山径依然是洛丹伦最危险的通路之一。"}},faq={{q="过去是哪个王国统治这些山脉的？",a="在阿拉索帝国分裂后，奥特兰克人类王国统治了这些山脉数代之久。它的首都坐落在最高峰之间，扼守着通往洛丹伦、达拉然和阿拉希高地的道路，直到其在第二次战争中陨落。",al={"谁拥有奥特兰克","奥特兰克是什么","奥特兰克王国历史"}},{q="奥特兰克为何沦为废墟？",a="在第二次战争期间，奥特兰克国王艾登·匹瑞诺德通过协助部落背叛了洛丹伦联盟。当叛国罪行败露后，联盟军队摧毁了奥特兰克的军队并废黜了王室。由于没有了合法统治者，加上随后第三次战争的破坏，这个国家最终坍塌成了一片废墟。",al={"奥特兰克发生了什么","谁摧毁了奥特兰克","奥特兰克废墟背景故事"}},{q="潜伏在山丘中的辛迪加是什么人？",a="辛迪加是一个由前奥特兰克贵族及其仆从组成的法外组织。在艾登·匹瑞诺德的领导下，他们雇佣强盗、刺客和流氓雇佣兵来破坏该地区的局势，企图通过暴力手段复辟他们的王国。",al={"谁是辛迪加","辛迪加是什么","为什么奥特兰克有强盗"}},{q="什么威胁游荡在雪峰之上？",a="勇敢攀登山坡的旅客必须与残暴的石拳食人魔、成群的高地豺狼人、拾荒的狗头人以及巡逻在山径上的投机取巧的辛迪加强盗周旋。",al={"奥特兰克有什么生物","奥特兰克怪物","奥特兰克的威胁"}}},fx={e4635e9a={q="奥特兰克山脉是什么地方？",a="奥特兰克山脉是一片崎岖、终年积雪的山脉，横亘在洛丹伦中部，位于希尔斯布莱德丘陵以北。这里曾是人类王国奥特兰克的领土，山上遍布设防的城市、山间要塞和偏远山谷。如今王国已分崩离析，城镇在风雪中化为废墟，冰封的山峰成了残余流亡者、交战部族和掠食怪物的战场。",al={"奥特兰克山脉是什么","奥特兰克山脉传说","奥特兰克地区概况"}},["858b3945"]={q="如今谁统治奥特兰克山脉？",a="没有合法政权统治奥特兰克山脉。奥特兰克王国在第二次战争中背叛盟友后覆灭，天灾军团的进攻又扫荡了残存的秩序。如今，辛迪加——由佩瑞诺德家族后裔领导、失去领地的人类贵族和亡命之徒——声称对这些废墟拥有祖传权利。然而，他们还在与凶残的碎脊食人魔、四处游荡的亡灵，以及盘踞在高山山谷中的霜狼兽人激烈争斗。",al={"谁控制奥特兰克","谁住在奥特兰克山脉","奥特兰克的领导者"}}},fp="17,274,14.492.0,22.502.0,42.266.0,24.302.0,43.246.0,36.195.0"}
P.entries["subzone:alterac-mountains-classic"] = {n="Alterac Mountains (Classic)",s="奥特兰克山脉是一片崎岖、阴云密布的高地，位于希尔斯布莱德丘陵的北面，地势陡峭，终年积雪，山峰险峻。这里曾经是人类王国奥特兰克和学术圣地达拉然的所在地，如今大部分地区已沦为废墟，残暴的Crushridge食人魔、贵族出身的强盗以及奥特兰克山谷的敌对军队在此争斗不休。",h="奥特兰克山脉是一片崎岖、阴云密布的高地，位于希尔斯布莱德丘陵的北面，地势陡峭，终年积雪，山峰险峻。这里曾经是人类王国奥特兰克和学术圣地达拉然的所在地，如今大部分地区已沦为废墟，残暴的Crushridge食人魔、贵族出身的...",kw={"奥特兰克山脉","奥特兰克山谷","crushridge食人魔","达拉然","洛丹米尔","奥特兰克废墟","斯坦恩布莱德","syndicate","高地"},ang={["class:Rogue"]="在边境一个僻静的山谷中坐落着拉文霍德庄园，这是由乔拉齐·拉文霍德公爵领导的盗贼和刺客公会的历史总部。",["faction:Alliance"]="联盟在哈格丁中尉的带领下在这些冰冷的丘陵中维持着一个前哨站，招募坚定的战士以增援奥特兰克山谷中的雷矛卫队。"},sec={{t="破碎的高地",b="奥特兰克山脉耸立在希尔斯布莱德低地之上，是一片充斥着雨水、松树和高海拔积雪的严酷之地。这里曾经由三大主要人类势力所主导——奥特兰克山王国、魔法王国达拉然以及坚固的城镇斯坦恩布莱德，但后来由于背叛和战争，这一地区分崩离析。如今，奥特兰克的废墟首都被Crushridge食人魔盘踞，斯坦恩布莱德被不法之徒占据，而在达拉然的残垣断壁中，幸存的法师们正不知疲倦地试图修复他们毁灭的圣所。"},{t="强盗、野兽与战争",b="除了在冻伤的山脊上潜伏的本地山狮和雪人之外，这片高地还被绝望的凡人派系所争夺。Syndicate——由失去土地的落魄人类贵族转变成的强盗——在旧庄园和山麓营地中挥舞着利刃，不断伏击并与入侵的食人魔发生冲突。与此同时，通往高耸山峰的深谷成为了雷矛远征军和霜狼氏族之间为了争夺奥特兰克山谷隐秘区域而展开的血腥战争的集结地。"}},faq={{q="奥特兰克王国发生了什么？",a="奥特兰克在第二次战争期间陷入了耻辱，当时它的统治者，国王Aiden Perenolde，背叛了联盟并协助部落。战争结束后，该王国被解散。由于缺乏领导，它的城市土崩瓦解，斯坦恩布莱德沦为废墟，而它的首都则被残暴的Crushridge食人魔所占领。",al={"奥特兰克为何沦为废墟","谁统治奥特兰克","奥特兰克的陨落"}},{q="山里的Syndicate强盗是谁？",a="Syndicate是一个由前奥特兰克贵族及其随从组成的不法组织。在奥特兰克背叛后，他们失去了土地、地位和财富，为了夺回他们认为属于自己的土地，他们开始从事间谍、暗杀和公路抢劫活动。",al={"syndicate是什么","奥特兰克为何有盗贼","奥特兰克强盗"}},{q="湖岸边巨大的紫色圆顶是什么？",a="今天达拉然上方没有圆顶。在第三次战争期间，这座城市被恶魔领主Archimonde夷为平地后，幸存的肯瑞托法师在废墟上竖起了一道紫色的护盾，但他们在重建早期就将其移除了，现在他们正在空地上重建他们那被毁坏的塔楼。",al={"奥特兰克的紫色泡泡","什么是达拉然圆顶","达拉然魔法护盾"}},{q="如何前往奥特兰克山脉？",a="旅行者通常从希尔斯布莱德丘陵步行进入，沿着塔伦米尔北部的道路或南海镇北部的道路前行。或者，大胆的游泳者可以从银松森林的岸边或Undercity的郊区向东南横跨洛丹米尔湖。",al={"如何前往奥特兰克","奥特兰克入口","通往奥特兰克的道路"}}},fp="27,359,20.533.0,24.503.0,40.308.0,47.304.0,50.280.0,35.283.0"}
P.entries["subzone:alther-s-mill"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是一座破败的伐木场，坐落在赤脊山中，位于湖畔镇东北方向崎岖的山丘之间。这里曾是当地建筑商极为重要的木材来源，但在被废弃后，这里已沦为各种野兽和掠食者的巢穴。对于前往石堡方向的冒险者来说，这些破旧的建筑是标志着安全边境终点的阴森地标。",h="奥瑟尔伐木场是一座破败的伐木场，坐落在赤脊山中，位于湖畔镇东北方向崎岖的山丘之间。这里曾是当地建筑商极为重要的木材来源，但在被废弃后，这里已沦为各种野兽和掠食者的巢穴。对于前往石堡方向的冒险者来说，这些破旧的建筑是标志着...",kw={"奥瑟尔伐木场","湖畔镇","开锁","伐木场","赤脊山","蜘蛛","石堡"},ang={["class:Rogue"]="联盟的恶棍们很熟悉奥瑟尔伐木场，因为盗贼组织将伐木场里散落的遗忘储物箱和偏僻的场地当作静谧的训练场，用来练习精细的开锁技术。",["faction:Alliance"]="这座废弃的伐木场是暴风城边境驻军捉襟见肘的又一个鲜明写照，宝贵的工业设施就这样在湖畔镇的眼皮底下破败荒废。"},sec={{t="一座被遗弃的边境伐木场",b="在赤脊山遭到掠食者入侵和兽人袭击之前，奥瑟尔伐木场曾因木材贸易而熙熙攘攘，为湖畔镇及周边定居点的建设提供了充足的原材料。它坐落在止水湖东北方向一片安静的林地中，便于就近获取山区的木材资源。随着暴风城王国内动荡加剧，黑石氏族从石堡高地南下，当地的伐木工被迫放弃了这里，任由干枯的木质建筑和水车逐渐腐朽。"},{t="阴影与残骸",b="随着人类工人的离去，伐木场里开始滋生巨大的狼蛛、食腐秃鹫和投机取巧的掠夺者。穿越这里前往东部山口的旅人必须小心翼翼地绕开它那阴暗的边缘。近年来，一些暗影中的不法分子和小偷也利用这座废弃的营地，将废弃的储物箱和隐蔽的角落作为练习非法开锁技巧和秘密交易的场所，以此避开湖畔镇守卫的耳目。"}},faq={{q="什么是奥瑟尔伐木场？",a="奥瑟尔伐木场是一座位于赤脊山，湖畔镇东北方向的废弃伐木场。它曾为周边定居点砍伐和加工木材，直到日益严重的野外威胁迫使其被废弃。",al={"奥瑟尔伐木场","这是什么地方","奥瑟尔伐木场过去是什么"}},{q="为什么伐木场会被废弃？",a="随着第一次和第二次战争后区域防御力量的减弱，巨大的蜘蛛等凶猛野兽以及黑石兽人的入侵，使得边境作业对于普通劳工而言变得过于危险，如果没有皇家军队的保护已无法维持。",al={"为什么被废弃","谁废弃了奥瑟尔伐木场","伐木工发生了什么"}},{q="什么生物会在伐木场附近徘徊？",a="伐木场地面及周围的灌木丛中主要盘踞着巨大的山地狼蛛、食腐秃鹫和游荡的掠食者，还有在石堡和止水湖之间往来的流窜强盗。",al={"奥瑟尔伐木场的敌人","伐木场的生物","这里有什么生物"}},{q="为什么潜行者要来奥瑟尔伐木场？",a="这里偏僻且堆满杂物的环境使其成为联盟潜行者理想的练习场，他们的训练师会指引他们到这里练习开启锁住的步兵箱，并获取宝贵的盗贼认证。",al={"潜行者伐木场任务","奥瑟尔伐木场开锁","盗贼认证"}}},fx={f58217b4={q="奥瑟尔伐木场发生了什么？",a="奥瑟尔伐木场曾是为暴风城王国和赤脊山居民服务的活跃伐木场。随着这一地区日益孤立，并受到敌对野生动物和从山中入侵的兽人威胁，伐木场逐渐脱离人类掌控。工人弃场而去后，这里最终被野兽、四处游荡的拾荒者，以及途经此地前往石堡要塞的零散兽人占据。",al={"奥瑟尔伐木场历史","奥瑟尔伐木场发生了什么","奥瑟尔伐木场的历史"}}},fp="13,425,26.491.0,17.485.0,22.230.0,26.247.0,36.205.0,34.215.0"}
P.entries["subzone:ambermill"] = {n="安伯米尔",s="安伯米尔是位于银松森林东南部的一座加固人类定居点，坐落在洛丹米尔湖的西南方。这里曾经是一个安静的伐木村庄，如今被达拉然的幸存法师和学徒占据。他们的存在构成了被遗忘者疆域南部边境上一个危险的人类反抗前哨。",h="安伯米尔是位于银松森林东南部的一座加固人类定居点，坐落在洛丹米尔湖的西南方。这里曾经是一个安静的伐木村庄，如今被达拉然的幸存法师和学徒占据。他们的存在构成了被遗忘者疆域南部边境上一个危险的人类反抗前哨。",kw={"安伯米尔","达拉然","肯瑞托","魔网","暗影牧师奥利斯特","银松森林"},ang={["class:Mage"]="这个定居点证明了肯瑞托在天灾军团和燃烧军团摧毁达拉然之后，试图恢复其影响力的努力。",["faction:Horde"]="对于被遗忘者的特工来说，安伯米尔是银松森林中仅存的少数人类反抗据点之一，它威胁着南部的后勤补给，并藏有危险的奥术秘密。"},sec={{t="达拉然的堡垒",b="第三次战争前，安伯米尔只是一个无足轻重的安静伐木小镇。在洛丹伦陷落后的混乱时期，肯瑞托的幸存法师们迁入并加固了该定居点。达拉然的法术抄写员、咒术师和学徒们如今巡视着这里的建筑和马厩，将安伯米尔用作对抗亡灵的前沿堡垒。"},{t="汲取魔网能量",b="肯瑞托对安伯米尔的兴趣远不止于简单的领土防御。这个村庄直接坐落在一个休眠的魔网能量节点之上。监视该镇的被遗忘者间谍和死亡猎手发现，达拉然的法师们正试图重新激活这个枢纽，以进行大规模的奥术工作。如果成功，涌动的魔法力量可能会威胁到被遗忘者对银松森林那脆弱的控制，从而促使暗影牧师奥利斯特和死亡猎手们在磨坊各处策划破坏活动、窃取肯瑞托文件并执行暗杀行动。"}},faq={{q="为什么达拉然的法师要占据银松森林的一个村庄？",a="在第三次战争中达拉然遭到毁灭后，幸存的肯瑞托部队迁入安伯米尔，建立了一个人类反抗军的前哨。被遗忘者的特工们正在调查他们的活动。",al={"为什么法师在这里","谁控制着安伯米尔","肯瑞托 银松森林"}},{q="安伯米尔一直是达拉然的一部分吗？",a="不。在第三次战争前，安伯米尔只是一个微不足道的伐木村庄。达拉然的法师是在天灾军团攻陷洛丹伦之后才迁入并将其加固的。",al={"安伯米尔历史","谁拥有安伯米尔"}},{q="为什么被遗忘者想要攻击安伯米尔？",a="安伯米尔是银松森林中一个加固的人类反抗中心。被遗忘者将这里得到达拉然支持的部队及其秘密奥术工作视为对自己该地区统治的威胁。",al={"被遗忘者 安伯米尔","为什么要杀掉安伯米尔的法师"}},{q="死亡猎手在安伯米尔搜寻什么？",a="被遗忘者的死亡猎手从俘虏的人类囚犯口中得知，安伯米尔的法师们保存着详细记录达拉然秘密计划和军事意图的机密文件，这使得该定居点成为了秘密渗透和窃取行动的首要目标。",al={"安伯米尔文件","mennet carkad 安伯米尔"}}},fx={["9833b496"]={q="安伯米尔是什么地方？",a="安伯米尔是一座设有防御工事的人类聚居地，坐落在银松森林东南部的丘陵中，位于洛丹米尔湖西南方。它最初是一处宁静的伐木前哨，设有市政厅、马厩和磨坊，如今已被改建成戒备森严的军事与魔法营地。施法者和守卫严守外围，镇中的建筑也因奥术能量而嗡鸣不止。",al={"安伯米尔是什么地方","安伯米尔概况","介绍一下安伯米尔"}},c529bf0b={q="安伯米尔发生了什么？",a="第三次战争前，安伯米尔只是一座不太起眼的宁静伐木镇。第三次战争期间，天灾军团蹂躏了这一地区，并摧毁了达拉然；随后，幸存的肯瑞托部队进驻并加固了这座城镇，以便在银松森林保住一个战略据点。",al={"安伯米尔历史","安伯米尔背景","安伯米尔的历史"}},fc63f553={q="谁住在安伯米尔？",a="安伯米尔完全由来自达拉然的肯瑞托人员占据和管理。达拉然守护者、召唤出的奥术蛇、学徒和铭文师在镇中巡逻，高阶召唤师则在市政厅及周围建筑内主持魔法行动。当地的服务人员，例如裁缝Avelina Lilly，也曾为这里的法师提供物资和衣物。",al={"谁控制安伯米尔","安伯米尔居民","安伯米尔有哪些人"}},b9a41d98={q="安伯米尔危险吗？",a="对于被遗忘者或部落一方的人来说，安伯米尔极其危险。驻扎在此的肯瑞托部队将亡灵视为生死大敌，会一见擅闯者便发动攻击。除了武装哨兵，这处聚居地还有技艺高超的施法者守卫，他们会施展强大的攻击性魔法，召唤奥术防护结界和蛇形仆从，将入侵者彻底消灭。",al={"安伯米尔有敌意吗","安伯米尔的危险","安伯米尔安全吗"}}},fp="9,329,20.345.0,21.569.1,58.210.0,37.154.0,45.186.0,54.245.0"}
P.entries["subzone:amberstill-ranch"] = {n="冻石农场",s="冻石农场是一处宁静的矮人宅邸，坐落在通往洛克莫丹的雪道旁，位于古博拉采掘场的正北方。这里是铁炉堡著名的山羊的主要繁育与训练基地。冒险者们来到农场购买坚韧的矮人坐骑、学习骑术，或是帮助这个家庭保护它们的牲畜免受当地掠食者的侵害。",h="冻石农场是一处宁静的矮人宅邸，坐落在通往洛克莫丹的雪道旁，位于古博拉采掘场的正北方。这里是铁炉堡著名的山羊的主要繁育与训练基地。冒险者们来到农场购买坚韧的矮人坐骑、学习骑术，或是帮助这个家庭保护它们的牲畜免受当地掠食者的...",kw={"冻石","坐骑商人","山羊","农场","骑术训练师","雪靴兔","瓦加什","雅琳"},ang={["faction:Alliance"]="冻石家族培育出的强壮山羊为联盟提供了可靠的寒带骑兵，非常适合在崎岖的山地地形中作战。",["race:Dwarf"]="对于矮人冒险者来说，这里是一个值得骄傲的文化基石，年轻的英雄们可以在此获得他们的第一只巴拉克·托尔山羊坐骑。"},sec={{t="山羊的家园",b="冻石农场坐落于丹莫罗的岩架旁，因培育出东部王国中最强壮的山羊而在卡兹莫丹享有盛誉。冻石家族经营着这里的马厩和围场，训练这些步履稳健的野兽在险峻的雪道和陡峭的高山悬崖上穿行。除了提供骑乘坐骑和家养牲畜外，这个家族还经常要应对山丘中凶猛的野兽，尤其是被新鲜兽群的气味吸引而来的游荡温迪戈。"}},faq={{q="冻石农场因何出名？",a="该农场是联盟繁育巴拉克·托尔山羊的中心枢纽。矮人和受人尊敬的联盟勇士来到这里，学习山羊骑术并向当地的马厩管理员购买坐骑。",al={"冻石农场用途","为什么访问冻石农场","冻石山羊"}},{q="非矮人种族可以在这里购买坐骑吗？",a="按照传统，山羊是专门为那些了解其固执脾性的矮人骑手准备的。其他联盟种族的成员只有在赢得了铁炉堡的绝对信任并获得崇拜声望后，才能学习骑术并购买它们。",al={"非矮人购买山羊","人类购买山羊","山羊坐骑要求"}},{q="农场面临哪些威胁？",a="兽群不断受到从冰冻悬崖上下来的饥饿温迪戈的威胁。在周边高地徘徊的最臭名昭著的掠食者是瓦加什，这是一只经常袭击脆弱牲畜的巨大温迪戈。",al={"冻石农场危险","温迪戈威胁","瓦加什任务"}},{q="在农场还能获得其他东西吗？",a="年轻的雅琳·冻石饲养了一群家养雪靴兔，并乐意将装在笼子里的兔子卖给那些在旅途中寻找宠物伙伴的旅行者。",al={"冻石兔子","雪靴兔宠物","雅琳·冻石"}}},fx={["0dde8a5d"]={q="冻石农场是什么地方？",a="冻石农场是一处矮人家园和饲养场，坐落在丹莫罗东部的丘陵中，位于古博拉采掘场以北。这里是主要的马厩，专门饲养矮人十分珍视的坚韧山羊；铁炉堡的矮人将它们视为在卡兹莫丹崎岖地形中可靠的坐骑。",al={"冻石农场是什么地方","冻石农场的用途"}},f9ed26f9={q="谁住在冻石农场？",a="冻石家族住在这座农场，负责繁育、照料和训练丹莫罗著名的山羊。家族成员管理马厩，出售雪兔等本地宠物，也为赢得铁炉堡深厚信任的人提供骑术指导。",al={"谁管理冻石农场","冻石农场居民","这里住着谁"}},["1facab92"]={q="冻石农场危险吗？",a="农场本身是联盟的安全据点，但周边地区危机四伏。附近的雪坡上有凶猛的野兽出没，当地饲养者最惧怕的莫过于会捕食牲畜的巨大温迪戈瓦加什。",al={"冻石农场的危险","冻石农场安全吗","冻石农场的危险因素"}}},fp="16,374,25.495.0,35.200.0,37.240.0,33.228.0,42.163.0"}
P.entries["subzone:ameth-aran"] = {n="亚米萨兰",s="亚米萨兰是黑海岸南部的一处古代遗迹，曾经是一座繁荣的城市，艾萨拉女王的在上层精灵在这里研习奥术魔法。当大分裂摧毁了古代世界时，这座城市也随之覆灭。如今，其残破的柱廊徘徊着在此丧生的精灵的复仇之魂。",h="亚米萨兰是黑海岸南部的一处古代遗迹，曾经是一座繁荣的城市，艾萨拉女王的在上层精灵在这里研习奥术魔法。当大分裂摧毁了古代世界时，这座城市也随之覆灭。如今，其残破的柱廊徘徊着在此丧生的精灵的复仇之魂。",kw={"亚米萨兰","阿奈雅·晨行者","阿斯利库斯·纳拉辛","巴莎兰","塞瑞利恩·白爪","黑海岸","上层精灵","坦莎·月刃"},ang={["class:Druid"]="德鲁伊将这些遗迹视为黑海岸上一道未愈合的伤疤，折磨的灵魂滞留于此，扰乱了荒野的自然平衡。",["race:NightElf"]="对于暗夜精灵来说，亚米萨兰是导致大分裂的上层精灵阶级的傲慢与背叛的冷酷纪念碑。"},sec={{t="法师之城",b="在大分裂之前，亚米萨兰及其姊妹定居点巴莎兰是古代海岸线上上层精灵影响力的双子中心。在艾萨拉女王的恩宠下，统治阶级致力于毫无节制的奥术实验。这座城市在奥萨拉克斯之塔的法师阿斯利库斯·纳拉辛的遥控下繁荣发展，直到永恒之井灾难性的崩塌撕裂了卡多雷帝国。"},{t="背叛与永恒的折磨",b="当世界开始分崩离析时，阿斯利库斯·纳拉辛回到了亚米萨兰，承诺用强大的护盾魔法拯救惊恐的臣民。然而法师并没有保护他们，反而实施了可怕的背叛，以赋予他们永恒保存为残酷幌子，窃取了他们的生命力来供养自己的灵魂宝石。亚米萨兰因大灾变和黑暗魔法而破碎。如今，它的土地上游荡着痛苦的上层精灵幽灵，在他们被谋杀的一万年后仍无法安息。"}},faq={{q="亚米萨兰发生了什么？",a="亚米萨兰在卡多雷帝国的最后日子里就已经是一片废墟，它在一万年前的大分裂中，随着永恒之井的破碎而被摧毁。遗迹中至今徘徊着在此丧生的上层精灵的灵魂。",al={"亚米萨兰为何成为废墟","亚米萨兰历史","亚米萨兰的陷落"}},{q="游荡在遗迹里的幽灵是谁？",a="它们是在大分裂前居住在这座城市并研习奥术魔法的上层精灵的躁动灵魂。由于无法安息，它们在痛苦和愤怒中徘徊在破碎的石块之间。",al={"亚米萨兰的幽灵","亚米萨兰的亡魂","黑海岸的上层精灵幽灵"}},{q="阿奈雅·晨行者是谁？",a="阿奈雅·晨行者是亚米萨兰的居民，也是塞瑞利恩·白爪的爱人。她在分裂期间城市陷落时丧生，她的灵魂一直被束缚在遗迹中，直到塞瑞利恩寻求外援最终让她的灵魂得到解脱。",al={"阿奈雅·晨行者","塞瑞利恩的爱人","亚米萨兰的迷失之爱"}},{q="遗迹中发现的石板是什么？",a="遗迹中刻有记载亚米萨兰历史及其陷落经过的古代石板。哨兵坦莎·月刃曾试图解读它们以便向塞纳里奥议会提交一份历史报告，但敌对的幽灵迫使她只能依靠过往的旅行者。",al={"亚米萨兰石板","亚米萨兰的符文石","亚米萨兰陷落的石板"}}},fx={["5cae2414"]={q="亚米萨兰是什么地方？",a="亚米萨兰是位于黑海岸南部的一处暗夜精灵古代废墟，地处奥伯丁东南方。大分裂之前，它曾与巴莎兰并称宏伟的双子城；艾萨拉女王最宠爱的上层精灵曾在此钻研奥术。",al={"亚米萨兰是什么地方","亚米萨兰简介","亚米萨兰废墟"}},bf7a1160={q="亚米萨兰为什么成了废墟？",a="一万年前，永恒之井爆炸，大分裂撕裂了古卡多雷世界，亚米萨兰也在那场灾难中沦陷。如今，这片残破的聚居地仍被不得安息的上层精灵灵魂所萦绕。",al={"亚米萨兰为何被毁","亚米萨兰如何沦为废墟","亚米萨兰的沦陷"}},["1468cad3"]={q="亚米萨兰危险吗？",a="是的。这些废墟被躁动不安的上层精灵鬼魂所纠缠，它们会猛烈地保护昔日的家园，抵御生者。哨兵斥候泰莎·月刃等人曾被它们的怒火赶走；任何想要寻找古代石板的旅人，都必须小心应对这些幽灵般的幻影。",al={"亚米萨兰安全吗","亚米萨兰危险吗","亚米萨兰有哪些威胁"}}},fp="10,301,19.452.0,28.517.1,28.254.0,39.209.0,25.251.1,46.276.0"}
P.entries["subzone:andorhal"] = {n="Andorhal",s="Andorhal曾经是洛丹伦北部繁荣的农业中心，在第三次战争期间，它成为了王国毁灭的中心。克尔苏加德正是在这里用亡灵瘟疫污染了谷物，将恐怖散布到了整个地区。如今，这座破败的城镇仍牢牢地掌握在天灾军团的铁腕统治之下。",h="Andorhal曾经是洛丹伦北部繁荣的农业中心，在第三次战争期间，它成为了王国毁灭的中心。克尔苏加德正是在这里用亡灵瘟疫污染了谷物，将恐怖散布到了整个地区。如今，这座破败的城镇仍牢牢地掌握在天灾军团的铁腕统治之下。",kw={"andorhal","谷物","粮仓","克尔苏加德","瘟疫之地","天灾军团","乌瑟尔"},ang={["class:Paladin"]="Andorhal是一片被白银之手鲜血浸染的神圣土地；乌瑟尔·光明使者和他的忠诚骑士们正是在这里对阿尔萨斯进行了悲剧性的最后抵抗。",["race:Undead"]="对于被遗忘者来说，Andorhal的田野是对他们起源的痛苦提醒，这里标志着The Cult of the Damned策划终结他们凡人生命的地方。"},sec={{t="瘟疫的中心",b="在第三次战争之前，Andorhal是东威尔德繁荣的粮仓，它收集来自整个洛丹伦的谷物，并将其向东分发到壁炉谷和斯坦索姆。正是因为这种庞大的分销网络，克尔苏加德和The Cult of the Damned选择了Andorhal作为他们恐怖阴谋的舞台。通过用亡灵瘟疫污染谷物箱，教派将王国的粮仓变成了坏死的引擎，在王室意识到威胁之前，无数公民就已经被感染了。"},{t="白银之手的覆灭",b="阿尔萨斯·米奈希尔王子和Jaina Proudmoore最初在这里对抗并杀死了克尔苏加德，但这名通灵师的死亡并非终点。当阿尔萨斯作为天灾军团的勇士从诺森德归来时，他进军回到Andorhal夺回了克尔苏加德的遗骸。乌瑟尔·光明使者和白银之手的残部为了保卫泰瑞纳斯国王的骨灰盒，进行了绝望的最后抵抗。圣骑士们被击溃，乌瑟尔被他曾经的学生杀害，这座伟大的定居点也沦为了一片被枯萎病笼罩的天灾据点。"}},faq={{q="为什么Andorhal在瘟疫的历史中如此重要？",a="Andorhal是洛丹伦北部主要的农业分销枢纽。克尔苏加德利用了这条供应链，用亡灵瘟疫侵染了粮仓，并将受到污染的收成沿着国王之路直接运往斯坦索姆和周边城镇。",al={"瘟疫是如何在这里开始的","安多哈尔谷物瘟疫","为什么andorhal很重要"}},{q="现在是谁控制着Andorhal？",a="不死的天灾军团牢牢控制着安多哈尔废墟。骷髅哨兵、通灵师和食尸鬼在焦黑的街道上游荡，守卫着他们在西瘟疫之地最初胜利的震中。",al={"谁统治着andorhal","andorhal的天灾军团","谁负责andorhal"}},{q="乌瑟尔·光明使者死在这里吗？",a="是的。在洛丹伦王城陷落后，乌瑟尔和他的圣骑士们在Andorhal郊外保护着装有泰瑞纳斯国王骨灰的瓮。阿尔萨斯袭击了护送队伍以夺取骨灰瓮来存放克尔苏加德的遗骸，最终在路上与他的导师决斗并将其杀害。",al={"乌瑟尔在哪里去世","乌瑟尔在andorhal的死亡","阿尔萨斯在这里杀了乌瑟尔吗"}}},fp="8,321,25.521.0,27.529.0,53.272.0,32.206.0,36.273.0"}
P.entries["subzone:angerfang-encampment"] = {n="怒牙营地",s="怒牙营地是龙喉氏族在湿地中部的主要据点。在酋长纳克罗什·碎颅的领导下，这些叛乱的兽人将这座庞大的营地作为进攻基地，以此威胁附近的矮人定居点，并策划摧毁米奈希尔港。",h="怒牙营地是龙喉氏族在湿地中部的主要据点。在酋长纳克罗什·碎颅的领导下，这些叛乱的兽人将这座庞大的营地作为进攻基地，以此威胁附近的矮人定居点，并策划摧毁米奈希尔港。",kw={"怒牙营地","龙喉氏族","米奈希尔港","纳克罗什","碎颅","斯托菲","湿地","维尔加"},ang={["class:Warlock"]="营地内的黑暗影卫携带着导能魔棒，这是完成《卡巴尔法典》所记载的契约所必需的器物。",["faction:Alliance"]="对于米奈希尔港的守卫者而言，怒牙营地是一个明显且迫在眉睫的威胁；摧毁纳克罗什的战旗并取下他的头颅，对于保卫沿海贸易路线至关重要。"},sec={{t="沼泽中的堡垒",b="怒牙营地坐落在湿地中部的泥沼之中，是龙喉氏族在该地区势力的堡垒核心。与那些在沼泽中游荡的零散劫掠小队不同，这个营地拥有防御严密的栅栏、岗哨，以及一支由战士、白骨卫士和效忠旧传统的黑暗施法者组成的强大军队。从这里开始，龙喉氏族向整个沼泽地投射军事力量，沿路劫掠旅行者，并威胁附近的矮人挖掘场，如维尔加挖掘场。"},{t="纳克罗什的野心",b="该营地由酋长纳克罗什·碎颅指挥，他是臭名昭著的术士耐克鲁斯之子，后者曾于格瑞姆巴托奴役了红龙军团。纳克罗什怀着对联盟的刻骨仇恨，集结了投石车并竖起了战旗，准备对米奈希尔港发动全面进攻。联盟在港口城市的指挥官察觉到了这场迫在眉睫的围攻，派遣勇士深入怒牙营地内部，夺取他们的战旗，摧毁他们的战争机器，并取得纳克罗什的头颅，以防他的攻势将港口淹没在火海之中。"}},faq={{q="谁统治着怒牙营地？",a="该营地由酋长纳克罗什·碎颅统治，他是臭名昭著的龙喉氏族术士耐克鲁斯·碎颅之子。纳克罗什在营地深处的指挥帐篷内指挥着区域性的劫掠小队，并策划着对米奈希尔港的征服。",al={"谁领导怒牙营地","怒牙营地首领","这里由谁负责","纳克罗什营地"}},{q="这里的兽人是萨尔部落的盟友吗？",a="不是。这里的龙喉氏族仍然独立于萨尔的新部落之外。他们坚守着旧部落的黑暗传统，对联盟和部落的旅行者都保持敌意。萨尔的战士视他们为野蛮的弃民，甚至为了获取护甲制造材料而猎杀他们。",al={"龙喉氏族属于部落吗","怒牙营地对部落友好吗","怒牙营地是萨尔部落的一部分吗"}},{q="为什么联盟致力于摧毁这个营地？",a="斯托菲队长和米奈希尔港的矮人守卫发现，纳克罗什已经在怒牙营地集结了投石车和庞大的部队，准备轰炸并征服港口。联盟采取先发制人的攻击，在围攻开始前将其粉碎。",al={"为什么要攻击怒牙营地","斯托菲队长怒牙营地","为什么要杀死纳克罗什"}},{q="为什么术士要寻找这个营地？",a="怒牙营地的龙喉氏族中的黑暗施法者携带着导能魔棒，这是那些寻求完成《卡巴尔法典》的恶魔术法修行者们梦寐以求的黑暗仪式器具。",al={"怒牙营地术士任务","湿地卡巴尔法典","怒牙营地导能魔棒"}}},fx={["02ce636e"]={q="怒牙营地是什么地方？",a="怒牙营地是湿地中部龙喉兽人的主要据点。这座防御严密的前哨营地遍布阴暗潮湿的地带，是龙喉部队集结和筹备行动的地方；他们正谋划征服这片区域，并进军米奈希尔港。",al={"怒牙营地是什么地方","湿地怒牙营地","怒牙营地简介"}},["5926baf0"]={q="怒牙营地发生过什么？",a="第二次战争结束后，龙喉氏族的残部最终撤入沼泽，并在此建立了主要行动基地。在奈克罗什·碎颅者的指挥下，氏族在这里集结攻城武器和投石车，积极筹备行动，意图摧毁联盟在米奈希尔港的据点。",al={"怒牙营地背景","怒牙营地的历史","怒牙营地发生了什么"}},c64d3749={q="怒牙营地危险吗？",a="这里极其危险。营地里挤满了训练有素的龙喉战斗大师、老练的劫掠者、黑暗术士和暗影卫士。毫无准备的旅人若靠得太近，就会面对压倒性的人数优势，以及决意碾碎任何外来者的敌对兽人。",al={"怒牙营地危险吗","怒牙营地有多危险","怒牙营地安全吗"}}},fp="20,284,21.531.0,19.554.1,35.252.0,45.277.0,52.249.0,41.191.0"}
P.entries["subzone:anvilmar"] = {n="安威玛尔",s="安威玛尔是位于丹莫罗寒脊山谷积雪深处的一处坚固的矮人前哨站。它以一座巨大的石制熔炉为中心，是年轻的铜须矮人和流离失所的侏儒难民开始冒险时的主要训练场和集结点。",h="安威玛尔是位于丹莫罗寒脊山谷积雪深处的一处坚固的矮人前哨站。它以一座巨大的石制熔炉为中心，是年轻的铜须矮人和流离失所的侏儒难民开始冒险时的主要训练场和集结点。",kw={"安威玛尔","寒脊山谷","丹莫罗","熔炉","霜鬃","莫迪姆斯·安威玛尔","新手区域"},ang={["race:Dwarf"]="对于矮人来说，安威玛尔代表着踏入世界之旅的开始，它可能承载着曾经统治过统一矮人王国的古代至高王的名字。",["race:Gnome"]="在诺莫瑞根陷落后在此避难的侏儒们，找到了坚毅的矮人盟友、温暖的炉火以及准备帮助他们适应冰封荒野的导师。"},sec={{t="寒脊的炉火",b="安威玛尔坐落在寒脊山谷北部的峭壁之中，是矮人坚韧不拔的象征。这座坚固的石砌建筑群以一座轰鸣的中央熔炉为核心，驻扎着职业训练师、补给商人和经验丰富的山地登山队员，他们在将新兵派往更广阔的王国之前会对其进行训练。尽管被高耸的雪堆所庇护，该定居点依然时刻警惕着敌对的霜鬃巨魔和在冰封山谷中徘徊的凶猛野兽。"},{t="铁与巨魔的传承",b="这个定居点的名字很可能取自至高王莫迪姆斯·安威玛尔，这位古代君主曾在三锤之战前统治着所有的矮人氏族。如今，这里的驻军依然保持警惕，确保熔炉之火长明，以抵御山谷中的巨魔和野兽。"}},faq={{q="安威玛尔是什么？",a="安威玛尔是位于丹莫罗寒脊山谷北部的一处矮人据点和定居点。它是新招募的矮人和侏儒冒险家最初的集结地和训练中心。",al={"什么是安威玛尔","安威玛尔位置","安威玛尔概况"}},{q="它为什么叫安威玛尔？",a="该前哨站可能以至高王莫迪姆斯·安威玛尔或安威玛尔血统命名。莫迪姆斯在三锤之战前统治着矮人氏族，但该定居点的命名并未得到证实。",al={"安威玛尔是谁","安威玛尔名字来源","名字含义"}},{q="安威玛尔面临什么威胁？",a="该前哨站面临着盘踞在寒脊山谷峭壁上的土著霜鬃巨魔，以及狼群和温迪戈等危险的当地野生动物带来的持续威胁。",al={"安威玛尔敌人","谁攻击安威玛尔","安威玛尔面临的威胁"}},{q="可以在这里学习专业技能吗？",a="虽然安威玛尔拥有一座适合锻造和熔炼的轰鸣熔炉，但这里并没有常驻的专业技能训练师。年轻的新兵必须深入丹莫罗，前往卡拉诺斯或铁炉堡等地，才能正式学习制作技艺。",al={"安威玛尔的专业技能","安威玛尔熔炉","安威玛尔锻造"}}},fx={["449334a9"]={q="安威玛尔危险吗？",a="定居点本身安全且受到保护，有宏伟的熔炉、炉火、训练师和守卫，是一处避难所。然而，刚离开其周边地带，四面八方都潜藏着危险。凶猛的狼、饥饿的熊和成群出没的敌对霜鬃巨魔在寒脊山谷的雪地中游荡，时刻威胁着粗心的旅人和新兵。",al={"安威玛尔安全吗","安威玛尔的危险","安威玛尔有哪些威胁"}}},fp="8,291,23.496.0,27.279.0,17.214.0,25.199.0,32.169.0,31.257.0"}
P.entries["subzone:apothecarium"] = {n="Apothecarium",s="Apothecarium是幽暗城的西南区，也是皇家药剂师学会的总部。在这些充满毒气的实验室中，被遗忘者炼金术士在大药剂师法拉尼尔的领导下不知疲倦地工作，调制致命的瘟疫、毒素和人造恐怖生物。这里是幽暗城生物研究的黑暗核心，对于希尔瓦娜斯女士针对生者与天灾军团的战役至关重要。",h="Apothecarium是幽暗城的西南区，也是皇家药剂师学会的总部。在这些充满毒气的实验室中，被遗忘者炼金术士在大药剂师法拉尼尔的领导下不知疲倦地工作，调制致命的瘟疫、毒素和人造恐怖生物。这里是幽暗城生物研究的黑暗核心，...",kw={"憎恶","炼金术","apothecarium","法拉尼尔","新瘟疫","皇家药剂师学会","希尔瓦娜斯","幽暗城"},ang={["profession:Herbalism"]="植物学家为皇家药剂师学会的邪恶蒸馏师提供从北部王国废墟中收集的稀有枯萎植物。",["race:Undead"]="对于被遗忘者来说，Apothecarium是他们生存的熔炉，生产着在洛丹伦抵御压倒性强敌所必需的化学武器和缝合武器。"},sec={{t="恐怖之室",b="Apothecarium位于这座地下首都的西南平台，是一座布满冒泡大锅、解剖台和刺鼻化学烟雾的迷宫。在大药剂师法拉尼尔的领导下，皇家药剂师学会利用该区来加深他们对死亡和腐朽的理解。在这里，炼金术士和外科医生进行组织移植、活体解剖和制造强大的憎恶的实验。在希尔瓦娜斯·风行者女士的授意下，他们的最高目标是研制出一种能够彻底根除洛丹伦大陆上残余的天灾军团和人类的全新瘟疫。"},{t="被遗忘者炼金术中心",b="除了宏大的军事野心外，该区还是东部王国部落进行实用炼金术和草药学的首要中心。无论是学徒还是大师，都会聚集在有毒的运河边蒸馏药剂、研究植物枯萎病，并向资深从业者请教。"}},faq={{q="Apothecarium的用途是什么？",a="Apothecarium是皇家药剂师学会的研究和制造部门。在这里，被遗忘者炼金术士酿造实验性毒药、精炼The New Plague、制造憎恶，并教授从业者炼金术和草药学。",al={"apothecarium的用途","这里发生了什么","为什么会有apothecarium"}},{q="谁领导着Apothecarium？",a="该区及其研究人员由大药剂师法拉尼尔领导，他是皇家药剂师学会的首席科学家，在希尔瓦娜斯·风行者女王的全力授权和支持下运作。",al={"apothecarium领导者","谁在管理apothecarium","法拉尼尔 幽暗城"}},{q="皇家药剂师学会试图创造什么？",a="他们的主要努力是培育一种致命的The New Plague，旨在彻底消灭巫妖王的天灾军团以及在洛丹伦境内挑战被遗忘者领土的任何人类抵抗力量。",al={"被遗忘者瘟疫研究","新瘟疫 幽暗城","他们正在酿造什么"}},{q="玩家可以在这里学习专业技能吗？",a="是的。该区是首都炼金术士和草药学家的主要枢纽，沿途的步道和房间里都有高级专业训练师。",al={"apothecarium训练师","幽暗城的炼金术","幽暗城草药学训练师"}}},fx={["05b32189"]={q="Apothecarium 是什么地方？",a="Apothecarium 是幽暗城西南区，也是皇家药剂师协会阴森的总部和实验室。被遗忘者炼金师和研究员在深邃的洞室中调制有毒药剂、制造强大的憎恶，并进行骇人的实验，以推进被遗忘者的事业。",al={"apothecarium 是什么地方","幽暗城 apothecarium"}},["170a66ad"]={q="Apothecarium 危险吗？",a="对部落旅人来说，这里还算安全；但外来者会觉得此处宛如恐怖密室。空气中充斥着刺鼻的毒气，敞开的药缸里翻滚着腐蚀性化学药剂和疫病试剂，蹒跚的憎恶则在走廊中游荡。任何愚蠢到擅闯此地的生者，都可能落得被绑在药剂师解剖台上的下场。",al={"apothecarium 安全吗","apothecarium 的危险","apothecarium 有什么危险"}}},fp="12,415,18.603.0,26.285.0,34.255.0,27.202.0,54.199.0,35.144.0"}
P.entries["subzone:ariden-s-camp"] = {n="埃瑞丁营地",s="埃瑞丁营地是一处废弃的营地，坐落在穿过逆风小径的小路北侧。它在卡拉赞的阴影中逐渐腐朽，在荒凉的峡谷风声中显得怪异而安静，格格不入。往返于暮色森林和悲伤沼泽的旅人经过这里时往往感到不安，不禁猜测是谁曾经在此扎营。",h="埃瑞丁营地是一处废弃的营地，坐落在穿过逆风小径的小路北侧。它在卡拉赞的阴影中逐渐腐朽，在荒凉的峡谷风声中显得怪异而安静，格格不入。往返于暮色森林和悲伤沼泽的旅人经过这里时往往感到不安，不禁猜测是谁曾经在此扎营。",kw={"埃瑞丁","埃瑞丁营地","逆风小径","暮色森林","卡拉赞","麦迪文","悲伤沼泽"},ang={["class:Mage"]="对于奥术学者来说，这座荒废的营地令人不安地提醒着人们卡拉赞是多么近在咫尺；很少有人能在麦迪文的塔楼附近久留。",["class:Rogue"]="有人在东部王国最恐怖的尖塔下扎营，却再也没有回来取走他们的物品。要么是极其野心勃勃，要么是愚不可及。"},sec={{t="静谧的营地",b="这个破败的营地紧挨着连接暮色森林与悲伤沼泽的峡谷道路北侧的岩壁，看起来就像一个被凡人长久遗弃的普通中转站。然而，在逆风小径压抑的阴霾中，没有任何事物能不被黑暗魔法所侵蚀。无论谁将这里命名为埃瑞丁营地，也无论其主人在卡拉赞周边寻求怎样的财富，这条路径上挥之不去的恐怖早已将其吞噬，只留下风化的布匹、冰冷的灰烬，以及一段永久的谜团。"}},faq={{q="埃瑞丁营地在哪里？",a="埃瑞丁营地位于逆风小径，坐落在连接西侧暮色森林和东侧悲伤沼泽的主路北侧，距离卡拉赞不远。",al={"埃瑞丁营地位置","埃瑞丁营地在哪里","逆风小径营地"}},{q="营地现在有任何活跃的威胁吗？",a="营地所在的空地此刻十分安静，显得诡异而寂静，尽管逆风小径本身潜伏着致命的逆风食人魔、幽灵幻象，以及在卡拉赞附近筑巢的邪恶飞禽。",al={"埃瑞丁营地危险吗","埃瑞丁营地的怪物"}}},fp="13,335,19.475.0,31.171.0,51.201.0"}
P.entries["subzone:astranaar"] = {n="阿斯特兰纳",s="阿斯特兰纳是位于灰谷中部的主要暗夜精灵定居点，它坐落于一座宁静的湖心岛上，横跨了古老的林间道路。作为联盟在该地区行动的核心，它为面对来自充满敌意的熊怪、萨特以及部落威胁的旅行者们提供了重要的庇护所。",h="阿斯特兰纳是位于灰谷中部的主要暗夜精灵定居点，它坐落于一座宁静的湖心岛上，横跨了古老的林间道路。作为联盟在该地区行动的核心，它为面对来自充满敌意的熊怪、萨特以及部落威胁的旅行者们提供了重要的庇护所。",kw={"灰谷","阿斯特兰纳","卡利姆多","暗夜精灵","莱恩·狼行者","哨兵","刺鬃熊怪"},ang={["faction:Alliance"]="阿斯特兰纳是联盟在灰谷充满争端的荒野中行动时的指挥所和主要后勤枢纽。",["race:NightElf"]="对于卡多雷来说，阿斯特兰纳是他们位于卡利姆多中部古老家园的核心堡垒，保护着神圣的林地免受森林中日益增长的威胁。"},sec={{t="森林之心",b="阿斯特兰纳坐落在森林湖泊中央的一座岛屿上，是灰谷中最大的暗夜精灵定居点。通过横跨水面的木制人行桥与陆地相连，这座城镇居住着守卫林地的哨兵、牧师和工匠。除了提供旅店、商人和专家级制皮师等基本便利设施外，它高耸的平台还设有一位飞行管理员，提供前往卡利姆多各地前哨站的角鹰兽交通服务。"},{t="受围困的堡垒",b="尽管这里水波宁静、灯火阑珊，但阿斯特兰纳始终处于随时备战的状态。莱恩·狼行者等当地领袖协调着巡逻和防御行动，以应对从北方入侵、遭到腐蚀的刺鬃熊怪，他们担心这些熊怪可能会对定居点发起直接突袭。"}},faq={{q="阿斯特兰纳提供什么服务？",a="阿斯特兰纳为联盟旅行者提供全套便利设施，包括旅店、杂货商、专家级制皮训练师，以及连接灰谷和卡利姆多各地关键前哨站的飞行管理员。",al={"阿斯特兰纳便利设施","阿斯特兰纳有什么","阿斯特兰纳飞行管理员"}},{q="湖对岸的墓地里埋葬着谁？",a="这个时代的记载中没有提到谁安息在那里。墓地位于城镇对面的湖畔，墓碑深藏着它们秘密。",al={"阿斯特兰纳墓地","瓦斯坦·鹿盔之墓","谁葬在这里"}},{q="为什么阿斯特兰纳的哨兵对当地的熊怪感到担忧？",a="北方的刺鬃熊怪受到了黑暗与腐蚀力量的影响。哨兵莱恩·狼行者担心，如果不加以遏制，它们日益增长的侵略性将助长它们对阿斯特兰纳本身发起公开袭击的野心。",al={"刺鬃熊怪威胁","为什么要对抗熊怪","莱恩·狼行者任务"}},{q="部落玩家可以安全地访问阿斯特兰纳吗？",a="不能。阿斯特兰纳是一个防御森严的联盟据点，由全副武装的暗夜精灵哨兵守卫，他们会攻击视线范围内的部落成员。",al={"阿斯特兰纳对部落友好吗","部落在阿斯特兰纳"}}},fx={["7c629b8a"]={q="阿斯特兰纳是什么地方？",a="阿斯特兰纳是灰谷中部主要的暗夜精灵城镇，也是整片森林中最大的定居点。城镇建在一座宁静湖泊中的岛上，横跨主要商道，并通过两座木桥与荒野相连。对暗夜精灵及其联盟盟友而言，这里是灰谷的核心，也是抵御各方侵扰的主要防御据点。",al={"阿斯特兰纳是什么地方","阿斯特兰纳背景","阿斯特兰纳简介"}},["262340cc"]={q="谁居住在阿斯特兰纳并负责管理这里？",a="阿斯特兰纳的居民主要是暗夜精灵平民、工匠，以及负责守护灰谷的哨兵。这里的重要领袖和守卫者包括哨兵莱恩·狼行者，她负责协调当地的侦察行动，并密切监视周围林地中日益增长的威胁。",al={"谁管理阿斯特兰纳","阿斯特兰纳的领导者","谁领导阿斯特兰纳","阿斯特兰纳哨兵"}},["62cff95a"]={q="阿斯特兰纳危险吗？",a="在桥内，阿斯特兰纳由警惕的哨兵昼夜守卫，是联盟旅人的坚固避难所。然而，这里位于一片争夺日益激烈的森林中。凶猛的蓟皮熊怪潜伏在北面不远处，附近的战歌兽人营地也时刻威胁着灰谷中部，可能发动袭击。部落旅人若踏入城中，就会立即遭到哨兵攻击。",al={"阿斯特兰纳安全吗","阿斯特兰纳的危险","阿斯特兰纳面临的威胁"}}},fp="9,315,19.477.0,21.307.0,41.223.0,47.129.0,68.231.0,41.133.0"}
P.entries["subzone:auberdine"] = {n="奥伯丁",s="奥伯丁是一座位于黑海岸阴沉海岸线上的暗夜精灵沿海港口城镇，它是联盟在卡利姆多北部的主要海上门户。在阴云密布的天空和松树覆盖的峭壁之下，它连接着泰达希尔的岛屿家园与东部王国，同时作为抵御蔓延荒野的行政避难所。",h="奥伯丁是一座位于黑海岸阴沉海岸线上的暗夜精灵沿海港口城镇，它是联盟在卡利姆多北部的主要海上门户。在阴云密布的天空和松树覆盖的峭壁之下，它连接着泰达希尔的岛屿家园与东部王国，同时作为抵御蔓延荒野的行政避难所。",kw={"奥伯丁","船","黑海岸","码头","卡多雷","灯塔","港口","哨兵","桑德里斯·风歌"},ang={["faction:Alliance"]="这座港口是联盟向卡利姆多北部进行旅行和补给的命脉，确保了暴风城、铁炉堡和达纳苏斯之间物流的稳定。",["race:NightElf"]="对于从泰达希尔出发的卡多雷来说，奥伯丁是第一个真正意义上的大陆枢纽，古老的传统在这里与年轻联盟盟友那奇特的习俗和繁忙的工业相遇。"},sec={{t="通往卡利姆多北部的门户",b="奥伯丁坐落在无尽之海的海岸边，是现代黑海岸唯一成功存续下来的大型定居点。与泰达希尔那些隐世的树顶城市不同，奥伯丁面向外界，是联盟在北方最繁忙的港口。往返于此和东部王国的常规航线连接着暴风城港口，并经由南海镇通往米奈希尔港，而当地的渡轮则通往世界之树下的鲁瑟兰村。由于其贸易地位，奥伯丁比传统的精灵飞地有着更浓郁的多元文化气息；游客们会发现，灯火照亮了铺石的街道，外来商人们（包括矮人和侏儒）穿梭在低矮的拱形木屋之间。"},{t="备受困扰的避难所",b="在长者桑德里斯·风歌和奥伯丁村议会的治理下，该镇与当地的哨兵共同协调黑海岸的防御工作。尽管这里是重要的贸易枢纽，但达纳苏斯的枝头却很少提及奥伯丁的名字，因为那里的记忆还沉浸在天崩地裂中逝去的大城市中。该镇长期忍受着严重的区域性威胁：好战的鱼人在海岸线上袭击渔船，腐化的黑木熊怪从南方压境，而从费伍德森林渗出的邪恶魔法更是骚扰着当地的野生生物。"}},faq={{q="奥伯丁的船只去往何处？",a="这里的码头连接着卡利姆多北部与更广阔的联盟世界。一个码头停靠着通往泰达希尔之基——鲁瑟兰村的渡轮，而其他码头则停靠着横跨无尽之海、前往暴风城港口的大型远洋船只，并经由希尔斯布莱德丘陵的南海镇，前往湿地的米奈希尔港。",al={"奥伯丁船只","船只去向","奥伯丁交通"}},{q="谁统治着奥伯丁？",a="奥伯丁由长者桑德里斯·风歌与奥伯丁村议会共同管理。该定居点的防御由哨兵部队负责，当地的指挥官是哨兵戈琳达·纳希恩。",al={"奥伯丁领导人","谁在负责","村议会"}},{q="为什么会有矮人和人类居住在暗夜精灵的城镇里？",a="因为奥伯丁是联盟在卡利姆多北部的核心港口，外国商人、工匠和旅行者首先抵达这里。矮人们建立了一座当地的铁匠铺，为往来的船只和旅客提供服务，这使得该镇与传统的暗夜精灵定居点相比，显得异常多元且热情。",al={"奥伯丁的非精灵族裔","为什么这里有矮人"}},{q="为什么达纳苏斯的暗夜精灵看不起奥伯丁？",a="桑德里斯·风歌称奥伯丁是一个谦卑的地方，其名字从不被达纳苏斯的枝头提及。大多数卡多雷只记得天崩地裂所夺走的东西，即亚米萨兰和巴莎兰的繁荣，而奥伯丁至今仍笼罩在它们的阴影之下。",al={"达纳苏斯与奥伯丁的隔阂","奥伯丁被遗忘者"}}},fx={a08cc347={q="奥伯丁是什么地方？",a="奥伯丁是位于黑海岸雾霭海滨的一处宁静港口定居点，是连接卡利姆多北部与更广阔联盟世界的主要门户。它沿着迷雾之海而建，拥有典型的暗夜精灵木质建筑、发光的街灯和宽阔的码头。这里为乘船从米奈希尔港抵达或乘渡船前往泰达希尔的旅人提供庇护、贸易和友谊，让他们在阴影笼罩的荒野中找到一处安身之所。",al={"这个城镇是什么地方","介绍奥伯丁","奥伯丁概况"}},["36b132df"]={q="奥伯丁发生过什么？",a="天崩地裂撕裂古卡多雷帝国并形成黑海岸海岸线后，人们曾多次尝试重建这片荒凉地区，但都以失败告终。奥伯丁成了这片闹鬼海岸上唯一留存并繁荣起来的定居点。暗夜精灵加入大联盟后，这个宁静的渔村扩建了港口，成为连接暗夜精灵故土与东部王国的重要海上枢纽。",al={"奥伯丁的历史","奥伯丁的过往","奥伯丁过去是什么样的"}},ba4d867a={q="奥伯丁危险吗？",a="由于警惕的暗夜精灵哨兵驻守道路和码头，奥伯丁范围内依然安全。然而，周围荒野的危险日益增多。堕落的熊怪潜伏在南面，焦躁的野生动物在森林中游荡，凶猛的鱼人则徘徊于浅滩，持续威胁着当地渔民和沿海航道。",al={"这里安全吗","奥伯丁面临的威胁","奥伯丁正在遭受攻击吗"}}},fp="9,353,28.716.0,19.536.0,35.324.0,20.188.0,60.308.0,57.246.0"}
P.entries["subzone:azurelode-mine"] = {n="碧玉矿洞",s="碧玉矿洞是一座由联盟运作的活跃铁矿，坐落在希尔斯布莱德丘陵的西南山丘中。矿洞由南海镇的民兵把守，并由人类劳工开采。这里源源不断出产的矿石支撑着当地人类对抗塔伦米尔的被遗忘者的战争行动。",h="碧玉矿洞是一座由联盟运作的活跃铁矿，坐落在希尔斯布莱德丘陵的西南山丘中。矿洞由南海镇的民兵把守，并由人类劳工开采。这里源源不断出产的矿石支撑着当地人类对抗塔伦米尔的被遗忘者的战争行动。",kw={"碧玉矿洞","工头邦兹","希尔斯布莱德丘陵","希尔斯布莱德矿工","铁矿","南海镇"},ang={["faction:Horde"]="打击碧玉矿洞会切断南海镇的新鲜铁矿供应，直接支持了被遗忘者在丘陵地区的攻势。",["profession:Mining"]="碧玉矿洞内部的隧道和周围的山脊拥有丰富的铁矿沉积，尽管联盟矿工对内部进行了严密的守卫。"},sec={{t="丘陵的矿脉",b="碧玉矿洞位于开阔农田的西南方，就在南海镇的西边。长期以来，它一直开采着沿海地区矿产丰富的山脊。如今，人类矿工在工头邦兹的注视下在地下深处劳作，挖掘铁矿，为在这个地区对抗幽暗城的联盟防御者锻造武器和盔甲。"},{t="至关重要的军事目标",b="由于碧玉矿洞提供了南海镇驻军和城镇民兵所需的大部分原铁，它直接成为了部落的目标。塔伦米尔将目标对准了这里的工人和守卫，试图切断维持希尔斯布莱德人类据点的补给线。"}},faq={{q="谁控制着碧玉矿洞？",a="碧玉矿洞由联盟控制，并由隶属于南海镇和希尔斯布莱德镇的人类矿工运作，工头邦兹负责现场监督。",al={"谁管理碧玉矿洞","碧玉矿洞阵营","谁拥有碧玉矿洞"}},{q="为什么这座矿洞对部落很重要？",a="这座矿洞为南海镇和当地联盟民兵的军械库提供了至关重要的铁矿。塔伦米尔的领导层将矿工和监工视为目标，旨在瘫痪人类在丘陵地区的武器生产。",al={"为什么要攻击碧玉矿洞","希尔斯布莱德矿洞之战","部落对矿洞的兴趣"}},{q="碧玉矿洞一直是希尔斯布莱德的一部分吗？",a="那个时代的记载并没有说明在希尔斯布莱德之前是谁占据了这些山丘。如今，这座矿洞是由来自希尔斯布莱德农场的矿工在工头邦兹的带领下开采的。",al={"格雷迈恩之墙历史","碧玉矿洞曾属于吉尔尼斯吗","吉尔尼斯矿洞"}},{q="这里开采什么金属？",a="矿洞主要为附近的人类军械库生产铁矿石。",al={"碧玉矿洞有什么矿石","碧玉矿洞资源"}}},fx={["9018e270"]={q="碧玉矿洞是什么地方？",a="碧玉矿洞是一处仍在开采的铁矿，凿建于希尔斯布莱德丘陵西南部的山丘中，位于希尔斯布莱德农场以南、南海镇以西。它是当地人类的重要战略资源，为该地区各处联盟军械库供应关键的铁矿，以支持他们对抗敌对势力的持续斗争。",al={"碧玉矿洞","碧玉矿洞是什么","碧玉矿洞信息"}},["549159c0"]={q="碧玉矿洞发生过什么？",a="碧玉矿洞长期由希尔斯布莱德农场的矿工在工头邦兹的带领下开采，为联盟军械库供应铁矿。如今，矿洞仍由联盟控制，驻军充足且照常运作；不过，被遗忘者正在争夺希尔斯布莱德，矿洞承受的压力也日益加剧。",al={"碧玉矿洞的历史","碧玉矿洞的过往"}},b1a6dc2c={q="谁居住在碧玉矿洞或负责运营这里？",a="矿洞由附近希尔斯布莱德农场的人类劳工运营，由工头邦兹负责指挥。由于部落和当地野生动物带来的持续威胁，希尔斯布莱德的哨兵和武装守卫驻扎在隧道内外，保护挖矿的工人。",al={"谁负责运营碧玉矿洞","碧玉矿洞的监管者","谁在碧玉矿洞工作"}},["7c8c1de2"]={q="碧玉矿洞危险吗？",a="是的。除了地下开采的常见危险外，碧玉矿洞还是一处卷入希尔斯布莱德之战的军事目标。矿场由警惕的人类哨兵严密防守，部落特工经常试探矿道，企图破坏矿石生产、刺杀工头邦兹并屠杀工人。",al={"碧玉矿洞危险吗","碧玉矿洞面临的威胁","碧玉矿洞有什么危险"}}},fp="14,261,22.338.0,23.300.0,28.163.0,39.197.0,44.155.0,27.63.0"}
P.entries["subzone:bael-dun-digsite"] = {n="巴尔丹挖掘场",s="巴尔丹挖掘场是一处深入莫高雷西缘山脉的矮人挖掘点。这处采石场由来自巴尔莫丹的勘探员卡兹戈姆的团队建立，当地牛头人认为这是对他们祖居之地的直接亵渎，也是对地母神的侮辱。",h="巴尔丹挖掘场是一处深入莫高雷西缘山脉的矮人挖掘点。这处采石场由来自巴尔莫丹的勘探员卡兹戈姆的团队建立，当地牛头人认为这是对他们祖居之地的直接亵渎，也是对地母神的侮辱。",kw={"巴尔莫丹","巴尔丹","贝恩·血蹄","挖掘场","矮人","地母神","探险者协会","莫高雷"},ang={["faction:Alliance"]="尽管巴尔丹的矿工们是出于对历史发现的真诚渴望，但他们过度深入了部落的主权领土，从而与当地人引发了激烈的摩擦。",["race:Tauren"]="对莫高雷西部山丘的侵入性破坏使得巴尔丹成为对地母神的直接侮辱，必须采取果断行动，保护祖传土地免受外来亵渎。"},sec={{t="山丘上的入侵",b="巴尔丹挖掘场位于莫高雷西部的山坡上，是总部位于南贫瘠之地巴尔莫丹的矮人探险者协会远征队的最南端据点。矮人勘探员们毫不关心领土边界或新定居部落的精神传统，他们带着镐、铲和爆破粉末来到这里，想要挖掘埋藏在平原之下的古老泰坦遗物。"},{t="保卫地母神",b="血蹄氏族将这种侵略性的采掘视为对地母神的直接攻击。贝恩·血蹄起初主张谨慎行事，并试图警告这些闯入者离开，但矮人们断然拒绝放弃他们的壕沟。牛头人认为外交手段已经失败，决定摧毁远征队的工具，并将矿工们强行驱逐出去，以免他们毁灭性的挖掘进一步破坏莫高雷的神圣土地。"}},faq={{q="为什么矮人在莫高雷进行挖掘？",a="这些勘探员隶属于总部位于南贫瘠之地巴尔莫丹的矮人远征队。在探险者协会发掘古老文物和泰坦遗产的任务驱动下，他们无视牛头人的主权，只要他们的仪器显示可能有遗物存在的地方，他们就会建立前哨站。",al={"为什么矮人会在这里","莫高雷的矮人","巴尔丹矮人"}},{q="血蹄氏族对该挖掘场有何反应？",a="牛头人将此行动视为对地母神不可容忍的伤害。在矮人拒绝了早先和平离开的警告后，贝恩·血蹄和村落领袖们派遣战士摧毁了矿工的工具，并将这些闯入者赶出了莫高雷。",al={"牛头人的看法","贝恩的反应","牛头人对挖掘场的反应"}},{q="巴尔丹和巴尔莫丹之间有什么联系？",a="巴尔丹是一个卫星挖掘点，直接由位于南贫瘠之地山脊对面的巴尔莫丹要塞和主要挖掘点建立。",al={"巴尔莫丹的关联","这些矮人来自哪里"}},{q="为什么牛头人没有直接与远征队进行谈判？",a="贝恩·血蹄起初寻求外交解决方案，并向远征队领导人发出了正式警告。然而，矮人们将莫高雷视为无主荒野，完全无视牛头人的精神关切，这使得武力成为了氏族唯一的选择。",al={"牛头人是否尝试过和平","与矮人的外交"}}},fx={["30c4a8af"]={q="巴尔丹挖掘场危险吗？",a="是的。驻扎在此的矮人挖掘者和工头对部落旅人怀有敌意，会用镐、步枪和棍棒捍卫自己的领地。此外，他们不断炸山、挖掘山坡，威胁着扰乱莫高雷的自然之灵。",al={"巴尔丹挖掘场有多危险","巴尔丹安全吗"}},["02606c94"]={q="巴尔丹挖掘场是什么地方？",a="巴尔丹挖掘场是一处矮人开采场，直接凿建在莫高雷西部的群山之中。它由探险者卡兹戈姆和来自巴尔莫丹的矮人考古协会成员建立，是联盟深入牛头人领地的一次不受欢迎的入侵。",al={"巴尔丹挖掘场是什么地方","莫高雷巴尔丹采石场","莫高雷矮人挖掘场"}},cc534035={q="巴尔丹挖掘场发生过什么？",a="矮人挖掘者从贫瘠之地赶来，想要挖掘泰坦遗物和埋藏在土地下的古老秘密。他们无视贝恩·血蹄愤怒的反对和警告，开始掘地开采。血蹄部族于是破坏了他们的采矿作业，还打断他们的镐，试图将他们赶出神圣的土地。",al={"巴尔丹的历史","挖掘场发生了什么"}},fc08309c={q="谁负责运营巴尔丹挖掘场？",a="挖掘场由从南贫瘠之地巴尔莫丹派来的矮人矿工和挖掘者运营。他们听从探险者协会和矮人远征队领袖的命令；这些人将发掘古代遗物置于与当地牛头人维持和平之上。",al={"谁控制巴尔丹","巴尔丹挖掘场的首领","谁负责运营挖掘场"}}},fp="16,299,22.420.0,26.432.0,35.308.0,52.266.0,55.172.0,59.263.0"}
P.entries["subzone:bael-dun-keep"] = {n="巴尔丹城堡",s="巴尔丹城堡是一座气势雄伟的矮人防御工事，俯瞰着南贫瘠之地的巴尔莫丹发掘场。在双辫将军的指挥下，这座堡垒成为了联盟在该地区备受争议的据点，使其与周围的部落领地陷入了激烈的冲突之中。",h="巴尔丹城堡是一座气势雄伟的矮人防御工事，俯瞰着南贫瘠之地的巴尔莫丹发掘场。在双辫将军的指挥下，这座堡垒成为了联盟在该地区备受争议的据点，使其与周围的部落领地陷入了激烈的冲突之中。",kw={"巴尔莫丹","巴尔丹城堡","巴尔丹","探险者协会","加恩·石塔","双辫将军","haggis boatmurder","南贫瘠之地"},ang={["faction:Alliance"]="这座城堡是你在南贫瘠之地的主要军事据点，保卫着探险者协会的重要发现，抵御着敌对部落势力的侵扰。",["race:Tauren"]="巴尔丹城堡矗立在从石塔部族手中掠夺的神圣土地上，这时刻提醒着我们联盟对你们家园的侵犯，这是一种莫大的侮辱。"},sec={{t="卡利姆多的一座矮人要塞",b="巴尔丹城堡由矮人建筑师Haggis Boatmurder设计建造，是铁炉堡在南贫瘠之地驻军的军事核心。这座堡垒高耸于巴尔莫丹广阔的发掘壕沟之上，保护着在此搜寻远古泰坦神器的勘探员和考古学家。由于配备了大量的铁制武器和火炮，其驻军始终保持警惕，确保了矮人补给线的安全，并将联盟的军事力量直接投射到卡利姆多的腹地。"},{t="流血冲突的焦点",b="巴尔丹城堡及其毗邻的挖掘现场并非和平建立，它迫使当地的石塔牛头人部族离开了祖居之地。如今，巴尔丹成为了贫瘠之地一个日益紧张的冲突焦点。附近的部落哨站视这座堡垒为赤裸裸的军事入侵，而加恩·石塔则对入侵者发动了一场个人的复仇战争。在愤愤不平的牛头人、投机取巧的斥候，以及像陶拉祖营地这样心怀戒备的哨站之间，这座城堡始终面临着突袭和破坏的威胁。"}},faq={{q="谁控制着巴尔丹城堡？",a="这座堡垒由效忠于联盟和铁炉堡探险者协会的矮人战士驻守，由坚定的指挥官双辫将军统领。",al={"谁管理巴尔丹城堡","谁领导巴尔丹","双辫将军"}},{q="为什么要在南贫瘠之地建造巴尔丹城堡？",a="它的建立是为了保卫巴尔莫丹。这是一场大规模的考古探险，旨在发掘卡利姆多的泰坦圣物以及矮人的古老起源。",al={"矮人为何出现在贫瘠之地","巴尔丹城堡的目的","矮人为何在此建造"}},{q="当地的牛头人为什么要攻击巴尔丹城堡？",a="发掘场和堡垒迫使当地的石塔牛头人离开了他们的祖居之地。像加恩·石塔这样的幸存者寻求复仇，并渴望消灭这些矮人入侵者。",al={"加恩·石塔的复仇","牛头人为何仇视巴尔丹","石塔部族的血仇"}},{q="这座堡垒的建筑师是谁？",a="矮人的建筑记录显示，这座堡垒是由Haggis Boatmurder设计并建造的。",al={"谁建造了巴尔丹城堡","haggis boatmurder","巴尔丹设计图"}}},fx={c3860f97={q="巴尔丹城堡是什么地方？",al={"巴尔丹城堡","巴尔丹堡垒","巴尔莫丹城堡是什么"}},["5592ca31"]={q="巴尔丹城堡发生过什么？",a="矮人远征军深入贫瘠之地，发掘古代泰坦遗物，在巴尔莫丹占据高地并修筑了坚固的城堡。此举使他们的挖掘活动和军事驻扎强行驱逐了当地的石塔牛头人部族，使其失去祖传的圣地。由此爆发了公开而激烈的冲突，幸存的牛头人遂请求部落援助，反击并摧毁这座据点。",al={"巴尔丹的历史","巴尔丹城堡的历史","巴尔丹发生过什么"}},["223c6b8e"]={q="巴尔丹城堡危险吗？",a="是的，尤其是对效忠部落的人而言。巴尔丹城堡驻扎着全副武装的矮人步枪手、军官和哨兵，由双辫将军指挥。他们会强烈敌视任何接近挖掘场的部落闯入者。城墙坚固、重型军械林立，加上联盟火力集中，在城门附近徘徊无异于自寻死路。",al={"巴尔丹危险吗","巴尔丹城堡的威胁","巴尔莫丹敌对吗"}}},fp="13,304,32.528.0,25.523.0,27.162.0,51.142.0,49.187.0,38.102.0"}
P.entries["subzone:bael-modan"] = {n="巴尔莫丹",s="巴尔莫丹是一座位于南贫瘠之地的矮人防御前哨和考古发掘场。这座防御森严的设施由寻找古代泰坦遗物的矮人挖掘者所建立，因驱逐了当地的石塔牛头人而引发了激烈的冲突。",h="巴尔莫丹是一座位于南贫瘠之地的矮人防御前哨和考古发掘场。这座防御森严的设施由寻找古代泰坦遗物的矮人挖掘者所建立，因驱逐了当地的石塔牛头人而引发了激烈的冲突。",kw={"巴尔莫丹","巴尔丹","贫瘠之地挖掘","费格雷","加恩·石塔","石塔","众月之泪","孪辫"},ang={["race:Dwarf"]="这座发掘场代表了探险者协会发掘泰坦历史的无情驱动力，尽管其指挥官的高压手段已经为他们招致了当地部族的激烈仇恨。",["race:Tauren"]="巴尔莫丹就像贫瘠之地上一道未愈合的伤口，建立在石塔部族圣地的废墟之上。帮助加恩·石塔复仇是关乎部族荣誉的事情。"},sec={{t="发掘出的秘密与流血事件",b="巴尔莫丹由防御森严的巴尔丹城堡、一系列巨大的攻城大炮、直升机停机坪以及一个深邃的露天挖掘坑组成。矮人勘探者来到卡利姆多，坚信红土地下埋藏着一处古代泰坦设施。然而，他们的爆破作业直接摧毁了属于石塔牛头人的圣地。矮人探险队没有选择协商，而是用枪炮和炸药将石塔牛头人从他们的祖居地驱逐出去，使得幸存的族人四散奔逃，满怀怨恨。"},{t="发掘遗物的代价",b="这次发掘出来的不仅仅是历史建筑。矮人挖掘者最近发现了一件名为众月之泪的古器，这件遗物会导致接触它的人产生偏执和疯狂。一名被流放的勘探者被流放的费格雷完全屈服于它的影响，当这块石头回到他手中时，他被扭曲成了一只穴居人。在致命的遗物和门外寻求报复的愤怒牛头人之间，这座矮人营地一直处于危险之中。"}},faq={{q="为什么矮人在贫瘠之地挖掘？",a="矮人们正在寻找埋藏在卡利姆多地下的古代泰坦建筑和遗物。他们的挖掘工作是旨在揭开矮人种族起源的更大规模探险的一部分，他们相信这与地下的泰坦研究设施有关。",al={"为什么矮人在这里","巴尔莫丹的目的","矮人在挖掘什么"}},{q="以前住在这里的牛头人怎么样了？",a="这片土地最初属于石塔部族，他们将这里的山丘视为圣地。当矮人到来时，他们使用炸药炸开了发掘场，屠杀或驱逐了居住在此的牛头人，并摧毁了他们的村庄。",al={"石塔牛头人","谁住在巴尔莫丹","牛头人村庄"}},{q="加恩·石塔是谁？",a="加恩·石塔是石塔部族为数不多的幸存者之一。在寻求和平解决的尝试失败后，他在巴尔莫丹门外的道路旁扎营，并征召部落的旅者去破坏矮人的飞行器，杀死那些摧毁他族人家园的军官。",al={"加恩","加恩任务发放者"}},{q="什么是众月之泪？",a="众月之泪是一件由挖掘者发现的神秘的古器。它会使接触它的凡人发疯，并使被流放的矮人费格雷沉迷于夺回它。",al={"众月之泪遗物","费格雷古器"}}},fx={["85aa09cd"]={q="巴尔莫丹是什么地方？",al={"巴尔莫丹信息","巴尔莫丹是什么地方","南贫瘠之地的矮人基地"}},["8ce94b36"]={q="巴尔莫丹发生过什么？",al={"巴尔莫丹的历史","巴尔莫丹这里发生过什么"}},f7e6e142={q="谁在管理巴尔莫丹？",a="这座据点及其考古挖掘工作由铁炉堡军官和勘探者共同管理。负责监督行动的重要人物包括双辫将军、赫金·石须、勘探者卡兹戈姆、马尔金·麦酒、格罗格·锤趾上尉，以及著名的飞行器驾驶员西里克·黑锻领主。",al={"谁领导巴尔莫丹","巴尔莫丹的领导者","谁负责管理巴尔莫丹"}},e130d5b0={q="巴尔莫丹危险吗？",a="是的，尤其是对高举部落旗帜的人而言。驻扎在此的矮人戒备森严，配备了步枪小队、攻城机械、飞行器和大型防御工事。此外，他们深入地下的挖掘活动可能会惊扰深埋的遗物和危险的诅咒，这些东西最好永远留在地下深处。",al={"巴尔莫丹的危险","巴尔莫丹敌对吗","我能去巴尔莫丹吗"}}},fp="10,281,31.560.0,29.490.1,39.246.0,50.245.0,23.302.0,30.181.1"}
P.entries["subzone:bal-lal-ruins"] = {n="巴拉尔废墟",s="巴拉尔废墟是位于荆棘谷西北海岸的古代古拉巴什巨魔废墟，就在格罗姆高营地以北。这些摇摇欲坠的石基俯瞰着暗礁海那浑浊的水域，目前被敌对的血顶巨魔所占据。",h="巴拉尔废墟是位于荆棘谷西北海岸的古代古拉巴什巨魔废墟，就在格罗姆高营地以北。这些摇摇欲坠的石基俯瞰着暗礁海那浑浊的水域，目前被敌对的血顶巨魔所占据。",kw={"巴拉尔废墟","血顶","格罗姆高","古拉巴什","荆棘谷","暗礁海"},ang={["faction:Horde"]="巴拉尔废墟位于格罗姆高营地沿岸不远处，血顶巨魔在此盘踞，对沿着海岸线巡逻的部落构成了持续的安全威胁。",["race:Troll"]="对于效忠部落的暗矛巨魔来说，像巴拉尔这样的地方令人清醒地看到了古代古拉巴什荣耀的残骸，而这里却被同样被无尽嗜血蒙蔽双眼的表亲部落所占据。"},sec={{t="暗礁上摇摇欲坠的前哨站",b="巴拉尔废墟坐落在格罗姆高营地以北的海岸线上，是破碎的古拉巴什帝国的又一遗迹。这里曾是统治艾泽拉斯南部的宏伟巨魔文明的一部分，如今已沦为布满青苔的石墙和破裂的砖石。废墟紧邻暗礁海，提供了一个俯瞰险恶海岸浅滩的高处视野。今天，好战的血顶巨魔占据了这里，拼命保卫着祖先饱经风霜的遗迹，抵御入侵者。"}},faq={{q="谁控制着巴拉尔废墟？",a="这些废墟目前由血顶氏族的成员占据，他们积极守卫领土，抵御外来者、旅行者和竞争对手。",al={"谁住在这里","巴拉尔废墟怪物","谁在巴拉尔废墟"}},{q="巴拉尔废墟位于哪里？",a="你可以在荆棘谷的西北海岸找到它们，位于格罗姆高营地正北方，俯瞰着暗礁海。",al={"巴拉尔废墟位置","巴拉尔废墟在哪里","如何找到巴拉尔废墟"}},{q="这些废墟有什么历史？",a="像荆棘谷中散布的大多数石制建筑一样，巴拉尔废墟可以追溯到古拉巴什帝国在分裂成相互交战的丛林巨魔部落之前的时代。",al={"巴拉尔背景故事","巴拉尔废墟历史","谁建造了巴拉尔废墟"}}},fp="13,269,31.527.0,27.153.0,36.151.0,33.193.0"}
P.entries["subzone:balia-mah-ruins"] = {n="巴里亚曼废墟",s="巴里亚曼废墟是位于荆棘谷北部，覆盖着苔藓的古老古拉巴什定居点遗迹。它位于格罗姆高营地以东的河对岸，这些破碎的石阶目前被敌对的裂颅者巨魔部落所占据并守护着。",h="巴里亚曼废墟是位于荆棘谷北部，覆盖着苔藓的古老古拉巴什定居点遗迹。它位于格罗姆高营地以东的河对岸，这些破碎的石阶目前被敌对的裂颅者巨魔部落所占据并守护着。",kw={"巴里亚曼","古拉巴什","废墟","裂颅者","荆棘谷"},ang={["faction:Horde"]="由于位置就在格罗姆高营地的河对岸，巴里亚曼的敌对裂颅者对部落的侦察兵和补给线构成了持续的周边威胁。",["race:Troll"]="对于暗矛巨魔来说，行走在这些古老的石台之上，不仅会让他们想起祖先曾经共有的辉煌古拉巴什文明，也会让他们想起那场撕裂了丛林巨魔社会的黑暗派系斗争。"},sec={{t="破碎的遗产",b="和散布在丛林中的许多石砌建筑一样，巴里亚曼是曾经统治了东部王国南部大部分地区的庞大古拉巴什帝国留下的遗迹。在古老的首都陷落后，古拉巴什的领土分裂成了许多交战的派系。如今，这些废墟成为了裂颅者部落的据点，他们拼死捍卫着这些石台，抵御着游荡的野兽、来自莫什奥格食人魔山的食人魔，以及任何胆敢过河的外来者。"}},faq={{q="巴里亚曼废墟位于何处？",a="这些废墟坐落在荆棘谷北部，位于部落据点格罗姆高营地东南方向的河对岸，莫什奥格食人魔山的西南方。",al={"巴里亚曼位置","巴里亚曼在哪里","巴里亚曼废墟地图"}},{q="目前是谁在控制这些废墟？",a="这些废墟目前被裂颅者部落占据，这是一个敌对的丛林巨魔派系，正大肆守卫着这些古老的石台。",al={"谁住在巴里亚曼","巴里亚曼有什么怪物","巴里亚曼敌人"}},{q="巴里亚曼的历史是什么？",a="该建筑群建于古拉巴什帝国鼎盛时期。在帝国崩溃后，遗址陷入荒废，最终被丛林植被和幸存的巨魔部落所重新占据。",al={"巴里亚曼背景故事","谁建造了巴里亚曼"}},{q="巴里亚曼的裂颅者是否与其他巨魔营地有关联？",a="是的。裂颅者部落在整个荆棘谷北部和中部维持着多个营地和废墟，并与血顶等敌对部落进行着持续不断的领土战争。",al={"荆棘谷的裂颅者","巴里亚曼裂颅者"}}},fp="15,283,20.498.0,38.164.0,33.148.0,33.200.0,67.205.0"}
P.entries["subzone:balnir-farmstead"] = {n="巴尼尔农场",s="巴尼尔农场是提瑞斯法林地东部的一处废弃庄园，位于洛丹伦废墟的东北方。这里曾经是巴尼尔家族经营的农场，如今土地已荒废，并被那些溜过亡灵壁垒的游荡天灾所侵占。",h="巴尼尔农场是提瑞斯法林地东部的一处废弃庄园，位于洛丹伦废墟的东北方。这里曾经是巴尼尔家族经营的农场，如今土地已荒废，并被那些溜过亡灵壁垒的游荡天灾所侵占。",kw={"巴尼尔","农场","金鱼草","提瑞斯法"},ang={["class:Mage"]="被遗忘者法师被派遣到这片荒芜的土地上采集幸存的巴尼尔金鱼草，通过研究它们来侦测天灾军团挥之不去的魔法污染。",["race:Undead"]="对于被遗忘者来说，这座农场不仅是他们失去洛丹伦的痛苦提醒，也是一个挥之不去的安全隐患，因为来自瘟疫天灾的天灾军团会从这里溜过亡灵壁垒。"},sec={{t="瘟疫前的农场",b="世世代代以来，巴尼尔家族都在提瑞斯法东部的连绵丘陵中经营着他们的家园，而他们花园里的金鱼草至今仍在废墟中绽放。第三次战争期间，当天灾军团横扫洛丹伦时，农场被攻陷，这里的人们也随之丧生，只留下了腐朽的建筑。"},{t="荒凉与天灾的渗透",b="第三次战争之后，这些废墟成了溜过亡灵壁垒的无脑天灾的立足点。被遗忘者死亡卫士警惕地监视着农场，而幽暗城的法师们则从花园里采集幸存的金鱼草，以测试瘟疫腐蚀在土壤中渗透的深度。"}},faq={{q="为什么巴尼尔农场很重要？",a="它坐落在提瑞斯法的东部入口处，就在亡灵壁垒后方。溜过防御者的天灾军团会聚集在这里，而其金鱼草花园则让被遗忘者法师能够测量瘟疫在提瑞斯法扩散的程度。",al={"巴尼尔农场的重要性","为什么要前往巴尼尔农场"}},{q="瘟疫发生前是谁住在农场里？",a="这座农场属于巴尼尔家族，他们以自己的名字命名了这里。当第三次战争期间天灾军团横扫提瑞斯法时，他们便已丧生，如今只有亡灵行走在这些田野之上。",al={"谁拥有巴尼尔农场","巴尼尔家族"}},{q="为什么被遗忘者现在要监视这个农场？",a="无脑的天灾军团经常从瘟疫之地溜过亡灵壁垒并聚集在农场，威胁着提瑞斯法的东部入口。此外，幽暗城的学者们研究着花园中依然生长的顽强金鱼草，以测量瘟疫污染的扩散情况。",al={"为什么被遗忘者关心巴尼尔","rear guard patrol背景故事","巴尼尔金鱼草"}}},fx={["40268029"]={q="巴尼尔农场是什么地方？",a="巴尼尔农场是提瑞斯法林地东部的一处废弃庄园，位于洛丹伦废墟东北方向。王国覆灭前，这里曾是巴尼尔家族宁静的乡间居所。如今庄园破败闹鬼，野生金鱼草蔓生，游荡的亡灵四处出没。",al={"巴尼尔农场是什么地方","巴尼尔农场","关于巴尼尔农场"}},decbf492={q="巴尼尔农场发生过什么？",a="第三次战争期间，天灾军团席卷提瑞斯法，农场遭到占据，巴尼尔家族也已失踪。如今，逃过亡灵壁垒的无脑亡灵聚集在农场废墟间。",al={"巴尼尔农场的历史","这里发生过什么"}},["037a698c"]={q="巴尼尔农场为什么会变成废墟？",a="天灾军团席卷洛丹伦、亡灵占据提瑞斯法东部时，农场遭到毁坏。庄园主人巴尼尔家族在浩劫中失踪，房屋因此逐渐腐朽，庭院则被游荡的幽灵以及从附近的瘟疫之地蔓延而来的恐怖生物占据。",al={"巴尼尔为什么变成废墟","巴尼尔农场为什么被遗弃","是什么摧毁了巴尼尔农场"}},["05134e04"]={q="巴尼尔农场危险吗？",a="是的。这里是逃过亡灵壁垒、从西瘟疫之地而来的躁动亡灵和游荡幽灵的藏身之所。流血的恐怖生物和复仇的鬼魂在杂草丛生的田地与破败的附属建筑间徘徊，始终威胁着沿东部道路旅行的人。",al={"巴尼尔农场危险吗","巴尼尔农场的危险","巴尼尔农场的威胁"}},["55c3446e"]={q="巴尼尔农场为什么叫这个名字？",a="这片土地以巴尼尔家族命名。他们是世代经营这座庄园的人类农民，直到第三次战争期间天灾军团席卷提瑞斯法，他们便失去了踪迹。",al={"为什么叫巴尼尔","巴尼尔农场名称的由来","巴尼尔家族是什么人"}}},fp="16,235,24.296.0,35.280.0,38.228.0,45.183.0,45.283.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="班奈希尔兽穴",s="班奈希尔兽穴是一处神圣的地下圣所，位于泰达希尔的根系之中。这座洞穴群最初是为沉睡的利爪德鲁伊所建的安息之所，但近来却陷入了混乱。被腐蚀的棘木熊怪占领了这些洞穴，将这片宁静的沉睡之地变成了一个危险而疯狂的兽穴。",h="班奈希尔兽穴是一处神圣的地下圣所，位于泰达希尔的根系之中。这座洞穴群最初是为沉睡的利爪德鲁伊所建的安息之所，但近来却陷入了混乱。被腐蚀的棘木熊怪占领了这些洞穴，将这片宁静的沉睡之地变成了一个危险而疯狂的兽穴。",kw={"班奈希尔","兽穴","利爪德鲁伊","翡翠梦境","熊怪","棘木部族","泰达希尔"},ang={["class:Druid"]="班奈希尔是塞纳里奥议会的神圣之地，它是为了在利爪德鲁伊与翡翠梦境沟通时保护他们而专门建造的。",["race:NightElf"]="被腐蚀的棘木熊怪对班奈希尔的占领，是一个令人担忧的迹象，表明这种正在折磨他们的新家园泰达希尔的疾病正在加剧。"},sec={{t="被玷污的圣所",b="兽穴是暗夜精灵德鲁伊进行沉睡的圣地，他们在沉睡时会将灵魂投射到翡翠梦境中。班奈希尔兽穴专门用于庇护进行自然交流的利爪德鲁伊。兽穴分为上下两层地下洞穴，曾经充满了宁静的冥想与深奥的沉思魔法。然而，席卷泰达希尔野生生物的腐蚀并没有放过棘木熊怪，它们入侵了这里，将原本空旷的大厅变成了坚固的巢穴。"},{t="棘木熊怪的入侵",b="在世界之树蔓延的神秘腐蚀令棘木部族陷入疯狂，他们驱逐或威胁了班奈希尔内沉睡的德鲁伊。如今，这些熊怪凶猛地守卫着蜿蜒的隧道，对任何靠近的暗夜精灵都充满敌意。对于泰达希尔的保卫者来说，夺回这座兽穴是一项迫在眉睫的任务，这不仅是为了击退敌对的熊怪，更是为了保护困在深处那些脆弱的德鲁伊和神圣的遗物。"}},faq={{q="什么是班奈希尔兽穴？",a="班奈希尔兽穴是暗夜精灵在泰达希尔开凿的一处地下空洞。它旨在为沉睡的利爪德鲁伊提供庇护，让他们在灵魂游历翡翠梦境时不受打扰。",al={"班奈希尔是什么","班奈希尔兽穴的作用","这个洞穴是什么"}},{q="为什么班奈希尔兽穴里会有熊怪？",a="棘木熊怪成为了泰达希尔生物所遭受的扩散性腐蚀的受害者。它们变得充满敌意且具有领地意识，入侵了兽穴，赶走了看守者，并威胁到了沉睡的德鲁伊。",al={"棘木熊怪为什么在班奈希尔","兽穴里的熊怪","谁占领了班奈希尔"}},{q="兽穴分为哪些区域？",a="洞穴群分为两个主要的相连层级：靠近入口通道的上层兽穴，以及深入地下根系的下层兽穴。",al={"班奈希尔的布局","上层兽穴和下层兽穴","班奈希尔的层级"}},{q="为什么兽穴对德鲁伊如此重要？",a="兽穴为那些进行长期深层沉睡、将意识投射到翡翠梦境中的德鲁伊提供了安全可靠的物理庇护所，因为他们在沉睡期间的肉体长达数年甚至数十年都处于无防备状态。",al={"德鲁伊为什么要睡在兽穴里","德鲁伊兽穴的背景故事","翡翠梦境与兽穴"}}},fx={["129d8c28"]={q="班奈希尔兽穴发生过什么？",a="班奈希尔兽穴由暗夜精灵建造，是供利爪德鲁伊沉睡的神圣避难所，本应是一处宁静的庇护地。然而，近来当地的瘤背熊怪遭到腐化。这个部族被逼得发狂，冲进墓穴并将其占为自己的巢穴，驱逐了暗夜精灵，亵渎了这片神圣的洞穴。",al={"班奈希尔兽穴的历史","班奈希尔发生过什么","班奈希尔兽穴的故事"}},["698c9749"]={q="班奈希尔兽穴为什么被遗弃？",a="暗夜精灵并非自愿遗弃兽穴，而是遭到暴力驱逐。瘤背部族受到腐化后，倾巢入侵了这处圣所。沉睡的德鲁伊及其看护者无力守住此地，上层和下层兽穴最终都落入敌对的熊怪手中。",al={"班奈希尔为什么被遗弃","德鲁伊为什么离开班奈希尔","熊怪占据班奈希尔兽穴"}},["9b622bd1"]={q="班奈希尔兽穴危险吗？",a="独自进入这里极其危险。上层和下层兽穴蜿蜒曲折的隧道里挤满了具有攻击性的腐化瘤背熊怪。地下空间狭窄，加上这些疯狂野兽强烈的领地意识，粗心的旅人很容易被包围并遭到围攻。",al={"班奈希尔兽穴危险吗","班奈希尔有多危险","班奈希尔的危险"}}},fp="20,368,19.540.0,23.472.0,29.189.0,51.224.0,40.159.0,43.209.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="班尼希尔山谷",s="班尼希尔山谷是一条崎岖的峡谷，切入了连接多兰纳尔和达纳苏斯的主干道以南的林地。它已成为受腐蚀、具有攻击性的熊怪的危险避风港，对旅行者构成了持续的威胁。峡谷深处隐匿着班奈希尔兽穴的入口。",h="班尼希尔山谷是一条崎岖的峡谷，切入了连接多兰纳尔和达纳苏斯的主干道以南的林地。它已成为受腐蚀、具有攻击性的熊怪的危险避风港，对旅行者构成了持续的威胁。峡谷深处隐匿着班奈希尔兽穴的入口。",kw={"伏击","班奈希尔兽穴","班尼希尔山谷","达纳苏斯","多兰纳尔","熊怪","峡谷","泰达希尔"},ang={["class:Druid"]="山谷隐藏着班奈希尔兽穴的入口，这是一片神圣的土地，德鲁伊传统上在此休息以与翡翠梦境交流，如今却受到狂暴野生动物的威胁。",["race:NightElf"]="看到熊怪在多兰纳尔和达纳苏斯之间的道路旁发疯，这是泰达希尔病情加重的严峻迹象，需要年轻的哨兵和德鲁伊介入。"},sec={{t="危险的峡谷",b="班尼希尔山谷坐落在多兰纳尔和达纳苏斯之间的大道旁，它尖锐地提醒着人们，泰达希尔的枝叶并非完全安全。受困扰世界之树的怪异疾病影响而发疯的熊怪们，在整个岩石斜坡上寻找藏身之处。他们经常跟踪附近的小路，等待伏击粗心的信使和游荡的哨兵。峡谷深处是班奈希尔兽穴的入口，那里沉睡的德鲁伊和古老的隧道正面临着外面疯狂野兽的侵扰。"}},faq={{q="班尼希尔山谷位于何处？",a="班尼希尔山谷位于泰达希尔中部，就在多兰纳尔村和达纳苏斯主城之间主干道的南侧。",al={"班尼希尔山谷位置","班尼希尔山谷在哪里","寻找班尼希尔山谷"}},{q="为什么这里的熊怪怀有敌意？",a="泰达希尔各处的熊怪已经屈服于一种正在蔓延的腐蚀和疯狂，这种腐蚀和疯狂正笼罩着世界之树的野生动物。这些部族不再像历史上那样与暗夜精灵和平共处，而是变得极具领地意识且暴力成性。",al={"为什么熊怪发疯","班尼希尔敌对熊怪","班尼希尔熊怪攻击"}},{q="峡谷尽头的班奈希尔兽穴里有什么？",a="班奈希尔兽穴是一个地下建筑群，历史上一直被暗夜精灵德鲁伊用来进入深度睡眠并与翡翠梦境交流。然而，随着山谷中腐蚀的加剧，兽穴已变成了一块危险之地。",al={"兽穴里有什么","班奈希尔兽穴","班尼希尔山谷中的兽穴"}},{q="山谷上方的道路安全吗？",a="主干道通常有暗夜精灵哨兵巡逻，但来自班尼希尔山谷的熊怪经常从峡谷窜出来伏击旅行者。往返于多兰纳尔和达纳苏斯之间的旅行者应保持警惕。",al={"道路安全吗","熊怪伏击","去达纳苏斯的道路安全吗"}}},fx={fa7d6d41={q="班尼希尔山谷是什么地方？",a="班尼希尔山谷是泰达希尔中部一处隐蔽的下沉峡谷，位于连接多兰纳尔和达纳苏斯的主干道正南方。山谷植被茂密、坡地崎岖，是腐化熊怪的营地；最深处则是广阔的班奈希尔兽穴入口。",al={"班尼希尔山谷","这是什么地方","班尼希尔山谷概况"}},["5004ddfb"]={q="谁住在班尼希尔山谷？",a="这条峡谷被具有攻击性的腐化熊怪占据。这些生物曾是暗夜精灵的和平邻居，如今却陷入疯狂、变得充满敌意，把山谷据为领地，并威胁着附近的行人。",al={"谁住在这里","班尼希尔山谷的居民","谁居住在班尼希尔山谷"}},f75c8a95={q="班尼希尔山谷危险吗？",a="这里极其危险。山谷里挤满了敌对的熊怪，它们会凶狠地守卫峡谷。上方主干道上的旅人常遭到从峡谷边缘发起的伏击，即使不深入山谷，路过此地也很危险。",al={"班尼希尔山谷有多危险","班尼希尔山谷安全吗","班尼希尔山谷的危险"}}},fp="16,317,17.529.0,34.165.0,34.262.0,66.236.0,44.239.0"}
P.entries["subzone:bandarion-keep"] = {n="班达里安堡",s="班达里安堡是一座与泰尔之守护（Tyr's Watch）有关的防御工事，坐落在提瑞斯法林地西部边缘，靠近耳语森林。这座哨站以加瑞克·班达里安（Garek Bandarion）的名字命名，是林地边境上的一道孤立堡垒，时刻应对着林区中挥之不去的威胁。守军不仅要抵御敌对的海岸鱼人，还要面对游荡的狂热者和不稳定的亡灵。",h="班达里安堡是一座与泰尔之守护（Tyr's Watch）有关的防御工事，坐落在提瑞斯法林地西部边缘，靠近耳语森林。这座哨站以加瑞克·班达里安（Garek...",kw={"班达里安","班达里安堡","加瑞克·班达里安","乔林·克罗格","提瑞斯法","泰尔之守护","耳语森林"},ang={["class:Paladin"]="对于直面冰冷亡灵现实的圣光战士而言，班达里安堡既是避难所，也是警示：一些无法调和圣光与亡灵身份的圣骑士已经崩溃，并开始对自己的被遗忘者同胞挥刀相向。",["race:Undead"]="这座堡垒矗立在提瑞斯法西部的边缘，证明了被遗忘者不仅要时刻警惕天灾军团和血色十字军，还必须提防自身内部的动荡。"},sec={{t="西境堡垒",b="班达里安堡坐落在提瑞斯法林地西部，靠近隐秘的耳语森林，是遗忘者的一座孤哨。该要塞以加瑞克·班达里安的名字命名，与泰尔之守护有着紧密的联系。尽管地理位置偏远且环境严酷，距离幽暗城的繁华庭院甚远，但像乔林·克罗格（Jorin Croge）这样的军需官仍在勤恳工作，以确保存货充足。"},{t="四面受敌",b="驻守此堡绝非安逸的差事。哨站时刻面临着种种威胁：附近水域有邪鳍鱼人（Vile Fin murloc）的突袭，血色十字军的试探性小规模骚扰，以及在阴影中蹒跚游荡、失去理智的天灾奴仆。更糟糕的是内部的危机：一些难以适应“被遗忘者”这一亡灵形态的圣骑士陷入了疯狂，竟将武器挥向了自己的同胞。"}},faq={{q="班达里安堡位于何处？",a="班达里安堡位于提瑞斯法林地遥远的西侧荒野，靠近神秘的耳语森林。",al={"班达里安堡位置","班达里安堡在哪里","如何找到班达里安堡"}},{q="班达里安堡是以谁的名字命名的？",a="这座要塞是以加瑞克·班达里安的名字命名的，他与驻扎在那里的组织有着密切的联系。",al={"谁是班达里安","加瑞克·班达里安","班达里安堡名称由来"}},{q="什么是泰尔之守护？",a="泰尔之守护与班达里安堡以及驻守此地的被遗忘者圣骑士息息相关；班达里安堡被视为泰尔之守护的堡垒，这两个名字经常被互换使用。",al={"泰尔之守护","什么是泰尔之守护"}},{q="有哪些危险威胁着这座堡垒？",a="堡垒的守军经常需要击退邪鳍鱼人，与血色十字军的狂热者交战，消灭游荡的无脑天灾，并镇压那些丧失理智且攻击同伴的不稳定被遗忘者圣骑士。",al={"谁在攻击班达里安堡","班达里安堡的威胁","班达里安敌人"}}},fx={a6af85d6={q="班达里安堡是什么地方？",a="班达里安堡是提尔之手的据点，位于提瑞斯法林地西部神秘的耳语森林附近。它坐落在该地区一处宁静却危机四伏的角落，驻扎着远离幽暗城中心、坚守岗位的被遗忘者。",al={"班达里安堡是什么地方","班达里安堡信息","关于班达里安堡"}},c054e935={q="谁居住在班达里安堡，或由谁管理？",a="这座堡垒驻扎着提尔守望的成员。负责照料这座堡垒的人中有 Jorin Croge，他统筹补给工作，确保驻军在周边威胁环伺之下仍能获得充足供给。",al={"班达里安堡由谁管理","班达里安堡的居民","谁在班达里安堡"}}},fp="14,382,31.385.0,21.405.0,32.118.0,35.112.0,20.181.0,31.223.0"}
P.entries["subzone:baradin-bay"] = {n="巴拉丁海湾",s="巴拉丁海湾是位于卡兹莫丹、湿地、阿拉希高地和洛丹伦南部海岸之间的广阔水域。在第二次战争期间，这里曾有库尔提拉斯强大的海军进行严密的巡逻，而如今，其水域深处隐藏着险恶的暗礁、沉没的战舰以及充满敌意的水生掠食者。",h="巴拉丁海湾是位于卡兹莫丹、湿地、阿拉希高地和洛丹伦南部海岸之间的广阔水域。在第二次战争期间，这里曾有库尔提拉斯强大的海军进行严密的巡逻，而如今，其水域深处隐藏着险恶的暗礁、沉没的战舰以及充满敌意的水生掠食者。",kw={"巴拉丁海湾","水下暗礁","大漩涡之海","库尔提拉斯","失落的舰队","米奈希尔港","南海镇","湿地"},ang={["faction:Alliance"]="巴拉丁海湾是连接卡兹莫丹的联盟行动与其在阿拉希和希尔斯布莱德的前哨站的海上生命线，尽管航海风险和沉没的残骸使得每一次航行都充满危险。",["race:Human"]="对于人类，特别是那些追溯血统至库尔提拉斯或洛丹伦的人来说，这片海湾是神圣而阴郁的土地，它是第二次战争水手们的葬身之地。"},sec={{t="战略水道",b="巴拉丁海湾南邻丹莫罗海岸，北接洛丹伦海岸，是连接东部王国各港口的重要海上通道。海湾的重要锚点包括湿地的米奈希尔港和希尔斯布莱德丘陵的南海镇等繁忙港口。然而，航行于此危机四伏：浅滩、参差不齐的礁石，以及鱼人、鳄鱼和深海鲨鱼等危险生物，时刻威胁着水手和旅行者。"},{t="舰队的坟墓",b="在第二次战争期间，巴拉丁海湾见证了激烈的海军冲突，当时库尔提拉斯舰队与部落在此交战。如今，这些战斗的残酷遗迹仍散布在海岸和海底。库尔提拉斯第三舰队（当地人称为失落的舰队）的残骸半沉在湿地海岸边，而其他船只则沉入了水下暗礁。敌对的灵魂、投机的打捞者和贪婪的海兽现在出没在这些腐朽的木质废墟周围的水域中。"}},faq={{q="巴拉丁海湾沿岸有哪些主要港口？",a="海湾沿岸最著名的定居点是位于湿地的米奈希尔港和位于希尔斯布莱德丘陵的南海镇，它们维持着跨海的重要海军运输。",al={"巴拉丁海湾港口","巴拉丁海湾的港口","巴拉丁海湾通向哪里"}},{q="为什么海湾沿岸有这么多沉船？",a="湿地海岸沿线的残骸是第二次战争期间被摧毁的库尔提拉斯第三舰队，即失落的舰队。其他船只则沉没在阿拉希海岸外危险的水下暗礁上。",al={"湿地沉船","为什么这里有沉船","失落的舰队起源"}},{q="在巴拉丁海湾的水域中会遇到什么威胁？",a="浅水区到处都是极具攻击性的鱼人与沼泽鳄鱼，而深水区则充满了掠食性蟹类、鲨鱼以及溺水水手们不安的灵魂。",al={"巴拉丁海湾怪物","巴拉丁海湾的鱼人","在巴拉丁海湾游泳安全吗"}},{q="哪些领土与巴拉丁海湾接壤？",a="巴拉丁海湾被丹莫罗西北部、湿地的沼泽海岸、阿拉希高地的悬崖以及希尔斯布莱德南部和吉尔尼斯的海岸所环绕。",al={"哪些区域与巴拉丁海湾接壤","巴拉丁海湾地理"}}},fx={["3e0a5d97"]={q="巴拉丁海湾是什么地方？",a="巴拉丁海湾是无尽之海的一处广阔海湾，沿东部王国中部西海岸延伸。海湾水域从卡兹莫丹西北部的丹莫罗一路向北，直达吉尔尼斯和希尔斯布莱德南部边境。它是连接激流堡、吉尔尼斯以及铁炉堡沿海领地等王国的重要海上通道，米奈希尔港则坐落在其南岸的显要位置。",al={"巴拉丁海湾概况","巴拉丁海湾在哪里","这片海湾是什么"}},["9b3de034"]={q="巴拉丁海湾危险吗？",a="进入巴拉丁海湾的水域绝不安全。沿岸浅滩遍布具有攻击性的鱼人和饥饿的鳄鱼，开阔的深水区则潜伏着凶猛的鲨鱼和巨型螃蟹。除了天然险境，暗礁和遗留的海上威胁多年来还吞噬了数十艘船只，留下浸水的危险物潜藏在水面之下。",al={"巴拉丁海湾的威胁","巴拉丁海湾有何危险","在巴拉丁海湾游泳安全吗"}}},fp="11,315,20.484.0,23.504.0,47.178.0,55.195.0,55.183.0,37.172.0"}
P.entries["subzone:bashal-aran"] = {n="巴莎兰",s="巴莎兰是一座位于黑海岸北部、奥伯丁东侧的古老上层精灵遗迹。在大分裂之前，这里曾是亚米萨兰的繁华姊妹城市。如今，这座遗迹中爬满了以残留奥术能量为食的恶魔萨特和格罗尔，而一位孤独的精灵鬼魂则被困在数世纪前的诅咒中。",h="巴莎兰是一座位于黑海岸北部、奥伯丁东侧的古老上层精灵遗迹。在大分裂之前，这里曾是亚米萨兰的繁华姊妹城市。如今，这座遗迹中爬满了以残留奥术能量为食的恶魔萨特和格罗尔，而一位孤独的精灵鬼魂则被困在数世纪前的诅咒中。",kw={"亚米萨兰","阿斯特利安","阿斯瑞克斯·纳拉辛","巴莎兰","黑海岸","德斯瑞尔","格罗尔","上层精灵","萨特"},ang={["class:Mage"]="束缚阿斯特利安的月石结界展现了上层精灵法术恐怖的持久性和威力。",["race:NightElf"]="巴莎兰是一座悲剧性的纪念碑，提醒着人们正是那种鲁莽的奥术傲慢导致了古老卡多雷帝国的毁灭，并为恶魔的腐化铺平了道路。"},sec={{t="破碎的姊妹城市",b="在大分裂将古老的卡利姆多大陆摧毁的一万年前，艾萨拉女王将她宠信的上层精灵子民安置在巴莎兰和亚米萨兰这两座姊妹城镇中。在强大的法师阿斯瑞克斯·纳拉辛的治理下，这些城市曾拥有辉煌的集市和供奉艾露恩的神殿。当永恒之井坍塌时，那场大灾变将两座定居点夷为平地。由于某些早已被时间遗忘的原因，阿斯瑞克斯利用他的奥术造诣，将他的副手、法师阿斯特利安束缚在巴莎兰的一枚月石印记中。即便在肉体消亡后，阿斯特利安的灵魂依然被禁锢在这座破败的神殿里。"},{t="恶魔出没",b="在现代，巴莎兰崩塌的石块被一群邪恶的非法占有者所占据：德斯瑞尔萨特和调皮的格罗尔。这些被腐化的生物受到依附在古老砖石上的残余魔法的吸引，贪婪地吸食着这些残留的能量以强化他们的邪恶法术。尽管它们成群结队地盘踞在残破的庭院中，恐吓着黑海岸林间小路上的旅人，但这些恶魔却对阿斯特利安永恒守望的中央神殿敬而远之。"}},faq={{q="巴莎兰在被毁之前是什么地方？",a="巴莎兰是艾萨拉女王在大分裂前为她宠信的上层精灵贵族建立的一座宏伟的卡多雷城市。它与姊妹城市亚米萨兰一起，由法师领主阿斯瑞克斯·纳拉辛统治。",al={"巴莎兰历史","谁建造了巴莎兰","这片遗迹是什么"}},{q="在神殿中游荡的鬼魂是谁？",a="那个灵魂是阿斯特利安，一位受人尊敬的上层精灵战士法师，他曾负责管理巴莎兰和亚米萨兰。他神秘地遭到了背叛，并被总督阿斯瑞克斯·纳拉辛用一枚月石印记束缚于此，即便在凡身死后，依然承受着囚禁之苦。",al={"阿斯特利安是谁","巴莎兰鬼魂","为什么会有鬼魂"}},{q="为什么萨特会居住在遗迹中？",a="萨特和格罗尔被古老上层精灵留下的强大奥术能量残余吸引到了巴莎兰。它们以这些挥之不去的魔法散溢为食，以增强它们邪恶的恶魔魔法。",al={"为什么这里有萨特","德斯瑞尔萨特背景","巴莎兰的格罗尔"}},{q="巴莎兰与亚米萨兰有何关联？",a="巴莎兰和亚米萨兰是在艾萨拉女王统治下共同治理的姊妹城市。在大分裂将两地摧毁前，阿斯特利安曾频繁往返于两座定居点之间，处理民众的需求。",al={"亚米萨兰联系","黑海岸的姊妹城市","亚米萨兰巴莎兰"}}},fx={["9019c4fd"]={q="巴莎兰是什么地方？",a="巴莎兰是位于黑海岸北部的一处古老暗夜精灵废墟。很久以前，在大分裂撕裂卡利姆多之前，这里曾是一座繁荣的上层精灵城市，拥有热闹的集市和供奉艾露恩的宏伟神殿。它与南方的姊妹城市亚米萨兰共同见证了早期暗夜精灵文明的鼎盛。如今，这里已化为破碎而闹鬼的废墟，被野蛮生长的植被和残存的奥术力量所吞噬。",al={"巴莎兰是什么","巴莎兰概况","关于巴莎兰"}},["3b163f6e"]={q="巴莎兰发生过什么？",a="在卡多雷帝国时期，艾萨拉女王将宠信的上层精灵安置在此，由 Athrikus Narassin 担任总督，副手为阿斯特利安。大约一万年前，第一口永恒之井在大分裂期间爆炸，城市因此彻底毁灭。在某个不为人知的时期，Athrikus 使用月亮石封印，以魔法将阿斯特利安束缚在一处神龛中。阿斯特利安虽已死去，他的幽灵形态却仍被永远困在废墟之间，远在族人消失之后依然如此。",al={"巴莎兰的历史","巴莎兰的传说","巴莎兰发生过什么"}},["0673c761"]={q="巴莎兰危险吗？",a="是的。破碎的石筑遗迹已被敌对的格雷尔和邪恶的德斯瑞尔萨特占据。这些恶魔生物被古老上层精灵石材中渗出的强大奥术能量吸引，吞噬其中残余的力量，以增强自身的黑暗魔法。它们畏惧并避开幽灵阿斯特利安徘徊的圣化神龛，但任何踏入周围废墟的旅人都会遭到袭击。",al={"巴莎兰安全吗","巴莎兰有何危险","巴莎兰的敌人"}}},fp="11,326,21.622.0,19.462.0,45.226.0,38.265.0,36.209.0,42.224.0"}
P.entries["subzone:bathran-s-haunt"] = {n="巴斯兰鬼屋",s="巴斯兰鬼屋是坐落在灰谷西北部、佐拉姆海岸以东的一处古代卡多雷遗迹。最近，被遗忘者药剂师及其卫兵占领了这片区域，搜集当地植物用于他们的炼金研究，导致周围的林地逐渐枯萎。",h="巴斯兰鬼屋是坐落在灰谷西北部、佐拉姆海岸以东的一处古代卡多雷遗迹。最近，被遗忘者药剂师及其卫兵占领了这片区域，搜集当地植物用于他们的炼金研究，导致周围的林地逐渐枯萎。",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","被遗忘者","草药学","卡多雷遗迹","奥迪拉兰废墟","佐拉姆海岸"},ang={["profession:Herbalism"]="这些遗迹在植物学上是独一无二的，因为它是巴斯兰的头发这种因其罕见的药用价值而备受追捧的草药的唯一已知栖息地。",["race:NightElf"]="巴斯兰鬼屋的被遗忘者营地是对卡多雷遗产的暴行，亡灵入侵者亵渎了古老的精灵石结构，并破坏了这片神圣的土地。"},sec={{t="古老森林中的荒芜避难所",b="在奥迪拉兰废墟的北面，破碎的暗夜精灵柱石矗立在茂密的灰谷枝叶掩映之中。这里曾经是一处宁静的卡多雷遗迹，如今却笼罩在被遗忘者的阴影之下。在残破的大理石之间，亡灵药剂师及其打手设置了一间粗陋的露天实验室。他们的存在本身就破坏了这片古老的土地：青草枯萎成了病态的棕色，鲜艳的花朵凋零，随着他们有条不紊地采摘珍稀的林地药材进行实验，一种不自然的腐败正在这片林地中蔓延。"},{t="巴斯兰的头发的采集",b="这些遗迹的主要吸引力在于巴斯兰的头发，这是一种独特的药用草药，只在这些特定的石头间扎根。虽然暗夜精灵和联盟侦察兵视被遗忘者的存在为对神圣精灵土地的邪恶亵渎，但这些亡灵正勤勉地工作，以提取这种植物的强大药效。部落对这种化合物的植物产量有着既得利益，尽管被遗忘者秘密的手段以及由此产生的土地腐化引起了局外人和盟友的一致怀疑。"}},faq={{q="巴斯兰鬼屋位于哪里？",a="巴斯兰鬼屋坐落在灰谷的西北部，位于奥迪拉兰废墟的正北方，在佐拉姆海岸的内陆东侧。",al={"巴斯兰鬼屋在哪里","巴斯兰鬼屋位置","如何前往巴斯兰鬼屋"}},{q="被遗忘者为什么会在这里？",a="被遗忘者药剂师在遗迹中建立了一个营地和实验室，以采集和研究森林中独特的植物生命，最著名的是一种被称为巴斯兰的头发的珍稀药用植物。",al={"亡灵在灰谷做什么","为什么被遗忘者在巴斯兰鬼屋","被遗忘者在巴斯兰的目的"}},{q="什么是巴斯兰的头发？",a="巴斯兰的头发是一种独特的、有价值的草药，具有强大的修复功效，仅生长在巴斯兰鬼屋摇摇欲坠的石结构周围。",al={"巴斯兰的头发草药","什么是巴斯兰的头发","巴斯兰草药"}},{q="为什么遗迹周围的土地正在枯死？",a="被遗忘者长期存在并进行炼金活动，已经腐化了周边区域，导致青草枯萎变黄，娇嫩的林地花朵凋零。",al={"为什么这里的草是棕色的","巴斯兰鬼屋的枯萎病","为什么土地正在腐烂"}}},fx={["72c7f68d"]={q="巴斯兰鬼屋是什么地方？",a="巴斯兰鬼屋是位于灰谷西北部的一处古老卡多雷遗迹，地处奥迪拉兰废墟以北。暗夜精灵早已将此地遗弃，如今，遗迹中摇摇欲坠的大理石柱和杂草丛生的庭院被被遗忘者草药师及其守卫占据。他们在石柱之间搭起了一座临时营地。",al={"巴斯兰鬼屋","这个地方是什么","巴斯兰鬼屋的传说"}},["43b0b094"]={q="谁居住在巴斯兰鬼屋，或由谁管理？",a="目前，占据遗迹的是被遗忘者草药师和受雇的暴徒，他们在古老的大理石建筑间搭建了一处露天实验室。他们欢迎部落成员，但其试验和活动始终受到严密监视；联盟的闯入者一经发现便会被赶走。",al={"谁控制着巴斯兰鬼屋","谁住在巴斯兰鬼屋","巴斯兰鬼屋的居民"}},["0d907f15"]={q="巴斯兰鬼屋危险吗？",a="这里相当危险，对联盟旅人尤其如此。驻守于此的被遗忘者全副武装，对外来者充满敌意，还在积极进行违背自然的实验。就连周围的土壤也在他们的盘踞下枯萎变色，表明这里的环境对生者极不友善。",al={"巴斯兰鬼屋的危险","巴斯兰鬼屋安全吗","这里危险吗"}}},fp="15,277,38.528.0,29.506.0,33.144.0,26.202.0,23.154.0,41.171.0"}
P.entries["subzone:bay-of-storms"] = {n="风暴海湾",s="风暴海湾是一片广阔而汹涌的海湾，切入了艾萨拉崎岖的东部悬崖。它那翻腾的海水掩盖了古老的废墟、水下洞穴以及危险的海洋生物，使得沿此海岸航行变得危机四伏。",h="风暴海湾是一片广阔而汹涌的海湾，切入了艾萨拉崎岖的东部悬崖。它那翻腾的海水掩盖了古老的废墟、水下洞穴以及危险的海洋生物，使得沿此海岸航行变得危机四伏。",kw={"艾萨拉","风暴海湾","无尽之海","赫塔拉的巢穴","鳞须海龟洞穴","亚考兰神殿"},ang={["profession:Cooking"]="风暴海湾那动荡且深邃的海水在卡利姆多海岸寻求稀有且珍贵的深海渔获的海岸渔民中非常出名。"},sec={{t="风暴海岸",b="风暴海湾向着无尽之海敞开，构成了艾萨拉大部分引人注目的海岸地理。这里绝非宁静的港湾，其动荡的水域和岩石暗礁是危险野生动物和古老水生威胁的家园。在其水域内外分布着诸多地标，例如沉没的亚考兰神殿、赫塔拉的巢穴的珊瑚礁，以及鳞须海龟洞穴，使得这片海湾绝大多数时候被普通水手所避开，反而是海岸怪物的领地。"}},faq={{q="风暴海湾位于哪里？",a="风暴海湾位于艾萨拉的东部边缘，直接通向卡利姆多海岸外的无尽之海。",al={"风暴海湾位置","风暴海湾在哪里","海湾在哪里"}},{q="海湾内有哪些著名地标？",a="海湾内包含几处著名的海岸特征，包括亚考兰神殿、被称为赫塔拉的巢穴的礁石，以及隐藏着的鳞须海龟洞穴。",al={"风暴海湾地标","风暴海湾里有什么","风暴海湾兴趣点"}},{q="为什么在海湾航行很危险？",a="狂暴的浪潮、尖锐的锯齿状岩石以及充满敌意的水生生物使得海湾对过往船只来说十分凶险，而且此处几乎没有海岸文明可以提供救援。",al={"风暴海湾安全吗","为什么危险","海湾危险因素"}}},fp="13,238,19.462.0,35.117.0,42.165.0,37.168.0"}
P.entries["subzone:bear-s-head"] = {n="熊头",s="熊头是艾萨拉东南部悬崖边上一处隐蔽的山区。该地因居住在崎岖高地上的木喉熊怪聚落而得名，是他们通往北方大型家园的前哨站，正下方则是大法师克希雷姆的悬崖圣所。",h="熊头是艾萨拉东南部悬崖边上一处隐蔽的山区。该地因居住在崎岖高地上的木喉熊怪聚落而得名，是他们通往北方大型家园的前哨站，正下方则是大法师克希雷姆的悬崖圣所。",kw={"大法师克希雷姆","艾萨拉","熊头","熊怪","木喉","乌索兰"},ang={["class:Mage"]="俯瞰熊头的高耸悬崖是大法师克希雷姆的居所，他是一位强大而古怪的施法者，那些寻求进阶训练的奥术修行者常常会来寻找他。"},sec={{t="熊怪前哨与崖顶魔法",b="熊头坐落于艾萨拉的东南部，因其高地上建立的未受腐蚀的木喉熊怪营地而得名。这些简朴的定居点是连接北方乌索兰和木喉要塞这些主要熊怪巢穴的边远营地。在这片区域高耸的悬崖顶端，坐落着克希雷姆之塔，这是一处古怪的圣所，大法师克希雷姆和他的一小群学徒在这里进行奥术研究，远离海岸线其他纷乱地区的喧嚣，在此静静隐居。"}},faq={{q="这个区域为什么叫熊头？",a="该地区以其丘陵地带建立的木喉熊怪村庄命名。这些熊族在此维持着活跃的营地，作为他们在卡利姆多北部的据点的前哨站。",al={"熊头名称由来","为什么叫熊头","熊头含义"}},{q="哪些熊怪居住在熊头？",a="该区域居住着木喉部族。与卡利姆多各地受恶魔腐蚀的其他许多熊怪部族不同，木喉部族在很大程度上抵御了这种污染，并与他们位于乌索兰和木喉要塞的主要聚落保持着联系。",al={"熊头的熊怪","熊头木喉","这里是什么熊怪部族"}},{q="熊头上方悬崖上的塔是什么？",a="那座悬崖上的尖塔属于大法师克希雷姆。他是一位古怪的人类法师，在艾萨拉隐居钻研学问，身边跟随着几名学徒和高等精灵同僚。",al={"熊头上方的塔","谁住在那座塔里","克希雷姆之塔"}}},fp="11,312,36.510.0,36.215.0,35.262.0,50.194.0"}
P.entries["subzone:beezil-s-wreck"] = {n="比吉尔的飞艇残骸",s="比吉尔的飞艇残骸位于尘泥沼泽的泥潭深处，是一艘不幸坠毁的地精飞艇遗址。这艘破碎的飞船位于Tabetha's Farm以东，其货舱内散落着补给品和不稳定的工程部件，吸引了许多拾荒者。",h="比吉尔的飞艇残骸位于尘泥沼泽的泥潭深处，是一艘不幸坠毁的地精飞艇遗址。这艘破碎的飞船位于Tabetha's Farm以东，其货舱内散落着补给品和不稳定的工程部件，吸引了许多拾荒者。",kw={"比吉尔","比吉尔的飞艇残骸","尘泥沼泽","瑟夫隆","塔贝萨","飞艇坠毁"},ang={["profession:Engineering"]="一艘地精飞艇扭曲的残骸中存放着不稳定的机械部件，尤其是任何技师都垂涎的瑟夫隆助推器。",["race:Gnome"]="检查竞争对手地精航空业那冒烟的遗骸，令人清醒地意识到非侏儒飞行设计中固有的危险。"},sec={{t="灾难性的着陆",b="隐藏在Tabetha's Farm以东潮湿泥泞之中的，是一架地精飞艇的残骸，被称为比吉尔的飞艇残骸。这艘飞艇在飞越卡利姆多向南运送货物的途中，不幸坠入了沼泽。虽然残骸在纠缠的芦苇丛中依然冒着烟，但它那古怪的船长比吉尔似乎已经从沼泽中消失了，只留下散落的板条箱和发出滴答声的机器，在盐水中慢慢腐烂。"},{t="泥潭中的打捞",b="尽管环境恶劣，坠机现场仍然是投机冒险家的首要目标。这艘飞艇携带了一批不稳定的货物，特别是那些在撞击中幸存下来的瑟夫隆助推器和沉重的板条箱。那些敢于涉水穿过周围野兽群的拾荒者，往往冒着生命危险试图在腐蚀性的沼泽水彻底毁掉这些货物之前，夺取剩余的失落补给。"}},faq={{q="什么是比吉尔的飞艇残骸？",a="比吉尔的飞艇残骸是一艘地精飞艇的坠毁地点，位于尘泥沼泽深处，Tabetha's Farm的正东方。这艘飞艇在穿过沼泽运送货物时坠毁了。",al={"比吉尔的飞艇残骸","尘泥沼泽坠毁的飞艇","这个残骸是什么"}},{q="飞行员比吉尔在哪里？",a="在坠机现场附近找不到飞行员比吉尔的踪影。他是逃入了险恶的荒野，还是完全逃离了这片沼泽，对于那些搜寻船体的人来说，这仍然是一个谜。",al={"比吉尔在哪里","谁是比吉尔","比吉尔的位置"}},{q="飞艇运载了什么贵重货物？",a="这艘飞艇装载了贸易货物和不稳定的地精技术，包括瑟夫隆助推器。这些贵重的工程组件使该地点成为冒险者和打捞者频繁光顾的目标。",al={"飞艇里有什么","瑟夫隆助推器","残骸货物"}}},fp="14,263,20.440.0,19.403.0,23.186.0,27.189.0,46.203.0"}
P.entries["subzone:beggar-s-haunt"] = {n="乞丐鬼屋",s="乞丐鬼屋是一座废弃的暴风城侦察塔，坐落在暮色森林东北部的山坡上，靠近通往逆风小径的山路。它最初是为监视王国东部边界而建，现在却成了被遗忘者深入联盟领地进行渗透的前哨站。",h="乞丐鬼屋是一座废弃的暴风城侦察塔，坐落在暮色森林东北部的山坡上，靠近通往逆风小径的山路。它最初是为监视王国东部边界而建，现在却成了被遗忘者深入联盟领地进行渗透的前哨站。",kw={"药剂师浮斯廷","乞丐鬼屋","死亡猎手扎瑞杜斯","暮色森林","骑士之穴","侦察塔","暴风城卫兵"},ang={["faction:Alliance"]="被遗忘者特工驻扎在紧邻主路的一座旧暴风城侦察塔内，这是部落在夜色镇家门口进行渗透的一个令人担忧的信号。",["race:Undead"]="对于被遗忘者的行动人员来说，这个隐蔽的前哨站为他们深入南方人类领地提供了一个罕见而危险的立足点。"},sec={{t="阴影中的瞭望塔",b="乞丐鬼屋矗立在密斯特曼托庄园东侧多雾的山丘之上，曾经是一座由暴风城卫兵驻守的活跃观察哨，负责保卫王国东部的入口。随着该地区陷入暮色森林的阴霾，王国巡逻队撤回了夜色镇，这座石塔便遭到了遗弃。今天，它所占据的战略制高点有着更加险恶的用途：被遗忘者的特工，包括皇家药剂师协会的成员和死亡猎手，利用这座破败的据点在联盟的眼皮底下进行研究并监视该地区。"},{t="骑士之穴与被遗忘的亡者",b="塔后有一条陡峭蜿蜒的小路，通向一个名为骑士之穴的僻静水潭和瀑布。这里有一座无名坟墓，两侧矗立着两尊不祥的兜帽石像，酷似黑暗之门两侧的守护者雕像。附近的埋葬地，包括一名无名士兵的墓地，诉说着在被遗忘者进驻这座瞭望塔之前，这条边境线上曾经发生的被遗忘的冲突。"}},faq={{q="为什么被遗忘者会出现在乞丐鬼屋？",a="来自幽暗城的特工，包括皇家药剂师协会的药剂师浮斯廷和死亡猎手扎瑞杜斯，已经占据了这座废弃的瞭望塔。从这里，他们可以监视联盟的动向，并悄悄地在遥远的南方进行实验。",al={"谁在乞丐鬼屋","为什么部落在这里","乞丐鬼屋的亡灵"}},{q="这座塔最初是被遗忘者建造的吗？",a="不是。这座塔是由暴风城王国建造的侦察前哨。当当地防御薄弱，该地区沦为暮色森林后，暴风城卫兵就放弃了它，使其空置，直到被遗忘者的侦察兵占据了这里。",al={"谁建造了乞丐鬼屋","乞丐鬼屋的历史","这是联盟的塔吗"}},{q="塔后面那座奇怪的坟墓是什么？",a="鬼屋后的小路下方是骑士之穴，这是一个僻静的瀑布水潭，里面有一座无名坟墓，周围环绕着与黑暗之门两侧纪念碑风格相同的兜帽守护者雕像。",al={"骑士之穴的雕像","塔后的坟墓","暮色森林的黑暗之门雕像"}},{q="乞丐鬼屋对联盟的旅行者怀有敌意吗？",a="是的。驻扎在塔里的被遗忘者都是经验丰富的特工，任何游荡到他们山坡据点附近的联盟冒险者都会遭到他们的攻击。",al={"他们会攻击我吗","乞丐鬼屋的守卫","乞丐鬼屋安全吗"}}},fx={["221bad0c"]={q="乞丐鬼屋是什么地方？",a="乞丐鬼屋是一座古老的废弃瞭望塔，最初由暴风城卫兵建于暮色森林东北部。它高踞在密斯特曼托庄园以东的山脊上，俯瞰通往逆风小径的隘口。这座石砌防御哨站早已脱离人类掌控，任由森林中蔓延的黑暗侵蚀。",al={"乞丐鬼屋","这座塔是什么","暮色森林的乞丐鬼屋"}},["945d85f8"]={q="谁居住在乞丐鬼屋？",a="塔中驻扎着两名被遗忘者高级特工：皇家药剂师协会的药剂师 Faustin，以及他的护卫亡灵哨兵 Zraedus。他们利用这处僻静的哨站进行黑暗的炼金研究，远离暴风城和他们在洛丹伦的敌人的耳目。",al={"谁在乞丐鬼屋","谁控制着乞丐鬼屋","乞丐鬼屋的居民"}},["29ce06ab"]={q="乞丐鬼屋为何被遗弃？",a="与暮色森林的大部分地区一样，随着暴风城王国的军事力量在此地瓦解，这座哨站也被废弃了。夜色镇守夜人疲于抵御狂暴的野兽、亡灵恐怖和蜘蛛，连夜色镇都难以守住，山脊上的偏远岗楼便被弃守，很快落入敌对势力之手。",al={"乞丐鬼屋为何被遗弃","乞丐鬼屋的废墟","暴风城为何离开乞丐鬼屋"}},dbe0cc4e={q="乞丐鬼屋危险吗？",a="极其危险，尤其对途经暮色森林东部而毫无戒备的联盟探险者而言。药剂师 Faustin 和亡灵哨兵 Zraedus 都是久经沙场的老手，比周围的野兽致命得多。任何联盟成员只要靠近他们隐秘的据点，都会遭到他们无情的攻击。",al={"乞丐鬼屋安全吗","乞丐鬼屋的等级","乞丐鬼屋的危险"}}},fp="14,297,27.587.0,38.408.0,41.251.0,48.233.0,43.202.0,48.155.0"}
P.entries["subzone:beren-s-peril"] = {n="博伦的巢穴",s="博伦的巢穴是位于银松森林安伯米尔西南方岩石山丘中一处隐蔽的山洞。这里是忠于死灵法师图勒·鸦爪的亡灵天灾残党所盘踞的堡垒，他们正密谋对抗附近的被遗忘者。",h="博伦的巢穴是位于银松森林安伯米尔西南方岩石山丘中一处隐蔽的山洞。这里是忠于死灵法师图勒·鸦爪的亡灵天灾残党所盘踞的堡垒，他们正密谋对抗附近的被遗忘者。",kw={"奥利斯特","安伯米尔","博伦的巢穴","鸦爪苦工","天灾军团","瑟伯切尔","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="保卫银松森林崎岖的山路意味着必须在亡灵残党的巢穴切断瑟伯切尔与南方领土之间的补给线之前将其肃清。",["race:Undead"]="博伦的巢穴中的鸦爪爪牙是天灾军团残留影响的痛苦提醒，他们威胁着瑟伯切尔的安全，需要希尔瓦娜斯的忠诚者们迅速而无情地将其铲除。"},sec={{t="山丘中的隐患",b="博伦的巢穴隐蔽在安伯米尔西南方的高耸峭壁之中，由一个昏暗的洞穴和一条远离主干道的蜿蜒山径组成。第三次战争的浩劫过后，叛变的死灵法师图勒·鸦爪指挥的一群亡灵天灾残党在此建立了防御据点。鸦爪的奴仆们——摄政者、守卫和苦工——没有向黑暗女王屈服，也没有撤退到北方，而是聚集于此，秘密筹划对被遗忘者据点瑟伯切尔发动袭击。被遗忘者的侦察兵发现了他们的踪迹，这片寂静的悬崖随即变成了一个活跃的战场，部落的特工被派往此处，旨在阻止这场袭击发生之前消除威胁。"}},faq={{q="什么是博伦的巢穴？",a="它位于银松森林中安伯米尔的西南方，是介于中央公路和通往安伯米尔的支路之间的一处洞穴及周边山坡通道。",al={"博伦的巢穴","博伦的巢穴在哪里","博伦的巢穴洞穴"}},{q="谁控制着博伦的巢穴？",a="该洞穴被忠于死灵法师图勒·鸦爪的亡灵天灾所占据，其中包括鸦爪守卫、苦工和摄政者。",al={"谁住在博伦的巢穴","博伦的巢穴的敌人","鸦爪亡灵"}},{q="为什么被遗忘者在意这个地点？",a="被遗忘者的侦察兵发现躲藏在博伦的巢穴内的亡灵正在集结部队，准备对瑟伯切尔发动攻击，这促使暗影牧师奥利斯特下令对他们进行先发制人的打击。",al={"奥利斯特博伦的巢穴","为什么要攻击博伦的巢穴","瑟伯切尔威胁"}},{q="谁是图勒·鸦爪？",a="图勒·鸦爪是活跃在银松森林的一名强大的死灵法师，他控制着零散而充满敌意的无脑天灾爪牙，并利用博伦的巢穴和芬里斯城堡等地点威胁该地区。",al={"图勒·鸦爪","图勒银松森林"}}},fx={["896a3c65"]={q="博伦的巢穴发生过什么？",a="第三次战争之后，银松山丘中这片僻静的洞穴群成了叛变亡灵的集结地。追踪当地威胁的被遗忘者斥候发现，效忠于叛变通灵师 Thule Ravenclaw 的敌对亡灵已聚集在洞穴内，暗中筹备袭击附近被遗忘者定居点瑟伯切尔。",al={"博伦的巢穴历史","博伦的巢穴发生过什么","博伦的巢穴传说"}},["25ec4175"]={q="博伦的巢穴危险吗？",a="是的，博伦的巢穴极其危险。山坡洞穴中遍布受 Thule Ravenclaw 控制的敌对亡灵，包括 Ravenclaw 苦工、守护者和摄政者。任何进入洞穴的旅人，都可能在这些有组织的亡灵对瑟伯切尔发动袭击之前被其淹没。",al={"博伦的巢穴危险吗","博伦的巢穴有多危险","博伦的巢穴安全吗"}}},fp="13,256,28.691.0,22.161.0,27.134.0,45.222.0,23.218.0"}
P.entries["subzone:bitter-reaches"] = {n="痛苦海岸",s="痛苦海岸是艾萨拉东北部一片崎岖且饱受风霜的荒野。这里几乎未受文明涉足，崎岖的悬崖间徘徊着捕食性的野兽和巨大的山岭巨人。",h="痛苦海岸是艾萨拉东北部一片崎岖且饱受风霜的荒野。这里几乎未受文明涉足，崎岖的悬崖间徘徊着捕食性的野兽和巨大的山岭巨人。",kw={"艾萨拉","痛苦海岸","奇美拉","角鹰兽","山岭巨人","山鼠草","软泥怪"},ang={["class:Hunter"]="痛苦海岸的悬崖巢穴是绝佳的狩猎场，这里生活着许多原始海岸特有的野生角鹰兽和极具攻击性的奇美拉。",["profession:Herbalism"]="痛苦海岸饱受风霜的高地是艾萨拉为数不多能生长珍贵山鼠草的地方，但你必须与奇美拉和巨人搏斗才能采集到它们。"},sec={{t="危险的海岸边境",b="痛苦海岸占据了艾萨拉东北部的悬崖，是一片俯瞰无尽之海、荒凉且未被驯服的岩石地带。成群的野生角鹰兽和双头奇美拉在高处筑巢，而酸性软泥怪则从寒冷的地面中渗出。沿着北部的高脊，巨大的山岭巨人占据了这些斜坡，驱逐了弱小的生物，使这片冰冷的区域成为了孤身旅者的致命险境。"},{t="峭壁上的植物",b="尽管这里寒风凛冽，掠食者横行，但这片崎岖的地貌却孕育着稀有的高山植物。稀疏的山鼠草丛顽强地依附在岩壁和风口上，这使得这片危险的地带偶尔也值得那些敢于避开巨人和领地意识极强的奇美拉、勇于冒险的草药师们涉足。"}},faq={{q="痛苦海岸在哪里？",a="痛苦海岸构成了艾萨拉的东北部区域，覆盖了海湾上方的高大海岸悬崖和山脊。",al={"痛苦海岸位置","痛苦海岸在哪里","痛苦海岸艾萨拉"}},{q="这里生活着哪些生物？",a="该地区是领地意识极强的角鹰兽、双头奇美拉和软泥怪的家园。高耸的山岭巨人在北部边界游荡。",al={"痛苦海岸怪物","痛苦海岸有什么生物","痛苦海岸的怪物"}},{q="为什么这里会有山岭巨人？",a="古老的山岭巨人栖息在艾萨拉北部的高峰和边缘地带，划定了属于自己的领地，并将大部分当地野生动物从它们的活动范围内驱逐出去。",al={"艾萨拉山岭巨人","为什么痛苦海岸有巨人"}},{q="在痛苦海岸能找到什么有价值的资源？",a="像山鼠草这样的稀有高海拔草药可以零星地在岩石露头和山脊线上找到。",al={"痛苦海岸草药","痛苦海岸采集"}}},fp="14,191,28.480.0,18.331.0,29.120.0,25.132.0,35.178.0,51.124.0"}
P.entries["subzone:black-channel-marsh"] = {n="黑水沼泽",s="黑水沼泽是一片位于湿地西南部阴暗泥泞的沼泽，紧邻通往米奈希尔港的主干道。这片潮湿的土地上到处都是极具攻击性的迅猛龙，对于在沿海低地穿行的粗心旅客和物资补给员来说，构成了直接的威胁。",h="黑水沼泽是一片位于湿地西南部阴暗泥泞的沼泽，紧邻通往米奈希尔港的主干道。这片潮湿的土地上到处都是极具攻击性的迅猛龙，对于在沿海低地穿行的粗心旅客和物资补给员来说，构成了直接的威胁。",kw={"黑水沼泽","沼泽","米奈希尔港","迅猛龙","湿地"},ang={["class:Hunter"]="对于那些想要驯服或追踪湿地凶猛迅猛龙的猎人来说，这片沼泽提供了一个就在大路旁、充满危险的试炼场。",["faction:Alliance"]="这条走廊是将米奈希尔港与卡兹莫丹其他地区连接起来的重要生命线，使得迅猛龙的入侵成为困扰旅行者的顽疾。"},sec={{t="米奈希尔大道的危机",b="黑水沼泽横跨主干道西南部的沼泽低地，在前往米奈希尔港的商队司机和信使中臭名昭著。虽然高架的道路给人一种安全的错觉，但停滞的水道和茂密的芦苇丛中栖息着极具领地意识的迅猛龙群。饥饿的野兽经常闯入交通要道，伏击那些偏离道路哪怕一两步的新兵和疲惫的旅人。"}},faq={{q="黑水沼泽在哪里？",a="黑水沼泽位于湿地的西南角，紧邻通往米奈希尔港的主要道路南侧。",al={"黑水沼泽在哪里","黑水沼泽位置","湿地黑水"}},{q="为什么这片沼泽被认为对旅行者很危险？",a="沼泽中布满了迅猛龙的巢穴。因为这些捕食者沿着沼泽边缘捕猎，它们经常潜行到路边，让毫无戒心的旅行者和低等级的冒险者措手不及。",al={"为什么很危险","黑水沼泽中的威胁","路上的迅猛龙"}},{q="谁经常经过这里？",a="联盟信使、矮人商人和往返于铁炉堡与米奈希尔港码头之间的旅行者经常经过这条紧邻沼泽的道路。",al={"谁使用这条路","这里的旅行者"}}},fp="19,280,26.449.0,37.149.0,53.225.0,36.177.0"}
P.entries["subzone:blackchar-cave"] = {n="黑炭谷",s="黑炭谷是一处神秘且被封闭的洞穴，隐藏在灼热峡谷的西南方岩壁中，靠近黑石山的山脚。它的入口被无法通过的碎石和岩块堵住了。",h="黑炭谷是一处神秘且被封闭的洞穴，隐藏在灼热峡谷的西南方岩壁中，靠近黑石山的山脚。它的入口被无法通过的碎石和岩块堵住了。",kw={"黑炭谷","黑石山","封闭的洞穴","灼热峡谷"},sec={{t="一处封闭的入口",b="黑炭谷隐藏在靠近黑石山通道的炽热岩壁之中，原本可能是深邃洞穴入口的地方，现在却是一堵严实的石墙。沉重的碎石和焦黑的矿渣堵住了入口，使得任何人都无法探索深埋在山根底下的隧道。周围荒凉的地形被灰烬和岩浆灼烧过，对于流浪者来说这里没有任何安身之处。"}},faq={{q="你能进入黑炭谷吗？",a="不能。黑炭谷的入口完全被坍塌的岩石、灰烬和碎石封死了。里面没有可以探索的开放内部空间。",al={"黑炭谷是否开放","进入黑炭谷","黑炭谷内部"}},{q="黑炭谷位于什么地方？",a="它位于灼热峡谷的西南角，坐落在靠近通往黑石山通道的岩石山麓旁。",al={"黑炭谷位置","黑炭谷在哪里"}}},fp="14,199,18.416.0,33.139.0,32.137.0"}
P.entries["subzone:blackfathom-deeps"] = {n="黑暗深渊",s="黑暗深渊是一处被淹没的地下神殿遗迹，埋藏在灰谷西北海岸的佐拉姆海岸之下。这里曾经是一座供奉月亮女神艾露恩的辉煌殿堂，但如今其被淹没的大厅已被纳迦、萨特和邪恶的暮光之锤教派所占据。",h="黑暗深渊是一处被淹没的地下神殿遗迹，埋藏在灰谷西北海岸的佐拉姆海岸之下。这里曾经是一座供奉月亮女神艾露恩的辉煌殿堂，但如今其被淹没的大厅已被纳迦、萨特和邪恶的暮光之锤教派所占据。",kw={"阿库麦尔","黑暗深渊","深渊","加摩拉","克尔里斯","萨利维丝","暮光之锤","佐拉姆海岸"},ang={["faction:Horde"]="对于部落来说，深渊的位置距离佐拉姆加前哨站近得令人不安；聚集在佐拉姆海岸的教徒和纳迦对该前哨站的守卫者构成了不可忽视的威胁。",["race:NightElf"]="对于卡多雷来说，这座古老神殿的亵渎是一件深重的伤痛，他们哀悼曾经神圣的艾露恩祭坛及其月亮井被虚空教徒和纳迦所玷污。"},sec={{t="从艾露恩的神殿到至暗深渊",b="在一万年前大分裂摧毁古老的卡利姆多之前，这座建筑群是一座供奉月亮女神艾露恩的神殿，并配有属于自己的月亮井。当永恒之井崩塌时，这座圣殿沉入海浪之下，人们一度认为它永远消失了。历经数千年，海岸线的退缩和地壳的变动使得其遗迹部分淹没在灰谷的悬崖之下。"},{t="阿库麦尔与邪教",b="近年来，一股上古之神的腐蚀力量从大地深处渗出，玷污了神殿内神圣的月亮井，而作为上古之神仆从的恐怖三头多头蛇阿库麦尔也从水中苏醒。在梦游者克尔里斯的指挥下，暮光之锤教派在被淹没的废墟中建立了一个据点。他们与萨利维丝率领的纳迦以及四处游荡的萨特一起，为了力量而将无辜者献祭给阿库麦尔。"}},faq={{q="黑暗深渊最初是为何而建？",a="它原本是一座供奉月亮女神艾露恩的暗夜精灵神殿，中心有一口神圣的月亮井，在大分裂期间沉入波涛之下。",al={"黑暗深渊历史","黑暗深渊是什么","黑暗深渊神殿"}},{q="为什么暮光之锤教派会在这里？",a="暮光之锤来到这里是为了崇拜阿库麦尔，这是一头原始的多头蛇，也是一位上古之神的仆从。在梦游者克尔里斯的领导下，教派成员为了换取黑暗力量，将无辜者献祭给这头野兽。",al={"为什么邪教徒在黑暗深渊","暮光之锤黑暗深渊","克尔里斯的目标"}},{q="入口在哪里？",a="入口隐藏在佐拉姆海岸沿线的洞穴废墟中，位于灰谷最西北的海岸上。冒险者必须穿过淹没的房间和充满敌意的纳迦前哨站，才能到达神殿的入口。",al={"黑暗深渊在哪里","黑暗深渊位置","如何进入黑暗深渊"}},{q="加摩拉是谁？",a="加摩拉是一只巨大的疯狂海龟，潜伏在神殿某个被淹没洞穴的小岛上，会攻击任何靠近的入侵者。",al={"巨型海龟首领","加摩拉背景故事","黑暗深渊乌龟"}}},fx={f0315c0b={q="黑暗深渊是什么地方？",a="黑暗深渊是一处被淹没的地下遗迹，位于灰谷海岸的佐拉姆海岸之下。它曾是一座辉煌的暗夜精灵神殿，供奉月亮女神艾露恩，在大分裂期间破碎并沉入海底。如今，部分淹没的殿堂和海底洞穴组成了一处黑暗的庇护所，被邪教徒、古老野兽和上古之神的邪恶仆从占据。",al={"黑暗深渊是什么","黑暗深渊概况","介绍黑暗深渊"}},["11da3285"]={q="黑暗深渊发生过什么？",a="很久以前，暗夜精灵在此建起供奉艾露恩的神殿，其中设有圣池和月亮井。一万年前，大分裂撕裂了卡利姆多，将这处圣所沉入波涛之下。这里一度被认为永远消失了，但上古之神的腐化已渗入月亮井，吸引邪恶势力重返这片无光废墟，唤醒远古的恐怖。",al={"黑暗深渊的历史","这里发生过什么","拉萨拉扎尔的历史"}},e07691c2={q="谁居住在黑暗深渊？",a="沉没的神殿由暮光之锤邪教掌控，首领是梦游者克尔里斯。他在此举行黑暗仪式和血祭，侍奉隐于暗处的主宰。与邪教徒共处的还有萨利维丝麾下的蛇形娜迦、被古老力量吸引而来的堕落萨特，以及水生怪物，其中最强大的便是阿库麦尔——一头为上古之神效命的巨型多头蛇。",al={"谁住在这里","谁控制着黑暗深渊","黑暗深渊里有谁"}},bfbbd665={q="黑暗深渊为何沦为废墟？",a="一万年前，大分裂期间永恒之井爆炸，神殿因此毁灭。这场灾变撕裂了大陆，汹涌的海水将神殿建筑群淹没，月亮井也随之沉入水底，宏伟的建筑最终化为黑暗的水下洞穴群。",al={"这里为何沦为废墟","黑暗深渊为何沉入水底","这里为何被毁"}},e7974e12={q="黑暗深渊危险吗？",a="这里极其危险。深处的狂热邪教徒会在亵渎的仪式中屠杀俘虏，以增强阿库麦尔的力量。这头原始巨兽一旦苏醒，便会给卡利姆多带来混乱。闯入者必须穿越被狂暴水生野兽巡游的水淹隧道，还要面对残忍的娜迦法师、狡诈的萨特，以及为掩盖仪式而杀死任何外来者的邪教徒。",al={"黑暗深渊安全吗","黑暗深渊有多危险","黑暗深渊的危险"}}},fp="17,290,36.395.0,20.451.1,48.156.0,39.190.0,30.228.0,17.140.0"}
P.entries["subzone:blackrock-mountain"] = {n="黑石山",s="黑石山是一座高耸于燃烧平原和灼热峡谷之间的巨大活火山。它源于炎魔拉格纳罗斯那毁天灭地的召唤仪式，其深处盘踞着古老的矮人石工、交战的军队以及闷烧的恐怖存在。",h="黑石山是一座高耸于燃烧平原和灼热峡谷之间的巨大活火山。它源于炎魔拉格纳罗斯那毁天灭地的召唤仪式，其深处盘踞着古老的矮人石工、交战的军队以及闷烧的恐怖存在。",kw={"黑石山","黑石塔","燃烧平原","奥格瑞姆毁灭之锤","拉格纳罗斯","灼热峡谷","暗炉城","索瑞森"},ang={["faction:Horde"]="对于现代部落而言，黑石塔是他们过去在Doomhammer统治下遭受奴役与血腥岁月的象征，如今那里被拒绝接受萨尔领导的叛变兽人所占据。",["race:Dwarf"]="这座山代表了矮人历史上最黑暗的篇章：黑铁矮人悲剧性的愚行，不仅让他们失去了自由，还在东部王国的土地上留下了难以磨灭的伤痕。"},sec={{t="大灾变般的起源",b="Blackrock Mountain did not exist until the climax of the War of the Three Hammers two and a half centuries ago. Facing annihilation by the united armies of Ironforge and the Wildhammer clan, Sorcerer-Thane Thaurissan reached into the depths of the earth for a weapon. His reckless spell shattered the dimensional barriers and summoned Ragnaros the Firelord into Azeroth. The resulting apocalypse tore the Redridge range apart, gouging out the Searing Gorge and Burning Steppes while thrusting a colossal volcano into the sky. Thaurissan perished in the blast, and the surviving Dark Iron clan was bound into eternal servitude to the Firelord, carving their capital, Shadowforge City, deep within the mountain's roots."},{t="灰烬与鲜血的堡垒",b="在第一次和第二次战争期间，这座山脉有了新的严酷意义。在洗劫暴风城后，Orgrim Doomhammer肃清了暗影议会，并将黑石塔变成了部落的要塞首都。今天，这座山依然是残酷的战场：黑铁矮人和他们的元素主人占据着炽热的深渊，而叛变的黑石氏族兽人、龙人和他们的黑暗主人则盘踞在上方的高塔中。"}},faq={{q="黑石山是如何形成的？",a="它形成于大约250年前的三锤之战期间。索瑞森大帝为了击败敌对的矮人氏族，不顾一切地试图释放地下的深层能量，却意外地召唤了炎魔拉格纳罗斯，引发了一场创造了这座火山的末日爆炸。",al={"黑石山的起源","谁建造了黑石山","火山如何形成"}},{q="为什么它叫黑石山？",a="那个时代的记载并没有说明是谁最先为这座山命名。它的名字与黑石氏族兽人相同：Orgrim Doomhammer的部落在第二次战争期间将黑石塔作为首都，而黑石氏族的残党至今仍盘踞在塔中。",al={"黑石名字由来","以黑石氏族命名"}},{q="谁目前控制着黑石山？",a="这座山正处于一场残酷的冲突之中。受奴役的黑铁矮人在拉格纳罗斯的统治下控制着暗炉城的地下大厅，而黑石氏族的残党和黑龙人则统治着黑石塔的上层堡垒。",al={"谁住在黑石山","谁统治黑石山"}},{q="哪些地区通过黑石山连接？",a="黑石山的内部通道和锁链是连接北面的灼热峡谷和南面的燃烧平原的直接通道。",al={"如何通过黑石山","黑石山连接的地区"}}},fp="18,264,20.717.0,24.433.0,35.292.0,35.258.0,42.259.0,46.154.0"}
P.entries["subzone:blackrock-pass"] = {n="黑石小径",s="黑石小径是一条连接赤脊山北侧悬崖与燃烧平原干旱荒地的山间通道。穿过一扇厚重的铁门，这里标志着宁静的人类腹地与黑铁矮人和黑石兽人危险战区之间的陡然分界。对于任何徒步向北跋涉的疲惫旅人来说，这里是一道艰险且危险的边境线。",h="黑石小径是一条连接赤脊山北侧悬崖与燃烧平原干旱荒地的山间通道。穿过一扇厚重的铁门，这里标志着宁静的人类腹地与黑铁矮人和黑石兽人危险战区之间的陡然分界。对于任何徒步向北跋涉的疲惫旅人来说，这里是一道艰险且危险的边境线。",kw={"黑石兽人","黑石小径","燃烧平原","边境","大门","湖畔镇","赤脊山"},ang={["faction:Alliance"]="对于赤脊山的守卫者和暴风城王国来说，黑石小径是他们永久的恐惧来源，因为它为黑石兽人提供了一条直通南方人类领地的道路。"},sec={{t="焦灼的门槛",b="黑石小径开凿在犬牙交错的山脊之上，是赤脊山与燃烧平原之间的陆路通道。一条坚固的铁门矗立在这片多岩的边界上，将南方山谷中田园诗般的森林与湖泊，与彼端的火山废墟分隔开来。跨过这条界线，就意味着离开了受湖畔镇苦战中的民兵所保护的田园土地，进入了一片布满了火元素、龙人和敌对兽人战帮的开阔荒原。除非是为了前往黑石山那阴影笼罩之地，否则很少有人会徒步穿越此地。"}},faq={{q="黑石小径通往哪里？",a="Blackrock Pass connects the northern border of Redridge Mountains directly into the southern perimeter of the Burning Steppes. It is one of the direct overland gateways linking the southern Alliance territories to the foothills of Blackrock Mountain.",al={"黑石小径通向哪里","黑石小径目的地","从赤脊山到燃烧平原的路径"}},{q="从湖畔镇来的旅行者穿越小径安全吗？",a="不安全。小径以北的土地远比赤脊山周边的丘陵更为致命。燃烧平原上充斥着凶残的黑石兽人、巨大的火元素和黑龙幼龙，对于低等级冒险者和普通过路人来说，这里极其危险。",al={"我可以穿过黑石小径吗","黑石小径危险吗","黑石小径等级要求"}},{q="谁控制着黑石小径？",a="暴风城和部落都没有完全控制这条小径。它依然是一个充满争议、防御薄弱的咽喉要道，两侧不断有黑石兽人和野兽侵袭，山下赤脊山的镇守卫兵对此深感恐惧。",al={"谁拥有黑石小径","黑石小径的卫兵","黑石小径阵营控制权"}}},fp="14,409,20.586.0,31.250.0,58.290.0,28.240.0"}
P.entries["subzone:blackrock-stronghold"] = {n="黑石要塞",s="黑石要塞是一个戒备森严的营地，开凿在燃烧平原北部的岩架之中，位于黑石山入口正外方。它是黑石兽人及其在黑手氏族旗帜下盟友的主要前线驻地。",h="黑石要塞是一个戒备森严的营地，开凿在燃烧平原北部的岩架之中，位于黑石山入口正外方。它是黑石兽人及其在黑手氏族旗帜下盟友的主要前线驻地。",kw={"黑石氏族","黑石要塞","燃烧平原","黑手氏族","雷德·黑手"},ang={["faction:Alliance"]="这座要塞是第二次战争的残酷写照，坐落在距离暴风城王国北部边界仅一步之遥的地方。",["faction:Horde"]="对于萨尔的部落来说，黑石氏族代表了旧部落那段可耻的遗产——一群拒绝荣誉与和平、嗜血且腐化的残党。"},sec={{t="黑手氏族的驻地",b="该要塞蔓延在黑石山下方焦灼的丘陵地带，是黑石氏族在燃烧平原的主要地面基地。与萨尔的部落不同，这些兽人固守着他们好战的遗产，效忠于雷德·黑手以及盘踞在上方黑石塔内的龙人。"},{t="黑石塔前线",b="该要塞既是外部防御工事，也是向赤脊山及邻近人类领土发动进攻的集结地。这座堡垒时刻监视着通往该山的南部入口，挑战任何敢于穿越这片荒芜之地的挑战者。"}},faq={{q="什么是黑石要塞？",a="这是一座位于燃烧平原北部、黑石山外的军事要塞，作为黑石兽人氏族的外部驻地。",al={"这是什么地方","黑石要塞 燃烧平原","什么是黑石要塞"}},{q="这里的兽人对萨尔的部落友好吗？",a="不。黑石要塞的兽人属于黑手氏族，由雷德·黑手领导。他们拒绝萨尔的领导，对联盟和新部落都抱有敌意。",al={"这是部落吗","黑石兽人是部落吗","对部落友好吗"}}},fp="20,275,26.299.0,29.280.0,29.166.0,45.173.0"}
P.entries["subzone:blackthorn-ridge"] = {n="黑棘山",s="黑棘山是一片崎岖、荆棘丛生的山谷，隐藏在贫瘠之地南部，就在剃刀沼泽的正北方。这片区域到处是好斗的刺鬃野猪人，它们守卫着自己带刺的聚落。在高处的山脊之上坐落着兽人萨满布莱恩的营地，守护着一池格外纯净的山泉。",h="黑棘山是一片崎岖、荆棘丛生的山谷，隐藏在贫瘠之地南部，就在剃刀沼泽的正北方。这片区域到处是好斗的刺鬃野猪人，它们守卫着自己带刺的聚落。在高处的山脊之上坐落着兽人萨满布莱恩的营地，守护着一池格外纯净的山泉。",kw={"贫瘠之地","黑棘山","布莱恩","纯净之水","野猪人","剃刀沼泽","刺鬃"},ang={["class:Shaman"]="对于寻求布莱恩指导、希望在严酷干燥的平原中领悟自然水元素纯净之道的部落年轻萨满来说，这座山脊是一处重要的朝圣之地。",["faction:Horde"]="盘踞在山脊上的刺鬃野猪人威胁着穿过南贫瘠之地前往千针石林的部落补给线，这要求往来的商队必须保持时刻警惕。"},sec={{t="荆棘丛生的堡垒",b="黑棘山坐落在剃刀沼泽高耸的藤蔓附近，遍布着浓密而尖锐的荆棘丛。刺鬃野猪人将此地视为祖传领地，利用这些天然屏障伏击外来者，并以此为基地向南贫瘠之地发起突袭。尽管危险重重，旅行者们还是会寻找隐居的兽人萨满布莱恩，他住在山脊上方的一个营地里，守护着一口因其极佳的清澈度和精神纯净度而闻名整个卡利姆多的泉水。"}},faq={{q="黑棘山在哪里？",a="黑棘山位于贫瘠之地的最南端，正好处于围绕着剃刀沼泽的巨大荆棘丛之北，陶拉祖营地之南。",al={"黑棘山位置","黑棘山在哪里","如何找到黑棘山"}},{q="谁住在黑棘山？",a="山谷底部满是敌对的刺鬃野猪人。在荆棘丛上方高耸的岩石栖息处，住着兽人萨满布莱恩，他守护着附近的那个山泉。",al={"黑棘山住着谁","黑棘山的居民","黑棘山野猪人"}},{q="布莱恩营地下方的水池有什么特别之处？",a="尽管被干旱的平原和野猪人荆棘丛所带来的腐化所包围，但隐藏在山脊下的这口水池却拥有异常纯净、清澈的水，这使其成为了萨满祭司进行仪式的一处神圣的自然焦点。",al={"布莱恩水池","黑棘山之水","黑棘山泉水"}}},fx={a60eac08={q="黑棘山是什么地方？",a="黑棘山是位于南贫瘠之地南部的一处崎岖山谷，谷中荆棘丛生，就在被称为剃刀沼泽的大型野猪人据点以北。这里因高耸于山谷之上的山脊而得名，巨大的荆棘在干旱的岩石间盘绕。它是当地野猪人部族盘踞的前哨，与开阔的平原隔绝。",al={"黑棘山是什么地方","黑棘山概况","介绍黑棘山"}},["4cf5ece9"]={q="黑棘山危险吗？",a="是的，对毫无防备的旅人来说，这里极其危险。谷底和周边小路上遍布敌对的钢鬃野猪人，他们守卫着通往剃刀沼泽的道路。除了一个名叫 Brine、驻扎在高脊上的孤立兽人萨满外，这片荆棘丛中没有友方据点，也没有安全的通道。",al={"黑棘山安全吗","黑棘山的危险","黑棘山有多危险"}}},fp="16,345,22.491.0,26.152.0,30.187.0,45.233.0"}
P.entries["subzone:blackwolf-river"] = {n="黑狼河",s="黑狼河是一条发源于峭壁湖，流经石爪山脉的狂风峭壁的水道。它曾经是一条清澈的山间溪流，但如今其水质已因荆棘谷地精激进的伐木和工业运作而遭到严重污染。",h="黑狼河是一条发源于峭壁湖，流经石爪山脉的狂风峭壁的水道。它曾经是一条清澈的山间溪流，但如今其水质已因荆棘谷地精激进的伐木和工业运作而遭到严重污染。",kw={"黑狼河","峭壁湖","伐木","污染","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="荆棘谷地精的木材开采作业对黑狼河的亵渎，是对塞纳里奥议会以及所有尊崇卡利姆多原始水域的人们的一种严重冒犯。",["race:Tauren"]="看到土地受损，水源被这些唯利是图的入侵者玷污，更加坚定了牛头人清除石爪山脉这种鲁莽工业毒害的决心。"},sec={{t="工业径流",b="黑狼河从峭壁湖流出，穿过狂风峭壁的盆地。这条本应纯净的高山支流，却成为了地精无节制开采的牺牲品。随着荆棘谷地精利用重型机械和圆锯清理周边的林地，淤泥、石油和伐木废料源源不断地渗入河水之中。这条被破坏的河流生动地展示了商业掠夺对石爪山脉荒野的威胁。"}},faq={{q="黑狼河的发源地和流向在哪里？",a="这条河流从高山之巅的峭壁湖流出，蜿蜒穿过狂风峭壁的伐木盆地。",al={"黑狼河源头","黑狼河在哪里","黑狼河位置"}},{q="为什么河水会被污染？",a="荆棘谷地精在整个狂风峭壁地区进行大规模的森林砍伐和机械伐木作业。他们蒸汽机械产生的径流、废料以及清理伐木产生的垃圾直接排入了水道。",al={"黑狼河为什么脏","黑狼河污染","荆棘谷地精污染"}},{q="目前是谁在河流沿岸运作？",a="荆棘谷地精占据了河岸，尽管遭到当地野生生物和原住民的抵制，他们仍利用周边的山谷进行重型木材采伐和机械作业。",al={"谁控制了黑狼河","黑狼河有哪些人","黑狼河附近的敌人"}}},fx={d14d2651={q="黑狼河有着怎样的历史？",a="黑狼河曾清澈地流经石爪山脉腹地，从峭壁湖发源，穿过狂风峭壁。荆棘谷地精将重工业迁入峭壁后，这种平衡便被打破。他们肆意砍伐森林，并使用机械伐木，很快就污染了水道，将原本纯净的山间溪流变成了被毒污泥堵塞的工业废水。",al={"黑狼河的传说","黑狼河的历史","黑狼河发生了什么"}},["476e6164"]={q="黑狼河危险吗？",a="是的，河水和河岸都暗藏严重危险。河水裹挟着上游荆棘谷地精伐木作业排放的有毒工业废水。此外，周围的峭壁上遍布荆棘谷地精的工人、伐木工和机械粉碎机；他们严密守卫机器，肆意砍伐树木，根本不顾及路过的人。",al={"黑狼河安全吗","黑狼河的危险","黑狼河有哪些危险"}}},fp="15,259,17.458.0,46.133.0,32.203.0,43.194.0"}
P.entries["subzone:blackwood-den"] = {n="黑木洞穴",s="黑木洞穴是一个被腐蚀的熊怪营地，坐落在黑海岸南部边缘，靠近灰谷的边界。这里曾经是一处宁静的住所，但如今洞穴和周围的营地已与黑木部族的其他成员一样陷入了疯狂。一位名叫沃科尔的暗夜精灵侦察兵被困在洞穴中，正等待着来自奥伯丁的援助。",h="黑木洞穴是一个被腐蚀的熊怪营地，坐落在黑海岸南部边缘，靠近灰谷的边界。这里曾经是一处宁静的住所，但如今洞穴和周围的营地已与黑木部族的其他成员一样陷入了疯狂。一位名叫沃科尔的暗夜精灵侦察兵被困在洞穴中，正等待着来自奥伯丁的...",kw={"灰谷","奥伯丁","黑木洞穴","黑木据点","黑海岸","熊怪","沃科尔"},ang={["class:Druid"]="德鲁伊们哀悼着熊怪的堕落，他们曾经是荒野坚定的守护者，而黑木洞穴的疯狂被视为卡利姆多被污染这一本质的又一痛苦症状。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，黑木部族因腐蚀而堕落是一件悲剧，将沃科尔从他们的魔爪中救出是一项紧迫的职责，以确保他们的人民在南部道路上的安全。"},sec={{t="被腐蚀的据点",b="Situated near the southern border where Darkshore meets Ashenvale, Blackwood Den consists of a winding network of crude camps and a rocky cave. The Blackwood furbolgs who dwell here have succumbed to the pervasive corruption gripping the region, turning violently hostile toward outsiders. Deep inside the den's cave, the night elf Volcor remains pinned down and endangered by the aggressive tribe, desperately needing assistance from scouts and travelers dispatched from Auberdine."}},faq={{q="什么是黑木洞穴？",a="黑木洞穴是一个熊怪聚落和洞穴综合体，位于黑海岸的最南部，靠近灰谷边界。它是被腐蚀的黑木熊怪部族的据点。",al={"什么是黑木洞穴","黑木据点","黑木洞穴在哪里"}},{q="谁被困在黑木洞穴里？",a="洞穴里困着沃科尔，他是一名被困在敌后的暗夜精灵。遇到他的旅行者必须与奥伯丁的盟友配合，组织逃生并引导他安全离开洞穴。",al={"谁被困在洞穴里","谁是沃科尔","黑木洞穴里的精灵"}},{q="为什么这里的熊怪怀有敌意？",a="黑木熊怪已成为第三次战争后蔓延在黑海岸和卡利姆多的黑暗腐蚀的受害者。这种折磨使他们陷入了疯狂，导致他们攻击视线内的任何外来者。",al={"为什么黑木熊怪具有攻击性","黑木熊怪是邪恶的吗","黑海岸受腐蚀的熊怪"}}},fx={["9f3b6295"]={q="黑木洞穴发生过什么？",a="黑木洞穴曾是黑木熊怪部族在黑海岸南部的普通聚居地。然而，这里的熊怪与当地大部分野生动物和原住部族一样，都成了蔓延于这片土地的黑暗腐化的受害者。他们背弃了往日的平和，变得极具攻击性，建立起防御营地，并设下陷阱，捕捉胆敢靠近洞穴的外来者。",al={"黑木洞穴的历史","黑木洞穴发生了什么","黑木洞穴的故事"}},d219a6ba={q="谁住在黑木洞穴？",a="黑木熊怪占据着洞穴及周边营地，并凶狠地抵御任何闯入者。一名名叫 Volcor 的暗夜精灵不幸被困在洞穴深处，遭敌对的熊怪逼入绝境，只能等待勇敢的救援者杀入洞穴。",al={"谁住在黑木洞穴","黑木洞穴的居民","谁占据着黑木洞穴"}},["3aa28176"]={q="黑木洞穴危险吗？",a="是的，这里非常危险。黑木熊怪在洞口外和洞穴内部都设有数处相互毗邻的营地。他们受到腐化，性情暴戾，会成群结队地袭击所有外来者。贸然深入洞穴，尤其是前去营救被困的暗夜精灵 Volcor，若不做好周密准备，必将凶险万分。",al={"黑木洞穴危险吗","黑木洞穴的危险","黑木洞穴有多危险"}},f77a0955={q="黑木洞穴为什么叫这个名字？",a="洞穴以在此定居的黑木熊怪部族命名。它位于黑海岸南部、靠近灰谷边界之处；洞穴及周边营地是这个遭受腐化的部族的核心洞穴和庇护所。",al={"黑木洞穴为何得名","黑木洞穴名称的含义","黑木洞穴的名字从何而来"}}},fp="13,344,22.482.0,22.186.0,40.208.0,34.231.0"}
P.entries["subzone:blackwood-lake"] = {n="黑木湖",s="黑木湖是位于东瘟疫之地南部的一片受污染的水域，到处都是充满敌意且腐化的元素生物。这片区域被战争与悲剧的记忆所笼罩，银色黎明在此处设有一座小型前线营地，守护着这片土地。",h="黑木湖是位于东瘟疫之地南部的一片受污染的水域，到处都是充满敌意且腐化的元素生物。这片区域被战争与悲剧的记忆所笼罩，银色黎明在此处设有一座小型前线营地，守护着这片土地。",kw={"黑木","达隆郡","元素生物","霍古斯","湖泊","瘟疫之地"},ang={["class:Paladin"]="黑木湖周围受污染的水域和腐朽的气息，鲜明地展现了导致洛丹伦自然元素腐化的枯萎病，需要圣光的净化。",["race:Human"]="对于洛丹伦的人类来说，黑木湖是一个苦涩的提醒，让他们想起天灾军团是何等彻底地毒害了这片王国的腹地。"},sec={{t="被污染的记忆",b="和东维尔德的大部分地区一样，黑木湖也受到了猖獗的亡灵瘟疫的毒害。患病且污秽的水元素在浑浊的湖面下翻涌，攻击任何靠近岸边的人。"},{t="逝者的遗物",b="湖中还埋藏着达隆郡之战留下的阴森遗物。根据《达隆郡全史》等当地史料记载，天灾军团督军毁灭者霍古斯的头颅在被砍下后，被投入了黑木湖污浊的深处。附近，一名银色黎明军医正在一个小型的先遣哨站照料伤兵，在天灾军团的破坏阴影下艰难地维持着士兵们的生命。"}},faq={{q="什么生物潜伏在黑木湖中？",a="湖中遍布着被腐化的水元素。和瘟疫之地大部分的淡水一样，湖水受到了死灵法术径流和污秽的影响，将当地的灵魂扭曲成了狂暴且带有毒性的实体。",al={"水里有什么","湖中怪物","黑木湖中的元素生物"}},{q="银色黎明为什么驻扎在湖边？",a="银色黎明在湖边维持着一个小型的野战营地，一名银色黎明军医在那里照料受伤的步兵。它是为在达隆郡和附近天灾军团据点之间的道路上巡逻作战的部队所设立的紧急救护站。",al={"银色黎明营地","银色黎明军医","为什么这里有士兵"}},{q="什么达隆郡遗物被埋在黑木湖中？",a="根据《达隆郡的历史》记载，在达隆郡之战中作为主要天灾军团首领之一的毁灭者霍古斯，在被击败后，他的头颅被投入了湖水深处。",al={"毁灭者霍古斯的头颅","湖中的任务物品","达隆郡的历史湖泊"}}},fp="14,243,17.215.0,20.414.1,38.219.0,45.229.0,51.203.0"}
P.entries["subzone:bladefist-bay"] = {n="刃拳海湾",s="刃拳海湾是杜隆塔尔东部沿海的一段崎岖海岸，就在Gates of Orgrimmar外。这座海湾以卡加斯·刃拳的名字命名，面向无尽之海，周围有嶙峋的悬崖和附近的艾萨拉南岸。",h="刃拳海湾是杜隆塔尔东部沿海的一段崎岖海岸，就在Gates of Orgrimmar外。这座海湾以卡加斯·刃拳的名字命名，面向无尽之海，周围有嶙峋的悬崖和附近的艾萨拉南岸。",kw={"海湾","刃拳","杜隆塔尔","无尽之海","卡加斯","奥格瑞玛","shattered hand","骷髅石"},ang={["class:Rogue"]="Shattered Hand作为Horde的盗贼和刺客公会，在奥格瑞玛的阴影中运作，这使得这片海岸对隐秘行动人员来说有着一种静谧的共鸣。",["race:Orc"]="这座海湾承载着卡加斯·刃拳这个引以为傲而又残酷的名字，提醒着人们Shattered Hand氏族在Draenor所经历的试炼。"},sec={{t="无尽之海边的一座海湾",b="刃拳海湾沿着杜隆塔尔的东北边缘延伸，直接通向广阔的无尽之海。它两侧是岩石峭壁和危险的浪潮，位于奥格瑞玛主城的东面。正北方向，艾萨拉古老的红色悬崖和废墟在水对面隐约可见，使这座海湾成为了杜隆塔尔重要的海上边界。"},{t="Shattered Hand的阴影",b="这座海湾是为了纪念卡加斯·刃拳，他是著名的Shattered Hand氏族酋长，在Draenor旧Horde的试炼中，他砍下了自己的手并换成了一把利刃。这座海湾靠近骷髅石等地点（邪教徒和隐秘的潜行者网络在那里暗中活动），这呼应了这位赋予海湾名字的酋长所领导的氏族那种凶猛而无情的传统。"}},faq={{q="刃拳海湾是以谁的名字命名的？",a="这座海湾是以卡加斯·刃拳的名字命名的，他是传说中的Shattered Hand氏族酋长，因将断手换成致命的镰刀利刃而闻名。",al={"谁是刃拳","刃拳的名字由来","卡加斯刃拳海湾"}},{q="刃拳海湾位于哪里？",a="它位于杜隆塔尔的东北海岸，就在奥格瑞玛正门的东面，隔水与南边的艾萨拉相对。",al={"刃拳海湾位置","刃拳海湾在哪里","如何前往刃拳海湾"}},{q="刃拳海湾周围潜伏着什么威胁？",a="海岸线紧邻骷髅石，这是一个臭名昭著的洞穴，窝藏着术士、恶魔和邪恶的火刃氏族邪教徒。",al={"刃拳海湾的危险","刃拳海湾的敌人"}},{q="为什么这座海湾有时被称为垃圾堆？",a="那个时代的记录并没有这样称呼它。刃拳海湾只是奥格瑞玛东部杜隆塔尔海岸的一段岩石区域，向北隔水眺望艾萨拉。",al={"垃圾堆","刃拳漂浮物","海洋垃圾湾"}}},fx={["6e8d698f"]={q="刃拳海湾是什么地方？",a="刃拳海湾是无尽之海沿岸的一处海湾，位于杜隆塔尔东北岸，处在奥格瑞玛以东、艾萨拉以南。",al={"刃拳海湾是什么地方","杜隆塔尔的刃拳海湾","关于刃拳海湾"}}},fp="13,244,22.354.0,28.387.0,33.157.0,31.129.0,39.148.0,46.162.0"}
P.entries["subzone:bloodfen-burrow"] = {n="鲜血沼泽墓穴",s="鲜血沼泽墓穴是位于尘泥沼泽西南部的一个洞穴，里面挤满了凶猛的迅猛龙。这些野兽占据了洞穴和周围的空地，彻底摧毁了一处曾经试图在这片湿地中生存的定居点遗迹。",h="鲜血沼泽墓穴是位于尘泥沼泽西南部的一个洞穴，里面挤满了凶猛的迅猛龙。这些野兽占据了洞穴和周围的空地，彻底摧毁了一处曾经试图在这片湿地中生存的定居点遗迹。",kw={"鲜血沼泽墓穴","鲜血沼泽迅猛龙","科泰罗的谜题","尘泥沼泽","迅猛龙洞穴"},ang={["class:Hunter"]="这里筑巢的鲜血沼泽迅猛龙是凶猛敏捷的野兽，非常适合那些寻找耐用、具有攻击性的沼泽同伴的猎人。"},sec={{t="掠食者的巢穴",b="鲜血沼泽墓穴坐落在尘泥沼泽的西南部，是该地区充满攻击性的鲜血沼泽迅猛龙的主要巢穴。洞口和周围的洼地到处都是迅猛龙群，它们被这处隐蔽的裂缝以及沼泽提供的丰富猎场所吸引。入口外散落着废墟和未知的定居点残骸，这冷酷地提醒着人们谁才是沼泽内部真正的主宰。旅行者们还私下传言，一位名叫科泰罗的冒险海盗将他的一条藏宝谜题线索留在了这个致命的巢穴中。"}},faq={{q="鲜血沼泽墓穴里住着什么？",a="这个墓穴被鲜血沼泽迅猛龙所占据。它们在洞穴内和周围的空地上建立了密集的筑巢地，攻击任何胆敢擅闯它们领地的愚蠢之徒。",al={"谁住在这里","鲜血沼泽墓穴迅猛龙","鲜血沼泽墓穴有什么怪物"}},{q="洞穴外面的废墟是什么？",a="洞穴外躺着一处无法辨认的定居点遗迹。迅猛龙摧毁了这个定居点，但其居住者的身份和命运并无记载。",al={"尘泥沼泽废墟定居点","谁建造了鲜血沼泽墓穴附近的棚屋","洞穴外的废墟"}},{q="为什么冒险者要搜寻鲜血沼泽墓穴？",a="除了猎杀凶猛的沼泽迅猛龙外，正在破解科泰罗的谜题的探险家们也必须冒险进入墓穴。这位海盗将他的一条谜题线索藏在了洞穴阴暗的深处。",al={"科泰罗的谜题鲜血沼泽","鲜血沼泽墓穴宝藏","鲜血沼泽墓穴任务"}}},fp="15,244,18.594.0,30.208.0,36.158.0,47.202.1"}
P.entries["subzone:bloodhoof-village"] = {n="血蹄村",s="血蹄村是一处位于莫高雷石牛湖畔的牛头人中心定居点。它以血蹄部族命名，是年轻的猎人和勇士从纳拉其营地出发前往雷霆崖途中遇到的第一个主要聚集点。在贝恩·血蹄的领导下，村庄协调着平原各地的本地防御、贸易和传统仪式。",h="血蹄村是一处位于莫高雷石牛湖畔的牛头人中心定居点。它以血蹄部族命名，是年轻的猎人和勇士从纳拉其营地出发前往雷霆崖途中遇到的第一个主要聚集点。在贝恩·血蹄的领导下，村庄协调着平原各地的本地防御、贸易和传统仪式。",kw={"贝恩·血蹄","血蹄村","纳拉其营地","科多兽","莫高雷","石牛湖","扎尔曼·双月"},ang={["faction:Horde"]="这个宁静的定居点是莫高雷南部平原与部落首都雷霆崖之间重要的中转站和后勤枢纽。",["race:Tauren"]="对于年轻的牛头人来说，进入血蹄村标志着他们从少年步入更广泛的部族责任和精神成熟的真正第一步。"},sec={{t="平原之心",b="血蹄村坐落在清澈的石牛湖畔，是莫高雷中部繁荣的商业、手工艺和庆典中心。在纳拉其营地完成试炼的年轻牛头人会来到这里，在继续前往雷霆崖的巨型台地之前磨练他们的技艺。这里也是耐心饲养野生科多兽作为坐骑的驯兽师们的家园。"},{t="领导与仪式",b="该地区的日常管理和防御工作由大酋长凯恩·血蹄之子，贝恩·血蹄负责。在他的注视下，勇士们被派遣去保卫草原，抵御狂暴的野生动物、刺背野猪人的入侵以及荆棘谷地精带来的阴影威胁。除了贝恩之外，像扎尔曼·双月这样的精神向导也在此照料着部族的内心生活，指引新手完成诸如幻象试炼之类的神圣旅程。"}},faq={{q="谁领导着血蹄村？",a="大酋长凯恩·血蹄之子，贝恩·血蹄领导着该定居点，并指挥其抵御针对中部平原的威胁。",al={"村庄领袖","贝恩·血蹄位置","谁负责血蹄村"}},{q="这里举行什么重大仪式？",a="像扎尔曼·双月这样的精神导师会指引年轻的牛头人完成传统的幻象试炼，这是通往成年之路必不可少的精神旅程。",al={"幻象试炼","精神试炼","扎尔曼·双月任务"}},{q="这个定居点以生产什么而闻名？",a="血蹄村是驯化和训练平原野生科多兽作为坐骑的主要枢纽。",al={"牛头人坐骑","科多兽驯化","血蹄战鼓"}},{q="旅行者在这里完成任务后去哪里？",a="一旦他们在莫高雷中部的任务完成，旅行者通常会被指引向北前往牛头人的主城——雷霆崖。",al={"血蹄村之后","离开血蹄村后去哪里","下一个枢纽"}}},fx={["0d479a74"]={q="血蹄村是什么地方？",a="血蹄村是牛头人在莫高雷中部的重要聚居地，坐落于石牛湖岸边。它是旅人和年轻勇士从红云台地北上前往雷霆崖途中主要的驿站与交通枢纽。牛头人在此交易、寻求灵性指引，并驯服野生科多兽作为坐骑。",al={"血蹄村是什么地方","血蹄村的传说","关于血蹄村"}},["4dcc3235"]={q="血蹄村危险吗？",a="村子本身守卫森严，是一处安全的避风港，由贝恩·血蹄和当地勇士守护。然而，莫高雷周围的平原危机四伏：从四处游荡的掠食者和凶悍的豺狼人，到步步逼近的荆棘谷地精伐木工，以及暗中破坏各部族和平的阴影长矛行动者。",al={"血蹄村的危险","血蹄村安全吗","血蹄村面临的威胁"}},["39f13758"]={q="血蹄村为什么叫这个名字？",a="这个聚居地以血蹄部族命名，以此纪念由大酋长凯恩·血蹄领导的牛头人显赫氏族。村子以氏族之名为荣，并继续由凯恩之子贝恩直接管理。",al={"血蹄村名称的由来","血蹄村为何得名","血蹄村以谁命名"}}},fp="17,379,19.367.0,20.454.0,28.141.0,36.160.0,43.93.0,55.142.0"}
P.entries["subzone:bloodtooth-camp"] = {n="血牙营地",s="血牙营地是位于灰谷中部的一处充满敌意、遭受腐蚀的熊怪营地，坐落在弗伦河以西。在酋长兰·血牙的带领下，这些曾经爱好和平的生物已陷入黑暗的疯狂，攻击任何靠近的人。该营地是联盟斥候旨在净化周边林地的主要目标。",h="血牙营地是位于灰谷中部的一处充满敌意、遭受腐蚀的熊怪营地，坐落在弗伦河以西。在酋长兰·血牙的带领下，这些曾经爱好和平的生物已陷入黑暗的疯狂，攻击任何靠近的人。该营地是联盟斥候旨在净化周边林地的主要目标。",kw={"灰谷","血牙营地","弗伦河","熊怪","克罗格","莱恩的净化","兰·血牙"},ang={["faction:Alliance"]="对于联盟冒险者来说，血牙营地是一个局部的腐蚀热点，威胁着灰谷南部树林和月亮井的安全。",["race:NightElf"]="暗夜精灵将兰·血牙部族的疯狂状态视为他们古老祖地所遭受的严重腐蚀所导致的悲剧性征兆。"},sec={{t="被腐蚀的巢穴",b="血牙营地坐落在南部月亮井的西南方、弗伦河以西，是灰谷日益腐朽的残酷写照。居住在此的熊怪曾与卡利姆多的神圣荒野息息相关，但挥之不去的精神腐蚀已经吞噬了他们的部落。在兰·血牙的指挥下，他们带着狂暴的敌意守护着粗陋的定居点，无论是过往的旅行者还是暗夜精灵守卫都会遭到他们的袭击。"},{t="净化森林",b="由于兰·血牙的团伙对附近的圣地构成了直接威胁，联盟哨兵及其盟友无法对此营地坐视不管。作为恢复森林和谐努力的一部分，即协助莱恩·狼行者的净化工作，克罗格指引冒险者潜入营地，除掉兰·血牙并消灭他那凶残的保镖。"}},faq={{q="血牙营地位于何处？",a="血牙营地位于灰谷中部，弗伦河正西方，就在南部月亮井的西南方。",al={"血牙营地位置","血牙营地在哪里","寻找血牙营地"}},{q="为什么这里的熊怪带有敌意？",a="和灰谷各处的许多熊怪部落一样，血牙部族已成为荒野中挥之不去的黑暗恶魔腐蚀的受害者。这使他们陷入疯狂，并对所有外来者表现出无尽的攻击性。",al={"为什么血牙熊怪会攻击人","血牙腐蚀","这里的熊怪是邪恶的吗"}},{q="谁领导着血牙营地的熊怪？",a="营地由兰·血牙统治，他是一位凶猛的酋长，与他的私人保镖团一同指挥着当地的熊怪。",al={"血牙营地首领","兰·血牙","谁领导血牙营地"}},{q="为什么联盟会派遣斥候来这里？",a="在莱恩的净化工作期间，被流放的熊怪克罗格指引联盟勇士突袭该营地，消灭兰·血牙，并消除他那被腐蚀的追随者对该地区构成的威胁。",al={"血牙营地任务","为什么击杀兰·血牙","克罗格任务"}}},fx={f92ad28e={q="血牙营地是什么地方？",a="血牙营地位于灰谷中部，处在弗伦河以西、一处暗夜精灵圣月亮井的西南方。这里是一个熊怪部族的据点；这些熊怪受到黑暗势力的腐化，如今会猛烈攻击任何踏入其领地的人。",al={"血牙营地是什么地方","血牙营地的传说","灰谷的血牙营地"}},["15670459"]={q="谁住在血牙营地？",a="一支野蛮而遭受腐化的熊怪部族居住在营地中，由 Ran Bloodtooth 率领。他们由忠诚的熊怪护卫和贴身卫士守护。这些曾经和平的生灵视所有外来者为死敌，并以野蛮的敌意守卫营地。",al={"谁住在血牙营地","血牙营地的熊怪","血牙营地的居民"}},["3d0c2137"]={q="血牙营地危险吗？",a="是的，这里极其危险。这里的熊怪深受腐化侵蚀，一发现外来者便会狂暴地发起攻击。踏入营地，就要面对久经战阵的熊怪战士和 Ran Bloodtooth 的贴身卫士，稍有不慎便会招致杀身之祸。",al={"血牙营地危险吗","血牙营地的危险","血牙营地面临的威胁"}},["39c5c848"]={q="血牙营地为什么叫这个名字？",a="营地以聚集于此的遭受腐化的熊怪部族首领 Ran Bloodtooth 命名。他是一位凶悍的酋长，统治着这个部族。",al={"血牙营地为何得名","血牙营地名称的含义","bloodtooth 是谁"}}},fp="15,364,15.448.0,20.375.1,33.131.0,34.213.0,42.131.0,39.222.0"}
P.entries["subzone:bloodvenom-falls"] = {n="血毒瀑布",s="血毒瀑布是一道高耸、污浊的瀑布，从费伍德森林北部腐化的悬崖上倾泻而下。它那充满毒素的流水汇入了血毒河，将恶魔滋生的腐化带下山脉，一直蔓延到下游的土地。",h="血毒瀑布是一道高耸、污浊的瀑布，从费伍德森林北部腐化的悬崖上倾泻而下。它那充满毒素的流水汇入了血毒河，将恶魔滋生的腐化带下山脉，一直蔓延到下游的土地。",kw={"血毒瀑布","血毒河","腐化","黑海岸","费伍德森林","软泥怪","瀑布","急弯河"},ang={["class:Druid"]="血毒瀑布受污染的水流对塞纳里奥议会来说是一个苦涩的景象，它成为了将费伍德森林的邪恶疾病带入下方土地的主要通道。",["race:NightElf"]="对于暗夜精灵来说，看到血毒瀑布汇入黑海岸那条受污染的急弯河，是对其祖居地和海岸避难所的直接威胁。"},sec={{t="腐化的源头",b="血毒瀑布从费伍德森林的峭壁上倾泻而下，是卡利姆多古老森林所遭受的最为触目惊心的创伤之一。这里原本是一道纯净的山涧，但在第三次战争期间，受到恶魔魔法和燃烧军团残党的侵蚀，水流变成了一种充满毒性的污泥。瀑布直接汇入血毒河，蜿蜒流经费伍德森林的中心地带。此后，这股被污染的湍流冲下山坡，在黑海岸变成了污秽的急弯河，将枯萎与凋零带到了费伍德森林那早已受损的边界之外。"},{t="生态毒害",b="来自血毒瀑布的恶性径流不仅仅是让河床变色，它还在扭曲所触及的一切。瀑布喷溅出的水雾周围，沼泽岸边滋生出了扭曲的树妖、病态的野兽和充满攻击性的软泥怪。对于试图遏制费伍德森林腐化的德鲁伊和典狱官来说，这道瀑布是一个令人心寒的警示，提醒着人们卡利姆多北部的水源在其源头处依然深受重创。"}},faq={{q="血毒瀑布的水流向何处？",a="瀑布直接汇入血毒河。这条河流穿过费伍德森林，随后从山上倾泻而下进入黑海岸，在那里变成了受到腐蚀的急弯河。",al={"血毒河的流向","血毒瀑布河流路径","水流向哪里排放"}},{q="为什么瀑布会被腐蚀？",a="在第三次战争期间，燃烧军团的恶魔魔法渗透了该地区，腐化了费伍德森林的野生林地。滋养瀑布的泉水和高山溪流吸收了这种邪能枯萎，使水变成了有毒的淤泥。",al={"为什么血毒瀑布是绿色的","为什么水被毒化了","是什么腐蚀了血毒瀑布"}},{q="瀑布的腐化会影响其他区域吗？",a="是的。水流从费伍德森林倾泻而下，越过西部的山脊进入黑海岸，形成了被污染的急弯河，并将腐化蔓延至海岸方向。",al={"费伍德森林是否污染了黑海岸","它如何影响黑海岸","黑海岸河流污染"}},{q="血毒瀑布的水可以被净化吗？",a="塞纳里奥议会一直在寻找净化费伍德森林的方法，但河水中蕴含的恶魔污染量巨大且浸透深重，使得治愈这道瀑布成为了一项极其艰巨且尚未解决的任务。",al={"德鲁伊能修复血毒瀑布吗","血毒瀑布可以净化吗","清理瀑布"}}},fp="16,219,17.560.0,17.381.0,48.179.0,31.240.0,52.164.0,47.203.0"}
P.entries["subzone:bloodvenom-post"] = {n="血毒岗哨",s="血毒岗哨是一处偏远的部落定居点，坐落在费伍德森林西部的岩石峭壁上，俯瞰着黑海岸。其牛头人风格的建筑和牛头人卫兵在这个饱受恶魔污染和野生生物腐化侵蚀的地区提供了一个立足点。",h="血毒岗哨是一处偏远的部落定居点，坐落在费伍德森林西部的岩石峭壁上，俯瞰着黑海岸。其牛头人风格的建筑和牛头人卫兵在这个饱受恶魔污染和野生生物腐化侵蚀的地区提供了一个立足点。",kw={"血毒岗哨","血毒河","黑海岸悬崖","费伍德森林","部落岗哨","牛头人"},ang={["faction:Horde"]="作为部落在费伍德森林中唯一的坚固避风港，这座营地在极其充满敌意的荒野中提供了安全、住所和行动基地。",["race:Tauren"]="牛头人勇士驻守在此，旨在研究燃烧军团造成的环境破坏，并对抗正在摧毁这片土地自然之灵的腐化。"},sec={{t="危险的立足点",b="血毒岗哨隐藏在黑海岸上方的高耸悬崖边，沿着费伍德森林主干道旁受腐化的血毒河南岸前行即可到达。这座营地采用传统的牛头人帐篷、图腾和岗哨建造，为在凋零森林中探索的部落成员提供了一个至关重要的行动基地。在这里，侦察兵追踪着不断逼近的恶魔势力，研究水域中蔓延的腐化，并试图监控那些因燃烧军团残留力量而变异的敌对野生生物。"},{t="纵览山脊的目光",b="除了观察费伍德森林受到污染的荒野，营地还直接坐落在悬崖边，可以俯瞰黑海岸的北部。其孤立的位置有着双重作用：既能让部落部队随时了解暗夜精灵在西海岸沿线的动向，又能避开穿梭于森林中央道路的联盟巡逻队。"}},faq={{q="血毒岗哨位于何处？",a="血毒岗哨隐藏在费伍德森林中部的西侧山脊上。若要从南北走向的主路前往那里，需沿着血毒河南岸向西走，沿一条蜿蜒绕过岩石山坡的小径前进。",al={"寻找血毒岗哨","如何前往血毒岗哨","血毒岗哨指引"}},{q="谁控制着这座岗哨？",a="血毒岗哨是一座由牛头人守卫、并采用传统牛头人建筑风格的部落岗哨。",al={"谁负责管理血毒岗哨","血毒岗哨阵营"}},{q="为什么这座岗哨叫血毒？",a="它得名于邻近的血毒河，由于渗入森林的恶魔腐化，河水已被玷污并带有毒性。",al={"为什么叫血毒","血毒名称含义"}},{q="这里的侦察兵面临什么威胁？",a="岗哨面临着来自费伍德森林本土腐化生物的持续压力，包括狂暴的豹、受污染的软泥怪和扭曲的树人，此外还有该区域内暗影议会和燃烧军团残党的恶魔威胁。",al={"血毒的敌人","什么袭击血毒岗哨"}}},fp="15,243,21.534.0,21.345.0,33.232.0,26.90.0,33.146.0,37.244.0"}
P.entries["subzone:bloodvenom-river"] = {n="血毒河",s="血毒河是一条穿过费伍德森林中心地带的肮脏水道，这条河流充满了导致这座古老森林枯萎的恶魔腐蚀。其腐臭的河水顺流而下，穿过山脉进入黑海岸，演变成了被污染的急弯河。",h="血毒河是一条穿过费伍德森林中心地带的肮脏水道，这条河流充满了导致这座古老森林枯萎的恶魔腐蚀。其腐臭的河水顺流而下，穿过山脉进入黑海岸，演变成了被污染的急弯河。",kw={"血毒河","腐蚀","黑海岸","费伍德森林","软泥怪","被污染的水","急弯河"},ang={["class:Druid"]="血毒河是卡利姆多神圣森林遭到亵渎的明证，它将邪能腐蚀带到了各个地区，昭示着自然亟需恢复。",["race:NightElf"]="对于卡多雷而言，眼看着他们祖先林地的水流通过急弯河毒害了黑海岸，这时刻提醒着他们燃烧军团留下的伤痛挥之不去。"},sec={{t="腐蚀之脉",b="血毒河贯穿了费伍德森林被腐蚀的核心地带，成为了这片土地精神与物质衰败的开放式导管。河岸边充斥着邪恶的软泥怪、变异的野兽，以及燃烧军团入侵后留下的肮脏径流。河道中的腐蚀性极强，足以污染远超费伍德森林本身的土地，并作为急弯河向西流向黑海岸的沿海森林。"}},faq={{q="为什么河流会被腐蚀？",a="这条河流流经费伍德森林中心，那是一片古老的暗夜精灵森林，在第三次大战期间深受燃烧军团恶魔魔法的扭曲。腐蚀彻底渗透进土地和水流中，将河流变成了充满有毒淤泥和坏死软泥的导管。",al={"血毒河污染","为什么水是绿色的","费伍德森林河流毒素"}},{q="血毒河的流向是怎样的？",a="这条河穿过费伍德森林受污染的山谷，随后穿过山脉流入黑海岸。在山脊之外，其被腐蚀的水流以急弯河的名义继续向下游奔涌。",al={"血毒河路径","它流向哪里","流向黑海岸的河流"}},{q="河岸边生活着哪些生物？",a="水域和泥泞的河岸边栖息着有毒的软泥怪、扭曲的野生动物，以及被致命的恶魔枯萎病所吸引或创造出来的腐化掠食者。",al={"血毒河野生动物","血毒河附近的怪物","河流中的怪物"}}},fp="16,261,20.435.0,27.281.0,37.206.0,41.151.0"}
P.entries["subzone:bluefen"] = {n="蓝色沼泽",s="蓝色沼泽是一片湿漉漉的沼泽地，位于尘泥沼泽北部，紧邻蕨墙村以东。这里不仅潜伏着极具攻击性的湿地掠食者，也成为了塞拉摩渗透者监控当地部落动态的据点。",h="蓝色沼泽是一片湿漉漉的沼泽地，位于尘泥沼泽北部，紧邻蕨墙村以东。这里不仅潜伏着极具攻击性的湿地掠食者，也成为了塞拉摩渗透者监控当地部落动态的据点。",kw={"蓝色沼泽","蕨墙","鳄鱼","尘泥","沼泽","塞拉摩渗透者"},ang={["faction:Alliance"]="尽管野生野兽使旅行变得危险，但塞拉摩侦察兵利用蓝色沼泽茂密的植被，密切监视着附近的食人魔营地。",["faction:Horde"]="蓝色沼泽位于蕨墙村以东，对部落勇士构成了双重威胁：凶猛的沼泽野兽，以及监视你们的石槌盟友的警惕的塞拉摩渗透者。"},sec={{t="充满争议的沼泽",b="蓝色沼泽位于蕨墙村的石槌食人魔据点以东，体现了尘泥沼泽未被驯服的危险特质。这片潮湿的沼泽地里到处都是掠食性野兽，包括迅猛龙、巨型蜘蛛、食腐鸟类和潜伏的鳄鱼。除了自然界的掠食者，旅行者还必须提防那些在阴暗地形中潜行、监视部落并试图将人类影响力深入沼泽地带的塞拉摩渗透者。"}},faq={{q="蓝色沼泽位于何处？",a="蓝色沼泽位于尘泥沼泽北部，就在蕨墙村以东。",al={"蓝色沼泽位置","蓝色沼泽在哪里","蓝色沼泽地图"}},{q="在蓝色沼泽能遇到什么威胁？",a="这片沼泽到处都是危险的野生动物，包括蜘蛛、鳄鱼、迅猛龙和沼泽鸟类。此外，隐秘的塞拉摩渗透者也会在此巡逻，对部落的旅行者构成威胁。",al={"蓝色沼泽敌人","蓝色沼泽有什么生物","蓝色沼泽怪物"}},{q="为什么塞拉摩侦察兵会出现在蓝色沼泽？",a="塞拉摩渗透者以蓝色沼泽为据点，监视着尘泥沼泽北部，观察邻近的蕨墙村石槌食人魔定居点，并巡逻着沼泽中充满争议的道路。",al={"塞拉摩渗透者","为什么联盟会在这里","塞拉摩间谍"}}},fp="7,259,15.437.0,25.85.0,37.198.0,43.196.0"}
P.entries["subzone:bluegill-marsh"] = {n="蓝腮沼泽",s="蓝腮沼泽是位于湿地西部的一片泥泞沼泽，是敌对的蓝腮鱼人部落大举定居的地方。这些水栖人形生物在被称为“戈布勒”的野蛮首领统治下，对水道和棚屋进行了严密的防御。前往西部沼泽的旅行者必须小心穿行，以免被困在浅滩中遭到包围。",h="蓝腮沼泽是位于湿地西部的一片泥泞沼泽，是敌对的蓝腮鱼人部落大举定居的地方。这些水栖人形生物在被称为“戈布勒”的野蛮首领统治下，对水道和棚屋进行了严密的防御。前往西部沼泽的旅行者必须小心穿行，以免被困在浅滩中遭到包围。",kw={"蓝腮","蓝腮沼泽","戈布勒","米奈希尔","鱼人","沼泽","湿地"},ang={["faction:Alliance"]="由于地理位置距离米奈希尔港不远，好战的蓝腮鱼人对穿过湿地西部的旅行者和补给线构成了持续的麻烦。"},sec={{t="蜂拥而至的威胁",b="蓝腮沼泽坐落在湿地西部的泥泞平原之中，这里到处都是淤泥、芦苇，以及当地鱼人刺耳的战吼声。蓝腮部落在死水中建立了粗糙的原始营地，宣称这片领土属于他们。与沼泽中那些孤立的野兽不同，这些鱼人以紧密的群体为单位生活和狩猎。米奈希尔港的谨慎游侠和侦察兵都知道，贸然进入他们的领地会引来四面八方的迅速伏击，尤其是当强大的首领戈布勒在浑浊的浅滩中徘徊时。"}},faq={{q="蓝腮沼泽是什么地方？",a="蓝腮沼泽是湿地西部的一个泥泞子区域。这里是好战的蓝腮鱼人部落的主要居所和筑巢地。",al={"蓝腮沼泽在哪里","这个地方是什么","湿地鱼人沼泽"}},{q="谁在统治这片沼泽？",a="蓝腮部落由一个强大而凶残的鱼人戈布勒领导，他守护着密集的营地，并会击杀任何踏入他们水域的陆行者。",al={"湿地鱼人首领","戈布勒","谁领导蓝腮鱼人"}},{q="为什么独自在此旅行很危险？",a="这里的鱼人很少单独行动。它们通常两三个结成紧密的小队聚集在棚屋和岸边，使得落单的旅行者很容易在深陷减速的泥地中被淹没。",al={"为什么这里有这么多鱼人","蓝腮沼泽难吗","鱼人仇恨"}},{q="为什么旅行者要冒险进入蓝腮沼泽？",a="来自米奈希尔港等附近定居点的侦察兵和冒险者经常被派往沼泽，以削减好战的鱼人数量，并找回被抢到营地中的货物。",al={"为什么要去这里","蓝腮沼泽任务","访问原因"}}},fx={c61162da={q="蓝腮沼泽为什么叫这个名字？",a="沼泽直接以在其浑浊水域中建立多处营地的蓝腮鱼人命名。他们凶悍的部族盘踞着这里西部的湿地，因此这片区域也以他们的名号而闻名。",al={"蓝腮沼泽为何得名","蓝腮沼泽名称的含义","蓝腮沼泽的名字从何而来"}}},fp="14,361,17.573.0,23.163.0,25.189.0,41.197.0,45.201.0"}
P.entries["subzone:bolgan-s-hole"] = {n="波尔甘的洞穴",s="波尔甘的洞穴是一个位于凄凉之地吉尔吉斯村南面悬崖中的地下洞穴。它是吉尔吉斯半人马部族的圣所，也是其最高酋长和神圣大地圣物的所在地。",h="波尔甘的洞穴是一个位于凄凉之地吉尔吉斯村南面悬崖中的地下洞穴。它是吉尔吉斯半人马部族的圣所，也是其最高酋长和神圣大地圣物的所在地。",kw={"波尔甘的洞穴","半人马","凄凉之地","吉尔吉斯","沙卡可汗","瑟莱德丝之泪"},ang={["class:Shaman"]="这个洞穴残酷地展示了当崇拜大地与瑟莱德丝公主的暴力遗产挂钩，而非与自然的灵魂平衡挂钩时，信仰会如何被扭曲。"},sec={{t="吉尔吉斯的权力中心",b="波尔甘的洞穴开凿在俯瞰吉尔吉斯营地的崎岖峭壁深处，是该部族的Command Center。统治部族的可汗就在这里召集部下，周围环绕着经验丰富的卫兵和部族中最有影响力的萨满祭司。这个洞穴不仅是天然的堡垒，还能抵御敌对部族，尤其是东面嗜血的玛格拉姆半人马。"},{t="大地公主之泪",b="除了军事上的重要性外，这个洞穴对吉尔吉斯人还有着深远的宗教意义。被称为瑟莱德丝之泪的发光蓝色矿物结构从潮湿的岩壁上生长出来。吉尔吉斯萨满狂热地采集并守卫着这些晶体，将其视为神圣的祝福，认为它们能带来半人马种族的原始土元素之母——瑟莱德丝公主的地下庇护。"}},faq={{q="波尔甘的洞穴位于何处？",a="波尔甘的洞穴是一处位于吉尔吉斯村南部的洞穴，隐藏在凄凉之地南部的山丘中。",al={"波尔甘的洞穴位置","波尔甘的洞穴在哪里","波尔甘洞穴入口"}},{q="谁居住在波尔甘的洞穴里？",a="洞穴内居住着吉尔吉斯半人马的高层领导，包括他们的部族可汗——例如沙卡可汗——以及他们的核心护卫和神秘的萨满祭司。",al={"谁在波尔甘的洞穴里","波尔甘的洞穴首领","吉尔吉斯可汗位置"}},{q="洞穴里的发光蓝色晶体是什么？",a="这些晶体被称为瑟莱德丝之泪。吉尔吉斯人将它们视为大地之母恩赐的有形体现，认为这些石头能为拥有它们的人提供神秘的保护。",al={"波尔甘的洞穴里的蓝色晶体","瑟莱德丝之泪","波尔甘的洞穴岩石"}},{q="玩家可以安全地进入波尔甘的洞穴吗？",a="默认情况下，洞穴内的吉尔吉斯半人马对局外人抱有敌意。然而，通过屠杀他们不共戴天的死敌——玛格拉姆部族，与吉尔吉斯人结盟的旅行者可以获得声望，从而得以平静地进入洞穴。",al={"波尔甘的洞穴有敌意吗","吉尔吉斯声望友好","我可以进入波尔甘的洞穴吗"}}},fp="13,217,24.365.0,27.409.0,31.116.0,31.173.0,51.204.0,39.230.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="格拉卡隆之骨",s="格拉卡隆之骨是一具巨大的青铜龙骸骨，在希利苏斯中部的烈日下显得苍白。这头倒下的巨龙在远古的流沙之战中被杀，如今成为了异种虫的阿努比萨斯哨兵们视为神圣的肃穆纪念碑。",h="格拉卡隆之骨是一具巨大的青铜龙骸骨，在希利苏斯中部的烈日下显得苍白。这头倒下的巨龙在远古的流沙之战中被杀，如今成为了异种虫的阿努比萨斯哨兵们视为神圣的肃穆纪念碑。",kw={"阿努比萨斯","格拉卡隆之骨","青铜龙","格拉卡隆","无疤者奥斯里安","希利苏斯","流沙之战"},ang={["race:NightElf"]="这具骸骨是对流沙之战的冷峻提醒，在那场战争中，卡多雷和四大巨龙军团并肩作战，抵御了其拉虫人的猛烈进攻。"},sec={{t="流沙之战的纪念碑",b="在希利苏斯中部风沙肆虐的沙丘上，横卧着格拉卡隆那巨大的肋骨和头骨。这是一头在远古流沙之战中丧生的青铜龙。在那场千年前的天启般冲突中，这头伟大的巨龙被“无疤者”奥斯里安击倒，这是一名被这座城市王国的黑暗力量所提拔的阿努比萨斯战士。对于阿努比萨斯来说，这个战场战利品是他们凌驾于巨龙军团之上的神圣证明，他倒下的地方至今未曾被触动。"}},faq={{q="这些是谁的骨头？",a="这是青铜龙军团中一头伟大的青铜龙——格拉卡隆的遗骸。一千年前，在流沙之战期间，他倒在了对抗安其拉虫族军队的战斗中。",al={"格拉卡隆是谁","哪头龙死在这里","希利苏斯巨龙骸骨"}},{q="谁杀死了格拉卡隆？",a="格拉卡隆是被阿努比萨斯战士“无疤者”奥斯里安所杀。奥斯里安战胜了这头青铜巨龙，为他赢得了巨大的声望以及来自安其拉主宰们的黑暗祝福。",al={"谁杀了那条龙","格拉卡隆是怎么死的"}},{q="为什么阿努比萨斯崇拜这个地方？",a="阿努比萨斯认为这具骨架是神圣的，因为它纪念了他们对一支强大的巨龙军团的决定性胜利。它矗立在开阔的沙丘上，象征着他们在面对那些企图将他们封印的人时所展现出的强大力量。",al={"为什么骨头是神圣的","阿努比萨斯骸骨"}}},fp="19,269,32.494.0,22.205.0,22.185.0,39.228.0"}
P.entries["subzone:booty-bay"] = {n="藏宝海湾",s="藏宝海湾是一座庞大的海盗避风港，修建在荆棘谷南端的陡峭海崖之上，由热砂港的黑水掠夺者负责运营。陆路入口位于一具巨鲨残骸的大张口中，这里作为中立港口受到严密的治安管理，在装备精良的地精打手虎视眈眈的监视下，联盟和部落成员在此和平共处。",h="藏宝海湾是一座庞大的海盗避风港，修建在荆棘谷南端的陡峭海崖之上，由热砂港的黑水掠夺者负责运营。陆路入口位于一具巨鲨残骸的大张口中，这里作为中立港口受到严密的治安管理，在装备精良的地精打手虎视眈眈的监视下，联盟和部落成员在...",kw={"黑水掠夺者","血帆海盗","藏宝海湾","棘齿城","里维加兹","salty sailor tavern","卡拉·海角","热砂港","荆棘谷"},ang={["class:Rogue"]="作为众所周知的无赖天堂，藏宝海湾充斥着地下交易人、销赃者、锁箱和秘密情报贩子，他们随时准备用秘密换取金币。",["faction:Alliance"]="在暴风城受保护的边界以南很远的地方，藏宝海湾为联盟旅行者提供了稀有的中立设施、飞行路线和直达卡利姆多的航线。"},sec={{t="无赖与利润的巢穴",b="最初，这里被称为黑水湾，曾是一处人类定居点，后来被丛林巨魔占领，最终被热砂港的地精夺回。如今，这里是一个国际贸易枢纽，也是无赖、放逐者和商人的避风港。在大财主里维加兹和舰队指挥官卡拉·海角的管理下，他们坐镇在Salty Sailor Tavern的阳台上，这座港口看似无法无天，实则管理严格：只要遵守财团的和平协议并缴纳港口费用，任何人都可以尽情饮酒、交易或雇佣雇佣兵。"},{t="水上的威胁",b="藏宝海湾繁忙的码头将东部王国与横跨无尽之海的棘齿城直接相连，使其成为贸易和跨大陆旅行的重要枢纽。然而，其巨大的财富也引来了不断的敌意。该镇的主要宿敌是血帆海盗，这是一支极具侵略性的海盗舰队，他们不断劫掠黑水港的船只，在荆棘谷海岸巡航，并积极策划彻底摧毁和洗劫这座地精港口。"}},faq={{q="谁统治着藏宝海湾？",a="该港口由热砂港的重要人物大财主里维加兹统治，他与黑水掠夺者的牛头人指挥官舰队指挥官卡拉·海角紧密合作。两人的办公地点都在俯瞰港口的Salty Sailor Tavern上层甲板上。",al={"藏宝海湾领袖","谁掌管藏宝海湾","藏宝海湾老板"}},{q="为什么联盟和部落玩家可以在这里和平共处？",a="藏宝海湾由中立的热砂港控制，该组织将利润和商业置于阵营冲突之上。财团维持着严格的中立性，欢迎任何拥有金币的人，并会对任何胆敢在此挑起争斗的人祭出精锐的地精打手。",al={"为什么藏宝海湾是中立的","藏宝海湾安全区","部落可以在这里攻击联盟吗"}},{q="血帆海盗是什么人？",a="血帆海盗是一个敌对的亡命之徒集团，与黑水掠夺者处于水火不容的战争状态。他们控制着荆棘谷南海岸的船只，并积极策划攻占藏宝海湾，攫取其利润丰厚的港口。",al={"血帆海盗","为什么血帆海盗仇恨藏宝海湾","血帆海盗背景故事"}},{q="藏宝海湾的船只驶向哪里？",a="从下层码头出发的客船横跨无尽之海，直达贫瘠之地的棘齿城港口小镇，这是连接东部王国南部与卡利姆多的主要中立交通路线。",al={"藏宝海湾船只目的地","船去哪里","前往卡利姆多的船"}},{q="海湾入口处伫立的巨大雕像是什么？",a="这座身份不明的地精张开双臂的巨大雕像矗立在港口外侧的加尼罗哨站。它既是导航灯塔，也是欢迎进港商船和海盗船员的地标。",al={"藏宝海湾雕像","藏宝海湾巨像","岛上的雕像"}}},fp="9,361,30.547.0,20.455.0,20.281.0,55.273.0,33.237.0,38.224.0,56.223.0"}
P.entries["subzone:bough-shadow"] = {n="大树荫",s="大树荫是位于灰谷东北角落的一片隐蔽的林地，在林歌神殿的东面。它的中心是一棵巨大的古树，树根盘踞在一个通往翡翠梦境的古老传送门之上。",h="大树荫是位于灰谷东北角落的一片隐蔽的林地，在林歌神殿的东面。它的中心是一棵巨大的古树，树根盘踞在一个通往翡翠梦境的古老传送门之上。",kw={"灰谷","大树荫","龙人","梦境追猎者","翡翠梦境","大树","绿龙","幻影","传送门"},ang={["class:Druid"]="大树荫对德鲁伊来说是神圣的土地，这里有连接艾泽拉斯与绿龙军团领域及翡翠梦境的实体入口之一。",["race:NightElf"]="这棵巨大的古树及其沉睡的传送门位于林歌神殿深处，象征着卡多雷与翡翠梦境之间紧密联系的活生生的见证。"},sec={{t="通往梦境的门户",b="大树荫坐落着罕见的大树之一，其根系深深扎入大地，围绕着一个通往翡翠梦境的天然交汇点。如今，这片宁静而威严的林地由绿龙军团严密把守。幻影和梦境追猎者等翡翠幼龙在树冠上方盘旋，而翡翠龙人巡逻队和先知们则对底部旋转的绿色传送门保持着警惕而坚定的监视，驱逐任何未经许可靠近的凡人。"}},faq={{q="这里发光的绿色传送门是什么？",a="大树根部旋转的漩涡是一个直接通往艾泽拉斯未受干扰的灵界——翡翠梦境的门户。这是散布在世界各地的几个此类天然交汇点之一。",al={"大树荫传送门","大树荫里的传送门是什么","灰谷绿色传送门"}},{q="为什么绿龙要守护大树荫？",a="伊瑟拉的绿龙军团负责守护翡翠梦境及其通往物质世界的直接通道。翡翠幼龙和龙人巡逻大树荫，以确保没有腐化势力或入侵者溜过这个临界点。",al={"为什么灰谷里有龙","绿龙军团 大树荫","为什么绿龙在这里"}},{q="玩家可以进入传送门吗？",a="不能。这个门户对物质世界的凡人来说仍然是严密封闭的，靠得太近会招致周围精英龙族守卫的愤怒。",al={"我可以穿过传送门吗","进入大树荫传送门","如何进入梦境传送门"}}},fx={ca240e18={q="大树荫是什么地方？",a="大树荫是一处僻静的林间空地，位于灰谷东北边缘、林歌神殿以东。它以世界之树之一为中心，并有一座通往翡翠梦境的神秘传送门。",al={"这个地方是什么","大树荫的传说","关于大树荫"}},["626e8e50"]={q="大树荫发生过什么？",a="大树荫坐落着一棵世界之树，其根系覆盖着通往翡翠梦境的传送门之一，绿龙军团严密看守着这里。",al={"大树荫的历史"}},f0692632={q="谁住在大树荫？",a="这片林地完全由绿龙军团成员居住。Phantim 和 Dreamstalker 等幼龙守望着林地，绿龙人巡逻队也在一旁协助，其中包括 Emeraldon Tree Warders、Boughguards 和 Oracles。",al={"这里有谁","谁居住在大树荫","大树荫的居民"}},["30f2c168"]={q="大树荫危险吗？",a="是的，对旅行者来说非常危险。绿龙和它们的龙人哨兵以严密戒备守护着传送门，任何凡人若靠近它们神圣的守卫之地，它们都会毫不犹豫地将其击倒。",al={"大树荫安全吗","大树荫危险"}}},fp="12,221,22.473.0,38.210.0,44.246.0,29.162.0"}
P.entries["subzone:boulder-gor"] = {n="博德戈尔",s="博德戈尔是一座位于阿拉希高地西部的崎岖山丘，坐落在废墟般的人类王国激流堡正北方。它是巨石拳食人魔及其不同寻常的盟友——枯木森林巨魔的活跃营地。",h="博德戈尔是一座位于阿拉希高地西部的崎岖山丘，坐落在废墟般的人类王国激流堡正北方。它是巨石拳食人魔及其不同寻常的盟友——枯木森林巨魔的活跃营地。",kw={"阿拉希高地","博德戈尔","巨石拳","食人魔","激流堡","枯木"},ang={["faction:Alliance"]="对于寻求收复激流堡的联盟军队来说，博德戈尔构成了潜伏在这个陨落王国北门口的严重威胁。",["race:Troll"]="来访高地的暗矛巨魔在这里找不到亲缘关系：博德戈尔的枯木森林巨魔对所有外来者——包括其他巨魔部族——都怀有深远的古老仇恨。"},sec={{t="食人魔与巨魔的巢穴",b="博德戈尔耸立在激流堡破败的城墙以北，是一座被巨石拳氏族占领的陡峭断崖。其阴影中坐落着Boulderfist Outpost土丘，使其成为巨石拳食人魔在整个高地权力的中心堡垒。独特的是，这里的食人魔与枯木部族的森林巨魔共享营火与防御工事，其中包括向氏族的蛮力提供黑暗魔法支持的阴影施法者。这种相互合作对任何路过阿拉希中部道路的旅人构成了持续的威胁。"},{t="周边领地",b="博德戈尔周围的山坡俯瞰着阿拉希西部开阔的高地。博德戈尔被夹在辛迪加渗透的激流堡废墟与平原上狂野的元素之地之间，依然是一个守备森严的敌对据点，展现着部落团结，对抗着联盟和部落的漫游者。"}},faq={{q="什么是博德戈尔？",a="博德戈尔是阿拉希高地激流堡以北的一座高地和营地。这里聚居着大量的巨石拳食人魔和枯木森林巨魔。",al={"博德戈尔在哪里","博德戈尔信息","这是什么地方"}},{q="为什么森林巨魔会和食人魔住在这里？",a="枯木巨魔和巨石拳食人魔在阿拉希维持着一种务实的同盟关系。双方都寻求保持对高地的统治并抵御敌对派系，将巨魔的暗影法术与食人魔的蛮力结合在了一起。",al={"为什么这里有巨魔","枯木食人魔联盟","巨魔与食人魔"}},{q="博德戈尔附近有什么主要地标？",a="博德戈尔位于激流堡的正北方，而Boulderfist Outpost的食人魔土丘就坐落在山丘之中。",al={"附近地点","博德戈尔旁边有什么","地标"}},{q="博德戈尔对部落或联盟友好吗？",a="都不友好。博德戈尔的巨石拳食人魔和枯木巨魔对联盟和部落完全敌对，他们会积极地从外来者手中捍卫自己的山丘。",al={"我可以安全地去那里吗","博德戈尔是敌对的吗"}}},fp="11,249,25.542.0,21.312.0,20.171.0,50.216.0,42.122.0,49.174.0"}
P.entries["subzone:boulder-lode-mine"] = {n="石矿洞",s="石矿洞是一处开凿在贫瘠之地东北部丘陵中的大型矿坑。虽然兽人的旗帜和瞭望塔表明这里最初是由部落建立的，但现在它已经被冷酷无情的荆棘谷地精牢牢掌控并运营。",h="石矿洞是一处开凿在贫瘠之地东北部丘陵中的大型矿坑。虽然兽人的旗帜和瞭望塔表明这里最初是由部落建立的，但现在它已经被冷酷无情的荆棘谷地精牢牢掌控并运营。",kw={"boss copperplug","石矿洞","迪兹维格","矿工的财富","主动式负载平衡器说明书","贫瘠之地","荆棘谷地精"},ang={["faction:Horde"]="看到荆棘谷地精在带有部落标志的防御工事中运作，这令人恼火地提醒着人们这个地精卡特尔组织是如何在卡利姆多土地上激进扩张的。",["profession:Mining"]="深邃的挖掘隧道直接切入干旱的丘陵，露出了丰富的矿脉，荆棘谷地精正在无情地掠夺这些资源。"},sec={{t="企业所有权",b="石矿洞洞口残留的风化兽人建筑表明，部落曾经拥有或建立了这里。然而如今，这里到处都是在Boss Copperplug指挥下工作的荆棘谷地精监工和执行者。为了搜寻珍贵的矿石、高产的宝石和工业机械，这个地精辛迪加组织在峡谷中进行露天开采，完全不顾及当地的生态环境或工人的死活。"},{t="宝石与蓝图",b="石矿洞开采出财富的消息已经传到了棘齿城。码头管理员迪兹维格已经派遣雇佣兵去窃取传说中在矿洞里发现的一颗巨大绿宝石，而那些试图理解复杂地精机械的工程师们也知道，Boss Copperplug将关键的操作手册藏在了他的营地里。"}},faq={{q="谁控制着石矿洞？",a="这座矿井由荆棘谷地精在Boss Copperplug的直接授权下运营，并由全副武装的企业执行者和劳工监工守卫。",al={"谁经营石矿洞","石矿洞首领","谁在石矿洞里"}},{q="部落最初拥有这座矿井吗？",a="幸存的兽人木制结构、瞭望塔和风化的部落旗帜有力地表明，在荆棘谷地精介入并夺取控制权之前，部落最初建立或占领了该地点。",al={"石矿洞的兽人旗帜","部落矿井","为什么会有部落旗帜"}},{q="为什么码头管理员迪兹维格对这个地方感兴趣？",a="迪兹维格听说石矿洞里的一名矿工挖出了一颗异常巨大且珍贵的绿宝石，于是他雇佣了冷酷的自由职业者潜入矿洞，试图将其偷走以分一杯羹。",al={"迪兹维格矿井任务","贫瘠之地绿宝石任务","矿工的财富"}},{q="Boss Copperplug与主动式负载平衡器有什么联系？",a="Boss Copperplug拥有附近发现的神秘主动式负载平衡器机械的基本操作手册，棘齿城的工程师们派遣冒险者从他的手下那里取回这本书及其散页。",al={"石矿洞主动式负载平衡器说明书","copperplug的说明书","里里·格里希戈布矿井"}}},fx={["60cbae83"]={q="石矿洞是什么地方？",a="石矿洞是一处采矿点，坐落在贫瘠之地东北部的 rocky hills 中。洞内有明显的兽人风格木料和旗帜，表明它曾由部落建立，但如今已被荆棘谷地精公司接管。如今，地精监工和雇来的打手在岩层深处疯狂开采，搜寻有价值的矿石和珍贵宝石。",al={"石矿洞是什么","贫瘠之地石矿洞","关于石矿洞"}},["97c77cb5"]={q="谁住在石矿洞，或是谁在经营这里？",a="这座矿洞目前由荆棘谷地精公司占据，由冷酷无情的头目铜插销监管。他负责管理一支劳工队伍，队伍由荆棘谷地精公司的监工和打手看守；他们不断向山体深处开采，同时严密控制专有机械手册和有价值的发现。",al={"谁在经营石矿洞","石矿洞里有谁","石矿洞的居民"}},a11a7920={q="石矿洞危险吗？",a="是的。荆棘谷地精公司不欢迎访客或擅闯者在他们的产业里四处探查。矿洞里到处都是全副武装的打手和警惕的监工；任何威胁他们的权益或企图掠夺洞内珍贵矿脉与宝藏的人，都会遭到攻击。",al={"石矿洞危险吗","石矿洞的危险","荆棘谷地精公司在石矿洞的威胁"}}},fp="17,247,15.464.0,19.338.0,31.159.0,39.200.0,53.201.0,56.212.0"}
P.entries["subzone:boulderfist-hall"] = {n="石拳大厅",s="石拳大厅是一座防御严密的食人魔土丘，坐落在阿拉希高地的南部丘陵中，位于萨多尔大桥以北。它是石拳食人魔当地的据点，在科格雷什·冷怒的指挥下，他们对邻近的贸易路线和山谷施加着残暴的影响力。",h="石拳大厅是一座防御严密的食人魔土丘，坐落在阿拉希高地的南部丘陵中，位于萨多尔大桥以北。它是石拳食人魔当地的据点，在科格雷什·冷怒的指挥下，他们对邻近的贸易路线和山谷施加着残暴的影响力。",kw={"阿拉希高地","石拳","石拳大厅","科格雷什·冷怒","食人魔土丘","法拉纳克斯","萨多尔大桥"},ang={["faction:Alliance"]="由于石拳食人魔的位置恰好在萨多尔大桥上方，他们对从铁炉堡向北进入阿拉希的联盟信使和增援部队构成了持续的伏击威胁。",["faction:Horde"]="确保阿拉希高地的安全需要打破食人魔的独立势力，清理南部的山脊以保障落锤镇的部落移动安全。"},sec={{t="残暴力量的堡垒",b="石拳大厅开凿在阿拉希高地崎岖的南面悬崖中，是该地区石拳氏族的主要堡垒。在土制防御工事和深邃洞穴的掩护下，食人魔蛮兵和法师在此维持着一个防御森严的定居点，距离枯木村和萨多尔大桥的战略要地仅几步之遥。在土丘深处，盘踞着他们的区域首领科格雷什·冷怒，以及像法拉纳克斯这样的执行者。从这座据点出发，食人魔对周围的道路施加了暴力控制，使得任何往来于阿拉希和湿地之间的和平通行对旅行者和补给商队而言都充满危险。"}},faq={{q="石拳大厅是什么地方？",a="这是一座防御严密的食人魔土丘和洞穴综合体，位于阿拉希高地南部，是石拳氏族在该领土上的行动基地。",al={"这是什么地方","石拳土丘","阿拉希食人魔洞穴"}},{q="谁统治着石拳大厅？",a="该据点由食人魔首领科格雷什·冷怒领导，他与像法拉纳克斯这样的勇士一起，在土丘内部的深处洞穴中指挥着他的氏族。",al={"谁领导石拳大厅","阿拉希食人魔首领","科格雷什"}},{q="为什么这个地点具有战略重要性？",a="它靠近萨多尔大桥，这使得石拳食人魔能够威胁连接阿拉希高地与卡兹莫丹的重要陆路路线，切断交通并猎杀过往的旅人。",al={"为什么食人魔在这里","萨多尔大桥的危险"}},{q="石拳食人魔与附近的枯木巨魔结盟了吗？",a="没有记录显示有正式结盟。石拳食人魔与枯木村的森林巨魔比邻而居；而在高地的其他地方，在博德戈尔，枯木巨魔甚至与食人魔共享地盘。双方对所有阵营的外来者都保持敌对态度。",al={"食人魔和巨魔是盟友吗","枯木氏族联盟"}}},fp="16,315,27.633.0,25.157.0,27.153.0,45.188.0,61.274.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Boulderfist Outpost",s="Boulderfist Outpost是坐落于阿拉希高地博德戈尔食人魔聚居地深处的一座堡垒土丘。它作为内部巢穴和关押区，栖息着好战的Boulderfist食人魔以及少数枯木巨魔。",h="Boulderfist Outpost是坐落于阿拉希高地博德戈尔食人魔聚居地深处的一座堡垒土丘。它作为内部巢穴和关押区，栖息着好战的Boulderfist食人魔以及少数枯木巨魔。",kw={"阿拉希","博德戈尔","boulderfist","俘虏","kovork","食人魔土丘","囚犯","枯木"},ang={["faction:Alliance"]="在阿拉希旅行的联盟斥候应该避开这座土丘，因为里面的Boulderfist执法者会攻击任何看到的入侵者。",["faction:Horde"]="Boulderfist食人魔不区分阵营，它们攻击部落流浪者和攻击联盟对手一样毫不手软。"},sec={{t="土丘之中的要塞",b="Boulderfist Outpost开凿在阿拉希西部的土地与岩石之中，是博德戈尔的核心。虽然粗暴的执法者统治着地表的聚居地，但前哨站内部集中了部落的核心力量，并提供了一个阴暗的地下庇护所。少数枯木巨魔巫医偶尔会混在食人魔中，暗示了脆弱的部落间合作。"}},faq={{q="Boulderfist Outpost位于何处？",a="Boulderfist Outpost是位于阿拉希高地西部大范围区域内，博德戈尔大型食人魔聚居地中的一处内部土丘。",al={"boulderfist outpost位置","boulderfist outpost在哪里","boulderfist土丘入口"}},{q="为什么食人魔前哨站里会有巨魔？",a="枯木森林巨魔居住在阿拉希高地附近，偶尔会与Boulderfist食人魔共享地盘。几名枯木巫医可以在前哨站深处与食人魔一同钻研他们的法术。",al={"为什么枯木巨魔在这里","boulderfist里的巨魔","阿拉希的枯木巨魔"}},{q="谁被关押在前哨站里？",a="目前已知没有被点名的俘虏被关押在前哨站中。其潮湿的走廊属于Boulderfist执法者和少数枯木巫医，任何闯入内部的人都应该做好战斗准备，而不是去营救什么人。",al={"boulderfist俘虏","谁被困在boulderfist","阿拉希食人魔手中的俘虏"}},{q="谁领导着前哨站内的食人魔？",a="虽然该氏族的粗暴执法者在内部巡逻，但一只名为Kovork的异常凶猛的食人魔潜伏在土丘中，是一个值得注意的威胁。",al={"kovork","阿拉希boulderfist首领","boulderfist稀有"}}},fp="19,239,29.390.0,37.154.0,44.240.0,33.219.0,39.150.0"}
P.entries["subzone:boulderslide-cavern"] = {n="滚岩洞穴",s="滚岩洞穴是位于石爪山脉滚岩峡谷最深处的一处地下巢穴。这里是当地滚岩狗头人的主要巢穴和挖掘场，他们执着地挖掘着，寻找发光的矿物结构。",h="滚岩洞穴是位于石爪山脉滚岩峡谷最深处的一处地下巢穴。这里是当地滚岩狗头人的主要巢穴和挖掘场，他们执着地挖掘着，寻找发光的矿物结构。",kw={"滚岩","洞穴","土灵","goggeroc","狗头人","共鸣晶石","石爪山脉"},ang={["class:Shaman"]="共鸣晶石和沉睡的土灵Goggeroc都与原始大地魔法产生了共鸣，这是世界古老造石者留下的回响。",["profession:Mining"]="滚岩氏族的狗头人正在洞穴中疯狂地工作，他们不停地挖掘，试图发现发着光的魔法共鸣晶石矿脉。"},sec={{t="共鸣晶石挖掘场",b="滚岩狗头人深入石爪山脉的岩缝中，将滚岩洞穴建成了他们的据点。与那些仅仅寻求栖身之所的普通害虫不同，这些狗头人疯狂地挖掘着“共鸣晶石”，这是一种嵌在岩石中、稀有且会发光的紫色水晶。这些晶石散发着残留的土灵魔法，让这些生物陷入了一种防御性的狂乱，对抗任何接近他们挖掘场地的入侵者。"},{t="沉睡的巨人",b="在洞穴更深处，鲁莽的挖掘行动揭开了一些古老的秘密。嵌入地下岩层中的是一个共鸣晶石容器，里面装着来自远古时代的沉睡土灵Goggeroc。狗头人在这个神秘遗物周围进行着无休止的挖掘，这可能会唤醒这个被原始岩石魔法灌注的存在，从而对整个峡谷构成突如其来的危险。"}},faq={{q="狗头人在这里挖掘什么？",a="狗头人正在挖掘共鸣晶石，这是一种嵌在洞穴岩壁中的稀有紫色水晶。这种矿石嗡嗡作响，带有微弱的土灵魔法痕迹，使它成为一种宝贵的战利品，也让狗头人们狂热地守卫着他们的藏宝处。",al={"什么是共鸣晶石","石爪山脉的紫色水晶","狗头人为什么挖掘"}},{q="Goggeroc是谁？",a="Goggeroc是一位古老的土灵，沉睡在洞穴深处的一个共鸣晶石容器中。狗头人在他安息之处周围的挖掘行动可能会打扰他长达数个世纪的沉睡。",al={"goggeroc背景故事","滚岩洞穴里的土灵","洞穴里的沉睡巨人"}},{q="滚岩洞穴在哪里？",a="洞穴入口位于滚岩峡谷的最尽头，坐落在石爪山脉南部多岩的山区中，就在通往贫瘠之地的道路东北方。",al={"滚岩洞穴位置","如何找到滚岩洞穴","洞穴在哪里"}},{q="为什么部落会对这个洞穴感兴趣？",a="部落监视着这个洞穴，以遏制向峡谷蔓延的、极具侵略性的狗头人，同时也是出于对他们挖掘出的共鸣晶石的魔法特性的兴趣。",al={"部落滚岩洞穴任务","为什么派我去滚岩洞穴"}}},fx={["5c565568"]={q="滚岩洞穴是什么地方？",a="滚岩洞穴是一座地下矿洞，深藏于石爪山脉的滚岩峡谷尽头。这里是当地狗头人的活跃巢穴和大型挖掘场，他们不知疲倦地在岩石深处开采稀有的魔法共鸣水晶。",al={"滚岩洞穴是什么","滚岩洞穴背景","关于滚岩洞穴"}},["66cd11c1"]={q="谁住在滚岩洞穴？",a="洞穴里住的全是滚岩狗头人。这些好斗的地下掘进者在此建起巢穴，疯狂开采共鸣水晶，并以暴力手段守卫隧道，抵御任何胆敢靠近的入侵者。",al={"谁住在滚岩洞穴","滚岩洞穴的居民","滚岩洞穴里有谁"}},babd5bca={q="滚岩洞穴危险吗？",a="是的，极其危险。洞内的狗头人会拼死守护采矿作业，并群起攻击任何闯入巢穴的人。此外，他们深挖的隧道已触及古老遗物，其中包括一具沉睡在矿洞深处、处于休眠状态的土灵。",al={"滚岩洞穴危险吗","滚岩洞穴的危险","滚岩洞穴的威胁"}}},fp="19,271,16.421.0,20.353.1,33.236.0,16.188.1,37.176.0,43.185.0"}
P.entries["subzone:boulderslide-ravine"] = {n="滚岩峡谷",s="滚岩峡谷是一条崎岖偏僻的峡谷，隐藏在石爪山脉的中央山峰之中，通过蛛网小径即可到达。这里基本上避开了部落与联盟之间的直接冲突，它是通往滚岩洞穴的岩石通道，依然是野生山地野兽的栖息地。",h="滚岩峡谷是一条崎岖偏僻的峡谷，隐藏在石爪山脉的中央山峰之中，通过蛛网小径即可到达。这里基本上避开了部落与联盟之间的直接冲突，它是通往滚岩洞穴的岩石通道，依然是野生山地野兽的栖息地。",kw={"滚岩洞穴","滚岩峡谷","峭壁风暴者","山羊","石爪","蛛网小径"},ang={["profession:Mining"]="峡谷陡峭的岩壁是观察因山脉岩石移动而暴露出来的矿脉的可靠地点。",["race:Tauren"]="小侧洞内褪色的艺术品带有明显的牛头人部落标记，暗示了穿越石爪山脉高地的祖先足迹。"},sec={{t="宁静的山间小径",b="滚岩峡谷隐藏在蛛网小径之外，是石爪山脉高地上一道狭窄的岩石裂缝。尽管伐木工、暗夜精灵和部落在该地区为木材和圣林争斗不休，但这条崎岖的山口却相对未受到军事力量的干扰。野生山羊和诸如峭壁风暴者之类的游荡岩石野兽是这里的当地动物，它们在险峻的岩架和陡峭的石墙间穿行。勘探者们也密切关注着峡谷，因为沿着通往洞穴网络深处的岩石斜坡上经常会出现丰富的矿脉。"},{t="岩石上的痕迹",b="滚岩洞穴入口对面有一个安静的小洞穴，俯瞰着峡谷。洞穴内点着粗糙的火把，堆放着风化的补给木桶，内壁上绘有原始的部落画作。这些粗糙的艺术品与古代牛头人的设计惊人地相似，暗示着在现代冲突席卷这些山脉之前，土著部落早已在这些岩脊中旅行或寻求过临时避难所。"}},faq={{q="滚岩峡谷位于哪里？",a="滚岩峡谷位于石爪山脉。沿着蛛网小径进入更高的岩脊即可到达。",al={"滚岩峡谷位置","如何前往滚岩峡谷","滚岩峡谷在哪里"}},{q="什么生物栖息在滚岩峡谷？",a="峡谷内主要居住着当地的野生动物，特别是山羊和危险的岩石潜伏者，例如峭壁风暴者。",al={"滚岩峡谷怪物","滚岩峡谷里有什么"}},{q="滚岩洞穴对面那个废弃的洞穴是什么？",a="洞穴入口对面是一个小凹室，里面点着火把，存放着旧木桶。其石墙上展示着部落象形图，类似于传统的牛头人艺术，表明过去曾有当地的流浪者或猎人在此使用过。",al={"滚岩废弃洞穴","滚岩峡谷中的洞穴","石爪牛头人洞穴"}},{q="滚岩峡谷有什么重要意义？",a="它是通往深藏于山中的地下巢穴滚岩洞穴的天然通道，并为途经此地的旅行者提供了宝贵的矿石露头。",al={"滚岩峡谷的作用","滚岩峡谷用途"}}},fx={["92909b11"]={q="滚岩峡谷是什么地方？",a="滚岩峡谷是石爪山脉中的一处崎岖峡谷，可经由蛛网小径抵达。它主要是通往更深处滚岩洞穴的入口。部落与联盟之间的战争席卷了周围的山峰，而这处隐蔽的峡谷仍基本远离战火。",al={"滚岩峡谷是什么","滚岩峡谷概况","滚岩峡谷背景"}},["846b0de4"]={q="为什么滚岩峡谷里的洞穴被遗弃了？",a="洞穴入口对面有一处僻静的废弃庇护所，里面点着简陋的火把，还堆放着旧木桶。墙上有褪色的部族艺术图案，令人想起牛头人的工艺；这表明当地部族或四处游荡的猎人曾在此扎营，后来离开峡谷，将其留给了野兽。",al={"洞穴为什么被遗弃","滚岩废弃洞穴","是谁遗弃了洞穴"}},["2463d3df"]={q="滚岩峡谷危险吗？",a="尽管躲过了有组织的军事冲突，这处峡谷远谈不上安全。当地的公羊在陡峭的小径旁吃草，躁动的元素生物峭壁风暴者则在岩壁间徘徊；因此，无论是前往矿脉还是洞穴，旅行者若不小心都会有危险。",al={"滚岩峡谷危险吗","滚岩峡谷里的危险","滚岩峡谷的威胁"}}},fp="19,306,21.567.0,19.442.0,37.130.0,43.128.0,59.222.0,39.172.0"}
P.entries["subzone:brackenwall-village"] = {n="蕨墙村",s="蕨墙村是部落在尘泥沼泽的主要前哨站，坐落在该区域西北角的沼泽地带中。在巨龙摧毁了他们位于南部的原始定居点后，幸存的石槌食人魔建立了这座村庄。它目前是一个脆弱的据点，周围环绕着联盟间谍、逃兵和黑龙军团。",h="蕨墙村是部落在尘泥沼泽的主要前哨站，坐落在该区域西北角的沼泽地带中。在巨龙摧毁了他们位于南部的原始定居点后，幸存的石槌食人魔建立了这座村庄。它目前是一个脆弱的据点，周围环绕着联盟间谍、逃兵和黑龙军团。",kw={"蕨墙村","德拉兹辛比","尘泥沼泽","渗透者","莫格穆洛克大王","食人魔","帕瓦尔·里瑟","石槌"},ang={["faction:Alliance"]="蕨墙村深入敌对领土，但关于失踪外交官和流氓塞拉摩逃兵的调查将把大胆的特工直接带到食人魔营地的边缘。",["faction:Horde"]="蕨墙村是你在沼泽中唯一的庇护所和飞行连接点；保卫它能确保部落维持一个重要的监听哨站，并作为防御塞拉摩的侧翼。"},sec={{t="石槌的避难所",b="当黑龙人将石槌食人魔赶出他们位于南部沼泽的古老家园——石槌村时，他们的领袖莫格穆洛克大王——雷克萨的继任者——带领幸存者向北进入沼泽，建立了蕨墙村。该定居点围绕着传统的土墩、茅屋和一座旧的守望塔而建，为饱受磨难的氏族提供了一个可以防御的避难所。尽管与部落结盟，但该村庄正遭受内部腐化的困扰：莫格穆洛克大王无所作为，囤积物资并拒绝面对龙族的威胁，将氏族的精神和战术指导留给了食人魔巫师德拉兹辛比和部落特使等人物。"},{t="沼泽中的眼睛",b="除了内部机能障碍外，蕨墙村还受到外部威胁的困扰。塞拉摩的渗透者不断潜伏在丛林中，窥探村庄的动向并向那座岛屿堡垒报告。与此同时，一名被废弃哨塔驱逐的塞拉摩逃兵帕瓦尔·里瑟被怀疑从前哨站偷走了重要物资。在东面警惕的目光和南部徘徊的黑龙夹击下，蕨墙村成为了部落孤立的集结地，用以抵御联盟和奥妮克希亚的子嗣。"}},faq={{q="为什么会有效忠部落的食人魔在这里？",a="这些是石槌食人魔，这是一个在杜隆塔尔建国期间由勇士雷克萨引入现代部落的荣誉氏族。雷克萨在击败了他们以前的领袖后成为了他们的酋长，在将领导权移交给莫格穆洛克大王之前，将该氏族束缚在萨尔大酋长的新联盟中。",al={"为什么有部落食人魔","石槌氏族背景故事","这些食人魔是谁"}},{q="为什么石槌食人魔定居在这里而不是留在他们旧的家园？",a="他们位于尘泥沼泽南部的祖传定居点被黑龙军团占领并夷为平地。莫格穆洛克大王带领流离失所的幸存者向北进入沼泽，将蕨墙村建立为一个坚固的避难所。",al={"石槌村发生了什么","为什么是蕨墙村","食人魔难民"}},{q="谁负责蕨墙村？",a="莫格穆洛克大王领导着这个定居点，但他的统治遭到了广泛的怨恨。他没有号召族人夺回家园或对抗巨龙，而是蜷缩在村庄里，迫使食人魔巫师德拉兹辛比和部落使节来处理日常危机。",al={"蕨墙村领袖","谁管理蕨墙村","莫格穆洛克大王"}},{q="为什么村外有塞拉摩间谍？",a="尽管塞拉摩和奥格瑞玛之间存在脆弱的停战协议，但吉安娜·普罗德摩尔的军队对尘泥沼泽内任何部落部队的动向都保持着严密的监视。渗透者在蕨墙村的周边潜行，报告食人魔的兵力和部落的行动。",al={"尘泥沼泽的联盟间谍","塞拉摩渗透者","为什么塞拉摩在监视"}}},fp="19,343,23.633.0,15.527.1,47.294.0,71.229.0,40.263.0,50.262.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="布莱克威尔南瓜田",s="布莱克威尔南瓜田是艾尔文森林东南部的一处被占据的农庄。这里曾是布莱克威尔家族的家园，如今农田和农舍已被迪菲亚潜行者彻底霸占，作为其行动据点。这里不仅是潜行同谋者的碰头点，还是走私赃金的中转站。",h="布莱克威尔南瓜田是艾尔文森林东南部的一处被占据的农庄。这里曾是布莱克威尔家族的家园，如今农田和农舍已被迪菲亚潜行者彻底霸占，作为其行动据点。这里不仅是潜行同谋者的碰头点，还是走私赃金的中转站。",kw={"布莱克威尔","迪菲亚","艾尔文","埃尔兰·德鲁格莫尔","收货人莫根","公主","南瓜田","苏瑞娜·卡蕾顿"},ang={["class:Warlock"]="农场的棚屋里藏着逃亡的学徒苏瑞娜·卡蕾顿，她偷走的血石颈环是召唤虚空行者所必需的物品。",["faction:Alliance"]="这片被占领的南瓜田是迪菲亚潜行者在艾尔文森林内最靠东的行动基地之一，直接威胁着附近的农场和贸易路线。"},sec={{t="强盗的避风港",b="布莱克威尔农场位于斯通菲尔德农场东南方，曾经是艾尔文森林一片高产的农田。如今，合法的农场主已不知所踪，他们要么是被日益猖獗的犯罪势力赶走，要么遭遇了更糟的命运。在他们离开后，迪菲亚潜行者占据了农场结实的农舍和杂草丛生的田地。这里成为了他们的藏身处和转运站，让强盗们得以在远离闪金镇巡逻队监视的地方重整旗鼓。像收货人莫根这样的重要共谋者，利用这片偏僻的地块接收从森林矿坑中非法开采并偷运出的黄金。"},{t="猪与黑暗魔法",b="除了迪菲亚潜行者，在这片南瓜藤中游荡的麻烦制造者还不止这些。布莱克威尔一家留下了一头巨大的获奖母猪，名叫公主，它在南瓜田里四处游荡，不断骚扰着邻近的农场。与此同时，农舍的阁楼和附属建筑掩盖着危险的个人交易：强盗埃尔兰·德鲁格莫尔引诱了苏瑞娜·卡蕾顿，这是一位术士学徒，她从暴风城的导师那里逃走，并偷走了一件血石饰品，从而将黑暗术士的注意力引向了这个藏身处。"}},faq={{q="布莱克威尔一家发生了什么？",a="他们的具体下落至今仍是个谜。当迪菲亚潜行者在艾尔文森林东南部扩大势力时，布莱克威尔一家要么被迫逃离，要么惨遭杀害，将他们的南瓜田和农舍留给了这些强盗。",al={"布莱克威尔一家在哪里","谁住在布莱克威尔农场","布莱克威尔家族的命运"}},{q="为什么迪菲亚潜行者要使用这个农场？",a="这个农场提供了一个靠近森林边缘的偏僻基地。它允许兄弟会储存赃物并协调走私行动，例如通过收货人莫根这样的信使接收偷来的矿金，且远离暴风城卫兵的视线。",al={"为什么迪菲亚在这里","强盗在南瓜田做什么","布莱克威尔的迪菲亚"}},{q="公主是谁？",a="公主是一头体型巨大的获奖母猪，最初由布莱克威尔一家饲养。农场沦陷时它被遗弃在此，由于经常闯入附近的斯通菲尔德农场偷吃他们珍贵的作物，它的体型变得更加庞大。",al={"巨型猪","猪公主","为什么这里有一头巨大的野猪"}},{q="为什么术士会来到南瓜田？",a="苏瑞娜·卡蕾顿是暴风城术士训练师黑暗缚灵者加科因的学徒，她偷走了一件强大的血石颈环，并潜逃到农场，与她的情人——迪菲亚强盗埃尔兰·德鲁格莫尔躲藏在一起。加科因派遣术士新手来到这里除掉她并取回这件圣物。",al={"布莱克威尔术士任务","苏瑞娜·卡蕾顿","加科因虚空行者任务"}}},fx={f38a2be0={q="布莱克威尔南瓜田是什么地方？",a="布莱克威尔南瓜田是一座暴风城风格的农庄，坐落在艾尔文森林东南部。这里曾是宁静的农家宅院，种植成熟的南瓜、饲养牲畜，最近却陷入混乱，落入了歹徒之手。",al={"布莱克威尔南瓜田","这座农场是什么","布莱克威尔农场"}},["0e932b65"]={q="布莱克威尔南瓜田发生了什么？",a="这片南瓜田曾是一座丰产的家庭农场，后来强盗夺取了这片土地，迪菲亚潜行者也随之占领了这里。布莱克威尔一家消失了，农场很快成了迪菲亚活动的据点，包括交付金币和藏匿非法物品。",al={"布莱克威尔农场历史","这里发生了什么","布莱克威尔背景"}},ae1356ee={q="谁住在布莱克威尔南瓜田，或是谁在经营这里？",a="农场原来的主人已经离开，如今这里由迪菲亚强盗占据。其中，埃兰·德鲁奇摩尔和他的情人苏雷娜·卡勒顿藏身于此，而收货人莫根则利用农场接收当地矿洞运来的金币。",al={"谁在经营布莱克威尔南瓜田","谁住在布莱克威尔","布莱克威尔南瓜田的居民"}},["90becbea"]={q="布莱克威尔南瓜田危险吗？",a="是的，务必小心行事。全副武装的迪菲亚扒手在南瓜田里巡逻，此外还有臭名昭著、贪吃的冠军猪公主。她会和随行的猪群一起，凶狠地守护自己的觅食地。",al={"布莱克威尔安全吗","布莱克威尔的危险","这座农场危险吗"}},["43009602"]={q="为什么叫布莱克威尔南瓜田？",a="它以布莱克威尔家族命名。这个人类农民家族曾在此定居，耕种这片独特的南瓜田，后来强盗袭击迫使他们离开家园。",al={"布莱克威尔名称由来","为什么叫布莱克威尔","布莱克威尔一家是谁"}}},fp="23,317,14.602.0,19.504.1,38.236.0,46.283.0,16.221.0,42.276.0"}
P.entries["subzone:brambleblade-ravine"] = {n="刺刃峡谷",s="刺刃峡谷是一条切入红云台地东北边缘的崎岖峡谷。它是刺鬃野猪人部落的坚固巢穴，他们不断袭击附近的牛头人定居点——纳拉其营地。年轻的牛头人勇士被派往此处，以证明他们的实力并保护家园免受这些凶猛入侵者的侵扰。",h="刺刃峡谷是一条切入红云台地东北边缘的崎岖峡谷。它是刺鬃野猪人部落的坚固巢穴，他们不断袭击附近的牛头人定居点——纳拉其营地。年轻的牛头人勇士被派往此处，以证明他们的实力并保护家园免受这些凶猛入侵者的侵扰。",kw={"刺刃","刺鬃","纳拉其营地","莫高雷","野猪人","峡谷","红云台地","棘幔"},ang={["faction:Horde"]="清除刺刃峡谷中极具侵略性的刺鬃野猪人，有助于巩固部落在莫高雷早期的立足点。",["race:Tauren"]="对于在纳拉其营地进行Coming of Age的年轻牛头人来说，深入刺刃峡谷是他们为保卫部落而进行的最初的武力和精神耐力测试之一。"},sec={{t="台地之刺",b="刺刃峡谷刻在红云台地那被烈日灼烧的土地上，峡谷中塞满了茂密多刺的荆棘和野猪人的营地。刺鬃部落将这一天然要塞作为袭击纳拉其营地的集结地，威胁着正在进行Coming of Age的年轻牛头人的安全。刺鬃萨满和战士在首领利牙·棘幔的带领下，与驯养的战猪一起居住在峡谷深处。对于舒哈鲁人来说，深入峡谷中心既是一场关键的成人礼，也是保卫平原的冷酷必要之举。"}},faq={{q="什么是刺刃峡谷？",a="刺刃峡谷是位于莫高雷红云台地东北边缘的一条峡谷。这里居住着大量的刺鬃野猪人，是他们当地的据点。",al={"刺刃峡谷","什么是刺刃峡谷","莫高雷刺刃峡谷"}},{q="为什么刺鬃野猪人从这里发起进攻？",a="刺鬃野猪人领地意识极强，并将牛头人的存在视为对其所宣称土地的侵犯。他们以刺刃峡谷为据点，频繁对附近的定居点纳拉其营地发起袭击。",al={"为什么野猪人发起进攻","刺鬃野猪人的动机","野猪人纳拉其营地"}},{q="谁领导着刺刃峡谷的野猪人？",a="这里的野猪人由首领利牙·棘幔领导，他是一位强大的酋长，居住在峡谷后方的一间大屋子里。",al={"刺刃峡谷首领","莫高雷野猪人头目","首领利牙·棘幔"}},{q="为什么年轻的牛头人要前往峡谷？",a="纳拉其营地的牛头人长者和酋长派遣初出茅庐的勇士进入峡谷，以击退刺鬃野猪人的威胁，削减其数量，并击败其首领，从而保障台地的安全。",al={"牛头人刺刃任务","为什么要前往刺刃峡谷","纳拉其营地任务"}}},fx={["9e3e8e60"]={q="谁住在刺刃峡谷？",a="这处峡谷是钢鬃野猪人的设防聚居地。钢鬃野猪人在泥土小径间建起了许多棚屋，身边还有好斗的战猪、部族成员和萨满；他们听命于酋长锋牙·荆棘披风及其族人。",al={"谁住在刺刃峡谷","刺刃峡谷的居民","刺刃峡谷里有谁"}},cff45375={q="刺刃峡谷危险吗？",a="对粗心的旅行者来说，这里十分凶险。野猪人会凶狠地守卫巢穴，驱使训练有素的战猪和神秘的萨满围攻入侵者。任何不加防备就进入峡谷的人，很快就可能被逼到高耸的峡谷壁边，走投无路。",al={"刺刃峡谷危险吗","刺刃峡谷有多危险","刺刃峡谷的危险"}}},fp="19,341,26.544.0,28.181.0,53.214.0,46.147.0,41.199.0"}
P.entries["subzone:bramblescar"] = {n="迅猛龙平原",s="迅猛龙平原是位于南贫瘠之地的一处防御森严的刺鬃野猪人定居点。茂密而多刺的荆棘屏障保护着这座营地，里面的居民正在与黄金之路对面的竞争对手刺棘部族进行着残酷的战争。",h="迅猛龙平原是位于南贫瘠之地的一处防御森严的刺鬃野猪人定居点。茂密而多刺的荆棘屏障保护着这座营地，里面的居民正在与黄金之路对面的竞争对手刺棘部族进行着残酷的战争。",kw={"阿迦玛戈","贫瘠之地","迅猛龙平原","刺棘","黄金之路","野猪人","刺鬃"},ang={["faction:Horde"]="确保黄金之路免受来自迅猛龙平原的野猪人突袭，对于维持十字路口、陶拉祖营地以及南部边境之间的安全通道至关重要。"},sec={{t="荆棘堡垒",b="迅猛龙平原开凿在南贫瘠之地参差不齐的巨大荆棘丛中，是刺鬃野猪人至关重要的防御堡垒。这些防御性的荆棘丛生长得又厚又尖，足以阻挡随意的游荡者，但里面的野猪人绝非善类。他们领地意识极强，对外人充满敌意，不断袭击任何靠近其边界的人，将所有非野猪人的生物视为对其古老野猪神所祝福土地的侵犯者。"},{t="部落血仇",b="迅猛龙平原与黄金之路对面的阿迦玛戈始终处于紧张对峙状态，后者是敌对的刺棘部族所据守的营地。这两个派系为了争夺对南贫瘠之地的统治权，陷入了一场无休止的部落战争。除了要击退沿大路行进的部落旅行者，还要抵御刺棘部族的突袭队，迅猛龙平原的刺鬃战士们始终保持着持续且暴力的戒备状态。"}},faq={{q="谁住在迅猛龙平原？",a="迅猛龙平原居住着刺鬃部族的野猪人，他们守卫着这片荆棘丛生的营地，以对抗其他敌对的野猪人以及任何路过的旅行者。",al={"这里有什么人","迅猛龙平原怪物","迅猛龙平原野猪人"}},{q="为什么这里的野猪人在自相残杀？",a="迅猛龙平原的刺鬃野猪人和路对面阿迦玛戈的刺棘野猪人是死敌，他们为了争夺对南贫瘠之地的控制权，陷入了激烈的领土血仇之中。",al={"为什么他们处于战争状态","刺鬃与刺棘","野猪人战争"}},{q="迅猛龙平原在哪里？",a="迅猛龙平原位于贫瘠之地的南部平原，坐落在黄金之路东侧，与阿迦玛戈隔路相望。",al={"迅猛龙平原位置","迅猛龙平原在哪里","如何找到迅猛龙平原"}},{q="这里的野猪人对部落有敌意吗？",a="是的。刺鬃野猪人将部落视为侵犯他们神圣部落领地的入侵者，他们会攻击任何靠近的旅行者。",al={"迅猛龙平原友好吗","部落与迅猛龙平原声望"}}},fx={["86a75fd0"]={q="迅猛龙平原是什么地方？",a="迅猛龙平原是南贫瘠之地的一处剃刀沼泽野猪人营地和巢穴。它位于主路旁，正对着钢鬃野猪人的领地阿迦玛戈。这里是剃刀沼泽野猪人的设防基地，他们与钢鬃宿敌之间的领土战争从未停歇。",al={"迅猛龙平原是什么","迅猛龙平原信息","关于迅猛龙平原"}},f9fc9349={q="迅猛龙平原危险吗？",a="是的，对任何旅行者来说，迅猛龙平原都极其危险。居住于此的剃刀沼泽野猪人极具攻击性，任何人只要靠近巢穴，都会遭到他们伏击；与此同时，他们还与附近的钢鬃部族展开激烈战争。",al={"迅猛龙平原危险吗","迅猛龙平原的危险","迅猛龙平原有多安全"}}},fp="11,238,17.466.0,17.402.0,25.164.0,46.184.0,29.121.0,43.157.0"}
P.entries["subzone:brewnall-village"] = {n="烈酒村",s="烈酒村是坐落在寒风峡谷，靠近诺莫瑞根入口处的一处小型矮人定居点。由麦酒家族建立，这个前哨站既是进行大胆酿酒实验的试验场，也是抵御野生野兽入侵的区域防线。尽管被称为“村”，它在丹莫罗积雪覆盖的侏儒低地中实际上更像是一个粗犷的营地。",h="烈酒村是坐落在寒风峡谷，靠近诺莫瑞根入口处的一处小型矮人定居点。由麦酒家族建立，这个前哨站既是进行大胆酿酒实验的试验场，也是抵御野生野兽入侵的区域防线。尽管被称为“村”，它在丹莫罗积雪覆盖的侏儒低地中实际上更像是一个粗犷...",kw={"麦酒家族","啤酒","烈酒村","寒风峡谷","丹莫罗","诺莫瑞根","黑啤酒"},ang={["race:Dwarf"]="对矮人而言，麦酒家族对终极配方的追求是一项崇高的事业，延续了铁炉堡最优秀的传统之一。",["race:Gnome"]="该村庄坐落在诺莫瑞根附近，是深处丹莫罗西部侏儒峡谷中一处意想不到的矮人前哨站。"},sec={{t="峡谷中的苦酒",b="烈酒村隐藏在寒风峡谷的积雪中，位于丹莫罗西部的传统侏儒领地内。这个定居点是麦酒氏族的家园，这些坚定的矮人酿酒师致力于完善古老的配方并酿造出终极烈性黑啤酒。虽然被称为村庄，但该前哨站主要由帐篷和户外酿酒设备组成，而非永久性的石质建筑。在测试实验性麦酒批次和抵御当地凶猛的狼群与熊群之余，麦酒家族非常依赖过往的登山者来收集稀有原料并确保峡谷的安全。"}},faq={{q="烈酒村是什么地方？",a="烈酒村是位于丹莫罗西部、诺莫瑞根正东方寒风峡谷内的一个小型矮人营地。它是麦酒氏族进行新啤酒配方实验和管理当地野生动物威胁的前哨站。",al={"烈酒村在哪里","烈酒村是什么","烈酒村信息"}},{q="既然没有建筑物，为什么叫它村庄？",a="尽管名字里带个“村”字，但该地点本质上是一个由帐篷和补给桶组成的露天营地。麦酒家族为了在这种寒冷气候下进行酿酒作业，并没有建造正式的石屋。",al={"为什么是营地","房子在哪里","烈酒村建筑"}},{q="为什么在侏儒领地会有矮人定居点？",a="虽然丹莫罗的西半部环绕着诺莫瑞根，主要居住着侏儒，但铁炉堡和侏儒之间紧密的联盟使得共同居住变得很常见。麦酒家族在寒风峡谷定居，是为了不受干扰地追求他们的技艺。",al={"诺莫瑞根附近的矮人","为什么矮人在那","侏儒领地的矮人营地"}},{q="居民们面临什么问题？",a="营地经常面临来自峡谷中凶猛野生动物的袭击，尤其是石腭怪、熊和霜狼。此外，麦酒家族也在不断寻找稀有和奇异的原料，以发明出更新、更棒的佳酿。",al={"烈酒村任务","麦酒家族需要什么","村庄问题"}}},fx={c4fa2ce1={q="谁住在烈酒村？",al={"谁在管理烈酒村","烈酒村的居民","谁住在烈酒村"}}},fp="16,380,27.637.0,25.243.0,53.234.0,57.266.0,36.244.0"}
P.entries["subzone:brightwater-lake"] = {n="澈水湖",s="澈水湖是提瑞斯法林地最大的水域，横跨布瑞尔东北部那片迷雾笼罩的低地。这片湖泊曾是洛丹伦王国一处宁静的度假地，如今湖水却变得阴冷昏暗，环绕着一座中央岛屿，一位被放逐的死灵法师正在那里进行着他那禁忌的研究。",h="澈水湖是提瑞斯法林地最大的水域，横跨布瑞尔东北部那片迷雾笼罩的低地。这片湖泊曾是洛丹伦王国一处宁静的度假地，如今湖水却变得阴冷昏暗，环绕着一座中央岛屿，一位被放逐的死灵法师正在那里进行着他那禁忌的研究。",kw={"澈水湖","布瑞尔","冈瑟尔·阿坎努斯","冈瑟尔的居所","死灵法师","血色十字军哨岗","提瑞斯法林地","亡灵"},ang={["class:Mage"]="湖上的岛屿保留着叛逃法师冈瑟尔·阿坎努斯所展现出的独特且未经引导的精湛技艺。",["race:Undead"]="对于被遗忘者来说，确保澈水湖的安全对于保卫布瑞尔的东侧防线以及评估这位独立的死灵法师冈瑟尔·阿坎努斯究竟会成为资产还是敌人至关重要。"},sec={{t="北方的水域",b="澈水湖横跨布瑞尔镇和血色十字军哨岗之间的北部平原，是提瑞斯法林地中心地带一处安静而诡异的地标。在洛丹伦王国统治的和平年代，这里曾是一处风景秀丽的乡村避风港。如今，就像林地的其他地方一样，它纯净的特质早已荡然无存。瘟疫之地就在东边不远处，浑浊而冰冷的湖水只能映照出灰暗的天空、枯萎的树木，以及时刻威胁着这里的鱼人游荡者和充满敌意的亡灵。"},{t="隐士的居所",b="澈水湖中央升起一座名为冈瑟尔的居所的岛屿。冈瑟尔·阿坎努斯靠自己的力量挣脱了巫妖王的控制，但他认为其他所有亡灵依然是天灾军团的奴隶。他将自己与世隔绝，并派遣亡灵仆从守卫他的居所。比索·埃斯沙德试图向他的老友证明，被遗忘者也拥有自由意志。在冒险者证明了自己反对天灾军团的立场后，冈瑟尔同意加入被遗忘者。"}},faq={{q="澈水湖在哪里？",a="澈水湖位于提瑞斯法林地东北部，就在被遗忘者据点布瑞尔的东北方。它位于崎岖的北部海岸正南方，西临血色十字军哨岗，后者守卫着通往西瘟疫之地的山口。",al={"澈水湖位置","澈水湖在哪里","寻找澈水湖"}},{q="住在湖中心岛上的人是谁？",a="中央岛屿被称为冈瑟尔的居所。一位与世隔绝的死灵法师和他的亡灵仆从居住在那里，这引起了附近布瑞尔和幽暗城的被遗忘者的兴趣。",al={"岛上住着谁","冈瑟尔·阿坎努斯","澈水湖岛屿npc"}},{q="水域周围有什么威胁？",a="沿着湖岸旅行的人经常会遇到好斗的鱼人和在岸边搜寻食物的怪鱼。接近中央岛屿时，那些发誓保护冈瑟尔·阿坎努斯免受入侵者伤害的亡灵仆从会带来危险。",al={"湖中怪物","澈水湖敌人","澈水湖的危险"}},{q="为什么布瑞尔的卫兵会谈论这里的夏令营？",a="布瑞尔的死亡卫兵会冷冷地开玩笑说，被遗忘者曾试图在澈水湖岸边开办一个儿童夏令营，但因为蒙面变态狂在营地里恐吓他人而被迫关闭——这是一个模仿人类篝火故事的病态本地笑话。",al={"夏令营传闻","布瑞尔卫兵关于湖的笑话","蒙面变态营地"}}},fx={["010a8c36"]={q="澈水湖是什么地方？",a="澈水湖是提瑞斯法林地最大的水域，位于布瑞尔东北方，东侧毗邻通往血色十字军哨岗的丘陵。湖水幽暗，中央有一座醒目的岛屿，名为冈瑟尔的居所，周围还散布着一些较小的露出水面的岩地。",al={"澈水湖是什么地方","澈水湖的背景故事","介绍澈水湖"}},["5d21e80d"]={q="澈水湖有着怎样的历史？",a="瘟疫爆发前，澈水湖是洛丹伦王国一处宁静的乡间胜地。如今，冰冷的湖水环绕着冈瑟尔的居所，亡灵法师冈瑟尔·阿坎努斯藏身于此，远离尘世。",al={"澈水湖的历史","澈水湖发生过什么","澈水湖的往事"}}},fp="16,307,19.503.0,19.454.1,34.247.0,50.185.0,41.225.0,57.266.0"}
P.entries["subzone:brightwood-grove"] = {n="阳光树林",s="阳光树林是一片位于暮色森林夜色镇正西方的阴影笼罩的林地。这里曾经是该地区宁静的农耕景观的一部分，现在却被野蛮的夜行狼人所占据，它们在废弃的农舍中安营扎寨，并袭击任何靠得太近的旅行者。",h="阳光树林是一片位于暮色森林夜色镇正西方的阴影笼罩的林地。这里曾经是该地区宁静的农耕景观的一部分，现在却被野蛮的夜行狼人所占据，它们在废弃的农舍中安营扎寨，并袭击任何靠得太近的旅行者。",kw={"阳光树林","夜色镇","暮色森林","守夜人","夜行者","狼人"},ang={["class:Hunter"]="树林阴暗的丛林为追踪凶残的夜行狼人提供了艰难的地形，考验着猎人在树线后潜伏的伏击面前的警觉性。",["faction:Alliance"]="阳光树林紧邻夜色镇大门，因此铲除其中的狼人狼群对于防止这座饱受摧残的城镇与西部隔绝至关重要。"},sec={{t="阴影中的树林",b="阳光树林位于夜色镇周边视野范围内，代表着威胁该镇边界的步步紧逼的危险。曾经划分出宁静农田的农舍和栅栏现在已经坍塌腐朽。取而代之的是，夜行狼人在杂草丛生的林间空地上搭建了粗陋的营地。这些狼兽的临近对城镇构成了持续的威胁，迫使守夜人和过往的冒险者不断地削减它们的数量，以免定居点被它们淹没。"}},faq={{q="阳光树林在哪里？",a="阳光树林位于暮色森林东部，就在夜色镇西侧，紧邻主要道路。",al={"阳光树林位置","阳光树林在哪里","暮色森林阳光树林"}},{q="什么生物栖息在阳光树林？",a="这片树林里盘踞着大量野蛮的夜行狼人。这些被诅咒的狼人已经在废墟建筑中建立了粗陋的营地，并会袭击任何靠近的人。",al={"阳光树林中的怪物","阳光树林的敌人","阳光树林住着什么"}},{q="为什么这片树林对夜色镇来说很危险？",a="由于阳光树林紧邻夜色镇西侧，潜伏在灌木丛中的好斗狼群对城镇巡逻队、补给线以及任何沿路抵达的旅行者构成了直接威胁。",al={"为什么阳光树林很危险","夜色镇阳光树林威胁"}},{q="树林里有友好的定居点吗？",a="没有。树林边缘仅存的几座石屋和农舍完全沦为废墟，被遗弃在荒野中，并被游荡的狼人占据。",al={"阳光树林里有友方单位吗","阳光树林城镇"}}},fx={d7b16ad8={q="阳光树林是什么地方？",a="阳光树林是一片阴森的林地，位于暮色森林夜色镇的正西方。这里曾是郁郁葱葱的森林的一部分，但黑暗逐渐笼罩了这片区域，如今树林已陷入压抑的阴霾之中。曾经散布在林地边缘的建筑如今都已坍塌成废墟，成群的野性夜行狼人占据了杂草丛生的田野与树林，将这里当作猎场。",al={"阳光树林","阳光树林是什么地方","暮色森林的阳光树林"}},d83f7d45={q="阳光树林为何沦为废墟？",a="与暮色森林的大部分地区一样，阳光树林也未能逃脱蔓延的诅咒与恐怖。掠食性的夜行狼人迁入此地后，林地边缘的宅院和建筑被遗弃，逐渐破败。如今，这里不再有宁静的农田或隐蔽的哨所，只剩下野兽粗陋的营地和破碎的石头地基。",al={"阳光树林为何沦为废墟","阳光树林废墟","阳光树林为何被遗弃"}},f237257f={q="阳光树林危险吗？",a="阳光树林对旅人来说极其危险。凶猛的夜行狼人徘徊在黑暗的田野间，搭起粗陋的营地，并凶狠地攻击任何靠近的人。由于树林就在夜色镇正西方，这些贪婪的狼人始终威胁着城镇外围，守卫和冒险者必须积极清剿它们。",al={"阳光树林危险吗","阳光树林的危险","阳光树林有多危险"}},["90b29732"]={q="为什么叫阳光树林？",a="没有流传下来的记载解释这片树林名称的由来。这个名字似乎让人想起更明亮的往昔：当时暮色森林还是一片繁茂、阳光充沛的林地，由暴风城管辖。此后，阴影、诅咒和狼人彻底夺走了森林的光明。",al={"为什么叫阳光树林","阳光树林名称的含义","阳光树林名称的由来"}}},fp="16,279,17.516.0,26.111.0,40.174.0,40.207.0,48.152.0"}
P.entries["subzone:brill"] = {n="布瑞尔",s="布瑞尔是提瑞斯法林地中心地带主要的被遗忘者定居点，位于洛丹伦废墟正北方。这里曾是一座繁荣的人类城镇，如今已成为新苏醒的亡灵离开丧钟镇后的行政与军事枢纽。",h="布瑞尔是提瑞斯法林地中心地带主要的被遗忘者定居点，位于洛丹伦废墟正北方。这里曾是一座繁荣的人类城镇，如今已成为新苏醒的亡灵离开丧钟镇后的行政与军事枢纽。",kw={"布瑞尔","被遗忘者","恐惧之末","洛丹伦","执政官塞弗伦","提瑞斯法林地","飞艇"},ang={["faction:Horde"]="镇外的飞艇停靠点是北方部落在洛丹伦与卡利姆多及东部王国各盟友据点之间的主要交通枢纽。",["race:Undead"]="对于从丧钟镇出发的被遗忘者来说，布瑞尔是他们见到的第一处文明，也是向黑暗女王证明忠诚的起点。"},sec={{t="从瘟疫之地到堡垒",b="第三次战争前，布瑞尔是一个在巴罗夫和阿曼德家族等当地贵族统治下生机勃勃的村庄。当克尔苏加德选择此地作为诅咒教派最初的亡灵瘟疫实验场时，这种繁荣便戛然而止。毁灭性的瘟疫迅速席卷了整个居民区，当地民兵被驱逐，留下了一大片广阔的乱葬岗。\n\n如今，在执政官塞弗伦的领导下，城镇已被被遗忘者重建，保留了洛丹伦饱经风霜的建筑风格，笼罩在冷酷的目标氛围之中。布瑞尔作为地区指挥中心，负责协调防御血色十字军的入侵、游荡的天灾余孽以及被死灵腐化扭曲的当地野兽。"},{t="北洛丹伦的十字路口",b="除了本地防御，布瑞尔还是连接提瑞斯法林地与部落更广阔领土的重要十字路口。城镇上空，地精运营的飞艇塔提供前往南方的杜隆塔尔以及深入荆棘谷的交通服务。在定居点内，恐惧之末旅店不仅是旅客黑暗的避风港，也是临时的实验室，被俘的血色狂热者会在此接受审讯和药剂师的测试。"}},faq={{q="谁在统治布瑞尔？",a="执政官塞弗伦代表Sylvanas Windrunner女士和被遗忘者监管布瑞尔的民政与当地防御事务。",al={"布瑞尔领袖","谁负责布瑞尔","布瑞尔执政官"}},{q="为什么布瑞尔外有如此巨大的墓地？",a="克尔苏加德在布瑞尔进行了他最早的一些亡灵瘟疫活体实验。瘟疫以惊人的速度消灭了当地人类人口，因此必须建立一个乱葬岗来安葬受害者，以免他们复生为天灾军团。",al={"布瑞尔墓地","布瑞尔附近的公墓","为什么有那么多坟墓"}},{q="恐惧之末旅店是做什么用的？",a="除了为疲惫的旅客提供住宿外，旅店的地下室还是药剂师的基地，他们在此对被俘的血色十字军狂热者进行化学和毒理学实验。",al={"恐惧之末旅店","布瑞尔旅店","布瑞尔旅店里发生了什么"}},{q="布瑞尔外的飞艇塔通往哪里？",a="由地精团队运营的飞艇塔将洛丹伦与奥格瑞玛外的卡利姆多直接连接起来，同时还通往南方的荆棘谷格罗姆高营地。",al={"布瑞尔飞艇目的地","布瑞尔的飞艇去哪","布瑞尔飞行航线"}}},fx={["0490a2ec"]={q="布瑞尔是什么地方？",a="布瑞尔是提瑞斯法林地的中心聚居地，位于洛丹伦废墟正北方。它曾是一个沉寂的人类村庄，如今则是被遗忘者重要的军事枢纽和前哨站。从丧钟镇启程的新兵会到这里报到，协助希尔瓦娜斯·风行者女士的部队守卫周边林地，抵御不断逼近的威胁。",al={"布瑞尔是什么地方","布瑞尔概况","布瑞尔城镇"}},["3209731c"]={q="布瑞尔过去发生过什么？",a="第三次战争期间，巫妖克尔苏加德在提瑞斯法林地展开黑暗试验，布瑞尔成为最早遭受亡灵瘟疫侵袭的村庄之一。守军不敌来袭的敌人，幸存者被迫逃离，随后阿尔萨斯王子前来调查此地。天灾军团席卷王国后，被遗忘者收复了这座废弃的聚居地，并将其重建为首都以北的主要要塞枢纽。",al={"布瑞尔的历史","布瑞尔发生过什么","布瑞尔的背景故事"}},fbdb53db={q="布瑞尔危险吗？",a="布瑞尔境内有警惕的亡灵卫兵和执政官塞弗伦严密防守。然而，城镇之外危机四伏：毫无理智的天灾军团在乡野间徘徊，凶残的腐皮豺狼人搜寻附近的水道，狂热的血色十字军则在林地各处发动无休止的战争，企图彻底消灭聚居地里的所有生者。",al={"布瑞尔安全吗","布瑞尔面临的威胁","布瑞尔危险吗"}}},fp="5,273,29.744.0,32.429.0,16.135.0,52.252.0,37.176.0,54.164.0"}
P.entries["subzone:brill-town-hall"] = {n="布瑞尔城镇大厅",s="布瑞尔城镇大厅是位于提瑞斯法林地中部布瑞尔定居点的行政中心。作为镇上最显眼的建筑，它是被遗忘者管理当地领地并协调林地防御的市政总部。",h="布瑞尔城镇大厅是位于提瑞斯法林地中部布瑞尔定居点的行政中心。作为镇上最显眼的建筑，它是被遗忘者管理当地领地并协调林地防御的市政总部。",kw={"布瑞尔","被遗忘者","洛丹伦","执政官塞弗伦","塞弗伦","提瑞斯法林地","城镇大厅"},ang={["faction:Horde"]="抵达提瑞斯法的部落盟友可以访问城镇大厅，以了解被遗忘者如何在他们黑暗的家园中维持民事权威和军事秩序。",["race:Undead"]="对于从丧钟镇出发探索的被遗忘者来说，这座城镇大厅代表了他们在希尔瓦娜斯女王统治下第一次体验到有组织的市政管理，当地的防御和收复工作都在这里被正式组织起来。"},sec={{t="被遗忘者的市政中心",b="尽管洛丹伦的大部分地区已破碎废弃，但布瑞尔城镇大厅在亡灵的统治下依然作为一座正常运作的市政中心屹立不倒。执政官塞弗伦在室内指挥镇务，并向被遗忘者的冒险者发布重要的任务和指令。除了阿拉希高地的污染者之穴外，它是已知世界中为数不多由被遗忘者积极运营的公认城镇大厅，既是对旧洛丹伦市政官僚体制的一种阴暗嘲讽，也是其职能的延续。"}},faq={{q="布瑞尔城镇大厅有什么用途？",a="它作为布瑞尔定居点的当地政府驻地。被遗忘者的领导层，特别是执政官塞弗伦，利用这座建筑来协调当地防御、发布法令，并为旅行者和新苏醒的亡灵分配重要任务。",al={"布瑞尔城镇大厅的用途","这是什么建筑","为什么要访问布瑞尔城镇大厅"}},{q="这里由谁负责？",a="执政官塞弗伦在讲台上主持城镇大厅的工作，代表被遗忘者管理市政事务，并指挥提瑞斯法林地中部的各项行动。",al={"谁管理布瑞尔城镇大厅","布瑞尔城镇大厅领导者","执政官是谁"}},{q="为什么这个城镇大厅比其他的更值得注意？",a="城镇大厅通常是人类王国遗留的古迹。布瑞尔城镇大厅之所以引人注目，是因为它是少数由被遗忘者维护和运营的活跃市政厅之一，仅与阿拉希高地的污染者之穴等地点相似。",al={"独特的被遗忘者城镇大厅","还有其他被遗忘者城镇大厅吗"}}},fx={["27f01e5a"]={q="布瑞尔城镇大厅是什么地方？",a="布瑞尔城镇大厅是提瑞斯法林地中部布瑞尔聚居地最醒目的建筑。它是城镇的民政与行政中心，被遗忘者的领袖在此处理地方事务，并协调整个地区的行动。",al={"布瑞尔城镇大厅是什么地方","布瑞尔城镇大厅的位置","布瑞尔大厅"}},["0a44eaf1"]={q="布瑞尔城镇大厅危险吗？",a="如果你是被遗忘者或部落的盟友，这里并不危险。布瑞尔城镇大厅牢牢掌握在被遗忘者手中，是他们安全的地方政务中心。不过，任何敌视黑暗女王的闯入者都休想在这里得到宽恕。",al={"布瑞尔城镇大厅危险吗","布瑞尔城镇大厅安全吗","布瑞尔城镇大厅的危险"}}},fp="15,278,26.509.0,37.251.0,22.176.0,49.226.0"}
P.entries["subzone:broken-hall"] = {n="Broken Hall",s="Broken Hall是位于悲伤沼泽的沉没的神庙中被淹没的外部入口。当伟大的巨龙守护者伊瑟拉和她的龙群将这座宏伟的祖尔金字塔拖入水下时，这里变得支离破碎。随着阿塔莱狂热者撤退到更深处的圣殿，这片废墟如今已荒废无人。",h="Broken Hall是位于悲伤沼泽的沉没的神庙中被淹没的外部入口。当伟大的巨龙守护者伊瑟拉和她的龙群将这座宏伟的祖尔金字塔拖入水下时，这里变得支离破碎。随着阿塔莱狂热者撤退到更深处的圣殿，这片废墟如今已荒废无人。",kw={"阿塔莱","broken hall","hall of masks","泪水之池","沉没的神庙","悲伤沼泽","阿塔哈卡神庙"},ang={["race:Troll"]="对于崇敬洛阿神的巨魔来说，Broken Hall是一个严酷的提醒，时刻铭记着那些违抗同族去侍奉剥魂者哈卡的阿塔莱狂热者所遭受的毁灭。"},sec={{t="被淹没的入口",b="当绿龙军团将愤怒降临在阿塔莱祭司身上，并将他们邪恶的祖尔金字塔沉入泪水之池下时，最外层的建筑首当其冲，承受了这场灾难。Broken Hall的地面彻底坍塌，导致浑浊的沼泽水淹没了整个房间。由于损毁和淹没，巨魔邪教徒放弃了这个入口大厅，撤退到了建筑群的更深处。进入沉没的神庙的冒险者必须穿过这些浸水的废墟，然后登上台阶才能到达Hall of Masks。"}},faq={{q="Broken Hall是什么？",a="它是阿塔哈卡神庙最外层的入口房间，位于泪水之池下被水淹没的入口之后。",al={"broken hall 概况","这是什么地方","神庙入口大厅"}},{q="为什么Broken Hall会被淹没并遭到破坏？",a="当绿龙军团为了阻止血神哈卡的召唤，将整个神庙拖入沼泽水下时，这个房间遭到了破坏，地面崩塌，大厅被淹没。",al={"为什么 broken hall 会潮湿","为什么 broken hall 会被淹没","是谁破坏了大厅"}},{q="还有阿塔莱巨魔住在那个大厅里吗？",a="Broken Hall本身基本上已经被遗弃了。在上层神庙被淹没后，阿塔莱邪教徒撤退到了建筑群内部更干燥、防御性更强的地方。",al={"broken hall 中的敌人","broken hall 是空的吗"}},{q="Broken Hall里的楼梯通向哪里？",a="沿着从被淹没的Broken Hall通出的石阶向上走，探险者可以直接进入Hall of Masks。",al={"broken hall 的楼梯","broken hall 出口","从 broken hall 出发去哪里"}}},fp="11,304,17.555.0,24.141.0,42.193.0,49.184.0,44.115.0"}
P.entries["subzone:broken-pillar"] = {n="破碎石柱",s="破碎石柱是一处风化严重的古代巨魔遗迹，从加基森南部的沙丘中突兀而出。它成为了地精勘探员兼科学家玛尔冯·瑞文斯克的孤立研究站，他在那里研究掩埋在周围沙地下的神秘神器。",h="破碎石柱是一处风化严重的古代巨魔遗迹，从加基森南部的沙丘中突兀而出。它成为了地精勘探员兼科学家玛尔冯·瑞文斯克的孤立研究站，他在那里研究掩埋在周围沙地下的神秘神器。",kw={"破碎石柱","加基森","加兹瑞迪安","玛尔冯·瑞文斯克","棘齿城","塔纳利斯","巨魔遗迹"},ang={["race:Gnome"]="驱使玛尔冯·瑞文斯克研究未知遗物特性的好奇心反映了侏儒的学术野心，尽管他的研究方法仍带有独特的地精风格。",["race:Troll"]="这些破碎的石柱是祖先巨魔建筑的庄严标志，回响着那个帝国对卡利姆多南部的统治被时间和沙尘所摧毁之前的时代。"},sec={{t="日晒褪色的岩石",b="破碎石柱从加基森南部、危险的深沙平原东部的沙海中升起，标志着早已被塔纳利斯吞没的古代巨魔建筑的残余。尽管周围环境荒凉且有沙漠野兽出没，但该遗址为探索这片大陆的史前文明提供了珍贵的线索。玛尔冯·瑞文斯克是一位原本驻扎在棘齿城的地精研究员，他在破碎的石雕旁建立了一个孤零零的营地，以研究散布在荒野中、被称为“加兹瑞迪安”的奇特遗物。"}},faq={{q="破碎石柱是什么？",a="破碎石柱是一处位于塔纳利斯中部、加基森南部以及深沙平原东部的古代巨魔遗迹。除了风化的石柱和半埋在流沙中的碎片外，原来的结构几乎所剩无几。",al={"破碎石柱 塔纳利斯","破碎石柱是什么","石柱遗迹"}},{q="谁在破碎石柱扎营？",a="来自棘齿城、充满好奇心的地精科学家兼勘探员玛尔冯·瑞文斯克在遗迹中设立了一个单独的研究营地。他正在调查埋藏在周围沙漠各处的神秘“加兹瑞迪安”饰品。",al={"谁在破碎石柱","破碎石柱npc","玛尔冯·瑞文斯克位置"}},{q="这里的原始遗迹是谁建造的？",a="这些石雕具有古代巨魔的设计风格，其历史可以追溯到古代巨魔帝国统治卡利姆多南部地区的时代，远在沙漠吞没该地区之前。",al={"谁建造了破碎石柱","破碎石柱历史","破碎石柱起源"}},{q="什么是加兹瑞迪安遗物？",a="“加兹瑞迪安”是埋藏在塔纳利斯沙地中的古代石制神器和雕刻面具。玛尔冯·瑞文斯克在他的破碎石柱营地研究这些物品，试图解开那个消失的帝国工艺中所蕴含的秘密与力量。",al={"加兹瑞迪安","什么是加兹瑞迪安","玛尔冯任务物品"}}},fp="13,279,18.526.0,26.242.0,35.228.0,34.177.0,28.228.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="铜须营地",s="铜须营地是位于希利苏斯南部的一处坚固的矮人前哨站，坐落在巨大的甲虫之墙以东。该营地由探险者协会的坚韧探险家和研究人员负责，是调查古老其拉符文和埋藏在沙漠黄沙之下的久远谜团的行动基地。",h="铜须营地是位于希利苏斯南部的一处坚固的矮人前哨站，坐落在巨大的甲虫之墙以东。该营地由探险者协会的坚韧探险家和研究人员负责，是调查古老其拉符文和埋藏在沙漠黄沙之下的久远谜团的行动基地。",kw={"铜须营地","死亡之钳","探险者协会","弗兰卡尔·石桥","格里布","鲁特加尔·雕石","甲虫之墙","希利苏斯"},ang={["faction:Alliance"]="对于在希利苏斯阴郁荒原上穿行的联盟旅行者来说，这座偏远的营地提供了一处远在塞纳里奥要塞以南、值得信赖的友好哨点。",["race:Dwarf"]="这座前哨站展示了探险者协会坚定不移的韧性，证明了对于寻求历史真相的铁炉堡矮人来说，没有任何贫瘠的沙漠是无法征服的。"},sec={{t="流沙中的落脚点",b="铜须营地背靠希利苏斯荒凉的南部悬崖，为这片危机四伏的荒原提供了一处难得的矮人避难所。该营地建立在铁炉堡考古事业的赞助之下，与高耸的甲虫之墙遥遥相望。在这里，像鲁特加尔·雕石和弗兰卡尔·石桥这样的研究人员不畏灼人的酷热、蝎形虫以及不断逼近的其拉虫群，致力于研究被遗忘的文明所留下的独特铭文和纪念碑。"},{t="符文与绝望",b="在营地里的生活绝非一场平静的挖掘。随着其拉虫人的威胁从横跨荒原的地下巢穴中蔓延开来，以及像可怕的巨型蝎形虫“死亡之钳”这样的危险怪物在附近的沙地上徘徊，这个前哨站必须在严谨的学术研究与艰难的生存之间保持平衡。研究人员非常依赖前来造访的冒险者去获取晦涩符文的拓片，破译古老的虫族语言，并寻找那些深入沙漠疯狂之中而失踪的同伴。"}},faq={{q="铜须营地在哪里？",a="该营地位于希利苏斯南部，坐落在巨大的甲虫之墙以东，南部山脊以北。",al={"铜须营地在哪里","铜须营地位置","如何找到铜须营地"}},{q="谁在管理铜须营地？",a="营地由矮人探险者协会的成员和相关人员组成，包括符文研究员鲁特加尔·雕石、弗兰卡尔·石桥以及他们的同伴格里布。",al={"谁在铜须营地","铜须营地npc","谁领导铜须营地"}},{q="矮人们在这里研究什么？",a="研究人员致力于破译古老的石刻符文，理解其拉虫人的交流系统，并挖掘卡利姆多南部深埋已久的秘密。",al={"矮人为什么在希利苏斯","鲁特加尔在研究什么","铜须营地的目的"}},{q="营地附近潜伏着什么威胁？",a="营地周围的沙漠中游荡着富有攻击性的其拉虫人、沙蝎，以及臭名昭著的巨型蝎形虫“死亡之钳”，它就在东南方向筑巢。",al={"铜须营地附近的危险","死亡之钳位置","铜须营地怪物"}}},fp="22,331,32.498.0,22.486.0,44.131.0,36.178.0,35.176.0,38.187.0"}
P.entries["subzone:browman-mill"] = {n="布洛米尔",s="布洛米尔是一座被枯萎病侵蚀的锯木厂，位于东瘟疫之地圣光之愿礼拜堂的北面。它曾是洛丹伦木材贸易中欣欣向荣的一部分，如今却在天灾军团的铁腕统治下，到处充斥着亡灵爪牙。它曾经的主人，斯蒂芬·布洛曼，在死后仍被困在他那破败的工场之中。",h="布洛米尔是一座被枯萎病侵蚀的锯木厂，位于东瘟疫之地圣光之愿礼拜堂的北面。它曾是洛丹伦木材贸易中欣欣向荣的一部分，如今却在天灾军团的铁腕统治下，到处充斥着亡灵爪牙。它曾经的主人，斯蒂芬·布洛曼，在死后仍被困在他那破败的工场...",kw={"憎恶","女妖","布洛米尔","东瘟疫之地","圣光之愿礼拜堂","锯木厂","天灾军团","斯蒂芬·布洛曼"},ang={["class:Paladin"]="被亵渎的锯木厂残骸以及在此地游荡的受折磨的灵魂，代表了圣职者们致力于从洛丹伦清除的一切邪恶。",["race:Undead"]="斯蒂芬·布洛曼的被奴役，鲜明地提醒了人们所有巫妖王的受害者所共同面临的命运——他们没能像被遗忘者那样获得自由意志。"},sec={{t="荒废的产业",b="在第三次战争之前，布洛米尔为洛丹伦周边的城镇和农庄提供服务，加工从东威尔德富饶森林中采伐的木材。当天灾瘟疫席卷王国时，这座锯木厂同该省的其他地区一样陷落了。如今，腐朽的木梁和破碎的轮轴闲置在那里，而憎恶、女妖和骷髅怪在周边巡逻。由于它紧邻圣光之愿礼拜堂，这使得它成为了亡灵大军紧逼银色黎明家门口的一个持续且危险的警示。"},{t="监管者的命运",b="锯木厂最初的主人，斯蒂芬·布洛曼，遭遇了与洛丹伦无数平民同样的惨淡命运。当被天灾军团入侵时，他被谋杀，并被复活成了贪婪的食尸鬼。他的人性被剥夺，沦为巫妖王意志的奴隶。布洛曼徘徊在他曾经的锯木厂的黑暗深处，守卫着他毕生心血的破碎废墟。"}},faq={{q="布洛米尔位于哪里？",a="布洛米尔位于东瘟疫之地的最东侧，坐落在圣光之愿礼拜堂的正北方。",al={"布洛米尔位置","布洛米尔在哪里","如何找到布洛米尔"}},{q="什么类型的敌人盘踞在锯木厂？",a="这片区域遍布天灾军团的势力，包括巨大的憎恶、哀嚎的女妖、骷髅怪和游荡的食尸鬼。",al={"布洛米尔怪物","谁在布洛米尔","布洛米尔有什么生物"}},{q="斯蒂芬·布洛曼是谁？",a="斯蒂芬·布洛曼是这座锯木厂最初的人类所有者和经营者。他在洛丹伦陷落期间被杀害，并被复活为一个亡灵食尸鬼，被迫守卫他那破败的建筑。",al={"斯蒂芬·布洛曼是谁","斯蒂芬·布洛曼背景故事","布洛曼食尸鬼"}},{q="为什么布洛米尔对旅行者来说很危险？",a="这里聚集了大量的强力亡灵，使其成为一个致命的危险地带，尤其是因为它距离银色黎明在圣光之愿礼拜堂的据点仅有很短的路程。",al={"为什么布洛米尔危险","布洛米尔的威胁"}}},fp="12,323,17.538.0,19.371.0,30.125.0,38.134.0,24.196.0,43.175.0"}
P.entries["subzone:bulwark"] = {n="亡灵壁垒",s="亡灵壁垒是一座横跨在提瑞斯法林地与西瘟疫之地边界上的防御前哨站。它由被遗忘者和中立的银色黎明共同维护，是部落对抗天灾军团的第一道防线，也是向被污染的东方地区派遣远征军的主要出发点。",h="亡灵壁垒是一座横跨在提瑞斯法林地与西瘟疫之地边界上的防御前哨站。它由被遗忘者和中立的银色黎明共同维护，是部落对抗天灾军团的第一道防线，也是向被污染的东方地区派遣远征军的主要出发点。",kw={"银色黎明","亡灵壁垒","寒风营地","被遗忘者","天灾军团","提瑞斯法","西瘟疫之地"},ang={["faction:Horde"]="亡灵壁垒是部落对应联盟寒风营地的据点，作为进入瘟疫之地进行各项行动的主要入口和作战基地。",["race:Undead"]="对于被遗忘者来说，亡灵壁垒是一个关键的咽喉要道，它阻止了巫妖王的军队直接向布瑞尔和幽暗城进军。"},sec={{t="对抗天灾军团的护盾",b="亡灵壁垒位于提瑞斯法林地的东部边缘，是保卫被遗忘者核心领土免受西瘟疫之地枯萎恐怖侵害的最后一道屏障。如今，粗糙的木制栅栏和全副武装的卫兵把守着隘口，抵御着游荡的亡灵。这是一个虽然不安但却必要的合作，被遗忘者部队与银色黎明在此协作，招募部落的精锐勇士，在巫妖王的爪牙涌入提瑞斯法之前将其击退。"}},faq={{q="亡灵壁垒的目的是什么？",a="亡灵壁垒是部落对抗天灾军团的首要防御驻地和集结地。它保护着提瑞斯法林地和幽暗城免受西瘟疫之地涌出的入侵，同时也驻扎着协调进攻污染地区的银色黎明和被遗忘者指挥官。",al={"为什么会有亡灵壁垒","亡灵壁垒的用途","这是什么地方"}},{q="联盟角色可以前往亡灵壁垒与银色黎明交谈吗？",a="不可以。尽管驻扎在那里的银色黎明代表是中立的，但该营地驻扎着大量的被遗忘者卫兵。任何踏入栅栏范围内的联盟成员都会立即遭到攻击。",al={"联盟可以使用亡灵壁垒吗","联盟在亡灵壁垒","亡灵壁垒是部落专属吗"}},{q="对于离开提瑞斯法的年轻冒险者来说，亡灵壁垒安全吗？",a="不安全。虽然大门直接连接着提瑞斯法林地，但外面的西瘟疫之地充满了致命的高等级亡灵和瘟疫锅。新手旅行者如果越过栅栏，将面临迅速死亡的危险。",al={"低等级可以越过亡灵壁垒吗","低等级进入瘟疫之地"}}},fx={["3800d924"]={q="亡灵壁垒是什么地方？",a="亡灵壁垒是一座坚固的前哨站，坐落在提瑞斯法林地与西瘟疫之地的交界处。它是被遗忘者东部防线的一环，守卫着提瑞斯法林地的入口，抵御天灾军团无休止的恐怖威胁。在这里，被遗忘者哨兵与银色黎明的使者并肩协作，共同部署防御、阻挡亡灵入侵，并派遣能干的勇士深入前方的疫病之地。",al={"亡灵壁垒是什么地方","亡灵壁垒概况","亡灵壁垒介绍"}},["7098c368"]={q="谁驻守亡灵壁垒？",a="这座前哨站由效忠希尔瓦娜斯女王的被遗忘者士兵，以及中立组织银色黎明的成员共同驻守。被遗忘者负责守卫边境、保卫北方王国，银色黎明则在此招募经验丰富的部落冒险者，派遣他们前往瘟疫之地打击巫妖王的爪牙。",al={"谁在管理亡灵壁垒","谁驻守亡灵壁垒","亡灵壁垒的居民"}},a92b042c={q="为什么叫亡灵壁垒？",a="这座要塞因其职责而得名：它是一道真正的壁垒，用于保护被遗忘者的领地免遭入侵。它正处于提瑞斯法林地与瘟疫之地的交界处，厚重的路障构成了最后一道防线，阻挡天灾军团的怪物大军。",al={"为何称作亡灵壁垒","亡灵壁垒名称的含义","亡灵壁垒为何得名"}}},fp="7,300,28.508.0,35.301.0,72.208.0,59.216.0"}
P.entries["subzone:burning-blade-coven"] = {n="火刃集会所",s="火刃集会所隐藏在试炼谷北部的悬崖中，是一个受腐蚀的洞穴网络，威胁着部落的新兵。堕落的邪教徒和被召唤的恶魔潜伏其中，将一个古老的矿洞变成了杜隆塔尔家门口施展黑暗魔法的基地。",h="火刃集会所隐藏在试炼谷北部的悬崖中，是一个受腐蚀的洞穴网络，威胁着部落的新兵。堕落的邪教徒和被召唤的恶魔潜伏其中，将一个古老的矿洞变成了杜隆塔尔家门口施展黑暗魔法的基地。",kw={"火刃集会所","恶魔","杜隆塔尔","小鬼","塔兹利尔","试炼谷","亚罗格·碎影"},ang={["class:Warlock"]="这里的恶魔小鬼和黑暗仪式是一个早期的警示，让人一窥当邪能被鲁莽地使用并公然反抗部落时会发生什么。",["race:Orc"]="火刃氏族邪教在如此靠近试炼谷的地方出现，是对萨尔的新部落不可容忍的侮辱，也是兽人们竭力想要摆脱的恶魔崇拜的严酷提醒。"},sec={{t="试炼场上的阴影",b="The dusty red mountains rimming the Valley of Trials were once simply a testing wilderness for young orcs and Darkspear trolls taking their first steps in service to the Horde. In recent days, however, dark rituals have taken hold of the northern caves. Imps and lesser fiends spill from the cavern mouth, stirring chaos and threatening recruits. Led by the shadowy warlock Yarrog Baneshadow, the Burning Blade cult has entrenched itself deep inside, turning what was once a routine training ground into an active battleground against demonic corruption."},{t="岩石中的腐蚀",b="在恶魔扎根之前，这些洞穴曾吸引了当地监工的注意，他们希望在此为定居点开采原材料。工头塔兹利尔深入洞穴进行矿产勘探，却被仓促赶出，丢下了宝贵的装备，因为邪教徒暴露了他们的存在。现在，击退碎影的集会所成为了有抱负的战士、潜行者和施法者在被认为有资格前往更广阔的杜隆塔尔之前，必须完成的终极试炼。"}},faq={{q="火刃集会所位于哪里？",a="洞穴嵌入在试炼谷北缘的红色高岩脊中，位于杜隆塔尔。",al={"集会所位置","火刃集会所在哪","山谷洞穴位置"}},{q="是谁领导着这里的邪教徒？",a="这个集会所由一名叫作亚罗格·碎影的术士领导，他指挥着当地的仪式并统领着被召唤的恶魔。",al={"集会所首领","谁领导火刃集会所","亚罗格"}},{q="里面潜伏着什么样的敌人？",a="洞穴里到处都是堕落的小鬼、低阶恶魔仆从，以及效忠于暗影火刃氏族邪教的凡人侍僧。",al={"洞穴里有什么怪物","集会所怪物","试炼谷里的恶魔"}},{q="为什么新兵要进入这个洞穴？",a="勇敢地深入洞穴的黑暗深处，找回工头塔兹利尔的矿工镐等遗失工具，并击杀亚罗格·碎影，这是兽人和巨魔冒险者在离开山谷前最后的入会仪式。",al={"为什么要去集会所","集会所目的","集会所最终考验"}}},fx={["8ab36280"]={q="火刃集会所是什么地方？",a="火刃集会所是一处幽暗的洞穴，凿刻在试炼谷北部的红色山脉之中。它曾是一处勘探矿藏后被废弃的洞穴，如今已被恶魔崇拜者占据，威胁着部落的试炼场。",al={"火刃集会所是什么地方","火刃集会所的背景故事","这座洞穴是什么地方"}},["7f26a7cc"]={q="火刃集会所危险吗？",a="它对试炼谷构成了严重威胁。顽皮的小鬼和危险的恶魔开始从洞口涌出，火刃氏族的邪恶成员则潜伏在洞穴深处。对立志成为冒险者的兽人和巨魔来说，进入洞穴面对这些危险，是他们获准前往杜隆塔尔之前的最后一项试炼。",al={"火刃集会所危险吗","集会所有多危险","这里安全吗"}},["5cf26a24"]={q="为什么叫火刃集会所？",a="这处洞穴因暗中占据其隧道的火刃氏族而得名。他们把洞穴中隐蔽的空穴当作集会所，与恶魔实体密谋，并在导师们眼皮底下策划对年轻部落不利的阴谋。",al={"为什么叫火刃集会所","火刃集会所名称的由来","谁给火刃集会所命名"}}},fp="19,297,33.554.0,23.490.0,41.117.0,28.118.0,34.127.0,37.216.0"}
P.entries["subzone:caer-darrow"] = {n="凯尔达隆",s="凯尔达隆是一座位于西瘟疫之地达隆米尔湖上的堡垒岛屿。它曾是贵族巴罗夫家族的领地，后来岛上的要塞被秘密卖给了克尔苏加德，并被改造为通灵学院，使得地表的城镇中充满了游荡的幻影。",h="凯尔达隆是一座位于西瘟疫之地达隆米尔湖上的堡垒岛屿。它曾是贵族巴罗夫家族的领地，后来岛上的要塞被秘密卖给了克尔苏加德，并被改造为通灵学院，使得地表的城镇中充满了游荡的幻影。",kw={"巴罗夫","凯尔达隆","the cult of the damned","达隆米尔湖","加丁","符文石","萨尔科夫","通灵学院","幽灵精华"},ang={["faction:Alliance"]="对于联盟而言，凯尔达隆代表了两次深重的背叛：第二次战争期间奥特兰克私掠船的伏击揭露了佩瑞诺德国王的叛国行径，以及巴罗夫家族将他们的祖宅卖给了克尔苏加德。",["race:Human"]="人类旅行者会认出这座岛屿曾是巴罗夫家族的领地，在他们的贪婪导致与The Cult of the Damned签订契约之前，该家族曾是洛丹伦最富有的贵族家庭之一。"},sec={{t="战争与背叛的遗产",b="在天灾军团出现很久之前，凯尔达隆是洛丹伦的一处战略要塞，守护着一块古老的精灵符文石。第二次战争期间，部落洗劫了这座要塞，并将符文石切开，用以建造古尔丹的风暴祭坛。当光明使者乌瑟尔乘船前来向幸存者提供援助时，他的舰队遭到了奥特兰克私掠船的伏击——这一背信弃义的行为向联盟揭露了奥特兰克的背叛。"},{t="巴罗夫家族的没落",b="凯尔达隆在第二次战争后得以重建，作为巴罗夫家族奢华的庄园，他们拥有横跨布瑞尔、塔伦米尔和南海镇的大片土地契约。随着年岁渐长，为了保住财富和永恒的生命，巴罗夫家族与克尔苏加德达成了一笔交易。The Cult of the Damned在要塞之下扎根，建立了通灵学院。甚至在第三次战争席卷洛丹伦之前，一场预备性的瘟疫就已经在岛上的仆人和城镇居民中爆发了。民众们纷纷丧命，被诅咒永远徘徊在残破的要塞中，化作挥之不去的余音。"}},faq={{q="什么是凯尔达隆？",a="凯尔达隆是一座位于西瘟疫之地达隆米尔湖中的堡垒岛屿。它曾是富有的巴罗夫家族引以为傲的祖宅，如今却成了一片阴森的废墟，其地下墓穴中坐落着被称为通灵学院的亡灵法术学院。",al={"凯尔达隆概况","这里是什么地方","凯尔达隆背景故事"}},{q="为什么这座城镇会被废弃并成为废墟？",a="巴罗夫家族与克尔苏加德进行了交易，将他们的庄园卖给了The Cult of the Damned以换取永生。该教派利用要塞的仆人进行早期的亡灵法术实验，并在针对洛丹伦的大规模入侵开始前，向整个定居点散布了一场致命的瘟疫。",al={"凯尔达隆为何被毁","凯尔达隆发生了什么","凯尔达隆历史"}},{q="为什么我在镇上看不到鬼魂？",a="凯尔达隆被谋杀的居民徘徊在此，变成了被困在最后时刻的游荡之魂。若没有特殊的魔法视觉，普通双眼无法看见它们，例如使用由伊娃和卢森·萨尔科夫的灵魂所提供的幽灵精华。",al={"鬼魂在哪里","凯尔达隆的隐形人","如何看见鬼魂"}},{q="这里曾经有过什么符文石？",a="在第二次战争期间，凯尔达隆曾安置着一块古老的高等精灵符文石。部落袭击了该岛，并将这块神圣的石头凿成碎片，古尔丹利用这些碎片建造了风暴祭坛，以此为食人魔法师引导能量。",al={"凯尔达隆的符文石","精灵符文石","风暴祭坛之石"}},{q="要塞之下有什么？",a="要塞之下坐落着通灵学院，这是The Cult of the Damned的总部和训练基地。在黑暗院长加丁的领导下，学院内的亡灵法师和侍僧们研究黑暗艺术并对死者进行实验。",al={"凯尔达隆之下有什么","地下室里有什么","凯尔达隆下的地下城"}}},fp="11,317,28.424.0,23.548.1,20.236.0,37.298.0,39.248.1,44.232.0,32.217.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Calmbreeze Inn",s="Calmbreeze Inn是指遍布泽风岛各地、提供住所与服务的首要场所，在申达尔村和Valaanar均有分布。它们是探索岛屿的旅行者必不可少的休憩之所，驻有当地的商业训练师、旅店老板，并陈列着历史文物。",h="Calmbreeze Inn是指遍布泽风岛各地、提供住所与服务的首要场所，在申达尔村和Valaanar均有分布。它们是探索岛屿的旅行者必不可少的休憩之所，驻有当地的商业训练师、旅店老板，并陈列着历史文物。",kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","申达尔村","valaanar","泽风岛"},ang={["class:Rogue"]="Miriann Mistblade在申达尔村Calmbreeze Inn的壁炉旁提供潜行者指导。",["profession:Herbalism"]="访问申达尔村的草药师可以在Calmbreeze Inn内寻找Halassa Fernbreeze，以磨练他们的采集技艺。"},sec={{t="岛上休憩",b="Calmbreeze Inn在泽风岛蜿蜒的道路中提供了一处避难所。在申达尔村，这家旅店由Coriella Calmbreeze打理，同时也是岛上商人们的聚集中心，包括草药学、剥皮和附魔训练师。在不远处的Valaanar，另一家Calmbreeze Inn为当地旅人提供住宿，并收藏着珍稀古玩，其中包括一颗记录着Eldre'Thalas远古反抗史的声音水晶。"}},faq={{q="Calmbreeze Inn位于何处？",a="在泽风岛上，申达尔村和Valaanar均设有Calmbreeze Inn。",al={"calmbreeze inn位置","calmbreeze inn在哪里","calmbreeze inn地图"}},{q="谁经营着申达尔村的旅店？",a="申达尔村的旅店由旅店老板Coriella Calmbreeze负责，为岛上的居民和旅行者提供热情接待。",al={"calmbreeze旅店老板","谁经营calmbreeze inn"}},{q="旅店里有哪些训练师？",a="在申达尔村的旅店里，驻有草药学训练师Halassa Fernbreeze、剥皮训练师Mendalass Tattermend、附魔训练师Nasalanna Windsinger以及潜行者训练师Miriann Mistblade。",al={"calmbreeze训练师","申达尔旅店训练师"}},{q="Valaanar楼上的声音水晶里记录着什么？",a="在Valaanar旅店的楼上放着一颗声音水晶，里面记录了《Eldre'Thalas的反抗》的第三部分，讲述了这座远古上层精灵城市的重要历史事件。",al={"valaanar声音水晶","eldre'thalas的反抗水晶"}}},fx={["043ce63b"]={q="Calmbreeze Inn是什么地方？",a="Calmbreeze Inn指的是一系列服务于泽风岛旅客的旅店，分别设在瓦拉纳尔和申达尔村。这些旅店是重要的社区聚集地，为疲惫的旅客提供休息之所，让他们结识当地的商贩和训练师，并收集岛上的各方消息。",al={"calmbreeze inn是什么地方","calmbreeze inn的背景故事","介绍calmbreeze inn"}},c8344be2={q="Calmbreeze Inn危险吗？",a="不危险。Calmbreeze Inn的各处分店都是申达尔村和瓦拉纳尔各自聚居地中的宁静庇护所。里面住着友善的居民，旅店老板和专业技能训练师，而没有充满敌意的威胁。",al={"calmbreeze inn安全吗","calmbreeze inn的危险"}}},fp="14,286,16.458.0,38.92.0,37.139.0,38.183.0,53.166.0"}
P.entries["subzone:camp-aparaje"] = {n="阿帕拉耶营地",s="阿帕拉耶营地曾是一个坐落在石爪山脉东部高地的宁静牛头人村庄。如今，它被敌对的恐怖图腾氏族占领，他们屠杀了原本的居民，并将这里变成了自己的前哨站。",h="阿帕拉耶营地曾是一个坐落在石爪山脉东部高地的宁静牛头人村庄。如今，它被敌对的恐怖图腾氏族占领，他们屠杀了原本的居民，并将这里变成了自己的前哨站。",kw={"阿帕拉耶营地","恐怖图腾","恐怖图腾岗哨","格伦迪格·黑云","卡雅·扁蹄","玛卡巴·扁蹄","石爪山脉"},ang={["faction:Horde"]="清除阿帕拉耶营地的恐怖图腾既是为了复仇也是为了防御，确保这个背信弃义的部族因在石爪山脉屠杀无辜的部落成员而受到惩罚。",["race:Tauren"]="阿帕拉耶营地的废墟提醒着人们玛加萨的恐怖图腾部族是何等残忍，这证明并非所有大地母亲的孩子都认同凯恩·血蹄关于荣誉与和平的愿景。"},sec={{t="悲剧的覆灭",b="阿帕拉耶营地坐落在石爪山脉的岩架上，由渴望在高原安静生活的宁静牛头人所建立。这份宁静在附近的恐怖图腾岗哨发起的袭击中被打破了，袭击由格伦迪格·黑云率领，是一场残暴且无端的突袭。村民们被屠杀或赶走，像玛卡巴·扁蹄这样的幸存者在哀悼家园毁灭的同时，也为被俘亲人的命运感到恐惧。"},{t="在恐怖图腾的统治下",b="如今，阿帕拉耶营地已完全被恐怖图腾战士占据，成为了该部族在该地区的进攻前哨。与悬挂蓝色标记的典型恐怖图腾定居点不同，立在阿帕拉耶的巨大图腾上刻着深红色的油漆。"}},faq={{q="谁曾经住在阿帕拉耶营地？",a="在被入侵之前，阿帕拉耶营地居住着隶属于部落和血蹄部族的和平牛头人，包括玛卡巴·扁蹄和他的女儿卡雅。",al={"谁住在这里","阿帕拉耶营地的原始居民","玛卡巴·扁蹄的村庄"}},{q="为什么这个营地对部落玩家充满敌意？",a="这个村庄被恐怖图腾氏族暴力夺取，这是一个排外且背信弃义的牛头人氏族，他们拒绝效忠凯恩·血蹄，并积极攻击包括部落成员在内的外来者。",al={"为什么牛头人攻击我","谁控制着阿帕拉耶营地","为什么阿帕拉耶营地是红色的"}},{q="谁领导了对阿帕拉耶营地的袭击？",a="这次突袭由格伦迪格·黑云带头，他是恐怖图腾岗哨的一名残暴的恐怖图腾酋长，试图扩大他部族对石爪山脉的暴力控制。",al={"谁袭击了阿帕拉耶","格伦迪格·黑云","这里的领袖是谁"}},{q="幸存的村民遭遇了什么？",a="大多数居民在袭击中丧生。少数人成功逃脱，而其他人，比如年轻的卡雅·扁蹄，被恐怖图腾俘虏并关押在附近的恐怖图腾岗哨。",al={"卡雅·扁蹄","幸存者在哪里","有幸存者吗"}}},fx={fcad7814={q="阿帕拉耶营地是什么地方？",a="阿帕拉耶营地曾是石爪山脉东部高地上一处宁静的牛头人聚居地。这里是玛卡巴·扁蹄和他女儿等平静生活的家庭的家园，但当凶暴的恐怖图腾劫掠者从据点倾巢而出，强行夺取村庄时，这份安宁便被彻底打破了。",al={"阿帕拉耶营地概况","这个营地是什么地方","介绍阿帕拉耶营地"}},["358940fc"]={q="阿帕拉耶营地发生了什么？",a="敌对的恐怖图腾战士从附近的恐怖图腾岗哨突然发起了残暴袭击。袭击者由Grundig Darkcloud率领，将当地的牛头人赶走或屠杀；来不及逃脱的人则被俘虏。这支背信弃义的部族就此完全占据了这座前哨。",al={"这里发生了什么","阿帕拉耶营地历史","阿帕拉耶营地如何被摧毁"}},["8b937e47"]={q="现在由谁控制阿帕拉耶营地？",a="营地目前被Grundig Darkcloud指挥的恐怖图腾劫掠者占据。驱逐原住民后，这些敌对的牛头人将村落用作活跃的营地，安排哨兵看守，并严加看管俘虏。",al={"谁住在阿帕拉耶营地","谁占据了阿帕拉耶营地","阿帕拉耶营地里有哪些人"}},["33da0239"]={q="阿帕拉耶营地的原住民为何离开？",a="面对恐怖图腾发动的突袭，和平的村民毫无还手之力。最初的屠杀中幸存下来的人，例如玛卡巴·扁蹄，被迫逃入周围的荒野求生。他们丢下家园和财物，任由征服者洗劫。",al={"阿帕拉耶营地为何沦为废墟","村庄为何失守","村民为何离开"}},["46090024"]={q="阿帕拉耶营地危险吗？",a="危险。营地被凶暴的恐怖图腾战士严密占据，他们会一见到靠近营地的人就发动攻击，无论你在部落中的声望如何。踏入营地范围，就会立刻与Grundig Darkcloud手下的老练劫掠者交战。",al={"阿帕拉耶营地安全吗","阿帕拉耶营地的危险","阿帕拉耶营地的威胁"}}},fp="12,250,17.458.0,20.270.0,33.176.0,41.205.0,36.169.0,41.186.0"}
P.entries["subzone:camp-e-thok"] = {n="伊索克营地",s="伊索克营地是位于千针石林西北部的一个伽拉克半人马定居点。这个富有侵略性的半人马部族将这处峡谷营地作为据点，伏击下方河道中经过的商队。",h="伊索克营地是位于千针石林西北部的一个伽拉克半人马定居点。这个富有侵略性的半人马部族将这处峡谷营地作为据点，伏击下方河道中经过的商队。",kw={"伊索克营地","半人马","伊索克","伽拉克","千针石林","维兹罗"},ang={["race:Tauren"]="伊索克营地的伽拉克半人马那不懈的侵略性，时刻提醒着人们牛头人与半人马之间在整个南卡利姆多地区持续不断的祖辈战争。"},sec={{t="伽拉克据点",b="伊索克营地坐落于千针石林崎岖的西北部边缘，是敌对的伽拉克半人马的重要定居点。正如他们在卡利姆多各处的同族一样，伽拉克半人马生性残暴，会对任何误入峡谷阴影的旅行者下手。该营地因策划针对商队的劫掠而臭名昭著，尤其是伏击了地精维兹罗并夺走了他的货物——不过他那珍贵的小装置在凶猛的宠物黑豹的守护下，幸免于难，未落入他们手中。"}},faq={{q="谁住在伊索克营地？",a="该营地由伽拉克氏族半人马占据，这是一个统治着千针石林西北部部分地区的侵略性部族。",al={"谁在伊索克营地","伊索克营地居民","谁控制着伊索克营地"}},{q="维兹罗在这里遭遇了什么？",a="地精维兹罗的商队遭到了来自伊索克营地的伽拉克半人马的伏击。虽然他们洗劫了商队，但未能夺走维兹罗最珍视的小装置，因为它被拴在他那只凶猛的宠物黑豹的项圈上。",al={"维兹罗遇袭","地精商队遇袭","半人马从维兹罗那里偷走了什么"}},{q="伊索克营地在哪里？",a="伊索克营地位于千针石林西北部，坐落在峡谷壁的底部。",al={"伊索克营地位置","伊索克营地在哪里","伊索克营地地图"}}},fx={["740a44e0"]={q="伊索克营地是什么地方？",a="伊索克营地是加拉克半人马部族的一处常驻营地，位于千针石林西北部的峡谷中。半人马以这座设防营地为据点，在下方峡谷中伏击并袭击旅人和商队。",al={"伊索克营地是什么","伊索克营地传说","介绍伊索克营地"}},["7ec291b4"]={q="伊索克营地危险吗？",a="伊索克营地极其危险。居住在此的加拉克半人马会一见到外来者就发动攻击，掠夺胆敢穿越峡谷的商队。任何闯入营地的人都会遭遇敌对的战士、萨满，以及他们用暴力掠夺来的战利品。",al={"伊索克营地有敌意吗","伊索克营地有多危险","伊索克营地的危险"}}},fp="11,231,18.508.0,25.127.0,42.256.0,29.101.0"}
P.entries["subzone:camp-kosh"] = {n="柯什营地",s="柯什营地是位于荒芜之地北部的一个食人魔营地，居住着凶猛的尘牙食人魔。该营地坐落在关键的交通要道附近，其蛮兵会劫掠路过的商队，并搜刮旅行者在严酷沙漠中留下的任何装备。",h="柯什营地是位于荒芜之地北部的一个食人魔营地，居住着凶猛的尘牙食人魔。该营地坐落在关键的交通要道附近，其蛮兵会劫掠路过的商队，并搜刮旅行者在严酷沙漠中留下的任何装备。",kw={"荒芜之地","柯什营地","尘牙","食人魔","西格鲁·铁斧","奥达曼"},ang={["faction:Alliance"]="沿北部通道前往灼热峡谷的联盟侦察兵在经过柯什营地附近时必须保持警惕，因为那些蛮兵随时准备伏击路过的补给商队。",["race:Dwarf"]="柯什营地的食人魔拾荒者掠夺了西格鲁·铁斧陷入困境的奥达曼探险队留下的重要口粮和武器储备。"},sec={{t="拾荒者的巢穴",b="柯什营地坐落在荒芜之地的北部荒野，是尘牙食人魔最北端的定居点，这些食人魔还占据着博夫、卡格和沃格等周边营地。驻扎在此的食人魔利用紧邻道路的便利，劫掠前往卡加斯或向西进入灼热峡谷的脆弱补给线。当西格鲁·铁斧带领的矮人勘探者被迫逃离奥达曼的挖掘现场时，柯什营地的蛮兵迅速洗劫了他们遗弃的货车，并将珍贵的口粮和武器搬回了尘土飞扬的营地中。"}},faq={{q="谁住在柯什营地？",a="柯什营地居住着尘牙食人魔，这是一个凶残的食人魔部落，在荒芜之地的干旱地区控制着几个小型营地。",al={"柯什营地怪物","柯什营地里是谁","柯什营地食人魔"}},{q="为什么柯什营地建在这里？",a="其北部的位置使尘牙食人魔能够伏击在灼热峡谷、奥达曼和部落前哨站卡加斯之间往来的补给商队和毫无防备的旅行者。",al={"为什么有柯什营地","柯什营地位置"}},{q="食人魔从矮人那里偷走了什么？",a="当西格鲁·铁斧的矮人探险队从奥达曼内部的危险中撤退时，他们在沙漠中遗弃了补给货车。柯什营地的食人魔搜刮了残骸，并抢走了成箱的食物和武器货物。",al={"柯什营地矮人补给","西格鲁·铁斧补给","奥达曼货车"}}},fp="9,250,19.583.0,23.138.0,30.177.0,42.227.0"}
P.entries["subzone:camp-mojache"] = {n="莫沙彻营地",s="莫沙彻营地是部落在菲拉斯的主要前哨站，它是一座加固的牛头人定居点，坐落于汇入狂风湖的水域旁。对于那些需要应对这片未被驯服的荒野、凶猛的野生动物以及深林中古老废墟的旅行者来说，这里提供了栖身之所、补给品和飞行连接点。",h="莫沙彻营地是部落在菲拉斯的主要前哨站，它是一座加固的牛头人定居点，坐落于汇入狂风湖的水域旁。对于那些需要应对这片未被驯服的荒野、凶猛的野生动物以及深林中古老废墟的旅行者来说，这里提供了栖身之所、补给品和飞行连接点。",kw={"勇士","莫沙彻营地","菲拉斯","飞行管理员","戈多克","牛头人","狂风湖","木爪"},ang={["faction:Horde"]="作为部落在菲拉斯唯一的加固枢纽，莫沙彻是你休息、补充物资和确保在深林中快速交通的唯一避难所。",["race:Tauren"]="莫沙彻营地代表了你们的民族在卡利姆多的传统工艺和定居点所能到达的最南端，在茂密的雨林中开辟出一片和谐之地。"},sec={{t="雨林中的牛头人堡垒",b="莫沙彻营地位于菲拉斯东部，坐落于一条汇入狂风湖的湍急溪流旁。这是一座牛头人定居点，旨在为部落在这片狂野的南部森林中稳固立足。虽然茂密的丛林中潜伏着危险——从野蛮的野生动物到戈多克食人魔和好斗的木爪豺狼人——但这座营地仍是一座安全的避风港。这里配备了住所、贸易商和双足飞龙管理员，是部落勇士在该地区行动的重要后勤枢纽。"},{t="边境前哨站",b="营地的猎手和勇士以勇气和坚韧著称，时刻保持警惕，防御来自周围荒野的袭击。对部落而言，守住莫沙彻营地对于在菲拉斯保持影响力至关重要，同时也能够牵制沿海的暗夜精灵以及潜伏在厄运之槌中的黑暗势力。"}},faq={{q="莫沙彻营地是什么？",a="莫沙彻营地是部落在菲拉斯的主要行动基地。它主要由牛头人建造和维护，横跨一条流入狂风湖的溪流，提供休息设施、贸易物资和飞行交通服务。",al={"莫沙彻营地的目的","这个营地是什么","菲拉斯的牛头人城镇"}},{q="谁领导或保卫这座营地？",a="该定居点由经验丰富的牛头人勇士负责保卫，他们防范着当地野兽群、戈多克食人魔以及在南部丘陵中徘徊的好斗的木爪豺狼人的入侵。",al={"莫沙彻营地的守卫","谁保卫莫沙彻","谁负责莫沙彻营地"}},{q="当地的飞行管理员可以去往哪里？",a="从营地的双足飞龙栖木出发，旅行者可以到达诸如雷霆崖、贫瘠之地的十字路口、凄凉之地的葬影村以及塔纳利斯加基森等邻近前哨站等中心枢纽。",al={"莫沙彻营地飞行路线","我能从莫沙彻营地飞往哪里"}},{q="莫沙彻营地周围有哪些主要威胁？",a="营地周围的森林里栖息着南部的木爪豺狼人氏族、北部和南部的戈多克食人魔，以及在远方西海岸羽月要塞活动的联盟部队。",al={"菲拉斯莫沙彻营地的危险","莫沙彻营地附近的威胁","莫沙彻附近的敌人"}}},fp="12,306,34.478.0,16.347.0,21.230.0,30.192.0,42.204.0,41.211.0"}
P.entries["subzone:camp-narache"] = {n="纳拉其营地",s="纳拉其营地是一座隐蔽的村落，坐落在莫高雷南部的红云台地上。它是鹰风部族的祖居地，也是年轻的牛头人开始训练的试炼场。营地高踞于平原之上，在保持古老传统的同时，时刻警惕着入侵的野猪人和徘徊的半人马威胁。",h="纳拉其营地是一座隐蔽的村落，坐落在莫高雷南部的红云台地上。它是鹰风部族的祖居地，也是年轻的牛头人开始训练的试炼场。营地高踞于平原之上，在保持古老传统的同时，时刻警惕着入侵的野猪人和徘徊的半人马威胁。",kw={"钢鬃","鹰风酋长的母亲","鹰风","莫高雷","纳拉其","红云台地","灵魂之屋","牛头人"},ang={["class:Shaman"]="年轻的萨满祭司在此踏上灵魂之旅的第一步，通过试炼来获得他们的大地图腾，并与台地的元素直接沟通。",["race:Tauren"]="对于牛头人来说，纳拉其营地代表着童年的终结——在这里，在鹰风部族长者的注视下，你将举行第一次狩猎仪式，并与祖先之灵建立感应，这就是那片神圣的土地。"},sec={{t="鹰风部族的心脏",b="Situated at the northern edge of the elevated Red Cloud Mesa, Camp Narache is the primary settlement of the Hawkwind tribe. The village consists of several large hide lodges and pavilions, including a communal tent for wounded braves, an armory, a bakery tent, and a spirit lounge dedicated to meditation and ancestral communion. At the center of the camp, tribal elders and path trainers stand in a circle at the heart of the camp, where the venerable Greatmother Hawkwind still offers guidance, guiding newly initiated youth as they step into their roles as defenders of the Earth Mother."},{t="受威胁的试炼场",b="尽管有台地陡峭的悬崖作为天然屏障，纳拉其营地仍面临着持续的动荡。来自刺刃峡谷的钢鬃野猪人不断侵扰鹰风部族的土地，而半人马斥候也在远处徘徊。年轻的猎人、萨满祭司、德鲁伊和战士们在此证明自己的实力，通过猎杀好斗的当地野生动物、保卫村庄的水井，并在沿大路下行进入莫高雷广阔的谷地之前击退野猪人袭击者。"}},faq={{q="什么是纳拉其营地？",a="纳拉其营地是年轻牛头人的新手村，坐落在莫高雷南部的红云台地上。它是鹰风部族的核心营地，也是初出茅庐的猎人、战士、德鲁伊和萨满祭司在前往血蹄村和雷霆崖之前磨练技艺的避风港。",al={"什么是纳拉其营地","纳拉其背景故事","牛头人新手村"}},{q="谁领导着这个村庄？",a="鹰风酋长负责引导部族的勇士并协调台地的防御，部族受人尊敬的长者鹰风酋长的母亲也在此协助。部族的导师和长者们聚集在营地中心，教导年轻的冒险者们。",al={"谁领导纳拉其营地","纳拉其营地酋长","鹰风部族首领"}},{q="营地面临着什么样的威胁？",a="营地不断受到东面刺刃峡谷中钢鬃野猪人的袭扰。除了在周边台地徘徊的凶猛战猪和陆行鸟外，掠夺成性的半人马部族所带来的潜在危险也让鹰风勇士们时刻保持警惕。",al={"纳拉其营地的敌人","谁袭击纳拉其营地","台地威胁"}},{q="旅行者能轻易离开台地吗？",a="红云台地四面环绕着陡峭的悬崖。通往莫高雷大平原的唯一路径是一条向北延伸的山道，由鹰风勇士守卫，以防止敌对野兽和野猪人伏击旅行者。",al={"离开红云台地","离开纳拉其营地","下台地的路径"}}},fx={["017769ab"]={q="纳拉其营地发生了什么？",a="纳拉其营地最初是鹰风部族在红云台地高处建立的避世家园。历经数代，它从一处简单的部族聚集地发展成莫高雷各地年轻牛头人的主要试炼场。陡峭的悬崖和天然壁垒为营地提供了保护，使初出茅庐的猎人、萨满和战士能够远离下方开阔平原上猖獗的半人马袭击，完成传统仪式。",al={"纳拉其营地历史","纳拉其营地的历史","这里发生了什么"}},de5ddd4a={q="谁住在纳拉其营地？",a="纳拉其营地是鹰风部族的主要村落，由鹰风酋长和他的母亲鹰风酋长的母亲领导。部族勇士、商人和工匠与来自牛头人各个传统的导师齐聚于此。萨满、德鲁伊、战士和猎人居住在营地的兽皮棚屋中，训练前来完成成年试炼的年轻牛头人。",al={"谁住在纳拉其营地","纳拉其营地的居民","谁住在这里"}},["452dc8d4"]={q="纳拉其营地危险吗？",a="营地本身平静安宁，由鹰风部族的勇士严密守卫，但周围的台地正变得愈发危险。凶猛的山地狮和护地野猪在边境徘徊，而越来越多的刺背野猪人已侵入附近的峡谷。在棚屋周围还算安全，但缺乏经验的年轻人若远离营地的篝火，便会立即陷入险境。",al={"纳拉其营地安全吗","纳拉其营地有多危险","纳拉其营地的危险"}},["602085f2"]={q="所有牛头人都从这里开始吗？",a="是的。纳拉其营地位于红云台地受保护的高崖之上，是所有年轻牛头人的主要训练营。在你获准前往莫高雷更广阔的山谷，或是前往雷霆崖为酋长效力之前，必须先在长者的注视下证明自己的力量、智慧以及对自然的敬意。",al={"所有牛头人都从这里开始吗","牛头人起始区域","牛头人为何从这里开始"}},e8115520={q="谁建造了纳拉其营地？",a="鹰风部族在红云台地建立了这座营地，作为他们世代相传的村落。营地主要由坚固的皮革帐篷、雕刻图腾和天然木材建成，遵循传统游牧技艺建造；如今，它已成为部族聚会和教育牛头人年轻一代的长久中心。",al={"谁建造了纳拉其营地","纳拉其营地的起源","谁建立了纳拉其营地"}},["9d2ccac7"]={q="鹰风酋长对牛头人很重要吗？",a="鹰风酋长是鹰风部族的领袖，也是红云台地的主管者。他治理营地并指挥抵御刺背野猪人的防务；此外，他在文化传承中也至关重要，会引导刚刚觉醒的勇士度过早期试炼，让他们日后加入统一的部族。",al={"鹰风酋长的职责","鹰风酋长是谁","鹰风酋长的重要性"}},["5c34accd"]={q="鹰风酋长还要听命于其他人吗？",a="是的。和莫高雷所有部族酋长一样，鹰风酋长尊凯恩·血蹄为统一牛头人部族的大酋长。除了效忠凯恩，牛头人也已宣誓效忠大酋长萨尔和更广大的部落，不过营地的日常治理仍由鹰风酋长负责。",al={"鹰风酋长听命于谁","鹰风酋长的上级","谁统辖鹰风酋长"}},["4397ed07"]={q="刺背野猪人是什么？他们为什么攻击我们？",a="刺背野猪人是居住在台地峭壁和荆棘丛中的凶残野猪人部族。他们领地意识极强，又苦于资源匮乏，视牛头人聚居地为对自己觅食地的侵占。在酋长们的鼓动下，他们开始袭击牛头人的补给线，并直接威胁纳拉其营地。",al={"刺背野猪人为何发动袭击","刺背野猪人","刺背野猪人是谁"}},["35bda353"]={q="刺刃峡谷是什么地方？",a="刺刃峡谷是一处崎岖的峡谷，荆棘丛生，位于红云台地东北边缘。这里是该地区刺背野猪人的主要巢穴和据点，居住着他们的战斗野猪和酋长Sharptusk Thornmantle。",al={"刺刃峡谷","刺刃峡谷在哪里","关于刺刃峡谷"}},["7ff27be4"]={q="大地母亲是谁？",a="大地母亲是牛头人最为敬仰的仁慈造物主。牛头人的传统认为，是她诞生了世界，为大地注入生命，并创造了牛头人，让他们与荒野和谐共处。她的意志指引着牛头人的灵修、萨满仪式以及对自然的敬畏。",al={"大地母亲是谁","大地母亲传说","牛头人的大地母亲"}},d26e5d41={q="莫高雷是什么地方？",a="莫高雷是牛头人的世代家园，是一片广袤而葱郁的土地，遍布风吹草地、连绵丘陵和高耸高原。四周被难以逾越的山脉环绕，肥沃的山谷中栖息着漫游的科多兽、狼群，以及牛头人永久的首都雷霆崖。",al={"莫高雷是什么地方","关于莫高雷","莫高雷传说"}},["2ba66ce3"]={q="牛头人为什么在莫高雷定居？",a="数代以来，残暴的半人马劫掠者迫使牛头人在贫瘠之地四处漂泊，过着游牧生活。加入大酋长萨尔和新部落的阵营，将半人马赶出这一地区后，大酋长凯恩·血蹄带领族人永久定居在世代家园中葱郁且易守难攻的山谷里。",al={"牛头人为何住在莫高雷","牛头人为何来到莫高雷","在莫高雷定居"}},b543a978={q="莫高雷安全吗？",a="莫高雷天然易守，与贫瘠之地相比也较为安宁，但并非毫无危险。敌对的白鬃豺狼人、风怒 harpy、凶暴的野猪人，以及荆棘谷地精公司的投机矿工不断扰乱这里的和平，迫使牛头人时刻保持警惕。",al={"莫高雷危险吗","莫高雷有多安全","莫高雷的威胁"}},["2e7cb737"]={q="血蹄村是什么地方？",a="血蹄村是莫高雷中部石牛湖畔的一处牛头人聚居地。它是红云台地的试炼场与雷霆崖的高耸之地之间重要的贸易和文化枢纽。",al={"关于血蹄村","血蹄村在哪里","血蹄是什么"}},["8b10e970"]={q="红云台地是什么地方？",a="红云台地是莫高雷南部一处高耸而隐蔽的高原。陡峭的悬崖环绕四周，将大多数来自低地的掠食者和入侵者挡在外面。台地上坐落着纳拉其营地，也是所有年轻牛头人的隐居试炼之地。",al={"红云台地","这片台地是什么地方","关于红云台地"}},dff4694b={q="雷霆崖是什么地方？",a="雷霆崖是牛头人壮丽的首都，坐落在莫高雷北部一系列被风雕琢的高原之巅。高原之间由悬空的绳桥相连，人们可乘坐巨大的木制升降梯抵达此地。它由大酋长凯恩·血蹄建立，旨在成为所有牛头人部族团结一心的庇护所。",al={"雷霆崖是什么地方","关于雷霆崖","牛头人首都"}},["51c45aa6"]={q="牛头人何时加入部落？",a="第三次战争期间，萨尔和他的兽人登陆卡利姆多后不久，牛头人与部落结盟。萨尔认同彼此共有的精神荣誉与血脉亲缘，帮助凯恩·血蹄抵御半人马对其商队的袭击。这段深厚友谊最终促使牛头人加入了新部落。",al={"牛头人加入部落","牛头人如何加入部落","牛头人何时遇见萨尔"}},["6d7e8195"]={q="我怎么会来到纳拉其营地？",a="你来到红云台地隐秘高处的纳拉其营地，在鹰风部族中接受训练、证明自己。莫高雷的低地平原只能通过设防的隘口抵达；年轻的牛头人则聚集在这处隐蔽的避难所，在部族长老和职业训练师的注视下磨炼本领，然后踏入更广阔的世界。",al={"我是怎么来到这里的","我怎么会来到这里","我为什么在纳拉其营地"}},ccbc2a7d={q="我在纳拉其营地应该做什么？",a="你的职责是在学习自己道路上的仪式时协助鹰风酋长和营地长老。凶暴的刺背野猪人潜伏在刺刃峡谷中，山地狮则在台地上游荡，红云台地因此时常受到侵扰。你可以守卫定居点、帮助受伤的勇士，并为大地母亲举行神圣仪式，以此赢得前往血蹄村、为部落效力的资格。",al={"我在这里该做什么","我在这里的职责是什么","我为什么在这里"}},["74e7cbb8"]={q="为什么新牛头人要从纳拉其营地开始？",a="纳拉其营地是祖辈传下的试炼之地，年轻的牛头人在这里迈出成年的第一步。营地高踞红云台地，远离游荡的半人马和困扰卡利姆多中部的外来威胁，因而是一处安全的庇护所。在这里，鹰风部族的长老和训练师会指导新勇士学习狩猎、敬奉灵魂，并守卫凯恩·血蹄为族人争取的新家园。",al={"牛头人为什么从这里开始","为什么从纳拉其营地开始","为什么这里是牛头人的新手区域"}}},fp="12,358,27.590.0,29.487.0,21.318.0,22.237.0,32.285.0,36.250.0"}
P.entries["subzone:camp-taurajo"] = {n="陶拉祖营地",s="陶拉祖营地是一个宁静的牛头人定居点，坐落在南贫瘠之地，位于通往西侧莫高雷的山口边上。它是一个重要的前哨避难所，为疲惫的旅者提供旅店、补给、专业导师以及往返于平原和卡利姆多中部之间的双足飞龙交通。",h="陶拉祖营地是一个宁静的牛头人定居点，坐落在南贫瘠之地，位于通往西侧莫高雷的山口边上。它是一个重要的前哨避难所，为疲惫的旅者提供旅店、补给、专业导师以及往返于平原和卡利姆多中部之间的双足飞龙交通。",kw={"贫瘠之地","血蹄村","陶拉祖营地","莫高雷山口","南贫瘠之地","陶拉祖","牛头人前哨站"},ang={["faction:Horde"]="陶拉祖营地确保了一个关键的陆路交叉口和飞行航线，将莫高雷与部落控制下的卡利姆多中部紧密联系在一起。",["race:Tauren"]="对于第一次走出莫高雷的牛头人来说，陶拉祖营地是在严酷的贫瘠之地平原上遇到的第一个友好避难所。"},sec={{t="赤色石的前线",b="陶拉祖营地坐落在通往莫高雷山口的东口，通常是年轻牛头人离开血蹄村后，第一次窥见广阔贫瘠之地的地方。营地被干燥的灌木丛和崎岖的台地所环绕，既是一个前哨站也是一个贸易枢纽。它为猎人、制皮师和野外药草师提供庇护，同时维持着通往雷霆崖、十字路口以及深处南方的乱风岗的双足飞龙航线。"}},faq={{q="什么是陶拉祖营地？",a="陶拉祖营地是位于南贫瘠之地的一个牛头人前哨站和定居点，是莫高雷家园与贫瘠之地干旱灌木丛之间的关键中转站。",al={"陶拉祖营地概述","什么是陶拉祖","陶拉祖背景故事"}},{q="往西的路通向哪里？",a="沿着陶拉祖营地以西的泥土小径穿过山口，即可进入莫高雷，直达血蹄村和雷霆崖。",al={"陶拉祖西侧山口","陶拉祖营地以西的道路","通往莫高雷的路径"}},{q="从陶拉祖营地出发的双足飞龙飞向哪里？",a="当地的飞行管理员负责协调双足飞龙航线，将营地与北部的十字路口、西部的雷霆崖以及南部的千针石林乱风岗直接连接起来。",al={"陶拉祖飞行管理员","陶拉祖飞行航线","陶拉祖飞行连接"}}},fx={["9a32993c"]={q="陶拉祖营地危险吗？",a="营地本身由牛头人勇士守卫，是一处安全的定居点，但南贫瘠之地周边的荒野危机四伏。附近的灌木丛地带有凶悍的野猪人部族争夺，而徘徊的野兽和掠食者也让人一旦远离道路便危机重重。",al={"陶拉祖营地安全吗","陶拉祖营地附近的危险","陶拉祖周围的威胁"}}},fp="12,303,25.441.0,21.173.0,30.146.0,47.189.0"}
P.entries["subzone:camp-wurg"] = {n="瓦格营地",s="瓦格营地是坐落在荒芜之地干旱区域的一处食人魔营地。它是宣称占领了荒芜之地大部分地区的尘贝尔彻食人魔所建立的几座前哨站之一。",h="瓦格营地是坐落在荒芜之地干旱区域的一处食人魔营地。它是宣称占领了荒芜之地大部分地区的尘贝尔彻食人魔所建立的几座前哨站之一。",kw={"荒芜之地","托格鲁恩头目","博夫营地","卡格营地","柯什营地","瓦格营地","尘贝尔彻","食人魔","瓦格"},sec={{t="尘贝尔彻要塞",b="瓦格营地坐落在荒芜之地的岩架之间，是尘贝尔彻食人魔建立的四个主要营地之一，另外三个分别是卡格营地、博夫营地和柯什营地。驻扎在此的食人魔凶猛地守卫着他们崎岖的领地，在残酷的荒漠中搜寻一切可以利用的资源。虽然普通的粗鲁武士和执法者居住在瓦格营地那简陋的篝火和粗糙的兽皮帐篷旁，但他们的首领，托格鲁恩头目并没有在这里设立常驻点，而是游荡在荒芜之地的道路上，时刻监视着他所有的营地。"}},faq={{q="谁住在瓦格营地？",a="瓦格营地居住着尘贝尔彻食人魔，这是一个凶猛且领地意识极强的部落，他们在整个荒芜之地都建立了定居点。",al={"瓦格营地怪物","谁在瓦格营地","谁住在这里"}},{q="营地的首领在哪里？",a="尘贝尔彻食人魔的首领，托格鲁恩头目，并没有被困在瓦格营地。相反，他在瓦格、卡格、博夫和柯什营地之间的荒芜之地开阔小径上巡逻。",al={"瓦格营地首领","托格鲁恩头目位置","谁领导瓦格营地"}},{q="这个部落还有其他什么营地？",a="尘贝尔彻食人魔在整个荒芜之地控制着四个主要要塞：瓦格营地、卡格营地、博夫营地和柯什营地。",al={"尘贝尔彻营地","荒芜之地其他食人魔营地","荒芜之地食人魔定居点"}}},fp="9,194,24.521.0,23.132.0,32.175.0,38.119.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Canals (Stormwind City)",s="运河是穿过暴风城的一系列石砌水道，将城市的不同区域分隔开来。它们既是行人和垂钓者安静的通道，也暗藏着危险，还是暴风城监狱的入口。",h="运河是穿过暴风城的一系列石砌水道，将城市的不同区域分隔开来。它们既是行人和垂钓者安静的通道，也暗藏着危险，还是暴风城监狱的入口。",kw={"运河区","运河","鳄鱼","加利纳","下水道","监狱","暴风城","水道"},ang={["faction:Alliance"]="运河见证了首都的重建，它们从第一次战争的废墟中恢复，成为了这座功能完善、风景如画的城市的一部分。",["profession:Cooking"]="安静的运河岸边为有志向的厨师提供了便利的垂钓地点，他们无需离开首都城墙的安全范围，就能捕获新鲜的鱼类。"},sec={{t="首都的动脉",b="The Canals link and define the districts of Stormwind, dividing the bustling markets of the Trade District from the aged alleys of Old Town, the cathedral gardens, and the Dwarven District. Stone bridges, archways, and waterside walkways frame quiet establishments like the Gallina Winery, tailor shops, and quiet residential homes. In addition to serving local merchants and recreational fishermen, the waterways conceal the fortified entrance to the Stockade, where Stormwind's most dangerous criminals and rebels are held beneath street level."},{t="惨痛的历史与潜伏的阴影",b="水道平静的表面掩盖了其暴力的过去。在第一次战争中，当部落洗劫暴风城时，城市化为废墟，运河直到第二次战争后重建首都时才得以修复。如今，虽然河道已经清理和修复，但深处仍弥漫着神秘的气息，城市中关于码头下方潜伏着一只巨大白化鳄鱼的传闻更是加剧了这种神秘感。"}},faq={{q="第一次战争期间运河发生了什么？",a="当兽人部落在第一次战争中征服并洗劫暴风城时，这座城市及其水道化为废墟。在第二次战争后暴风城重建时，运河也随之修复。",al={"运河历史","第一次战争运河","暴风城洗劫运河"}},{q="暴风城的运河里真的有怪物吗？",a="没人能给出肯定的答案。流传已久的都市传说称，水道中潜伏着一只巨大的白色鳄鱼。城市卫兵和居民通常将其视为酒馆闲谈，但相关报道从未间断，冒险者们也被警告不要掉进水里。",al={"暴风城鳄鱼","运河短吻鳄","下水道野兽","白化鳄鱼"}},{q="监狱的入口在哪里？",a="监狱的入口位于环绕法师区运河的最北段，由暴风城卫兵重兵把守。",al={"监狱在哪里","监狱入口","如何进入监狱"}},{q="玩家可以通过在运河里游泳在暴风城内穿行吗？",a="在运河中游泳完全可行，但要回到街道上，需要找到沿水岸分布的石阶或码头。",al={"在运河中游泳","暴风城水路交通","暴风城水上路线"}}},fx={["8ec6c1e0"]={q="运河是什么地方？",al={"运河是什么地方","暴风城运河的背景","运河区"}},["74e84108"]={q="运河危险吗？",a="大多数时候，运河很安全，城里的居民、店主和当地钓鱼者经常在此往来。不过，在水边仍要小心脚下。当地人之间一直流传着传闻，说水面下潜伏着一头可怕的白化鳄鱼，任何不慎落水的人都会面临真正的威胁。",al={"运河里安全吗","运河的危险","运河危险吗"}}},fp="23,257,23.546.0,38.375.0,49.226.0,50.245.0,46.151.0,63.154.0"}
P.entries["subzone:canals-undercity"] = {n="Canals (Undercity)",s="幽暗城的运河是一条阴暗、环形的护城河，蜿蜒穿过幽暗城各区之间。里面流淌的不是清水，而是极其不自然、散发着恶臭的绿色粘液，它既是排污系统，也是被遗忘者这座地下要塞的冷酷象征。",h="幽暗城的运河是一条阴暗、环形的护城河，蜿蜒穿过幽暗城各区之间。里面流淌的不是清水，而是极其不自然、散发着恶臭的绿色粘液，它既是排污系统，也是被遗忘者这座地下要塞的冷酷象征。",kw={"运河","钓鱼","被遗忘者","绿色粘液","洛丹伦","淤泥","有毒","幽暗城"},ang={["class:Shaman"]="元素无法对填满幽暗城水道的污染泥浆产生太大影响，导致诸如水上行走之类的常规法术完全失效。",["race:Undead"]="对于被遗忘者而言，这些肮脏的运河对其非生命的生理结构完全无害，它们作为功能性的护城河和化学径流渠道，非常适合他们的地下国度。"},sec={{t="毒液护城河",b="运河开凿于洛丹伦废墟之下的深处，环绕着幽暗城的核心地带，用宽阔的绿色污泥水道将各个区域隔开。虽然凡人的城市会引入流动的河水来清洁街道，但被遗忘者却用工业废料、化学径流和炼金废物填满了这些石质管道。这种液体散发着微弱的病态光芒和恶臭的蒸气，使得通过水上行走等常规魔法手段穿越它变得不可能。尽管这些泥浆具有致命性，但绝望的垂钓者偶尔还是能从淤泥中打捞出奇特而扭曲的玩意儿。"}},faq={{q="运河里的绿色液体是什么？",a="这是一种炼金淤泥，由收集在幽暗城排水系统中的有毒径流、瘟疫副产品和工业废料组成。与清水不同，它明显是受到污染且有毒的。",al={"幽暗城绿水","幽暗城的粘液是什么","绿色粘液河"}},{q="能在幽暗城的运河里钓鱼吗？",a="可以，耐心的垂钓者可以将鱼线抛入这些污泥之中。除了病态、受污染的鱼类之外，人们偶尔还会捞起废弃的垃圾，包括来自洛丹伦覆灭往昔的旧人类头骨。",al={"幽暗城钓鱼","这里可以钓鱼吗","在绿色粘液中钓鱼"}},{q="为什么水上行走在运河上无效？",a="这种浓稠的化学淤泥与自然水体的性质不同。其恶臭的粘性和非自然的成分使得萨满祭司和其他施法者无法通过传统的水上行走魔法维持表面张力。",al={"幽暗城水上行走","萨满水上行走错误","为什么我不能在幽暗城水上行走"}}},fx={dc46e6d3={q="幽暗城的运河是什么地方？",a="运河是穿行于幽暗城各个区域之间的下沉式水道。它们在地下城市中绕成宽阔的环形，将一条缓慢流淌的污浊绿浆河引入深石渠中；水道既分隔了各个城区，也将这座幽暗的下层城市连为一体。",al={"幽暗城运河","运河是什么地方","幽暗城运河系统"}},c0800d9e={q="运河危险吗？",a="运河里潜伏的掠食者不会造成太大的直接威胁，但浑浊的绿色深水绝非干净之处。黏稠的污泥中可能藏着遗弃的骨头、人类头骨，以及病态变异的水生生物；不慎跌入其中，滋味定然糟透了。",al={"运河的危险","在幽暗城运河里游泳安全吗","幽暗城运河安全吗"}}},fp="18,261,12.614.0,39.201.0,37.192.0,45.217.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="荆棘谷海角",s="荆棘谷海角是荆棘谷被太阳炙烤的南端，从古拉巴什竞技场向南一直延伸到海边的悬崖。这片区域以广阔的海盗港口藏宝海湾为中心，是地精、血帆海盗、古老的丛林巨魔以及不断入侵的野生生物激烈争夺的战场。",h="荆棘谷海角是荆棘谷被太阳炙烤的南端，从古拉巴什竞技场向南一直延伸到海边的悬崖。这片区域以广阔的海盗港口藏宝海湾为中心，是地精、血帆海盗、古老的丛林巨魔以及不断入侵的野生生物激烈争夺的战场。",kw={"大财主里维加兹","blackwater raiders","血帆海盗","藏宝海湾","荆棘谷海角","古拉巴什竞技场","南海","荆棘谷"},ang={["class:Rogue"]="这里是私掠者、无赖和亡命之徒的避风港，提供了无穷无尽的机会来行窃、走私沿海违禁品，或者挑拨Blackwater Raiders与血帆海盗之间的关系。",["profession:Cooking"]="周围的南海和沿海水域拥有宝贵的渔场，藏宝海湾的鱼贩和港口厨师独家出售珍稀食谱。"},sec={{t="大陆边缘",b="在古拉巴什竞技场这座古老斗兽场的南面，茂密的丛林逐渐过渡到被称为荆棘谷海角的海岸线。这里星罗棋布地分布着朱布瓦尔废墟和阿博拉兹废墟等破败的巨魔定居点，荆棘谷海角早已脱离了古拉巴什帝国的控制。如今，这里的海滩、海湾和丛林空地上聚集着危险的掠食者、鱼人营地，以及为了贸易路线和埋藏的财宝而互相交战的敌对海盗船员，一片混乱。"},{t="藏宝海湾与海盗战争",b="荆棘谷海角的主导势力是Blackwater Raiders，由大财主里维加兹和舰队指挥官卡拉·海角在海盗城市藏宝海湾领导。这座中立港口直接开凿在南部海湾的悬崖中，通过往返棘齿城的蒸汽船连接东部王国和卡利姆多。然而，地精的控制权依然岌岌可危。血帆海盗活跃在南部浅滩和外岛，他们劫掠补给线，并公开策划推翻藏宝海湾，以夺取对南海的全面统治。"}},faq={{q="荆棘谷和荆棘谷海角有什么区别？",a="荆棘谷海角特指荆棘谷较大区域的南部，涵盖了从古拉巴什竞技场以南一直到藏宝海湾的陆地和海岸。",al={"海角与荆棘谷的区别","荆棘谷地理","海角在哪里"}},{q="谁统治着荆棘谷海角？",a="没有单一的势力控制整个海角。藏宝海湾及其周边水域由大财主里维加兹和地精支持的Blackwater Raiders统治，而血帆海盗、娜迦和残存的巨魔则控制着各处的海滩和内陆废墟。",al={"谁领导藏宝海湾","海角统治者","谁控制着海角"}},{q="部落和联盟都能使用藏宝海湾吗？",a="是的。藏宝海湾是一个由热砂港维护的开放式中立港口。只要旅行者保持武器入鞘，且在城市范围内维护和平，联盟和部落的冒险者都可以使用其码头、商人、飞行管理员和拍卖行。",al={"藏宝海湾是中立的吗","联盟与部落在藏宝海湾","部落可以进入藏宝海湾吗"}},{q="什么是古拉巴什竞技场？",a="古拉巴什竞技场是位于海角北缘的一座古代巨魔斗兽坑，战斗者们汇聚于此进行试炼。",al={"古拉巴什宝箱","竞技场规则","荆棘谷pvp竞技场"}},{q="旅行者如何往返于荆棘谷海角和卡利姆多之间？",a="一艘地精运营的蒸汽船定期往返于藏宝海湾码头和贫瘠之地的港口城市棘齿城之间，提供了横跨南海的少数几种远洋客运航线之一。",al={"前往棘齿城的船","前往卡利姆多的交通工具","藏宝海湾的船"}}},fp="21,323,21.466.0,31.516.0,80.184.0,36.256.0,42.271.0,28.132.0,51.196.0"}
P.entries["subzone:capital-gardens"] = {n="Capital Gardens",s="Capital Gardens构成了位于菲拉斯的古老精灵遗迹厄运之槌的西区。这里曾经是一座宁静优美的卡多雷贵族公园，如今却已枯萎成一片荒凉的林地，游荡着被腐蚀的古树、幽灵以及辛德拉的残部。",h="Capital Gardens构成了位于菲拉斯的古老精灵遗迹厄运之槌的西区。这里曾经是一座宁静优美的卡多雷贵族公园，如今却已枯萎成一片荒凉的林地，游荡着被腐蚀的古树、幽灵以及辛德拉的残部。",kw={"图书馆区","capital gardens","厄运之槌西区","埃雷萨拉斯","菲拉斯","伊莫塔尔","辛德拉"},ang={["class:Mage"]="尽管已经荒废，花园中依然保留着通往图书馆区的路径，那里是卡利姆多现存的、关于大分裂前魔法理论最伟大的宝库之一。",["race:NightElf"]="对于暗夜精灵来说，走在Capital Gardens那荒芜的铺路石上，是一次关于上层精灵狂妄自大以及奥术成瘾所带来的灾难性代价的惨痛警示。"},sec={{t="腐朽的圣所",b="一万年前，埃雷萨拉斯曾是卡多雷帝国最璀璨的明珠之一。Capital Gardens作为其户外区域，拥有繁茂的魔法植被和宏伟的大理石露台，是上层精灵法师们辩论和休憩的地方。大分裂之后，这片飞地陷入了绝境。由于失去了永恒之井，留守的辛德拉转而通过黑暗魔法来维持永生，任由花园枯萎。如今，灰暗扭曲的枝干和被腐蚀的树人布满了破碎的庭院，残留的魔法腐化使得这片森林永远无法真正愈合。"},{t="图书馆区与监狱",b="穿过杂草丛生的小径和充满敌意的古树，Capital Gardens通向辛德拉堡垒的深处。道路直达上层精灵法庭和图书馆区——那里保存着数个世纪以来的奥术知识和被遗忘的典籍。更深处则是伊莫塔尔的监狱，幸存的精灵在那里束缚了一只恶魔以吸取其力量，这种绝望的举动将周边的花园扭曲成了如今梦魇般的景象。"}},faq={{q="什么是Capital Gardens？",a="Capital Gardens是厄运之槌的西区，位于菲拉斯中部的埃雷萨拉斯遗迹内。它曾经是这座城市上层精灵精英们居住的原始公共公园。",al={"什么是capital gardens","厄运之槌西区花园","埃雷萨拉斯公园"}},{q="为什么这里的树木和古树会受到腐蚀？",a="永恒之井被毁后，幸存的辛德拉通过吸取被召唤的恶魔伊莫塔尔体内的邪能来维持生存。由此产生的动荡魔法泄露缓慢地扭曲了当地的植被，并使当地的古树陷入了狂暴的疯狂之中。",al={"为什么这里的古树是邪恶的","树木发生了什么","为什么这里一片荒凉"}},{q="这个区域通向哪里？",a="花园通往厄运之槌西区建筑群的更深处，连接着上层精灵法庭、学术性的图书馆区以及关押恶魔伊莫塔尔的内部圣所。",al={"capital gardens通往哪里","它通向何处"}},{q="花园里还有友好的精灵吗？",a="游荡在小径上的大多数上层精灵都是敌对的灵魂或疯狂的守卫。不过，在附近的图书馆区内，仍有一些辛德拉学者留存，他们愿意交换古老的知识或用失落的精灵法典进行交易。",al={"里面有盟友吗","谁居住在capital gardens"}}},fp="15,263,19.609.0,28.475.1,28.195.0,46.280.0,26.182.0,49.232.0"}
P.entries["subzone:cathedral-of-light"] = {n="Cathedral of Light",s="Cathedral of Light是暴风城的精神核心，也是圣光教会的主要圣所。它高耸于Cathedral Square之上，是人类牧师和白银之手骑士团的中央堡垒。",h="Cathedral of Light是暴风城的精神核心，也是圣光教会的主要圣所。它高耸于Cathedral Square之上，是人类牧师和白银之手骑士团的中央堡垒。",kw={"本尼迪塔斯","cathedral of light","cathedral square","达索瑞恩·拉尔","圣光","劳瑞娜","沙东布瑞克","白银之手","暴风城"},ang={["class:Paladin"]="Cathedral of Light是你在暴风城的主要职业大厅，像达索瑞恩·拉尔和格雷森·沙东布瑞克公爵这样的导师会引导你完成《勇气之书》和《神圣之书》的神圣试炼。",["class:Priest"]="作为圣光教会在南部王国的最高驻地，大教堂是高阶牧师劳瑞娜和大主教本尼迪塔斯培养你的精神虔诚和神圣治疗艺术的地方。"},sec={{t="信徒的圣所",b="在第一次战争中遭到破坏后，在大主教阿隆苏斯·法奥和当时还是主教的本尼迪塔斯的指导下，Cathedral of Light得以重建，成为了一座高耸的坚韧灯塔。随着第三次战争中洛丹伦陷落于天灾军团，教会的中心南移至暴风城。如今，大主教本尼迪塔斯就在这座宏伟的大厅里引导信徒，为整个联盟提供精神指引。"},{t="虔诚与武备大厅",b="除了作为祈祷和治疗的场所外，大教堂还是白银之手骑士团在南部王国残部的主要总部。格雷森·沙东布瑞克公爵和达索瑞恩·拉尔等高阶人物，通过《勇气之书》和《神圣之书》的神圣试炼来训练有前途的侍从。与他们一同，高阶牧师劳瑞娜引导虔诚的侍僧领悟圣光最深奥的教义，培养圣光勇士以抵御迪菲亚潜行者和天灾军团日益增长的威胁。"}},faq={{q="谁在大教堂内领导教会？",a="大主教本尼迪塔斯是圣光教会的领袖。在洛丹伦沦陷和大主教阿隆苏斯·法奥去世后，本尼迪塔斯便在暴风城的讲坛上承担起了重组后的教会的精神领导职责。",al={"大教堂领袖","谁是大主教","谁领导教会"}},{q="大教堂与圣骑士有何关联？",a="大教堂是白银之手骑士团在暴风王国的主要作战总部。格雷森·沙东布瑞克公爵和达索瑞恩·拉尔等著名的圣骑士在此指导新晋侍从，授予神圣典籍，并指挥十字军对抗王国的敌人。",al={"白银之手暴风城","暴风城圣骑士职业大厅","为什么圣骑士在这里"}},{q="大教堂的地板下面是什么？",a="主圣所下方是大教堂的地下墓穴，那是受人尊敬的英雄、牧师和圣骑士的安息之所。",al={"大教堂地下室","大教堂墓穴","大教堂下面有什么"}}},fx={["2c1d9b08"]={q="圣光大教堂是什么地方？",a="圣光大教堂是圣光教会和联盟宏伟的精神中心。它位于暴风城的Cathedral Square，是供人祈祷、冥想和疗愈的圣所。前途无量的牧师和白银之手骑士团的圣骑士从各地前来，在拱顶之下潜心学习；而在镶嵌钴石的石厅下方，安息着受人敬仰的逝者。",al={"圣光大教堂是什么地方","圣光大教堂的用途","暴风城大教堂"}},e612604f={q="圣光大教堂过去发生过什么？",a="第一次战争期间，旧部落严重损毁了最初的大教堂。第二次战争结束后，大主教阿隆苏斯·法奥尔与当时还是他学徒的本尼迪塔斯主持了大教堂的全面重建。第三次战争中洛丹伦陷落后，这里成为了信仰的主要圣地。",al={"圣光大教堂的历史","暴风城大教堂的历史","圣光大教堂发生过什么"}},b98edca3={q="圣光大教堂危险吗？",a="不危险。圣光大教堂是暴风城戒备森严的中心地带中的一处宁静圣所，专用于沉思、礼拜和疗愈之术。只要你不是联盟的敌人，也不是正在躲避城卫的闯入者，便能在大教堂里找到安全、导师和志同道合的圣光修习者。",al={"圣光大教堂危险吗","暴风城大教堂安全吗","圣光大教堂的危险"}}},fp="18,249,25.432.0,26.550.0,42.241.0,51.278.0,38.124.0"}
P.entries["subzone:cathedral-square"] = {n="Cathedral Square",s="Cathedral Square是暴风城的精神与市政中心，雄伟的Cathedral of Light坐落于此。除了作为礼拜和祈祷的场所，这个繁华的广场还容纳了市政厅、城市孤儿院以及银色黎明在该地区的总部等市政机构。",h="Cathedral Square是暴风城的精神与市政中心，雄伟的Cathedral of Light坐落于此。除了作为礼拜和祈祷的场所，这个繁华的广场还容纳了市政厅、城市孤儿院以及银色黎明在该地区的总部等市政机构。",kw={"银色黎明","cathedral of light","cathedral square","市政厅","圣职区","孤儿院","圣骑士","牧师","暴风城"},ang={["class:Paladin"]="对于圣骑士来说，Cathedral Square是信仰和职责的源泉，这里汇聚了导师、神圣誓言以及专为圣战勇士量身打造的特制护甲商。",["class:Priest"]="广场上宁静的大厅和高耸的尖塔为牧师提供了一个与圣光沟通、推进灵性研究以及服务暴风城市民的安宁圣所。"},sec={{t="圣职区",b="Cathedral Square位于Trade District西北方，Dwarven District东南方，是暴风城王国的信仰中心。矗立在天际线上的是Cathedral of Light，这是艾泽拉斯所有圣光信徒最重要的圣所。牧师、圣骑士和治疗者汇聚于此进行学习、祈祷和训练。市民、朝圣者以及由校长丹娜带领的当地学童经常在广场上交流和沉思。"},{t="市政中心与圣职秩序",b="该区域不仅仅用于祈祷；它也是首都最繁忙的市政中心之一。广场内设有暴风城孤儿院和市政厅，是王国行政生活的基石。专为圣战者服务的特殊护甲商和武器匠，例如Righteous Plates和Just Maces，都在街道两旁开店。它同时也是银色黎明在暴风城的行动基地，招募人员和代表在此协调救援工作，并集结勇士以应对北部王国天灾军团的威胁。"}},faq={{q="什么是Cathedral Square？",a="Cathedral Square是暴风城的一个主要区域，以Cathedral of Light为中心。它既是圣光修行者的精神枢纽，也是容纳了市政厅、当地孤儿院和各类商铺的重要市政中心。",al={"大教堂区","圣职区","这是什么地方"}},{q="谁在Cathedral Square进行训练？",a="联盟的牧师和圣骑士来到Cathedral Square和Cathedral of Light磨练技能并研习神圣教义。医疗人员和护理员也在此接受急救训练师的指导。",al={"职业训练师","谁在这里训练","圣骑士牧师训练师"}},{q="为什么银色黎明设在这里？",a="银色黎明在Cathedral Square设有一个重要的办事处，旨在招募有能力的勇士，并协调暴风城的后勤支援，以支持他们在瘟疫之地对抗天灾军团的持久圣战。",al={"暴风城银色黎明","银色黎明驻地"}},{q="Cathedral Square通向哪里？",a="桥梁和运河通道将Cathedral Square与东南方繁华的Trade District、西北方工业气息浓厚的Dwarven District以及西南方宁静的法师区花园直接相连。",al={"连接区域","这里通向哪里"}}},fx={["2ce95091"]={q="为什么叫Cathedral Square？",a="这片城区因俯瞰其间的宏伟圣光大教堂而得名。这座宏伟建筑主宰着暴风城的天际线，是艾泽拉斯最重要的圣光纪念建筑，自然也将自己的名字和神圣使命赋予了周围的街道与市政广场。",al={"cathedral square名称的含义","为什么叫cathedral square","cathedral square是怎么得名的"}},aa9b3d24={q="谁住在Cathedral Square，或负责管理这里？",a="Cathedral Square是暴风城的精神与市政核心。圣光大教堂的神职人员和圣骑士负责引领这里的宗教生活，市政领袖则在市政厅处理事务。这里还有城市孤儿院、专营武器和护甲的商人，以及银色黎明等在此积极活动的重要组织。",al={"谁管理cathedral square","谁住在cathedral square","cathedral square的居民"}},e4d635a7={q="Cathedral Square危险吗？",a="不危险。Cathedral Square是王国中最安全、守备最严密的地方之一。这里位于暴风城城墙之内，由城卫巡逻，日夜都有坚毅的圣骑士和虔诚的牧师守护，维护此地的和平。",al={"cathedral square安全吗","cathedral square的危险","cathedral square里的威胁"}}},fp="16,300,17.492.0,26.571.0,25.241.0,31.201.0,36.216.0,33.205.0"}
P.entries["subzone:cauldron"] = {n="大熔炉",s="大熔炉是一处巨大的露天挖掘场，占据了灼热峡谷的中心地带。这座火热的采石场由黑铁部族运营，受尽折磨的奴隶在残暴的监工和游荡的元素生物的监视下，日夜不停地在此劳作。",h="大熔炉是一处巨大的露天挖掘场，占据了灼热峡谷的中心地带。这座火热的采石场由黑铁部族运营，受尽折磨的奴隶在残暴的监工和游荡的元素生物的监视下，日夜不停地在此劳作。",kw={"大熔炉","黑铁矮人","挖掘","熔岩元素","采石场","灼热峡谷","奴隶工人","奴隶"},ang={["profession:Mining"]="大熔炉中巨大的机械挖掘机和露天梯田展现了黑铁部族挖掘工程的工业规模，这些工程直接开凿在不稳定的火山地壳之上。",["race:Dwarf"]="亲眼目睹黑铁矮人的堕落——在火元素之中将有知觉的俘虏当作可随意消耗、破碎不堪的劳动力来使用——让铁炉堡矮人感到深深的厌恶。"},sec={{t="熔岩采石场",b="大熔炉深深刻在灼热峡谷那焦灼的土地上，是在索瑞森大帝灾难性地召唤出拉格纳罗斯后加固而成的。巨大的黑铁挖掘机械喷吐着浓烟，环绕在峡谷四周，从阴燃的岩石中刮取矿石。在燃烧的裂隙深处，活生生的火焰与熔岩元素与黑铁工头一同徘徊，而地底的热气正不断地从山腹中涌出。"},{t="破碎的劳工",b="在矿坑深处，被俘的奴隶工人在黑铁监工的鞭笞下，忍受着残酷而无尽的轮班。在无情的劳作、闷热的高温和折磨下，许多劳工已经彻底疯狂。他们不再能分辨敌友，会猛烈攻击任何打扰他们劳作的局外人——即使对方可能是来给予他们获得自由机会的人。"}},faq={{q="大熔炉是什么？",a="大熔炉是一座巨大的露天矿场和挖掘场，位于灼热峡谷的中心。它由黑铁部族建造并加固，是用于在极其不稳定的火山环境下开采石料和矿石的工业中心。",al={"大熔炉背景故事","大熔炉是什么","灼热峡谷采石场"}},{q="谁在控制挖掘作业？",a="黑铁部族控制着整个场地。他们使用重型挖掘机和武装监工来监督作业，对矿坑及其劳工维持着残酷的统治。",al={"谁在运营大熔炉","大熔炉主人"}},{q="为什么奴隶会攻击试图提供帮助的冒险者？",a="这些奴隶已被残酷的折磨、灼人的热浪和无休止的疲惫所击垮。在主人的虐待和艰苦的生存环境下，他们早已陷入疯狂，破碎的精神使他们将任何对工作的干扰都视为威胁，从而攻击附近的任何人。",al={"为什么奴隶具有敌意","奴隶工人的攻击","可以解放奴隶吗"}},{q="矿坑里住着什么样的生物？",a="除了黑铁监工和他们的奴隶劳工外，大熔炉那充满火焰的裂隙中爬满了不稳定的火元素和熔岩元素，这些都是由峡谷的火山特性所释放出来的。",al={"大熔炉怪物","大熔炉里有什么","大熔炉中的怪物"}}},fp="8,243,17.465.0,20.403.0,21.253.0,28.169.0,53.254.0,44.188.0"}
P.entries["subzone:cavern-of-mists"] = {n="Cavern of Mists",s="Cavern of Mists是通往哀嚎洞穴深处的宽阔外室。受从岩石中喷涌而出的地下间歇泉滋养，其中心的池塘和悬浮的迷雾中栖息着奇怪、变异的野生生物，它们就在副本传送门入口外游荡。",h="Cavern of Mists是通往哀嚎洞穴深处的宽阔外室。受从岩石中喷涌而出的地下间歇泉滋养，其中心的池塘和悬浮的迷雾中栖息着奇怪、变异的野生生物，它们就在副本传送门入口外游荡。",kw={"贫瘠之地","cavern of mists","间歇泉","雷霆蜥蜴","鞭笞者特里格","哀嚎洞穴"},ang={["class:Druid"]="在浓雾中繁衍的扭曲野生生物给了塞纳里奥德鲁伊们最初的警示，让他们意识到纳拉雷克斯的翡翠梦境交流已经偏离了轨道，堕落得有多深。",["faction:Horde"]="这片迷雾坐落在贫瘠之地的中心，清除潜伏在这里的掠食性野兽，对于保障十字路口周围的贸易路线和前哨站至关重要。"},sec={{t="梦魇的门槛",b="在进入哀嚎洞穴真正的核心之前，旅行者必须先穿过Cavern of Mists。浓厚而温暖的蒸汽终年弥漫在空气中，这些蒸汽源自洞穴底部喷涌而出并汇入中央深池的天然间歇泉。尽管这里只是一个入口，但远非宁静之地。成群的迅猛龙、毒蛇、软泥怪和半水生的雷霆蜥蜴在岩架和水域中徘徊，还有像九头蛇“鞭笞者特里格”这样的臭名昭著的野兽。它为冒险者们提供了一个不祥的预兆，预示着深处滋生的不自然生长物。"}},faq={{q="Cavern of Mists在哪里？",a="Cavern of Mists构成了哀嚎洞穴的外部洞穴系统，位于贫瘠之地十字路口的西南方。它是玩家在到达副本传送门前必须穿过的非副本区域。",al={"cavern of mists位置","cavern of mists在哪里","哀嚎洞穴入口洞穴"}},{q="为什么叫它Cavern of Mists？",a="活跃的间歇泉不断从石质地面喷涌而出，汇入中央池塘，并使地下空气中充满了沉重、潮湿的迷雾。",al={"为什么有雾","cavern of mists名称由来"}},{q="这里生活着哪些生物？",a="这个洞室里生活着迅猛龙、软泥怪、风蛇、毒蛇、蟾蜍和栖息在池塘里的雷霆蜥蜴，偶尔还能见到稀有的九头蛇鞭笞者特里格。",al={"cavern of mists里的怪物","cavern of mists怪物"}},{q="鞭笞者特里格是谁？",a="鞭笞者特里格是一只危险的稀有九头蛇，偶尔会发现它与洞室中央水池里的雷霆蜥蜴一起游动。",al={"特里格","哀嚎洞穴稀有九头蛇"}}},fx={["923aae57"]={q="Cavern of Mists是什么地方？",a="Cavern of Mists也被称为哀嚎洞穴，是哀嚎洞穴深处之前的一处外围地下洞室。活跃的间歇泉从石质地面喷涌而出，洞穴中央有一片苍翠的水池，温暖的水流与蒸汽交融，让封闭的地下空间常年笼罩在浓重雾气中。",al={"cavern of mists是什么地方","cavern of mists的背景","关于cavern of mists"}},["8ec0c6f8"]={q="Cavern of Mists危险吗？",a="危险，粗心的旅人会在这处洞室遭遇险境。凶猛的迅猛龙、蠕动的软泥怪、毒蛇和会咬人的风蛇都在雾蒙蒙的岸边和浑浊的水中游荡。中央深池中栖息着掠食性的棘齿龙，此外还有名为“鞭笞者特里高尔”的隐秘多头蛇等可怕威胁。",al={"cavern of mists危险吗","cavern of mists的危险","cavern of mists里的威胁"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="时光之穴",s="时光之穴坐落在塔纳利斯东部的悬崖峭壁中，是诺兹多姆和青铜龙军团的神秘巢穴。在蜿蜒曲折的深处，巨龙们监视并守护着艾泽拉斯脆弱的时间线，防止任何凡人的闯入或对时间的篡改。",h="时光之穴坐落在塔纳利斯东部的悬崖峭壁中，是诺兹多姆和青铜龙军团的神秘巢穴。在蜿蜒曲折的深处，巨龙们监视并守护着艾泽拉斯脆弱的时间线，防止任何凡人的闯入或对时间的篡改。",kw={"阿纳克洛斯","青铜龙军团","时光之穴","诺兹多姆","塔纳利斯","时间的","时间线"},ang={["class:Mage"]="洞穴中充斥的时间魔法远超凡人的时空奥术，让人在这些超越奥术操纵的强大力量面前感到谦卑。",["race:NightElf"]="卡多雷对巨龙军团守护者们的古老契约记忆犹新，他们认为诺兹多姆的职责对于世界的生存至关重要。"},sec={{t="蜿蜒的时间线",b="时光之穴深凿于荒漠悬崖之下，是历史洪流汇聚的枢纽。在世界诞生之初，泰坦赋予了永恒者诺兹多姆和他的青铜龙军团神圣的职责，让他们成为这些走廊的永恒守卫。在内部，时间流向变幻莫测；过去与未来的碎片在隐秘的裂隙中穿梭，从遥远时代被取回的遗物散落在沙地上。虽然巨龙阿纳克洛斯在入口附近守望，但较小的青铜幼龙也在蜿蜒的通道中巡逻，凶猛地保护着唯一的一条真实时间线。"},{t="时代的宝库",b="这里不仅是过去与未来的交汇点，也是一座奇特的宝库。千百年来，青铜龙军团从艾泽拉斯的各个角落收集了历史碎片：古老的矮人建筑、来自洛丹伦的岗哨塔、兽人氏族的酋长营房，以及可追溯到斯托姆加德第一位国王时期的盔甲。然而，尽管偶尔有旅行者敢于溜过守卫一睹这些奇观，但内部的门户依然紧闭，等待着龙军团认为凡人干预成为必要的那一天。"}},faq={{q="我现在能进入时光之穴吗？",a="不能。通往洞穴的道路依然封锁，青铜龙军团不接待任何凡人。你必须小心在入口处巡逻的幼龙；虽然年长的青铜龙阿纳克洛斯对旅行者不屑一顾，但他的同伴会攻击任何靠得太近的凡人。",al={"可以进入时光之穴吗","如何进入时光之穴","时光之穴开放吗"}},{q="谁统治着时光之穴？",a="洞穴属于永恒者诺兹多姆，他是泰坦赋予力量用以监管时间的巨龙军团守护者。日常的监管和入口守卫工作通常由他的主要后裔阿纳克洛斯，以及青铜龙军团的卫士们共同承担。",al={"时光之穴由谁领导","时光之穴首领","谁住在时光之穴"}},{q="为什么里面会有随意的建筑物和手工艺品？",a="诺兹多姆花费了数个时代来编目和收集艾泽拉斯历史上的实物遗迹。洞穴中散落着错位的宝藏，包括一座完整的洛丹伦岗哨塔、矮人建筑、兽人结构，以及来自早已被遗忘的凡人王国的武器。",al={"为什么时光之穴里有人类塔楼","时光之穴的文物"}},{q="青铜龙军团在此处的目的是什么？",a="泰坦赋予他们神圣的职责，即守护时间的流动并维护历史的完整性。他们确保凡人的篡改或外界的破坏不会扰乱那些定义世界的事件。",al={"青铜龙在这里做什么","青铜龙军团的目的"}}},fp="15,275,20.575.0,15.538.0,46.289.0,35.254.0,52.279.0,52.219.0"}
P.entries["subzone:cenarion-enclave"] = {n="塞纳里奥区",s="塞纳里奥区是达纳苏斯西北部郁郁葱葱的区域，它是塞纳里奥议会在首都的核心聚会地和权力中心。在大德鲁伊玛法里奥·怒风沉睡于翡翠梦境期间，大德鲁伊范达尔·鹿盔便在这片树林的巨大树洞和生机勃勃的枝干间领导着暗夜精灵德鲁伊们。",h="塞纳里奥区是达纳苏斯西北部郁郁葱葱的区域，它是塞纳里奥议会在首都的核心聚会地和权力中心。在大德鲁伊玛法里奥·怒风沉睡于翡翠梦境期间，大德鲁伊范达尔·鹿盔便在这片树林的巨大树洞和生机勃勃的枝干间领导着暗夜精灵德鲁伊们。",kw={"塞纳里奥议会","塞纳里奥区","达纳苏斯","德鲁伊","范达尔·鹿盔","夜刃豹","泰达希尔"},ang={["class:Druid"]="对于暗夜精灵德鲁伊来说，塞纳里奥区是你们在泰达希尔的组织民事中心，在大德鲁伊范达尔·鹿盔的严厉指导下提供训练和指引。",["class:Hunter"]="猎人们聚集在该区域东侧的枝干上，与饲养首都夜刃豹的兽王们一起磨练他们的射击技巧和荒野知识。"},sec={{t="议会之心",b="塞纳里奥区位于神殿花园上方的一处高台上，由刻有符文树皮的古老橡树和白蜡树塑造而成。塞纳里奥议会的成员们聚集在直接由活木和岩石塑造的建筑中。由于玛法里奥·怒风身陷翡翠梦境，大德鲁伊范达尔·鹿盔在此主持大局，他不顾与高阶女祭司泰兰德·语风之间挥之不去的政治摩擦，竭力推行他那关于泰达希尔的雄心壮志。除了在溪流间冥想的德鲁伊外，该区域也是首都精灵猎人的聚集地，这里的马厩里，技艺精湛的骑手们会学习如何驯服达纳苏斯夜刃豹。"},{t="枝叶间的阴影",b="虽然这里以宁静的自然保护区而闻名，但该区域也隐藏着一些秘密活动。在最西侧枝干的中空根部下方，坐落着达纳苏斯潜行者们的地下避难所，他们在上方沙沙作响的树冠掩护下，悄无声息地进行着自己的勾当。"}},faq={{q="谁在领导塞纳里奥区？",a="大德鲁伊范达尔·鹿盔目前领导着这片树林以及居住在达纳苏斯的暗夜精灵德鲁伊。塞纳里奥议会的最高领导者玛法里奥·怒风依然被困在翡翠梦境中，陷入了一种无法解释的深沉睡眠，这使得鹿盔成为了实际的权威。",al={"这里的主事人是谁","塞纳里奥区领导者","范达尔·鹿盔"}},{q="什么职业在这里训练？",a="该区域是首都德鲁伊训练师的主要驻地，他们在活树间指导新手。东侧的枝干是城内猎人训练师的所在地，而西侧枝干下方的根部区域则隐藏着一处安静的潜行者训练师巢穴。",al={"塞纳里奥区的训练师","达纳苏斯德鲁伊训练师","达纳苏斯猎人训练师"}},{q="我在哪里可以购买夜刃豹坐骑？",a="照看达纳苏斯珍贵豹类坐骑的骑术训练师和饲养员驻扎在树林入口附近的东侧树木底部，他们为符合条件的联盟旅行者提供骑术训练和夜刃豹坐骑。",al={"夜刃豹训练师","暗夜精灵坐骑训练师","达纳苏斯骑术训练师"}},{q="塞纳里奥议会对联盟的立场是什么？",a="虽然该区域位于联盟首都境内，并由坚定主张民族主义的范达尔·鹿盔领导，但作为一个更广泛的组织，塞纳里奥议会始终致力于维护自然秩序，而非参与派系战争。然而，由于鹿盔的存在，这个特定的区域在立场上强烈倾向于暗夜精灵的区域利益。",al={"塞纳里奥议会是联盟吗","德鲁伊是联盟专属吗"}}},fx={cda262fb={q="塞纳里奥区是什么地方？",a="塞纳里奥区是一片葱郁的林地，也是达纳苏斯西北部树枝间的一片城区。这里古老的橡树与白蜡树上刻有神秘符文，是这座城市德鲁伊生活与思想的中心。月神殿引领着神职人员，塞纳里奥区则汇聚学者、疗愈者和自然守护者，在此商议、传授知识并磨炼他们的精神技艺。",al={"达纳苏斯塞纳里奥区","塞纳里奥区是什么地方","关于塞纳里奥区"}},fed5260a={q="塞纳里奥区发生过什么？",a="塞纳里奥区与达纳苏斯一同发展起来，成为首都德鲁伊的聚集地。这里的圣所由活木与雕琢过的石材构成。大德鲁伊范达尔·鹿盔居住在其中最大的一座建筑里，在玛法里奥·怒风仍身处翡翠梦境、未归之时领导着德鲁伊。",al={"塞纳里奥区历史","塞纳里奥区的历史","这里发生过什么"}},["1a9fb52b"]={q="塞纳里奥区危险吗？",a="不危险。塞纳里奥区是达纳苏斯最宁静、守卫最森严的区域之一，里面有经验丰富的德鲁伊、技艺高超的猎手和警惕的树妖守卫。只要你不怀有敌视暗夜精灵与联盟的心思，这里便是适合冥想与研习的宁静圣所。",al={"塞纳里奥区安全吗","塞纳里奥区的危险","塞纳里奥区敌对吗"}},["88e7d09b"]={q="为什么叫塞纳里奥区？",a="它的名字源自塞纳里奥议会。这个德鲁伊教团致力于守护自然，并敬奉半神、所有德鲁伊的守护者塞纳留斯。作为塞纳里奥议会在暗夜精灵首都的主要驻地，这里是一处专为古老技艺与亲近自然而设的区域。",al={"为什么叫塞纳里奥区","塞纳里奥区名称由来","谁命名了塞纳里奥区"}}},fp="16,358,19.640.0,21.285.0,31.283.0,24.246.0,35.227.0,57.362.0"}
P.entries["subzone:cenarion-hold"] = {n="塞纳里奥要塞",s="塞纳里奥要塞是塞纳里奥议会在希利苏斯严酷沙漠中建立的坚固据点。为了监视埋藏在沙土之下的古老威胁，它被建立起来，成为了卡利姆多最大的德鲁伊定居点之一，也是这片荒凉之地中罕见的安全避难所。",h="塞纳里奥要塞是塞纳里奥议会在希利苏斯严酷沙漠中建立的坚固据点。为了监视埋藏在沙土之下的古老威胁，它被建立起来，成为了卡利姆多最大的德鲁伊定居点之一，也是这片荒凉之地中罕见的安全避难所。",kw={"塞纳里奥议会","塞纳里奥要塞","德鲁伊","卡利姆多","流沙之战","异种虫","希利苏斯"},ang={["class:Druid"]="作为月光林地之外最大的德鲁伊飞地之一，塞纳里奥要塞体现了塞纳里奥议会维护自然平衡、抵御宇宙恐怖的誓言。",["race:NightElf"]="对于暗夜精灵来说，这座堡垒纪念着数千年前那场灾难性的流沙之战中做出的古老牺牲。"},sec={{t="沙丘中的堡垒",b="坐落在希利苏斯荒凉的沙地之中，塞纳里奥要塞作为塞纳里奥议会的南部指挥中心而存在。穿过安戈洛环形山蜿蜒的小径即可到达此地。这座堡垒是在流沙之战的历史性事件结束后，为了监控被封印在沙漠地下的沉睡威胁而建立的。在布满虫群异种虫和沙暴的荒凉广袤之地，这座要塞为监视那些被囚禁的过往恐怖的暗夜精灵和牛头人德鲁伊提供了至关重要的庇护、贸易和后勤支持。"},{t="中立领地",b="因为守护世界免受古老邪恶侵害的职责高于凡人的纷争，塞纳里奥要塞在严格的塞纳里奥议会中立原则下运作。联盟和部落的旅行者都可以进入其城墙之内，受到当地补给线依然岌岌可危的军需官和守望者的欢迎。通过连接菲拉斯、塔纳利斯和安戈洛环形山前哨站的飞行路线，该要塞成为了那些敢于调查沙漠中日益动荡局势的凡人冒险者的唯一集结地。"}},faq={{q="谁控制着塞纳里奥要塞？",a="这座要塞完全由玛法里奥·怒风创立的德鲁伊组织——塞纳里奥议会管理和驻守。它保持完全中立，欢迎联盟和部落的成员。",al={"谁在管理塞纳里奥要塞","塞纳里奥要塞阵营","塞纳里奥要塞中立吗"}},{q="为什么这座堡垒要建在沙漠里？",a="它是在流沙之战后建立的，旨在监视封印在希利苏斯深处的古老邪恶，并压制该地区泛滥的异种虫群的复苏。",al={"为什么塞纳里奥要塞在希利苏斯","塞纳里奥要塞的目的","德鲁伊为何在此建立基地"}},{q="如何前往塞纳里奥要塞？",a="步行者通常会走那条从安戈洛环形山向西北方向蜿蜒而上的陡峭山路。飞行网络也将要塞与加基森、安戈洛和菲拉斯的飞行管理员连接起来。",al={"如何前往塞纳里奥要塞","塞纳里奥要塞路径","进入希利苏斯"}},{q="两个阵营的成员都能在这里使用服务吗？",a="是的。塞纳里奥要塞内的商人和飞行管理员与任何愿意勇敢面对沙漠的冒险者进行自由贸易，无论其政治立场如何。",al={"部落在这里安全吗","联盟可以在这里休息吗","塞纳里奥要塞商人"}}},fp="13,294,22.529.0,14.518.0,27.212.0,50.202.0,35.190.0,47.158.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Chamber of Atonement",s="Chamber of Atonement是血色修道院内墓地区域阴森的入口大厅。在这里，在悬挂着铁链的石拱顶下，血色十字军会对被俘的亡灵和其他被视为异教徒的对象进行残酷的审讯和拷打，随后将他们的残骸扔进外面的回廊中。",h="Chamber of Atonement是血色修道院内墓地区域阴森的入口大厅。在这里，在悬挂着铁链的石拱顶下，血色十字军会对被俘的亡灵和其他被视为异教徒的对象进行残酷的审讯和拷打，随后将他们的残骸扔进外面的回廊中。",kw={"chamber of atonement","forlorn cloister","墓地","审讯员韦沙斯","血色修道院","拷打","vorrel sengutz"},ang={["class:Priest"]="对神圣誓言的亵渎在这里体现得淋漓尽致，十字军的审讯官们将神圣的纪律扭曲成了肉体的屠杀和残忍的折磨。",["race:Undead"]="Chamber of Atonement代表了血色十字军对你的人民最残酷的一面，这里是像Vorrel Sengutz这样的被遗忘者俘虏仅仅因为他们的存在而受到系统性拷打的地方。"},sec={{t="苦痛大厅",b="作为通往Forlorn Cloister的入口，Chamber of Atonement绝非一处安静祈祷的圣地。相反，血色十字军将这座宏伟的门厅改造成了一座刑讯室，里面布满了拷问架、镣铐和燃烧的火盆。狂热的审讯官利用这些刑具来逼供并折磨俘虏，他们认为极度的痛苦是这些邪恶生物唯一应得的赎罪方式。大厅内回荡着受难者的哀嚎，残酷的监工们在这里监督着一切，确保那些进入此地的人极少能完整地走出去。"},{t="审讯官的领域",b="这座大厅由审讯员韦沙斯掌管，他是十字军中最残忍的胁迫手段实施者之一。韦沙斯以击垮任何胆敢踏入修道院边界的人的意志为荣，其行径令人发指。他最“珍视”的受害者之一是被遗忘者俘虏Vorrel Sengutz，他在韦沙斯手中忍受了数周无尽的折磨。这些墙壁内上演的残酷行径向外界证明，血色十字军所谓的纯净圣战已经扭曲成了肆意的虐待狂行径。"}},faq={{q="Chamber of Atonement有何用途？",a="它是血色十字军在修道院墓地区域内设置的审讯和拷打侧厅。俘虏，主要是被遗忘者和其他被视为敌人的对象，会被带到这里，在被扔进墓地之前，他们会受到残酷刑具的审讯、摧残和折磨。",al={"大厅用途","为什么这里有刑具","chamber of atonement发生了什么"}},{q="谁控制着这个大厅？",a="这个房间由血色十字军的审讯员韦沙斯指挥，他是一名残忍的拷问者，以从受害者的痛苦中获得快感而臭名昭著。",al={"谁是这里的首领","chamber of atonement领袖","谁负责刑讯室"}},{q="这个房间通往哪里？",a="这是墓地区域的最外层大厅，直接通往Forlorn Cloister，那里是阵亡十字军战士和不安的亡灵安息的露天墓地。",al={"大厅出口","chamber of atonement通往何处","atonement之后的区域"}},{q="谁被关押在这里？",a="一名名为Vorrel Sengutz的被遗忘者俘虏已被关押在室内，并受到审讯员韦沙斯长达数周的拷打。",al={"谁是这里的囚犯","vorrel sengutz","被拷打的囚犯"}}},fx={["5cd82fbf"]={q="什么是Chamber of Atonement？",a="Chamber of Atonement是血色修道院墓地区的最外侧大厅。它正对着Forlorn Cloister和露天墓地，是一处阴森的门槛，血色十字军会把俘虏拖到这里，施以残酷审讯。",al={"什么是chamber of atonement","chamber of atonement介绍","关于chamber of atonement"}},f468ffff={q="Chamber of Atonement危险吗？",a="这里极其危险。审讯员韦沙斯率领一群狂热的血色十字军施刑者驻守此处，周围满是骇人的刑具。任何闯入者，或被视为亡灵同情者的人，都会立刻遭到攻击，并承受与囚犯同样无情的折磨。",al={"chamber of atonement危险吗","chamber of atonement的威胁","chamber of atonement有多危险"}},["1937bc67"]={q="为什么叫Chamber of Atonement？",a="血色十字军以此命名，是因为他们扭曲地认为，任何被亡灵之力污染或反对他们圣战的生灵，都必须忏悔并以痛苦偿还罪孽。在审判官看来，刀下的苦难与折磨才是赎罪的唯一正途。",al={"为什么叫chamber of atonement","chamber of atonement名称含义","为什么叫赎罪厅"}}},fp="20,317,15.566.0,25.480.0,42.292.0,26.157.0,26.171.0,31.128.0"}
P.entries["subzone:champions-hall"] = {n="勇士大厅",s="勇士大厅坐落在Old Town的南端，是暴风城中为联盟的荣誉老兵提供的军官军营和物资仓库。在其入口之后，军需官会为该阵营久经考验的战士分发特制的武器、板甲和徽章。只有在战场上展现出勇气的军官才能进入此地，入口处守卫森严。",h="勇士大厅坐落在Old Town的南端，是暴风城中为联盟的荣誉老兵提供的军官军营和物资仓库。在其入口之后，军需官会为该阵营久经考验的战士分发特制的武器、板甲和徽章。只有在战场上展现出勇气的军官才能进入此地，入口处守卫森严。",kw={"勇士大厅","大元帅","骑士","军官军营","old town","pvp商人","军需官","暴风城"},ang={["class:Warrior"]="对于前线作战人员来说，这座大厅代表了最终的军事储备库，提供仅供久经考验的战场领袖使用的重型作战装备和军械。",["faction:Alliance"]="这座大厅是联盟在暴风城军事功绩的最高象征，旨在向那些致力于抵御部落入侵的人们致敬。"},sec={{t="联盟军官军营",b="勇士大厅隐藏在Old Town一处守卫森严的入口之后，是联盟最杰出的战士们的禁地。军事指挥官们聚集在这里，在艾泽拉斯的战略地图上商讨正在进行的战役，四周陈列着军械和代表军衔的宏伟徽记。只有在联盟等级制度中达到军官级别——具体来说是骑士或更高军衔——的士兵才被允许进入。在内部，军事军需官为久经沙场的士兵提供精英武器、护甲和坐骑，这些装备专为在世界各地的争夺区域扭转与部落的战局而打造。"}},faq={{q="勇士大厅在哪里？",a="勇士大厅位于暴风城Old Town的南部，隐藏在一处有守卫的入口后方。",al={"勇士大厅在哪里","暴风城pvp商人位置","如何找到勇士大厅"}},{q="谁被允许进入勇士大厅？",a="只有在战场上赢得了骑士或更高军事军衔的联盟老兵才能获得通过入口的许可。未经考验的新兵和平民会被阻挡在门外。",al={"谁能进入","勇士大厅进入要求","为什么我不能进入勇士大厅"}},{q="勇士大厅里有什么？",a="大厅内有提供军官级武器、护甲、徽章和特制战争坐骑的军需官。联盟的战术家和将军们也会聚集在摆放着艾泽拉斯区域地图的战术桌旁。",al={"勇士大厅里有什么","勇士大厅有哪些商人","勇士大厅奖励"}},{q="这个建筑的部落对应物是什么？",a="部落的对应建筑是位于奥格瑞玛的传说大厅，它为部落的荣誉战士提供相同的军事物资服务。",al={"部落的勇士大厅","奥格瑞玛pvp房间","部落pvp军营"}}},fx={["5bb2303a"]={q="什么是勇士大厅？",a="勇士大厅是联盟在暴风城的军官兵营。它隐匿于Old Town，是一处专属场所，联盟中功勋卓著的军官与久经考验的战士会在此集会、商议战争策略，并配备专用武器和护甲。",al={"什么是勇士大厅","暴风城勇士大厅","这是什么地方"}},["68396c8b"]={q="为什么叫勇士大厅？",a="它的名字源自那些经过考验、赢得踏入大厅资格的联盟勇士。只有在战场上建立功勋、达到骑士或更高军官军衔的人，才被视为真正有资格进入此处的勇士。",al={"为什么叫勇士大厅","勇士大厅名称含义","勇士是谁"}},b22714b1={q="勇士大厅危险吗？",a="对联盟士兵来说并不危险。兵营位于暴风城Old Town深处，入口由附魔传送门隔开，并由联盟军官和军需官严密守卫。不过，若有部落潜入者鲁莽地闯入暴风城，就会发现这里驻扎着联盟最强悍的老兵之一。",al={"勇士大厅危险吗","勇士大厅安全吗","勇士大厅的威胁"}}},fp="15,396,31.625.0,37.124.0,42.209.0,35.212.0,46.154.0"}
P.entries["subzone:charred-vale"] = {n="焦炭谷",s="焦炭谷是位于石爪山脉西南部的一处闷烧山谷，被荆棘谷地精鲁莽的滥砍滥伐和重型机械摧毁。这里曾经是树人和奇美拉的繁荣栖息地，如今却被火焰、游荡的元素生物和充满敌意的鹰身人所吞噬。",h="焦炭谷是位于石爪山脉西南部的一处闷烧山谷，被荆棘谷地精鲁莽的滥砍滥伐和重型机械摧毁。这里曾经是树人和奇美拉的繁荣栖息地，如今却被火焰、游荡的元素生物和充满敌意的鹰身人所吞噬。",kw={"焦黑的远古树人","血怒","焦炭谷","奇美拉","火元素","石爪","烈日石居","荆棘谷地精"},ang={["class:Druid"]="这里的破坏是一个严酷的警告，昭示着当自然平衡被无节制的贪婪打破时会发生什么，这也使该山谷成为了复垦工作的重点。",["faction:Horde"]="部落军队以烈日石居为基地，与塞纳里奥盟友密切合作，以遏制 Elemental Unrest，并击退荆棘谷地精留下的腐化后患。"},sec={{t="焦黑的林地",b="不久之前，这个西南部的盆地还是一片繁茂的高山森林，由雄伟的树人守护，并栖息着当地的奇美拉和鹰身人。它的毁灭始于荆棘谷地精的到来。这群贪婪的地精利用爆炸性机械砍伐森林，腐化了守护者，并唤醒了混乱的火元素。尽管树人们最终迫使地精撤退，但这片土地已经破碎不堪，布满了火烧的痕迹，并被撤退的伐木工留下的各种污秽装置所污染。"},{t="重生的挣扎",b="如今，焦黑的远古树人在烟雾和灰烬中盲目地游荡，与愤怒的元素生物并肩而行。血怒鹰身人在枯树残枝上筑巢，捍卫着它们残存的领地。尽管山谷充满了敌意，但来自烈日石居的德鲁伊拒绝放弃这片区域，他们派遣旅行者播下附魔种子并照料那些被腐化的远古树人，坚持不懈地试图收复这片焦土。"}},faq={{q="为什么焦炭谷会燃起大火？",a="这场灾难是由荆棘谷地精残酷的伐木作业造成的。他们破坏性的机械和激进的砍伐行为激怒了这片土地的原始灵魂，并释放出了席卷整个山谷的毁灭性火元素。",al={"为什么在燃烧","是谁烧毁了焦炭谷","焦炭谷发生了什么"}},{q="焦炭谷的森林还能恢复吗？",a="附近烈日石居的牛头人德鲁伊相信可以。他们委托旅行者安抚狂暴的树人，并在灰烬中播下附魔的大地种子，希望能从废墟般的土壤中催生出绿色的嫩芽。",al={"焦炭谷正在恢复吗","焦炭谷的德鲁伊"}},{q="焦炭谷栖息着哪些生物？",a="这个盆地里到处都是充满敌意的火元素之灵、焦黑且复仇心切的远古树人、焦灼的蛇怪和野生的奇美拉。此外，这里还深受血怒鹰身人的困扰。",al={"焦炭谷的怪物","焦炭谷有什么生物"}},{q="在被烧毁之前，焦炭谷叫什么名字？",a="它最初的名字已经随着时间流逝而遗失了，但在地精的斧头抵达之前，它曾以茂密的森林保护区而闻名。",al={"焦炭谷的旧称","焦炭谷的最初名字"}}},fx={e38ca889={q="什么是焦炭谷？",a="焦炭谷是石爪山脉西南部一处广阔、烟雾弥漫的山谷。这里曾是郁郁葱葱的森林，由古老的树妖守护；在遭受毁灭性的工业开采后，如今只剩灰烬、熔岩裂隙和燃烧的树桩。",al={"什么是焦炭谷","焦炭谷概况","关于焦炭谷"}},["97858e06"]={q="焦炭谷发生过什么？",a="荆棘谷地精席卷山谷，砍伐森林并焚烧土地。古老的树木守护者奋起保卫森林、驱逐伐木者时，冲突激怒了当地的自然之灵，震裂大地，并释放出狂暴不定的火元素。地精撤退时，他们的剧毒武器污染了幸存的古树，使其化为焦黑而疯狂的躯壳。",al={"焦炭谷历史","焦炭谷发生了什么","焦炭谷是如何被毁的"}},["543e0702"]={q="焦炭谷危险吗？",a="这里是石爪山脉最具敌意的地方之一。除了灼热的地面和令人窒息的浓烟，你还会遭遇火元素、凶暴的血怒鹰身人、好斗的奇美拉、焦灼的石化蜥蜴，以及疯狂的焦黑古树。",al={"焦炭谷危险吗","焦炭谷的威胁","焦炭谷的危险"}}},fp="12,275,19.499.0,20.411.0,32.249.0,48.216.0,40.172.0,50.122.0"}
P.entries["subzone:chill-breeze-valley"] = {n="寒风峡谷",s="寒风峡谷是位于丹莫罗西部的一处崎岖雪径，连接着矮人定居点卡拉诺斯和饱受战火蹂躏的诺莫瑞根城。虽然其主干道是年轻旅行者和难民常走的路，但其偏僻的角落里却潜藏着危险的野兽和血腥的巢穴。",h="寒风峡谷是位于丹莫罗西部的一处崎岖雪径，连接着矮人定居点卡拉诺斯和饱受战火蹂躏的诺莫瑞根城。虽然其主干道是年轻旅行者和难民常走的路，但其偏僻的角落里却潜藏着危险的野兽和血腥的巢穴。",kw={"洞穴","寒风峡谷","丹莫罗","诺莫瑞根","卡拉诺斯","t字形","雪怪"},ang={["race:Dwarf"]="登山者和年轻的矮人猎人会通过清理那些威胁到连接丹莫罗中部与西部高地重要通道的凶猛雪怪来磨练自己的意志。",["race:Gnome"]="对于从诺莫瑞根的浩劫中逃亡，寻求卡拉诺斯和铁炉堡庇护的侏儒难民来说，穿越寒风峡谷那布满掠食者的外围区域是生存下去的关键第一步。"},sec={{t="冰雪与利爪的交汇处",b="寒风峡谷在丹莫罗西部的群山中形成了一道T字形的沟壑。其东西走向的主路常有往返于卡拉诺斯和诺莫瑞根郊区的矮人与侏儒新手在此穿行。然而，误入峡谷南北两侧的分支则是另一回事了。这些阴暗的区域布满了血迹和残缺的尸骸，栖息着凶猛的掠食者——尤其是那些盘踞在深层冰洞中，以任何胆敢踏入其猎场者为食的野蛮雪怪。"}},faq={{q="寒风峡谷位于哪里？",a="寒风峡谷位于丹莫罗西部，坐落在东侧繁忙的矮人枢纽卡拉诺斯和西侧侏儒科技之城诺莫瑞根之间。",al={"寒风峡谷位置","寒风峡谷在哪里","寒风峡谷地图"}},{q="为什么穿过峡谷如此危险？",a="虽然卡拉诺斯和诺莫瑞根之间的主路相对安全且常有人迹，但峡谷北侧和南侧的岔路却是掠食野兽的猎场。那里的积雪被鲜血和撕碎的尸块染红，通往凶残且领地意识极强的雪怪所居住的洞穴。",al={"寒风峡谷怪物","寒风峡谷的危险","为什么这里有骨头"}},{q="这里有哪些野兽筑巢？",a="峡谷的深处是凶猛雪怪的家园，其中甚至还有一只体型庞大、力量惊人的雪怪将其中一个洞穴占为己有。",al={"寒风峡谷的雪怪","寒风峡谷里有什么生物"}}},fx={["746bfe00"]={q="什么是寒风峡谷？",a="寒风峡谷是丹莫罗西部一处崎岖的T形隘口，向西连接诺莫瑞根的废墟，向东通往卡拉诺斯。中央道路是矮人和侏儒难民往来的重要通道，而更深处仍是险恶的雪地荒野。",al={"寒风峡谷","这是什么山谷","关于寒风峡谷"}}},fp="19,303,30.543.0,37.192.0,49.302.0,42.164.0"}
P.entries["subzone:chillwind-camp"] = {n="寒风营地",s="寒风营地坐落于从奥特兰克山脉通往西瘟疫之地的南部山口。该营地由联盟分遣队与银色黎明共同驻守，是通往洛丹伦废墟前的最后一个安全补给点。坐镇于这一险要的前哨站，指挥官们在此策划对附近天灾军团据点和瘟疫锅炉的打击行动。",h="寒风营地坐落于从奥特兰克山脉通往西瘟疫之地的南部山口。该营地由联盟分遣队与银色黎明共同驻守，是通往洛丹伦废墟前的最后一个安全补给点。坐镇于这一险要的前哨站，指挥官们在此策划对附近天灾军团据点和瘟疫锅炉的打击行动。",kw={"奥特兰克山脉","andorhal","银色黎明","阿什拉姆·瓦洛菲斯特","瘟疫锅炉","寒风营地","冰风岗","西瘟疫之地"},ang={["class:Paladin"]="有前途的圣骑士会被暴风城的格雷森·沙东布瑞克公爵指引至此，以协助瓦洛菲斯特指挥官，并将白银之手的神圣愤怒带给亡灵部队。",["faction:Alliance"]="寒风营地是联盟收复北洛丹伦努力的前锋，提供安全避难所、狮鹫运输以及针对天灾军团的行动指令。"},sec={{t="凋零之缘",b="寒风营地隐藏在从冰风岗蜿蜒而下的岩石隘口中，是联盟军队推进西瘟疫之地的第一道防线和主要作战基地。尽管高耸的山脊将其与最严重的腐化隔离开来，但北方死寂的寒意依然沉重地笼罩着营地的帐篷和栅栏。在阿什拉姆·瓦洛菲斯特指挥官的率领下，一小支由士兵、斥候和银色黎明专家组成的卫戍部队试图遏制在国王之路沿线徘徊的恐怖生物，并收集收复洛丹伦沦陷土地所需的关键情报。"},{t="消耗战",b="由于缺乏对安多哈尔或通灵学院这座亡灵要塞发动全面进攻所需的正规军队，寒风营地严重依赖于各地的勇士和雇佣兵。此处的行动专注于外科手术式的游击打击：收集关于The Cult of the Damned的情报，中和毒害土地的炼金瘟疫锅炉，并确保通往圣光之愿礼拜堂等东部前哨的补给线畅通。随着天灾军团盘踞在北面的废墟中，而被遗忘者加强了西部边境的防御，营地的守军战斗的目的仅仅是为了防止山口被敌军压制。"}},faq={{q="寒风营地的目的是什么？",a="寒风营地是联盟和银色黎明在西瘟疫之地边界的主要南部据点。它为在安多哈尔对天灾军团发动游击战以及中和区域内瘟疫锅炉的行动提供了安全的基地。",al={"为什么会有寒风营地","寒风营地的目的","什么是寒风营地"}},{q="如何从南海镇前往寒风营地？",a="从希尔斯布莱德丘陵的南海镇出发，向北前往塔伦米尔，然后沿着山间小径进入奥特兰克山脉的最东端。道路经过冰风岗的巨魔遗迹，随后向北穿过一条峡谷直接抵达营地。",al={"如何前往寒风营地","寒风营地路线","去寒风营地的路径"}},{q="这个前哨站有部落对应的版本吗？",a="部落对应的据点是亡灵壁垒，位于提瑞斯法林地和西瘟疫之地之间的西部边境。这两个前哨站都是针对区域内天灾军团作战的坚固补给基地。",al={"部落的寒风营地","寒风营地的部落版本","有部落版的寒风营地吗"}},{q="谁负责指挥寒风营地的部队？",a="阿什拉姆·瓦洛菲斯特指挥官领导着寒风营地的驻军，协调联盟志愿者、白银之手骑士团和银色黎明联络员在周边的废墟和被污染的农场开展行动。",al={"寒风营地的领导者","谁负责寒风营地","寒风营地指挥官"}}},fp="14,373,22.595.0,18.620.0,38.269.0,48.261.0,45.221.0,42.213.0"}
P.entries["subzone:chillwind-point"] = {n="冰风岗",s="冰风岗是一处位于奥特兰克山脉、希尔斯布莱德丘陵和西瘟疫之地之间高地边缘的岩石高地，也是一座古老的巨魔遗迹。它的名字来源于从北方被腐蚀的土地吹向山口的凛冽寒风。如今，这里是一个荒凉的瞭望点，主要住着一位孤独的巨魔神秘学家。",h="冰风岗是一处位于奥特兰克山脉、希尔斯布莱德丘陵和西瘟疫之地之间高地边缘的岩石高地，也是一座古老的巨魔遗迹。它的名字来源于从北方被腐蚀的土地吹向山口的凛冽寒风。如今，这里是一个荒凉的瞭望点，主要住着一位孤独的巨魔神秘学家。",kw={"奥特兰克","捕风者巴斯拉","寒风","冰风岗","希尔斯布莱德","瘟疫之地","巨魔遗迹","捕风者"},ang={["class:Shaman"]="山口中狂野的汇聚气流使冰风岗成为了一个元素汇聚之地，吸引着修行者前来向隐士捕风者巴斯拉学习。",["faction:Alliance"]="这些古老的遗迹位于寒风营地边防哨所的正南方，标志着争议不断的丘陵地带与恐怖的瘟疫之地之间的分界线。"},sec={{t="苦涩的十字路口",b="冰风岗位于希尔斯布莱德通往奥特兰克和被瘟疫侵蚀的北方地区的边缘地带，俯瞰着直通西瘟疫之地的山谷。在洛丹伦占领这些山口很久之前，远古巨魔就在这些高地上建造了石质建筑，这些遗迹至今仍屹立在那里，饱经风霜。今天，寒风穿过峡谷向南吹去，将陷落的北方大地的寒意带到了下方的丘陵地带。"},{t="捕风者",b="尽管这里环境恶劣且邻近天灾军团肆虐的土地，冰风岗并非完全荒无人烟。古老的石砌建筑为捕风者巴斯拉提供了庇护。他是一位丛林巨魔隐士，与穿过山口的狂暴大风进行沟通。前往北方的旅行者和萨满祭司经常会在废墟中寻找他的隐居营地，以学习山间气流的秘密。"}},faq={{q="什么是冰风岗？",a="冰风岗是一座古老的巨魔遗迹，坐落在一处高地上，俯瞰着希尔斯布莱德、奥特兰克和西瘟疫之地之间的山口。它的名字取自不断在邻近峡谷中呼啸而过的刺骨寒风。",al={"冰风岗概览","冰风岗在哪里","这是什么地方"}},{q="冰风岗和寒风营地是同一个地方吗？",a="不是，虽然它们经常被混淆。寒风营地是联盟和银色黎明在边界以北、西瘟疫之地内设立的防御前哨，而冰风岗则是稍微靠南一点的巨魔废墟高地。",al={"冰风岗与寒风营地的区别","寒风营地的不同之处","这是寒风营地吗"}},{q="谁住在冰风岗？",a="废墟中唯一的居住者是捕风者巴斯拉，一位友好的丛林巨魔，他研究风向，并帮助那些勇敢穿过山口的元素探索者和萨满祭司。",al={"谁在这里","那个巨魔是谁","巴斯拉"}},{q="为什么这里这么冷？",a="该据点直接毗邻一条狭窄的山谷，这条山谷将来自北部高海拔地区和西瘟疫之地被腐蚀的广袤土地上的冰冷气流汇聚并吹向较低的丘陵地带。",al={"为什么这里很冷","寒风","冰冷的风"}}},fx={["8e613e22"]={q="冰风岗过去发生过什么？",a="这处高地隘口曾属于繁盛的人类王国洛丹伦。然而，早在洛丹伦覆灭之前，巨魔便建起了那座至今仍矗立在山顶的古老石建筑。如今，它成了一处被遗弃的遗迹，夹在动荡的奥特兰克和从北方蔓延而来的疫病之间。",al={"冰风岗历史","冰风岗的过去","冰风岗发生过什么"}},["14e6a6f5"]={q="为什么冰风岗成了废墟？",a="山丘顶上的石建筑是一处古老的巨魔遗迹，早在近期的战争之前就已衰败。洛丹伦覆灭、周边山脉遭到蹂躏后，再无文明势力维持这处隘口，只剩风化的石构建筑暴露在严酷的自然环境中。",al={"为什么冰风岗成了废墟","冰风岗遗迹","为什么冰风岗被遗弃"}},b1aade3c={q="冰风岗危险吗？",al={"冰风岗安全吗","冰风岗的危险","冰风岗的威胁"}}},fp="15,354,19.478.0,15.392.0,24.235.0,46.238.0,29.177.0,23.203.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Circle of Aquementas",s="Circle of Aquementas是一个神秘的直立石圈，位于塔纳利斯东海岸，落帆海湾以南。它是一个仪式场所，旅行者可以在这里召唤元素之灵Aquementas。",h="Circle of Aquementas是一个神秘的直立石圈，位于塔纳利斯东海岸，落帆海湾以南。它是一个仪式场所，旅行者可以在这里召唤元素之灵Aquementas。",kw={"aquementas","circle of aquementas","元素","落帆海湾","直立石块","塔纳利斯"},ang={["class:Shaman"]="石圈聚集原始能量并锚定元素之灵的能力，使它成为了任何漫步在塔纳利斯海岸的萨满祭司眼中极具吸引力的奇观。"},sec={{t="海边的石圈",b="Circle of Aquementas隐匿在塔纳利斯风沙弥漫的东海岸，位于落帆海湾海盗据点以南。这个非同寻常的地点由呈环形排列的、历经风雨的直立石块组成，在沙漠海岸边散发着阵阵元素能量。它是召唤Aquementas的焦点，这是一位与古代神器息息相关的元素实体。尽管周围的海滩上爬满了南海海盗和游荡的海洋生物，但石圈本身依然是沙丘中一处肃穆的仪式之地。"}},faq={{q="Circle of Aquementas是什么？",a="它是一座位于塔纳利斯东南海岸的直立石圈，用于召唤元素实体Aquementas。",al={"这个石环是什么","circle of aquementas的用途","塔纳利斯的直立石块"}},{q="石圈位于何处？",a="石圈位于塔纳利斯东岸，就在落帆海湾的悬崖和入口正南方。",al={"circle of aquementas在哪里","如何找到circle of aquementas","circle of aquementas位置"}},{q="Aquementas是谁？",a="Aquementas是一个与涉及奇怪神器的古代任务线相关的元素之灵，可以直接在石圈中被召唤出来。",al={"aquementas是谁","aquementas背景故事"}},{q="石圈有海盗守卫吗？",a="虽然南海海盗在落帆海湾及周边海岸线附近徘徊，但石圈本身主要是一个孤立的召唤点。",al={"这里有海盗吗","石圈附近的南海海盗"}}},fp="20,246,17.546.0,33.154.0,28.119.0,18.139.0,33.146.0"}
P.entries["subzone:circle-of-east-binding"] = {n="东部禁锢法阵",s="东部禁锢法阵是一处神秘的古代仪式地点，位于阿拉希高地的东部边缘，就在落锤镇的西南方。该地点由东部禁锢之石固定，这里一直处于激烈的争夺之中，并由被称为涌动流放者的漫游水元素所守卫。",h="东部禁锢法阵是一处神秘的古代仪式地点，位于阿拉希高地的东部边缘，就在落锤镇的西南方。该地点由东部禁锢之石固定，这里一直处于激烈的争夺之中，并由被称为涌动流放者的漫游水元素所守卫。",kw={"阿拉希高地","东部禁锢法阵","涌动流放者","元素生物","落锤镇","东部禁锢之石"},ang={["class:Shaman"]="阿拉希的禁锢石代表了粗糙或古老的元素压制方法，这与萨满追求的元素平衡与沟通形成了鲜明对比。",["faction:Horde"]="法阵周围不稳定的水之灵位于落锤镇附近的一条路上，对部落的巡逻队和补给线造成了持续的领土困扰。"},sec={{t="东部结界",b="东部禁锢法阵位于斯托姆加德以东崎岖的高地之中，是散布在阿拉希盆地各处的若干古代力量据点之一。其中心矗立着东部禁锢之石，这是一座散发着强大元素魔法的神秘纪念碑。被称为涌动流放者的旋涡水元素在周围的土地上徘徊，并凶猛地抵御着任何胆敢靠近的凡人。"},{t="元素禁锢",b="阿拉希各处的法阵石并非仅仅是自然异常现象；它们发挥着古代禁锢结界的作用，旨在压制和囚禁不稳定的元素力量。东部法阵周围焦躁不安的水之灵显露出了这些结界所承受的压力，因为被法阵之石的魔法所吸引或困住的实体，会攻击那些在前往落锤镇的道路上经过的旅行者和冒险者。"}},faq={{q="东部禁锢法阵位于哪里？",a="东部禁锢法阵位于阿拉希高地的东部地区，大路以南，落锤镇部落营地的西南方。",al={"东部禁锢法阵位置","东部禁锢法阵在哪里","东部禁锢法阵地图"}},{q="这里有哪些生物？",a="法阵中充斥着极具攻击性的水元素，即不断守卫着东部禁锢之石的涌动流放者。",al={"东部禁锢法阵怪物","东部禁锢法阵有哪些怪物","涌动流放者"}},{q="为什么高地里会有水元素？",a="散布在阿拉希各处的石头作为古代元素禁锢存在。这里出现水元素表明，通过东部结界石引导的水元素能量在此受到了抑制或吸引。",al={"阿拉希的水元素原因","东部禁锢法阵元素背景"}},{q="东部禁锢之石的用途是什么？",a="东部禁锢之石是阿拉希高地各处一系列协同禁锢石网络的一部分，旨在锚定、引导并锁住不稳定的元素实体。",al={"东部禁锢之石用途","东部禁锢之石的作用"}}},fp="22,286,16.417.0,22.389.0,44.169.0,30.124.0,48.219.0,49.180.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="内禁锢法阵",s="内禁锢法阵是一圈古老的仪式石阵，位于阿拉希高地南部的丘陵地带，就在激流堡的东面。这里由充满敌意的土元素守卫，它是禁锢着深埋地底的元素公主Myzrael最强大的封印——内禁锢之石的所在地。",h="内禁锢法阵是一圈古老的仪式石阵，位于阿拉希高地南部的丘陵地带，就在激流堡的东面。这里由充满敌意的土元素守卫，它是禁锢着深埋地底的元素公主Myzrael最强大的封印——内禁锢之石的所在地。",kw={"阿拉希高地","内禁锢法阵","土元素","myzrael","轰鸣的流放者","内禁锢之石","激流堡"},ang={["class:Mage"]="石阵的几何排列构成了一个复杂且持久的收容场，能够引导并固定巨大的地下魔法压力。",["class:Shaman"]="涌动在内禁锢法阵中的原始土元素能量表明这里存在着古老而沉重的元素羁绊，然而当地土元素精神不自然的躁动也预示着地表之下存在着腐化。"},sec={{t="核心封印",b="内禁锢法阵坐落在大路南边的一处高原上，它是将Myzrael封印在阿拉希地下的最强古老结界的核心。高耸的石板环绕着中央的内禁锢之石，这块石头正散发着浓郁的地脉魔力。巨大的轰鸣土元素在此无休止地巡逻，或是受此地共鸣吸引，或是被束缚于此担任守卫。尽管有这些强大的结界，但这道内部封印上的裂痕还是让被困在高地之下的实体能够进行心灵感应，向那些接触过其石片碎块的无知漫游者低语求救。"}},faq={{q="内禁锢法阵的目的是什么？",a="该法阵内存放着内禁锢之石，它是锚定Myzrael地下监狱的主要且最强大的结界。它与散布在阿拉希高地各处的其他元素法阵协同作用，将该生物禁锢在地表之下。",al={"为什么这里有这个法阵","内禁锢法阵的作用是什么","内禁锢法阵背景故事"}},{q="什么生物守卫着这个法阵？",a="该法阵由强大的土元素严密守护，主要是轰鸣的流放者。这些岩石巨兽会猛烈攻击任何靠近仪式石阵的人。",al={"这里有什么敌人","内禁锢法阵怪物","轰鸣的流放者"}},{q="是谁在石头中低语？",a="通过禁锢碎片传出的声音属于Myzrael，这是一位被囚禁在地底深处的古老而强大的元素公主。她的心灵感应已经穿透了这道破碎的封印，试图与凡人的思想取得联系。",al={"是谁在这里和你说话","myzrael的声音","低语之石"}},{q="内禁锢法阵位于何处？",a="它位于阿拉希高地的南部，坐落在激流堡废墟以东的一处高耸山脊上。",al={"内禁锢法阵位置","内禁锢法阵在哪里","如何找到内禁锢法阵"}}},fp="23,327,13.590.0,51.274.0,33.169.0,36.239.0,45.152.0"}
P.entries["subzone:circle-of-west-binding"] = {n="西部禁锢法阵",s="西部禁锢法阵是散布在阿拉希高地的几处古老仪式地点之一，坐落于索拉丁之墙附近。这道奥术圆环围绕着西部禁锢之石，现在已经被束缚于此地的烈焰元素生物所占领。",h="西部禁锢法阵是散布在阿拉希高地的几处古老仪式地点之一，坐落于索拉丁之墙附近。这道奥术圆环围绕着西部禁锢之石，现在已经被束缚于此地的烈焰元素生物所占领。",kw={"阿拉希高地","燃烧的流放者","西部禁锢法阵","元素","ruul onestone","西部禁锢之石","索拉丁之墙"},ang={["class:Mage"]="阿拉希的禁锢之石为奥术修行者提供了关于古代法师和萨满如何锚定并制服位面元素生物的见解。",["class:Shaman"]="燃烧的流放者那动荡的存在揭示了与这些古老阿拉希基石相连的挥之不去的Elemental Unrest。"},sec={{t="西部基石",b="西部禁锢法阵依偎在索拉丁之墙附近崎岖的山坡上，是分散在整个阿拉希高地更广泛的仪式地点网络的一部分。它的中心坐落着西部禁锢之石，这是一件与元素禁锢相关的远古遗物。这片区域到处都是燃烧的流放者——那些不遗余力守卫着外围的暴躁火元素，这使得任何靠近这块石头的人对于穿越西部平原的旅行者来说都是一场危险的冒险。"}},faq={{q="什么是西部禁锢法阵？",a="它是一处位于阿拉希高地西部的古老仪式地点，坐落于索拉丁之墙附近。它存放着西部禁锢之石，并由敌对的火元素严密守卫。",al={"西部禁锢法阵","西部禁锢之石"}},{q="为什么这里会有火元素？",a="燃烧的流放者栖息并守卫着西部禁锢之石。它们是被吸引或被束缚在阿拉希高地各处所建造的远古魔法焦点上的元素力量。",al={"阿拉希燃烧的流放者","为什么西部禁锢法阵有火元素","西部禁锢法阵的元素"}},{q="Ruul Onestone是谁？",a="Ruul Onestone是一只徘徊在该地点的石拳食人魔，与其说他是禁锢之石的学者，不如说他是一个罕见而危险的蛮族。",al={"ruul onestone","ruul","西部禁锢法阵的矮人"}}},fp="22,253,20.472.0,35.174.0,35.173.0,21.132.0"}
P.entries["subzone:clean-zone"] = {n="Clean Zone",s="Clean Zone是一个防御森严的去污隔离区，坐落在诺莫瑞根废墟内，就在上层Hall of Gears的后面。它是这处受辐射设施中唯一的避风港，未受感染的侏儒部队在此坚守阵地，抵御周围的穴居人和麻风侏儒。在这里，战地医疗兵、技师和特制的Sparklematic机器在充满放射性的废墟中提供休整和打捞作业。",h="Clean Zone是一个防御森严的去污隔离区，坐落在诺莫瑞根废墟内，就在上层Hall of...",kw={"clean zone","dormitory","诺莫瑞根","hall of gears","辐射","sparklematic 5200","tink sprocketwhistle","穴居人"},ang={["profession:Engineering"]="可运作的Sparklematic 5200装置和商人Tink Sprocketwhistle的存在，使这个哨所成为了从受辐射的垃圾中搜寻稀有图纸和机械零件的关键地点。",["race:Gnome"]="对侏儒来说，站在Clean Zone既是对家园陷落的严酷提醒，也是一种坚定的希望之光，象征着诺莫瑞根的技术仍能从穴居人手中夺回。"},sec={{t="废料场中的堡垒",b="虽然诺莫瑞根的大部分地区因梅卡托克灾难性的放射性废料排放而沦陷，但Clean Zone却未受污染。它处于下方穴居人出没的Dormitory和上方争夺激烈的Hall of Gears走廊之间的战略要地，充当前线防御基地。坚定的侏儒守卫、技师和战地医疗兵日夜坚守着路障，确保联盟探险队有一个稳定的据点来重整旗鼓、包扎伤口和维护机械。"},{t="Sparklematic 5200型",b="除了作为军事据点外，Clean Zone还是打捞这座失落之城的中心。侏儒工程师安装了Sparklematic 5200装置，对从城市充满放射性的腹地中拖出的沾满污垢的遗物进行化学洗涤和清洁。技师和像Tink Sprocketwhistle这样的商人处理这些回收的齿轮和饰品，在为冒险者提供装备的同时，研究困扰着深层隧道的残留毒素。"}},faq={{q="为什么这个区域没有像诺莫瑞根的其他地方那样受到辐射？",a="Clean Zone收容了未受摧毁诺莫瑞根的辐射影响的侏儒。相关记录并没有解释为什么这个小区域能幸免于难。",al={"为什么clean zone没有受辐射","为什么这里安全","clean zone辐射"}},{q="Sparklematic 5200机器有什么作用？",a="Sparklematic 5200是特制的侏儒清洗和去污装置。冒险者可以将从穴居人和麻风侏儒身上获得的沾满污垢的物品投入其中，洗去放射性污垢，从而获得有用的矿石、宝石、硬币或工程学小玩意。",al={"sparklematic 5200","什么是sparklematic","清洗污垢"}},{q="谁在控制和保卫Clean Zone？",a="一支由未受感染的侏儒守卫、战地医疗兵和技师组成的精锐分队负责保卫外围。他们击退了从Dormitory入侵的穴居人以及从上层涌下的麻风侏儒，以确保这个补给站的安全。",al={"clean zone里有什么人","clean zone守卫","谁控制着clean zone"}},{q="玩家可以在这里安全地休息或修理装备吗？",a="是的。Clean Zone是诺莫瑞根深处的一个战地营地，为在前线后方活动的冒险者提供工程学补给、由商人Tink Sprocketwhistle提供的修理服务，甚至还有一个功能完好的邮箱。",al={"clean zone修理","能在clean zone休息吗","诺莫瑞根里的邮箱"}}},fx={dc9c4202={q="什么是Clean Zone？",a="Clean Zone是诺莫瑞根深处的一处设防庇护所，位于Hall of Gears上层之外。它是这座沦陷首都内最后一处据点，未受污染的侏儒在此坚守，得以避开致命的辐射尘埃。",al={"什么是clean zone","clean zone概况","关于clean zone"}},fa9b1319={q="诺莫瑞根陷落时，Clean Zone发生了什么？",a="大工匠梅卡托克开启辐射阀门清除入侵的穴居人时，毒性辐射尘埃席卷全城，许多侏儒因此变异成麻风侏儒。未受影响的侏儒守住这处小小的避难所，并抵御周围的入侵者。",al={"clean zone历史","clean zone发生过什么","clean zone的历史"}},["844f3e3b"]={q="Clean Zone危险吗？",a="Clean Zone内部安全，并由精锐侏儒守卫和医护人员严密防守。但紧邻这里的区域险象环生：下方宿舍里遍布敌对的穴居人，外围紧挨着的Hall of Gears上层也有穴居人大批出没。",al={"clean zone危险吗","clean zone内的威胁","clean zone的危险"}}},fp="10,424,21.486.0,21.438.0,59.175.0,42.263.0,40.249.0,39.232.0"}
P.entries["subzone:cleft"] = {n="大断崖",s="大断崖是位于泰达希尔，多兰纳尔西北方的一处阴暗洼地。这里曾经是枝叶间静谧的一角，如今却被堕落的棘鬃熊怪所占据。他们以此为据点，伏击沿主干道前往达纳苏斯的旅行者。",h="大断崖是位于泰达希尔，多兰纳尔西北方的一处阴暗洼地。这里曾经是枝叶间静谧的一角，如今却被堕落的棘鬃熊怪所占据。他们以此为据点，伏击沿主干道前往达纳苏斯的旅行者。",kw={"大断崖","达纳苏斯","多兰纳尔","熊怪","棘鬃","哨兵阿玛拉·夜行者"},ang={["class:Druid"]="堕落的棘鬃熊怪威胁着前往达纳苏斯路上的旅行者的安全。",["race:NightElf"]="大断崖代表了暗夜精灵的一场痛苦悲剧，他们眼看着长期的熊怪盟友陷入疯狂并攻击旅行者。"},sec={{t="堕落的巢穴",b="大断崖位于多兰纳尔和达纳苏斯之间的公路旁，现已成为世界之树上最危险的巢穴之一。受泰达希尔蔓延的邪恶腐蚀影响，居住于此的棘鬃熊怪已经陷入疯狂，并加固了这个洼地。这些疯狂的野兽以此为堡垒恐吓当地道路，威胁着要切断多兰纳尔与首都之间的联系。"},{t="路上的伏击者",b="大断崖带来的威胁已变得十分严峻，哨兵阿玛拉·夜行者和她的哨兵们被迫在入口外的道路沿线建立防御哨所。对于哨兵而言，肃清大断崖对于确保连接泰达希尔各村庄与达纳苏斯的主干道安全至关重要。"}},faq={{q="什么是大断崖？",a="大断崖是位于泰达希尔枝叶间的一处熊怪巢穴，坐落在多兰纳尔西北方，紧邻通往达纳苏斯的主干道。",al={"什么是大断崖","泰达希尔大断崖","大断崖位置"}},{q="谁控制着大断崖？",a="它被充满敌意的棘鬃熊怪占据，这些熊怪已成为泰达希尔逐渐蔓延的腐蚀的牺牲品。",al={"谁住在大断崖","大断崖敌人","谁统治大断崖"}},{q="暗夜精灵为什么要在这里战斗？",a="大断崖里的棘鬃熊怪一直在伏击前往达纳苏斯路上的旅行者。哨兵阿玛拉·夜行者和哨兵们致力于保障这条道路的安全。",al={"为什么要攻击大断崖","大断崖暗夜精灵任务","通往达纳苏斯的道路"}},{q="大断崖与暗影裂口有关吗？",a="没有。尽管名字相似，这个大断崖是泰达希尔的一处熊怪洞穴，而暗影裂口是位于部落主城奥格瑞玛内部的黑暗地下洞穴。",al={"与暗影裂口的联系","大断崖与暗影裂口"}}},fx={de17fe22={q="大断崖危险吗？",a="大断崖非常危险。敌对且堕落的Gnarlpine熊怪挤满了这处幽暗的巢穴。它们会凶狠地守卫自己的洞穴，已经伏击过补给线，还威胁过旅人。哨兵阿玛拉·夜行者和她的哨兵必须守住外面的道路，阻止它们出来。",al={"大断崖危险","大断崖安全吗","大断崖的威胁"}},["3e19e4c1"]={q="大断崖发生过什么？",a="Gnarlpine熊怪曾在洞穴中避难，但邪恶的腐化很快侵蚀了他们的心智。他们陷入疯狂后，开始袭击通往达纳苏斯附近的道路，攻击毫无防备的旅人，并威胁首都的商贸往来。",al={"大断崖的历史","大断崖发生过什么","大断崖历史"}}},fp="5,265,19.366.0,21.295.1,18.143.0,23.104.0,38.157.0,44.185.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Cleft of Shadow",s="Cleft of Shadow隐藏在奥格瑞玛地下的洞穴深处，是城中潜行者、法师和术士的聚集地。这里远离萨尔所提倡的尚武精神，却成为了部落潜行者和术士在阴影中开展活动的必要避风港。",h="Cleft of Shadow隐藏在奥格瑞玛地下的洞穴深处，是城中潜行者、法师和术士的聚集地。这里远离萨尔所提倡的尚武精神，却成为了部落潜行者和术士在阴影中开展活动的必要避风港。",kw={"cleft of shadow","暗火议会","奥格瑞玛","怒焰裂谷","潜行者","暗影迅捷兄弟会","术士"},ang={["class:Rogue"]="暗影迅捷兄弟会与毒药商人和开锁专家在此聚集，使这处阴暗的凹地成为了部落潜行特工的主要巢穴。",["class:Warlock"]="暗火议会为部落术士提供了一个在奥格瑞玛下方召唤恶魔和束缚邪能的准许之地，而不会招致萨满和战士们的直接愤怒。"},sec={{t="地下庇护所",b="虽然萨尔领导的新部落推崇荣誉、萨满教义和武装力量，但务实的领导层仍需为更隐秘的技艺保留一席之地。Cleft of Shadow开凿在首都下方的潮湿石洞中，聚集了潜行者组织“暗影迅捷兄弟会”和术士组织“暗火议会”。远离山谷地区熙熙攘攘的日常活动，这个阴暗的角落让钻研毒药和邪能的修行者可以在避开公众视线的同时，依然处于奥格瑞玛领导层的监视之下。"},{t="危险的边缘",b="除了作为秘密教学和魔法试剂的中心之外，Cleft of Shadow还直通怒焰裂谷。这片火热的火山洞穴网络如同蜂巢般遍布在奥格瑞玛下方，构成了持续的安全威胁，将勇敢的保卫者和险恶的邪教徒一同引向洞穴边缘。"}},faq={{q="为什么术士和潜行者被安置在这里的地下？",a="萨尔努力在光荣的萨满教义和战士传统下团结部落。虽然术士和潜行者的效用得到了认可，但他们的做法受到许多兽人民众的怀疑。将他们限制在地下洞穴中，可以对危险的邪能和非法活动进行有效控制和监控。",al={"为什么会有cleft of shadow","为什么术士在奥格瑞玛地下","cleft of shadow背景"}},{q="在Cleft of Shadow可以找到哪些主要的训练师和服务？",a="该洞穴是奥格瑞玛主要的潜行者和术士训练师中心。此外，这里还有毒药供应商、试剂商以及魔杖和法杖商人。",al={"cleft of shadow里的训练师","谁在cleft of shadow"}},{q="洞穴底部是什么入口？",a="通往洞穴底部的深渊连接着怒焰裂谷，这是一个位于奥格瑞玛下方、充满岩浆管道的危险地下网络，里面充斥着穴居人、炽热元素生物和邪恶的邪教徒。",al={"cleft of shadow里的地下城","cleft的洞穴入口","这里有什么副本"}}},fx={["866219a4"]={q="Cleft of Shadow是什么地方？",a="Cleft of Shadow是一座广阔的地下洞穴，深深凿入奥格瑞玛崎岖的峡谷之下。地面上的城市崇尚力量、荣誉与正面交锋，而这片昏暗的地下区域则聚集着一些不那么光彩、其技艺备受猜疑的人：潜伏于阴影中的潜行者，以及修习邪能魔法的术士。",al={"cleft of shadow是什么地方","cleft of shadow背景故事","关于cleft of shadow"}},["3bd03716"]={q="谁居住在Cleft of Shadow，或由谁管理？",a="没有任何一位领袖公开统辖这座洞穴；这里属于部落所容忍的流亡者、间谍和神秘学者。你会在此找到影速兄弟会的潜行者和黑火教派的术士，还有为他们那些非法技艺提供服务的用毒者与试剂商人。",al={"谁领导cleft of shadow","cleft of shadow的居民","谁住在cleft of shadow"}},b6f6ea67={q="Cleft of Shadow危险吗？",a="这座洞穴本身是奥格瑞玛正常运作的城区，对市民来说相对安全，不过恶魔召唤者和毒药商人让这里令人不安。更大的危险潜伏在大断崖的最底部：通往怒焰裂谷的火山通道。怒焰裂谷是一片庞大的熔岩隧道网络，里面遍布穴居人和邪教徒，就在城市地基之下。",al={"cleft of shadow安全吗","cleft of shadow危险吗","cleft of shadow的危险"}}},fp="15,307,24.521.0,21.326.0,50.318.0,69.155.0,49.191.0"}
P.entries["subzone:cliffspring-falls"] = {n="峭壁之泉",s="峭壁之泉是黑海岸壁泉河那壮观的源头，河水从东部的悬崖倾泻而下，奔涌进沿海的森林中。这里长期以来都被视为该地区洁净饮用水的主要来源，但其水质最近却遭受了邪恶且不断扩散的污染。为瀑布供水的地下洞穴已经被充满敌意的纳迦和阴暗的暮光之锤教徒所占据。",h="峭壁之泉是黑海岸壁泉河那壮观的源头，河水从东部的悬崖倾泻而下，奔涌进沿海的森林中。这里长期以来都被视为该地区洁净饮用水的主要来源，但其水质最近却遭受了邪恶且不断扩散的污染。为瀑布供水的地下洞穴已经被充满敌意的纳迦和阴暗的...",kw={"奥伯丁","峭壁之泉","壁泉河","黑海岸","费伍德森林","纳迦","暮光之锤","水污染"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们密切监测着这条河流，努力查明并净化那威胁要扼杀这片荒野的非自然腐烂。",["race:NightElf"]="对于奥伯丁的卡多雷来说，峭壁之泉的腐化是一场环境和精神上的危机，污染了滋养黑海岸古老森林的生命之水。"},sec={{t="被污染的源头",b="峭壁之泉从黑海岸东部边缘高耸岩壁上的洞穴中倾泻而出，汇入壁泉河，随后向西蜿蜒穿过树林注入大海。传统上，这条瀑布为当地的暗夜精灵定居点提供了最纯净的饮用水。然而近来，河水变得污浊不堪，导致疾病和生态衰退在整个流域蔓延。调查此事的博物学者们发现，瀑布源头的洞穴网络被邪恶的纳迦和黑暗教徒所占据，他们潜伏在阴影中密谋作恶，而来自邻近费伍德森林的恶魔腐蚀正威胁着要穿过高地的基岩渗入此地。"}},faq={{q="峭壁之泉是什么？",a="峭壁之泉是黑海岸东部的一处主要瀑布，它构成了壁泉河的源头。在历史上，它为周围的森林提供了主要的淡水饮用水源。",al={"峭壁之泉","峭壁之泉是什么"}},{q="为什么从瀑布流出的水会被污染？",a="据怀疑，原因来自两股邪恶势力：从腐化的费伍德森林穿过山脉渗出的恶魔污染，以及潜伏在为瀑布供水的洞穴内、极其活跃的暮光之锤教徒与敌对的纳迦。",al={"水为什么会被污染","壁泉河腐化","污染水源"}},{q="是谁占据了瀑布后的洞穴？",a="瀑布上方及后方的洞穴中布满了在淹没的密室中蜿蜒穿行的敌对纳迦，以及隶属于末日教派暮光之锤的教徒。",al={"洞穴里是谁","峭壁之泉洞穴怪物","谁住在峭壁之泉"}},{q="为什么峭壁之泉对黑海岸如此重要？",a="壁泉河贯穿了黑海岸北部的中心地带。由于它是该地区主要的淡水来源，其遭受的污染直接危及了野生动物、古老的树林以及当地暗夜精灵的栖息地。",al={"黑海岸为何在意","峭壁之泉的重要性"}}},fx={b072a170={q="峭壁之泉发生了什么？",a="峭壁之泉曾是一处纯净的山间瀑布，为黑海岸北部提供洁净的饮用水。第三次战争的浩劫过后，黑暗势力悄然侵入周围的荒野。河流源头的洞穴遭到腐化，使纯净的山泉变得污浊，也吸引了邪恶实体潜入其隐秘深处。",al={"峭壁之泉的历史","峭壁之泉发生了什么","峭壁之泉为何变化"}},["894b4715"]={q="峭壁之泉危险吗？",a="瀑布及其后方的洞穴极其危险。敌对的娜迦在水道中出没，狂热的暮光之锤教徒则潜伏在洞穴网络深处举行邪恶仪式。除了致命的居民，受到污染的泉水本身也会给任何胆敢饮用的人带来极大危险。",al={"峭壁之泉的危险","峭壁之泉安全吗","峭壁之泉的威胁"}}},fp="17,417,16.682.0,26.197.0,49.225.0,42.181.0,51.218.0"}
P.entries["subzone:clockwerk-run"] = {n="Clockwerk Run",s="Clockwerk Run是通往堕落的诺莫瑞根核心地带的主要入口走廊。这条受损的走廊位于Train Depot和Hall of Gears之间，充斥着有毒的辐射尘埃，并被受辐射的穴居人所占领。",h="Clockwerk Run是通往堕落的诺莫瑞根核心地带的主要入口走廊。这条受损的走廊位于Train Depot和Hall of Gears之间，充斥着有毒的辐射尘埃，并被受辐射的穴居人所占领。",kw={"clockwerk run","诺莫瑞根","hall of gears","受辐射的穴居人","train depot","穴居人"},ang={["profession:Engineering"]="沿途废弃的机械和坍塌的基础设施让人清楚地看到，当工业规模的侏儒机械遭受灾难性的爆炸和辐射破坏时会发生什么。",["race:Gnome"]="穿过Clockwerk Run是一个关于首都沦陷的苦涩提醒，它直接展示了那个试图净化城市的孤注一掷的计策是如何让入侵者发生变异，而不是将其消灭的。"},sec={{t="一处废墟之门",b="Clockwerk Run曾是Gnomeregan从外部Train Depot进入的主要门户，也是侏儒物流和交通繁忙的枢纽。当大工匠梅卡托克下令排放放射性废料以遏制穴居人入侵时，这条走廊变成了一个致命的陷阱。爆炸和随后的战斗导致走廊部分坍塌。如今，这条通道充斥着有毒气体和游荡的受辐射穴居人，使它成为任何探险队要到达上层Hall of Gears都必须杀出一条血路的危险前线。"}},faq={{q="Clockwerk Run通向哪里？",a="Clockwerk Run将深层拱顶外的Train Depot与Gnomeregan内部上层的Hall of Gears直接连接起来。",al={"clockwerk run位置","这条走廊通往哪里","clockwerk run入口"}},{q="为什么这里有这么多穴居人？",a="地下的穴居人在最初入侵期间涌入了Gnomeregan的下层通道。那些在Clockwerk Run游荡的穴居人吸收了大量排放出的放射性废料，变异成了凶猛的受辐射穴居人，攻击任何试图进入这座城市的人。",al={"为什么有穴居人","clockwerk run敌人"}},{q="为什么走廊部分坍塌了？",a="Gnomeregan沦陷期间的激烈战斗以及灾难性的有毒反制措施的释放，导致整个周边区域结构严重受损，使走廊部分坍塌。",al={"clockwerk run坍塌","为什么它破损了"}}},fx={["8c8c10db"]={q="Clockwerk Run是什么地方？",a="Clockwerk Run是一条宏伟的入口通道，直通诺莫瑞根深处。它从上层的Train Depot一直延伸到Hall of Gears，曾是繁忙的交通干道，将侏儒首都的外围交通系统与工业核心连接起来。如今，它已成为通往这座沦陷城市的一处破败而危险的入口。",al={"clockwerk run是什么地方","clockwerk run概况","这是什么区域"}},["556e3735"]={q="Clockwerk Run发生了什么？",a="穴居人从深处洞穴涌出并席卷诺莫瑞根时，侏儒孤注一掷，释放了有毒的放射性气体，试图消灭入侵者。计划酿成了灾难：侏儒被迫逃离或惨遭杀害，混乱中通道部分坍塌，遭受辐射变异的穴居人则占据了这条通道。",al={"clockwerk run的历史","clockwerk run发生了什么","clockwerk run的陷落"}},c5bdf1c1={q="现在是谁控制Clockwerk Run？",a="如今已没有文明势力控制这条通道。这里完全被凶残的穴居人占据，它们在诺莫瑞根沦陷时受到释放的有毒辐射影响而发生变异。任何胆敢踏入这片废墟的外来者都会遭到它们攻击。",al={"谁住在clockwerk run","谁控制clockwerk run","谁管理clockwerk run"}},aa198084={q="Clockwerk Run危险吗？",a="这里极其危险。通道中爬满了敌对的辐射穴居人，它们被残留的辐射逼得疯狂失常；部分天花板和墙壁也已坍塌。任何深入这条通道的人都必须做好准备，在摇摇欲坠的废墟中杀出一条路，对抗成群的变异野兽。",al={"clockwerk run危险吗","clockwerk run的危险","clockwerk run的威胁"}}},fp="13,248,18.561.0,34.135.0,34.272.0,39.217.0"}
P.entries["subzone:cold-hearth-manor"] = {n="炉灰庄园",s="炉灰庄园是一处荒废的农庄，位于布瑞尔以西，紧邻提瑞斯法林地的主要道路。这里曾是一处繁华好客的庄园，以丰收的农作物而闻名，但亡灵天灾的爆发夺走了所有居民的生命，使周边的田野里充斥着毫无理智的亡灵生物。如今，被遗忘者已经占领了主屋，将其作为旅行者的前哨站和中转站。",h="炉灰庄园是一处荒废的农庄，位于布瑞尔以西，紧邻提瑞斯法林地的主要道路。这里曾是一处繁华好客的庄园，以丰收的农作物而闻名，但亡灵天灾的爆发夺走了所有居民的生命，使周边的田野里充斥着毫无理智的亡灵生物。如今，被遗忘者已经占领...",kw={"布瑞尔","炉灰庄园","农庄","被遗忘者","天灾军团","提瑞斯法林地","僵尸"},ang={["faction:Horde"]="这座庄园在布瑞尔与提瑞斯法东部区域之间的道路上提供了一个安全的制高点，为穿行于这片被瘟疫侵袭的乡村的旅行者提供了一个安全的补给站。",["race:Undead"]="对于被遗忘者而言，收复炉灰庄园这样的地方是苦涩的提醒，让他们想起自己失去的凡人生活，将昔日人类的避风港改造成对抗天灾军团和血色十字军的阴森防御前哨。"},sec={{t="冰冷的炉火",b="在第三次战争之前，这座庄园以温馨好客而闻名，是洛丹伦腹地的丰饶粮仓。当瘟疫席卷王国时，整户人家和他们的劳工都未能幸免，死后又作为天灾军团的行尸走肉复活。虽然野性的亡灵仍在荒废的田野间徘徊，但被遗忘者的部队成功将那些毫无理智的死尸赶出了主屋，收复了这座建筑，使之成为通往东部林地道路上的贸易点和立足点。"}},faq={{q="住在这里的人们发生了什么事？",a="当亡灵瘟疫席卷洛丹伦时，照料庄园的农夫和工人们全都被杀害了。他们死后并未获得安息，而是被复活成了毫无理智的僵尸，至今仍在周边的田野中徘徊。",al={"谁住在炉灰庄园","庄园背景故事","这家人发生了什么"}},{q="为什么叫它炉灰庄园？",a="这座庄园最初以其温馨的氛围和迎接客人的炉火而闻名。这个阴森的名字很可能是被遗忘者所取的，是对其往日时光的一种讽刺，意在彰显这座农场如今是多么寒冷、死寂和荒芜。",al={"炉灰庄园名字含义","为什么叫炉灰"}},{q="现在谁控制着这座庄园？",a="被遗忘者已经控制了主屋，将其作为往返布瑞尔的旅行者和商人的安全驻点。然而，庄园周边的开阔田野和谷仓依然被敌对的天灾军团所盘踞。",al={"谁拥有炉灰庄园","炉灰庄园友好吗"}},{q="为什么被遗忘者不清理那些田野？",a="在提瑞斯法林地的被遗忘者兵力不足，他们既要对抗毫无理智的天灾残党，又要抵御血色十字军的圣战者。确保主屋和主路的安全能提供直接的效用，而田野里散落的死尸只是碍事，而非对布瑞尔构成的直接威胁。",al={"为什么田野里有僵尸","为什么天灾军团在这里"}}},fx={["29a639a2"]={q="炉灰庄园是什么地方？",a="炉灰庄园是一座位于提瑞斯法林地中部主路旁的农庄。它曾以丰收的作物和宜人的氛围闻名洛丹伦，却在第三次战争期间随着亡灵瘟疫席卷乡野而沦陷。如今，被遗忘者商人守着农舍，在路边勉强维持营生，与旅人交易，同时警惕地留意周围遭到疫病侵蚀的土地。",al={"炉灰庄园是什么地方","炉灰庄园概况","炉灰庄园背景故事"}},["673749f2"]={q="炉灰庄园发生了什么？",a="第三次战争期间，亡灵瘟疫摧毁了这座农庄，所有在此生活和耕作的人都丧了命。失去理智的天灾僵尸从死者中爬起，在杂草丛生的田地间游荡。洛丹伦沦陷后，被遗忘者重新占据了农舍，将这处人类农耕生活的惨淡遗迹改造成提瑞斯法大道旁的前哨。",al={"炉灰庄园的历史","这里发生了什么","炉灰庄园的故事"}},["7e9cca93"]={q="炉灰庄园危险吗？",a="农舍本身有被遗忘者商人驻守，能提供一定程度的安全，但周围的田地危机四伏。失去理智的天灾僵尸仍然盘踞在荒地上，会攻击任何偏离道路的人。旅人必须保持警惕，因为天灾的威胁始终就在庄园门外。",al={"炉灰庄园的危险","这里安全吗","炉灰庄园的威胁"}}},fp="17,390,16.513.0,43.236.0,35.230.0,33.229.0,44.297.0"}
P.entries["subzone:coldridge-pass"] = {n="寒脊山小径",s="寒脊山小径是一条崎岖且被积雪覆盖的隧道，横穿丹莫罗南部的山脊。它是连接与世隔绝的寒脊山谷训练场和王国其他地区的唯一陆路通道，出口靠近繁华的卡拉诺斯小镇。由于敌对的穴居人已经占领了这条通道，任何试图穿越的旅行者都必须杀出一条血路，或者孤注一掷冲向另一端。",h="寒脊山小径是一条崎岖且被积雪覆盖的隧道，横穿丹莫罗南部的山脊。它是连接与世隔绝的寒脊山谷训练场和王国其他地区的唯一陆路通道，出口靠近繁华的卡拉诺斯小镇。由于敌对的穴居人已经占领了这条通道，任何试图穿越的旅行者都必须杀出一...",kw={"安威玛尔","寒脊山小径","寒脊山谷","丹莫罗","卡拉诺斯","山路","穴居人","隧道"},ang={["race:Dwarf"]="对于矮人山地猎人和新兵来说，穿越寒脊山小径意味着你将从安威玛尔的新手训练毕业，开始在铁炉堡的领地内服役。",["race:Gnome"]="寻求援助联盟的流亡侏儒必须穿过这个被穴居人盘踞的咽喉要道，才能到达卡拉诺斯，进而走上通往铁炉堡的高地之路。"},sec={{t="离开山谷的门户",b="对于刚踏出寒脊山谷的年轻矮人新兵和侏儒新手来说，寒脊山小径是一场严酷的成人礼。这条直接凿穿岩石的隧道是连接刚完成训练的冒险者通往东部卡拉诺斯前哨枢纽的主要通道。这里曾经是一条安全的山中走廊，如今却变成了一个危险的咽喉要道，里面充斥着从地下深处涌出的凶猛穴居人，威胁着每一个试图往返于避风山谷和广阔丹莫罗地区的人。"}},faq={{q="寒脊山小径通向哪里？",a="这条小径连接了西南部的寒脊山谷和广大的丹莫罗地区，出口位于卡拉诺斯小镇西侧的雪山丘陵中。",al={"寒脊山小径通往哪里","寒脊山小径目的地","如何离开寒脊山谷"}},{q="为什么寒脊山小径里会有穴居人？",a="穴居人最近从丹莫罗地下的深层裂隙中涌出，占领了该地区的黑暗洞穴和隧道。寒脊山小径为它们提供了庇护所，也成为了伏击山地旅行者的便利地点。",al={"为什么这里有穴居人","寒脊山小径怪物","穴居人入侵"}},{q="穿过寒脊山小径安全吗？",a="不，不安全。隧道里到处都是敌对的穴居人，这意味着新兵和旅行者必须砍杀这些野兽，或者在黑暗中奔跑，才能到达另一端。",al={"寒脊山小径危险吗","我可以穿过寒脊山小径吗"}},{q="谁在守卫或维护这条小径？",a="山地猎人会监视山谷和道路出口，但隧道内部仍然处于争夺状态且未被清理，旅行者在穿越时只能自求多福。",al={"寒脊山小径的矮人守卫","谁控制了这条小径"}}},fx={["7f71f8e0"]={q="寒脊山小径的历史是怎样的？",a="寒脊山小径开凿于丹莫罗群山之间，是连接与世隔绝的寒脊山谷训练场、外界和边境小镇卡拉诺斯的主要通道。数代以来，矮人新兵和登山者都经由这条通道，在山谷与王国其他地区之间自由往来。然而，近期敌对穴居人出现在隧道内，打破了这里的平静，迫使旅人必须杀出一条路，才能通过这条曾经安全的交通路线。",al={"寒脊山小径的历史","寒脊山小径发生了什么","寒脊山小径背景"}}},fp="14,440,29.541.0,31.157.0,39.231.0,41.190.0,33.179.0"}
P.entries["subzone:coldridge-valley"] = {n="寒脊山谷",s="寒脊山谷是一个隐蔽的、覆盖着白雪的山谷，位于丹莫罗的西南部高地。它以安威玛尔村落为中心，是年轻的矮人和诺莫瑞根流亡者初次拿起武器为铁炉堡效力时的训练场。一条名为寒脊山小径的隧道连接着这片与世隔绝的山谷和广阔的山区。",h="寒脊山谷是一个隐蔽的、覆盖着白雪的山谷，位于丹莫罗的西南部高地。它以安威玛尔村落为中心，是年轻的矮人和诺莫瑞根流亡者初次拿起武器为铁炉堡效力时的训练场。一条名为寒脊山小径的隧道连接着这片与世隔绝的山谷和广阔的山区。",kw={"安威玛尔","寒脊山小径","寒脊山谷","丹莫罗","霜鬃巨魔","铁炉堡","新手区","石腭怪"},ang={["race:Dwarf"]="作为铜须登山者和牧师的传统训练地，山谷代表了一个矮人离开炉火，投身服务于铁炉堡的第一步。",["race:Gnome"]="对于被迫离开诺莫瑞根的侏儒流亡者来说，寒脊山谷的雪地为他们提供了一个安全的避难所，让他们能够与矮人东道主一起掌握法术和机械技术。"},sec={{t="一处与世隔绝的试炼场",b="寒脊山谷被陡峭的山崖环绕，与丹莫罗繁忙的贸易路线基本隔绝。在它的中心坐落着安威玛尔，那是一座坚固的石制大厅和村落，经验丰富的矮人教官和流离失所的侏儒学者们在那里训练新兵，教导他们战斗、潜行和魔法的艺术。在安威玛尔的炉火温暖之外，谷底覆盖着厚厚的积雪，野猪和饥饿的冬狼在此徘徊，为新手们提供了他们初次体验边境生存的机会。"},{t="逼近的敌人",b="尽管寒脊山谷相对孤立，但它正面临来自两个冷酷敌人的直接威胁。当地的霜鬃巨魔已经建立了诸如Frostmane Hovel之类的营地，他们与登山者发生冲突，并为了保卫祖先的领地而抵御矮人的入侵。更糟糕的是，野蛮的石腭怪已经占领了寒脊山谷通往卡拉诺斯的唯一自然通道——寒脊山小径。如果不击退这些来自地下的野蛮生物，旅行者和补给就无法在山谷和铁炉堡高地之间自由通行。"}},faq={{q="如何离开寒脊山谷？",a="离开山谷的唯一陆路是穿过寒脊山小径，这是一条向东北方向穿过山脊的雪地隧道。穿过小径后，道路直接向东通往卡拉诺斯镇，并继续前往铁炉堡的宏伟大门。",al={"离开寒脊山谷","如何出去","通往卡拉诺斯的路径"}},{q="为什么侏儒会和矮人一起在这里开始冒险？",a="在诺莫瑞根悲剧性地落入石腭怪手中并遭受辐射污染后，幸存的侏儒作为难民逃往了丹莫罗。大工匠梅卡托克的子民受到了国王麦格尼·铜须的欢迎，这使得许多流亡的侏儒学徒能够在安威玛尔与年轻的矮人并肩受训。",al={"寒脊山谷的侏儒","为什么侏儒在这里","侏儒新手区"}},{q="有哪些威胁在困扰着山谷？",a="山谷面临两大主要威胁：敌对的霜鬃巨魔，他们反感矮人在其山地领土上的定居；以及粗野的石腭怪，它们从地底深处爬上来，封锁了寒脊山小径。此外，狼和野猪等当地掠食者也会袭击不谨慎的旅行者。",al={"寒脊山谷的敌人","山谷的威胁","谁在攻击"}},{q="什么是安威玛尔？",a="安威玛尔是寒脊山谷的核心堡垒和定居点。它容纳了职业训练师、锻造大师以及协调山谷防御并为新晋冒险者踏入广阔世界做准备的当地登山者军官。",al={"安威玛尔镇","这里的城镇是什么"}}},fx={["80e4cacf"]={q="寒脊山谷是什么地方？",a="寒脊山谷是一处隐于丹莫罗西南角、积雪覆盖的幽静盆地。它四周环绕着嶙峋的山峰，是年轻矮人和侏儒难民在踏入更广阔的王国之前接受训练、集结待命的隐蔽营地。",al={"寒脊山谷概况","寒脊山谷在哪里","寒脊山相关信息"}},["73aec6cd"]={q="寒脊山谷属于丹莫罗吗？",a="是的，它位于丹莫罗西南部的高地。四周的群山将它与这片冰雪覆盖的区域其余部分隔开，东北方向只有一条狭窄的寒脊山小径隧道与大陆相连。",al={"寒脊山属于丹莫罗吗","丹莫罗的寒脊山谷"}},["0ba4a80e"]={q="寒脊山谷危险吗？",a="这片山谷原本是宁静而隐蔽的训练场，但近来麻烦已经蔓延到了这里。敌对的霜鬃巨魔潜伏在附近营地，凶猛的野生动物在雪地中出没，而残暴的穴居人已经占据了通往丹莫罗其他地区的唯一山道。",al={"寒脊山的危险","这里安全吗","寒脊山的威胁"}},["7fc500c6"]={q="谁统治矮人？",a="铁炉堡的矮人由国王麦格尼·铜须统治。国王麦格尼是一位坚定的领袖，也是大战的老兵。他在雄伟的山中王座厅治理铁炉堡王国，也是联盟最坚毅的勇士之一。",al={"矮人国王是谁","铁炉堡之王","矮人领袖"}},ff57e405={q="卡拉诺斯有什么？为什么大家总提到它？",a="卡拉诺斯是一座热闹的边境小镇，位于寒脊山小径之外、通往铁炉堡的主路旁。这里是年轻新兵报到服役、学习工艺训练，以及在雷酒酿制厂品尝举世闻名麦酒的主要前哨。",al={"卡拉诺斯是什么地方","为什么要去卡拉诺斯","卡拉诺斯小镇"}},["966deec9"]={q="森内尔·白须是谁？",a="森内尔·白须是一位重要的矮人领袖，驻扎在附近的边境小镇卡拉诺斯。他负责协调当地的防务，积极铲除霜鬃冰巨魔在丹莫罗各处山峰上建立的危险据点。",al={"森内尔·白须","森内尔·白须和卡拉诺斯"}},a3c72edd={q="我是怎么来到寒脊山谷的？",a="你来到寒脊山谷，是因为这里是丹莫罗新兵的隐蔽训练场。山谷坐落在西南部群山之中，为有志成为守卫者的人提供了一处僻静之地，让他们学习技艺、收集装备，并在踏入外界更广阔也更险恶的领域前证明自己的实力。",al={"我是怎么来到这里的","我为什么在这里","我是怎么到这里来的","是什么带我来到这里"}},["8bdf0a70"]={q="我在寒脊山谷该做些什么？",a="你的任务是接受基础训练、磨炼战斗技巧，并协助驻扎在安威玛尔的当地官员。你需要清除滋扰当地的野兽，击退步步逼近的霜鬃巨魔和穴居人，最终打通寒脊山小径，前往卡拉诺斯报到服役。",al={"我在这里做什么","我的任务是什么","我在寒脊该做什么"}},["2eeaa2be"]={q="为什么新来的矮人会从寒脊山谷开始？",a="作为一名年轻的矮人冒险者，你来到安威玛尔，在老练的训练师指导下学习武技与魔法传统。铁炉堡需要坚定的勇士来守护疆土，而这片群山中的摇篮正是绝佳的试炼之地，能够将新兵锻造成卡兹莫丹久经沙场的守卫者。",al={"矮人为什么从这里开始","矮人为什么在这里","矮人出生区域","矮人为什么从寒脊山谷开始"}},ef9153cd={q="为什么新来的侏儒会从寒脊山谷开始？",a="诺莫瑞根最近沦陷于穴居人的入侵，幸存的侏儒逃离家园，在矮人盟友中找到了庇护。作为一名流亡的侏儒，你渴望帮助联盟并重建族人的未来，于是来到安全的寒脊山谷，与矮人新兵一同开始训练。",al={"侏儒为什么从这里开始","侏儒为什么在这里","侏儒出生区域","侏儒为什么从寒脊山谷开始"}}},fp="16,350,25.508.0,16.522.0,34.256.0,47.293.0,38.283.0,17.249.0"}
P.entries["subzone:command-center"] = {n="Command Center",s="Command Center，通常被称为Stormwind Barracks，坐落在Old Town的中心地带，是该市军事官员的作战总部。在和平时期，这里驻扎着常备军，但由于Stormwind的军队被派往遥远的边境，它目前仅由一小队经验丰富的骨干人员负责训练新兵和当地民兵。",h="Command Center，通常被称为Stormwind Barracks，坐落在Old...",kw={"ander germaine","兵营","command center","old town","暴风城兵营","战士训练师","wu shen"},ang={["class:Warrior"]="Command Center是暴风城战士训练的主要枢纽，像Ander Germaine和Wu Shen这样的老兵在这里将新兵磨练成纪律严明的火线士兵。"},sec={{t="脆弱的防线",b="Command Center位于Old Town那饱经风霜的街道内，是暴风城王国主要的驻军和军事训练场。该设施通常挤满了正规步兵和高级军官，但现在却异常空旷。由于大部分皇家军队都投入了海外战役，兵营现在依靠一批经验丰富的教官——包括Ander Germaine和武术家Wu Shen——来训练新战士，以加强城市的防御。"},{t="Old Town的武术中心",b="整个暴风城的卫兵在人们寻求重型武器和战术格斗指导时，通常会将他们指引向“兵营”。这座建筑靠近Pig and Whistle Tavern，同时也靠近Old Town其他区域那些阴暗的行动，这使它成为了这个以酒馆斗殴和流氓活动著称的区域中，维持秩序的关键支柱。"}},faq={{q="为什么Command Center这么空？",a="大部分暴风城的常备军已被部署到世界各地遥远的前哨站和外国战场。Command Center目前只保留了一小队经验丰富的退伍军人来指导新兵和组织当地防御。",al={"为什么这里卫兵很少","暴风城军队在哪里","兵营空了"}},{q="Command Center和Stormwind Barracks是同一个地方吗？",a="是的。虽然官方名称是Command Center，但城市卫兵和当地居民在指路时习惯称该建筑为Stormwind Barracks。",al={"暴风城兵营","指挥中心和兵营是同一个吗","兵营位置"}},{q="谁负责这里的训练？",a="Ander Germaine与Wu Shen和Ilsa Corbin等教官一起协调并训练该市的战士。",al={"谁在这里训练战士","指挥中心战士训练师","谁管理兵营"}},{q="Command Center位于哪里？",a="Command Center位于Old Town，靠近Pig and Whistle Tavern，处于该区训练设施的中心位置。",al={"指挥中心在哪里","指挥中心位置","如何找到指挥中心"}}},fx={["3e3491ec"]={q="Command Center是什么地方？",a="Command Center是暴风城军队的作战总部和训练营房。它位于Old Town，是军官和战士训练师操练新兵、协调王国防御的主要据点。",al={"command center是什么","暴风城的command center","这是什么建筑"}},["1a0e6604"]={q="Command Center危险吗？",a="完全不危险。Command Center是一座坚固的要塞，安全地坐落于暴风城的中心。这里由经验丰富的老兵和忠于联盟的精锐战斗教官驻守，是首都最安全的设施之一。",al={"command center危险吗","command center的危险","这里安全吗"}}},fp="14,366,22.488.0,22.335.0,35.248.0,57.166.0,28.109.0,36.134.0"}
P.entries["subzone:commons"] = {n="Commons",s="平民区是铁炉堡充满活力的商业中心，它直接连接着城市入口与广阔的洞穴。这里挤满了商人、旅客和银行家，是矮人首都最繁忙的通道，也是整个联盟的核心市场。",h="平民区是铁炉堡充满活力的商业中心，它直接连接着城市入口与广阔的洞穴。这里挤满了商人、旅客和银行家，是矮人首都最繁忙的通道，也是整个联盟的核心市场。",kw={"拍卖行","银行","平民区","铁炉堡","市场","stonefire tavern","vault of ironforge"},ang={["faction:Alliance"]="平民区实际上充当了联盟交易大厅的角色，吸引着来自泰达希尔、暴风城和诺莫瑞根的英雄们前来拍卖珍贵的战利品并储备补给。",["race:Dwarf"]="对于铜须矮人来说，平民区是他们的骄傲，证明了矮人的好客、勤劳和商业繁荣可以在冰封的山脉深处蓬勃发展。"},sec={{t="山脉的商业枢纽",b="平民区位于铁炉堡大门东北方，是进入这座山中王国的旅客所见到的第一个城区。这条繁华的商业街直接在岩石中开凿而成，这里不仅有主要的联盟拍卖行、Stonefire Tavern，还有位于Vault of Ironforge内的城市中心银行。宽阔的大道将其与Great Forge、Mystic Ward和Military Ward顺畅地连接起来，确保了山城内几乎所有的行人流量都会经过其繁忙的店面。"},{t="联盟的十字路口",b="得益于铁炉堡在东部王国大陆的中心位置，以及连接暴风城的矿道地铁，平民区成为了联盟主要的贸易枢纽。冒险者们聚集于此，交易从艾泽拉斯各个角落带来的货物，从Steelfury's Weapon Emporium购买武器，从Barim处购买施法材料，或者在踏入卡兹莫丹的漫天风雪之前，于当地旅店温暖的灯光下会面。"}},faq={{q="是什么让平民区相比其他城区如此拥挤？",a="平民区拥有联盟主要的拍卖行、位于Vault of Ironforge的城市主银行，以及繁华的Stonefire Tavern。它位于主大门内的优越地理位置，使其成为了整个王国最便利的聚集和交易场所。",al={"为什么平民区很忙","为什么这里玩家很多","铁炉堡贸易枢纽"}},{q="平民区通向哪里？",a="平民区连接着铁炉堡几乎所有主要的城区。向西南方走会回到城市大门，向东北方连接Great Forge，向东方延伸至Military Ward，向北方则通往Mystic Ward。",al={"平民区出口","如何离开平民区","平民区方向"}},{q="这里有哪些关键的商店和服务？",a="除了拍卖行和银行，平民区还设有铁炉堡游客中心、Steelfury's Weapon Emporium、铁炉堡军械库、Barim的施法材料店以及Fizzlespinner杂货店。",al={"平民区商人","平民区服务","铁炉堡平民区便利设施"}},{q="银行位于这里吗？",a="是的。Vault of Ironforge位于平民区拍卖行的对面，是该市的主要银行。",al={"铁炉堡银行在哪里","铁炉堡金库","银行位置"}}},fx={["1b528195"]={q="Commons是什么地方？",a="Commons是铁炉堡主要的商业街区。它位于城门内侧，与几乎所有其他城区相连，是矮人首都繁荣的经济中心。旅客和市民可以在这里的拍卖行买卖货物、使用城市金库、入住Stonefire Tavern，或是浏览各地商人的商品。",al={"commons是什么","铁炉堡commons","关于commons"}},e4c18740={q="Commons危险吗？",a="一点也不危险。Commons是整个卡兹莫丹人口最密集、治安最好的城区之一。这里有坚不可摧的山体石墙保护，铁炉堡卫兵也时刻巡逻，访客在此办事时无需担心野兽或敌人入侵。",al={"commons危险吗","commons有什么危险","这里安全吗"}}},fp="7,278,34.513.0,29.445.0,62.262.0,28.230.0,43.195.0,25.115.0"}
P.entries["subzone:corin-s-crossing"] = {n="考林路口",s="考林路口是一座位于东瘟疫之地中南部主要十字路口的被毁人类定居点。这里曾经是斯坦索姆、提尔之手、达隆郡和Andorhal之间一个繁荣的中转站，如今这座满目疮痍的城镇已被天灾军团完全占领。其破败的市政厅和铁匠铺中潜伏着挥之不去的恐怖，包括隐形的幽灵看守者。",h="考林路口是一座位于东瘟疫之地中南部主要十字路口的被毁人类定居点。这里曾经是斯坦索姆、提尔之手、达隆郡和Andorhal之间一个繁荣的中转站，如今这座满目疮痍的城镇已被天灾军团完全占领。其破败的市政厅和铁匠铺中潜伏着挥之不...",kw={"考林路口","东瘟疫之地","魔刃之痕","米雷达尔湖","看不见的仆从"},ang={["class:Paladin"]="考林路口的废墟代表了洛丹伦中心地带的彻底亵渎，这里作为一个邪恶的天灾据点，嘲弄着沿路更前方的圣地堡垒斯坦索姆。",["class:Rogue"]="在这里不要相信你的影子。看不见的仆从在巷子里游荡，凡人肉眼无法看见它们，而且它们能直接看穿你的潜行，这使得在城镇广场随意行走等同于自寻死路。"},sec={{t="破碎的十字路口",b="Before the Third War, Corin's Crossing served as a central junction for travel across eastern Lordaeron. Positioned between the shimmering waters of Lake Mereldar and what has now become the blighted chasm of the Infectis Scar, its thoroughfares once bore merchants, couriers, and pilgrims traveling between the great bastion of Stratholme and the southern strongholds. When the plague swept through the province, the settlement stood directly in the path of destruction, collapsing swiftly beneath the sheer weight of the undead vanguard."},{t="被诅咒者的避难所",b="如今，考林路口已完全沦陷于天灾军团之手。漫无目的的亡灵充斥着泥泞的街道，腐烂的尸骸和食尸鬼则徘徊在空荡荡的铁匠铺和市政厅内。对于侦察兵来说，这座城镇尤其危险：隐形的“看不见的仆从”在废墟中游荡，凡人的肉眼根本无法察觉。它们能洞穿普通的潜行，伏击任何试图绕过主力部队而不被发现的旅行者。"}},faq={{q="瘟疫发生前考林路口是什么样的地方？",a="它曾是洛丹伦东部一个繁荣的枢纽城镇。以市政厅和铁匠铺为中心，在天灾军团屠杀其居民之前，它曾为往来于斯坦索姆、提尔之手、达隆郡和Andorhal之间的旅客提供服务。",al={"考林路口历史","考林路口背景故事","考林路口曾经是什么"}},{q="为什么考林路口对潜行者来说如此危险？",a="这座城镇被“看不见的仆从”——一群效忠于天灾军团的隐形幽灵所困扰。这些幽灵可以毫不费力地识破魔法和普通的潜行，让粗心大意的潜行者或侦察兵猝不及防，并引来附近的亡灵。",al={"考林路口潜行","看不见的仆从","潜行者考林路口"}},{q="城镇周围有哪些主要地标？",a="考林路口位于东瘟疫之地的中南部。被荒废的魔刃之痕深沟就在附近，米雷达尔湖则沿其边界延伸。",al={"考林路口位置","考林路口在哪里"}},{q="谁现在控制着考林路口？",a="天灾军团完全统治着这些废墟。镇上没有任何活着的守军，整个定居点到处都是游荡的亡灵士兵和幽灵。",al={"谁拥有考林路口","考林路口阵营"}}},fp="16,358,22.539.0,21.419.0,44.228.0,60.222.0,39.180.0,36.169.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="考兰之匕",s="考兰之匕是耸立在希尔斯布莱德丘陵北部，四座山脊状山脉中的第二座。这片高地是辛迪加盗贼的藏身处。",h="考兰之匕是耸立在希尔斯布莱德丘陵北部，四座山脊状山脉中的第二座。这片高地是辛迪加盗贼的藏身处。",kw={"考兰","考兰之匕","匕首","四指","希尔斯布莱德","辛迪加"},ang={["race:Dwarf"]="这座山脊是辛迪加的藏身处，因此穿越北部丘陵的矮人旅行者应该做好遇到强盗而非盟友的心理准备。",["race:Undead"]="占据山脊的辛迪加匪徒对在希尔斯布莱德活动的被遗忘者抱有敌意。"},sec={{t="北部据点",b="考兰之匕陡峭地耸立在希尔斯布莱德丘陵北部，是当地被称为“希尔斯布莱德之指”的四座岩石突起中的第二座。这座山脊被辛迪加的匪徒占据，他们利用这一高处俯瞰下方的山谷。"}},faq={{q="谁控制着考兰之匕？",a="这座山脊由辛迪加的人类叛徒占据，他们将这里作为藏身处。",al={"考兰之匕有什么人","考兰之匕所属阵营","谁住在这里"}},{q="什么是希尔斯布莱德之指？",a="希尔斯布莱德之指是从北部山脉向南延伸至希尔斯布莱德山谷的四座突出的手指状山脊。考兰之匕是这些地貌中的第二座。",al={"希尔斯布莱德四指","希尔斯布莱德四山脊","希尔斯布莱德之指"}}},fx={["2610a3ae"]={q="考兰之匕是什么地方？",a="考兰之匕是希尔斯布莱德四座著名山脊中的第二座，这些山脊被称为“手指”，沿着山麓北缘拔地而起。辛迪加的流亡人类盘踞高处，将山脊用作藏身之所，俯瞰下方的山谷。",al={"考兰之匕是什么","考兰之匕的背景","考兰之匕山丘"}},dcd9fc97={q="考兰之匕危险吗？",a="危险。辛迪加的匪徒占据着这座山脊，把高处当作藏身之所；无论联盟还是部落的旅人，只要靠得太近，他们都会发动袭击。",al={"考兰之匕安全吗","考兰之匕的危险","考兰之匕的敌人"}}},fp="16,184,22.271.0,30.86.0,34.205.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="工匠区",s="工匠区是达纳苏斯北部一处熙熙攘攘的工匠区域。它是这座暗夜精灵首都的主要贸易和制造中心，坐落着各种工作室、专业训练师和一家热闹的旅店。该区域还接待外部代表，其中包括一个为中立组织银色黎明设立的使馆。",h="工匠区是达纳苏斯北部一处熙熙攘攘的工匠区域。它是这座暗夜精灵首都的主要贸易和制造中心，坐落着各种工作室、专业训练师和一家热闹的旅店。该区域还接待外部代表，其中包括一个为中立组织银色黎明设立的使馆。",kw={"银色黎明","工匠","工匠区","达纳苏斯","泰达希尔","训练师"},ang={["faction:Alliance"]="联盟的游客会发现这里是达纳苏斯最受欢迎的区域之一，它在提供熟悉的商业物资、公会管理和住宿的同时，还有外来代表驻扎。",["race:NightElf"]="对于卡多雷而言，这里证明了他们的社会在泰达希尔上自给自足，将古老的工艺与新首都日常生活的需求融合在了一起。"},sec={{t="达纳苏斯的工匠之心",b="工匠区横跨这座树冠之城的北缘，聚集了维持达纳苏斯运转的各种贸易。木工、制皮师、炼金师和其他工匠在这里经营着他们的店铺，将古典的暗夜精灵工艺与实用技艺相结合。该区域还提供必要的社区设施，包括一家旅店、一位公会会长和公会注册商。桥梁将该平台与西侧的塞纳里奥区和南侧的战士区直接相连。"},{t="外部联系与被遗忘的知识",b="尽管卡多雷在历史上一直处于孤立状态，但工匠区却容纳了对外联系，最引人注目的是银色黎明建立的一座使馆，旨在与北方盟友协调对抗天灾军团。游览该区域各个工作室的游客偶尔也能发现散落的学术书籍，内容从上古之战的历史记载，到第二次战争的编年史，再到关于上古之神的深奥论述，应有尽有。"}},faq={{q="在工匠区可以找到哪些服务？",a="该区域容纳了城里大部分的商业专业训练师、商业物资商人、一家旅店以及公会注册服务。对于想要在达纳苏斯学习或练习实用技能的旅行者来说，这里是商业中心。",al={"工匠区服务","工匠区里有什么","达纳苏斯训练师"}},{q="为什么银色黎明会出现在工匠区？",a="银色黎明在该区域设有一座使馆，以便与暗夜精灵联络并招募援助以对抗天灾军团。他们的存在为西部的联盟军队与饱受战争蹂躏的洛丹伦土地之间架起了一座外交桥梁。",al={"达纳苏斯的银色黎明","银色黎明使馆","为什么银色黎明在这里"}},{q="如何到达工匠区？",a="该平台占据了达纳苏斯的北部。你可以通过从战士区向北或从塞纳里奥区向东的桥梁到达这里。",al={"如何前往工匠区","工匠区位置","寻找工匠区"}},{q="在工作室周围可以找到哪些值得注意的书籍？",a="学术书籍散落在各个工作室中，其中包括上古之战的历史、第二次战争后的局势，以及存放在银色黎明驻地内的一份关于上古之神的研究资料。",al={"工匠区书籍","达纳苏斯背景书籍","工匠区的书籍"}}},fx={["7384ca35"]={q="工匠区是什么地方？",a="工匠区是达纳苏斯北部一处繁忙的城区。达纳苏斯是泰达希尔上暗夜精灵的首都。这里是卡多雷主要的贸易和手工业中心，训练师、商人和工坊聚集在世界之树的枝叶下。旅客和市民可以在这里找到技艺娴熟的工匠、行会服务、舒适的旅店，以及由银色黎明设立的官方大使馆。",al={"工匠区是什么","达纳苏斯的工匠区","关于工匠区"}},ef9e89a7={q="为什么叫工匠区？",a="这个城区因其作为达纳苏斯工商业中心的职能而得名。这里有城内的专业技能训练师、补给商和手工艺作坊，因此成为暗夜精灵工匠、建造者和各行从业者聚集的地方。",al={"为什么叫工匠区","工匠区名称的含义","工匠区的名字"}},["1dc55189"]={q="工匠区危险吗？",a="不危险。工匠区是暗夜精灵首都达纳苏斯内安全的平民城区。这里由哨兵守护，也有当地工匠和银色黎明照看；对联盟成员而言，这里完全宁静，没有敌对威胁。",al={"工匠区安全吗","工匠区的危险","工匠区的威胁"}}},fp="19,341,30.508.0,31.454.0,51.235.0,58.239.0,41.160.0,53.199.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Crag of the Everliving",s="Crag of the Everliving 是位于哀嚎洞穴深处的一处葱郁的洞穴室。这里被茂密且受到腐蚀的植物群和捕食性植物生物所占据，是尖牙领主皮萨斯领主的领地。其高耸的上层区域庇护着这座岩穴以其命名的那尊古老存在。",h="Crag of the Everliving 是位于哀嚎洞穴深处的一处葱郁的洞穴室。这里被茂密且受到腐蚀的植物群和捕食性植物生物所占据，是尖牙领主皮萨斯领主的领地。其高耸的上层区域庇护着这座岩穴以其命名的那尊古老存在。",kw={"贫瘠之地","crag of the everliving","变异蹒跚者","尖牙德鲁伊","皮萨斯","瑟芬迪斯","永生者沃尔丹","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊来说，目睹 Crag of the Everliving 的景象是一次悲剧性的教训，因为纯粹的自然生命力和元素守护力量已经被扭曲成了梦魇的致命工具。",["profession:Herbalism"]="岩穴内不自然且葱郁的地下环境滋养了稀有的地下根茎和蘑菇，它们在潮湿、充满梦境气息的土壤中繁茂生长。"},sec={{t="腐蚀的林冠",b="虽然哀嚎洞穴的大部分区域都是由潮湿的地下岩石开凿而成，但 Crag of the Everliving 却因受到腐蚀纳拉雷克斯睡梦的梦魇影响，而爆发出了肆意生长的扭曲植被。高耸的苔藓平台和蜿蜒的小径上挤满了变异蹒跚者——潜伏在灌木丛中的活体植物巨怪。纳拉雷克斯堕落的弟子之一，皮萨斯领主，正看守着这处岩穴的中心区域，他已经抛弃了自己高贵的德鲁伊誓言，转而信奉尖牙德鲁伊的毒性仪式。"},{t="远古守护者",b="这处洞穴室的名字来源于永生者沃尔丹，这是一位居住在岩穴高处的巨大原始植物元素。受到笼罩着洞穴的翡翠梦魇腐蚀，永生者沃尔丹现在已不再是和平的自然守护者，而是成为了一道可怕的防线。在他高耸的身躯之后，潜伏着瑟芬迪斯领主，他是自封的尖牙领袖，负责监督该教派堕入蛇蝎般的疯狂。"}},faq={{q="这个区域的名字是从何而来？",a="这处洞穴室是以永生者沃尔丹的名字命名的，他是一位居住在岩穴最高台地上的古老而巨大的植物野兽。虽然他曾经是自然永恒活力的化身，但现在已经屈服于折磨着洞穴的梦魇。",al={"为什么叫 crag of the everliving","永生者名字由来","岩穴名称"}},{q="谁控制着洞穴的这一部分？",a="皮萨斯领主，主要的尖牙领袖之一，直接管辖着这处岩穴。在他上方的更高岩架上，潜伏着永生者沃尔丹和尖牙德鲁伊的首领瑟芬迪斯领主。",al={"谁在管理这里","岩穴首领","此处的尖牙领袖"}},{q="在 Crag of the Everliving 中通常能发现哪些生物？",a="这处岩穴到处都是变异蹒跚者——从受腐蚀的泉水中诞生的蹒跚植物恐怖——此外还有扭曲的蛇类和狂热的尖牙德鲁伊。",al={"岩穴中的怪物","岩穴敌人","这里有什么生物"}},{q="为什么植物能在如此深的地下茂盛生长？",a="暗夜精灵德鲁伊纳拉雷克斯利用地下泉水来恢复贫瘠之地。当他的仪式被翡翠梦魇捕获后，野生植物便疯狂生长，并扭曲成了敌对的畸形植被。",al={"为什么地下会有植物","为什么这里如此葱郁","受到腐蚀的植被"}}},fx={["6a6b08ee"]={q="Crag of the Everliving是什么地方？",a="Crag of the Everliving是哀嚎洞穴深处一处郁郁葱葱的地下洞窟。受腐化的自然能量滋养，这里植物繁茂、生长狂乱，岩架高耸。",al={"crag of the everliving是什么","crag of the everliving信息","关于crag of the everliving"}},cca8a755={q="Crag of the Everliving危险吗？",a="危险。这里是洞穴中最致命的区域之一。变异践踏者在过度生长的台地间徘徊，山崖由尖牙德鲁伊守卫，皮萨斯领头，瑟芬迪斯的巢穴也近在咫尺。",al={"crag of the everliving有多危险","crag of the everliving危险吗","crag of the everliving的威胁"}}},fp="22,298,18.491.0,20.427.0,34.261.0,38.196.0,64.170.0,47.219.0"}
P.entries["subzone:cragpool-lake"] = {n="峭壁湖",s="峭壁湖是一片隐匿于石爪山脉狂风峭壁之中的水域。在其深邃的水面之上，耸立着一座由荆棘谷地精建造的巨大木质结构。",h="峭壁湖是一片隐匿于石爪山脉狂风峭壁之中的水域。在其深邃的水面之上，耸立着一座由荆棘谷地精建造的巨大木质结构。",kw={"峭壁湖","格伦佐·扳鸣","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="峭壁湖周围的径流、木质平台和破坏行为如同石爪山脉上的一道丑陋伤疤，扭曲了当地的生态系统并驱逐了原生野生动物。",["profession:Engineering"]="峭壁湖上方高耸的木制脚手架和悬臂式机械，堪称地精工业实用主义的教科书式展示——建造迅速，负荷沉重，且对自然地形漠不关心。"},sec={{t="工业侵蚀",b="峭壁湖坐落在狂风峭壁之中，正下方就是荆棘谷地精建造的庞大伐木装置。一座巨大的木质结构横跨水面，是格伦佐·扳鸣监督整个山谷作业的视察点。荆棘谷地精的工人们占据着上方的平台。"}},faq={{q="悬在湖面上的大型木质结构是什么？",a="这是一座由荆棘谷地精建造的工业上层建筑，旨在管理他们在狂风峭壁的大规模伐木和采矿工作。它连接着横跨湖面的平台与重型机械。",al={"荆棘谷地精平台","峭壁湖脚手架","峭壁湖大桥"}},{q="谁在监督峭壁湖的作业？",a="荆棘谷地精的一名关键干事格伦佐·扳鸣将自己的视察点设在高耸的脚手架顶端，以监督整个狂风峭壁的森林砍伐和资源开采工作。",al={"谁在此领导荆棘谷地精","谁是这里的老大","格伦佐·扳鸣"}},{q="峭壁湖周围有哪些危险？",a="荆棘谷地精在湖面上的平台上进行作业。其武装工人的存在使得这处工业地点对入侵者来说十分危险。",al={"峭壁湖里有什么"}},{q="荆棘谷地精放弃峭壁湖了吗？",a="没有。荆棘谷地精的工人和格伦佐·扳鸣仍然占据着湖面上方的建筑。",al={"荆棘谷地精离开了吗","谁住在峭壁湖"}}},fx={["588e76b4"]={q="峭壁湖是什么地方？",a="峭壁湖是石爪山脉狂风峭壁中的一片小湖。湖面上矗立着一座庞大的高架木制建筑，由荆棘谷地精建造，用来支撑山谷里的伐木和挖掘设备。",al={"峭壁湖是什么","峭壁湖的背景","石爪山脉的峭壁湖"}},["686f269e"]={q="峭壁湖发生过什么事？",a="荆棘谷地精在峭壁湖上方建造了庞大的木制建筑，作为其在狂风峭壁行动的一部分。格雷佐·扳哨在平台上监督这项工作。",al={"峭壁湖的历史","峭壁湖发生过什么","峭壁湖的过去"}}},fp="13,184,23.344.0,59.212.0,45.193.0,36.128.0,48.90.0"}
P.entries["subzone:crossroads"] = {n="十字路口",s="十字路口是部落在卡利姆多中部交通往来的心脏，位于南北走向的黄金之路与从棘齿城通往石爪山脉的道路交汇处。这里是一个繁忙的贸易前哨站、军事补给点，也是往返于杜隆塔尔、莫高雷和北方前线的旅客们的中转枢纽。",h="十字路口是部落在卡利姆多中部交通往来的心脏，位于南北走向的黄金之路与从棘齿城通往石爪山脉的道路交汇处。这里是一个繁忙的贸易前哨站、军事补给点，也是往返于杜隆塔尔、莫高雷和北方前线的旅客们的中转枢纽。",kw={"贫瘠之地","十字路口","迪弗拉克","黄金之路","迅猛龙","棘齿城","石爪山脉","双足飞龙"},ang={["faction:Alliance"]="直接打击十字路口可以切断往返于奥格瑞玛、莫高雷和灰谷争议边界之间的部落增援部队的流动。",["faction:Horde"]="十字路口是你羽翼未丰的民族的核心试炼场和交通枢纽，连接着兽人、牛头人和巨魔的家园，同时统筹着卡利姆多各地的补给。"},sec={{t="稀树草原上的交通要道",b="十字路口名副其实，正处于黄金之路与从地精港口棘齿城通往石爪山脉的东西向路线的交汇处。尽管这里设施简陋，但该前哨站却是一个繁忙的区域枢纽。双足飞龙管理员、商人、铁匠和训练师们在岗哨塔下常驻。对于从杜隆塔尔或莫高雷出发的年轻战士来说，这个定居点往往是他们首次见证将新部落紧密联系在一起的庞大、多战线后勤体系的地方。"},{t="处于围攻之下的边境哨所",b="维护十字路口的秩序是一场永无休止的斗争。当地的野生生物——包括胆大到敢从岗哨塔掠夺军饷银币的平原迅猛龙——构成了持续的困扰，而鹰身人、野猪人和半人马部落则不断对周边地区施加压力。除了贫瘠之地本土的威胁外，该定居点靠近中立的棘齿城和饱受争议的灰谷，使其成为联盟侦察小队入侵的首要目标，导致其防御路障外经常发生小规模冲突。"}},faq={{q="为什么十字路口对部落如此重要？",a="它是卡利姆多中部主要交通动脉的锚点。每一位往返于杜隆塔尔、莫高雷、棘齿城、石爪山脉或灰谷的陆路旅客都必须经过或靠近十字路口，这使其成为后勤和增援的主要枢纽。",al={"为什么十字路口很重要","十字路口的作用","为什么十字路口意义重大"}},{q="谁在十字路口提供飞行运输服务？",a="迪弗拉克担任十字路口的飞行管理员，负责管理该定居点的双足飞龙栖息地，并将旅客直接送往卡利姆多各地的哨所，包括奥格瑞玛和雷霆崖。",al={"十字路口飞行管理员","这里谁提供双足飞龙","十字路口的飞行管理员"}},{q="为什么联盟如此频繁地袭击十字路口？",a="因为十字路口是部落交通的中心，且处于北部灰谷和东部中立港口棘齿城的易攻距离之内，联盟突袭队经常将该前哨站作为目标，以破坏部落的补给线。",al={"为什么联盟袭击十字路口","十字路口的联盟pvp","对十字路口的袭击"}},{q="前哨站的军饷银币发生了什么事？",a="贫瘠之地的迅猛龙袭击了十字路口的岗哨塔，并抢走了一批本应发给该定居点守卫的军饷银币，将它们散落到了周围的稀树草原上。",al={"十字路口军饷失窃","谁拿走了银币","十字路口的银币被盗"}}},fx={["2f66b0ff"]={q="十字路口是什么地方？",a="十字路口是贫瘠之地最大、位置最中心的部落聚居地。它围绕一座设防瞭望塔和旅店而建，是连接奥格瑞玛、雷霆崖、棘齿城以及石爪山脉和灰谷边境的主要驿站与补给站。对于穿行卡利姆多中部的旅人来说，这里是休息、贸易和区域防御的繁忙枢纽。",al={"十字路口是什么","贫瘠之地的十字路口","十字路口是什么城镇"}},["6d918d5a"]={q="为什么叫十字路口？",a="这个哨站的名字直接源于地理位置：它正好坐落在南北向的黄金之路与东西向道路的交汇处，后者从中立港口棘齿城通往石爪山脉。几乎所有穿越贫瘠之地的陆路旅程都会经过这里，因此聚居地自然围绕这处重要路口发展起来。",al={"为什么叫十字路口","十字路口名称的由来","十字路口的名字是怎么来的"}},["9b710adc"]={q="十字路口危险吗？",a="尽管内部有部落卫兵守护，这座聚居地仍时时面临危险。由于靠近灰谷和棘齿城，它常遭联盟突袭；周围的平原则有凶猛的迅猛龙、劫掠的 harpy，以及怀有敌意的野猪人部族肆虐，他们都企图切断部落至关重要的补给线。",al={"十字路口安全吗","十字路口的危险","十字路口面临的威胁"}}},fp="10,336,32.539.0,28.538.0,48.251.0,48.198.0,58.253.0,46.184.0"}
P.entries["subzone:crown-guard-tower"] = {n="皇冠哨塔",s="皇冠哨塔是一座位于东瘟疫之地南部的洛丹伦废弃侦察塔。在第三次战争期间，天灾军团入侵了洛丹伦并摧毁了它，自那以后，它破碎的石块便一直矗立在枯萎之地中。",h="皇冠哨塔是一座位于东瘟疫之地南部的洛丹伦废弃侦察塔。在第三次战争期间，天灾军团入侵了洛丹伦并摧毁了它，自那以后，它破碎的石块便一直矗立在枯萎之地中。",kw={"皇冠哨塔","东瘟疫之地","洛丹伦","天灾军团","侦察塔","瞭望塔"},ang={["faction:Alliance"]="对于联盟来说，这处损毁的皇冠哨塔提醒着人们，天灾军团曾以何等彻底的方式摧毁了洛丹伦王国的防线。"},sec={{t="坍塌的堡垒",b="皇冠哨塔曾是洛丹伦王国防御体系的一部分，也是一座监视东洛丹伦大地的侦察塔。当天灾军团横扫该王国时，这座塔被摧毁并化为废墟，成为了散落在如今东瘟疫之地上的众多倒塌塔楼之一。它焦黑的石块依然矗立在这片亡灵仍旧占据的土地上。"}},faq={{q="皇冠哨塔最初的用途是什么？",a="在第三次战争之前，它曾作为洛丹伦人类王国的区域军事瞭望塔和侦察前哨，负责守卫道路以防入侵。",al={"皇冠哨塔历史","为何而建","洛丹伦塔楼"}},{q="这座塔为什么会损毁？",a="这座塔是在天灾军团入侵洛丹伦期间被摧毁的，当时如潮水般的亡灵冲垮了王国的防线，将这座建筑夷为瓦砾。",al={"谁摧毁了皇冠哨塔","这里发生了什么"}}},fp="17,225,16.354.0,48.157.0,24.151.0"}
P.entries["subzone:crusader-outpost"] = {n="十字军前哨",s="十字军前哨是一座设在提瑞斯法林地东部崎岖山丘顶端的加固岗哨。这里驻扎着血色十字军的狂热成员，守卫着通往他们大本营——血色修道院的入口。从这一高处，十字军监视着道路上的往来，并随时准备击退任何被遗忘者的入侵。",h="十字军前哨是一座设在提瑞斯法林地东部崎岖山丘顶端的加固岗哨。这里驻扎着血色十字军的狂热成员，守卫着通往他们大本营——血色修道院的入口。从这一高处，十字军监视着道路上的往来，并随时准备击退任何被遗忘者的入侵。",kw={"瓦松队长","十字军前哨","血色十字军","血色修道院","侦察塔","提瑞斯法林地","岗哨"},ang={["faction:Horde"]="在提瑞斯法东部的山径中穿行需要谨慎，因为这座山丘上的血色哨兵会迅速攻击任何向修道院方向行进的人。",["race:Undead"]="这座岗哨坐落在被遗忘者领地的边缘，时刻提醒着人们，这些狂热的生者十字军在林地中仍然保留着自己的据点。"},sec={{t="提瑞斯法之眼",b="Built into the bluffs overlooking the eastern road, the Crusader Outpost serves as a primary early-warning station for the Scarlet Crusade. From their elevated tower, sentries watch over movement between Brill and the eastern reaches of Lordaeron, ensuring that wandering undead or scouting parties are spotted long before reaching the Monastery gates. The tower also grants the garrison tactical flanking capability against any force seeking to march up the valley toward their holy bastion."},{t="黑暗女王眼中的芒刺",b="在诸如瓦松队长这样的血色十字军军官指挥下，驻扎在此的守军时刻保持着警惕。他们眼中的周围森林并非被遗忘者的领土，而是被怪物从人类手中窃取的亵渎之地。对于效忠于幽暗城的旅行者来说，这座前哨站是一个随时可能遭遇伏击的地方，任何过于靠近悬崖的人都会遭到弩箭和净化之刃的攻击。"}},faq={{q="什么是十字军前哨？",a="这是一座由血色十字军占据的加固侦察塔，位于提瑞斯法林地东部。它监视着下方经过的道路，并保护着通往血色修道院的南部入口。",al={"这座塔是什么","提瑞斯法十字军前哨","血色岗哨"}},{q="谁控制着这座前哨站？",a="这座前哨站由在瓦松队长指挥下的血色十字军狂热者驻守。他们视所有亡灵为必须当场消灭的憎恶。",al={"谁拥有十字军前哨","谁住在这里","血色十字军前哨站"}},{q="为什么这座塔要建在这些山丘上？",a="其高处的地理位置提供了对提瑞斯法林地东部主干道的清晰视野。这使得十字军能够尽早发现被遗忘者的部队调动，并对任何试图进攻血色修道院的部队进行侧翼攻击。",al={"为什么建在这里","前哨位置","战术目的"}},{q="这里的守卫会攻击我吗？",a="是的。血色十字军认为所有外来者——尤其是被遗忘者及其部落盟友——都是必须用圣火净化其罪恶的敌人。",al={"十字军前哨有敌意吗","他们具有攻击性吗"}}},fx={a83c5de5={q="谁在负责十字军前哨？",a="前哨由瓦雄上尉指挥。他是驻扎于此的血色十字军军官，负责监督侦察，并抵御擅闯十字军领地的入侵者。",al={"谁领导十字军前哨","十字军前哨的上尉","十字军前哨的指挥官"}},b91596ef={q="为什么叫十字军前哨？",a="这座前哨直接以血色十字军命名。这个狂热的人类组织建造并维护了此处，将其作为预警哨站和防御侧翼，守卫附近的血色修道院。",al={"为什么叫十字军前哨","十字军前哨名称由来","十字军前哨为何得名"}}},fp="16,340,18.492.0,31.433.0,29.184.0,26.156.0,41.232.0,31.150.0"}
P.entries["subzone:crusader-s-armory"] = {n="Crusader's Armory",s="Crusader's Armory是一处位于Scarlet Monastery Armory侧厅内的防御性大厅。这里堆满了弹药、火药和炮弹，是守卫通往The Inner Sanctum路径的狂热者们的集结地。在它那道锁住的铁门后，便是Hall of Champions。",h="Crusader's Armory是一处位于Scarlet Monastery Armory侧厅内的防御性大厅。这里堆满了弹药、火药和炮弹，是守卫通往The Inner...",kw={"军械库","crusader's armory","火药","hall of champions","血色十字军钥匙","血色修道院"},ang={["faction:Horde"]="对于被遗忘者和部落来说，Crusader's Armory中的爆炸性物资直接威胁着提瑞斯法林地的边界和幽暗城的城门。",["profession:Blacksmithing"]="这里储备的武器和弹药展示了洛丹伦昔日铁匠的高超技艺和军事纪律，现在已全然转变为狂热的盲信。"},sec={{t="狂热者的军械库",b="Crusader's Armory坐落于Footman's Armory和宏伟的Hall of Champions之间，展示了血色十字军充分的军事准备。与外面的训练场不同，这些狭窄的石制走廊从地面到天花板堆满了易燃的火药箱、成堆的炮弹，以及随时准备击退入侵者的全副武装的十字军。血色十字军已将一处修道院建筑群转变为一座严阵以待的堡垒，将每一处可用的大厅都贡献给了全面战争的工具。军械库的最尽头矗立着一扇沉重的铁锁门，除非持有血色十字军钥匙，否则无法进入内部的密室。"}},faq={{q="Crusader's Armory是什么？",a="Crusader's Armory是血色修道院Armory侧厅的一个内部区域。它作为Footman's Armory和Hall of Champions之间的弹药库和防御走廊使用。",al={"crusaders armory","crusaders armory是什么","修道院军械库房间"}},{q="为什么尽头的门是锁着的？",a="Crusader's Armory尽头的门守卫着通往Hall of Champions和指挥官营地的通道。血色十字军对此处严加看守，必须使用在修道院Library侧厅中发现的血色十字军钥匙才能将其打开。",al={"军械库锁着的门","如何打开军械库门","血色十字军钥匙军械库"}},{q="为什么这里有这么多炮弹和火药箱？",a="血色十字军在整个提瑞斯法林地维持着活跃的围攻态势和炮兵防御。这座军械库是他们大炮和爆炸性军火的中央存储库，确保他们的部队在对抗天灾军团和被遗忘者时拥有充足的补给。",al={"军械库火药箱","修道院里的大炮","为什么有火药"}},{q="谁在守卫这个区域？",a="该大厅由经验丰富的血色十字军士兵防守，包括驻扎在弹药堆中的步兵、十字军和弓箭手，旨在阻止任何试图深入该建筑群的入侵者。",al={"军械库怪物","crusaders armory里有什么人"}}},fx={["2e345cd4"]={q="Crusader's Armory 危险吗？",a="这里极其危险。军械库里挤满了狂热的血色十字军战士，他们一发现入侵者就会发动攻击，把所有外来者都视为腐化势力或天灾军团的爪牙。更危险的是，整条走廊堆满了烈性炸药，包括易燃的火药桶和成堆的火炮弹药，供他们在提瑞斯法林地进行旷日持久的战争。",al={"crusader's armory 的危险","crusader's armory安全吗","crusader's armory 的威胁"}},["9c475e8e"]={q="为什么叫 Crusader's Armory？",a="这间军械室以驻守于此并在其中储存攻城装备的血色十字军战士命名。它位于血色修道院军事区深处，在步兵军械库之后，里面存放着火炮弹药、火药和武器，供血色十字军的老练战士使用，他们正准备进攻周边的瘟疫之地。",al={"为什么叫 crusader's armory","crusader's armory 名称由来","crusader's armory 的含义"}}},fp="17,293,15.621.0,30.194.0,34.252.0,60.275.0,21.196.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Crusader's Outpost",s="Crusader's Outpost 是一座由血色十字军驻守的防御型侦察塔，位于提瑞斯法林地西部。它毗邻索利丹农场，是十字军在整个洛丹伦最西端的据点。由于它距离血色十字军的主要堡垒过于遥远，导致其驻军被孤立在充满敌意的被遗忘者领地的中心地带。",h="Crusader's Outpost...",kw={"crusader's outpost","血色十字军","侦察塔","索利丹农场","提瑞斯法林地","提尔之手"},ang={["faction:Horde"]="这座前哨站是一个痛苦的提醒，展示了血色十字军疯狂地拒绝将提瑞斯法拱手让给被遗忘者及其部落盟友的决心。",["race:Undead"]="对于从丧钟镇走出的新晋被遗忘者来说，这座附近的塔楼以及守护它的血色狂热分子，构成了紧邻他们边境的直接生存威胁。"},sec={{t="一座孤独的瞭望塔",b="这座石塔栖身于丧钟镇北部的提瑞斯法西部丘陵之中，代表了血色十字军在洛丹伦最远的影响力范围。驻扎于此的守军与附近索利丹农场幸存的人类劳工协同工作，试图抵挡不断侵蚀的亡灵。从塔顶望去，守望者们监视着周围的南瓜田和林间小路，时刻警惕着游荡的天灾军团恶魔以及来自幽暗城的巡逻队。"},{t="身陷敌后的孤岛",b="坚守西部边境风险极高。由于切断了与血色修道院主要据点以及远在东方的提尔之手的联系，这座前哨站的十字军如果遭遇攻击，无法指望迅速获得增援。任何由聚集在提瑞斯法各处的被遗忘者部队发动的围攻，都意味着他们要么独自守住塔楼，要么在援军到来之前面临彻底的覆灭。"}},faq={{q="为什么血色十字军会出现在提瑞斯法西部的这里？",a="这座塔楼作为提瑞斯法西部丘陵沿线的预警哨所和防御工事。它负责保护索利丹农场的在世人类农民，并监视西部通道，以防范野性的天灾军团和被遗忘者的先遣侦察兵。",al={"血色十字军为什么在这里","提瑞斯法西部的血色十字军","十字军前哨站的目的"}},{q="如果前哨站遭到攻击，援军能抵达这里吗？",a="很难。该前哨站是洛丹伦最西端的血色十字军据点。他们的主要堡垒位于遥远的东方，即血色修道院和提尔之手，这使得一旦被遗忘者部队包围，该驻军将彻底陷入孤立无援的境地。",al={"血色十字军能否增援","前哨站援助","援军距离多远"}},{q="这座塔楼与索利丹农场之间是什么关系？",a="十字军与索利丹农场剩余的人类农民结成了同盟。士兵们为他们提供抵御行尸走肉的保护，以换取食物补给，并在洛丹伦的边缘地带获得一个忠诚的后勤据点。",al={"与索利丹农场的联系","为什么十字军在农场","十字军与农民"}},{q="该地区还有其他类似的塔楼吗？",a="是的。这座塔楼是血色十字军在提瑞斯法林地建立的四座类似的 Crusader's Outpost 之一，用于侦察和巡逻周边土地。",al={"其他十字军前哨站","更多的血色塔楼"}}},fx={["5e123392"]={q="Crusader's Outpost 是什么地方？",a="Crusader's Outpost 是提瑞斯法林地西部的一座防御塔楼，位于丧钟镇以北不远处。它是血色十字军在洛丹伦最西端的据点，作为前线哨站抵御周边被遗忘者和天灾军团的威胁，并与附近的盟友索利丹农场一道警戒这片区域。",al={"crusader's outpost 是什么","提瑞斯法的 crusader's outpost","提瑞斯法西部的血色前哨"}},["74d073f8"]={q="谁控制着 Crusader's Outpost？",a="这座塔楼由血色十字军的狂热成员驻守和管理。这些哨兵与十字军远离东部据点，在此维持着一支孤立的守备力量，并与索利丹农场中同情他们的人类农民密切合作，保护提瑞斯法地区这片小小的领地。",al={"谁住在 crusader's outpost","crusader's outpost 的居民","谁管理 crusader's outpost"}},["30c5615e"]={q="Crusader's Outpost 危险吗？",a="是的，如果你是外来者或亡灵，这里尤其危险。血色十字军认为几乎所有不属于他们的人都受到了污染或腐化，一发现入侵者就会发动攻击。这里的十字军深入敌境，长期处于高度戒备状态，因此接近前哨十分危险。",al={"crusader's outpost 危险吗","十字军前哨的危险","这里的十字军有敌意吗"}},["52f2bf53"]={q="为什么叫 Crusader's Outpost？",a="这个名字直接源自建造并驻守这座侦察塔楼的宗教军事组织——血色十字军。它是提瑞斯法林地上数座此类前哨之一，用于巩固他们对抗天灾军团和被遗忘者的狂热圣战。",al={"为什么取名 crusader's outpost","crusader's outpost 名称由来"}}},fp="18,343,19.497.0,27.411.0,68.253.0,58.229.0,66.221.0,47.160.0"}
P.entries["subzone:crypt-badlands"] = {n="Crypt (Badlands)",s="在荒芜之地尘土飞扬的山丘高处，隐匿着一座被称为“墓穴”的偏僻地下陵墓。内部安息着一位古代战士的静默遗骸：一具身披盔甲的骸骨端坐在石王座上，身旁散落着骨灰瓮、宝箱和一把巨大的遗物之剑。",h="在荒芜之地尘土飞扬的山丘高处，隐匿着一座被称为“墓穴”的偏僻地下陵墓。内部安息着一位古代战士的静默遗骸：一具身披盔甲的骸骨端坐在石王座上，身旁散落着骨灰瓮、宝箱和一把巨大的遗物之剑。",kw={"荒芜之地","野蛮人国王","墓穴","铁趾挖掘场","剑","王座"},ang={["class:Warrior"]="对于战士们来说，这座墓穴提供了一个机会，让他们能在一个身穿板甲、至死仍紧握强大兵刃的陨落冠军面前表达片刻的敬意。",["race:Dwarf"]="虽然它坐落在活跃的矮人考古挖掘场附近，但其建筑风格和骸骨王座所指向的奥秘，显然早于铁炉堡近期的挖掘工作。"},sec={{t="野蛮人国王之墓",b="这座荒芜之地墓穴位于铁趾挖掘场的东南方，沿着一条沿山坡向上延伸的无名土路即可到达，过往的行人很容易错过它。在黑暗的石室深处，一具身着盔甲的骸骨端坐在王座之上。遗骸旁倚靠着野蛮人国王之剑，周围散落着零星的尸骨、骨灰瓮和被遗忘的宝箱。尽管矿工和冒险者经常出没于周边的沟壑，搜寻着矮人的遗迹和财宝，但这位坐姿君主的真实起源和历史，依然是埋没在干旱荒原中的未解之谜。"}},faq={{q="墓穴位于荒芜之地的什么地方？",a="入口位于铁趾挖掘场的东南方。若要到达那里，请沿着一条蜿蜒向上、通往挖掘场上方山脊的无名小径前行。",al={"荒芜之地墓穴位置","如何找到荒芜之地墓穴","荒芜之地墓穴入口"}},{q="王座上的那具骸骨是谁？",a="这具披甲骸骨通常被称为野蛮人国王。没有任何现存的当地文献记载过他的统治或身份，使他成为了荒芜之地那个早已被遗忘的远古时代留下的一件神秘遗物。",al={"王座上的骸骨","谁是野蛮人国王","墓穴骸骨身份"}},{q="王座旁的那把剑是什么？",a="它被称为野蛮人国王之剑。它静静地靠在骸骨统治者的身旁，作为庄严肃穆的墓碑，见证着他那充满战火的过去。",al={"野蛮人国王之剑","墓穴之剑","荒芜之地王座之剑"}},{q="有与这座墓穴相关的任务吗？",a="没有指引冒险者前往该墓穴的标准任务。它主要作为一个令人毛骨悚然的隐藏发现，供那些搜寻悬崖的旅行者探寻。",al={"荒芜之地墓穴任务","为什么要前往荒芜之地墓穴"}}},fp="16,266,30.542.0,43.147.0,49.202.0,37.162.0,48.151.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Crypt (Stromgarde Keep)",s="在激流堡的废墟深处坐落着皇家墓穴，它位于密室教堂之后，处于幸存的激流堡保卫者所掌控的核心区域。这里安放着已故国王索拉斯·托尔贝恩的陵墓以及他王朝的祖传宝藏。在加林王子和忠诚的看守者的严密守卫下，这处拱顶在破碎的王国中依然是一片彰显皇家荣耀的圣所。",h="在激流堡的废墟深处坐落着皇家墓穴，它位于密室教堂之后，处于幸存的激流堡保卫者所掌控的核心区域。这里安放着已故国王索拉斯·托尔贝恩的陵墓以及他王朝的祖传宝藏。在加林王子和忠诚的看守者的严密守卫下，这处拱顶在破碎的王国中依然...",kw={"阿拉希","墓穴","加林","密室","激流堡","索拉斯","托尔卡拉","托尔贝恩"},ang={["faction:Alliance"]="激流堡的皇家墓穴是联盟在阿拉希的最后堡垒之一，它顽强地抵御着强盗、食人魔和部落的侵袭。",["race:Human"]="对于联盟的人类而言，这座陵墓代表了七大王国之一的激流堡那悲剧性的衰落，也是联盟最勇猛的战时领袖之一的神圣安息地。"},sec={{t="索拉斯·托尔贝恩之墓",b="这处地下墓穴隐藏在激流堡密室的下方，是索拉斯·托尔贝恩国王的最终安息之所，这位武力非凡的君王曾带领激流堡度过了第二次战争。尽管这座城市遭受了毁灭性的打击——被辛迪加盗贼和巨石食人魔瓜分——但留守的激流堡民兵依然死死守卫着这个区域。加林·托尔贝恩王子亲自与尽职的皇家看守者们一同看管着这些墓穴，确保他父亲的遗体和遗产不会受到外界拾荒者和敌人的侵扰。"},{t="托尔卡拉之库",b="除了安放皇家逝者外，这处墓穴还守护着托尔贝恩家族珍贵的文物。其中最重要的圣物就是托尔卡拉，这把古老的符文巨剑是在几个世纪前为屠杀巨魔而锻造的。在阿拉里克、内夫林和韦斯顿等发誓守护的看守者的保护下，这间墓室及其宝藏被强大的防护措施所封存。加林和他的忠诚部下不懈地守护着陵墓，因为他们深知阿拉希各处的敌对派系和仇视人类的巨魔都觊觎着这把利刃的古老力量。"}},faq={{q="谁被埋葬在墓穴中？",a="激流堡已故的统治者，索拉斯·托尔贝恩国王安葬于此。他的儿子，加林·托尔贝恩王子，在这座荒废的城市中守卫着陵墓。",al={"谁葬在这里","这是谁的陵墓","墓穴 陵墓"}},{q="什么是托尔卡拉？",a="托尔卡拉是托尔贝恩家族的古老传家宝剑。它的名字在古代语言中的意思是“巨魔杀手”，最初是为了对抗阿拉希盆地的森林巨魔而锻造的。",al={"托尔卡拉之剑","托尔贝恩之剑","什么是托尔卡拉"}},{q="谁在守卫墓穴？",a="墓穴由加林·托尔贝恩王子和激流堡的皇家看守者（包括阿拉里克、内夫林和韦斯顿）共同保卫。他们守护着墓室，抵御辛迪加窃贼和巨石食人魔的入侵。",al={"墓穴守卫","谁在保卫墓穴","看守者"}},{q="墓穴位于何处？",a="它位于阿拉希高地的激流堡内，坐落在密室区域的深处，就在城堡教堂的后面，处于激流堡忠诚派依然掌控的区域内。",al={"墓穴位置","如何找到墓穴","激流堡墓穴在哪"}}},fp="23,394,28.570.0,23.518.0,27.153.0,19.219.0,21.212.0,27.176.0"}
P.entries["subzone:crystal-lake"] = {n="水晶湖",s="水晶湖是位于艾尔文森林中心地带、闪金镇以东的一片水域。这里曾经是一个宁静的地方，但现在其湖岸已被好斗的鱼人占领，成为当地村民和过往旅客经常面临的危险之地。",h="水晶湖是位于艾尔文森林中心地带、闪金镇以东的一片水域。这里曾经是一个宁静的地方，但现在其湖岸已被好斗的鱼人占领，成为当地村民和过往旅客经常面临的危险之地。",kw={"水晶海藻","水晶湖","艾尔文","闪金镇","鱼人","威廉·匹斯特"},ang={["faction:Alliance"]="鱼人在闪金镇附近的泛滥，凸显了王国在保卫核心领土方面的兵力是何等捉襟见肘。",["profession:Herbalism"]="淡水浅滩中生长着水晶海藻，不过它主要是从栖息在湖底并采集海藻的鱼人身上获得的。"},sec={{t="动荡的湖岸",b="水晶湖距离Lion's Pride Inn仅几步之遥，本应是一处宁静的乡村休憩之所，却饱受危险野生生物的困扰。成群的淡水鱼人占据了湖岸和浅滩，袭击任何过于靠近的人。当地的炼金术师威廉·匹斯特经常雇佣过往的冒险者前往水边，指引他们击败这些生物，并收集它们身上携带的水晶海藻，用于他的实验性药剂。"}},faq={{q="水晶湖在哪里？",a="水晶湖位于艾尔文森林中心地带，闪金镇的东侧，从村庄郊区步行即可轻松抵达。",al={"水晶湖位置","水晶湖在哪里","寻找水晶湖"}},{q="为什么鱼人会聚集在水晶湖？",a="和艾尔文森林中的许多水道一样，水晶湖为鱼人提供了筑巢和觅食的天然淡水栖息地。由于暴风城当地卫兵兵力吃紧，靠近闪金镇的鱼人数量激增。",al={"为什么鱼人在水晶湖","闪金镇的鱼人问题","水晶湖鱼人"}},{q="冒险者需要从水晶湖获得什么？",a="威廉·匹斯特是一位在闪金镇的Lion's Pride Inn工作的药剂师，他雇佣冒险者去猎杀湖岸边的鱼人，以此收集他制造隐形药水所需的水晶海藻。",al={"威廉·匹斯特水晶湖","水晶海藻任务水晶湖","艾尔文森林隐形药水"}}},fx={["18711dcc"]={q="水晶湖是什么地方？",a="水晶湖是艾尔文森林腹地的一片淡水湖，位于闪金镇正东面。这里或许曾是宁静的饮水之地，但近来平静的湖面已成了附近旅人和居民麻烦不断的根源。",al={"水晶湖是什么","艾尔文的水晶湖","水晶湖的背景"}},c07536f5={q="水晶湖危险吗？",a="是的，对粗心或缺乏经验的旅人来说，这里可能致命。湖岸和浅水区遍布富有攻击性的鱼人，任何人只要走得太靠近水边，就会遭到攻击。",al={"水晶湖有多危险","水晶湖安全吗","水晶湖的威胁"}}},fp="12,248,16.478.0,30.154.0,41.227.0,43.203.0"}
P.entries["subzone:crystal-shore"] = {n="水晶海岸",s="水晶海岸是位于荆棘谷东南边缘的一片沙质海岸线，受南海波涛的冲刷。这片沙滩隐匿在陡峭的海岸悬崖之下，位于古老的阿博拉兹废墟以南，与哈圭罗岛隔水相望。",h="水晶海岸是位于荆棘谷东南边缘的一片沙质海岸线，受南海波涛的冲刷。这片沙滩隐匿在陡峭的海岸悬崖之下，位于古老的阿博拉兹废墟以南，与哈圭罗岛隔水相望。",kw={"水晶海岸","哈圭罗岛","薄雾山谷","阿博拉兹废墟","南海","荆棘谷","蛮荒海岸"},sec={{t="一片与世隔绝的海岸带",b="水晶海岸沿着荆棘谷的东南边界延伸，构成了茂密的热带内陆与开阔的南海海域之间的一道天然边界。这片沙滩本身被陡峭的山脊与内陆丛林隔开，只留下了几条崎岖的通道，供那些试图在海岸与更深处的薄雾山谷荒野之间往来的旅人通行。北面是阿博拉兹废墟那摇摇欲坠的巨魔建筑，而蛮荒海岸则沿着海岬的南侧曲线延伸。由于其地理位置，这里成为了一处安静且饱受风吹的边缘地带，远离喧嚣的藏宝海湾码头。"}},faq={{q="水晶海岸位于何处？",a="水晶海岸坐落在荆棘谷的最东南海岸。它沿着面朝南海的海域延伸，位于阿博拉兹废墟以南，蛮荒海岸的东北方向。",al={"水晶海岸位置","水晶海岸在哪里","水晶海岸地图"}},{q="如何从内陆前往水晶海岸？",a="一道陡峭的山脊将沙滩与内陆丛林隔开。不过，高耸的悬崖间有几条狭窄的天然通道，其中包括一条直接通往薄雾山谷的小径。",al={"如何到达水晶海岸","去往水晶海岸的路径","抵达水晶海岸"}},{q="附近有哪些地标？",a="在海岸北面矗立着古老的阿博拉兹废墟，西南方向隔着水道则是哈圭罗岛。沿海岸线向南更远的地方是蛮荒海岸。",al={"水晶海岸附近的地标","水晶海岸附近有什么"}},{q="有任何阵营在水晶海岸定居吗？",a="没有任何正式阵营在水晶海岸设有城镇或定居点。这里依然是一片未经开发的海岸，被原生野生动物、北面的古代巨魔废墟以及南海的拍岸浪潮所占据。",al={"谁居住在水晶海岸","水晶海岸定居点","水晶海岸城镇"}}},fp="13,270,24.627.0,35.208.0,48.186.0,26.187.0,44.218.0"}
P.entries["subzone:crystal-vale"] = {n="水晶谷",s="水晶谷坐落于希利苏斯的西北远角，是一处偏僻的峡谷，满是参差不齐的矿物尖塔和盘旋的元素力量。土元素和风元素徘徊在岩石平原上，守护着丰富的矿脉。这里也是强大的召唤魔法之地，与远古的元素领主有着深厚的联系。",h="水晶谷坐落于希利苏斯的西北远角，是一处偏僻的峡谷，满是参差不齐的矿物尖塔和盘旋的元素力量。土元素和风元素徘徊在岩石平原上，守护着丰富的矿脉。这里也是强大的召唤魔法之地，与远古的元素领主有着深厚的联系。",kw={"水晶谷","元素生物","德米提恩","暮光营地废墟","希利苏斯","瑟银","thunderaan"},ang={["class:Shaman"]="此处土元素与风元素灵魂之间产生的剧烈摩擦，有力地提醒着人们希利苏斯各地那些不受束缚的元素所带来的混乱。",["profession:Mining"]="水晶谷崎岖的边缘和峡谷岩壁据说是富瑟银矿脉的所在地，使其成为高等级矿工眼中一处有利可图但也充满危险的目的地。"},sec={{t="石与风的交汇处",b="水晶谷与希利苏斯南部的贫瘠沙漠截然不同。盆地四周环绕着陡峭的悬崖，布满了闪烁的晶体结构、徘徊的土元素和咆哮的活体旋风。丰富的瑟银矿藏偶尔会吸引胆大的勘探者，但这里绝非安宁之地。此地的元素生物对入侵者有着天然的敌意，它们守护着这片仿佛沉浸在艾泽拉斯原始冲突中的领域。"},{t="逐风者的沉睡",b="除了矿物和原生灵魂外，水晶谷对远古的元素力量而言意义深远。德米提恩在此徘徊，守护着逐风者桑德兰王子的秘密。那些收集了这位陨落王子断裂的元素束缚以及最稀有锻造金属的勇士们会被指引至此山谷，被囚禁的风元素领主可以从束缚中被唤出，并接受公开的挑战。"}},faq={{q="水晶谷位于何处？",a="水晶谷位于希利苏斯的西北边缘，坐落在接壤沙漠的山缘之间。",al={"水晶谷在哪里","水晶谷地图","水晶谷位置"}},{q="山谷里居住着什么生物？",a="峡谷里主要栖息着具有攻击性的风元素和土元素，它们在矿层周围漂浮和踩踏。",al={"水晶谷怪物","水晶谷有什么生物","水晶谷的元素生物"}},{q="德米提恩是谁，他为什么在这里？",a="德米提恩是一位居住在山谷中的隐士，掌握着关于桑德兰王子的深奥知识。他会帮助那些有能力重聚逐风者束缚并召唤这位元素王子的勇士。",al={"德米提恩是谁","水晶谷的德米提恩","德米提恩位置"}},{q="什么是暮光营地废墟？",a="那是山谷内一座暮光之锤营地的残骸，已被占据峡谷的狂暴元素居民摧毁并夷为平地。",al={"水晶谷的暮光营地废墟","山谷里的暮光营地","被摧毁的暮光营地"}}},fp="12,325,30.472.0,29.437.1,34.134.0,35.122.0,45.208.0,34.148.0"}
P.entries["subzone:crystalvein-mine"] = {n="水晶矿洞",s="水晶矿洞是位于荆棘谷中部的一个洞穴，毗邻古老的祖玛维废墟。洞穴中蕴藏着宝贵的“歌唱水晶”，但好斗的本土蛇怪已经完全占据了此地，将那些意图采矿的人变成了坚硬的石头。",h="水晶矿洞是位于荆棘谷中部的一个洞穴，毗邻古老的祖玛维废墟。洞穴中蕴藏着宝贵的“歌唱水晶”，但好斗的本土蛇怪已经完全占据了此地，将那些意图采矿的人变成了坚硬的石头。",kw={"蛇怪","克兰克·菲兹巴布","水晶矿洞","歌唱水晶","荆棘谷","荆棘谷地精","祖玛维"},ang={["profession:Mining"]="受歌唱水晶的诱惑而来的矿工必须小心行事，因为洞穴中本土蛇怪的数量使得在这里勘探成为荆棘谷最危险的活动之一。"},sec={{t="一个诱人的陷阱",b="水晶矿洞隐藏在祖玛维附近的丛林丘陵中，拥有稀有的歌唱水晶矿藏。这是一种独特的矿石，在南部贸易港口能卖出高价。在巨额利润的诱惑下，荆棘谷地精将目光投向了这些矿脉。然而，矿洞的原住民对生意来说是灾难性的。当地的蛇怪以这些奇特的晶体为食，这硬化了它们的鳞片，使它们变得异常致命。在洞口外，巨魔和人类的石化雕像矗立在那里，无声地证明了荆棘谷地精远征队的失败。"}},faq={{q="水晶矿洞为何具有价值？",a="这座矿洞储藏着稀有的“歌唱水晶”，这是一种仅能在荆棘谷发现的暴利矿石。克兰克·菲兹巴布等地精因其声学价值和货币价值而对其趋之若鹜，驱使勘探者们冒险进入危险的洞穴。",al={"为什么水晶矿洞很重要","水晶矿洞里有什么","歌唱水晶"}},{q="为什么矿洞外有石像？",a="这些雕像是倒霉的当地巨魔和荆棘谷地精劳工被石化后的残骸。居住在这里的蛇怪以这些共鸣晶体为食，增强了它们石质的皮，并将任何愚蠢到侵入它们觅食地的人变成石头。",al={"水晶矿洞里的石化者","水晶矿洞里的结晶巨魔","荆棘谷的石体"}},{q="谁目前控制着水晶矿洞？",a="尽管荆棘谷地精声称拥有开采该洞穴的权利，但他们实际上并未占领此处。蛇怪的泛滥非常严重，以至于地精们无法在深处建立有效的采矿作业。",al={"谁拥有水晶矿洞","水晶矿洞阵营","水晶矿洞的荆棘谷地精"}}},fp="16,265,16.596.0,37.239.0,45.252.0,40.224.0"}
P.entries["subzone:cut-throat-alley"] = {n="Cut-Throat Alley",s="Cut-Throat Alley是暴风城中一个僻静且无人居住的角落，藏在运河商店后方。它位于Dwarven District边缘一家名为Shady Lady的店面后方，由一个安静的庭院和一处与城市日常人流隔绝的空宅组成。",h="Cut-Throat Alley是暴风城中一个僻静且无人居住的角落，藏在运河商店后方。它位于Dwarven District边缘一家名为Shady Lady的店面后方，由一个安静的庭院和一处与城市日常人流隔绝的空宅组成。",kw={"cathedral square","cut-throat alley","dwarven district","秘密小巷","shady lady","暴风城运河"},ang={["class:Rogue"]="只能通过一家阴暗运河商店的后门进入，这个无人巡逻的死胡同为那些希望避开暴风城卫兵视线的人提供了一个理想的藏身处。"},sec={{t="一个僻静的角落",b="Cut-Throat Alley是暴风城最安静、最隐秘的角落之一。虽然在地图上它被划归为Dwarven District，但这里既没有该区喧嚣的熔炉之火，也没有浓重的煤烟。这条小巷无法通过城市的主要街道进入；唯一的通道是穿过位于Cathedral Square南侧桥边运河旁的小店Shady Lady。店门外是一个铺设过的小型死胡同，堆放着货物箱、废弃的木桶，还有一栋无人居住的两层住宅。这里完全避开了过往的卫兵和普通市民，在首都的喧嚣中显得格外寂静。"}},faq={{q="如何前往Cut-Throat Alley？",a="前往Dwarven District边缘的运河岸边，就在通往Cathedral Square的人行桥南侧。寻找一家名为Shady Lady的商店。径直穿过这家店的后门，就能直接进入这条隐蔽的小巷。",al={"寻找cut throat alley","cut throat alley位置","cut-throat alley在哪里","如何进入cut-throat alley"}},{q="为什么地图将此地标为Dwarven District？",a="这条小巷位于Dwarven District的范围内，通常被视为该区的一部分，尽管它并没有该区的烟雾，也不与该区的街道相连。唯一的入口是运河岸边的Shady Lady。",al={"小地图dwarven district","为什么显示为dwarven district","cut-throat alley名称错误"}},{q="有人住在Cut-Throat Alley吗？",a="没有。这条小巷及其唯一的两层住宅完全被废弃了。除了堆放的货物箱和空木桶外，这里没有居民、店主或驻守的城市卫兵。",al={"cut throat alley的npc","谁住在cut throat alley","cut throat alley的空房子"}},{q="Cut-Throat Alley里有什么任务吗？",a="没有任务或市政指派会将玩家引向这条小巷。它仅仅是首都中一个被忽视的僻静背景地。",al={"cut throat alley的任务","cut throat alley剧情"}}},fx={["636e4761"]={q="Cut-Throat Alley 是什么地方？",a="Cut-Throat Alley 是一条隐蔽而无人居住的后巷，藏在暴风城运河沿岸的阴暗女士旅店后方。虽然官方上被视为矮人区的一部分，但它与城区其他地方隔绝，没有附近街区那种浓重的烟雾和喧闹。巷中散落着一些箱子和木桶，还有一栋无人居住的两层住宅。",al={"cut-throat alley 是什么","cut-throat alley 的背景","关于 cut-throat alley"}},e98a554d={q="Cut-Throat Alley 危险吗？",a="尽管名字听起来阴森，这条巷子非常平静，没有任何敌对威胁。这里既没有四处游荡的杀手，也没有潜伏的扒手，只有一处空院子、安静的箱子，以及一栋远离城卫巡逻路线的空置宅邸。",al={"cut-throat alley 危险吗","cut-throat alley 有敌人吗","cut-throat alley 的危险"}}},fp="16,287,15.663.0,35.264.0,48.239.0,37.189.0,41.146.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="达比雷农场",s="达比雷农场是位于阿拉希高地北部的一个联盟阵营乡村定居点。在这个被第三次战争摧毁，并充斥着辛迪加不法之徒和枯木巨魔的国度里，这片庄园仍是斯托姆加德公民在肯娜塔·达比雷领导下的一座顽强堡垒。",h="达比雷农场是位于阿拉希高地北部的一个联盟阵营乡村定居点。在这个被第三次战争摧毁，并充斥着辛迪加不法之徒和枯木巨魔的国度里，这片庄园仍是斯托姆加德公民在肯娜塔·达比雷领导下的一座顽强堡垒。",kw={"阿拉希","卡洛","达比雷","法德尔","农场","肯娜塔","马塞尔","斯托姆加德"},ang={["faction:Alliance"]="对于联盟旅行者来说，这座农场是一个罕见且令人欣慰的提醒，告诉人们即便身处四面楚歌的境地，斯托姆加德的人民依然在为自己的土地生存和战斗。",["race:Undead"]="对于被遗忘者来说，这处繁荣的家园简直是个令人恼火的讽刺，里面的活人囤积着从第三次战争中死难家族那里抢来的财物。"},sec={{t="高地堡垒",b="达比雷农场坐落在阿拉希高地的北部原野上，是破碎的斯托姆加德王国中为数不多仍在运作的人类家园之一。农场由肯娜塔·达比雷拥有，她与两个儿子法德尔和马塞尔共同经营，并由当地的一支家族民兵武装拼死保卫。这片农场被凶猛的野生动物、伺机而动的强盗以及北部近在咫尺的被遗忘者势力所包围，成为了人类在这一荒芜之地顽强生存的象征。"},{t="苦涩仇怨",b="在阿拉希，生存往往伴随着苦涩的仇怨。这座庄园招致了被遗忘者的强烈愤怒，尤其是曾在大战中失去家园和亲人的前贵族女士吉娜维·卡洛。卡洛指责达比雷家族在瘟疫肆虐的混乱时期劫掠了她家族的珍贵传家宝，使这座原本简朴的农场成为了部落雇佣兵寻求清算旧日北部恩怨的目标。"}},faq={{q="谁住在达比雷农场？",a="这座农场是肯娜塔·达比雷和她的儿子法德尔与马塞尔的家。他们是忠于联盟的斯托姆加德人类公民，并受到当地民兵誓死保护。",al={"谁拥有达比雷农场","达比雷家族","肯娜塔·达比雷"}},{q="为什么部落要针对这个农场？",a="一名叫吉娜维·卡洛的被遗忘者对达比雷一家怀恨在心。她声称在第三次战争中她的亲人罹难时，达比雷一家洗劫了她家族的庄园，并抢走了她幸存的传家宝。",al={"为什么要杀达比雷","吉娜维·卡洛任务","部落达比雷任务"}},{q="达比雷农场属于斯托姆加德吗？",a="是的。达比雷一家视自己为斯托姆加德王国的臣民和广大联盟的盟友，尽管南方的主城已经陷落，他们依然坚守于此。",al={"达比雷是联盟吗","斯托姆加德农场"}},{q="农场周围有哪些威胁？",a="农场所处的位置十分危险，紧邻充满敌意的高地掠食者、四处游荡的辛迪加割喉者，以及从北方边境步步紧逼的被遗忘者部队。",al={"达比雷的威胁","达比雷农场附近的危险"}}},fp="19,277,26.482.0,12.437.1,33.168.0,37.215.0,42.184.0,36.162.0"}
P.entries["subzone:dagger-hills"] = {n="匕首岭",s="匕首岭是一道横跨西部荒野南部、紧邻荒废的月溪镇后方的崎岖山脊。这片岩石高地长期被皇室所忽视，成了不法之徒、强盗和潜伏的恐怖生物的聚集地，威胁着周边的平原。",h="匕首岭是一道横跨西部荒野南部、紧邻荒废的月溪镇后方的崎岖山脊。这片岩石高地长期被皇室所忽视，成了不法之徒、强盗和潜伏的恐怖生物的聚集地，威胁着周边的平原。",kw={"匕首岭","迪菲亚潜行者","葛瑞姆·雷酒","莱普瑞瑟斯","月溪镇","雷酒","西部荒野"},ang={["faction:Alliance"]="这些山丘代表了西部荒野南部法律的彻底崩溃，格里安·斯托曼的人民民兵必须在此奋战，以夺回因暴风城缺席而丧失的领土。",["race:Dwarf"]="葛瑞姆·雷酒独自一人守在这片暴露的山脊上，展现了矮人酿酒师那种为了寻找不受干扰的空间来完善技艺而展现出的顽固执着。"},sec={{t="强盗的避风港",b="匕首岭高耸于月溪镇破败的定居点之上，构成了西部荒野南部崎岖的边缘。由于暴风城不再派遣官方巡逻队，这片干旱的高地已成为迪菲亚潜行者的天然堡垒。指节火枪手、探路者和强盗潜伏在岩脊与灌木丛中，伏击毫无防备的旅行者，并监视着通往下方据点的道路。"},{t="山脊上的阴影",b="除了凡人罪犯外，匕首岭在夜幕掩盖下还带有一种诡异的名声。每当夕阳西下，人们就会看到令人不安的幽灵——游荡的食尸鬼莱普瑞瑟斯在荒凉的高地上徘徊。除了游荡的罪犯和徘徊的亡灵，唯一愿意冒着风险待在这道山脊上的居民就是葛瑞姆·雷酒，一位矮人酿酒师。他无视附近的危险，在这片崎岖的荒野中搭建起了他的蒸馏设备。"}},faq={{q="匕首岭在哪里？",a="匕首岭构成了西部荒野南部高耸的岩石边界，位于被遗弃的月溪镇正后方。",al={"匕首岭位置","匕首岭在哪里","如何前往匕首岭"}},{q="谁控制着匕首岭？",a="迪菲亚潜行者在这道山脊上保持着强大的势力，派遣强盗、探路者和指节火枪手守卫着南部丘陵。",al={"匕首岭迪菲亚潜行者","谁住在匕首岭","匕首岭的敌人"}},{q="为什么会有矮人在这里酿酒？",a="葛瑞姆·雷酒在这片寂寥的高地上建立了他的酿酒厂，为了酿造出烈性矮人啤酒，他不惜冒着被强盗和野兽袭击的风险，只为了那口好酒。",al={"葛瑞姆·雷酒 西部荒野","匕首岭的矮人","葛瑞姆·雷酒背景故事"}},{q="莱普瑞瑟斯是什么？",a="莱普瑞瑟斯是一只臭名昭著的食尸鬼，经常在匕首岭的岩壁间徘徊，令任何在黑暗中不幸撞见它的旅行者或强盗心惊胆战。",al={"莱普瑞瑟斯刷新","匕首岭的食尸鬼","匕首岭的亡灵"}}},fx={["7ebc9df0"]={q="匕首岭有什么危险？",a="这片崎岖的山脊就在月溪镇后方，盘踞着全副武装的迪菲亚潜行者盗贼、拦路强盗和拳匪，他们利用高处监视低地。除了这些强盗巡逻队，令人不安的亡灵食尸鬼莱普利瑟斯也会在荒凉的高地上出没，独自穿行于这些山岩间十分危险。",al={"匕首岭的危险","匕首岭危险吗","匕首岭有什么危险"}}},fp="12,278,14.431.0,20.444.0,35.130.0,30.151.0,36.172.0,18.160.0"}
P.entries["subzone:dalaran"] = {n="达拉然",s="达拉然曾是肯瑞托辉煌的魔法王国首都，坐落在洛丹米尔湖南岸。在第三次战争中被天灾军团和恶魔领主阿克蒙德摧毁，幸存的法师们正在重建这座城市，并在重建初期移除了其保护性的紫色护盾。",h="达拉然曾是肯瑞托辉煌的魔法王国首都，坐落在洛丹米尔湖南岸。在第三次战争中被天灾军团和恶魔领主阿克蒙德摧毁，幸存的法师们正在重建这座城市，并在重建初期移除了其保护性的紫色护盾。",kw={"奥特兰克","阿克蒙德","六人议会","达拉然","穹顶","肯瑞托","洛丹米尔","护盾","紫罗兰城堡"},ang={["class:Mage"]="达拉然是人类和高等精灵巫术的历史摇篮。看到它那传奇的尖塔仍在重建中，这让人庄严地想起法师们在第三次战争中遭受的惨重损失。",["faction:Alliance"]="达拉然是最初洛丹伦联盟的七个创始王国之一，肯瑞托正在重建其沦陷的首都。"},sec={{t="魔法王国的陨落",b="达拉然由阿拉索帝国的巫师在古老的巨魔战争后建立，几个世纪以来一直是人类研究奥术的首要圣地。在六人议会的领导下，肯瑞托积累了庞大的魔法档案，并将强大的神器守卫在紫罗兰城堡中。那段辉煌的时代在第三次战争中戛然而止。叛徒王子阿尔萨斯率领天灾军团穿过城门夺取了麦迪文之书，此后不久，恶魔领主阿克蒙德将达拉然高耸的尖塔摧毁成废墟。"},{t="重建魔法王国",b="在军团战败后，肯瑞托幸存的巫师回到了他们满目疮痍的家园。他们拒绝将祖地让给天灾军团或拾荒者，在城市中心上方竖起了一道无法逾越的闪烁紫色屏障。护盾此后已被移除，但重建工作仍在继续。法师们继续重建他们沦陷的圣地，可以在紫罗兰城堡找到大法师安斯雷姆·鲁因维沃尔。"}},faq={{q="达拉然的保护护盾怎么了？",a="肯瑞托在达拉然于第三次战争中被毁后竖起了一道魔法护盾。护盾现已被移除，城市仍在重建中。",al={"紫色气泡","紫色护盾奥特兰克","那个穹顶是什么","达拉然穹顶"}},{q="玩家可以进入达拉然吗？",a="可以，虽然重建工作仍在进行，大法师安斯雷姆·鲁因维沃尔也居住在紫罗兰城堡。不过，肯瑞托站在联盟一边：部落在他们眼中是仇恨对象，在城中会被立刻攻击，但部落团队仍然可以挑战达拉然城地下城。",al={"我能进入达拉然吗","如何进入达拉然","越过达拉然护盾"}},{q="是谁摧毁了达拉然？",a="达拉然遭到了阿尔萨斯王子及其天灾军团的攻击，他们从金库中偷走了麦迪文之书。不久之后，恶魔领主阿克蒙德召唤黑暗魔法将这座城市化为废墟。",al={"达拉然是如何陷落的","是谁炸毁了达拉然","为什么达拉然是一片废墟"}},{q="谁统治达拉然？",a="这座城市由肯瑞托治理，这是一个由被称为六人议会的统治集会领导的精英魔法机构。",al={"谁管理达拉然","达拉然领导层","谁领导肯瑞托"}}},fp="7,308,21.539.0,24.459.0,43.163.0,26.275.0,22.202.0,18.118.0"}
P.entries["subzone:dalson-s-tears"] = {n="达尔松之泪",s="达尔松之泪是一处位于西瘟疫之地中心地带的荒废农庄。这片土地曾被称为达尔松果园，在第三次战争期间被占领，并被改造为天灾军团存放有毒瘟疫大锅的集结地。农场主人死后的亡灵残骸至今仍在田野和外屋游荡。",h="达尔松之泪是一处位于西瘟疫之地中心地带的荒废农庄。这片土地曾被称为达尔松果园，在第三次战争期间被占领，并被改造为天灾军团存放有毒瘟疫大锅的集结地。农场主人死后的亡灵残骸至今仍在田野和外屋游荡。",kw={"大熔炉领主马尔维尼斯","达尔松果园","达尔松之泪","达尔松先生","达尔松夫人","瘟疫大锅","西瘟疫之地"},ang={["class:Paladin"]="被亵渎的田野和达尔松一家受苦的灵魂，证明了圣光的圣武士们誓要将洛丹伦从挥之不去的邪恶中净化干净。",["race:Undead"]="这座荒废的农庄是一个鲜明的提醒，让人想起在Sylvanas Windrunner打破巫妖王对被遗忘者的控制之前，许多洛丹伦人民共同的命运。"},sec={{t="被毒化的收成",b="在第三次战争之前，这片庄园曾是达尔松果园，是洛丹伦粮仓中一片多产的农田。如今，这片田野充斥着腐烂的气息，被重新命名为达尔松之泪。在废弃农场的中心矗立着一口巨大的铁锅，源源不断地向周围散发着剧毒的绿色瘟疫蒸汽。该装置由大熔炉领主马尔维尼斯监管，并由一群凋零僵尸、腐烂尸体和效忠于巫妖王的骸骨恐怖怪防守。"},{t="达尔松一家的命运",b="当瘟疫席卷该地区时，农场的原主人遭遇了悲惨的结局，但死亡并没有给他们带来解脱。达尔松夫人作为一具毫无思想的骷髅在被毒化的土地上游荡，手里紧握着农场外屋的钥匙。在那间小屋里潜伏着可怕的食尸鬼，那正是达尔松先生本人，他在夫妻二人都彻底屈服于天灾军团的诅咒之前，被绝望的妻子锁在了里面。"}},faq={{q="达尔松之泪在瘟疫爆发前叫什么名字？",a="在第三次战争摧毁洛丹伦之前，这处房产是一块繁荣的农业用地，被称为达尔松果园。",al={"达尔松果园","原名","这个农场原来叫什么"}},{q="为什么农场中间会有一个巨大的大锅？",a="天灾军团在洛丹伦的农田各处竖起了巨大的瘟疫大锅，用来持续熬煮剧毒毒素。这些蒸汽飘散在整个地区，污染了大地，毒害了水源，并腐蚀了任何接触到它们的生物。",al={"达尔松大锅","绿烟大锅","这里为什么有个大锅"}},{q="谁在看守达尔松之泪的大锅？",a="这口瘟疫大锅由大熔炉领主马尔维尼斯保护，他是效忠于天灾军团的亡灵指挥官，身边还有成群的凋零僵尸、骸骨恐怖怪和腐烂尸体随从。",al={"大熔炉领主","这里的老大是谁","大熔炉领主马尔维尼斯"}},{q="关于那个锁住的外屋有什么了解？",a="那个锁住的外屋是废弃农场的一部分。达尔松夫人的日记为调查这一家人遭遇的任何人提供了线索。",al={"外屋怪物","外屋里有什么","达尔松先生"}}},fp="14,329,18.487.0,23.399.1,49.118.0,56.245.0,42.181.0,40.137.1"}
P.entries["subzone:dandred-s-fold"] = {n="达伦德农场",s="达伦德农场是一处隐秘的农舍和庄园，坐落在奥特兰克山脉洛丹米尔湖薄雾缭绕的西北岸。这里现在已被辛迪加占领，成为了奥里登·匹瑞诺德领主及其同谋者的安全避难所。部落和联盟出于完全不同的原因，都密切关注着这处湖畔据点。",h="达伦德农场是一处隐秘的农舍和庄园，坐落在奥特兰克山脉洛丹米尔湖薄雾缭绕的西北岸。这里现在已被辛迪加占领，成为了奥里登·匹瑞诺德领主及其同谋者的安全避难所。部落和联盟出于完全不同的原因，都密切关注着这处湖畔据点。",kw={"奥里登·匹瑞诺德","阿古斯唤醒者","达伦德农场","艾丽萨","洛丹米尔湖","纳格兹","辛迪加","高地"},ang={["faction:Alliance"]="联盟无法容忍人类不法之徒与恶魔般的阿古斯唤醒者结盟，因此赫尼·马雷布镇长下令对该庄园进行外科手术式的打击。",["faction:Horde"]="对于部落来说，潜入达伦德农场有着深刻的私人原因。大酋长萨尔希望夺回塔蕾莎·福克斯顿的项链。"},sec={{t="沦为不法之徒巢穴的贵族避风港",b="达伦德农场位于高地的西缘，拥有通往洛丹米尔湖水域的私人通道，曾经是一处宁静的乡村庄园，可能由一位名为达伦德的奥特兰克贵族所拥有。王国覆灭后，这里变成了辛迪加的防御性飞地。辛迪加的刺客和暴徒如今巡逻在围栏和码头周围，保护着那些没落贵族，使其免受南海镇当局和湖对岸被遗忘者的窥探。"},{t="阴谋的中心",b="庄园紧闭的大门后，酝酿着危险的阴谋。辛迪加公认的领袖奥里登·匹瑞诺德领主将达伦德农场作为其大本营，与他的情妇艾丽萨一同在此运筹帷幄。然而，这些不法之徒并不孤单，一名来自阿古斯唤醒者的暗影议会兽人术士纳格兹也已潜伏于此，与这群人类强盗进行着黑暗的交易。这种危险的联盟使达伦德农场成为了南海镇镇长和部落勇士共同的目标。"}},faq={{q="谁控制着达伦德农场？",a="该庄园由辛迪加占领，这是一个由奥特兰克被废黜的贵族所领导的贵族犯罪网络。辛迪加刺客和暴徒守卫着庄园，效忠于奥里登·匹瑞诺德领主。",al={"谁在达伦德农场","谁住在达伦德农场","达伦德农场的怪物"}},{q="为什么部落关心这座庄园？",a="部落针对这座庄园进行打击，旨在铲除奥里登·匹瑞诺德领主并夺回一件被窃取的纪念品：曾经属于塔蕾莎·福克斯顿的传家宝项链，她是萨尔童年时的救命恩人和知己。",al={"部落与达伦德农场","为什么部落要前往达伦德农场"}},{q="为什么联盟会派遣冒险者前往这里？",a="南海镇的赫尼·马雷布镇长指派联盟特工前往此地，消灭阿古斯唤醒者邪教的一名危险成员纳格兹，此人正与辛迪加不法之徒相互勾结。",al={"联盟与达伦德农场","马雷布镇长达伦德农场任务"}},{q="达伦德是谁？",a="有关达伦德的身份并无记载。庄园冠以其名，但没有任何确切的记录能指明其最初的所有者。",al={"谁是达伦德","达伦德背景故事"}}},fx={e469c160={q="达伦德农场是什么地方？",a="达伦德农场是一处隐蔽的农场庄园，坐落在奥特兰克山脉西部高地，毗邻洛丹米尔湖雾气笼罩的湖岸。这里曾是一处宁静的贵族庄园，如今已成为辛迪加的防御据点和行动基地。",al={"达伦德农场是什么","奥特兰克的达伦德农场","关于达伦德农场"}},b8b5cedb={q="达伦德农场发生了什么？",a="奥特兰克王国覆灭后，这座湖畔农场落入辛迪加之手。艾登·匹瑞诺德领主将这处偏僻庄园改造成自己的据点和隐居之所，并与阿古斯之潮等神秘组织建立了危险的联系。",al={"达伦德农场的历史","达伦德农场发生了什么"}},fc1f4fab={q="达伦德农场危险吗？",a="独自旅行的人在这里会面临极大的危险。庄园由技艺娴熟的辛迪加执法者、潜行杀手和阿古斯之潮的秘密特工把守，他们都忠于艾登·匹瑞诺德领主，并对外来入侵者怀有敌意。",al={"达伦德农场危险吗","达伦德农场的危险","谁在达伦德农场"}}},fp="14,352,36.473.0,20.477.1,28.201.0,42.198.1,44.172.0,16.121.0"}
P.entries["subzone:dark-portal"] = {n="黑暗之门",s="黑暗之门是一座巨大的石制门户，矗立在诅咒之地的南缘。它最初由麦迪文和古尔丹联手施展法术强行开启，是旧部落进入艾泽拉斯的宿命通道，并引发了第一次战争。",h="黑暗之门是一座巨大的石制门户，矗立在诅咒之地的南缘。它最初由麦迪文和古尔丹联手施展法术强行开启，是旧部落进入艾泽拉斯的宿命通道，并引发了第一次战争。",kw={"黑色沼泽","诅咒之地","黑暗之门","德拉诺","大传送门","古尔丹","卡德加","麦迪文"},ang={["faction:Alliance"]="对联盟来说，该门户是第一次战争和古老的暴风城陷落的庄严纪念碑，因此守望堡的法师们必须进行永恒的守望。",["race:Orc"]="这道门户是你的人民过去的痛苦门槛——旧部落在恶魔主人的奴役下行军穿过这道大门，为了战争抛弃了他们的祖居之地。"},sec={{t="跨越现实的裂隙",b="在它开启之前，这片区域曾是黑色沼泽的一部分，是一片横跨南方的潮湿湿地。当被萨格拉斯附身的麦迪文将提瑞斯法法术与德拉诺的古尔丹的邪能法术结合在一起时，一切都改变了。这场仪式耗尽了无数生命，撕裂了现实的结构。旧部落建造了巨大的石制建筑来锚定裂隙，并从其入口处行军，在第一次战争中击碎了暴风城王国。门户散发的邪能从根本上腐蚀了周围的地形，将茂密的沼泽变成了今天所见的红色石化荒地。"},{t="休眠的警惕",b="洛丹伦联盟在第二次战争中获胜后，大法师卡德加利用强大的魔法击碎了石制门框，希望永远切断与德拉诺的联系。然而，底下的空间撕裂实际上是不可摧毁的。联盟在附近建立了守望堡来监视这道伤疤，而恶魔和暗影议会的残党仍在被炸毁的火山口中潜行。今天，这座门户虽然已经重组但处于休眠状态，成为了世界之间一道双方都不敢遗弃的无声伤痕。"}},faq={{q="我现在能穿过黑暗之门吗？",a="不能。门户的石制框架依然完好，但其中的裂隙处于休眠状态。目前没有任何旅行者可以穿越这道门槛。",al={"我可以进入黑暗之门吗","黑暗之门开启了吗","通往外域的传送门"}},{q="谁最初建造了黑暗之门？",a="它是由艾泽拉斯的人类守护者麦迪文和垂死世界德拉诺的术士古尔丹共同施展仪式所创造的，这次仪式策划了点燃第一次战争的入侵行动。",al={"谁创造了黑暗之门","麦迪文古尔丹传送门","黑暗之门创造者"}},{q="为什么守望堡要监视它？",a="在第二次战争后，大法师卡德加击碎了门户最初的框架，并说服联盟监视其废墟。守望堡正是由联盟建立的，旨在维持对该地点的永久监视，以防威胁再次出现。",al={"为什么守望堡在这里","守望堡传送门守望","为什么是守望堡"}},{q="为什么门户周围的地面是红色且贫瘠的？",a="诅咒之地曾经是一片被称为黑色沼泽的肥沃湿地。为了突破现实而消耗的巨大邪能，加上来自德拉诺和恶魔野兽的腐蚀，毒害了土壤并使生态系统石化。",al={"为什么诅咒之地是死地","传送门腐蚀","为什么诅咒之地是红色的"}}},fp="11,264,23.601.0,17.516.0,47.126.0,37.192.0,40.257.0,51.236.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="黑云峰",s="黑云峰是一个坚固的牛头人定居点，坐落在千针石林升降梯以东的几座相互连接的平顶山上。这个空中据点由好战的恐怖图腾氏族把守，是他们进行区域骚扰和阴谋勾当的行动基地。",h="黑云峰是一个坚固的牛头人定居点，坐落在千针石林升降梯以东的几座相互连接的平顶山上。这个空中据点由好战的恐怖图腾氏族把守，是他们进行区域骚扰和阴谋勾当的行动基地。",kw={"阿纳克·恐怖图腾","黑云峰","恐怖图腾","哈布·邪山","平顶山","千针石林"},ang={["faction:Horde"]="占据这座平顶山的恐怖图腾氏族充当了敌对势力，威胁着从升降梯深入千针石林的旅人。",["race:Tauren"]="恐怖图腾氏族在这些平顶山上的背叛行径，与凯恩·血蹄为各部落之间力争维持的团结与和平构成了鲜明的对比。"},sec={{t="悬崖之上的堡垒",b="黑云峰横跨三座由绳桥连接的主要平顶山，俯瞰着下方的峡谷盆地。通往这些高地的路径非常有限，只能通过从峡谷底部通向木桥的陡峭天然斜坡，或者通过靠近剃刀高地附近的一处高地通道到达。在这些风吹雨打的岩石之上，恐怖图腾氏族监视着整个山谷，不仅避开了寻常的袭击，也与广大的牛头人部落隔绝开来。"},{t="平顶山上的阴谋",b="该定居点由阿纳克·恐怖图腾和哈布·邪山等首领指挥，绝非一个简单的哨站。在平顶山上发现的秘密信件表明，恐怖图腾氏族正在与一股黑暗且未知的力量积极勾结，其追求的野心与凯恩·血蹄在雷霆崖所建立的和平背道而驰。"}},faq={{q="谁控制着黑云峰？",a="这座堡垒属于恐怖图腾氏族，这是一个好战且孤僻的牛头人派系，他们公开敌视大多数外来者，并对部落抱有极深的猜忌。",al={"谁住在黑云峰","黑云峰的主人","黑云峰里有什么人"}},{q="如何到达黑云峰？",a="可以通过从峡谷底部攀爬相邻平顶山的天然坡道并穿过木制绳桥，或者经过剃刀高地附近的一座桥梁到达黑云峰。",al={"如何登上黑云峰","黑云峰路径","黑云峰入口"}},{q="是谁在此领导恐怖图腾氏族？",a="该定居点的行动由几位重要的恐怖图腾人物负责监管，其中包括阿纳克·恐怖图腾和哈布·邪山。",al={"黑云峰首领","谁领导着黑云峰","恐怖图腾首领"}},{q="恐怖图腾氏族在此策划着什么？",a="黑云峰的恐怖图腾氏族与一股未知的黑暗势力保持着秘密通讯，致力于实现威胁到千针石林稳定的阴暗目标。",al={"黑云峰发生了什么","恐怖图腾阴谋"}}},fx={["0ab7147f"]={q="黑云峰是什么地方？",a="黑云峰是牛头人村落，坐落在千针石林峡谷底部上方的高处，就在升降梯以东。村落横跨三座有人居住的台地，彼此由悬空的绳桥相连。这里是恐怖图腾部族的重要据点。这个好斗而孤立的牛头人部族严密守护自己的领地，不让外人靠近。",al={"黑云峰是什么","黑云峰信息","关于黑云峰"}},["44a431c5"]={q="黑云峰危险吗？",a="非常危险。占据黑云峰的恐怖图腾牛头人对擅闯者怀有强烈敌意，并在整个村落严密布防。这里台地高耸、绳桥狭窄，战斗时随时可能坠入下方峡谷；部族的萨满和战士也已准备好杀死任何沿山坡闯上来的人。",al={"黑云峰的危险","黑云峰有多危险","黑云峰危险吗"}}},fp="18,273,21.385.0,20.328.1,32.157.0,36.177.0,29.121.0,37.170.1"}
P.entries["subzone:darkened-bank"] = {n="暗色河滩",s="暗色河滩是暮色森林的北岸，与将这片阴影笼罩的树林与艾尔文森林分隔开来的河流接壤。它从遥远的西边一直延伸至东边的赤脊山，标志着北方相对安全地带与森林中黑暗恐怖之间的边界。",h="暗色河滩是暮色森林的北岸，与将这片阴影笼罩的树林与艾尔文森林分隔开来的河流接壤。它从遥远的西边一直延伸至东边的赤脊山，标志着北方相对安全地带与森林中黑暗恐怖之间的边界。",kw={"暗色河滩","暮色森林","艾尔文森林","拉尔斯","河流","河岸","斯温·约根"},ang={["faction:Alliance"]="对于离开艾尔文森林的联盟冒险者来说，暗色河滩是他们深入暮色森林那被诅咒的核心地带之前的初期集结地。"},sec={{t="危险的边界",b="暗色河滩沿着河流南岸延伸，与艾尔文森林隔河相望，构成了暮色森林的北缘。它从西侧的河湾处向东延伸，一直到通往赤脊山的石桥。尽管在暮色森林诅咒的笼罩下，这里的景色显得阴郁晦暗，但这片河岸通常是冒险者从艾尔文森林向南进发时的第一个立足点。在河滩的最西端坐落着一个临时的营地，流离失所的难民，包括斯温·约根和拉尔斯，在此避难，勉强处于深林威胁的边缘之外。"}},faq={{q="暗色河滩位于何处？",a="暗色河滩沿着河流横跨暮色森林的整个北岸，与艾尔文森林隔水相望。它从该区域的最西端一直延伸到通往赤脊山的桥梁。",al={"暗色河滩位置","暗色河滩在哪里","暮色森林暗色河滩"}},{q="谁居住在暗色河滩？",a="在河滩的最西端有一个简陋的避难营地，由斯温·约根和拉尔斯占据。他们被迫离开了原本在领地深处的生活，将这片北部的河岸当作一个脆弱的避风港，同时寻求帮助以对抗暮色森林的威胁。",al={"暗色河滩的营地","谁在暗色河滩","暗色河滩npc"}},{q="旅行者通常如何到达此区域？",a="旅行者可以从艾尔文森林的西南部游过河流到达暗色河滩的西段，或者沿着赤脊山大桥向西沿河岸行进。",al={"如何前往暗色河滩","前往暗色河滩"}}},fx={["84b37a17"]={q="暗色河滩是什么地方？",a="暗色河滩是暮色森林北部绵长的河岸线，从森林西缘一直向东延伸，直到通往赤脊山的桥附近。隔河望去便是艾尔文森林，这片边境地带标志着北方金色阳光与笼罩暮色森林的诡异阴霾之间的分界。",al={"暗色河滩是什么","暮色森林的暗色河滩","介绍暗色河滩"}},["180e4478"]={q="暗色河滩危险吗？",a="与暮色森林深处潜伏的致命恐怖相比，暗色河滩的野生动物和徘徊者相对弱小，但这里远非安全之地。掠食野兽在河岸边的灌木丛中出没，西岸的难民也时刻警惕着不断蔓延的黑暗。",al={"暗色河滩的危险","暗色河滩安全吗","暗色河滩的威胁"}}},fp="13,306,21.557.0,35.242.0,34.259.0,41.220.0"}
P.entries["subzone:darkmist-cavern"] = {n="黑雾洞穴",s="黑雾洞穴是一座位于尘泥沼泽西北部、被人遗弃的矿坑，现在完全被捕食性的巨型蜘蛛所占据。洞穴外摇摇欲坠的废墟暗示着这里曾经有过一个不幸的定居点，但最终被沼泽的危险吞噬。当地人对于究竟是洞穴因蜘蛛得名，还是蜘蛛因洞穴得名，仍各执一词。",h="黑雾洞穴是一座位于尘泥沼泽西北部、被人遗弃的矿坑，现在完全被捕食性的巨型蜘蛛所占据。洞穴外摇摇欲坠的废墟暗示着这里曾经有过一个不幸的定居点，但最终被沼泽的危险吞噬。当地人对于究竟是洞穴因蜘蛛得名，还是蜘蛛因洞穴得名，仍各...",kw={"黑雾洞穴","黑雾蜘蛛","尘泥沼泽","矿坑遗迹","蜘蛛矿坑","沼眼贾尔"},ang={["profession:Cooking"]="古怪的隐士“沼眼”贾尔认为黑雾蜘蛛那邪恶的眼睛是制作美味沼泽炖菜的主要配料，尽管沼泽外很少有人能接受这种口味。",["profession:Mining"]="显然，这处洞穴是过去的矿工开凿出来的，但任何想要在其岩石深处勘探的人，都必须先杀出一条血路，穿过成群结队的巢居蜘蛛。"},sec={{t="矿坑中的蛛群",b="黑雾洞穴坐落在尘泥沼泽的西北边缘，看起来曾经是一处活跃的采矿点。如今，人类的足迹早已消逝，只在入口外留下破败不堪的棚屋，而内部的隧道网络则被厚厚的蛛网所覆盖。洞穴被黑雾蜘蛛所占据，这些捕食性的恐怖生物毒性极强且体型巨大，让这里成了大意行人的死亡禁区。沼泽居民们至今仍在争论，究竟是该洞穴以潜伏其中的邪恶蛛群命名，还是蜘蛛取了这个阴森洞穴的名字。"},{t="隐士的储藏室",b="尽管这里危险重重，但偶尔还是会有拾荒者和古怪的沼泽居民造访。隐士“沼眼”贾尔因经常派遣旅行者深入蛛网密布的洞穴去采集这些巨型蜘蛛的眼睛而闻名，他坚称那是熬制肉汤的上好食材。除了这种古怪的烹饪需求外，大多数明智的旅行者都会对那布满蛛网的入口敬而远之。"}},faq={{q="什么是黑雾洞穴？",a="这是一座位于尘泥沼泽西北部的废弃矿坑，如今已完全被名为黑雾蜘蛛的剧毒巨型蜘蛛所占据。",al={"什么是黑雾洞穴","黑雾洞窟","尘泥沼泽蜘蛛洞"}},{q="洞穴外的废墟里曾住着什么人？",a="残存的小木屋遗迹表明这里曾有一个定居点或采矿营地，但其曾经的居民身份已不可考。",al={"这里曾住着谁","黑雾洞穴外的房屋","黑雾废弃村庄"}},{q="为什么当地人要冒险进入黑雾洞穴？",a="极少有人会自愿进入其中，但那个古怪的隐士“沼眼”贾尔会雇佣大胆的冒险者潜入隧道，取回蜘蛛眼来炖煮他那古怪的沼泽乱炖。",al={"为什么去黑雾洞穴","黑雾洞穴任务"}},{q="是蜘蛛还是洞穴先得的名？",a="尘泥沼泽的居民们对于究竟是蜘蛛以洞穴命名，还是洞穴以蜘蛛命名各执一词。目前还没有定论能说明哪个名字出现得更早。",al={"蜘蛛命名来源","为什么叫黑雾"}}},fp="15,322,21.557.0,15.381.0,24.155.0,40.125.0,43.179.0,49.182.0"}
P.entries["subzone:darkshire"] = {n="夜色镇",s="夜色镇，原名大汉姆莱特，是暮色森林东部一座饱经风霜的定居点。由于常年笼罩在不自然的阴霾之下且被暴风城所忽视，这座城镇只能依靠守夜人的警惕和镇民们顽强的韧性勉强维持。",h="夜色镇，原名大汉姆莱特，是暮色森林东部一座饱经风霜的定居点。由于常年笼罩在不自然的阴霾之下且被暴风城所忽视，这座城镇只能依靠守夜人的警惕和镇民们顽强的韧性勉强维持。",kw={"亮木","夜色镇","暮色森林","埃伯洛克","大汉姆莱特","守夜人","猩红乌鸦酒馆"},ang={["class:Paladin"]="随着周围墓地里死者不断复生，而恐惧的当地人几乎快要遗忘圣光，圣光勇士们会发现村庄外围总有清理不完的邪恶枯萎。",["faction:Alliance"]="夜色镇是王国破碎边疆的一个鲜明写照。联盟的英雄们在这里会受到镇民的感激，但同时也能感受到他们对暴风城那毫无作为的贵族们发自内心的苦涩怨恨。"},sec={{t="一座被遗弃的城镇",b="这里曾是一片名为大汉姆莱特的宁静林地定居点，但在第一次战争期间被旧部落夷为平地，后来才得以重建。麦迪文在卡拉赞的陨落令当地局势彻底恶化，他死前那漫长的挣扎诅咒了周围的森林，使其化作如今昏暗荒凉的暮色森林。尽管名义上属于暴风城王国，但市政厅实际上几乎得不到王室的任何援助。暴风城内政治上的瘫痪导致驻军撤离，边境无人巡逻，这迫使艾尔罗·埃伯洛克公爵和当地议会只能在阴影中自行维持残酷而封闭的治理。"},{t="黑暗中的防线",b="在西部墓地游荡的行尸和在林间出没的野性狼人的环伺下，夜色镇只能沿着木栅栏苦苦支撑。城镇的主要屏障是由阿尔泰娅·埃伯洛克指挥的平民志愿民兵组织——守夜人。这些疲惫的哨兵以镇中心为据点，在漆黑的道路上巡逻，确保道路畅通，并将潜伏在林边的恐怖生物拒之门外。抵达Scarlet Raven Tavern的旅人会发现，当地人不仅多疑、恐惧，而且急切地想要寻找任何能够挥舞武器的雇佣兵。"}},faq={{q="这座城镇为什么要改名大汉姆莱特？",a="该定居点在这一地区还是阳光明媚的森林时，最初被称为大汉姆莱特。在守护者麦迪文于附近的卡拉赞死亡后，黑暗魔法席卷了整片森林，遮蔽了阳光并唤醒了死者。随着森林逐渐腐化为暮色森林，这片被诅咒的残酷现实促使居民将村庄改名为夜色镇。",al={"为什么叫夜色镇","大汉姆莱特更名","夜色镇历史"}},{q="为什么暴风城不协助保卫夜色镇？",a="在瓦里安·乌瑞恩国王失踪后的政治动荡中，暴风城从暮色森林撤走了军队。镇民们组建了守夜人来抵御王室不再负责的威胁。",al={"暴风城军队在哪","为什么暮色森林没有守卫","为什么暴风城抛弃了夜色镇"}},{q="谁在领导夜色镇？",a="城镇的治理权掌握在艾尔罗·埃伯洛克公爵和夜色镇议会手中，他们与书记员达尔塔一同在市政厅办公。军事防卫则由艾尔罗的女儿，指挥官阿尔泰娅·埃伯洛克领导，她指挥着名为守夜人的志愿民兵组织。",al={"谁负责夜色镇","夜色镇领导层","夜色镇镇长"}},{q="什么是守夜人？",a="守夜人是阿尔泰娅·埃伯洛克出于必要而组建的当地平民民兵组织。由于暴风城军队拒绝向暮色森林部署兵力，当地镇民只能拿起武器，在阴暗的道路上巡逻，保卫边境，并击退食尸鬼的入侵和流窜的野兽。",al={"什么是守夜人","夜色镇守卫","谁保卫夜色镇"}},{q="摩根·拉迪莫尔是谁？",a="摩根·拉迪莫尔是一位老兵，他在第三次战争后回到家乡，却发现家园已毁，家人下落不明。他的寻找过程将他带到了夜色镇；关于他故事的后续，当地的记录中有所保留。",al={"摩根拉迪莫尔背景","拉迪莫尔夜色镇","拉迪莫尔是谁"}}},fx={["59ecffc1"]={q="什么是夜色镇？",a="夜色镇是暮色森林中最后一处幸存的人类聚居地。它曾是一座宁静的林间村庄，名为Grand Hamlet，如今却成了被重重围困、孤立无援，笼罩在永恒阴霾中的前哨。镇上有一家旅店、一间铁匠铺和一座市政厅，是旅行者和苦苦坚守、抵御森林恐怖的当地居民唯一的避难所。",al={"这座城镇是什么","介绍夜色镇","夜色镇信息"}},["2c565dbf"]={q="夜色镇过去发生过什么？",a="这座城镇最初名为Grand Hamlet，建在当时阳光明媚的森林中，后来在第一次战争期间被旧部落夷为平地。第二次战争后，聚居地得以重建；麦迪文之死却使周围的森林腐化成暮色森林，城镇也因此逐渐陷入恐怖之中。永恒的暮光笼罩大地后，这里便改名为夜色镇。",al={"夜色镇历史","grand hamlet的历史","grand hamlet发生了什么"}},a7f74618={q="谁住在夜色镇？",a="夜色镇的居民包括固执而神经紧张的当地人、工匠，以及由艾尔罗·埃伯洛克公爵和书记员达尔塔领导的地方政府。艾尔塞亚·埃伯洛克和她的志愿者组成的守夜人民兵负责守卫这里。居民们与王室援助隔绝，始终生活在恐惧和猜疑之中，却仍坚定地守护着祖居，抵挡不断逼近的黑暗。",al={"这里住着谁","夜色镇居民","谁住在夜色镇"}},a9d39424={q="夜色镇危险吗？",a="尽管夜色镇本身由守夜人严密守卫，危险仍迫近城门。行尸堵塞着附近的墓地和道路，凶猛的狼人潜伏在昏暗的森林中，而暴风城已将这片地区听天由命。若无护卫，走出城镇昏暗的灯火范围，无异于自寻死路。",al={"这里安全吗","夜色镇危险吗","夜色镇有多危险"}}},fp="9,262,16.638.0,20.574.0,43.360.0,45.223.0,20.268.0,24.277.0,24.194.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Darkshire Town Hall",s="Darkshire Town Hall坐落在城镇广场西侧，是暮色森林当地的行政中心。在这座灯光昏暗的大厅内，镇长艾尔罗·埃伯洛克公爵和他的议会试图管理这个被蔓延的黑暗和亡灵怪物所包围的定居点。",h="Darkshire Town Hall坐落在城镇广场西侧，是暮色森林当地的行政中心。在这座灯光昏暗的大厅内，镇长艾尔罗·埃伯洛克公爵和他的议会试图管理这个被蔓延的黑暗和亡灵怪物所包围的定居点。",kw={"书记员达尔塔","议会","夜色镇","暮色森林","艾尔罗·埃伯洛克","市政厅"},ang={["faction:Alliance"]="对于联盟的旅行者来说，市政厅代表了王国南部边境脆弱的权威，展现了暴风城的保护在孤立的定居点是多么薄弱。"},sec={{t="夜色镇的权力中心",b="市政厅位于主城镇广场的正西侧，是夜色镇民政领导聚集并管理这片日益孤立的领地的地方。在饱经风霜的墙壁内，镇长艾尔罗·埃伯洛克公爵正努力维持社会秩序并保护民众，而暴风城几乎无法提供任何军事援助。与镇长一起工作的还有书记员达尔塔等市政官员，他们负责追踪当地记录以及那些敢于穿越暮色森林危险道路的旅行者，尽管在如此危险的时期，保持账目更新是一项严峻而艰巨的任务。"}},faq={{q="谁在这座建筑里领导这个城镇？",a="艾尔罗·埃伯洛克公爵担任夜色镇镇长，并在市政厅内主持镇议会。他指挥当地的防御工作，并向来访的冒险者寻求帮助，因为该镇几乎得不到来自王国首都的任何增援。",al={"谁是镇长","谁管理夜色镇","市政厅里有谁"}},{q="市政厅内保留了哪些记录？",a="书记员达尔塔负责维护城镇登记册，记录居住在夜色镇以及途经此地的旅行者。由于暮色森林中混乱和频繁的危险，他的许多日志和记录都有些过时了。",al={"书记员达尔塔的记录","达尔塔负责什么","城镇登记册"}},{q="为什么市政厅对暮色森林的生存如此重要？",a="由于暮色森林与暴风城的直接军事支持切断了联系，市政厅成为了夜色守卫和当地权威机构的运营中心。议会在这里协调平民防御，并向这片阴影笼罩的地区派遣援助。",al={"为什么市政厅很重要","夜色镇议会的角色"}}},fx={e48299c3={q="什么是Darkshire Town Hall？",a="Darkshire Town Hall是夜色镇的行政中心，也是当地政府的所在地。这座建筑位于镇广场西侧的高处，当地领袖、议会成员和政务书记员在此协调公共事务、维护公共档案，并设法治理这群被暮色森林的腐化荒野包围、心怀恐惧的居民。",al={"什么是darkshire town hall","darkshire town hall的用途","介绍darkshire town hall"}},bcc317cc={q="谁住在或管理Darkshire Town Hall？",a="市政厅由市长艾尔罗·埃伯洛克公爵和夜色镇议会管理，书记员达尔塔等行政人员也在此工作。这里并非私人住所，而是市政枢纽；夜色镇的政务官员、历史学家和抄写员每天都在此整理城镇记录、处理民政事务，并商议聚居地的防务。",al={"谁在darkshire town hall工作","darkshire town hall里有谁","darkshire town hall的工作人员"}},["8f432bfa"]={q="Darkshire Town Hall危险吗？",a="这座建筑本身是暮色森林中最安全的避难所之一。它由守夜人严密守卫，四周也有城镇防线保护，只要城镇外围防线能够抵挡外部袭击，这里就能免受亡灵、野兽和徘徊在周围森林中的黑暗威胁。",al={"darkshire town hall安全吗","darkshire town hall的危险","darkshire town hall内部有危险吗"}}},fp="19,278,21.556.0,38.263.0,43.229.0,57.255.0"}
P.entries["subzone:darkspear-strand"] = {n="暗矛海滩",s="暗矛海滩是杜隆塔尔南部的一片海岸线，暗矛巨魔在被驱逐出回音群岛后，在此处登陆。这片海滩紧邻森金村，标志着该部落在沃金的领导下在大陆寻求庇护的艰苦开端。",h="暗矛海滩是杜隆塔尔南部的一片海岸线，暗矛巨魔在被驱逐出回音群岛后，在此处登陆。这片海滩紧邻森金村，标志着该部落在沃金的领导下在大陆寻求庇护的艰苦开端。",kw={"暗矛","暗矛海滩","杜隆塔尔","回音群岛","森金村","沃金","扎拉赞"},ang={["faction:Horde"]="在失去了他们的岛屿定居点后，这片海滩标志着暗矛巨魔在卡利姆多大陆与他们的兽人盟友并肩扎根的南部海岸。",["race:Troll"]="对于暗矛巨魔来说，踏上这片海岸不仅带来了扎拉赞背叛的刺痛，也承载着他们死里逃生并建立森金村的苦涩回忆。"},sec={{t="流亡之岸",b="当巫医扎拉赞发疯并夺取了回音群岛的控制权后，幸存的暗矛巨魔被迫放弃了他们海外的家园。绝望的难民们渡过狭窄的水域，登上了这片被阳光灼烤的海岸。幸存者们没有分散到杜隆塔尔那充满敌意的红色荒原中，而是聚拢在距离海岸线仅几码远的地方，建造了森金村。今天，这片海滩静静地提醒着他们曾经流离失所的过去，隔着海浪眺望着他们仍渴望夺回的群岛。"}},faq={{q="暗矛海滩发生了什么？",a="这片海岸线是暗矛巨魔在逃离回音群岛后的登陆点。当扎拉赞对他的族人施展黑魔法时，幸存者们撤离并渡海来到这里，随即在附近聚集建立了森金村。",al={"为什么叫暗矛海滩","暗矛海滩背景故事","这片海滩是什么"}},{q="暗矛部族为什么要离开回音群岛？",a="巫医扎拉赞背叛了他的族人，并利用黑暗巫毒奴役了同胞的思想。沃金酋长率领其余未受腐蚀的暗矛巨魔逃离了群岛以躲避完全的奴役，并在这片海滩上岸。",al={"巨魔为什么离开回音群岛","扎拉赞流亡","回音群岛撤离"}},{q="暗矛海滩旁边有什么聚居地？",a="森金村位于距离海滩仅几码远的内陆。它是由难民在登上这片海滩后立即建立的，也是暗矛在杜隆塔尔的主要前哨站和精神中心。",al={"暗矛海滩附近的村庄","海滩旁边的城镇","森金村位置"}}},fx={["88a2cf68"]={q="什么是暗矛海滩？",al={"什么是暗矛海滩","暗矛海滩传说","介绍暗矛海滩"}},["504bffc1"]={q="为什么叫暗矛海滩？",a="这片海岸以暗矛部族命名，纪念他们从回音群岛撤离时在此登陆。它标志着该部族逃离扎拉赞恩阴险的政变后，在卡利姆多大陆上抵达的第一处安全之地。",al={"为什么叫暗矛海滩","暗矛海滩的名字由来","暗矛海滩名称起源"}}},fp="16,286,16.539.0,34.270.0,43.233.0,52.206.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="暗语峡谷",s="暗语峡谷是一道地势险峻、恶魔横行的峡谷，开凿在冬泉谷的南部高地上。当阿克蒙德在第三次战争的高潮中被消灭时，破碎的燃烧军团残部逃离了海加尔山的斜坡，并在这些崎岖的深渊中固守下来。如今，强大的恶魔在山岭间徘徊，守护着古老的矿产和黑暗的位面圣物。",h="暗语峡谷是一道地势险峻、恶魔横行的峡谷，开凿在冬泉谷的南部高地上。当阿克蒙德在第三次战争的高潮中被消灭时，破碎的燃烧军团残部逃离了海加尔山的斜坡，并在这些崎岖的深渊中固守下来。如今，强大的恶魔在山岭间徘徊，守护着古老的矿...",kw={"燃烧军团","暗语峡谷","地语者弗兰扎尔","暗影之眼","赫德瑞恩","赫德瑞恩女士","海加尔山","维'艾尔","冬泉谷"},ang={["class:Warlock"]="在这些洞穴中潜行的赫德瑞恩恶魔掌握着至关重要的位面组件，这使得该峡谷成为术士们磨练召唤仪式（例如召唤末日守卫）技艺的主要试炼场。",["profession:Mining"]="险峻的峡谷隐藏着丰富的真银和富瑟银矿脉，足以奖励那些敢于潜行绕过精英恶魔的胆大矿工。"},sec={{t="雪原中的军团据点",b="在海加尔山顶阿克蒙德战败后，燃烧军团幸存的恶魔四散逃往周边山脉。一支纪律严明的先遣队在暗语峡谷避难，将冬泉谷的南部边界变成了一个致命的据点。在赫德瑞恩女士的领导下，赫德瑞恩恶魔（包括致命的法力追猎者、屠戮者和见习者）在此盘踞，他们誓死保卫着地下的隧道和火热的营地。除了这些精英居民带来的直接威胁外，在峡谷的最低点还有一道阴森的密封拱门，暗示着通往神圣山脉更高处的封闭通道。"},{t="隐藏的试剂与稀有的知识",b="尽管存在巨大的危险，勇敢的冒险者和投机者仍会为了极其丰厚的财富而闯入峡谷。峡谷中盛产真银和密集的瑟银矿。在阴暗的洞穴深处，一些不寻常的居民在此苟延残喘，例如贩卖魔布和格罗姆之血等邪能试剂的维'艾尔，以及难以捉摸的高等精灵地语者弗兰扎尔，他掌握着关于熔炼稀有源质的古老冶金知识。"}},faq={{q="为什么冬泉谷会有这么多恶魔？",a="暗语峡谷中的恶魔是第三次战争期间燃烧军团入侵海加尔山后的幸存者。在阿克蒙德在世界之树被击杀后，他残破的军队并没有被完全消灭，而是撤退到了这些深渊中重整旗鼓。",al={"这里的恶魔来源","暗语峡谷军团背景","恶魔从哪里来"}},{q="峡谷后方的密封大门是什么？",a="在峡谷南部深处，矗立着一道刻满符文的拱门和一道活跃的魔法屏障。它守卫着直接通往海加尔山的山口；旅行者可以通过从永望镇飞行前往海加尔山的污染山麓。",al={"暗语峡谷传送门","冬泉谷副本入口","海加尔山大门"}},{q="这里的恶魔由谁领导？",a="营地由一群被称为赫德瑞恩的恶魔入侵者所控制，看起来是由赫德瑞恩女士指挥。他们与被称为法力追猎者的地狱犬、屠戮者和见习者一起在峡谷中巡逻。",al={"暗语峡谷首领","赫德瑞恩领袖","谁统治暗语峡谷"}},{q="为什么冒险者要冒险进入暗语峡谷？",a="该地区极其危险，需要协同作战的小队才能安全通行。然而，这里吸引了寻求位面绑定的术士、寻找稀有掉落物“暗影之眼”的牧师、寻找富瑟银矿脉的铁匠和矿工，以及寻找隐居的地语者弗兰扎尔的学者。",al={"为什么去暗语峡谷","暗语峡谷任务","暗语峡谷奖励"}}},fp="17,388,29.628.0,34.498.0,45.261.0,49.238.0,26.211.0,55.285.0"}
P.entries["subzone:darnassus"] = {n="达纳苏斯",s="在泰达希尔那连绵起伏的枝叶高处，坐落着卡多雷的避难之都——达纳苏斯。它依傍着宁静的水域和葱郁的林地而建，是暗夜精灵的精神核心，也是联盟在卡利姆多北部的关键堡垒。大祭司泰兰德·语风与大德鲁伊范达尔·鹿盔在此坐镇，指引着他们的人民度过刚刚获得凡人寿命后的重重考验。",h="在泰达希尔那连绵起伏的枝叶高处，坐落着卡多雷的避难之都——达纳苏斯。它依傍着宁静的水域和葱郁的林地而建，是暗夜精灵的精神核心，也是联盟在卡利姆多北部的关键堡垒。大祭司泰兰德·语风与大德鲁伊范达尔·鹿盔在此坐镇，指引着他们...",kw={"主城","达纳苏斯","卡多雷","鹿盔","泰达希尔","temple of the moon","泰兰德"},ang={["faction:Alliance"]="对于来自东部王国的旅客而言，达纳苏斯是一处与世隔绝、宁静祥和的避风港，也是联盟在卡利姆多大陆上不可或缺的锚点。",["race:NightElf"]="达纳苏斯是卡多雷的文化与政治中心，也是你们的人民在经历第三次战争的惨痛牺牲后，重新开始并获得主权庇护的地方。"},sec={{t="枝头上的避难所",b="达纳苏斯兴建于第三次战争之后，旨在纪念暗夜精灵在失去了神圣的世界之树诺达希尔所赋予的永恒寿命后依然得以幸存。与铁炉堡或暴风城那密集坚固的石质都市不同，达纳苏斯是一座开放且安详的定居点，处处可见木质建筑、闪烁的神龛，以及横跨晶莹湖泊的拱桥。警惕的哨兵、高耸的战争古树和塑造树木的德鲁伊们守护着这里的道路，确保大自然的宁静能在这座城市中得以保存。"},{t="分裂的领导层",b="虽然达纳苏斯代表了卡多雷的统一，但其治理结构却反映出微妙的分歧。大祭司泰兰德·语风在艾露恩神殿中主持民政与军事事务，身边环绕着艾露恩姐妹会。与此同时，塞纳里奥议会的事务则由大德鲁伊范达尔·鹿盔掌管，他曾主张种植泰达希尔以恢复精灵们失去的永恒寿命。由于玛法里奥·怒风在翡翠梦境深处陷入了神秘的沉睡，鹿盔对于种族未来的激进设想，常与性格更为沉稳的祭司阶层产生摩擦。"}},faq={{q="谁统治达纳苏斯？",a="大祭司泰兰德·语风在艾露恩神殿中作为暗夜精灵社会的主要领袖，统领着哨兵部队。德鲁伊事务则由大德鲁伊范达尔·鹿盔指挥，在玛法里奥·怒风缺席期间，由他领导塞纳里奥议会。",al={"达纳苏斯领袖","谁在管理达纳苏斯","暗夜精灵领袖"}},{q="旅客如何从泰达希尔外部到达达纳苏斯？",a="由于达纳苏斯坐落在巨大的世界之树岛屿的枝干之上，船只和飞行航线仅能抵达树根处的鲁瑟兰村。从鲁瑟兰村出发，有一座魔法传送门可以将访客传送至城内。",al={"如何前往达纳苏斯","达纳苏斯入口","进入达纳苏斯"}},{q="为什么达纳苏斯建城时间这么晚？",a="在第三次战争中海加尔山遭到破坏后，暗夜精灵失去了他们的永恒寿命和古老的生活方式。范达尔·鹿盔及其盟友在卡利姆多海岸外种植了泰达希尔，达纳苏斯便在其枝干上扎根，成为他们人民的一处新避难所。",al={"为什么达纳苏斯是新的","达纳苏斯是什么时候建造的","达纳苏斯历史"}},{q="玛法里奥·怒风在哪里？",a="大德鲁伊玛法里奥·怒风下落不明，他的灵魂被困在翡翠梦境中，陷入了一场深沉且原因未明的沉睡。他的缺席使得达纳苏斯的塞纳里奥议会完全交由范达尔·鹿盔领导。",al={"玛法里奥在哪里","玛法里奥在达纳苏斯吗","玛法里奥状态"}}},fx={["24a1a5b0"]={q="什么是达纳苏斯？",a="达纳苏斯是暗夜精灵的首都，坐落在新生世界之树泰达希尔巨大的枝干高处。城市环绕着一座宁静的湖泊，沐浴在暮光之中；第三次战争后，这里成为暗夜精灵文明的精神与文化中心。优雅的桥梁、由活木建成的居所和神圣的林地构成了城市的布局，巍然矗立的月神殿是其中心。达纳苏斯是联盟的庇护所，也见证着卡多雷对自然的崇敬。",al={"这个地方是什么","介绍达纳苏斯","达纳苏斯城市概况"}},["3a9c78e5"]={q="谁住在达纳苏斯？",a="这座城市主要由暗夜精灵居住，也欢迎德鲁伊、猎人、牧师和战士。大祭司泰兰德·语风与她的艾露恩姐妹会一起驻守在宏伟的月神殿；大德鲁伊范达尔·鹿盔则在塞纳里奥区统领塞纳里奥议会。警惕的哨兵巡逻各条大道，古老的守护者则在道路间徘徊。访客还会遇到其他联盟种族的使者，以及银色黎明等中立组织的代表。",al={"这里住着谁","达纳苏斯居民","达纳苏斯的居民"}},["0325f465"]={q="达纳苏斯危险吗？",a="对联盟成员而言，达纳苏斯是格外宁静的避难所，海洋和泰达希尔的高耸地势使其免受卡利姆多更严酷的威胁。这里由全副武装的哨兵和强大的古树守护者严密保护。不过，部落的成员会发现这里充满敌意，一旦进入，便会立即遭到城市守卫的攻击。",al={"达纳苏斯安全吗","达纳苏斯的威胁","达纳苏斯有什么危险吗"}}},fp="9,392,23.569.0,20.599.0,20.268.0,57.227.0,38.291.0,29.213.0"}
P.entries["subzone:darrow-hill"] = {n="达隆山",s="达隆山是一片位于希尔斯布莱德丘陵北部，紧邻海角下方，地势较高的崎岖草原。山狮和雄鹿在开阔的山坡上吃草，而凶猛的雪人则潜伏在点缀着山腰的丘陵洞穴内。这里蕴藏着丰富的奥特兰克花岗岩矿脉，是一个危险的前线，野兽和敌对的旅行者在此不断冲突。",h="达隆山是一片位于希尔斯布莱德丘陵北部，紧邻海角下方，地势较高的崎岖草原。山狮和雄鹿在开阔的山坡上吃草，而凶猛的雪人则潜伏在点缀着山腰的丘陵洞穴内。这里蕴藏着丰富的奥特兰克花岗岩矿脉，是一个危险的前线，野兽和敌对的旅行者在...",kw={"奥特兰克花岗岩","达隆山","丘陵洞穴","海角","希尔斯布莱德丘陵","雪人"},ang={["class:Hunter"]="这些山丘是山狮和雄鹿在奥特兰克林木线和下层草原之间移动时的绝佳狩猎场。",["profession:Mining"]="贯穿达隆山的洞穴网络，特别是丘陵洞穴，拥有丰富的奥特兰克花岗岩和区域矿脉，前提是你能够对付附近筑巢的雪人。"},sec={{t="危险的前线",b="达隆山坐落在海角下方北部的山脉脚下，连接着希尔斯布莱德南部的起伏牧场与奥特兰克崎岖寒冷的高地。山狮和雄鹿在高高的草丛中潜行，与从丘陵洞穴中涌出的高大雪人共享着这些岩石坡地。除了凶猛的野生动物，洞穴墙壁还隐藏着致密的奥特兰克花岗岩矿床，吸引着采石工、矿工和冒险者陷入危险之中。由于身处相互竞争的地区主张之间，其道路对于毫无防备的任何阵营的旅行者来说都极其危险。"}},faq={{q="达隆山位于何处？",a="达隆山位于希尔斯布莱德丘陵的北部边缘，坐落在被称为海角的岩石峭壁正南侧，以及通往奥特兰克的主要山路以东。",al={"达隆山位置","达隆山在哪里","达隆山地图"}},{q="哪些生物威胁着达隆山附近的旅行者？",a="开阔的山坡上有雄鹿和山狮徘徊，而野蛮的雪人则在丘陵洞穴周围和内部出没。",al={"达隆山怪物","达隆山有什么生物"}},{q="丘陵洞穴里有什么？",a="丘陵洞穴里到处是凶猛的雪人，岩石洞壁中还嵌有珍贵的奥特兰克花岗岩矿脉。",al={"丘陵洞穴","达隆山洞穴","洞穴里有什么"}},{q="为什么这个地区被认为对旅行者来说非常危险？",a="除了凶猛的野生动物和雪人巢穴外，直接邻近争议道路的开阔地理位置使达隆山成为了一个臭名昭著的冲突点，联盟和部落的漫游者经常在此相互伏击。",al={"为什么达隆山很危险","达隆山pvp","达隆山的危险"}}},fx={["35480940"]={q="什么是达隆山？",a="达隆山是一片高耸而崎岖的地带，位于希尔斯布莱德丘陵北部，紧贴着高耸的岬角山脉。野生动物在开阔的山坡上游荡，附近的丘陵洞穴则深入岩层之中，在宁静的地表下藏着地下危险。",al={"什么是达隆山","希尔斯布莱德的达隆山","达隆山信息"}}},fp="11,385,22.608.0,29.181.0,53.134.0,46.129.0,55.213.0"}
P.entries["subzone:darrowmere-lake"] = {n="达隆米尔湖",s="达隆米尔湖是一片广阔的淡水湖，位于西瘟疫之地的东南部。在湖心坐落着凯尔达隆的要塞岛，其废墟之下隐藏着The Cult of the Damned令人恐惧的通灵学院：通灵学院。",h="达隆米尔湖是一片广阔的淡水湖，位于西瘟疫之地的东南部。在湖心坐落着凯尔达隆的要塞岛，其废墟之下隐藏着The Cult of the Damned令人恐惧的通灵学院：通灵学院。",kw={"巴罗夫","凯尔达隆","达隆米尔","达隆米尔湖","普罗德摩尔舰队","通灵学院","索多里尔河","西瘟疫之地"},ang={["faction:Alliance"]="对于联盟老兵来说，达隆米尔湖是一处关键的海战前线，普罗德摩尔的舰队曾在此与旧部落交战。",["race:Undead"]="该湖泊标志着凯尔达隆的边界，生前的巴罗夫家族曾在此与巫妖王交易，将他们的家园变成了令人恐惧的通灵学院。"},sec={{t="一段传奇的内陆海",b="达隆米尔湖是东部王国最大的内陆水域之一，其边缘环绕着受瘟疫侵蚀的洛丹伦森林，由索多里尔河和达隆米尔河补给。在第二次战争期间，这些深邃的水域见证了部落与海军上将戴林·普罗德摩尔舰队之间激烈的海战。部落还袭击了位于湖心的凯尔达隆要塞，洗劫了它并夺走了那里的古老符文石。这里曾是巴罗夫家族繁荣的水路和贸易动脉，如今已变成瘟疫之地中心地带一片阴森、笼罩在迷雾中的盆地。"},{t="水面上的阴影",b="统治着湖中心的是凯尔达隆，这里曾是巴罗夫家族引以为傲的祖居地。在其破败的地基之下坐落着通灵学院，这是天灾军团主要的死灵法术与黑暗艺术学院。围绕着岛屿的水域停滞不前且危机四伏，反映了The Cult of the Damned黑暗的遗产。横渡湖面的冒险者不仅要面对瘟疫肆虐的乡野带来的危险，还必须抵御那座位于湖心堡垒所散发出的无尽恐惧。"}},faq={{q="达隆米尔湖位于哪里？",a="达隆米尔湖位于西瘟疫之地的东南角，北连索多里尔河，南接达隆米尔河。",al={"达隆米尔位置","达隆米尔湖在哪里","如何前往达隆米尔"}},{q="湖中心的岛上有什么？",a="岛上是凯尔达隆，这是一座古老的定居点，曾由贵族巴罗夫家族统治。在荒废的城镇之下坐落着通灵学院，这是一所由The Cult of the Damned运营的庞大黑暗魔法学院。",al={"达隆米尔岛屿","岛上有什么","凯尔达隆位置"}},{q="达隆米尔湖在第二次战争中扮演了什么角色？",a="该湖泊曾是一片充满争议的水域，普罗德摩尔的舰队在此与部落进行过海战。部落还突袭了位于湖心岛的凯尔达隆，洗劫了要塞并夺取了其古老的符文石。",al={"第二次战争达隆米尔","达隆米尔海战","达隆米尔历史"}},{q="船只还能驶入达隆米尔湖吗？",a="虽然在第二次战争期间大型海军舰队曾在此航行，但连接湖泊的河流如今出现了陡峭的瀑布和浅滩，使得大型船只无法从海上驶入。",al={"达隆米尔船只通行","船只能否到达达隆米尔"}}},fp="15,258,20.589.0,24.493.0,33.173.0,48.202.0,53.220.0,42.196.0"}
P.entries["subzone:darrowshire"] = {n="达隆郡",s="达隆郡是位于东瘟疫之地南部群山中的一座废墟村庄，曾经是洛丹伦一个宁静的小村落。在第三次战争期间，这里的居民为了对抗势不可挡的天灾军团，进行了一场绝望而悲壮的抵抗。如今，在寂静之中，这里只剩下残垣断壁、躁动的灵魂和苦涩的记忆。",h="达隆郡是位于东瘟疫之地南部群山中的一座废墟村庄，曾经是洛丹伦一个宁静的小村落。在第三次战争期间，这里的居民为了对抗势不可挡的天灾军团，进行了一场绝望而悲壮的抵抗。如今，在寂静之中，这里只剩下残垣断壁、躁动的灵魂和苦涩的记...",kw={"达隆郡之战","达隆郡","东瘟疫之地","食尸鬼","蹂躏者霍古斯","洛丹伦","玛杜克·布莱克伍德"},ang={["class:Paladin"]="达隆郡的悲惨命运不断呼唤着圣骑士们将净化的圣光带到瘟疫之地，既是为了消灭亡灵，也是为了让受尽折磨的灵魂得到安息。",["race:Human"]="对于联盟的人类来说，达隆郡是洛丹伦所遭受的毁灭性打击的严肃见证，这里曾经有普通民众为了保卫家人而进行过一场毫无希望的抵抗。"},sec={{t="悲壮的抵抗",b="在瘟疫吞噬北部洛丹伦之前，达隆郡曾是一个坐落在南部悬崖下的简朴乡村。当第三次战争期间天灾军团南下时，由死亡骑士玛杜克·布莱克伍德和食尸鬼领主蹂躏者霍古斯率领的部队围攻了这座城镇。村民和当地的守卫者英勇奋战，在绝境中暂时守住了防线。最终，防线崩溃，全镇上下惨遭屠戮，无一幸免。达隆郡许多阵亡的守卫者死后不仅没能得到安宁，反而被复活成了食尸鬼，成为了加强天灾军团实力的工具，使这座村庄成为了一座阴森、空旷、缅怀逝去勇气的纪念地。"},{t="战斗的回响",b="尽管早已被生者遗弃，达隆郡却远非空无一物。那场屠杀留下的沉重精神压力沉重地笼罩着这片山谷，将镇民的灵魂残片困在废墟之中。路过的旅人报告说这里会出现奇怪的现象，包括令人毛骨悚然的重现——那场悲惨的战斗会在幽灵般的寂静中再次上演。这片土地依然浸透着哀伤，成为了天灾军团从王国手中夺走一切的凄凉见证。"}},faq={{q="达隆郡发生了什么事？",a="达隆郡在第三次战争中被摧毁，当时一支庞大的天灾军团军队袭击了这座城镇。在死亡骑士玛杜克·布莱克伍德和食尸鬼领主蹂躏者霍古斯的带领下，亡灵淹没了城镇的守卫者并屠杀了所有居民，使这里沦为一片废墟。",al={"达隆郡历史","达隆郡为何被毁","这里发生了什么"}},{q="领导天灾军团袭击达隆郡的领袖是谁？",a="这次袭击由死亡骑士玛杜克·布莱克伍德和狰狞的食尸鬼领主蹂躏者霍古斯共同领导。他们的部队合力击溃了村庄的守卫者，使这里走向了毁灭。",al={"谁袭击了达隆郡","达隆郡的恶棍","霍古斯和玛杜克"}},{q="为什么达隆郡会有鬼魂出没？",a="那场屠杀发生得太过突然且惨绝人寰，导致阵亡者的灵魂依然被束缚在这片土地上。除了在破败的建筑中徘徊的鬼魂幻影外，据说那场残酷的战斗还会以幽灵的形式周期性地重演，将死者困在他们生命最后那悲惨的时刻。",al={"达隆郡的幽灵","为什么达隆郡会有灵魂"}},{q="那些保卫城镇而死的村民后来怎么样了？",a="大多数守卫者被当场屠杀，他们的尸体中有许多被通灵师复活成了毫无思想的食尸鬼，被迫为摧毁了他们家园的天灾军团效力。",al={"达隆郡村民","达隆郡的守卫者"}}},fp="11,321,14.670.0,20.468.0,29.284.0,58.190.0,27.294.0,57.200.0"}
P.entries["subzone:dawning-isles"] = {n="黎明岛",s="黎明岛是位于银松森林东缘、洛丹米尔湖内的一群低洼小岛。这里曾是风景优美的度假胜地，但如今已遭受亡灵瘟疫的侵蚀，并被好斗的鱼人所占据。",h="黎明岛是位于银松森林东缘、洛丹米尔湖内的一群低洼小岛。这里曾是风景优美的度假胜地，但如今已遭受亡灵瘟疫的侵蚀，并被好斗的鱼人所占据。",kw={"黎明岛","洛丹伦","洛丹米尔湖","银松森林","邪鳍"},ang={["faction:Alliance"]="这些受瘟疫侵蚀的岛屿沉重地提醒着人们，天灾军团的腐化究竟蔓延到了洛丹伦多么秀丽的水域。",["race:Undead"]="受瘟疫侵蚀的黎明岛位于洛丹米尔湖上，在幽暗城的西侧入口处清晰可见，而占据此地的邪鳍鱼人数量每年都在增加。"},sec={{t="湖中瘟疫",b="在第三次战争之前，黎明岛以洛丹米尔湖平静清澈水域上的风景胜地而闻名。当亡灵瘟疫席卷洛丹伦时，腐化渗入了湖泊的浅滩。植被变得苍白腐烂，昔日的宁静也随之消散。今天，邪鳍鱼人部落占据了泥泞的海岸和丛生的灌木丛，并凶猛地保卫着他们不断扩张的领地，阻拦任何试图横渡湖泊的人。"},{t="鱼人据点",b="鱼人并非岛上唯一的威胁。曾经有沼泽兽与它们一起在这些受瘟疫侵蚀的小岛上徘徊，但沼泽兽此后便消失了。随着它们的消失，邪鳍鱼人的数量激增，以至于鱼人现在彻底控制了这些岛屿，将原本宁静的岛链变成了它们在洛丹米尔湖上的据点。"}},faq={{q="黎明岛位于何处？",a="黎明岛位于洛丹米尔湖中，毗邻银松森林的东部边界，坐落在洛丹伦废墟的正西面。",al={"黎明岛位置","黎明岛在哪里","黎明岛地图"}},{q="黎明岛上栖息着哪些生物？",a="这些岛屿主要被邪鳍鱼人部落所盘踞，它们在受腐蚀的海岸线上繁衍生息。过去，危险的沼泽兽也会在这些小岛上徘徊，不过随着鱼人数量的泛滥，它们已基本绝迹。",al={"黎明岛怪物","黎明岛上的生物"}},{q="为什么这里的树木和海岸在腐烂？",a="在第三次战争期间，当亡灵瘟疫席卷洛丹伦时，这些岛屿受到了污染。水和土壤吸收了瘟疫，导致植被中毒，使得这些小岛变得阴暗、病态且腐朽。",al={"为什么黎明岛被瘟疫腐蚀","洛丹米尔湖瘟疫黎明岛"}}},fx={["501d8847"]={q="什么是黎明岛？",a="黎明岛是由一簇低矮岛屿组成的群岛，从洛丹米尔湖的水面上隆起，沿银松森林东北部延伸。这里曾被视为湖面上风景如画、宁静安逸的世外桃源，如今却在天灾瘟疫的持续侵蚀下日渐衰败。",al={"什么是黎明岛","黎明岛传说","介绍黎明岛"}},["425e68c2"]={q="黎明岛发生过什么？",a="黎明岛曾是洛丹米尔湖上 pristine 的小岛，却因天灾瘟疫蔓延而遭到毁坏，植被变得病弱，岸边也开始腐烂。鱼人和沼泽兽曾经席卷这些岛屿；沼泽兽如今已经消失，邪鳍鱼人则日益增多，已经控制了整片群岛。",al={"黎明岛历史","黎明岛发生了什么"}},d646a662={q="黎明岛安全吗？",a="不安全，那里极其危险。除了天灾瘟疫留下的腐烂痕迹，岛上还遍布极具攻击性的邪鳍鱼人；它们数量大增，会攻击任何闯入其领地的人。",al={"黎明岛安全吗","黎明岛有多危险","黎明岛的危险"}}},fp="13,248,18.460.0,19.353.0,36.149.0,41.250.0,42.205.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="黎明墓穴",s="黎明墓穴深凿于乌鸦岭墓地之下，是一座黑暗的迷宫，里面充满了暮色森林中最凶猛的不死生物。那些敢于进入这些地下隧道的人，将面临成群结队的骷髅守卫和食肉食尸鬼的围攻。",h="黎明墓穴深凿于乌鸦岭墓地之下，是一座黑暗的迷宫，里面充满了暮色森林中最凶猛的不死生物。那些敢于进入这些地下隧道的人，将面临成群结队的骷髅守卫和食肉食尸鬼的围攻。",kw={"地下室","黎明墓穴","暮色森林","食尸鬼","乌鸦岭墓地","骷髅","不死生物"},ang={["class:Paladin"]="这座墓穴是王国陨落者的冷酷见证，它呼唤着圣光的愤怒来净化这些被亵渎的陵墓。",["class:Priest"]="在乌鸦岭的石拱顶下，不安的灵魂和腐烂的尸体呼喊着寻求最终的安息，使得墓穴成为了对信仰的严峻考验。"},sec={{t="乌鸦岭下方",b="在暮色森林笼罩在暮光诅咒之前很久，黎明墓穴曾是周边森林逝者的安息之所。如今，这些深埋在破败的乌鸦岭墓地之下的黑暗石廊，囚禁着该地区最致命的不死生物。墓穴分为两个截然不同的地下侧翼：西侧通道由守护先祖陵墓的骷髅卫兵把守，而东侧通道则通向一个充满饥饿、携带瘟疫的食尸鬼的恶臭巢穴。独自前来的旅行者很少能从其深处生还。"}},faq={{q="黎明墓穴位于何处？",a="墓穴位于暮色森林最西端的乌鸦岭墓地正下方。入口位于地面上纵横交错的墓碑和破败的地下室之间。",al={"墓穴位置","黎明墓穴在哪里","如何前往墓穴"}},{q="墓穴中潜伏着什么？",a="墓穴中盘踞着暮色森林中最密集、最凶猛的不死生物。西侧侧翼由全副武装的骷髅战士守卫，而东侧隧道则遍布着野蛮且身染瘟疫的食尸鬼。",al={"墓穴敌人","黎明墓穴里有什么","墓穴怪物"}},{q="墓穴最初为何建造？",a="早在该地区还是一片葱郁之时，墓穴作为当地家族和名人的大型墓葬拱顶而被开凿。后来吞噬森林的黑暗诅咒使得那些被埋葬的人重新复活了。",al={"墓穴历史","为什么要建造墓穴","墓穴的原始用途"}},{q="独自探索墓穴安全吗？",a="独自冒险进入墓穴是非常危险的。幽闭的隧道几乎没有撤退的空间，不死生物会密集成群，以极具侵略性的攻势压垮落单的旅行者。",al={"我可以单刷墓穴吗","墓穴危险性","墓穴难度高吗"}}},fx={fdcc93ff={q="什么是黎明墓穴？",a="黎明墓穴是一座蜿蜒曲折的地下迷宫，开凿在暮色森林西部广阔的乌鸦岭墓地下方。这里最初是为了安葬当地死者而挖掘的，如今却被森林中最凶猛、疾病缠身的亡灵占据。墓穴分为两大区域，一侧成了狂暴食尸鬼的污秽巢穴，另一侧则有手持武器的骷髅守卫徘徊。",al={"什么是墓穴","黎明墓穴概况","乌鸦岭墓穴"}},["514fe1a3"]={q="进入黎明墓穴危险吗？",a="深入墓地之下是暮色森林中最致命的行动之一。墓穴里挤满了无情的亡灵，独自行走的旅人很快就会在漆黑中被它们淹没。东侧区域遍布携带疾病、会撕裂血肉的食尸鬼；西侧则由久经战阵的骷髅哨兵把守，它们守望着遭亵渎的墓穴。若没有经验丰富的盟友同行，走下这些阶梯几乎必死无疑。",al={"墓穴危险","墓穴危险吗","墓穴有多危险"}}},fp="22,245,18.565.0,45.180.0,32.215.0,48.206.0,42.206.0"}
P.entries["subzone:dead-acre"] = {n="死亡农地",s="死亡农地是一片位于西部荒野东南部，靠近通往暮色森林的河桥处，早已荒废且冒着余烟的农庄。在迪菲亚潜行者于乡间发动起义时，这里被付之一炬，如今焦黑的田地已被人们遗弃，只剩下失控的收割傀儡在徘徊。",h="死亡农地是一片位于西部荒野东南部，靠近通往暮色森林的河桥处，早已荒废且冒着余烟的农庄。在迪菲亚潜行者于乡间发动起义时，这里被付之一炬，如今焦黑的田地已被人们遗弃，只剩下失控的收割傀儡在徘徊。",kw={"烧毁的农场","死亡农地","迪菲亚","农场","收割守望者","西部荒野"},ang={["faction:Alliance"]="死亡农地是暴风城忽视西部荒野的凄凉写照，让忠诚的农民在面对迪菲亚潜行者的暴力掠夺时毫无防卫能力。"},sec={{t="边境的灰烬",b="死亡农地位于连接哨兵岭与暮色森林的道路北侧，曾经是西部荒野众多粮仓农场中颇有产出的一处家园。当迪菲亚潜行者发动叛乱并驱逐了当地地主时，这座农场遭到了毁灭性的打击。农舍及其周边的作物被付之一炬，只留下焦黑的木材、冒烟的土地，以及依然在荒芜的土地上收割作物的机械收割守望者。"}},faq={{q="这个地方为什么叫死亡农地？",a="迪菲亚潜行者在控制西部荒野时，将该农庄及其周边的田地夷为平地。正是因为他们留下的焦黑废墟和冒烟的土地，才让这里获得了这样一个阴森的名字。",al={"为什么叫死亡农地","死亡农地发生了什么","它为什么被烧毁"}},{q="为什么会有机械收割守望者在这里徘徊？",a="像西部荒野各地的许多农场一样，当定居者逃离或死亡时，他们留下了用于照料庄稼的机械收割机。由于损坏或缺乏看管，这些自动化的收割守望者继续在烧焦的田地里无休止地巡逻，并攻击任何靠近的人。",al={"死亡农地的收割傀儡","为什么这里有傀儡","收割守望者"}},{q="死亡农地在哪里？",a="死亡农地坐落在西部荒野东南部，紧邻通往暮色森林阴影边境的桥梁北侧主路旁。",al={"死亡农地位置","死亡农地在哪里","如何找到死亡农地"}}},fx={["6eb41297"]={q="什么是死亡农地？",a="死亡农地是西部荒野东南部一处被毁、仍冒着烟的旧农庄，靠近通往暮色森林的河桥。这里曾是肥沃的农田，如今只剩焦黑的土地和烧毁的残骸。",al={"什么是死亡农地","西部荒野的死亡农地","死亡农地传说"}},e7e3cf0f={q="死亡农地发生过什么？",a="迪菲亚潜行者控制西部荒野各地时，他们的袭击者放火烧毁了这座农庄和周围的田地。建筑被彻底摧毁，只留下冒烟的废墟和毁坏的作物田。",al={"死亡农地发生了什么","死亡农地为何被毁","死亡农地历史"}},["80cb4842"]={q="死亡农地为何沦为废墟并被遗弃？",a="迪菲亚潜行者夺取该地区时，将这座农场夷为平地。家园被付之一炬，土地也遭到焚毁，原来的农民不是被赶走就是被杀害，留下的田地仍冒着余烬，彻底荒废。",al={"死亡农地为何被遗弃","死亡农地被烧毁","死亡农地为何成为废墟"}},["3f91a783"]={q="死亡农地危险吗？",a="危险。敌对的机械收割守望者会在焦土上巡逻，攻击任何误入这片余烬未熄之地的旅人或农民。",al={"死亡农地危险吗","死亡农地的威胁","死亡农地的敌人"}}},fp="9,279,19.446.0,39.213.0,51.282.0,31.148.0"}
P.entries["subzone:dead-field"] = {n="亡者农场",s="亡者农场位于银松森林北部，是一处荒废、被枯萎病侵蚀的农庄。这里曾经是宁静的乡村农田，但现在已被腐皮豺狼人占据，并被改造成了天灾军团的前线集结地。被遗忘者多次尝试清剿该地区，却都在女妖夜刃的指挥下无功而返。",h="亡者农场位于银松森林北部，是一处荒废、被枯萎病侵蚀的农庄。这里曾经是宁静的乡村农田，但现在已被腐皮豺狼人占据，并被改造成了天灾军团的前线集结地。被遗忘者多次尝试清剿该地区，却都在女妖夜刃的指挥下无功而返。",kw={"女妖","亡者农场","死亡猎手","夜刃","腐皮","银松森林","图勒·鸦爪"},ang={["class:Rogue"]="死亡猎手侦察小队密切监视着农场；渗透进豺狼人的队伍并打击其指挥系统是一项关键的战术重点。",["race:Undead"]="对被遗忘者而言，天灾军团在亡者农场的立足点对连接瑟伯切尔和洛丹伦北部的道路构成了直接威胁，必须尽快将其清除。"},sec={{t="一处受枯萎病侵蚀的集结地",b="位于银松森林北部的这片农庄早已所剩无几，其原本的居民在第三次战争中早已丧生。如今，这片废墟成了腐皮豺狼人的行动基地，他们甘愿充当天灾军团的走卒。随着这些豺狼人的数量不断增加，路过该地区的死亡猎手斥候发现了他们即将进行军事动员的迹象，这威胁到了被遗忘者的补给线和哨所。被遗忘者对该农场进行的小规模突袭屡屡失败，每当她的豺狼人奴仆陷入险境，女妖夜刃这只哀嚎的幽灵就会现身将其击退。"},{t="鸦爪的野心",b="腐皮豺狼人并非孤军奋战。他们在亡者农场的行动是由驻扎在芬里斯岛的死灵法师图勒·鸦爪在幕后策划的。为了确立天灾军团对银松森林的统治并以此将希尔瓦娜斯的军队逐出洛丹伦，鸦爪将魔法幻象投射到农场，以视察他的亡灵爪牙并向闯入的被遗忘者发出警告。"}},faq={{q="什么是亡者农场？",a="亡者农场位于银松森林北部，是一处破败不堪、受枯萎病侵蚀的农庄。它曾是一座普通的人类农场，如今已沦为废墟，并被效忠于天灾军团的腐皮豺狼人所占据。",al={"亡者农场 银松森林","亡者农场在哪里","亡者农场发生了什么"}},{q="为什么农场里有豺狼人？",a="这些腐皮豺狼人受到天灾军团的控制。他们将这处农庄当作前线集结地，用以集结兵力，准备袭击银松森林北部的被遗忘者阵地。",al={"为什么有腐皮豺狼人","腐皮豺狼人 亡者农场","天灾军团豺狼人"}},{q="夜刃是谁？",a="夜刃是天灾军团的一名女妖，负责指挥农场里的腐皮豺狼人。每当被遗忘者的突击部队进攻营地时，她就会现身保卫她的奴仆，击退了以往多次收复该地区的尝试。",al={"夜刃 女妖","亡者农场里的女妖","谁在保护豺狼人"}},{q="这里的天灾军团由谁指挥？",a="这个营地听命于图勒·鸦爪，他是一位强大的死灵法师，驻扎在附近的芬里斯岛。他通过幻象和魔法监视来协调豺狼人的行动，以此骚扰被遗忘者的扩张。",al={"谁控制着亡者农场","图勒·鸦爪 亡者农场","谁负责指挥"}}},fx={["8ddbb760"]={q="亡者农场发生了什么？",a="这座农场曾是银松森林北部的一处家园，不过原来农民的姓名和命运都已湮没在第三次战争之中。王国覆灭后，这片土地日渐荒败，天灾军团的爪牙也随之进驻。天灾军团没有耕种作物，而是将废弃的土地改造成据点，集结亡灵豺狼人，准备威胁附近被遗忘者的领地。",al={"亡者农场的历史","亡者农场发生了什么","谁住过亡者农场"}},["00a3cfa2"]={q="谁控制着亡者农场？",a="亡者农场被腐皮豺狼人占据，它们为天灾军团充当步兵。女妖夜鞭潜伏在它们之上，负责看守据点，并会在她的爪牙遭到攻击时现身。死灵法师 Thule Ravenclaw 则从远处协调它们的行动，借助幻影指挥它们对付被遗忘者。",al={"谁掌管亡者农场","谁住在亡者农场","亡者农场的居民"}},["242af2de"]={q="亡者农场为何被遗弃？",a="和银松森林北部的大部分地区一样，这座农场在天灾军团席卷洛丹伦时覆灭。居民或被杀害，或被迫逃离，再无人照料土地或维护建筑。农场无人看管，周围又是遭受瘟疫侵蚀的土地，天灾军团很快便占据了腐朽的谷仓和破败的围栏，将此处用作前线集结地。",al={"亡者农场为何成为废墟","亡者农场为何被遗弃","亡者农场废墟"}},fd654559={q="亡者农场危险吗？",a="独自在此旅行极其危险。腐皮豺狼人聚集的人数越来越多，预示着天灾军团即将发起攻势。被遗忘者多次突袭，仍未能将它们赶走，因为夜鞭总会迅速现身保护她的仆从，使任何正面交锋都演变成与凶猛豺狼人和幽灵哀嚎者的致命战斗。",al={"亡者农场有多危险","亡者农场的威胁","亡者农场安全吗"}}},fp="10,327,25.616.0,20.386.1,23.196.0,33.202.0,17.220.0,37.198.1"}
P.entries["subzone:deadeye-shore"] = {n="死眼海岸",s="死眼海岸是杜隆塔尔东部边缘的一片风蚀海岸，位于枯水谷正东方。这片荒凉沙滩得名于传说中的血环氏族酋长基尔罗格·死眼，主要有野生迅猛龙、蝎毒虫和野猪在此游荡。",h="死眼海岸是杜隆塔尔东部边缘的一片风蚀海岸，位于枯水谷正东方。这片荒凉沙滩得名于传说中的血环氏族酋长基尔罗格·死眼，主要有野生迅猛龙、蝎毒虫和野猪在此游荡。",kw={"血环氏族","死眼海岸","枯水谷","杜隆塔尔","基尔罗格·死眼"},ang={["race:Orc"]="对于在杜隆塔尔建立新国家的兽人来说，这片海岸旨在纪念基尔罗格·死眼，提醒他们那些在艾泽拉斯战争期间塑造了部落历史的老酋长们。"},sec={{t="血环氏族的海岸",b="死眼海岸延伸在杜隆塔尔中部红色峭壁之下，得名于在第一次和第二次战争中奋战的血环氏族独眼酋长基尔罗格·死眼。从高空俯瞰，沙地和岩石露头隐约呈现出一个缺失眼眶的头骨形状。虽然这里没有大型定居点或军事哨所，但海岸绝非安宁之地：凶猛的野生动物占据着沙滩，而且据传来自火刃氏族的邪教徒经常从附近峡谷的藏身处潜行到水边。"}},faq={{q="为什么叫死眼海岸？",a="这条海岸是以血环氏族著名酋长基尔罗格·死眼命名的。这里的天然海岸地形也酷似一个缺失眼睛的头骨，呼应了酋长本人失明的眼眶。",al={"谁是死眼","为什么叫死眼海岸","名字起源"}},{q="谁住在死眼海岸？",a="死眼海岸上没有永久定居点。这片海岸主要栖息着当地的野生动物，如迅猛龙、蝎毒虫和野猪，不过渔民和旅行者偶尔会经过这里——有时会遭遇隐秘的火刃氏族邪教徒。",al={"这里有哪些人","死眼海岸的定居点","死眼海岸的非玩家角色"}},{q="在死眼海岸附近能发现什么威胁？",a="除了具有攻击性的当地野兽外，最大的危险来自邻近的枯水谷。隶属于火刃氏族的邪教徒偶尔会从岩石峡谷中游荡至海岸，伏击毫无防备的旅行者和渔民。",al={"死眼海岸的危险","这里的敌人","火刃氏族与死眼"}}},fx={["46f1927a"]={q="死眼海岸是什么地方？",a="死眼海岸是杜隆塔尔东缘的一段崎岖海岸，正位于枯水谷以东。这里以被阳光晒得发白的沙滩和面朝无尽之海的岩石峭壁为特色，基本与部落已定居的区域隔绝。",al={"死眼海岸是什么地方","死眼海岸概况","死眼海岸在哪里"}},["01a709cb"]={q="死眼海岸发生过什么？",a="除了以血环氏族酋长基尔罗格·死眼之名命名外，这段海岸几乎没有留下多少有记载的历史。这里至今仍因地处偏僻而对游荡者构成危险，沙滩上有迅猛龙、蝎子和野猪出没。",al={"死眼海岸的历史","这里发生了什么","死眼海岸的事件"}}},fp="13,271,34.569.0,31.205.0,30.263.0,44.243.0"}
P.entries["subzone:deadman-s-crossing"] = {n="死者十字",s="死者十字是位于逆风小径荒凉峡谷中的一个令人不祥的交汇点。它连接着暮色森林、悲伤沼泽以及闹鬼的卡拉赞高塔，此处有着绞刑架和警示牌，是一个阴森的关隘。尽管外表恐怖，但对于穿行于东部王国南部的旅人来说，这条路依然是一条至关重要的通道。",h="死者十字是位于逆风小径荒凉峡谷中的一个令人不祥的交汇点。它连接着暮色森林、悲伤沼泽以及闹鬼的卡拉赞高塔，此处有着绞刑架和警示牌，是一个阴森的关隘。尽管外表恐怖，但对于穿行于东部王国南部的旅人来说，这条路依然是一条至关重要...",kw={"死者十字","逆风小径","暮色森林","绞刑架","绞刑树","卡拉赞","路标牌","悲伤沼泽"},ang={["faction:Alliance"]="对于从夜色镇前往诅咒之地守望堡的联盟信使来说，穿过死者十字是最快，但也最令人不安的路线。",["faction:Horde"]="从斯通纳德向西前往暮色森林的部落游荡者必须经过这处阴森的地标，这也是对前方被侵蚀的人类土地的初步体验。"},sec={{t="阴森的交叉路口",b="死者十字坐落于逆风小径的东部路口，将暮色森林的阴影与悲伤沼泽的浑浊深处连接起来，而一条不祥的南部小径则向上通往闹鬼的卡拉赞高塔。这个十字路口得名于岔路口那棵扭曲的绞刑树，树上悬挂着两具腐烂的尸体，作为对所有过路人的严酷警告。树旁还有几块破损的木牌，上面写着直白的忠告，催促旅人回头并放弃希望。峡谷本身充斥着敌对的野兽和黑暗魔法，但只要旅人们坚定地沿着泥土路前行，不误入荒芜的岩石区，十字路口本身却意外地没有受到骚扰。"}},faq={{q="从死者十字出发的每条路通向哪里？",a="向西走会带你离开山谷，进入闹鬼的暮色森林。向东走则直接进入悲伤沼泽的湿地。沿着蜿蜒的南部小径前行，则会带你深入逆风小径的腹地，前往被诅咒的废墟和宏伟的卡拉赞高塔。",al={"道路通向何处","交叉路口方向","死者十字的路径"}},{q="吊在树上的尸体是谁？",a="他们的身份已无从考证。多年来，逆风小径吞噬了无数不幸的游荡者、强盗和难民，有人竖起了这棵绞刑树，将其作为一种令人毛骨悚然的边界标志，用来警告那些试图前行的旅人。",al={"悬挂的尸体","树上的死尸","谁被绞死了"}},{q="死者十字对旅人来说安全吗？",a="令人惊讶的是，是的。虽然逆风小径周围的峭壁和洞穴中充斥着凶猛的秃鹫、幽灵和食人魔，但十字路口及其东西走向的主路依然畅通。只要不偏离踩出的土路，低等级的信使和冒险者都可以安全地在暮色森林和悲伤沼泽之间穿行。",al={"是否安全","路上会遭到袭击吗","危险等级"}},{q="路口的牌子上写着什么？",a="风化的木制路标上写着不祥的警告：一块牌子上直白地指示旅人“回头！”，而另一块则警告说“在此经过者，放弃所有希望吧”，毫不掩饰这个山谷的危险本质。",al={"路标","路标写了什么","放弃希望的标牌"}}},fp="18,369,19.745.0,50.280.0,42.237.0,41.339.0,38.220.0"}
P.entries["subzone:deadmines"] = {n="死亡矿井",s="在月溪镇尘土飞扬的鬼镇下方，死亡矿井是一座庞大的地下迷宫，曾经是人类领土上最大的黄金产地。它在第一次战争期间被废弃，长期以来一直有闹鬼的传闻。现在有传言称，邪恶势力已在这些被遗忘的矿道中扎根，但深处潜藏着何种危险仍是一个谜。",h="在月溪镇尘土飞扬的鬼镇下方，死亡矿井是一座庞大的地下迷宫，曾经是人类领土上最大的黄金产地。它在第一次战争期间被废弃，长期以来一直有闹鬼的传闻。现在有传言称，邪恶势力已在这些被遗忘的矿道中扎根，但深处潜藏着何种危险仍是一个...",kw={"死亡矿井","迪菲亚潜行者","艾德温·范克里夫","铁甲湾","铁甲无畏舰","洛萨","月溪镇","希斯耐特","范克里夫","西部荒野"},ang={["class:Paladin"]="死亡矿井对圣骑士来说具有神圣的意义：安度因·洛萨爵士曾在第一次战争期间深入其最黑暗的密室，从野蛮的食人魔手中找回了神圣法典。",["profession:Mining"]="第一次战争前，这些矿道是人类采矿业的明珠，在被地精机械和迪菲亚歹徒接管之前，曾是人类领土上最大的黄金产地。"},sec={{t="金与血的矿脉",b="第一次战争前，死亡矿井是人类领土上首屈一指的采矿点，盛产黄金以及用于木材和结构支撑的坚固的Whitestone oak。当兽人部落向北推进时，矿井被仓促废弃。安度因·洛萨爵士曾冒险深入其危险的深处，试图找回神圣法典，他在地底食人魔手中被囚禁了二十个月后才获救。在王国陷落后的动荡中，矿道变得寂静无声，并因被诅咒而恶名远扬。"},{t="范克里夫的铸造厂",b="在暴风城的石匠工会暴乱之后，新成立的迪菲亚潜行者占领了这个地下建筑群，将其作为主要避难所。当暴风城的矿工联盟在工头希斯耐特的带领下试图重开隧道时，迪菲亚强盗伏击了工人，摧毁了矿道，导致被杀害的矿工变成了游荡的亡灵。如今，在食人魔打手和地精技师的保护下，迪菲亚潜行者已将深处的隧道改造成了一个工业化战争营地，其核心是铁甲湾的地下造船厂。"}},faq={{q="如何进入死亡矿井？",a="主入口隐藏在Defias Hideout内，位于西部荒野西南部的月溪镇废墟中。穿过地下室蜿蜒向下，即可直接进入庞大的矿道。",al={"死亡矿井入口位置","如何进入死亡矿井","死亡矿井位置"}},{q="矿井最初为何被废弃？",a="它们是在第一次战争期间被废弃的，当时部落占领了王国的南部地区。随着战争爆发和食人魔迁入地下，采矿作业停止了，废弃的隧道很快就有了闹鬼的名声。",al={"死亡矿井为何关闭","死亡矿井为何被废弃"}},{q="迪菲亚潜行者在下面建造什么？",a="在铁甲湾被淹没的洞穴深处，艾德温·范克里夫和雇佣的地精工程师正在建造一艘巨大的铁甲无畏舰。范克里夫打算驾驶这艘战舰沿海岸直上，轰炸并围攻暴风城以进行报复。",al={"死亡矿井里有什么","范克里夫在死亡矿井的计划","铁甲湾的战舰"}},{q="入口隧道附近游荡的亡灵是谁？",a="他们是矿工联盟的不幸工人，由工头希斯耐特领导。当联盟试图勘测并收复矿井时，迪菲亚暴徒伏击了他们并导致矿道坍塌，被困的矿工们死后化作了躁动不安的食尸鬼。",al={"死亡矿井的亡灵矿工","死亡矿井的工头希斯耐特","死亡矿井为什么有食尸鬼"}},{q="安度因·洛萨与死亡矿井有什么联系？",a="第一次战争期间，安度因·洛萨爵士深入死亡矿井，执行找回神圣法典的任务。他被居住在洞穴中的食人魔俘虏，被关押了近两年才最终获救。",al={"洛萨与死亡矿井","安度因·洛萨与死亡矿井"}}},fx={fb059910={q="死亡矿井是什么地方？",a="死亡矿井是一片庞大而曲折的隧道网络，位于西部荒野和荆棘谷北部的地下，入口设在鬼镇月溪镇。在第一次战争之前，这些矿道是人类领地中最大的黄金产地。兽人入侵引发的混乱使矿井遭到废弃，此后又长期因闹鬼的传闻而无人问津。如今，这座庞大的地下迷宫已被迪菲亚潜行者秘密占据，成为他们的主要行动基地。",al={"死亡矿井是什么地方","死亡矿井概况","死亡矿井的传说"}},["00c1b6a4"]={q="谁控制着死亡矿井？",a="迪菲亚潜行者完全控制着这座迷宫。在艾德温·范克里夫的领导下，这些心怀不满的石匠和强盗以武力夺取了洞窟，击溃了试图在此作业的矿工联盟工人。在矿井深处，范克里夫指挥着庞大的迪菲亚盗贼网络、受雇的地精工程师、食人魔打手和盟友匪徒，他们为实现对暴风城王国的复仇而效力。",al={"谁住在死亡矿井","谁掌管死亡矿井","死亡矿井的阵营"}},["3042a935"]={q="死亡矿井危险吗？",a="极其危险。上层隧道里到处都是不得安息的亡灵矿工和凶狠的强盗，深处则由迪菲亚潜行者严密设防。闯入者除了要面对持械歹徒和冷酷的监工，还会遭遇地精制造的战争机器、致命的熔炉、食人魔蛮力打手以及用于防御的火药炸药。人民军认为，没有技艺高超的盟友陪同就进入这片区域，无异于自寻死路。",al={"死亡矿井危险吗","死亡矿井的危险","死亡矿井有多危险"}}},fp="9,375,24.558.0,18.534.1,34.211.1,48.245.0,50.256.1,55.259.0,57.250.0"}
P.entries["subzone:deadwood-village"] = {n="死木村",s="死木村是一个位于费伍德森林南部的熊怪营地。该部族曾经是一个热爱自然、爱好和平的部族，但其居民最终未能幸免于那片森林中肆虐的恶魔腐蚀。受到邪能侵染而陷入疯狂的死木熊怪现在会攻击任何靠近其简陋木制定居点的人。",h="死木村是一个位于费伍德森林南部的熊怪营地。该部族曾经是一个热爱自然、爱好和平的部族，但其居民最终未能幸免于那片森林中肆虐的恶魔腐蚀。受到邪能侵染而陷入疯狂的死木熊怪现在会攻击任何靠近其简陋木制定居点的人。",kw={"腐蚀","死木","死木村","费伍德森林","熊怪","木喉"},ang={["class:Druid"]="死木村象征着自然防线的一场心碎溃败，提醒着塞纳里奥德鲁伊们：恶魔的腐蚀能将原本和平的生物扭曲到何种深渊。"},sec={{t="堕落的部族",b="死木村位于费伍德森林南缘附近，是死木部族的主要聚居地。当燃烧军团的恶魔能量席卷这片古老的林地时，熊怪们无力抵御那不断蔓延的腐化。他们的心智被邪恶扭曲，放弃了古老的传统与心灵的和谐。如今，这个村庄聚集着一群充满敌意的野蛮人、萨满祭司和巢穴守卫，他们暴力地抗击着试图进入这片受污染土地的入侵者，也令他们未受腐化的同族——木喉部族——感到无比绝望。"}},faq={{q="为什么这里的熊怪带有敌意？",a="死木村的熊怪在第三次战争期间被那场摧毁费伍德森林的恶魔腐蚀所吞噬。邪能魔法扭曲了他们本性，使其变得极度狂暴，让他们陷入疯狂并对所有外来者抱有敌意。",al={"死木部族敌意","为什么攻击","为什么死木熊怪是红名"}},{q="玩家可以与死木村沟通或建立和平吗？",a="不可以。死木部族已经彻底腐化，无法进行和平外交。冒险者通常通过狩猎他们来收集部族羽毛，从而获得在北方隧道守卫的、未受腐化的木喉熊怪的青睐。",al={"能与死木部族友好吗","死木部族声望"}},{q="这个部族与木喉部族有什么关系？",a="两支部族曾经都是与自然和谐共处的典型熊怪部族。当费伍德森林遭受腐蚀时，木喉部族设法保持了理智，而死木部族则完全屈服于邪能的疯狂。如今，木喉部族将死木部族视为堕落且危险的存在。",al={"木喉部族与死木部族","熊怪部族"}}},fp="16,310,14.566.0,34.245.0,56.221.0,44.272.0"}
P.entries["subzone:deathknell"] = {n="丧钟镇",s="丧钟镇是一座坐落在提瑞斯法林地西南方一处隐蔽山谷中的设防村落。它是新近摆脱巫妖王控制、加入被遗忘者阵营的亡灵觉醒的首要之地。这座定居点深受无意识的天灾余孽、当地狂热分子以及极具攻击性的野生动物的围困，对于那些想要在希尔瓦娜斯·风行者的王国中寻求一席之地的人来说，这是一个严酷的试炼场。",h="丧钟镇是一座坐落在提瑞斯法林地西南方一处隐蔽山谷中的设防村落。它是新近摆脱巫妖王控制、加入被遗忘者阵营的亡灵觉醒的首要之地。这座定居点深受无意识的天灾余孽、当地狂热分子以及极具攻击性的野生动物的围困，对于那些想要在希尔瓦...",kw={"丧钟镇","被遗忘者新手区","无意识者","夜行蜘蛛洞穴","灰影墓穴","希尔瓦娜斯","提瑞斯法林地"},ang={["faction:Horde"]="尽管孤立且黑暗，但这座山谷是被遗忘者王国的门户，为部落在东部王国的立足点输送了新鲜的士兵。",["race:Undead"]="每一位被遗忘者冒险者都始于此地，从灰影墓穴冰冷的土地中站起，在瘟疫的恐怖之后，在希尔瓦娜斯女王的庇护下寻找目标与避难所。"},sec={{t="被遗忘者的摇篮",b="丧钟镇隐藏在银松森林边界以北崎岖的群山之后，是新觉醒的亡灵第一次睁开双眼直面凄凉现实的地方。与提瑞斯法林地中大多数保留了洛丹伦王国陨落前人类名称的定居点不同，丧钟镇是由占领这里的亡灵明确更名的。城镇本身被一分为二：被遗忘者顽强地盘踞在旧教堂周围的南部地区，而北部地区（包括村里的铁匠铺）仍被无意识的天灾僵尸和野性食尸鬼所占据。精英死亡卫士牢牢封锁了通往山谷的狭窄峡谷，抵御入侵者，使当地的看管人能够引导新来者为女妖之王效力。"},{t="被围困的山谷",b="在丧钟镇的生存危机四伏。在西北方，夜行蜘蛛洞穴——一座对被遗忘者初创经济至关重要的金矿——已经被可怕的蜘蛛所占据。在东南方，一个好战的血色十字军营地保持着严密的监视，他们与东部的要塞往来信使，并不断试探山谷的防御。与此同时，村里的看管人必须持续不断地击退在北部废墟中游荡的无意识亡灵，并收集废金属、工具和补给，以装备新生的灵魂，迎接前方的漫长道路。"}},faq={{q="这座城镇为什么改名为丧钟镇？",a="丧钟镇是在成为亡灵定居点后才更名的，这与提瑞斯法林地大多数保留人类名称的社区不同。这一新名称的由来尚不为人所知。",al={"丧钟镇名称由来","为什么要叫丧钟镇","丧钟镇的旧称"}},{q="为什么城镇的北部被亡灵占据？",a="并不是每一个在第三次战争后复活的尸体都能保持神智清醒。北部的村庄广场和铁匠铺被“无意识者”所占据——这些野性的僵尸、食尸鬼和骷髅仍然受到天灾军团残留意志的驱使。被遗忘者的防御者经常清理它们，以回收装备并保卫教堂。",al={"为什么丧钟镇有僵尸","丧钟镇的天灾军团","丧钟镇的无意识者"}},{q="血色十字军在丧钟镇附近做什么？",a="一支血色十字军分遣队在村庄东南方的山丘上维持着一个营地。他们狂热地致力于不加区分地消灭所有亡灵，监视着山口，伏击新觉醒的被遗忘者，并与其他洛丹伦境内的血色十字军要塞交换侦察情报。",al={"丧钟镇的血色十字军营地","丧钟镇外的十字军","提瑞斯法林地的血色十字军"}},{q="为什么被遗忘者无法使用当地的金矿？",a="夜行蜘蛛洞穴是位于村庄西北方悬崖上的一座金矿，现已完全被充满攻击性的蜘蛛所占据。像黄金这样的自然资源对于被遗忘者的战争努力至关重要，但在清理掉这些虫害之前，该定居点无法开采矿脉。",al={"丧钟镇矿洞","夜行蜘蛛洞穴","提瑞斯法林地的蜘蛛矿洞"}}},fx={["1ab0c524"]={q="丧钟镇是什么地方？",a="丧钟镇是被遗忘者的一处小型定居点，坐落在提瑞斯法林地西南部一处隐蔽的山谷中，紧邻银松森林边界以北。这里是新近获得自由的亡灵苏醒之地，新复生者会在此受到接待、评估和训练。村庄分为两部分：被遗忘者占据教堂附近的南部区域，而北部区域及其古老的铁匠铺仍被没有心智的亡灵占据。",al={"这是什么地方","丧钟镇村庄","关于丧钟镇"}},ae63ed0c={q="它以前曾是普通的村庄吗？",a="是的。第三次战争蹂躏这片土地之前，丧钟镇曾是洛丹伦王国境内一座有人居住的人类村庄。亡灵瘟疫席卷乡间时，村民们相继死去，又被复生为天灾军团的奴仆。与提瑞斯法其他保留原有人类名称的城镇不同，这座村庄后来被遗忘者改名为丧钟镇。",al={"丧钟镇的过去","丧钟镇以前是人类村庄吗","旧丧钟镇"}},["2ffa4d6f"]={q="这里以前住着什么人？",a="最初的居民是洛丹伦王国的普通人类臣民，包括农民、铁匠和镇民。天灾军团摧毁王国时，许多人遭到屠杀或被瘟疫腐化，被埋葬在山坡上的墓地和地穴里，或变成至今仍在北部废墟游荡的无心奴仆。",al={"谁住过这里","丧钟镇的原居民","以前的村民"}},e9c17660={q="丧钟镇为何沦为废墟或被遗弃？",a="亡灵瘟疫吞噬洛丹伦时，这座城镇在第三次战争中沦陷。此后，被遗忘者只收复了教堂周围的南部区域。包括铁匠铺在内的北部建筑仍被遗弃，并遭天灾军团留下的敌对亡灵占据，防守者至今未能将它们彻底肃清。",al={"丧钟镇为何被毁","丧钟镇为何破败","丧钟镇废墟"}},af76d1fc={q="丧钟镇危险吗？",a="离开南部边界后，这里非常危险。没有心智的亡灵在城镇北部游荡，西北方附近的金矿里则盘踞着巨型夜行蜘蛛。更糟的是，东南方就驻扎着一支狂热的血色十字军营地，他们会定期突袭村庄。",al={"丧钟镇安全吗","丧钟镇的危险","丧钟镇的威胁"}},["9b2c91d1"]={q="我为什么会变成亡灵？我身上发生了什么？",a="你在洛丹伦沦陷期间死去，成了巫妖王释放的可怕亡灵瘟疫的受害者。你的尸体被复生，编入天灾军团，被迫服从主人的铁腕意志。第三次战争之后，巫妖王的控制力减弱，你的心智挣脱了束缚，让你在死去的躯体中重新获得了自由意志。",al={"我为什么是亡灵","我是怎么死的","我身上发生了什么"}},["4fca782c"]={q="我以前活着吗？",a="是的。在第三次战争令这个国度陷入毁灭之前，你曾是洛丹伦的一名凡人居民。在瘟疫夺走你的性命、邪恶魔法重塑你的尸体之前，你有自己的生活、家园和凡人牵绊。",al={"我以前活着吗","我以前是人类吗","我过去的生活"}},["37eab6c0"]={q="我还记得过去的生活吗？",a="许多亡灵仍保留着前世支离破碎而令人痛苦的记忆，也记得自己受巫妖王奴役时被迫犯下的种种暴行。对大多数被遗忘者而言，这些记忆是挥之不去的折磨，也是无声复仇的源头。",al={"我还记得吗","亡灵的过往记忆","被遗忘者的记忆"}},e26c7288={q="被遗忘者是什么人？",a="被遗忘者是摆脱巫妖王控制、拥有智慧和自由意志的亡灵，他们在第三次战争后脱离了天灾军团。在希尔瓦娜斯·风行者女士的集结和领导下，他们在洛丹伦废墟中开辟了家园，并在幽暗城建立了首都。",al={"被遗忘者是什么人","被遗忘者阵营","被遗忘者是什么"}},b31080e3={q="我们和其他亡灵有什么不同？",a="艾泽拉斯绝大多数亡灵都属于天灾军团，完全受巫妖王的精神控制。你和其他被遗忘者挣脱了束缚，重新获得了意识、自主权和自由意志。",al={"被遗忘者和天灾军团有什么区别","我们是天灾军团吗","拥有自由意志的亡灵"}},["7fbc82e5"]={q="我们为什么加入部落？",a="被敌对的生者王国和永无止境的天灾军团包围，被遗忘者独自面对着彻底毁灭的命运。他们与远在海对岸的部落结成了权宜之盟，以在东部王国取得一处北方立足点为交换，获得必要的军事支持，共同求得生存。",al={"为什么加入部落","被遗忘者与部落结盟"}},c317a133={q="大家常提到的黑暗女王是谁？",a="她就是希尔瓦娜斯·风行者女士，女妖之王，也是被遗忘者的统治者。她曾是银月城游侠将军，在天灾入侵奎尔萨拉斯期间被阿尔萨斯王子杀害，并被转化为女妖。后来她摆脱了巫妖王的意志，集结叛离天灾的亡灵，并夺回了洛丹伦的地下墓穴。",al={"黑暗女王","黑暗女王是谁","女妖之王"}},["1b5563f2"]={q="无脑僵尸是什么？他们以前不也是被遗忘者吗？",a="他们从来都不是被遗忘者。瘟疫使洛丹伦的死者复生时，许多人丧失了理智与高等思维能力，沦为只受基本捕食本能驱使的野蛮躯壳。由于他们没有心智可供挣脱控制，也无法做出选择，因此仍是敌对的天灾爪牙。",al={"无脑僵尸","无脑僵尸是什么","丧钟镇的僵尸"}},["68a4c897"]={q="我也可能变成那样吗？",a="是的。瘟疫复活的无数尸体都遭受了彻底的精神退化，再也无法恢复理智或意识。你能保住智慧和自我意识，而许多人却沦为无脑的野兽，这纯属运气或意志坚定。",al={"我会变成无脑僵尸吗","我为什么没有变成无脑僵尸","变成无脑僵尸的风险"}},["05e3a89b"]={q="血色十字军是什么？他们为什么攻击我们？",a="血色十字军是由白银之手骑士团残部和洛丹伦幸存人类组成的狂热组织。他们对所有亡灵都怀有狂热的仇恨，不肯区分嗜血的天灾军团与拥有自由意志的被遗忘者，并企图彻底清除洛丹伦境内的一切亡灵。",al={"血色十字军是什么","血色十字军为什么攻击我们","血色十字军"}},b4877dc1={q="他们曾经是白银之手的一员吗？",a="是的。第三次战争期间，乌瑟尔·光明使者逝世、王都沦陷后，白银之手骑士团分崩离析。幸存的圣骑士和牧师联合起来对抗亡灵，最终逐渐扭曲成了你如今看到的狂热十字军。",al={"血色十字军与白银之手","血色十字军曾是圣骑士吗","白银之手的起源"}},["56471820"]={q="骷髅牢笼里的骷髅是什么？他们为什么敌视我们？",a="骷髅牢笼里的骷髅是天灾军团的傀儡，由洛丹伦死者的骸骨通过通灵术复活而成。它们没有独立意志，也没有活人的血肉，直接受巫妖王残留的通灵束缚驱使，会屠杀任何闯入的生者或叛离天灾的亡灵。",al={"骷髅牢笼里的骷髅","骷髅牢笼里的骷髅为何攻击","敌对的骷髅"}},["574ed092"]={q="他们不也是和我一样的亡灵吗？",a="他们和你一样都是亡灵，但敌对的骷髅牢笼里的骷髅并没有展现出被遗忘者所具有的自由意志和自我意识。它们为天灾军团效力，执行毁灭性的任务。",al={"骷髅牢笼里的骷髅是亡灵吗","骷髅不也和我们一样吗","骷髅是亡灵"}},["9d34c29a"]={q="夜行蜘蛛是什么？它们从哪里来的？",a="夜行蜘蛛是有毒的蛛形纲动物，曾侵占丧钟镇西北方的金矿和周围的山谷。提瑞斯法遭受瘟疫而日渐枯萎时，当地害虫发生变异并变得凶暴，占据了山谷，将被遗忘者赶离了重要的金矿。",al={"夜行蜘蛛","蜘蛛从哪里来","矿洞里的夜行蜘蛛"}},["22acb08e"]={q="离开丧钟镇之后呢？布瑞尔有什么？",a="离开丧钟镇所在的山谷，就会进入提瑞斯法林地，前往布瑞尔。布瑞尔是规模更大的被遗忘者城镇，那里有市政厅、恐惧之末旅店和训练师。从那里出发，道路继续向南通往幽暗城。",al={"离开丧钟镇之后","布瑞尔有什么","离开丧钟镇后去哪里"}},["969b7b3b"]={q="幽暗城在什么方向？",a="幽暗城位于丧钟镇以东。要前往那里，你需要沿山谷北面的道路离开，经过布瑞尔，再向南前往王都废墟下方。",al={"幽暗城在哪里","怎么去幽暗城","幽暗城的方向"}},["95231242"]={q="我是怎么来到丧钟镇的？",a="洛丹伦遭天灾军团摧毁时，你死去了，被埋在村庄上方灰影墓穴的墓室中。巫妖王对亡灵的铁腕控制减弱后，你的意识骤然恢复。你从墓穴中挣脱出来，沿着山坡来到丧钟镇。被遗忘者聚集在此，接纳刚刚苏醒的尸体，看看他们是否拥有为黑暗女王效力的意志。",al={"我是怎么来到这里的","我为什么在这里","我从哪里来"}},["6fb0c436"]={q="我在丧钟镇应该做什么？",a="你要证明自己对被遗忘者有用，并守住这片山谷。新近苏醒的亡灵必须证明自己没有被村庄周围徘徊的无脑天灾夺去心智。当地首领需要你铲除失控的僵尸，清理附近金矿里的蜘蛛，并击退企图将亡灵逐出提瑞斯法林地的血色十字军狂热分子，之后你才能被派往布瑞尔。",al={"我在这里该做什么","我在这里的目标是什么","我的任务是什么"}},["3bebe502"]={q="为什么新生的亡灵要从丧钟镇开始？",a="丧钟镇是被遗忘者安置新近苏醒死者的地方。周围的山丘和墓穴，尤其是灰影墓穴，埋葬着数千名第三次战争期间阵亡的洛丹伦人。巫妖王的精神控制日渐衰弱，尸体便不断在此复生，并保有自己的自由意志。驻扎在山谷各处的亡灵卫兵会拦下新近复生者，为幸存者提供庇护和指引，免得他们被疯狂吞噬或遭敌对的十字军杀害。",al={"亡灵为什么从这里开始","我为什么从丧钟镇开始","亡灵为什么从丧钟镇开始"}}},fp="10,405,22.740.0,20.560.0,36.169.0,55.350.0,50.302.0,47.283.0"}
P.entries["subzone:decrepit-ferry"] = {n="破旧渡口",s="破旧渡口是位于银松森林东岸的一处损毁码头，曾经提供横跨洛丹米尔湖通往芬里斯岛的航运。洛丹伦陷落后，渡口被摧毁，摆渡人遭到谋杀，而岸边也被亡灵和凶残的腐皮豺狼人所占据。",h="破旧渡口是位于银松森林东岸的一处损毁码头，曾经提供横跨洛丹米尔湖通往芬里斯岛的航运。洛丹伦陷落后，渡口被摧毁，摆渡人遭到谋杀，而岸边也被亡灵和凶残的腐皮豺狼人所占据。",kw={"破旧渡口","芬里斯岛","摆渡人","食尸鬼","洛丹米尔湖","腐皮","天灾军团","银松森林"},ang={["race:Undead"]="这些遗迹是洛丹伦陨落的残酷见证，如今这里充斥着麻木的天灾残党和肮脏的豺狼人，威胁着被遗忘者在银松森林东部的行动。"},sec={{t="中断的生命线",b="在第三次战争之前，这里曾是往返于洛丹米尔湖的繁忙码头。当地农民将新鲜农产品运到水边，直接卖给芬里斯岛上富有的领主及其家眷。只需支付少许费用，摆渡人便会运送贸易货物、信使以及往来于大陆和城堡之间的贵族。然而随着天灾军团横扫王国，这种和平的贸易戛然而止。摆渡人被残忍杀害，船只被砸毁，码头也随之荒废。"},{t="被腐蚀的湖岸",b="如今，对于任何途经湖岸的旅行者来说，这些码头都是一处险境。渡口停止运营后，芬里斯岛孤悬于对岸，而遗迹本身则爬满了食尸鬼、骷髅战士和四处游荡的腐皮豺狼人。曾经秩序井然的交通枢纽，如今已成为银松森林中又一个令人不安的危险之地。"}},faq={{q="破旧渡口最初的用途是什么？",a="它是银松森林大陆与芬里斯岛之间的主要渡口。当地农民利用渡轮将收获的庄稼运过洛丹米尔湖，卖给岛上的贵族领主，并为每次航行向当地的摆渡人支付少量费用。",al={"渡口历史","这个码头是做什么的","为什么这里有渡口"}},{q="渡口和摆渡人发生了什么事？",a="当天灾军团入侵洛丹伦时，码头遭到了袭击。摆渡人被谋杀，船只和航运装备被摧毁，该地点也被遗弃给了亡灵。",al={"摆渡人怎么了","谁摧毁了渡口"}},{q="现在有什么怪物潜伏在渡口附近？",a="湖岸上充斥着天灾军团的残党，包括食尸鬼和骷髅战士，同时附近的岸边还有危险的腐皮豺狼人出没。",al={"破旧渡口的怪物","渡口有什么生物"}},{q="还能从这里乘船去芬里斯岛吗？",a="不能。渡口在入侵期间损毁，如今已是一片废墟。任何想要前往芬里斯岛的人必须游泳或寻找跨越湖泊的其他途径。",al={"乘船去芬里斯","如何前往芬里斯岛","渡口还能用吗"}}},fx={e48e8d6c={q="破旧渡口是什么地方？",a="破旧渡口是银松森林东岸一处昔日繁忙码头的废墟。洛丹伦沦陷之前，这里是横渡洛丹米尔湖前往芬里斯岛的重要渡口，负责运送当地农民、旅客和物资前往岛上的庄园。",al={"破旧渡口是什么","银松森林的破旧渡口","破旧渡口码头"}},db91f3d1={q="破旧渡口为什么成了废墟，还被废弃了？",a="天灾军团席卷洛丹伦时，渡船服务也惨遭终结。摆渡人被亡灵大军杀害，船只被砸毁，凶猛的掠食者占据周围海岸，码头也彻底荒废。",al={"为什么这里被废弃了","破旧渡口为什么成了废墟","破旧渡口被毁"}},e3243651={q="破旧渡口危险吗？",a="是的，毫无戒心的旅人来到这里会面临极大危险。废弃的码头和岸边到处都是凶暴的食尸鬼、不得安息的骷髅战士和野化的腐皮豺狼人，任何人若在渡口附近逗留，都可能丧命。",al={"破旧渡口危险吗","破旧渡口的威胁","这里安全吗"}},bec7dabe={q="为什么叫破旧渡口？",a="第三次战争后，这里满目疮痍、腐朽破败，因而得了这个阴森的名字。它曾是通往芬里斯岛的坚固繁忙的生命线，如今只剩下风化的木梁、碎裂的残骸和被水浸泡的废墟。",al={"为什么叫破旧渡口","破旧渡口的名称","破旧渡口名称的由来"}}},fp="14,288,20.523.0,21.349.0,48.241.0,44.175.0,46.158.0,51.155.0"}
P.entries["subzone:deep-elem-mine"] = {n="埃利姆矿洞",s="埃利姆矿洞是坐落在银松森林腹地的一处挖掘场。它曾经是一处活跃的矿场，但在大法师阿鲁高的黑暗魔法席卷该地区时被占领，矿工们被转化为了野蛮的狼人。",h="埃利姆矿洞是坐落在银松森林腹地的一处挖掘场。它曾经是一处活跃的矿场，但在大法师阿鲁高的黑暗魔法席卷该地区时被占领，矿工们被转化为了野蛮的狼人。",kw={"阿鲁高","达拉尔·道恩维沃尔","埃利姆矿洞","苍白的格里姆森","银松森林","瓦里玛萨斯","狼人"},ang={["profession:Mining"]="尽管由于内部盘踞着狂暴的狼群而目前十分危险，但该矿洞仍是银松森林最丰富的地下矿产矿床之一。",["race:Undead"]="对于被遗忘者来说，确保矿洞的安全既是经济上的必要，也是来自瑟伯切尔的直接指令，旨在打破阿鲁高在银松森林中部不断扩张的控制力。"},sec={{t="野兽巢穴",b="埃利姆矿洞位于银松森林中心地带，曾经作为洛丹伦的居民获取资源的普通矿脉。当大法师阿鲁高将狼人的梦魇释放到森林中时，他那狂暴的诅咒也蔓延到了矿洞深处。矿工们没能抵御诅咒，纷纷化作凶残的狼人，他们丢下手中的镐头，将这片洞穴变成了捕食者的巢穴。"},{t="格里姆森与被遗忘者的野心",b="矿洞内的狼人族群由苍白的格里姆森统领，他曾是这里的工头，即便在遭受怪物般的转变后仍保留着狡诈。由于意识到这些矿洞及其矿石的战略价值，瑟伯切尔的被遗忘者对收复该地点产生了浓厚的兴趣。在恐惧魔王瓦里玛萨斯的权威命令下，被遗忘者的特工们试图砍下格里姆森的头颅并肃清这些野兽，以便部落能够夺取矿洞的财富。"}},faq={{q="埃利姆矿洞里有什么？",a="矿洞中盘踞着受大法师阿鲁高魔法影响的敌对狼人。他们由昔日的人类工头苍白的格里姆森领导，他现在统治着矿洞深处的狼人群落。",al={"埃利姆矿洞里有什么","埃利姆矿洞怪物","谁住在埃利姆矿洞"}},{q="为什么被遗忘者想要清理埃利姆矿洞？",a="被遗忘者寻求开发矿洞的天然矿产财富，以加强他们在洛丹伦的战争努力。在消灭这些狼人后，达拉尔·道恩维沃尔和瑟伯切尔的领导层打算以恐惧魔王瓦里玛萨斯的名义夺取这些资源。",al={"被遗忘者对矿洞的兴趣","为什么要清理埃利姆矿洞","谁想要这座矿洞"}},{q="苍白的格里姆森是谁？",a="格里姆森原本是监管埃利姆矿洞运营的人类工头。在阿鲁高的野性诅咒将工人们转化后，格里姆森变成了一个狡诈的狼人阿尔法，他保留了足够的智慧来指挥居住在矿洞中的狼群。",al={"格里姆森是谁","苍白的格里姆森背景故事","埃利姆矿洞首领"}},{q="狼人是怎么进入矿洞的？",a="他们并不是从外面搬进来的；原本的矿工们是在大法师阿鲁高的诅咒横扫银松森林时发生了转化，劳动力在他们工作的地方直接变成了怪物。",al={"为什么矿洞里有狼人","埃利姆矿洞狼人起源","矿工是如何转化的"}}},fx={["3a795aef"]={q="埃利姆矿洞为何被废弃？",a="阿鲁高大法师的邪恶巫术席卷银松森林的群山后，矿洞便沦陷了。矿洞并非单纯遭到外敌侵袭，而是从内部崩溃：矿洞的工头Grimson the Pale染上狼人诅咒，变成了野兽盘踞的巢穴。",al={"埃利姆矿洞为何被废弃","埃利姆矿洞毁坏","是什么毁了埃利姆矿洞"}},ee2e1c55={q="埃利姆矿洞危险吗？",a="毫无准备地闯入埃利姆矿洞极其危险。漆黑的隧道里到处都是受捕猎本能驱使的凶残狼人，它们全都听命于冷酷无情的前任监管者Grimson the Pale。",al={"埃利姆矿洞危险吗","埃利姆矿洞安全吗","埃利姆矿洞里的威胁"}},["1f4b67a8"]={q="埃利姆矿洞是什么地方？",a="埃利姆矿洞是银松森林中部山丘里的一处古老矿场。这里曾由人类监督开采，如今已停止日常作业，并落入阿鲁高大法师的黑暗巫术所造就的野化狼人手中。",al={"埃利姆矿洞","埃利姆是什么","银松森林埃利姆矿洞"}}},fp="14,224,15.397.0,29.457.1,30.188.0,48.257.0,24.243.0,37.196.0"}
P.entries["subzone:deeprun-tram"] = {n="矿道地铁",s="矿道地铁是侏儒工程学的地下杰作，连接着联盟的首都铁炉堡和暴风城。在第二次战争后，国王麦格尼·铜须下令修建了这条地铁，让平民和士兵能够在短短几分钟内穿越地底的遥远距离。这段封闭的双轨铁路穿过群山与湖泊，成为了联盟军事支援与商业往来的重要大动脉。",h="矿道地铁是侏儒工程学的地下杰作，连接着联盟的首都铁炉堡和暴风城。在第二次战争后，国王麦格尼·铜须下令修建了这条地铁，让平民和士兵能够在短短几分钟内穿越地底的遥远距离。这段封闭的双轨铁路穿过群山与湖泊，成为了联盟军事支援与...",kw={"矿道地铁","dwarven district","gelbin mekkatorque","magni bronzebeard","地下湖","地铁","工匠镇"},ang={["faction:Alliance"]="地铁是连接联盟两座最坚固首都的主要战略大动脉，能够在几分钟内实现部队的快速部署和相互防御。",["profession:Engineering"]="整条铁路是一项无与伦比的侏儒杰作，展示了先进的轨道推进技术、能够承受地下湖水压力的加固玻璃工艺，以及复杂的电力切换站。"},sec={{t="地下工程学的奇迹",b="第二次战争造成的破坏令国王麦格尼·铜须感到忧心，他对于矮人的援助与建筑补给物资跨越重重山脉前往暴风城的速度之慢感到日益不满。为了解决物流障碍并确保矮人军队能在危机时刻迅速增援人类首都，麦格尼找到了大工匠Gelbin Mekkatorque。这位侏儒工程大师起草了一份由尖端技术驱动的封闭式地下铁路方案。尽管挖掘过程中困难重重——包括直接穿过巨大的地下湖泊，以及与地下鼠群不断的抗争——矿道地铁最终成为了联盟的一座巅峰成就，免费运送数以千计的旅客往返于铁炉堡和暴风城之间。"}},faq={{q="为什么要建造矿道地铁？",a="第二次战争结束后，国王麦格尼·铜须需要一种更快捷的方式来运送补给物资和矮人部队，以协助重建和保卫暴风城。他委托大工匠Gelbin Mekkatorque起草并执行了这项地下铁路工程，将两座首都无缝连接起来。",al={"为什么要修地铁","地铁的用途","谁建造了矿道地铁"}},{q="地铁是如何在水下运行的？",a="在丹莫罗和暴风城之间的挖掘过程中，侏儒工程师穿透了一座巨大的地下湖泊。他们没有绕道而行，而是直接在深水中建造了一条密封的加固玻璃观景隧道，让乘客可以观察到在轨道旁游弋的野生大口雷象和鲨鱼。",al={"地铁水下观景窗","水下地铁","矿道地铁湖泊"}},{q="为什么轨道沿线有这么多老鼠？",a="潮湿阴暗的地下坑道为害虫提供了理想的繁殖地。侏儒站长们时刻都在努力防止鼠群咬断电缆或占领站台，偶尔不得不依靠旅行者和像蒙蒂这样的捕鼠人来控制它们的数量。",al={"矿道地铁老鼠","为什么地铁里有老鼠","老鼠问题"}},{q="乘坐地铁需要收费吗？",a="不需要。作为铁炉堡和暴风城政府共同支持的一项公共与军事项目，矿道地铁全天候运行，对所有联盟公民和盟友免费开放。",al={"地铁费用","地铁票价","坐地铁要花多少钱"}}},fx={a94670c5={q="什么是矿道地铁？",a="矿道地铁是由侏儒设计的地下及水下铁路系统，连接着联盟的两座首都铁炉堡和暴风城。铁路由复线和两组各含三节车厢的列车组成，为旅客提供往返矮人山地要塞与人类王国的快捷免费交通。",al={"什么是矿道地铁","矿道地铁介绍","关于矿道地铁"}},a0c9cf68={q="矿道地铁发生过什么？",a="第二次战争结束后，国王麦格尼·铜须希望能更快地运送矮人补给和部队，帮助重建饱受战火摧残的暴风城王国。他委托大工匠Gelbin Mekkatorque设计地下线路。施工期间，工程队遭遇了一座意料之外的地下湖，还要应对不断侵扰的鼠群，但铁路最终还是建成了，并成为联盟不可或缺的生命线。",al={"矿道地铁历史","矿道地铁的历史","矿道地铁是如何建成的"}},c0b14a4e={q="谁负责维护和运营矿道地铁？",a="侏儒工程师每天都会检修矿道地铁，确保机械车厢在两座首都之间平稳安全地运行。除了工程人员，车站和隧道里还常有当地商贩、铁路工人，以及Monty这样的害虫捕手出没。Monty不辞辛劳地试图控制铁轨沿线屡禁不绝的鼠群。",al={"谁运营矿道地铁","矿道地铁工作人员","谁在矿道地铁工作"}},["2e1a8782"]={q="矿道地铁危险吗？",a="乘坐地铁本身十分平稳安全，它的设计足以让旅客安全穿行于山脉和地下水域之下。然而，徒步走上轨道会让你暴露在飞驰的车厢和臭名昭著的地铁鼠群面前。加固玻璃管道之外，巨齿鲨和鲨鱼等水生掠食者潜伏在黑暗的湖底，与乘客安全隔开。",al={"矿道地铁危险吗","地铁安全吗","矿道地铁里的危险"}}},fp="12,410,36.774.0,31.306.0,36.317.0,44.293.0,25.192.0"}
P.entries["subzone:deepwater-tavern"] = {n="深水旅店",s="深水旅店是米奈希尔港内熙熙攘攘的海边旅店，坐落在湿地（Wetlands）那潮湿的沼泽地之中。这里是往来于繁忙港口城镇的旅人和水手们主要的聚会、补给和休息点。在畅饮美酒和打听港口传闻之余，客人们经常能在这里找到工作，或是不小心卷入混乱的酒馆斗殴中。",h="深水旅店是米奈希尔港内熙熙攘攘的海边旅店，坐落在湿地（Wetlands）那潮湿的沼泽地之中。这里是往来于繁忙港口城镇的旅人和水手们主要的聚会、补给和休息点。在畅饮美酒和打听港口传闻之余，客人们经常能在这里找到工作，或是不...",kw={"深水旅店","急救训练师","旅店老板","米奈希尔港","tapoke slim jahn","酒馆斗殴","湿地"},ang={["faction:Alliance"]="深水旅店是联盟成员往返于铁炉堡和无尽之海之间的重要集结地和休息港湾。"},sec={{t="米奈希尔港的中心",b="深水旅店矗立在米奈希尔港潮湿的街道上，为旅客们提供了一个躲避户外那终年细雨、险象环生的沼泽地的避风港。水手、码头工人、商人和疲惫的冒险者们聚集在木梁之下，交流新闻、围坐在温暖的火堆旁，或是处理他们的伤口。除了常规的港口旅店设施外，这里还有一位常驻的急救训练师和当地商人，为那些即将深入沼泽或踏上前往无尽之海旅程的人们提供服务。这里气氛嘈杂，偶尔也潜藏着危险；因为打翻麦芽酒而引发的争吵总是迅速升级，像Tapoke 'Slim' Jahn这样的臭名昭著的麻烦制造者就经常引发全酒馆范围的斗殴。"}},faq={{q="深水旅店在哪里？",a="深水旅店位于米奈希尔港的滨海区域，这是卡兹莫丹（Khaz Modan）西海岸湿地（Wetlands）的主要港口城镇。",al={"深水旅店位置","深水旅店在哪里","米奈希尔港旅店"}},{q="酒馆里有哪些服务？",a="除了常规的旅店住宿和餐饮服务外，酒馆内还有商人及一位急救训练师，使其成为冒险者穿越沼泽地时关键的补给和治疗点。",al={"深水旅店服务","米奈希尔旅店训练师","在深水旅店能找到什么"}},{q="谁经常在酒馆里挑起斗殴？",a="这家酒馆以自发的打斗而闻名，一个名叫Tapoke 'Slim' Jahn的狡猾捣乱者经常在喧闹的顾客和水手之间挑起斗殴。",al={"米奈希尔酒馆斗殴","tapoke slim jahn","谁在深水旅店挑起争斗"}},{q="为什么酒馆这么繁忙？",a="米奈希尔港是连接卡兹莫丹和卡利姆多的主要航运和海军门户。作为镇上唯一的正规旅店，它吸引了源源不断的水手、雇佣兵和前往湿地（Wetlands）的联盟冒险者。",al={"为什么要造访深水旅店","为什么深水旅店很受欢迎"}}},fx={d7fa1340={q="什么是深水旅店？",a="深水旅店是湿地联盟海港米奈希尔港的主要旅店和社区中心。途经卡兹莫丹的水手、商人、旅客和冒险者都会在此歇脚、购买补给、寻求医疗救助或接取当地的差事。它依然是沼泽地最热闹的聚集点之一。",al={"什么是深水旅店","湿地的深水旅店","米奈希尔港的旅店"}},e51423df={q="深水旅店危险吗？",a="深水旅店位于米奈希尔港内，受到联盟保护，十分安全，但绝不安静。醉酒的客人和性格鲜明的常客经常在酒馆大厅里大打出手，惹事生非的Tapoke Slim Jahn往往是争端的导火索。在这里要保持警惕，不过在旅店屋檐下，你几乎不会遇到真正的危险。",al={"深水旅店安全吗","深水旅店打斗","深水旅店危险吗"}}},fp="16,353,24.710.0,38.146.0,46.202.0,43.163.0,26.220.0"}
P.entries["subzone:defias-hideout"] = {n="Defias Hideout",s="Defias Hideout是一座坐落在月溪镇南缘的不起眼的废弃房屋。虽然它与周围破败的定居点融为一体，但其二楼隐藏着一条通往城镇下方黑暗地下室的陆路通道。",h="Defias Hideout是一座坐落在月溪镇南缘的不起眼的废弃房屋。虽然它与周围破败的定居点融为一体，但其二楼隐藏着一条通往城镇下方黑暗地下室的陆路通道。",kw={"死亡矿井","迪菲亚","defias hideout","入口","月溪镇","范克里夫","西部荒野"},ang={["class:Rogue"]="该藏身处是秘密防御的典范：通过将通往巨大地下要塞的入口伪装成一座不起眼的破败庄园，迪菲亚人将其实际规模隐藏在暴风城的巡逻视线之外。",["faction:Alliance"]="这座破旧的庄园是艾德温·范克里夫阴谋的门户，对于寻求终结迪菲亚叛乱的联盟冒险者来说，这里是一个关键的集结地。"},sec={{t="废墟中的入口",b="在普通人眼中，Defias Hideout看起来就像月溪镇中任何其他被洗劫一空的庄园或农舍，充斥着赤贫的流浪汉和迪菲亚潜行者。然而，它朴素的内部掩盖了艾德温·范克里夫在南方行动的指挥中心。登上二楼会发现一个通向死亡矿井庞大迷宫的入口。由于迪菲亚兄弟会将其人力集中在守卫月溪镇的周边地区，并让劳工深入地下工作，因此藏身处本身的守卫并不多，更多是作为一个受到严密监控的关卡，而非一个活跃的堡垒。"}},faq={{q="Defias Hideout里面有什么？",a="建筑内有一道楼梯通向一条蜿蜒的隧道，这是通往死亡矿井的陆路入口。除了游荡的流浪汉和零星的强盗外，建筑本身大多是空的，主要起到一个守卫入口的作用。",al={"defias hideout内部","藏身处入口","这里有什么"}},{q="为什么藏身处内部守卫相对较少？",a="迪菲亚兄弟会将武装力量集中在月溪镇的街道上，以便在入侵者靠近之前进行拦截，而其余的劳工和执行者则在矿井深处忙碌工作。",al={"为什么是空的","迪菲亚在哪里","为什么守卫这么少"}},{q="这座建筑在月溪镇的什么位置？",a="该藏身处位于西部荒野西南部的月溪镇南缘，是一座靠近山脚下的大型完好双层建筑。",al={"如何找到藏身处","defias hideout在哪里","藏身处位置"}},{q="谁在藏身处周围徘徊？",a="该建筑和周边城镇中聚集了迪菲亚强盗以及绝望的流浪汉，他们因逃离贫困或出于生存需要而加入了兄弟会。",al={"流浪汉是谁","月溪镇流浪汉","迪菲亚成员"}}},fx={["34bb7c5e"]={q="什么是Defias Hideout？",a="Defias Hideout是月溪镇一座饱经风霜的建筑，这座城镇如今被强盗占据。从外面看，它不过是一栋被流浪汉占据的废弃房屋，但楼上藏着一处入口，可直接通往死亡矿井——迪菲亚潜行者庞大的地下据点。",al={"defias hideout","这是什么建筑","什么是defias hideout"}},d0a92509={q="为什么叫Defias Hideout？",a="它是迪菲亚潜行者通往月溪镇地下行动据点的隐蔽入口。强盗们利用平平无奇的外观，掩盖通向死亡矿井的主通道，以躲避人民民兵团和联盟当局的耳目。",al={"为什么叫defias hideout","defias hideout这个名字"}},["5348ff1f"]={q="Defias Hideout危险吗？",a="这栋建筑本身的守卫通常不多，因为大多数迪菲亚成员不是在月溪镇街头巡逻，就是在地下深处忙碌。然而，绝望的流浪汉仍在屋内徘徊，而穿过楼上隐蔽的门口，就会让你直接来到死亡矿井及其武装帮派的入口处。",al={"defias hideout危险吗","defias hideout有多危险","defias hideout的危险"}}},fp="14,267,17.598.1,34.252.1,47.240.0,44.174.0,48.212.0"}
P.entries["subzone:demon-fall-canyon"] = {n="屠魔峡谷",s="屠魔峡谷是一道伤痕累累、受到邪能腐蚀的峡谷，位于灰谷南部。这里是传奇般的战场，格罗玛什·地狱咆哮和萨尔曾在此与深渊领主玛诺洛斯对决，终结了奴役兽人种族长达一代人的恶魔之血诅咒。",h="屠魔峡谷是一道伤痕累累、受到邪能腐蚀的峡谷，位于灰谷南部。这里是传奇般的战场，格罗玛什·地狱咆哮和萨尔曾在此与深渊领主玛诺洛斯对决，终结了奴役兽人种族长达一代人的恶魔之血诅咒。",kw={"灰谷","血之诅咒","屠魔峡谷","血吼","格罗玛什·地狱咆哮","玛诺洛斯","深渊领主","萨尔"},ang={["faction:Horde"]="这片焦土对于部落来说是神圣的，因为这是格罗玛什·地狱咆哮做出最终牺牲的地方，燃烧军团的血之诅咒在此彻底终结。",["race:Orc"]="每一个兽人的精神和身体自由都归功于在这座峡谷中进行的战斗，格罗玛什用生命换取了他们从恶魔枷锁中挣脱的机会。"},sec={{t="玛诺洛斯的陨落",b="这道峡谷刻在灰谷南部崎岖的边界上，靠近冥火岭和屠魔山，承载着第三次战争的沉重伤痕。正是在这里，大酋长萨尔和酋长格罗玛什·地狱咆哮追踪到了深渊领主玛诺洛斯，意图打破他对部落的控制。在激烈的决斗中，玛诺洛斯击晕了萨尔，但格罗玛什抓住了机会，将他的斧头——血吼——直接劈入了恶魔的胸膛。随之而来的地狱烈焰爆炸摧毁了这位深渊领主，也夺去了格罗玛什的生命，使兽人永远从挥之不去的恶魔奴役中解脱了出来。"},{t="一个神圣而危险的裂谷",b="玛诺洛斯死后，部落为了纪念格罗玛什最后的抗争而将此地命名为屠魔峡谷，并在附近竖立了一座纪念碑以表彰他的救赎。尽管深渊领主被消灭了，但他那暴力死亡所释放出的原始恶魔力量彻底玷污了周边地区。如今，峡谷内仍然充斥着邪能魔法，并潜伏着敌对的次级恶魔，使得任何前往这片圣地的朝圣之旅都充满危险。"}},faq={{q="为什么这个地方叫屠魔峡谷？",a="峡谷由部落命名，以纪念深渊领主玛诺洛斯的死亡，他在此被格罗玛什·地狱咆哮击杀。",al={"屠魔峡谷名称起源","为什么叫屠魔峡谷","它是如何得名的"}},{q="格罗玛什和玛诺洛斯在这里发生了什么？",a="萨尔和格罗玛什联手对抗玛诺洛斯。萨尔被打昏在地，但格罗玛什用他的斧头给予了致命一击。玛诺洛斯死时释放出的剧烈恶魔烈焰爆炸给予了格罗玛什致命伤，但他用临终前的最后一口气让族人摆脱了血之诅咒。",al={"格罗玛什之死","格罗玛什对战玛诺洛斯","格罗玛什是怎么死的"}},{q="为什么峡谷里还有恶魔游荡？",a="当深渊领主玛诺洛斯死亡时，那股巨大的恶魔能量爆发永久性地腐蚀了峡谷底部，留下了挥之不去的邪能腐蚀，吸引并滋生了次级恶魔。",al={"为什么屠魔峡谷里有恶魔","屠魔峡谷的怪物","为什么这里受到邪能腐蚀"}},{q="格罗玛什·地狱咆哮的纪念碑在哪里？",a="一座纪念格罗玛什·地狱咆哮的纪念碑矗立在屠魔峡谷附近的区域，部落的朝圣者们会来到这里，向那位解放了他们族人的战士致敬。",al={"格罗玛什纪念碑位置","地狱咆哮纪念碑","格罗玛什的墓在哪里"}}},fx={f0a5bd72={q="什么是屠魔峡谷？",a="屠魔峡谷是一道伤痕累累、受邪能腐蚀的峡谷，隐匿于灰谷南部群山之中，位于屠魔山以东。第三次战争期间，酋长萨尔和格罗玛什·地狱咆哮曾在此与恶魔深渊领主玛诺洛斯交战。如今，峡谷仍受残余恶魔能量污染，是部落的圣地。部落成员前来此地，缅怀格罗姆最终的牺牲。",al={"什么是屠魔峡谷","屠魔峡谷的背景","关于屠魔峡谷"}},["1e62195e"]={q="屠魔峡谷危险吗？",a="极其危险。深渊领主玛诺洛斯的死亡让峡谷充斥着原始邪能，至今仍在腐蚀大地。敌对的低阶恶魔和残存的魔物游荡在峡谷深处，会攻击任何胆敢闯入的人。尽管燃烧军团在此地的主要指挥官已被击败，但无论是旅人还是前来凭吊的朝圣者，都必须时刻提防在峭壁间游荡的凶暴怪物。",al={"屠魔峡谷有多危险","屠魔峡谷危险吗","屠魔峡谷里的威胁"}}},fp="17,274,21.577.0,28.436.0,43.141.0,46.275.0,46.193.0,36.176.0"}
P.entries["subzone:demon-fall-ridge"] = {n="屠魔山",s="屠魔山是位于灰谷东南部的一片被摧残的高地，俯瞰着玛诺洛斯陨落的峡谷。这里充斥着低级恶魔和腐蚀性的魔法，山脊的中心是一座被燃烧军团占领的受亵渎的暗夜精灵兽穴。",h="屠魔山是位于灰谷东南部的一片被摧残的高地，俯瞰着玛诺洛斯陨落的峡谷。这里充斥着低级恶魔和腐蚀性的魔法，山脊的中心是一座被燃烧军团占领的受亵渎的暗夜精灵兽穴。",kw={"灰谷","兽穴","燃烧军团","屠魔峡谷","屠魔山","觅寻者迪亚托鲁斯","恐惧魔王"},ang={["class:Druid"]="看到一座曾经是翡翠梦境神圣避难所的兽穴被恶魔亵渎和占据，使得这座山脊成为了对塞纳里奥议会的冒犯。",["class:Warlock"]="这里的邪能存在由一名活跃的恐惧魔王领导，让黑暗修行者得以一窥卡利姆多境内有组织的军团残党。"},sec={{t="腐蚀之上的栖息地",b="屠魔山从屠魔峡谷正西方的上方拔地而起，沾染了第三次战争中残留的邪能余烬。下方的峡谷标志着格罗玛什·地狱咆哮与深渊领主玛诺洛斯之间灾难性冲突的地点，而这片高地则是幸存恶魔入侵者的集结地。低级恶魔在岩石峭壁间巡逻，玷污着古老的林地，威胁着所有穿行于灰谷南部边界的旅行者。"},{t="受亵渎的兽穴",b="在山脊一侧凿出的一座废弃的暗夜精灵兽穴被掏空，并被改造成了黑魔法的据点。地下的通道里不再是沉睡的德鲁伊，而是挤满了邪能魔物。在地下深处潜伏着觅寻者迪亚托鲁斯，这是一位狡诈的恐惧魔王，统治着这个秘密集会，指挥着森林中残留的恶魔余党。"}},faq={{q="屠魔山在哪里？",a="屠魔山位于灰谷东南部。它位于屠魔峡谷正西方的上方高处，靠近与贫瘠之地的边界。",al={"山脊位置","屠魔山在哪里","灰谷屠魔山"}},{q="为什么这个山脊上有恶魔？",a="这座山脊俯瞰着深渊领主玛诺洛斯在第三次战争中丧命的地点。在军团战败后幸存的恶魔分散到了周围的高地，并固守在山脊上和一座废弃的兽穴里。",al={"为什么这里有恶魔","屠魔山的恶魔","燃烧军团的踪迹"}},{q="谁在领导这里的恶魔？",a="山脊上的秘密集会由觅寻者迪亚托鲁斯指挥，他是一位强大的纳斯雷兹姆恐惧魔王，栖居在兽穴的最深处。",al={"这里的首领是谁","恶魔领袖","觅寻者迪亚托鲁斯"}},{q="凿入山脊的建筑是什么？",a="那是一座古老的暗夜精灵兽穴。它曾经是德鲁伊进入翡翠梦境的圣所，后来被废弃，此后一直被燃烧军团占领并亵渎。",al={"兽穴","屠魔洞穴","大兽穴是什么"}}},fx={["38a8c952"]={q="什么是屠魔山？",a="屠魔山是灰谷南部一处高耸荒凉的悬崖，俯瞰着屠魔峡谷。这里曾是暗夜精灵德鲁伊神圣的墓穴庇护所，如今山脊和地下大厅都已陷入黑暗，被燃烧军团的残存成员占据。他们在森林深处建立了一处邪恶据点。",al={"什么是屠魔山","屠魔山的背景","屠魔山概况"}},f78b2bbc={q="谁住在屠魔山？",a="屠魔山上遍布燃烧军团残存的恶魔。各种低阶恶魔在地表小径上游荡，守卫着废弃墓穴巢穴的入口；而在深处，它们的主人、恐惧魔王Diathorus the Seeker正率领恶魔集会。",al={"谁住在屠魔山","屠魔山的居民","屠魔山上有什么人"}},c0607561={q="屠魔山危险吗？",a="这里极其危险。屠魔山上遍布敌对恶魔，它们随时准备屠杀任何擅闯者。深入空心墓穴巢穴，就要面对盘踞其中的恶魔魔物，最终还会遭遇一名狡诈而致命的恐惧魔王。",al={"屠魔山危险吗","屠魔山的威胁"}},["45002eaf"]={q="屠魔山为什么叫这个名字？",a="屠魔山因相邻的屠魔峡谷而得名。第三次战争期间，格罗姆·地狱咆哮曾在峡谷中击杀深渊领主玛诺洛斯，解除了兽人身上的恶魔之血诅咒，也标志着燃烧军团先锋部队的覆灭。",al={"屠魔山为何得名","屠魔山名称的由来","屠魔之名的含义"}},e8f31dd4={q="屠魔山上的墓穴巢穴为何被遗弃？",a="凿入悬崖的墓穴巢穴曾是暗夜精灵德鲁伊长眠之所。第三次战争的动乱过后，附近峡谷蔓延而来的恶魔腐化侵袭此地，精灵们失去了这处圣所或将其遗弃，燃烧军团的残余势力便得以亵渎并占据这里。",al={"屠魔山为何荒废","屠魔山上的废弃墓穴巢穴","墓穴巢穴为何被遗弃"}}},fp="16,252,23.462.0,21.389.0,26.149.0,35.246.0,26.148.0,44.182.0"}
P.entries["subzone:demont-s-place"] = {n="迪蒙特荒野",s="迪蒙特荒野是一处坐落在西部荒野西南部的废弃宅地，位于被遗弃的月溪镇以西。这片农场曾经是一块繁忙的耕地，但随着该地区其余部分的衰落，它也破败不堪，并被迪菲亚潜行者的流氓特工所占据。如今，它那饱经风霜的围栏和荒芜的田野，见证了王国繁荣消逝后的又一处牺牲品。",h="迪蒙特荒野是一处坐落在西部荒野西南部的废弃宅地，位于被遗弃的月溪镇以西。这片农场曾经是一块繁忙的耕地，但随着该地区其余部分的衰落，它也破败不堪，并被迪菲亚潜行者的流氓特工所占据。如今，它那饱经风霜的围栏和荒芜的田野，见证...",kw={"迪菲亚","迪菲亚潜行者","迪蒙特荒野","农庄","月溪镇","西部荒野"},ang={["class:Rogue"]="月溪镇周围大片破败的农田，包括迪蒙特荒野，都真实地反映了迪菲亚潜行者在乡间建立的无法无天的网络。",["faction:Alliance"]="对于联盟的旅行者来说，迪蒙特荒野残酷地提醒着人们，秩序在西部荒野已经退缩到何种地步——昔日的农田竟然被迪菲亚歹徒在王国的眼皮底下公然占据。"},sec={{t="一处废弃的宅地",b="迪蒙特荒野位于月溪镇的视线范围内，曾经是为暴风城供应粮食的私人家族领地之一。经济崩溃和不法歹徒的突然崛起剥夺了农场的生计，迫使最初的照料者们背井离乡。就像它周围的农田一样，这块土地已经沦为一处粗陋的藏身所，被那些将这里当作月溪镇迪菲亚据点延伸部分的亡命之徒所占据。"},{t="潜行者的控制",b="由于紧邻月溪镇，迪蒙特荒野成了迪菲亚潜行者在他们区域中心外围的一个作战前哨站。暴徒、扒手和流离失所的劳工徘徊在围栏和破碎的建筑之间，伏击误入南部道路的旅行者。在月溪镇被收复、歹徒被击溃之前，这片土地依然太过危险，绝无可能恢复和平的耕作。"}},faq={{q="迪蒙特荒野在哪里？",a="迪蒙特荒野位于西部荒野的西南部，就在荒废的月溪镇正西方。",al={"迪蒙特荒野位置","迪蒙特荒野在哪里","迪蒙特荒野地图"}},{q="谁拥有迪蒙特荒野？",a="在农民动乱和经济问题席卷乡野之前，这座农场很可能属于一位名叫迪蒙特的定居者。最初的居民早已逃离或丧生，只留下了这片废弃的土地给强盗们。",al={"迪蒙特荒野所有者","谁是迪蒙特","迪蒙特农场主"}},{q="目前是谁占据着这座农场？",a="这座宅地目前被迪菲亚潜行者的成员占据，他们将这片破败的土地当作月溪镇行动基地外围的集结点。",al={"谁在迪蒙特荒野","迪蒙特荒野有什么敌人","迪蒙特荒野怪物"}},{q="这座农场还能恢复生产吗？",a="在目前的情况下是不可能的。随着迪菲亚势力在西部荒野南部根深蒂固，而暴风城又无法抽调守备部队，这座宅地对于普通农夫来说仍然太危险，无法进行重建。",al={"能否修复迪蒙特荒野","迪蒙特荒野是否被废弃"}}},fx={["9301a59d"]={q="为什么迪蒙特荒野变成了废墟？",a="西部荒野日渐衰败之际，农庄的原始看守者弃置了这里，迪菲亚潜行者随后占据此地，建筑无人照料，最终只剩下破败的废墟。",al={"迪蒙特荒野为何被毁","迪蒙特农庄废墟","迪蒙特荒野为何被遗弃"}},f73fe511={q="迪蒙特荒野危险吗？",a="危险。荒凉的农庄紧邻月溪镇这处亡命之徒的据点，危险的迪菲亚成员和当地的拾荒者经常在此巡逻，或成群出没。",al={"迪蒙特荒野危险吗","迪蒙特荒野安全吗","迪蒙特农庄的威胁"}},["74f5ac6b"]={q="什么是迪蒙特荒野？",a="迪蒙特荒野是一处破败的农庄遗址，位于西部荒野月溪镇以西不远处。它和死亡农地等西部荒野的其他废弃农场一样，昔日农耕生活的痕迹所剩无几。",al={"什么是迪蒙特荒野","西部荒野的迪蒙特荒野","迪蒙特农场"}},["51911e59"]={q="迪蒙特荒野发生过什么？",a="迪蒙特荒野曾是西部荒野粮仓地带的一处正常农庄，后来受到席卷该地区的普遍动荡和经济崩溃的冲击，最终被迪菲亚潜行者的成员占据。",al={"迪蒙特荒野的历史","迪蒙特荒野发生过什么","迪蒙特荒野为何被废弃"}}},fp="14,374,18.441.0,27.431.0,32.105.0,24.220.0,32.179.0,39.214.0"}
P.entries["subzone:den-of-flame"] = {n="火焰洞穴",s="火焰洞穴是位于尘泥沼泽西部的一个坚固洞穴，就在石槌废墟以西。它最初由石槌食人魔建造，作为他们的营地，但后来被效忠于奥妮克希亚的黑龙军团龙族所占据。",h="火焰洞穴是位于尘泥沼泽西部的一个坚固洞穴，就在石槌废墟以西。它最初由石槌食人魔建造，作为他们的营地，但后来被效忠于奥妮克希亚的黑龙军团龙族所占据。",kw={"黑龙军团","火焰洞穴","龙人","尘泥沼泽","奥妮克希亚","石槌废墟"},ang={["faction:Horde"]="石槌食人魔是部落的忠实盟友；清理火焰洞穴中的龙族有助于为他们陷落的定居点复仇。"},sec={{t="被征服的营地",b="火焰洞穴由石槌食人魔建造，作为他们的主要营地和避难所，带有石槌食人魔建筑那种粗糙开凿的标志性风格。然而，当黑龙军团摧毁了石槌氏族的定居点时，这群巨龙并没有仅仅驱散食人魔，而是占领了这座要塞。如今，黑龙人巡逻着燃烧的边界和洞穴入口，身处奥妮克希亚附近巢穴的阴影之下。"}},faq={{q="火焰洞穴最初是为什么而建的？",a="这座建筑最初由石槌食人魔建造，作为他们氏族的主要营地。其石砌工艺和布局体现了典型的食人魔氏族建筑风格。",al={"谁建造了火焰洞穴","火焰洞穴的起源","尘泥沼泽食人魔营地"}},{q="为什么黑龙军团会侵占这个营地？",a="伟大的黑龙奥妮克希亚在附近的沼泽中建立了她的巢穴。她的龙族将石槌食人魔赶出了定居点，并将该洞穴作为黑龙军团的前哨基地占据。",al={"为什么这里会有龙","谁住在火焰洞穴里","尘泥沼泽黑龙人"}},{q="石槌食人魔能夺回这个洞穴吗？",a="目前还不行。幸存的石槌食人魔已经和部落一起在蕨墙村定居，而黑龙人则重兵把守着他们昔日的营地。",al={"夺回洞穴"}}},fp="12,257,17.448.0,47.161.0,45.194.0,41.158.0"}
P.entries["subzone:dire-maul"] = {n="厄运之槌",s="厄运之槌是埃雷萨拉斯的废墟，这是一座古老的上层精灵城市，隐藏在菲拉斯的荒野深处。它最初是为了守护艾萨拉女王的奥术秘密而建，如今，它那摇摇欲坠的广场和高耸的斗兽场已被占领的戈多克食人魔、入侵的萨特以及其最初的精灵看护者们的枯萎残部所瓜分。",h="厄运之槌是埃雷萨拉斯的废墟，这是一座古老的上层精灵城市，隐藏在菲拉斯的荒野深处。它最初是为了守护艾萨拉女王的奥术秘密而建，如今，它那摇摇欲坠的广场和高耸的斗兽场已被占领的戈多克食人魔、入侵的萨特以及其最初的精灵看护者们的...",kw={"厄运之槌","埃雷萨拉斯","菲拉斯","戈多克","戈杜尼","伊莫塔尔","辛德拉","托塞德林"},ang={["class:Mage"]="在辛德拉的废弃图书馆内，存放着大分裂之前就保存下来的奥术论著和秘密，由大师级法师的幽灵所守护。",["race:NightElf"]="埃雷萨拉斯是一座悲剧性的纪念碑，见证了导致古代卡多雷帝国分崩离析的无节制奥术傲慢和与恶魔的妥协。"},sec={{t="埃雷萨拉斯与大分裂",b="一万二千年前，埃雷萨拉斯曾是艾萨拉女王最宠爱的法师——辛德拉的绝佳堡垒。当永恒之井在大分裂中崩塌时，托塞德林王子编织了一道魔法屏障，保护这座城市免遭毁灭。由于失去了魔法之源，幸存的上层精灵将一个名为伊莫塔尔的巨大恶魔囚禁在他们的圣所之下，抽取其邪能精华，以维持他们数千年的永生和奥术力量。"},{t="分裂的废墟",b="数百年的与世隔绝和日益衰弱的力量使托塞德林王子陷入疯狂，导致他清洗了大部分国民，以便一小撮党羽能独占恶魔剩余的能量。如今，这座庞大建筑群的外围区域已被其他威胁所占据。戈杜尼食人魔占据了Gordok Commons，并在竞技场内举办残酷的角斗比赛，而荒野变形者奥兹恩和他的堕落萨特则从内部腐蚀着Warpwood Quarter。"}},faq={{q="厄运之槌最初叫什么名字？",a="厄运之槌最初名为埃雷萨拉斯，是一座华丽的暗夜精灵城市，由辛德拉教派在一万二千年前建造，旨在保护艾萨拉女王最珍贵的奥术知识。",al={"厄运之槌的最初名称","埃雷萨拉斯历史","谁建造了厄运之槌"}},{q="现在谁居住在厄运之槌？",a="这座建筑群被分割成几个敌对区域。戈杜尼食人魔在戈多克大王的统治下控制着北部的公共区域，萨特和堕落的树妖盘踞在东部的花园，而一群隐居的上层精灵法师残部则在西部的圣所中苟延残喘。",al={"谁在厄运之槌","厄运之槌的居住者","厄运之槌里有什么怪物"}},{q="这座城市是如何在大分裂中幸存下来的？",a="当大陆在大分裂期间撕裂时，托塞德林王子和他的奥术师们施放了一个巨大的防护法术，保护埃雷萨拉斯免受淹没了周围帝国的毁灭性打击。",al={"埃雷萨拉斯如何幸存","大分裂与厄运之槌的护盾","它为什么没有被摧毁"}},{q="这里的上层精灵为什么要使用恶魔能量？",a="当永恒之井被摧毁时，辛德拉承受了严重的奥术戒断反应。为了保持他们的力量和永生，他们束缚了恶魔伊莫塔尔，并汲取其精华以求生存。",al={"厄运之槌的伊莫塔尔","为什么辛德拉要汲取恶魔能量","厄运之槌的恶魔"}},{q="厄运之槌的竞技场里会发生什么？",a="巨槌竞技场位于城市中心，是一个露天的斗兽场，被食人魔和奴隶主用作角斗锦标赛、血腥运动和挑战戈多克王位的角斗场。",al={"厄运之槌斗兽场","巨槌竞技场pvp","厄运之槌角斗士"}}},fp="9,341,36.477.0,14.450.1,37.180.0,27.271.0,39.213.0,48.201.0,39.192.0"}
P.entries["subzone:direforge-hill"] = {n="恶铁岭",s="恶铁岭是一片位于湿地东北部的崎岖高地，坐落在丹莫德的东南方，绿带草地的东北方。黑铁矮人术士邪恶的巴尔加拉斯在此处的坡地上指挥着一座敌对营地。",h="恶铁岭是一片位于湿地东北部的崎岖高地，坐落在丹莫德的东南方，绿带草地的东北方。黑铁矮人术士邪恶的巴尔加拉斯在此处的坡地上指挥着一座敌对营地。",kw={"巴尔加拉斯","邪恶的巴尔加拉斯","黑铁矮人","恶铁","恶铁岭","丹莫德","绿带草地","湿地"},ang={["class:Druid"]="穿行于湿地的德鲁伊必须应对恶铁岭上那座敌对的黑铁矮人营地。",["race:Dwarf"]="对于铁炉堡的铜须矮人来说，看到黑铁氏族的背叛行径蔓延到湿地——特别是在像巴尔加拉斯这样的术士领导下——是一种必须用冰冷的钢铁来回应的暴行。"},sec={{t="黑暗巫术的堡垒",b="恶铁岭是黑铁矮人在湿地东北部的主要营地。黑铁矮人术士邪恶的巴尔加拉斯指挥着盘踞在丹莫德东南方山丘上的敌对矮人。"},{t="对湿地的威胁",b="占据恶铁岭的黑铁矮人对穿行于湿地东北部的旅人构成了威胁。邪恶的巴尔加拉斯负责指挥这座敌对营地。"}},faq={{q="恶铁岭位于何处？",a="恶铁岭位于湿地的东北部。它坐落在丹莫德的东南方，绿带草地的正东北方，以及恐龙岭岩石峭壁的西北方。",al={"恶铁岭位置","恶铁岭在哪里","湿地恶铁岭"}},{q="目前是谁控制着恶铁岭？",a="这座山丘被由术士邪恶的巴尔加拉斯指挥的敌对黑铁矮人所占据。他们利用路障、瞭望塔和露天火坑加固了这处高地。",al={"谁在恶铁岭","谁住在恶铁岭","恶铁岭怪物"}},{q="为什么恶铁岭对湿地很重要？",a="这座山丘是黑铁矮人在湿地东北部的一处敌对营地。邪恶的巴尔加拉斯和他的矮人们威胁着穿行于周边地区的旅人。",al={"为什么恶铁岭很重要","恶铁岭威胁","恶铁岭发生了什么"}},{q="邪恶的巴尔加拉斯是谁？",a="邪恶的巴尔加拉斯是一位黑铁矮人术士，指挥着驻扎在恶铁岭的部队。他那腐化的法术和他在这片丘陵地带的咄咄逼人的存在，使他成为了那些保卫沼泽之人的首要目标。",al={"巴尔加拉斯","邪恶的巴尔加拉斯背景故事","巴尔加拉斯是谁"}}},fx={["5340135d"]={q="恶铁岭是什么地方？",a="恶铁岭是湿地东北部的一道高耸山脊，位于丹莫德东南方、恐龙岭西北方。这里是敌对的黑铁矮人在该地区建立的坚固前沿营地。",al={"恶铁岭是什么地方","恶铁岭信息","湿地恶铁岭"}},c35b9f4a={q="恶铁岭危险吗？",a="恶铁岭极其危险。营地里挤满了好斗的黑铁矮人和凶狠的术士，他们都听命于残暴的巴尔加拉斯·污秽。任何闯上山脊的人都会立刻遭到攻击。",al={"恶铁岭安全吗","恶铁岭危险","恶铁岭的威胁"}}},fp="14,211,25.198.0,26.159.0,32.191.0,38.180.0,50.155.0,25.212.0"}
P.entries["subzone:dolanaar"] = {n="多兰纳尔",s="多兰纳尔是一处宁静的暗夜精灵定居点，坐落在泰达希尔中东部的枝桠之间。它位于幽影谷西南方，是年轻的卡多雷离开他们受庇护的新手区后遇到的第一个真正的城镇。在这里，游侠、德鲁伊和工匠们聚集在一起，指导新手并着手处理那些扰乱世界之树的诡异而蔓延的病痛。",h="多兰纳尔是一处宁静的暗夜精灵定居点，坐落在泰达希尔中东部的枝桠之间。它位于幽影谷西南方，是年轻的卡多雷离开他们受庇护的新手区后遇到的第一个真正的城镇。在这里，游侠、德鲁伊和工匠们聚集在一起，指导新手并着手处理那些扰乱世界...",kw={"达纳苏斯","多兰纳尔","卡多雷","暗夜精灵城镇","幽影谷","泰达希尔"},ang={["class:Druid"]="对于那些寻求泰达希尔病痛相关指导并学习如何将自己的灵魂与自然平衡协调一致的初学者来说，多兰纳尔是一个必经之地。",["race:NightElf"]="对于年轻的暗夜精灵来说，多兰纳尔标志着他们迈向广阔世界的第一步。在目睹世界之树上日益严重的腐蚀时，他们也正在经受维护自然的誓言的考验。"},sec={{t="枝桠间的十字路口",b="多兰纳尔坐落在幽影谷西南方茂密的树冠之下，是往来泰达希尔的旅行者们的重要枢纽。它以传统的暗夜精灵风格建造，其房屋和平台与林地完美地交织在一起。这个村庄为新手提供了贸易、武艺和自然工艺方面的首次全面培训，并且坐落在前往首都达纳苏斯的道路上。由于其中心位置，关于受腐蚀的野生生物、好斗的熊怪以及来自周围枝桠的污秽苔藓的报告，不可避免地会传到多兰纳尔议会。"}},faq={{q="多兰纳尔的作用是什么？",a="多兰纳尔是年轻暗夜精灵离开幽影谷新手区后的主要任务中心和哨所。它作为泰达希尔东部的一个行政前哨，驻扎着商人、武技与魔法训练师，并与首都相连。",al={"什么是多兰纳尔","多兰纳尔的作用","多兰纳尔的重要性"}},{q="多兰纳尔位于哪里？",a="多兰纳尔位于泰达希尔的中东部地区，沿着幽影谷西南方的小径走一小段路即可到达，它位于首都达纳苏斯的东面。",al={"多兰纳尔位置","多兰纳尔在哪里","多兰纳尔指引"}},{q="旅行者如何从这里前往达纳苏斯？",a="多兰纳尔没有属于自己的飞行点。旅行者需要沿着泰达希尔的林间小路向西走，步行到达达纳苏斯的大门。",al={"前往达纳苏斯","多兰纳尔飞行管理员","从多兰纳尔到达纳苏斯"}},{q="多兰纳尔受到什么威胁？",a="多兰纳尔周边的林地正遭受着侵蚀泰达希尔的诡异腐蚀，导致了染病的野兽、疯狂的树精，以及附近敌对的熊怪部落。",al={"多兰纳尔的麻烦","多兰纳尔的问题","多兰纳尔任务"}}},fx={d9d46a9a={q="多兰纳尔是什么地方？",a="多兰纳尔是一座繁荣的暗夜精灵村庄，坐落在泰达希尔东部偏中的树枝间，就在幽影谷训练场的西南方。它是这棵宏伟世界之树上区域贸易与事务的中心，也是年轻暗夜精灵离开家园、踏入广阔世界后通常遇到的第一个大型聚居地。",al={"多兰纳尔是什么地方","多兰纳尔城镇","多兰纳尔村庄"}},["6bb1c128"]={q="多兰纳尔危险吗？",a="在村庄里，哨兵守卫、德鲁伊和商人会保护你，让你安然无恙。然而，周围的林地正日益动荡。腐化的野生动物、躁动不安的灰鬃熊怪，以及阴险的 harpy 群落，都在威胁着那些走出村庄边界的旅人。",al={"多兰纳尔危险吗","多兰纳尔安全吗","多兰纳尔安全"}}},fp="8,383,22.588.0,32.257.0,26.158.0,44.137.0,29.176.0"}
P.entries["subzone:dor-danil-barrow-den"] = {n="朵丹尼尔兽穴",s="朵丹尼尔兽穴是一处古老的暗夜精灵圣所，挖掘在灰谷中部，位于碎木岗哨南方的地下。这里曾是沉睡的德鲁伊与翡翠梦境沟通的宁静休憩之所，但在被遗忘者插手并将这些做梦者的灵魂与其肉体强行分离后，这里已沦为恐怖之地。",h="朵丹尼尔兽穴是一处古老的暗夜精灵圣所，挖掘在灰谷中部，位于碎木岗哨南方的地下。这里曾是沉睡的德鲁伊与翡翠梦境沟通的宁静休憩之所，但在被遗忘者插手并将这些做梦者的灵魂与其肉体强行分离后，这里已沦为恐怖之地。",kw={"灰谷","兽穴","朵丹尼尔","发狂的德鲁伊","玛沃瑞斯·断云","莫登塔尔","塔尼尔·暗木","乌希尔·月语"},ang={["class:Druid"]="兽穴是与翡翠梦境沟通的神圣之地，因此对朵丹尼尔内部德鲁伊的折磨和精神摧残是一种不可饶恕的亵渎。",["race:Undead"]="在朵丹尼尔进行的扭曲研究反映了被遗忘者对生命、死亡和灵魂分离魔法临界点的无尽好奇，即便是在遥远的卡利姆多战场上也是如此。"},sec={{t="遭到亵渎的圣所",b="整个卡利姆多的兽穴都是备受尊崇的圣所，暗夜精灵德鲁伊历来会在其中沉睡数个世纪，在翡翠梦境中漫游，同时他们的肉体在地下受到保护。当部落推进到灰谷时，朵丹尼尔深陷敌后。兽人们大多忽略了这些昏迷的精灵，但新加入的被遗忘者却看到了机会。被遗忘者的特工潜入深处，开始进行可怕的实验，试图将沉睡的德鲁伊与他们的灵魂分离，致使他们的精神崩溃，陷入无可救药的疯狂。阴暗的洞穴里现在爬满了邪恶的被遗忘者刺客，以及那些因为再也无法回到肉体而愤怒、痛苦发狂的德鲁伊之灵。"},{t="受折磨的守护者",b="朵丹尼尔内的腐化深入地下的隧道，三位著名的德鲁伊之灵在那里陷入疯狂徘徊：乌希尔·月语、玛沃瑞斯·断云和塔尼尔·暗木。在他们身边游荡的是黑暗杀手莫登塔尔，一个在兽穴内发现的被遗忘者特工。对于暗夜精灵和塞纳里奥议会的盟友来说，让这些痛苦的灵魂安息是一种冷酷的仁慈，而持续存在的被遗忘者也暴露了希尔瓦娜斯的特工们在卡利姆多的冲突中所带来的无情且病态的好奇心。"}},faq={{q="什么是朵丹尼尔兽穴？",a="朵丹尼尔兽穴是位于灰谷的一处暗夜精灵地下避难所，坐落在碎木岗哨以南，冥火岭的西南方。传统上，德鲁伊会在此进入深度昏迷状态以进入翡翠梦境，同时他们的肉体受到保护。",al={"这个地方是什么","朵丹尼尔兽穴信息","朵丹尼尔背景故事"}},{q="为什么里面的德鲁伊之灵充满敌意且疯狂？",a="被遗忘者的特工进入兽穴，对沉睡的德鲁伊进行实验，将他们的灵魂与肉体分离开来。在清醒世界与梦境之间被撕裂的创伤导致这些德鲁伊变得极度疯狂。",al={"为什么这里的德鲁伊疯了","为什么灵魂很愤怒","发狂的德鲁伊背景"}},{q="黑暗杀手莫登塔尔是谁？",a="黑暗杀手莫登塔尔是被发现于兽穴深处的一名被遗忘者，混迹于其中的亡灵生物之间。人们知道他的存在，但并未将其认定为这些实验的负责人。",al={"莫登塔尔","里面的亡灵是谁"}},{q="哪些著名的灵魂徘徊在深处？",a="三位著名的德鲁伊之灵徘徊在下层密室：乌希尔·月语、玛沃瑞斯·断云和塔尼尔·暗木。这三位都被强行与肉体分离，现在在黑暗的隧道中无尽地愤怒徘徊。",al={"朵丹尼尔的有名怪物","里面的有名德鲁伊"}}},fx={b36fa772={q="朵丹尼尔兽穴发生过什么？",a="过去，这处兽穴曾是宁静的圣所，暗夜精灵德鲁伊会在此进入翡翠梦境。部落进军灰谷后，这里落入了敌军控制的腹地。兽人基本没有理会沉睡的德鲁伊，被遗忘者却对此另有图谋。他们试图切断沉睡精灵与其灵魂的联系；这一过程摧毁了德鲁伊的心智，使他们彻底陷入疯狂。",al={"朵丹尼尔历史","朵丹尼尔发生过什么","朵丹尼尔背景故事"}},c4765c4c={q="朵丹尼尔兽穴危险吗？",a="进入朵丹尼尔兽穴极其危险。蜿蜒的地下隧道里潜伏着继续进行阴谋的被遗忘者刺客，还有那些与灵魂分离、饱受折磨的凶暴幽灵。深入兽穴最深处，你会遭遇尤希尔·月语、玛沃里斯·断云和塔尼尔·暗木这类格外强大的不安亡魂。",al={"朵丹尼尔危险吗","朵丹尼尔的危险","朵丹尼尔的威胁"}}},fp="20,320,22.716.0,23.509.1,29.256.0,52.229.0,29.181.0,39.206.0"}
P.entries["subzone:dormitory"] = {n="Dormitory",s="宿舍是诺莫瑞根这座堕落科技之都内的一个居住区。这里曾经为无数的侏儒居民提供了住所，如今却充斥着放射性尘埃，并爬满了野蛮且受到辐射变异的穴居人。",h="宿舍是诺莫瑞根这座堕落科技之都内的一个居住区。这里曾经为无数的侏儒居民提供了住所，如今却充斥着放射性尘埃，并爬满了野蛮且受到辐射变异的穴居人。",kw={"clean zone","宿舍","诺莫瑞根","hall of gears","打孔机","穴居人"},ang={["profession:Engineering"]="即使在生物遏制完全失效的情况下，像矩阵打孔机3005-B这样的自动化终端仍在完美地处理着算法安全打孔卡。",["race:Gnome"]="对于每个侏儒来说，踏入宿舍都是一件私人的事情：这里曾经是你的家，现在却沦为受辐射的废墟，并被当初将你驱逐出来的那些野蛮生物所占据。"},sec={{t="沦陷的家园",b="宿舍位于Clean Zone的去污室之后，曾经居住着诺莫瑞根的发明家、工人和他们的家庭。当大工匠梅卡托克启动紧急辐射排气以对抗入侵的穴居人大军时，这个人口稠密的区域就变成了一座牢笼。如今，这里的公共大厅和生活区已彻底失去了侏儒的踪迹，取而代之的是在放射性瘴气中繁衍的变异穴居人。前往城市下层的旅行者必须穿过这个灾难留下的悲剧性遗迹，才能抵达下方的Hall of Gears。"},{t="打孔机终端",b="在被遗弃的居住区中，城市行政机构的残余部分仍在运作。矩阵打孔机3005-B机器可以处理安全打孔卡。这些终端为深入诺莫瑞根内部的高安全性数据终端提供访问权限，有助于恢复侏儒撤离时留下的重要记录。"}},faq={{q="在沦陷之前，宿舍是做什么用的？",a="宿舍曾是诺莫瑞根庞大的发明家、工人和家庭的日常住所。在有毒辐射淹没下层走廊之前，这里靠近工业和民用区域，方便了侏儒居民在工作站和休息铺位之间往返。",al={"什么是宿舍","宿舍用途","谁住在这里"}},{q="为什么宿舍里会有穴居人出没？",a="当穴居人从城市下方突破防线时，大工匠梅卡托克向城市中释放了毒气以试图消灭它们。但这些辐射并没有消灭穴居人，反而使幸存者发生了变异，变得更加凶残，并且完全适应了居住区内受辐射的环境。",al={"为什么这里有穴居人","宿舍穴居人入侵","受辐射的穴居人"}},{q="宿舍通往哪里？",a="宿舍就在Clean Zone的消毒气闸室之后，连接着上层区域与下层的Hall of Gears，对于任何想要深入诺莫瑞根的人来说，这是一个无法避开的咽喉要地。",al={"宿舍出口","从宿舍去哪里","宿舍连接区域"}},{q="这里发现的矩阵打孔机是什么？",a="矩阵打孔机3005-B终端可以处理安全打孔卡。它们编码的卡片可以授予访问更高级别安全终端的权限，从而能够恢复留在诺莫瑞根的重要数据。",al={"打孔机","矩阵打孔机3005-b","打孔卡"}}},fx={a2c6e6cc={q="宿舍区是什么地方？",a="宿舍区是诺莫瑞根内部的一个居住分区，位于Clean Zone和Hall of Gears上层的深处。这里曾是人口密集、热闹繁华的街区，许多城市里的侏儒居民在此生活和休息；如今这里已荒废，并向下连接着Hall of Gears的下层。",al={"宿舍区是什么","诺莫瑞根宿舍区","关于宿舍区"}},["47f03a0e"]={q="宿舍区遭遇了什么？",a="穴居人入侵席卷诺莫瑞根、毒性辐射涌入下层走廊时，宿舍区彻底沦陷。居住在此的侏儒不是被杀，就是被迫逃往铁炉堡，或因辐射变异；他们留下私人居所任其腐朽，地下的恐怖生物则趁机占据了这里。",al={"宿舍区发生过什么","宿舍区的陷落","宿舍区历史"}},["9c6fea46"]={q="宿舍区为什么被遗弃？",a="城市灾难性陷落期间，宿舍区遭到弃置。为阻止地下穴居人疫情蔓延，毒性辐射扩散到了这片区域，普通侏儒已无法在居住区生存。曾经舒适的集体宿舍就此变成了受污染的废墟。",al={"宿舍区为何变成废墟","宿舍区被遗弃","侏儒为何离开宿舍区"}},["410e0de9"]={q="现在谁住在宿舍区？",a="这里已没有文明居民。辐射穴居人彻底占领了这些居所；在诺莫瑞根最后的时刻，辐射席卷全城，这些凶残的地下蛮族也因此发生了畸变。",al={"谁控制宿舍区","宿舍区居民","谁住在宿舍区"}},["33cb3e50"]={q="宿舍区危险吗？",a="这里极其危险。任何人只要走出附近Clean Zone的安全范围，就会直接撞上辐射穴居人。这些生物成群出没于狭窄的走廊中，一见入侵者便会发动攻击，周围还残留着有毒污染。",al={"宿舍区危险","宿舍区安全吗","宿舍区的威胁"}},["68138d13"]={q="这片区域为什么叫宿舍区？",a="这个名字直指它最初的用途：在城市陷落前，这里是诺莫瑞根大部分劳动人口共同的寝居之所。",al={"宿舍区为何得名","宿舍区名称含义","宿舍区的由来"}}},fp="9,240,14.610.0,21.331.0,48.302.0,42.294.0,30.221.0,52.202.0"}
P.entries["subzone:drag"] = {n="Drag",s="Drag是一条繁忙且阴凉的通道，开凿在奥格瑞玛的红岩之中，连接着力量谷、荣誉谷和智慧谷。作为杜隆塔尔公认的首都商业中心，其峡谷两侧布满了工匠、商人和手艺人。这里还隐藏着通往臭名昭著的Cleft of Shadow的深邃入口。",h="Drag是一条繁忙且阴凉的通道，开凿在奥格瑞玛的红岩之中，连接着力量谷、荣誉谷和智慧谷。作为杜隆塔尔公认的首都商业中心，其峡谷两侧布满了工匠、商人和手艺人。这里还隐藏着通往臭名昭著的Cleft of...",kw={"炼金","cleft of shadow","drag","制皮","诺格","奥格瑞玛","回收","裁缝","the drag"},ang={["faction:Horde"]="每一位经过首都的旅行者最终都会踏足Drag，因为它直接连接着奥格瑞玛的军事核心与社区和神秘区域。",["profession:Engineering"]="Drag是Nogg的机械商店所在地，地精修补匠们在那里向部落传授图纸、炸药和专业的工程学知识。"},sec={{t="工匠通道",b="Drag深藏在奥格瑞玛红色的峡谷峭壁之间，是部落首都的商业支柱。如果说力量谷侧重于军事集结和行政指挥，那么Drag就是城市日常生活展开的地方。在悬崖和兽皮的遮蔽下，街道上弥漫着鞣革池的气味、沸腾的炼金坩埚味，以及修补匠齿轮的叮当声。几乎所有学科的工匠都聚集在这里，实践他们的手艺并教导有抱负的冒险者，从制皮和裁缝，到诸如Nogg的机械商店之类的地精工程学车间。"},{t="阴影与技艺的十字路口",b="除了容纳商人店面和物资回收站外，Drag在奥格瑞玛的社会地理中处于一个微妙的位置。在它的峡谷岩壁旁坐落着通往地下Cleft of Shadow的严密入口。这使得Drag成为了一个无法避开的十字路口，诚实的商人、前往智慧谷的萨满，以及从事黑暗艺术的神秘实践者们，都会在这阴暗、尘土飞扬的峡谷悬垂之下擦肩而过。"}},faq={{q="Drag在奥格瑞玛有什么用途？",a="Drag是奥格瑞玛主要的购物和贸易区。这里汇集了各种专业的训练师和补给供应商，包括炼金、裁缝、制皮、剥皮、附魔和工程学，此外还有各种回收物资和贸易商品。",al={"drag的用途","什么是drag","drag里有什么商店"}},{q="Drag通向哪里？",a="这条峡谷街道将南部的力量谷与东北部的荣誉谷连接起来，并有通往智慧谷的路径。关键的是，通往Cleft of Shadow阴影洞穴的入口就位于Drag的西侧崖壁沿线。",al={"drag的连接处","如何前往cleft of shadow","drag通向哪里"}},{q="Nogg是谁？",a="Nogg是一位进取的地精工程师，他在Drag经营着Nogg的机械商店，是部落成员重要的工程学训练师和装置供应商。",al={"noggs机械商店","谁经营机械商店"}},{q="所有的专业训练师都在Drag吗？",a="大多数制作和采集专业的店铺都设在Drag的下层和上层架台上，但并非全部。值得注意的是，城里的铁匠和矿工更倾向于荣誉谷的炽热熔炉。",al={"奥格瑞玛的训练师在哪里","急救训练师drag"}}},fx={b51cb4ea={q="暗巷区是什么地方？",a="暗巷区是奥格瑞玛一条繁华而幽暗的峡谷巷道，连接着Valley of Strength和智慧谷。它藏身于高耸的红色峭壁下，是首都主要的商业与工艺区，商人、工匠和训练师云集于此，为冒险者和居民提供各自的商品与技艺。",al={"暗巷区是什么地方","奥格瑞玛暗巷区","关于暗巷区"}},ba842caf={q="暗巷区有着怎样的历史？",a="暗巷区和奥格瑞玛的其他部分一样，开凿于杜隆塔尔的深邃峡谷中。萨尔的部落建立城市时，这里被规划为中央贸易通道。它紧邻首都一处阴凉崎岖的峡谷峭壁，很快便聚集了工坊、拾荒者和商贩，他们都渴望为这个新兴的国家提供物资。",al={"暗巷区历史","暗巷区如何建立"}},["376c9470"]={q="谁住在暗巷区，又由谁经营？",a="形形色色的工匠、店主和劳工在这里安家谋生。知名店主包括经营工程学工坊的诺格、酿制药水的耶尔玛克、制作布制品的玛格，以及负责废品回收的德罗弗斯家族。",al={"谁住在暗巷区","暗巷区居民","谁经营暗巷区"}},["5a953074"]={q="暗巷区危险吗？",a="暗巷区虽然位于阴暗粗犷的峡谷通道中，却是奥格瑞玛受保护的区域，对部落成员而言本身并不危险。不过，它紧邻暗影裂口的幽暗隧道，术士和其他行事隐秘的势力会在那里钻研那些不宜公之于众的技艺。",al={"暗巷区安全吗","暗巷区危险吗","暗巷区的危险"}}},fp="4,367,26.607.0,33.442.0,39.260.0,25.291.0,12.177.0,48.213.0"}
P.entries["subzone:dragonmaw-gates"] = {n="龙喉大门",s="龙喉大门是一系列位于湿地东部通往山脉的道路上的雄伟防御工事。为了守卫通往格瑞姆巴托山中要塞的陡峭攀升路线，这些厚重的路障阻挡了进入这座矮人废墟受诅咒高地的通道。",h="龙喉大门是一系列位于湿地东部通往山脉的道路上的雄伟防御工事。为了守卫通往格瑞姆巴托山中要塞的陡峭攀升路线，这些厚重的路障阻挡了进入这座矮人废墟受诅咒高地的通道。",kw={"阿克斯特洛兹","龙喉氏族","龙喉大门","格瑞姆巴托","山隘","红龙军团","湿地"},ang={["faction:Alliance"]="联盟一直在警惕地注视着这些大门，因为他们知道任何从高路上出现的东西都会威胁到整个湿地的稳定。",["race:Dwarf"]="对于矮人来说，这些大门代表了通往格瑞姆巴托的被封锁的门槛——那曾是他们在三锤之战后放弃，后来又被龙喉兽人亵渎的祖地。"},sec={{t="格瑞姆巴托的哨兵",b="龙喉大门雕刻在毗邻湿地东部的崎岖山峰之中，封锁了那条蜿蜒向上通往格瑞姆巴托的山路。这些防御工事因在第二次战争期间占领了这座矮人山城的龙喉氏族兽人而得名，至今仍是防御森严的检查点。任何试图攀登向高处的人都必须应对关口挥之不去的危险，那里强大的幼龙以及该氏族黑暗历史的残酷遗迹依然投下长长的阴影。"},{t="一个充满争端的阈限",b="虽然龙喉氏族的兽人在恶魔之魂被摧毁后分崩离析，但这条山路依然极其危险。人们常能看到强大的红龙在守望着大门周围蜿蜒的坡道和栖息地。在大门周围的丘陵中，徘徊的怪物幼龙和龙喉氏族的残党让这道大门成为阻挡任何大胆旅客前往高地的坚实屏障。"}},faq={{q="龙喉大门通向哪里？",a="这些大门封锁了从湿地向东蜿蜒上升，直接通往受诅咒的要塞城市格瑞姆巴托及其周围山脉高地的山路。",al={"通往龙喉大门的路径","龙喉大门后方是什么","经过大门的道路"}},{q="为什么它们被称为龙喉大门？",a="它们的名字来源于龙喉氏族兽人，这些兽人在第二次战争期间占领了附近的矮人据点格瑞姆巴托，并利用邪恶的巫术奴役红龙。",al={"为什么叫龙喉大门","龙喉大门名称","湿地的龙喉兽人"}},{q="旅客可以穿过大门吗？",a="厚重的大门紧紧关闭并有着严密的防御，阻止了任何正常的通行进入高山。",al={"能打开龙喉大门吗","通过龙喉大门"}},{q="谁守卫着大门周围的道路？",a="道路和附近崎岖的关口被凶猛的红龙人和幼龙所占据，还有分散的兽人以及依然盘踞在山坡上的黑暗威胁。",al={"谁在龙喉大门","龙喉大门的巨龙","阿克斯特洛兹 龙喉大门"}}},fx={fb3392df={q="龙喉大门发生过什么？",a="第二次战争期间，龙喉兽人占据格瑞姆巴托的山中要塞并控制红龙军团时，曾为这些气势恢宏的大门修筑防御工事。兽人战败并被驱逐后，由巨龙阿克斯卓兹率领的红龙前来守望通往山脉的道路。",al={"龙喉大门历史","龙喉大门发生过什么","龙喉大门过往"}},["3dd629b0"]={q="龙喉大门有多危险？",a="这里极其危险。守卫道路的红龙——包括阿克斯卓兹这类强大的巨龙——不会欢迎凡人擅闯格瑞姆巴托的入口。除了红龙之外，敌对的龙喉兽人仍在湿地周边的丘陵间出没，因此任何前往大门的旅途对行人而言都危机四伏。",al={"龙喉大门危险吗","龙喉大门的危险","龙喉大门安全吗"}}},fp="15,272,23.504.0,21.430.0,34.164.0,40.178.0,37.107.0,37.177.0"}
P.entries["subzone:dragonmurk"] = {n="黑龙谷",s="黑龙谷是尘泥沼泽南部一片广阔而危险的区域，到处都是黑龙人、幼龙和雏龙。这片区域两侧环绕着古老的食人魔废墟和焦黑的洞穴，是奥妮克希亚龙巢的敌对外部防线。",h="黑龙谷是尘泥沼泽南部一片广阔而危险的区域，到处都是黑龙人、幼龙和雏龙。这片区域两侧环绕着古老的食人魔废墟和焦黑的洞穴，是奥妮克希亚龙巢的敌对外部防线。",kw={"黑龙军团","火焰洞穴","黑龙谷","龙人","尘泥沼泽","奥妮克希亚","石槌废墟","雏龙"},ang={["faction:Alliance"]="塞拉摩时刻警惕着黑龙谷，因为他们知道，在离要塞如此近的地方放任一个黑龙巢穴可能会轻易酿成灾难。",["faction:Horde"]="黑龙谷的巨龙将石槌食人魔赶出了他们的村庄，并不断威胁着深入沼泽探险的部落远征队。"},sec={{t="沼泽中的龙巢",b="Spanning the southern interior of Dustwallow Marsh, the Dragonmurk marks the threshold where damp wetlands give way to the dominion of the black dragonflight. The waterways and thick mud here crawl with black wyrmkins, dragonspawn, and ravenous whelps. The surrounding landscape has suffered deeply from their presence; adjacent territories such as the ruined village of Stonemaul and the scorched cavern known as the Den of Flame have both fallen completely under the flight's territorial grip."},{t="守卫龙母",b="黑龙谷中成群的幼龙和守卫并非漫无目的地游荡。尘泥沼泽南部是Deathwing之女奥妮克希亚在卡利姆多的主要巢穴。龙人积极地巡逻着这片沼泽，消灭闯入者，保护龙蛋不受塞拉摩侦察兵和部落附近营地的威胁。"}},faq={{q="什么是黑龙谷？",a="黑龙谷是尘泥沼泽的南部地区，那里遍布着属于黑龙军团的雏龙、幼龙和龙人。",al={"什么是黑龙谷","黑龙谷在哪里","黑龙谷位置"}},{q="为什么这里有这么多黑龙？",a="尘泥沼泽南部坐落着黑龙军团龙母奥妮克希亚的巢穴。黑龙谷起着保护缓冲的作用，她的后代和仆从可以在这里筑巢、成长并抵御外部威胁。",al={"为什么尘泥沼泽有黑龙","谁统领这里的巨龙","奥妮克希亚 巨龙 尘泥沼泽"}},{q="黑龙谷附近有哪些地标？",a="黑龙谷包含并环绕着火焰洞穴和石槌废墟等关键地点，这两个地方都已被黑龙人占领。",al={"黑龙谷地标","黑龙谷附近有什么","黑龙谷周围的地点"}},{q="黑龙谷对旅行者来说安全吗？",a="一点也不安全。黑龙谷中的龙类极其敌对且好战，这使其成为卡利姆多南部最危险的荒野地区之一。",al={"黑龙谷危险吗","我能穿过黑龙谷吗"}}},fp="10,237,18.495.0,24.349.1,19.152.0,41.215.0,41.165.0,33.153.0"}
P.entries["subzone:dreadmaul-post"] = {n="巨槌岗哨",s="巨槌岗哨是一个位于诅咒之地焦土之上的食人魔定居点。该岗哨由巨槌氏族建立，是一个靠近黑暗之门的坚固堡垒，食人魔自德拉诺抵达艾泽拉斯后便一直盘踞于此。途经该地区的旅行者必须提防这些凶猛的蛮族以及他们营地周围险恶的地形。",h="巨槌岗哨是一个位于诅咒之地焦土之上的食人魔定居点。该岗哨由巨槌氏族建立，是一个靠近黑暗之门的坚固堡垒，食人魔自德拉诺抵达艾泽拉斯后便一直盘踞于此。途经该地区的旅行者必须提防这些凶猛的蛮族以及他们营地周围险恶的地形。",kw={"诅咒之地","黑暗之门","巨槌","巨槌岗哨","食人魔土堆","食人魔"},ang={["faction:Alliance"]="对于监视黑暗之门的联盟侦察兵来说，巨槌食人魔是一个根深蒂固、充满暴力的危险因素，这使得任何经过大陆南部的巡逻任务都变得复杂起来。",["faction:Horde"]="尽管食人魔曾经与旧部落并肩作战，但像巨槌氏族这样的野生氏族早已断绝了与萨尔的新秩序之间的联系，并将所有旅行者视为敌对的入侵者。"},sec={{t="德拉诺的残部",b="几十年前，当部落通过黑暗之门涌入时，数个食人魔氏族随其一同进入了艾泽拉斯。巨槌氏族选择在门户附近扎根，在诅咒之地的红色荒原上竖起了粗糙的石堆和土方工程。巨槌岗哨是他们主要的哨站之一，牢牢控制着这片荒地，并不时与游荡的野兽以及胆敢靠近他们领地的愚蠢旅行者发生冲突。"}},faq={{q="谁居住在巨槌岗哨？",a="巨槌岗哨居住着巨槌氏族的食人魔。这些高大的蛮族在战争期间通过黑暗之门从德拉诺跨界而来，并在诅咒之地的荒凉岩地中建立了永久性的据点。",al={"谁在巨槌岗哨","巨槌岗哨的居民","巨槌食人魔"}},{q="为什么食人魔还留在诅咒之地？",a="在旧部落崩溃且黑暗之门被封印后，许多食人魔散落到了艾泽拉斯各地。然而，巨槌氏族却留在了他们最初的入口附近，将那处休眠裂隙周围伤痕累累、荒凉广袤的土地当作了家园。",al={"为什么巨槌在这","诅咒之地的食人魔","为什么食人魔在传送门附近"}},{q="除了岗哨，还有谁在附近游荡？",a="除了食人魔本身，巨槌岗哨附近的红色沙漠中还游荡着蝎虫和蜥蜴等凶猛的当地掠食者。",al={"诅咒之地的德莱尼","谁在巨槌附近","巨槌岗哨的生物"}}},fp="14,391,19.456.0,28.227.0,45.253.0,40.125.0"}
P.entries["subzone:dreadmaul-rock"] = {n="巨槌石",s="巨槌石是耸立在燃烧平原焦灼荒地之上的一座高耸岩架和洞穴综合体。它是火腹食人魔的主要行动基地，他们在那蜿蜒的地底土丘中安家落户。",h="巨槌石是耸立在燃烧平原焦灼荒地之上的一座高耸岩架和洞穴综合体。它是火腹食人魔的主要行动基地，他们在那蜿蜒的地底土丘中安家落户。",kw={"燃烧平原","巨槌峰","巨槌石","火腹食人魔","食人魔土丘"},ang={["faction:Alliance"]="对于守卫着赤脊山边境关口的联盟部队来说，巨槌石那些好战的食人魔构成了时刻存在的残酷威胁，就盘踞在北面的山脊对面。",["faction:Horde"]="跋涉穿过平原前往黑石山的部落旅行者必须小心绕过巨槌石，以免招致领地意识极强的火腹氏族的愤怒。"},sec={{t="火腹要塞",b="巨槌石高耸于燃烧平原的焦土之上，是一座由迷宫般的洞穴系统雕凿而成的巨大岩石构造。尽管它的名字暗示着它可能与诅咒之地的巨槌食人魔有关，但这座岩石目前被火腹氏族牢牢控制。这些粗野的食人魔利用高处的路径、岩架和内部的土丘作为防御营地，主宰着周边的荒原，并威胁着任何试图穿过北坡前往黑石塔的人。"}},faq={{q="谁住在巨槌石？",a="巨槌石是火腹食人魔的核心基地。他们居住在外部悬崖小径和岩石构造内部复杂的洞穴系统中。",al={"谁在巨槌石","巨槌石怪物","巨槌石有什么食人魔"}},{q="既然火腹食人魔住在这里，为什么它叫巨槌石？",a="虽然火腹氏族目前控制着这座山峰，但其名字强烈暗示这里曾经可能属于巨槌食人魔氏族，该氏族在南方的诅咒之地拥有庞大的势力。",al={"为什么叫巨槌","巨槌还是火腹","巨槌食人魔联系"}},{q="这座岩石的布局是怎样的？",a="巨槌石由沿岩架蜿蜒而上的陡峭外部坡道，以及布满食人魔土丘和住所的错综复杂的内部洞穴网络组成。",al={"巨槌洞穴","巨槌峰布局","穿行巨槌石"}},{q="巨槌石位于哪里？",a="它位于燃烧平原，是赤脊山路径以北、黑石山以东的一座显眼的山状构造。",al={"巨槌石位置","巨槌石在哪里","燃烧平原食人魔基地"}}},fp="14,233,25.510.0,28.162.0,58.190.0,36.151.0,32.165.0"}
P.entries["subzone:dreadmist-den"] = {n="鬼雾兽穴",s="鬼雾兽穴是一处位于贫瘠之地北部鬼雾峰峭壁下的地下洞穴。该洞穴由火刃氏族邪教控制，终年笼罩在令人不安的红色迷雾中，是崇拜恶魔的祭坛。",h="鬼雾兽穴是一处位于贫瘠之地北部鬼雾峰峭壁下的地下洞穴。该洞穴由火刃氏族邪教控制，终年笼罩在令人不安的红色迷雾中，是崇拜恶魔的祭坛。",kw={"贫瘠之地","火刃氏族","邪教徒","恶魔之种","鬼雾兽穴","鬼雾峰","红色迷雾"},ang={["class:Warlock"]="鬼雾兽穴中培育的恶魔遗物和不稳定的邪能引起了术士们浓厚的兴趣，他们希望利用火刃氏族的黑暗秘密。",["faction:Horde"]="在贫瘠之地之上存在一个火刃氏族洞穴，这对附近的贸易路线和定居点构成了不可容忍的危险，需要部落保卫者迅速采取行动。"},sec={{t="邪恶阴影的巢穴",b="鬼雾兽穴隐藏在鬼雾峰的崎岖山坡之中，是火刃氏族邪教徒的黑暗避难所。洞穴内弥漫着厚重的深红色蒸汽，使整个洞穴笼罩在诡异的暮色之中。在远离下方平原上部落视线的地方，邪教徒在这些石质隧道中进行着邪恶的恶魔仪式，守护着他们亵渎的遗物，并密谋在整个卡利姆多散布他们的腐化。"},{t="恶魔之种",b="在洞穴的最深处存放着恶魔之种，这是邪教徒所珍视的邪能力量神器。它被放置在火焰祭坛之上，与燃烧军团有着紧密的联系。阿克泽洛斯正在准备一块能量石来切断这种联系。对于追踪火刃氏族阴谋的部落斥候和有志向的术士来说，潜入这个洞穴是揭开恶魔在贫瘠之地渗透程度的危险但必要之举。"}},faq={{q="什么是鬼雾兽穴？",a="鬼雾兽穴是一个隐藏在贫瘠之地北部鬼雾峰内的洞穴系统。它是阴险的火刃氏族成员的活跃据点和仪式场所。",al={"鬼雾兽穴","什么是鬼雾兽穴","贫瘠之地 鬼雾洞穴"}},{q="是什么导致了洞穴内的红色迷雾？",a="红色的薄雾笼罩着鬼雾兽穴及其上方的山峰。火刃氏族邪教徒在此进行恶魔仪式，但迷雾的确切成因尚不明确。",al={"鬼雾 红色薄雾","贫瘠之地 绯红浓雾","鬼雾兽穴 红色迷雾"}},{q="里面发现的恶魔之种是什么？",a="恶魔之种是一件保存在鬼雾兽穴深处的黑暗神器。它对火刃氏族邪教徒具有巨大的价值，是他们邪能魔法的强大聚焦点。",al={"恶魔之种","什么是恶魔之种","鬼雾兽穴中的神器"}},{q="为什么部落关心这个洞穴？",a="火刃氏族公然崇拜恶魔，并试图从卡利姆多内部破坏部落。在靠近十字路口和奥格瑞玛的地方留下一个崇拜恶魔的邪教据点，对贫瘠之地的安全构成了持续的威胁。",al={"部落 鬼雾兽穴","为什么要清理鬼雾兽穴","兽人 火刃氏族 贫瘠之地"}}},fx={["43f375e7"]={q="鬼雾兽穴里住着谁？",a="洞穴被火刃氏族的教徒占据。这些崇拜恶魔的人将这处偏僻的山洞用作隐秘的圣所和仪式据点，栖身于洞内不自然的红色雾气所笼罩的永恒暮色之中。",al={"鬼雾兽穴的居民","谁在鬼雾兽穴","谁控制鬼雾兽穴"}},bcbe1c71={q="鬼雾兽穴危险吗？",a="兽穴十分危险，因为火刃氏族的教徒会守卫他们的恶魔祭坛。红色雾霭笼罩着洞穴，闯入者必须面对其中充满敌意的居民。",al={"鬼雾兽穴的危险","鬼雾洞穴安全吗","鬼雾兽穴有多危险"}},["5db705cc"]={q="为什么叫鬼雾兽穴？",a="这处洞穴因内部常年弥漫的暗红色雾气而得名。这种有毒的雾气从山峰中渗出，让洞内一切都笼罩在诡异的暮色中，也让山峰和山下的兽穴都染上了这个阴森的名字。",al={"鬼雾兽穴的来历","鬼雾兽穴名称由来","鬼雾兽穴的含义"}}},fp="13,246,23.449.0,14.444.1,22.180.0,40.158.0,36.165.0,40.244.0"}
P.entries["subzone:dreadmist-peak"] = {n="鬼雾峰",s="鬼雾峰是一座嶙峋、荒凉的山峰，耸立在贫瘠之地十字路口的西北方。山峰被一层非自然的深红色瘴气笼罩，是火刃氏族恶魔邪教徒的一处隐秘堡垒。",h="鬼雾峰是一座嶙峋、荒凉的山峰，耸立在贫瘠之地十字路口的西北方。山峰被一层非自然的深红色瘴气笼罩，是火刃氏族恶魔邪教徒的一处隐秘堡垒。",kw={"贫瘠之地","火刃氏族","鬼雾兽穴","鬼雾峰","瘴气","萨里鲁斯·邪语"},ang={["class:Druid"]="来自陶拉祖营地的牛头人德鲁伊正在调查鬼雾峰的水源，试图查明毒害平原上羚羊和野生动物的非自然毒素来源。",["faction:Alliance"]="在灰谷附近活动的联盟特工追踪到，被污染的水元素所束缚的腐化魔法，直指潜伏在山顶的亡灵召唤师萨里鲁斯·邪语。"},sec={{t="腐化之穴",b="鬼雾峰高高耸立在贫瘠之地干旱的草原之上，是一处邪恶气息显而易见的地方。当旅行者沿着崎岖山路蜿蜒而上时，明朗的天空会被浓厚的红色迷雾遮蔽。在山顶和地下的洞穴中，火刃氏族邪教徒秘密活动，包庇着术士和毒药师。他们占据着这处制高点，将毒素散布到附近的水源中，并密谋对抗那些正在卡利姆多中部建立统治的新兴势力。"},{t="阴谋汇聚之地",b="除了在鬼雾兽穴周围窝藏术士并进行黑暗仪式外，这座山峰还吸引了另一位邪恶的人物。叛逃的被遗忘者法师萨里鲁斯·邪语（Sarilus Foulborne）在高处安营扎寨，他扭曲元素力量，腐化了远至灰谷的水之灵。"}},faq={{q="为什么鬼雾峰周围的空气是红色且充满迷雾的？",a="没有任何记载能说明笼罩在山峰上的红橙色迷雾从何而来。它掩盖了山间小径和鬼雾兽穴，那是当地火刃氏族术士进行邪恶仪式的地方。",al={"红色迷雾 鬼雾","橙色浓雾 鬼雾峰","为什么鬼雾是红色的"}},{q="谁控制了鬼雾峰？",a="这座山由火刃氏族控制，他们在山间小径上巡逻并守卫着下方的鬼雾兽穴。此外，它也被像叛逃的亡灵法师萨里鲁斯·邪语这样的黑暗人物所占据。",al={"谁住在鬼雾峰","鬼雾峰敌人","火刃氏族 鬼雾"}},{q="如何前往鬼雾峰？",a="从十字路口沿主路向北走，直到道路分叉前往灰谷和石爪山脉。向西北望去，可以看到那座高耸的山崖，然后沿北坡的小径攀登，这是通往山顶最安全的路线。",al={"如何前往鬼雾峰","鬼雾峰位置","鬼雾小径"}}},fx={["225dd39b"]={q="鬼雾峰是什么地方？",a="鬼雾峰是一座嶙峋而阴森的山峰，耸立在贫瘠之地北部、十字路口西北方。它笼罩在诡异的红橙色雾气中，是臭名昭著的火刃氏族秘密据点。峰顶藏着鬼雾兽穴等险恶洞穴，术士和教徒会在那里举行邪恶仪式，荼毒周围的草原。",al={"鬼雾峰是什么地方","鬼雾峰背景故事","介绍鬼雾峰"}},["9aed69cf"]={q="鬼雾峰危险吗？",a="这里极其危险。山上遍布狂热的火刃氏族侍僧、打手、毒理学家和黑暗召唤师，他们会凶狠地守卫仪式场所。除了充满敌意的教徒，据说山峰上的水也在毒害下方贫瘠之地的野生动物。",al={"鬼雾峰危险吗","鬼雾峰的威胁","鬼雾峰的危险"}}},fp="14,224,19.502.0,24.265.1,51.191.0,28.206.0,32.215.0"}
P.entries["subzone:dreadmurk-shore"] = {n="恐惧海岸",s="恐惧海岸包含了尘泥沼泽多雾的海岸线和散布的岛屿，一路向北延伸至贫瘠之地。这里不仅有充满攻击性的泥鳍鱼人及海兽盘踞，这片凶险的水域最近还成为了沉船幸存的迪菲亚潜行者亡命之徒的藏身之所。",h="恐惧海岸包含了尘泥沼泽多雾的海岸线和散布的岛屿，一路向北延伸至贫瘠之地。这里不仅有充满攻击性的泥鳍鱼人及海兽盘踞，这片凶险的水域最近还成为了沉船幸存的迪菲亚潜行者亡命之徒的藏身之所。",kw={"奥卡兹岛","迪菲亚","恐惧海岸","尘泥沼泽","泥鳍","鱼人","沉船","塞拉摩"},ang={["class:Rogue"]="海岸线上孤立的营地和沉船残骸提供了绝佳的机会，可以追踪迪菲亚的秘密货物，并溜过该地区凶残的泥鳍哨兵。",["faction:Alliance"]="在距离塞拉摩如此近的地方发现迪菲亚潜行者幸存者，表明其阴谋的影响力远超西部荒野，直接威胁到了联盟在卡利姆多的稳定。"},sec={{t="凶险的海岸",b="恐惧海岸沿着尘泥沼泽的东北边缘，横跨塞拉摩岛与北方城堡之间，是一片泥泞浅滩、潮汐池和多雾岛屿组成的阴沉地带。海岸被泥鳍鱼人部落占领，这是一个领地意识极强的鱼人氏族，会对任何靠近其沿海村庄的旅行者发起攻击。海龟和水生掠食者在浅滩出没，使得即使不考虑周边的沼泽环境，这条海岸线本身也危机四伏。"},{t="迪菲亚渗透者",b="除了土生土长的沼泽生物，由于人类亡命之徒的存在，这条海岸线也引起了塞拉摩方面的高度警惕。一艘载有迪菲亚潜行者的船只在恐惧海岸与奥卡兹岛之间的水域遭遇海难，导致暴徒散落在沙滩和小岛上。这些来自东部王国的罪犯出现在距离吉安娜·普罗德摩尔女士的堡垒如此近的地方，是一个令人担忧的事态发展，威胁到了海湾两岸脆弱的权力平衡。"}},faq={{q="恐惧海岸位于哪里？",a="恐惧海岸沿着尘泥沼泽的东北海岸延伸，面向无尽之海，位于塞拉摩岛郊外与靠近北方城堡的贫瘠之地边界之间。",al={"恐惧海岸位置","恐惧海岸在哪里"}},{q="为什么这片海岸会有迪菲亚暴徒？",a="一艘迪菲亚潜行者的船只近期在恐惧海岸与奥卡兹岛之间的近海水域沉没。幸存者逃上岸，在偏僻的海滩和岩礁沿线建立了临时营地，试图打捞沉没的货物。",al={"尘泥沼泽的迪菲亚","迪菲亚为什么在这里","失事的迪菲亚"}},{q="住在海滩上的鱼人是什么来头？",a="这片海岸居住着大量的泥鳍鱼人部落。他们在沙洲和岩礁小岛上建造了简陋的渔业定居点，激烈地保卫着自己的领地，以抵御来自塞拉摩的巡逻队和失事船只上的入侵者。",al={"泥鳍鱼人","恐惧海岸的鱼人"}},{q="恐惧海岸是由塞拉摩控制的吗？",a="塞拉摩名义上对该岛周边地区拥有管辖权，但恐惧海岸实际上处于无法无天的状态。这里的沼泽浅滩太过野蛮，且充满了鱼人和强盗，以至于吉安娜·普罗德摩尔女士的哨兵无法维持常规巡逻。",al={"谁拥有恐惧海岸","恐惧海岸属于联盟吗"}}},fp="15,287,19.482.0,19.463.1,33.188.0,43.250.0,43.228.0,43.254.0"}
P.entries["subzone:dream-bough"] = {n="梦境之树",s="梦境之树是一棵矗立在菲拉斯北部加德米尔湖中心岛屿上的巨大世界之树。这棵古老的树木庇护着一道连接艾泽拉斯与翡翠梦境的神秘传送门。绿龙们忠诚地守护着这片圣地，将不速之客阻挡在它青翠的枝叶之外。",h="梦境之树是一棵矗立在菲拉斯北部加德米尔湖中心岛屿上的巨大世界之树。这棵古老的树木庇护着一道连接艾泽拉斯与翡翠梦境的神秘传送门。绿龙们忠诚地守护着这片圣地，将不速之客阻挡在它青翠的枝叶之外。",kw={"梦境之树","翡翠梦境","菲拉斯","世界之树","绿龙军团","加德米尔湖"},ang={["class:Druid"]="梦境之树是神圣的土地，体现了艾泽拉斯的荒野与你的教团所照料的原始翡翠梦境之间至关重要的桥梁。",["race:NightElf"]="这棵伟大的树木守护着通往翡翠梦境的入口，代表了你的人民守护和捍卫自然世界的古老职责。"},sec={{t="加德米尔的大树",b="梦境之树高耸于菲拉斯北部的树冠之上，是该地区最大的树木。它坐落在宁静的加德米尔湖中，这座高大的守望者在树干上开辟了一道天然传送门，提供了通往荒野翡翠梦境的直接入口。"},{t="翡翠守望者",b="由于它与翡翠梦境的联系，这棵树处于绿龙军团的严密保护之下。龙人和幼龙巡视着加德米尔湖的岸边以及通往大树树干的路径。虽然这里主要是游走于各个位面之间的德鲁伊进行沉思和休憩的地方，但旅行者们在接近时仍需小心，因为绿龙几乎不会容忍不速之客靠近如此重要的入口。"}},faq={{q="什么是梦境之树？",a="梦境之树是一棵位于菲拉斯北部加德米尔湖中岛屿上的巨大世界之树。它是一个庇护所，内部有着通往翡翠梦境的活跃传送门。",al={"梦境之树","什么是梦境之树","加德米尔湖之树"}},{q="是谁种植了梦境之树？",a="现今没有任何记载说明是谁种植了梦境之树。它被称为是庇护着通往翡翠梦境传送门的几棵世界之树之一，并由绿龙军团负责守护。",al={"谁种植了梦境之树","梦境之树起源","范达尔·鹿盔之树"}},{q="为什么这里会有绿龙？",a="绿龙军团是翡翠梦境永恒的守护者。因为通往梦境的直接入口就位于树干之中，龙类及其眷属时刻保持警惕，以保护传送门不受入侵者侵害。",al={"绿龙军团与梦境之树","加德米尔湖的龙"}},{q="玩家可以进入通往翡翠梦境的传送门吗？",a="镶嵌在树干上的漩涡传送门直接连接着翡翠梦境，但对于在物质位面苏醒的凡人冒险者来说，它是无法通行的。只有强大的沉睡德鲁伊和绿龙军团可以自由穿越这道边界。",al={"我能使用梦境之树传送门吗","进入菲拉斯翡翠梦境"}}},fp="11,310,25.286.0,20.423.0,24.171.0,28.185.0,33.227.0,52.242.0"}
P.entries["subzone:dreamer-s-rock"] = {n="Dreamer's Rock",s="Dreamer's Rock是一处隐秘的天然圣所，深藏在Wailing Caverns中，位于Screaming Gully之后。沉睡的暗夜精灵德鲁伊纳拉雷克斯就躺在这里，他为了让贫瘠之地重现生机而做出的崇高努力，却反而孕育出了一场活生生的噩梦。这里既是一处神圣的兽穴，也是导致周围地下生态系统发生异变的腐蚀源头。",h="Dreamer's Rock是一处隐秘的天然圣所，深藏在Wailing Caverns中，位于Screaming...",kw={"兽穴","dreamer's rock","尖牙德鲁伊","翡翠梦境","穆坦努斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="Dreamer's Rock是翡翠梦境中潜藏危险的冷酷警示，它揭示了崇高的意图是多么容易被沉睡的恐怖所颠覆。",["race:NightElf"]="在贫瘠之地干涸的地表下发现一处被腐蚀的神圣兽穴，这让人沉痛地想起纳拉雷克斯和他的追随者在远离卡利姆多北部森林的地方所冒的巨大风险。"},sec={{t="纳拉雷克斯的沉睡",b="Dreamer's Rock位于Wailing Caverns的核心地带，其作用与临时的兽穴颇为相似。在这里，暗夜精灵德鲁伊纳拉雷克斯进入了深层冥想，试图利用地下泉水，将翡翠梦境的力量引入贫瘠之地的干涸土壤。然而，他的连接非但没有带来生命，反而被黑暗势力所劫持。扭曲他思想的梦魇如今已实体化溢出到这个洞穴中，不仅扭曲了当地的野生动物，还将他的追随者变成了毒蛇般的尖牙德鲁伊，并向清醒的世界投下了可怕的畸变怪兽。"},{t="唤醒仪式",b="只有终结了尖牙领主的腐蚀，纳拉雷克斯的幸存信徒才能前往Dreamer's Rock进行唤醒仪式。这一过程危机四伏：当咒语开始吟唱时，纳拉雷克斯挥之不去的梦魇会显化出怪物，以守卫其对他沉睡心智的控制。这场精神折磨的终极高潮便是吞噬者穆坦努斯，这个卑劣的畸变怪兽会直接从做梦者的潜意识深处显现，吞噬所有试图解救他的人。"}},faq={{q="谁在Dreamer's Rock沉睡？",a="纳拉雷克斯，一位强大的暗夜精灵德鲁伊，正躺在这里沉睡。他来到Wailing Caverns是希望能利用其地下水道，让贫瘠之地恢复郁郁葱葱的生机，但由于恐怖梦魇的干扰，他与翡翠梦境的沟通被劫持了。",al={"沉睡的精灵","谁在此沉睡","谁是纳拉雷克斯","织梦者身份"}},{q="为什么这个洞穴叫Dreamer's Rock？",a="这个洞穴是以纳拉雷克斯本人（即“织梦者”）的名字命名的。它就像传统的暗夜精灵兽穴一样，为他的肉体提供了一个安息之所，而他的灵魂则在翡翠梦境中穿行。",al={"为什么叫dreamer's rock","dreamer's rock名字含义","名字起源"}},{q="当你试图唤醒纳拉雷克斯时会发生什么？",a="在尖牙领主被击败后，纳拉雷克斯的一名幸存信徒会尝试唤醒仪式。仪式进行时，你会亲眼目睹其结果以及显现出的威胁。",al={"唤醒纳拉雷克斯","信徒仪式","纳拉雷克斯事件"}},{q="为什么纳拉雷克斯的追随者变得具有敌意？",a="随着纳拉雷克斯的沟通演变成一场噩梦，黑暗幻象扭曲了他信徒的心智。他们抛弃了塞纳里奥誓言，拥抱了毒蛇形态，成为了尖牙德鲁伊，狂热地捍卫着他们主人那备受折磨、永无止境的沉睡。",al={"尖牙德鲁伊起源","德鲁伊为何邪恶","被腐蚀的德鲁伊"}}},fx={["8278540a"]={q="Dreamer's Rock是什么地方？",a="Dreamer's Rock是哀嚎洞穴深处一处僻静的天然洞室，位于Screaming Gully之外。它的作用类似传统的德鲁伊墓穴，是暗夜精灵德鲁伊纳拉雷克斯长眠之处；他在那里将意识投入翡翠梦境，试图为贫瘠之地带来生机。",al={"dreamer's rock是什么地方","dreamer's rock洞室","dreamer's rock在哪里"}},["29a7d0a7"]={q="Dreamer's Rock发生过什么？",a="纳拉雷克斯来到这处洞室，试图汲取翡翠梦境的力量，为贫瘠荒芜的贫瘠之地恢复葱郁生机。然而，黑暗腐化侵入了他的梦境，将他崇高的沉眠扭曲成清醒的噩梦。他混乱心智中的恐怖之物化为实体，挣脱出来进入洞穴，腐化了他的追随者和周围的泉水。",al={"dreamer's rock历史","纳拉雷克斯在这里遭遇了什么","dreamer's rock如何沦陷"}},["70f268b5"]={q="Dreamer's Rock危险吗？",a="这里极其危险。这处洞室位于洞穴腐化的核心，直接暴露在纳拉雷克斯扭曲的潜意识之下。任何试图惊扰或唤醒这位沉睡德鲁伊的举动，都会引来凶恶的噩梦异形；它们急于让他继续受困，其中包括名为吞噬者穆坦努斯的巨型怪物。",al={"dreamer's rock有多危险","dreamer's rock的威胁","dreamer's rock安全吗"}}},fp="14,367,22.553.0,20.496.1,34.254.0,42.199.0,42.196.1,41.259.0"}
P.entries["subzone:drowned-reef"] = {n="水下暗礁",s="水下暗礁是阿拉希高地南侧悬崖外一片危险的沿海水域。波涛之下埋藏着古老的沉没遗迹，被充满敌意的Daggerspine纳迦所占据，他们似乎能够控制海湾的潮汐，威胁着过往的船只。",h="水下暗礁是阿拉希高地南侧悬崖外一片危险的沿海水域。波涛之下埋藏着古老的沉没遗迹，被充满敌意的Daggerspine纳迦所占据，他们似乎能够控制海湾的潮汐，威胁着过往的船只。",kw={"阿拉希高地","daggerspine","水下暗礁","法迪尔海湾","maiden's folly","纳迦","prince nazjak","spirit of silverpine","沉没的遗迹"},ang={["race:NightElf"]="暗礁下被淹没的大厅和散落在海底的钙化宝石，是Kaldorei帝国在万年前的Great Sundering中沉入大海的沉痛遗迹。"},sec={{t="船只的坟墓",b="在法迪尔海湾的隐藏入口外，水下暗礁成为了航海者的水下坟墓。破碎的船只，包括Maiden's Folly和Spirit of Silverpine，沉没在波涛之下。由Prince Nazjak领导的Daggerspine纳迦占据了这片暗礁，他们似乎能够控制海湾的潮汐，让那些在海湾寻找Seeking Refuge的船员陷入绝境。"},{t="沉没之城",b="那些足够勇敢或愚蠢的人潜入深水，将会发现一座古老精灵城市的沉没建筑。钙化的精灵宝石仍散落在其被淹没的遗迹之中。"}},faq={{q="什么是水下暗礁？",a="水下暗礁是位于阿拉希高地南海岸的一片危险海洋区域，坐落在法迪尔海湾离岸不远处。它以其浅滩、沉船浅滩以及潜伏在海面下的古老遗迹而闻名。",al={"水下暗礁","水下暗礁在哪里","阿拉希暗礁"}},{q="为什么这里有这么多沉船？",a="这片暗礁对于航行在阿拉希南海岸的船只来说非常危险。其Daggerspine纳迦似乎能够控制海湾的潮汐，威胁着那些试图在法迪尔海湾寻找Seeking Refuge的船员。",al={"船只为何沉没","阿拉希沉船","maidens folly"}},{q="谁控制着水下暗礁？",a="这片暗礁由Daggerspine部落的纳迦居住，他们栖息在被淹没的遗迹中。他们当地的军队由Prince Nazjak指挥，他命令他们猎杀搁浅的水手并保卫他们潜入水下的领地。",al={"是谁领导这里的纳迦","prince nazjak","daggerspine naga 阿拉希"}},{q="暗礁下沉没的遗迹是什么？",a="暗礁包含了古老精灵城市的遗迹，钙化的精灵宝石散落在其沉没的废墟中。",al={"阿拉希水下遗迹","水下暗礁的精灵遗迹"}}},fp="12,261,20.358.0,15.177.0,25.229.0,40.187.0,30.228.0,46.108.0"}
P.entries["subzone:drowned-sacellum"] = {n="Drowned Sacellum",s="Drowned Sacellum是一座位于黑暗深渊入口内的精灵神龛。它浸没在咸水中，布满了巨大的树根，其破碎的砖石结构如今已被鱼人和纳迦所占据。",h="Drowned Sacellum是一座位于黑暗深渊入口内的精灵神龛。它浸没在咸水中，布满了巨大的树根，其破碎的砖石结构如今已被鱼人和纳迦所占据。",kw={"黑暗深渊","drowned sacellum","纳迦","鱼人","神龛","佐拉姆海岸"},ang={["class:Druid"]="巨大的树根继续从地表穿透石质天花板，证明了即使在被腐蚀的地下水域中，自然依然顽强存在。",["race:NightElf"]="看到一座古老的神圣神龛被淹没在咸水中，并被鱼人玷污，这令人苦涩地想起那段沉没在佐拉姆海岸下的卡多雷圣迹。"},sec={{t="沉没的圣所",b="穿过黑暗深渊的入口，探险者会立刻进入Drowned Sacellum。这里曾是一座供奉艾露恩的宁静地下礼拜堂，但早已坍塌，沉入了灰谷海岸下方的深海裂隙之中。咸水池吞没了布满海星的古老大理石地砖，巨大的树根从上方的洞穴顶部垂下。阴暗中，只有昏暗闪烁的小精灵提供着微光，照亮了一条残破的石径，冒险者必须小心翼翼地穿过这里，才能抵达神庙建筑群深处的Pool of Ask'ar。"},{t="食腐者的巢穴",b="Drowned Sacellum早已被暗夜精灵看护者遗弃，落入了海岸食腐者的手中。成群结队的凶猛鱼人和身披重甲的纳迦在浑浊的水中并肩栖息，袭击任何胆敢打扰它们筑巢地的人。虽然神庙深处潜伏着更黑暗的邪教威胁，但这些掠食性生物构成了通往这些地下遗迹的第一道危险防线。"}},faq={{q="Drowned Sacellum最初是用来做什么的？",a="Sacellum是一种小型无顶神龛或礼拜堂。在大分裂之前的古代，它曾是供奉月神艾露恩的宏大地下神庙建筑群中的一处精灵礼拜场所。",al={"drowned sacellum用途","什么是drowned sacellum","sacellum历史"}},{q="什么生物栖息在洞穴的这一区域？",a="被淹没的遗迹主要被野生鱼人和纳迦占据。它们在咸水池和洞穴的筑巢缝隙中繁衍生息。",al={"drowned sacellum怪物","drowned sacellum里住着什么","drowned sacellum中的野兽"}},{q="如何穿过Drowned Sacellum？",a="旅行者必须小心地跳过水中半淹没的破碎平台和石柱，才能进入通往Pool of Ask'ar的隧道。",al={"如何通过drowned sacellum","drowned sacellum跳跃","前往pool of askar的路径"}},{q="洞穴里的光是从哪里来的？",a="昏暗而诡异的光芒来自漂浮在厚重、扭曲的树根间的小精灵，这些树根是从上方的灰谷森林穿透洞顶延伸下来的。",al={"为什么它在发光","drowned sacellum里的小精灵","drowned sacellum照明"}}},fx={b0803046={q="Drowned Sacellum是什么地方？",a="Drowned Sacellum是一座地下废弃神殿，位于黑暗深渊洞穴入口内不远处。它半淹没在一池漆黑的咸水中，古老的石墙上如今布满海星，上方洞顶垂下的粗壮树根也将它缠绕得密不透风。",al={"drowned sacellum是什么地方","drowned sacellum背景故事","黑暗深渊的drowned sacellum"}},["515e8f31"]={q="为什么叫Drowned Sacellum？",a="Sacellum意为小型的祝圣神殿或礼拜堂。这处圣所之所以有了这个阴森的名字，是因为周围的海水渗入地下洞穴，将它的殿室彻底淹没，让神圣的祭坛也有一部分沉在咸水之下。",al={"drowned sacellum的来历","drowned sacellum名称含义","sacellum名称由来"}},["97f28086"]={q="Drowned Sacellum危险吗？",a="是的。这座被淹没的神殿曾是神圣的礼拜之地，如今却遍布好斗的鱼人和披甲的巨钳龙虾。它们共同栖息在浑浊的水池和残破的石柱间，会凶狠地攻击任何试图深入黑暗深渊洞穴的人。",al={"drowned sacellum安全吗","drowned sacellum的威胁","drowned sacellum的危险"}}},fp="16,230,21.592.0,17.434.0,50.210.0,48.149.0,46.172.0,45.165.0"}
P.entries["subzone:dry-hills"] = {n="无水岭",s="无水岭构成了贫瘠之地崎岖的西北角，紧靠着石爪山脉的山麓。尽管名字叫“无水”，这些高地的植被却比下方干旱的平原要绿得多，不过由于沿途峭壁上栖息着具有攻击性的巫翼鹰身人，此地以危险而闻名。",h="无水岭构成了贫瘠之地崎岖的西北角，紧靠着石爪山脉的山麓。尽管名字叫“无水”，这些高地的植被却比下方干旱的平原要绿得多，不过由于沿途峭壁上栖息着具有攻击性的巫翼鹰身人，此地以危险而闻名。",kw={"贫瘠之地","无水岭","黄金之路","鹰身人","瑟瑞娜·血羽","石爪山脉","巫翼"},ang={["class:Hunter"]="这片崎岖的高地提供了丰富的狩猎场，到处都是敏捷的嘲牙土狼、掠食性的日鳞迅猛龙和凶猛的鹰身人。",["faction:Horde"]="在无水岭筑巢的巫翼鹰身人对连接十字路口至石爪山脉和灰谷的北部贸易动脉构成了持续的威胁，需要部落的勇士们定期进行清理。"},sec={{t="鹰身人的绿色避难所",b="无水岭位于干旱平原向石爪山脉抬升的地带，其命名多少有些名不副实，因为这里拥有比南面被太阳灼晒的稀树草原更为繁茂的灌木丛。然而，这片郁郁葱葱的山麓地区对旅行者来说几乎没有任何安全可言。悬崖上盘踞着由女族长瑟瑞娜·血羽领导的巫翼鹰身人。她们的劫掠小队从这些高地上俯冲而下，袭击使用黄金之路北部路段的补给车队，将荒废的兽人防御工事和废弃的攻城器械丢弃在灌木丛中任其腐烂。"},{t="对十字路口的威胁",b="由于巫翼鹰身人经常从山上冲出，劫掠贸易路线并骚扰附近的定居点，部落因此悬赏征集鹰身人的羽毛。深入岩石峡谷的冒险者不仅会遇到重兵把守的鹰身人巢穴和栖木，还会碰到在高地四处捕食的嘲牙土狼和凶猛的日鳞迅猛龙。"}},faq={{q="既然这里这么绿，为什么叫无水岭？",a="尽管名字叫无水岭，但这里的植被明显比周围的贫瘠之地更为葱郁。该名称的由来以及这种局部对比的原因并无记载。",al={"为什么叫无水岭","无水岭的绿色植被","无水岭的地形"}},{q="谁居住在无水岭？",a="这片丘陵几乎完全由瑟瑞娜·血羽统治的巫翼鹰身人部落所控制。嘲牙土狼和日鳞迅猛龙等野生野兽也出没在岩石斜坡上。",al={"谁在无水岭","无水岭的居民","无水岭的鹰身人"}},{q="为什么部落对这个地区感兴趣？",a="巫翼掠夺者经常从山上下来，劫掠沿黄金之路北部行驶的补给车队，这促使部落指挥官悬赏以削减她们的数量并消灭她们的头目。",al={"部落在无水岭","为什么在这里战斗鹰身人","无水岭的任务"}},{q="丘陵中间的废墟塔楼和投石车是什么？",a="那是兽人废弃前哨站的遗迹。幸存的建筑结构无法证实其最初的任务或被废弃的原因。",al={"无水岭的兽人塔楼","无水岭的废弃投石车","无水岭的兽人遗迹"}}},fx={["06447f2d"]={q="无水岭是什么地方？",al={"无水岭是什么地方","无水岭背景故事","无水岭信息"}},["9a122504"]={q="无水岭危险吗？",a="深入无水岭十分危险。险峻的山岩由女巫岭鹰身人严密把守，她们由塞瑞娜·血羽率领，会主动袭击沿北部黄金之路行进的补给车队。除了鹰身人和伏击者，凶猛的赫克雷尔豺狼人和太阳鳞迅猛龙也在山脊间徘徊，毫无准备、偏离道路的人随时可能被它们撕碎。",al={"无水岭安全吗","无水岭的威胁","无水岭的危险"}}},fp="9,319,25.579.0,24.388.0,48.166.0,27.189.0,41.214.0,68.139.0"}
P.entries["subzone:drygulch-ravine"] = {n="枯水谷",s="枯水谷是一条崎岖隐蔽的峡谷，深藏在杜隆塔尔东部的岩石峭壁之中。这处沟壑只能通过烈风峡谷中一条隐秘的洞穴通道进入，或者从上方危险地跳下才能到达，里面盘踞着筑巢的尘风鹰身人，它们时刻威胁着附近的补给车队。",h="枯水谷是一条崎岖隐蔽的峡谷，深藏在杜隆塔尔东部的岩石峭壁之中。这处沟壑只能通过烈风峡谷中一条隐秘的洞穴通道进入，或者从上方危险地跳下才能到达，里面盘踞着筑巢的尘风鹰身人，它们时刻威胁着附近的补给车队。",kw={"枯水谷","杜隆塔尔","尘风鹰身人","鹰身人巢穴","奥格瑞玛","烈风峡谷","stolen supplies"},ang={["faction:Horde"]="清理峡谷中的巢穴并找回被盗物资，有助于保护杜隆塔尔内部贸易路线免受持续的劫掠。",["race:Orc"]="枯水谷是边境耐力的一项考验，年轻的兽人们在此磨练意志，对抗栖息在家园岩石峭壁上的凶猛鹰身人。"},sec={{t="赤色石中的强盗避风港",b="枯水谷深深地凿刻在奥格瑞玛以东的岩壁中，几乎与外界隔绝。它唯一的地面入口是连接烈风峡谷的一条狭窄自然隧道。盘踞在此的尘风鹰身人将这处避风的低地变成了杜隆塔尔一处无法无天的地方。这些带翼的拾荒者利用陡峭的悬崖面来筑巢，并囤积从经过该地区道路的部落补给车队中抢来的货物。"},{t="杜隆塔尔的眼中钉",b="鹰身人构成了直接的威胁。它们的女族长会凶猛地守卫着安置在高处岩架上的鸟蛋，部落侦察兵经常派遣年轻战士去清理鸟群，找回被掠夺的贸易板条箱，并打破鹰身人对这条峡谷的控制。"}},faq={{q="如何进入枯水谷？",a="除非你能从上方的高耸悬崖跳下并幸存，否则唯一的地面路线就是通过邻近烈风峡谷内的一处小型洞穴入口。",al={"枯水谷入口","如何进入枯水谷","枯水谷洞穴在哪里"}},{q="枯水谷里居住着什么生物？",a="峡谷中主要栖息着尘风鹰身人，它们在嶙峋的岩架上筑巢、产卵并囤积劫掠来的车队补给品。",al={"枯水谷怪物","枯水谷里有什么","谁住在枯水谷"}},{q="部落为什么要关注这条峡谷？",a="尘风鹰身人袭击杜隆塔尔重要的贸易路线，并在峡谷中囤积被盗货物。剃刀岭的部落当局经常派遣新兵去回收物资并清理鸟群。",al={"为什么要杀枯水谷的鹰身人","枯水谷任务","部落对枯水谷的兴趣"}}},fx={["7b842580"]={q="枯水谷是什么地方？",a="枯水谷是杜隆塔尔崎岖山岩间一处僻静的陡壁峡谷。人们通常要从烈风峡谷旁一处狭窄的洞口进入，这里形成了一道避开开阔平原的隐蔽裂谷。如今，它成了尘风鹰身人的筑巢地，远离部落的主要聚居地。",al={"枯水谷是什么地方","枯水谷背景故事","枯水谷信息"}},c29d93c1={q="枯水谷危险吗？",a="没有护卫的旅人和补给车队经过枯水谷时会面临危险。高耸的峭壁被凶猛的尘风鹰身人占据，它们会从巢穴俯冲而下，袭击闯入者并劫掠经过的部落运输队。谷中悬崖陡峭、缝隙狭窄，行进时很容易遭到伏击，尤其是在它们的高处巢穴附近，最凶猛的鹰身人会极力守护幼崽。",al={"枯水谷危险吗","枯水谷的威胁","枯水谷有多危险"}}},fp="15,284,31.456.0,25.264.0,36.152.0,39.141.0,42.189.0"}
P.entries["subzone:drywhisker-gorge"] = {n="枯须峡谷",s="枯须峡谷是阿拉希高地东部山区的一处崎岖裂隙，位于部落据点落锤镇的东北方。峡谷及其内部洞穴被一个充满敌意的狗头人氏族占据，他们激烈地守卫着埋藏在深地下的丰富矿藏和古老的元素遗物。",h="枯须峡谷是阿拉希高地东部山区的一处崎岖裂隙，位于部落据点落锤镇的东北方。峡谷及其内部洞穴被一个充满敌意的狗头人氏族占据，他们激烈地守卫着埋藏在深地下的丰富矿藏和古老的元素遗物。",kw={"阿拉希高地","枯须","枯须峡谷","落锤镇","狗头人","次级血石矿","迈兹拉尔公主","石片"},ang={["faction:Horde"]="充满敌意的枯须狗头人盘踞在落锤镇另一侧的山脊上，是对该据点东侧边翼挥之不去且难以预测的威胁。",["profession:Mining"]="矿工们视枯须洞穴为目前已知的唯一次级血石矿来源，这是一种致密、带有深红色纹路的矿物，埋藏在被狗头人占据的岩石深处。"},sec={{t="东部峭壁中的巢穴",b="枯须峡谷隐藏在落锤镇以东的山峦褶皱中，是枯须狗头人氏族的主要据点。虽然狗头人常被视为简单的矿洞害虫，但阿拉希的枯须氏族却根基深厚。他们以极强的领地意识守卫着地下的通道，开采稀有的次级血石矿，并防守着大地深处的隐秘角落。他们的存在对附近的落锤镇兽人来说是一个持续的麻烦。"},{t="深层洞穴的秘密",b="穿过火把照亮的路障和蜿蜒的隧道，洞穴展现出的秘密远比普通的十字镐和蜡烛更为阴暗。枯须狗头人与高地高耸的石巨人结盟，侍奉着古老的土元素魔法微粒。洞穴深处藏着一块神秘的石片，其中囚禁着被束缚在地表之下的古老土元素实体——迈兹拉尔公主的精华碎片。"}},faq={{q="谁居住在枯须峡谷？",a="峡谷及其洞穴网络由枯须狗头人氏族居住。他们积极防御外来者，同时守护着他们的采矿作业和隐藏在其中的古老遗物。",al={"枯须峡谷的居民","枯须峡谷里有什么","谁控制着枯须峡谷"}},{q="枯须峡谷位于何处？",a="峡谷穿过阿拉希高地崎岖的东部山脉，位于部落定居点落锤镇的正东北方。一条崎岖的小径穿过据点以东的丘陵，通向洞穴入口。",al={"如何前往枯须峡谷","枯须峡谷位置","阿拉希的洞穴在哪里"}},{q="内部的洞穴为何重要？",a="除了蕴藏着稀有的次级血石矿外，洞穴中还庇护着一块古老的石片。这件遗物中包含着被囚禁的强大地下实体——迈兹拉尔公主的精华碎片。",al={"洞穴里有什么","枯须洞穴的秘密","迈兹拉尔碎片"}},{q="为什么狗头人与山地巨人结盟？",a="枯须氏族与当地的石巨人有联系，他们侍奉并守卫着与阿拉希地底深处迈兹拉尔公主封印相关的土元素遗物和魔法微粒。",al={"狗头人与巨人","为什么枯须氏族与巨人在一起"}}},fp="16,304,29.490.0,26.438.1,30.210.0,34.225.0,39.209.0,48.188.0"}
P.entries["subzone:dun-algaz"] = {n="丹奥加兹",s="丹奥加兹是连接洛克莫丹与湿地的坚固山口和隧道网络。在第二次战争期间，这里曾是兵家必争之地，而这条重要的贸易动脉最近遭到龙喉兽人的围攻，阻断了铁炉堡领地与米奈希尔港之间的便利通行。",h="丹奥加兹是连接洛克莫丹与湿地的坚固山口和隧道网络。在第二次战争期间，这里曾是兵家必争之地，而这条重要的贸易动脉最近遭到龙喉兽人的围攻，阻断了铁炉堡领地与米奈希尔港之间的便利通行。",kw={"奥加兹大门","奥加兹岗哨","龙喉氏族","丹奥加兹","洛克莫丹","米奈希尔港","山口","湿地"},ang={["faction:Alliance"]="这条穿过丹奥加兹的路线对联盟的后勤至关重要，它保障了连接米奈希尔港与洛克莫丹和铁炉堡的陆路交通。",["race:Dwarf"]="对矮人而言，丹奥加兹是穿过卡兹莫丹脊梁的祖传通道。目睹龙喉兽人占据矮人堡垒并威胁通往米奈希尔港的补给线，这是一种持续的羞辱，也是一场安全危机。"},sec={{t="联通诸界的咽喉",b="丹奥加兹的历史可以追溯到三锤之战以前，最初是蛮锤氏族被驱逐出铁炉堡后向北迁移所经过的通道。该山口在分隔洛克莫丹与湿地的崎岖山峰中凿深而成，由蜿蜒的石制隧道、堡垒和岗哨组成。其战略价值不言而喻：谁掌握了丹奥加兹，谁就控制了连接矮人腹地与米奈希尔港西海岸的唯一陆路通道。"},{t="龙喉氏族的卷土重来",b="在第二次战争期间，旧部落在丹莫德战败后撤退至丹奥加兹，将其变为对抗安度因·洛萨爵士军队的最后一道南方堡垒。尽管联盟曾一度夺回该山口，但龙喉兽人再次占领了这座要塞，迫使矮人登山者撤退到上层隧道，并将这条山间走廊变成了旅行者的死亡陷阱。"}},faq={{q="为什么现在的丹奥加兹如此危险？",a="龙喉兽人从周围的山脉中倾巢而出，夺取了下层山口和要塞的控制权。矮人登山者被迫退守至奥加兹岗哨附近的上层山口，主路上到处都是敌对的兽人，他们埋伏着试图往来于洛克莫丹和湿地之间的旅行者。",al={"为什么丹奥加兹会有兽人","丹奥加兹的兽人","谁控制着丹奥加兹"}},{q="为什么这个山口对矮人如此重要？",a="丹奥加兹是连接铁炉堡和洛克莫丹与湿地境内米奈希尔港的主要陆路通道。米奈希尔港是卡兹莫丹与联盟其他领土之间的主要航运门户，这使得丹奥加兹成为补给、军队和贸易不可或缺的走廊。",al={"丹奥加兹的重要性","为什么铁炉堡需要丹奥加兹"}},{q="丹奥加兹在第二次战争中发挥过作用吗？",a="是的。在丹莫德战败后，兽人部落撤退穿过萨多尔谷地，将丹奥加兹设为防御据点。安度因·洛萨爵士下令进攻以驱逐他们并将他们赶出卡兹莫丹，但联盟未能彻底根除部落，使其成为了他们在该地区最后的据点之一。",al={"丹奥加兹与第二次战争","安度因·洛萨与丹奥加兹"}},{q="丹奥加兹与蛮锤矮人之间有什么历史渊源？",a="早在第二次战争之前，在古老的三锤之战期间，蛮锤矮人被驱逐出铁炉堡。他们穿过丹奥加兹向北迁移至湿地，并最终定居在格瑞姆巴托。",al={"蛮锤矮人与丹奥加兹","三锤之战的山口"}}},fx={e0cd650e={q="丹奥加兹是什么地方？",a="丹奥加兹是一系列开凿于山中的隧道和山地壁垒，穿过群峰，连接洛克莫丹与湿地。它曾是一处坚固的矮人要塞，也是铁炉堡通往北部海岸的主要陆路通道。这座设防关隘保障了卡兹莫丹腹地与米奈希尔港之间的重要交通。",al={"丹奥加兹是什么地方","丹奥加兹关隘","丹奥加兹关口"}},f60a7bc4={q="谁控制着丹奥加兹？",a="丹奥加兹大部分地区已落入龙喉兽人之手。尽管矮人巡山人仍守卫着上层隧道，并守住来自洛克莫丹的北部入口，但敌对的龙喉劫掠者已在下层区域和山路各处站稳脚跟，夺取了关隘的控制权。",al={"谁住在丹奥加兹","谁控制丹奥加兹","谁掌控丹奥加兹"}},["59a004f5"]={q="矮人为什么放弃丹奥加兹？",a="龙喉氏族的残部发动猛烈袭击后，这座要塞便被放弃了。兽人击溃了驻守要塞的矮人守军，迫使铁炉堡的巡山人撤退，并在关隘上层隧道重新集结防线，导致大部分道路失修并被敌军占据。",al={"丹奥加兹为何被放弃","丹奥加兹为何成了废墟","矮人为何离开丹奥加兹"}}},fp="9,301,27.477.0,24.415.0,40.320.0,45.296.0,44.336.0,65.229.0"}
P.entries["subzone:dun-garok"] = {n="丹加洛克",s="丹加洛克是一座防御严密的矮人山地堡垒，位于希尔斯布莱德丘陵的东南部高地。在该哨所指挥官铁丘上尉的率领下，这支坚定的卫戍部队保卫着联盟在这一地区的利益，并保护碧玉矿洞等附近的作业点免受敌对势力的侵扰。对于塔伦米尔的被遗忘者来说，这座根深蒂固的矮人据点是紧邻他们领地的一个持续军事威胁。",h="丹加洛克是一座防御严密的矮人山地堡垒，位于希尔斯布莱德丘陵的东南部高地。在该哨所指挥官铁丘上尉的率领下，这支坚定的卫戍部队保卫着联盟在这一地区的利益，并保护碧玉矿洞等附近的作业点免受敌对势力的侵扰。对于塔伦米尔的被遗忘者...",kw={"碧玉矿洞","丹加洛克","矮人","希尔斯布莱德","铁炉堡","铁丘","要塞","山地猎人"},ang={["faction:Horde"]="这座防御完备的矮人飞地对被遗忘者的扩张以及塔伦米尔周边的边境安全构成了持续的威胁，使其卫戍部队成为了重点打击目标。",["race:Dwarf"]="丹加洛克是铁炉堡势力延伸至洛丹伦的骄傲象征，铁丘上尉和他的山地猎人们坚守在那里，保卫着他们的人类盟友。"},sec={{t="丘陵中的堡垒",b="丹加洛克开凿在希尔斯布莱德丘陵崎岖的东南部山地中，是一座由铁炉堡山地猎人和火枪手严密防守的堡垒。在铁丘上尉的指挥下，这里的矮人维持着关键的防线，护卫着希尔斯布莱德的人类定居点，并确保了碧玉矿洞的关键作业安全。他们坚固的石质建筑和深沟固垒为联盟提供了一个抵御附近威胁的据点。"},{t="塔伦米尔的目标",b="由于丹加洛克紧邻塔伦米尔，被遗忘者将其视为对南部边境的一种不可容忍的侵入。Sylvanas Windrunner的军队厌恶在他们据点附近驻扎重装矮人部队，并经常密谋渗透这座要塞，瓦解其防御，消灭铁丘上尉的卫戍部队，从而确保被遗忘者对希尔斯布莱德的统治。"}},faq={{q="丹加洛克是什么？",a="丹加洛克是一座防御严密的矮人哨所，位于希尔斯布莱德丘陵的东南部山区。这里驻扎着来自铁炉堡的军队，专门负责保卫联盟在这一地区的领地。",al={"丹加洛克位置","这座矮人要塞是什么","希尔斯布莱德矮人要塞"}},{q="谁指挥着丹加洛克？",a="这座据点由铁丘上尉指挥，他带领当地的山地猎人和火枪手保卫着希尔斯布莱德和附近的碧玉矿洞。",al={"丹加洛克指挥官","谁指挥丹加洛克","铁丘上尉"}},{q="为什么被遗忘者想要摧毁丹加洛克？",a="被遗忘者认为在他们南部边境有一个活跃的、防御严密的矮人据点，这对塔伦米尔构成了重大的安全威胁，因此他们积极派遣特工来消灭那里的卫戍部队。",al={"为什么部落攻击丹加洛克","被遗忘者 丹加洛克","塔伦米尔 丹加洛克冲突"}},{q="丹加洛克对联盟的战略价值是什么？",a="丹加洛克是希尔斯布莱德的一个关键军事据点，有助于维护联盟在该区域的安全，并保护附近的碧玉矿洞免受敌对势力的侵占。",al={"为什么丹加洛克很重要","联盟在丹加洛克的目的"}}},fx={b8973178={q="丹加洛克发生过什么？",a="丹加洛克是一座矮人要塞，建在东南部的丘陵中，用以守卫附近的人类聚居地和碧玉矿洞。自被遗忘者在洛丹伦建立统治以来，他们一直视这座矮人堡垒为严重的军事威胁，频繁派遣士兵和雇佣兵骚扰守军，并试图将其铲除。",al={"丹加洛克历史","这里发生过什么","丹加洛克背景故事"}},d2b489e2={q="丹加洛克危险吗？",a="是的。这座要塞防御森严，由纪律严明的矮人士兵驻守，队长是铁山上尉。部落成员和被遗忘者若进入丹加洛克，会立刻遭到精锐火枪手和山地卫兵的敌视；他们会以顽强的决心守卫堡垒。",al={"丹加洛克安全吗","丹加洛克的危险","丹加洛克的威胁"}}},fp="9,417,26.450.0,21.400.0,18.195.0,23.151.0,46.186.0,52.169.0"}
P.entries["subzone:dun-mandarr"] = {n="丹曼达尔",s="丹曼达尔是一个被遗弃的矮人营地，位于冬泉谷东南部的一个冰冷洞穴前。该营地由矮人贾伦·石塑者建立，但在其居住者遭受愤怒的当地枭兽袭击并逃离后，如今已是一片废墟。",h="丹曼达尔是一个被遗弃的矮人营地，位于冬泉谷东南部的一个冰冷洞穴前。该营地由矮人贾伦·石塑者建立，但在其居住者遭受愤怒的当地枭兽袭击并逃离后，如今已是一片废墟。",kw={"蓝羽护符","丹曼达尔","矮人营地","贾伦·石塑者","枭兽","冬泉谷"},ang={["class:Druid"]="守卫丹曼达尔的枭兽极度捍卫自然和天界圣物，当蓝羽护符这类神圣遗物被外来者触碰时，它们会做出激烈的反应。",["race:Dwarf"]="这处遗迹保留了传统的矮人命名方式，也成为了一个惨痛的警示，提醒人们在古老的卡利姆多进行考古探险时，稍有不慎就可能酿成灾难。"},sec={{t="被遗弃的营地",b="丹曼达尔采用了传统的矮人命名习惯，由探险家贾伦·石塑者建立，作为他在冬泉谷东南部冰原上的行动基地。然而，当他挖掘出一件名为“蓝羽护符”的圣物时，他的好奇心却成了他失败的根源。这件神器的出现激怒了当地的枭兽，它们陷入了无法抑制的狂怒，向营地发起了猛攻。在人数众多的枭兽面前，矮人们被迫撤离，彻底放弃了营地。如今，积雪之中已无友好的灵魂，凶猛且具有领地意识的枭兽守卫着洞穴，并在残破的棚屋中徘徊。"}},faq={{q="丹曼达尔营地发生了什么事？",a="丹曼达尔由矮人探险家贾伦·石塑者建造。在挖掘该地区时，他发现了一个神秘的蓝羽护符。这件圣物极大地激怒了周围的枭兽，它们对定居点发动了猛烈的攻击。贾伦和他的同伴们被迫撤离，留下了一座被废弃且遭侵占的前哨站。",al={"为什么丹曼达尔会被废弃","谁建造了丹曼达尔","什么是丹曼达尔"}},{q="为什么这里有这么多枭兽？",a="当地的枭兽将洞穴及周围的圣物视为神圣之物。当贾伦·石塑者挖掘出蓝羽护符时，这些生物陷入了疯狂，为了夺回圣物并保卫领地，它们驱逐了入侵者，并将营地占为己有。",al={"为什么这里有枭兽","丹曼达尔枭兽","为什么枭兽会攻击"}},{q="贾伦·石塑者去了哪里？",a="在被暴怒的枭兽赶出营地后，贾伦·石塑者撤退到了冬泉谷的其他地方进行重组，并试图寻求帮助以收回他被窃的研究资料和装备。",al={"贾伦·石塑者在哪里","贾伦·石塑者位置"}}},fp="11,236,15.618.0,41.324.0,35.280.0,31.182.0"}
P.entries["subzone:dun-modr"] = {n="丹莫德",s="丹莫德是一座位于湿地北部的古老矮人要塞城镇，守卫着通往萨多尔大桥的南部通道。它曾是一座在多次战争中被反复争夺的关键要塞，但最近被一股敌对的黑铁矮人势力攻占了。",h="丹莫德是一座位于湿地北部的古老矮人要塞城镇，守卫着通往萨多尔大桥的南部通道。它曾是一座在多次战争中被反复争夺的关键要塞，但最近被一股敌对的黑铁矮人势力攻占了。",kw={"邪恶的巴尔加拉斯","黑铁矮人","丹莫德","铁炉堡","卫山者","萨多尔大桥","湿地"},ang={["faction:Alliance"]="丹莫德的陷落威胁到了穿越萨多尔大桥的关键交通路线，切断了铁炉堡与北部联盟残部之间的便捷往来。",["race:Dwarf"]="看到一座历史悠久的铜须山地定居点落入背信弃义的黑铁氏族手中，是一种令人痛苦的羞辱，必须予以复仇。"},sec={{t="饱经战火的堡垒",b="丹莫德坐落在湿地的北缘，扼守着连接卡兹莫丹与北部人类王国的主要陆路交通要道。由于其至关重要的地理位置，这座要塞在过去几十年里经历了多次血腥的战斗。在第二次战争期间，兽人部落占领了这座矮人要塞并在此驻扎，将其作为发动袭击和抵御联盟军队的前进基地。斯托姆加德的战士们从托尔巴拉德发起了一场残酷的两栖突袭以夺回要塞，但随后兽人进行了猛烈的反扑，双方展开了血腥的拉锯战。最终，安度因·洛萨爵士率领的联盟军队将入侵者赶过了萨多尔大桥，恢复了矮人对这座堡垒的管辖。"},{t="黑铁入侵",b="随着铁炉堡的注意力被分散，许多精锐的卫山者被派往海外执行联盟任务，丹莫德变得极其脆弱。黑铁入侵者抓住机会向北推进，用炸药破坏了萨多尔大桥，随后蜂拥攻占了要塞。在黑铁术士邪恶的巴尔加拉斯的指挥下，这些渗透者击溃了城镇的守军，驱逐了铜须驻军，并将这个战略前哨变成了一个敌对的巢穴。周围的卫山者现在只能在路边维持着严峻的防线，绝望地寻求援助以驱逐占领者。"}},faq={{q="为什么丹莫德如此重要？",a="丹莫德直接坐落在湿地通往萨多尔大桥的主要北向道路上。控制这座要塞意味着控制了卡兹莫丹与洛丹伦大陆北部之间所有的陆路交通、补给线和军事调动。",al={"为什么丹莫德很重要","丹莫德的重要性","丹莫德的战略价值"}},{q="目前是谁在控制丹莫德？",a="这座要塞已经被黑铁氏族占领，由术士“邪恶的”巴尔加拉斯在现场指挥。忠于铁炉堡的铜须卫山者在附近设立了一个警戒营地，希望能夺回要塞。",al={"谁在丹莫德","谁控制了丹莫德","谁住在丹莫德"}},{q="丹莫德在第二次战争中发生了什么？",a="兽人部落占领了该镇并将其改造成了一个前进军事基地。斯托姆加德军队从托尔巴拉德岛发起进攻试图夺回遗迹，引发了激烈的冲突，直到安度因·洛萨率领的联盟军队最终将部落势力从该地区清除。",al={"第二次战争丹莫德","丹莫德的兽人","部落是否占领了丹莫德"}},{q="谁是“邪恶的”巴尔加拉斯？",a="“邪恶的”巴尔加拉斯是领导占领丹莫德的黑铁术士。在他的指挥下，黑铁矮人成功破坏了萨多尔大桥，并将当地的铁炉堡守军赶出了要塞。",al={"邪恶的巴尔加拉斯背景故事","巴尔加拉斯是谁","丹莫德的黑铁领袖"}}},fx={["9363f36e"]={q="丹莫德是什么地方？",a="丹莫德是一座古老的矮人设防城市，坐落在湿地北部主干道旁，萨多尔大桥以南。它曾是一处繁荣的据点，拥有自己的铁匠铺和旅店；历史上，这里守卫着卡兹莫丹与洛丹伦北部王国之间的门户。",al={"丹莫德是什么","丹莫德背景","关于丹莫德"}},["72873e9f"]={q="丹莫德为何沦为废墟？",a="铁炉堡派遣山地矮人和士兵远赴艾泽拉斯各地，为联盟而战时，黑铁矮人从内部袭击了这片防备薄弱的地区。他们破坏了萨多尔大桥，攻陷了兵力空虚的丹莫德防线，让这座城市在硝烟中化为废墟。",al={"丹莫德为何被毁","丹莫德陷落","丹莫德为何化为废墟"}},["3c329954"]={q="丹莫德危险吗？",a="这里极其危险。丹莫德遍布敌对的黑铁矮人，他们由邪恶的术士 Balgaras the Foul 率领。试图穿过萨多尔大桥北上的旅人若不谨慎行事，或不帮助附近驻守的矮人山地部队，就有遭到伏击的风险。",al={"丹莫德的威胁","丹莫德危险吗","丹莫德附近安全吗"}}},fp="8,249,19.711.0,23.604.0,29.258.0,32.197.0,48.257.0,25.208.0"}
P.entries["subzone:dunemaul-compound"] = {n="砂槌营地",s="砂槌营地是砂槌食人魔氏族在塔纳利斯的中心聚居地和食人魔土丘。它坐落在沙漠荒原边缘的岩石山脊中，是该氏族野蛮的执行者和施法者的居住地。",h="砂槌营地是砂槌食人魔氏族在塔纳利斯的中心聚居地和食人魔土丘。它坐落在沙漠荒原边缘的岩石山脊中，是该氏族野蛮的执行者和施法者的居住地。",kw={"砂槌营地","砂槌食人魔","食人魔土丘","欧姆格恩","塔纳利斯"},ang={["class:Warlock"]="在看似原始的沙漠氏族中出现砂槌术士是一种奇特的景象，这表明暗影和邪能传统即使在偏远的食人魔土丘中也已经扎根。",["faction:Horde"]="虽然许多食人魔曾跟随旧部落远征，但隐居的砂槌食人魔不听命于任何外部势力，并将部落旅行者视为和其他人一样的入侵者。"},sec={{t="沙中的据点",b="砂槌营地开凿在塔纳利斯西部的崎岖沙漠岩石中，是砂槌食人魔的主要据点。这些庞大的沙漠居民已经适应了严酷干旱的气候，依靠蛮力和机会主义艰难生存。营地本身以一个食人魔土丘和洞穴网络为中心。虽然原始，但该氏族拥有战士、执行者和修行黑暗术士与法师魔法的扭曲施法者等危险组合。对于穿过沙丘的旅行者来说，这个定居点是一个充满敌意的巨人们的危险巢穴，他们会暴力拒绝不速之客。"}},faq={{q="谁统治着砂槌营地？",a="戈马洛克（Gor'marok the Ravager）领导着占据营地的砂槌食人魔。加基森的安迪·利恩对这群新到之敌的力量感到恐惧。",al={"砂槌首领","砂槌头目"}},{q="这里居住着什么样的食人魔？",a="该定居点包含多种多样的砂槌食人魔，从普通的蛮兵和执行者，到狡猾的、挥舞着黑暗邪能和暗影魔法的食人魔术士和法师。",al={"砂槌种类","砂槌怪物"}},{q="为什么部落对这个营地感兴趣？",a="没有记录显示部落对该营地感兴趣。砂槌氏族是由戈马洛克领导的一群独立的食人魔，摧毁营地的请求来自加基森的安迪·利恩，他担心他们日益增长的力量会威胁到该地区。",al={"部落与砂槌"}},{q="欧姆格恩（Omgorn the Lost）是谁？",a="欧姆格恩是一个难以捉摸、形单影只的食人魔，据知他偶尔会在砂槌营地的边缘徘徊，与巡逻土丘的普通哨兵不同。",al={"欧姆格恩","塔纳利斯稀有食人魔"}}},fp="17,212,25.602.0,32.140.0,30.169.0,45.258.0,23.165.0"}
P.entries["subzone:durnholde-keep"] = {n="敦霍尔德城堡",s="敦霍尔德城堡是一座位于希尔斯布莱德丘陵，塔伦米尔东部的破碎堡垒。它曾是联盟兽人收容所的指挥中心，也是大酋长萨尔作为俘虏角斗士长大的地方，如今已沦为废墟，被辛迪加的歹徒所占据。",h="敦霍尔德城堡是一座位于希尔斯布莱德丘陵，塔伦米尔东部的破碎堡垒。它曾是联盟兽人收容所的指挥中心，也是大酋长萨尔作为俘虏角斗士长大的地方，如今已沦为废墟，被辛迪加的歹徒所占据。",kw={"布莱克摩尔","敦霍尔德城堡","希尔斯布莱德","收容所","辛迪加","塔蕾莎·福克斯顿","塔伦米尔","萨尔"},ang={["faction:Alliance"]="敦霍尔德曾是洛丹伦防御和正义的基石，如今其破碎的城墙只能作为辛迪加歹徒和暴徒的卑劣巢穴。",["race:Orc"]="敦霍尔德的残垣断壁标志着大酋长萨尔挣脱枷锁的熔炉，结束了数十年的兽人囚禁，并点燃了部落重生的火种。"},sec={{t="囚禁的熔炉",b="敦霍尔德由联盟建造，在第二次战争后作为监管南部收容所的总部。在野心勃勃且腐败的埃德拉斯·布莱克摩尔中将的指挥下，它既是一座行政堡垒，也是一个角斗场。正是在这里，布莱克摩尔抚养了孤儿戈尔，给他取名萨尔，并训练他为了娱乐和利益而战。在塔蕾莎·福克斯顿的帮助下，萨尔逃离了囚禁，随后在新部落的旗帜下联合了分散的兽人氏族。萨尔回到敦霍尔德，对这座堡垒发动了围攻，杀死了布莱克摩尔，并召唤大地之灵摧毁了它的城墙。"},{t="在辛迪加的魔爪下",b="自第三次战争前倒塌以来，敦霍尔德城堡一直是一堆伤痕累累的瓦砾。在洛丹伦陷落后留下的权力真空中，辛迪加的贵族强盗们在城墙间找到了避难所。这些失势的奥特兰克贵族和暴徒在破碎的内院和塔楼中活动，劫掠穿过希尔斯布莱德丘陵的旅行者，将曾经的军事法律执行工具变成了一个重兵把守的流氓前哨站。"}},faq={{q="敦霍尔德城堡为何成为废墟？",a="萨尔率领解放后的部落回到了敦霍尔德，击败了他以前的主人埃德拉斯·布莱克摩尔中将。在杀死布莱克摩尔后，萨尔与大地之灵沟通，摧毁了这座堡垒，使其永远无法再囚禁他的人民。",al={"谁摧毁了敦霍尔德","敦霍尔德城堡发生了什么","为什么敦霍尔德被摧毁了"}},{q="谁目前占据着敦霍尔德城堡？",a="这座要塞被辛迪加所占据，这是一个由被流放的奥特兰克贵族变成的强盗组织。他们利用残破的城墙作为坚固的堡垒，进行抢劫并在希尔斯布莱德各地发起袭击。",al={"谁住在敦霍尔德","敦霍尔德的怪物","敦霍尔德的辛迪加"}},{q="萨尔与这个地方有什么渊源？",a="埃德拉斯·布莱克摩尔发现了还是个婴儿的兽人孤儿，并他在敦霍尔德将其作为奴隶抚养长大。萨尔接受了战术教育，并被迫在竞技场中作为角斗士战斗，直到他在一名名为塔蕾莎·福克斯顿的人类女性帮助下成功逃脱。",al={"萨尔住在这里吗","萨尔的敦霍尔德历史","萨尔曾是这里的囚犯吗"}},{q="这座城堡在第二次战争期间有什么用途？",a="敦霍尔德曾是联盟的要塞。第二次战争结束后，它成为了关押战败兽人的收容所指挥中心，由埃德拉斯·布莱克摩尔中将统治。",al={"第二次战争时期的敦霍尔德","敦霍尔德有什么用途"}}},fx={["1d89eea7"]={q="敦霍尔德城堡是什么地方？",a="敦霍尔德城堡是一座破败的堡垒，位于希尔斯布莱德丘陵的塔伦米尔以东。它曾是一处繁荣的军事据点，设有兵营、竞技场和法师塔；第二次战争结束后，这里成为联盟兽人拘留营的行政指挥中心。如今，它已是一片广阔的废墟，被亡命之徒和拾荒者占据。",al={"敦霍尔德是什么","敦霍尔德城堡概况","敦霍尔德在哪里"}},d850e42f={q="敦霍尔德城堡发生过什么？",a="第二次战争结束后，敦霍尔德成了兽人拘留营的指挥中心，并因中将 Aedelas Blackmoore 而声名狼藉。他将被俘的兽人萨尔留在此处抚养，并把他训练成角斗士。萨尔逃脱后，率领重组的部落返回此地，解放族人。他在战斗中击败了 Blackmoore，并召唤大地之灵，将整座堡垒震成废墟。",al={"敦霍尔德的历史","敦霍尔德背景","敦霍尔德之战"}},e6548fd4={q="敦霍尔德城堡危险吗？",a="危险。坍塌的城墙和周边区域遍布辛迪加成员。辛迪加是一个由前激流堡贵族和强盗组成的激进犯罪组织。他们严密守卫着废墟，会袭击任何靠近营地的旅人或冒险者。",al={"敦霍尔德危险吗","敦霍尔德城堡有哪些威胁","敦霍尔德有哪些危险"}}},fp="14,286,23.665.0,32.442.0,31.269.0,38.203.0,43.258.0,54.194.0"}
P.entries["subzone:dust-plains"] = {n="尘埃平原",s="尘埃平原构成了西部荒野干旱、饱受风蚀的南部边境。这里地表贫瘠，灌木稀疏，不仅被成群凶猛的豺狼人占据，其东侧高地上还矗立着一座古老的法师塔。",h="尘埃平原构成了西部荒野干旱、饱受风蚀的南部边境。这里地表贫瘠，灌木稀疏，不仅被成群凶猛的豺狼人占据，其东侧高地上还矗立着一座古老的法师塔。",kw={"尘埃平原","豺狼人","klaven's tower","平原","西部荒野南部","西部荒野"},ang={["faction:Alliance"]="尘埃平原是另一个法外之地，暴风城的忽视在这里显而易见，迫使旅人和当地守军在没有官方支援的情况下，独自抵御无休止的豺狼人族群。"},sec={{t="贫瘠的边境",b="尘埃平原横跨西部荒野南部，标志着这片土地从饱受蹂躏的农田向荒凉原野的过渡。与北边遭到劫掠的农场不同，这片干旱的土地早已沦为野性豺狼人的地盘，它们在此伏击旅人，并向任何冒险前往海岸或附近山丘的人发起挑战。在东部边界坐落着Klaven's Tower，这是一座古老的法师塔，如今被迪菲亚潜行者Klaven Mortwake所控制，这里无法为在荒野中徘徊的野兽之外的任何人提供庇护。"}},faq={{q="尘埃平原位于何处？",a="尘埃平原占据了西部荒野的最南端，位于废弃农场的南面，一直延伸到东部的悬崖和Klaven's Tower。",al={"尘埃平原位置","尘埃平原在哪里"}},{q="旅人在尘埃平原会遇到什么威胁？",a="该地区遍布着野蛮的豺狼人，它们在尘土飞扬的景观中建立了简陋的营地，并会暴力袭击任何靠近的旅人。",al={"尘埃平原有什么生物","尘埃平原敌人","尘埃平原怪物"}},{q="平原东侧边缘的那座塔是什么？",a="那是Klaven's Tower，一座俯瞰着尘埃平原东缘的古老法师塔。如今它在潜行者Klaven Mortwake的控制下，成为了迪菲亚兄弟会的一个据点。",al={"尘埃平原之塔","西部荒野东部的塔","什么是mortwake之塔"}},{q="人民民兵组织是否控制着尘埃平原？",a="没有。人民民兵组织为了保卫哨兵岭和北部农场免受迪菲亚兄弟会的侵扰，兵力已经捉襟见肘，尘埃平原完全处于四处游荡的豺狼人掌控之下。",al={"尘埃平原民兵","西部荒野卫兵是否在此"}}},fx={["008911b2"]={q="尘埃平原上住着谁？",a="这片干旱地带没有安居的居民。相反，凶残的豺狼人占据了平原各处粗陋的营地，袭击任何从北部农田南下的人。东边，叛徒 Klaven Mortwake 率领迪菲亚占据了 Klaven's Tower，令西部荒野南部依旧无法无天、危机四伏。",al={"这里住着谁","尘埃平原的居民","谁控制着尘埃平原"}},["54892ac9"]={q="尘埃平原有多危险？",a="这里是西部荒野最危险的地区之一。平原远离哨兵岭和人民军的保护，遍布凶暴的豺狼人和迪菲亚亡命之徒。毫无准备的旅人贸然闯入南部荒地，很容易遭到包围并被杀死。",al={"尘埃平原危险吗","尘埃平原的危险程度","尘埃平原的威胁"}}},fp="11,225,17.504.0,34.164.0,51.152.0,52.164.0,64.204.0"}
P.entries["subzone:dustbowl"] = {n="漫尘盆地",s="漫尘盆地是荒芜之地西北部一片广阔、干旱的区域，位于部落哨站卡加斯和中部的巨牙谷之间。这里终年被肆虐的沙漠狂风所席卷，是一片荒凉的野外之地，栖息着食腐动物、徘徊的野兽以及游荡的元素生物。瓦格营地也坐落于此，使这里成为了勇敢穿越荒原的旅行者们的必经之路。",h="漫尘盆地是荒芜之地西北部一片广阔、干旱的区域，位于部落哨站卡加斯和中部的巨牙谷之间。这里终年被肆虐的沙漠狂风所席卷，是一片荒凉的野外之地，栖息着食腐动物、徘徊的野兽以及游荡的元素生物。瓦格营地也坐落于此，使这里成为了勇敢...",kw={"荒芜之地","秃鹫","瓦格营地","土狼","漫尘盆地","卡加斯","岩石元素","巨牙谷"},ang={["faction:Horde"]="漫尘盆地位于卡加斯外围，是部落斥候向东挺进荒芜之地时必须穿越的第一片开阔荒野。"},sec={{t="焦灼的穿越之地",b="漫尘盆地横跨荒芜之地的西北部，以干涸的沟壑、开裂的粘土和卷起呛人砂砾的强劲狂风为特征。尽管地貌贫瘠，但顽强的沙漠植物依然存在，例如耐旱的仙人掌和零星分布的扭曲树木。这片开阔的平原对没有向导的旅人构成了持续的威胁，他们必须应对掠食的土狼、盘旋的秃鹫以及由崎岖大地诞生的活体岩石元素。在这片灌木丛中坐落着瓦格营地，为这片本应荒无人烟的广袤之地提供了一个显眼的地标。"}},faq={{q="漫尘盆地位于何处？",a="漫尘盆地覆盖了荒芜之地的西北区域，直接位于西侧的部落要塞卡加斯和地图中部区域的巨牙谷之间。",al={"漫尘盆地位置","漫尘盆地在哪里","荒芜之地漫尘盆地地图"}},{q="漫尘盆地中游荡着哪些生物？",a="该区域徘徊着凶猛的土狼和搜寻腐肉的盘旋秃鹫。旅行者们还会遇到在石质高地上游荡的危险岩石元素。",al={"漫尘盆地怪物","漫尘盆地有什么生物","漫尘盆地野兽"}},{q="在漫尘盆地能找到什么地标？",a="漫尘盆地中最著名的定居点是瓦格营地，它是连接卡加斯与中央平原之间那片干旱沙漠中一个显眼的路标。",al={"漫尘盆地的营地","漫尘盆地瓦格营地"}},{q="这里有任何植物能生存吗？",a="尽管气候干燥且严酷，漫尘盆地仍有稀疏的植被，主要是能够适应贫瘠土壤的耐旱仙人掌和偶尔可见的枯萎沙漠树木。",al={"漫尘盆地植物","漫尘盆地里的植物"}}},fp="8,379,19.578.0,30.195.0,35.165.0,41.143.0,36.165.0"}
P.entries["subzone:dustfire-valley"] = {n="尘火谷",s="尘火谷是一道干旱、多风的深谷，坐落在灼热峡谷的北缘。它是一处焦黑的入口，直接通往石坝小径的设防大门，而那道大门阻断了通往洛克莫丹的山路。",h="尘火谷是一道干旱、多风的深谷，坐落在灼热峡谷的北缘。它是一处焦黑的入口，直接通往石坝小径的设防大门，而那道大门阻断了通往洛克莫丹的山路。",kw={"尘火谷","洛克莫丹","锁闭的大门","灼热峡谷","石坝小径","国王谷"},ang={["race:Dwarf"]="对于矮人而言，这里设防的大门是卡兹莫丹的安全地带与黑铁矮人统治的险恶领地之间的一道重兵把守的后门。"},sec={{t="北部边界",b="尘火谷隐蔽在灼热峡谷的北部，到处都是令人窒息的火山灰、脆弱的岩石和贫瘠的峡谷峭壁。这里最引人注目的景观，是那道封锁了石坝小径的雄伟矮人铁门。由于这道铁门紧锁，普通的旅行者无法直接向北前往国王谷和洛克莫丹，使得这里成为了硫磺荒原中一处与世隔绝的死胡同。"}},faq={{q="尘火谷的大门通向哪里？",a="这道大门封锁着石坝小径，那是一条穿越高山，直达洛克莫丹国王谷的山间通道。",al={"尘火大门","尘火锁闭的门","石坝小径通向哪里"}},{q="你能打开通往洛克莫丹的大门吗？",a="这道大门由矮人工匠严密锁死，旨在保护洛克莫丹的土地免受来自灼热峡谷的威胁。想要通行，必须获得一把特定的钥匙。",al={"如何打开大门","打开石坝小径","尘火大门钥匙"}},{q="为什么这个区域被称为尘火谷？",a="这个名字反映了此地靠近北部山墙的峡谷中，火山灰、干尘和残留的热浪相互交织，令人窒息的环境特点。",al={"尘火谷名称","为何叫尘火"}}},fp="15,239,21.426.0,44.119.0,36.169.0,40.152.0"}
P.entries["subzone:dustwallow-bay"] = {n="尘泥海湾",s="尘泥海湾是无尽之海的一处内湾，坐落在尘泥沼泽潮湿的海岸与防御森严的塞拉摩岛之间。这里咸淡水交汇的浅滩中海洋生物繁多，到处都是危险的浅滩和隐蔽的小海湾，位于卡利姆多东部的主要航道之外。",h="尘泥海湾是无尽之海的一处内湾，坐落在尘泥沼泽潮湿的海岸与防御森严的塞拉摩岛之间。这里咸淡水交汇的浅滩中海洋生物繁多，到处都是危险的浅滩和隐蔽的小海湾，位于卡利姆多东部的主要航道之外。",kw={"尘泥海湾","尘泥沼泽","无尽之海","纳特·帕格","塞拉摩","狂潮湾"},ang={["faction:Alliance"]="对于前往卡利姆多的联盟水手和旅行者来说，尘泥海湾是进入塞拉摩岛防御港口前最后一段开阔海域。"},sec={{t="东部沼泽水域",b="尘泥海湾划定了海岸边界，在这里，尘泥沼泽那死气沉沉、浑浊的湿地与无尽之海的开阔水域交汇。海湾东侧毗邻塞拉摩岛，是船只前往吉安娜·普罗德摩尔的岛屿避难所的航道。尽管进出码头的海上交通繁忙，但周围的海岸线依然荒凉且充满危险，遍布着岩石露头、鱼人营地，以及诸如狂潮湾之类僻静的入海口。"},{t="垂钓者的天堂",b="虽然沼泽本身到处都是鳄鱼和敌对的野兽，但海湾的岛屿和入海口却吸引着那些寻求与世隔绝和丰厚渔获的人们。狂潮湾附近星罗棋布的小岛为垂钓者提供了隐蔽的休憩之所，其中最著名的莫过于传奇渔夫纳特·帕格，他经常被发现远离喧嚣的塞拉摩城，在岩石边垂钓。"}},faq={{q="尘泥海湾在哪里？",a="尘泥海湾位于卡利姆多中部的东海岸。它正好坐落在尘泥沼泽潮湿的东岸与塞拉摩岛那坚固的堡垒之间。",al={"尘泥海湾位置","尘泥海湾在哪里","尘泥水域"}},{q="在海湾能找到谁？",a="海湾外围最著名的居民是举世闻名的钓鱼大师纳特·帕格。他在塞拉摩岛西南方、狂潮湾附近的一个小岛上扎营。",al={"尘泥海湾里有谁","纳特·帕格 尘泥海湾","尘泥海湾的npc"}},{q="游过尘泥海湾安全吗？",a="虽然海湾距离安全的塞拉摩岛相对较近，但其浅滩和海岸线上经常有鱼人、鲨鱼以及沼泽边缘常见的其他具有攻击性的水生野生生物出没。",al={"尘泥海湾危险吗","尘泥海湾的怪物"}}},fp="14,284,27.483.0,19.377.0,32.180.0,28.195.0,38.196.0"}
P.entries["subzone:dustwind-cave"] = {n="尘风洞穴",s="尘风洞穴是一处位于烈风峡谷悬崖顶端的隐蔽空洞，就在剃刀岭的东北方。它是杜隆塔尔境内邪恶的火刃氏族为教徒提供训练和秘密避难的活跃场所。",h="尘风洞穴是一处位于烈风峡谷悬崖顶端的隐蔽空洞，就在剃刀岭的东北方。它是杜隆塔尔境内邪恶的火刃氏族为教徒提供训练和秘密避难的活跃场所。",kw={"火刃氏族","邪教徒","杜隆塔尔","尘风洞穴","邪血","剃刀岭","烈风峡谷"},ang={["class:Warlock"]="部落的术士们会认出尘风洞穴内正在进行的黑暗仪式，尽管火刃氏族运用他们的邪能天赋是为了反叛，而非服务于萨尔的新秩序。",["faction:Horde"]="尘风洞穴象征着一种令人尴尬且危险的内部漏洞，在离剃刀岭仅咫尺之遥的地方窝藏着恶魔崇拜者。"},sec={{t="悬崖之影",b="尘风洞穴俯瞰着烈风峡谷，是对剃刀岭最直接且危险的威胁之一。尽管许多人认为恶魔崇拜者只会聚集在深邃的地底，但火刃氏族却在这里，在部落当局的眼皮底下训练新兵。阴险的邪教徒在这里向新成员传授禁忌的黑暗魔法和恶魔学识，准备从杜隆塔尔内部破坏年轻的兽人国度。"},{t="受污染的血脉",b="擅闯此洞穴的人有遭受邪教徒危险腐化的风险。洞穴内的施法者引导着邪血折磨等不稳定的黑暗艺术，这证明了火刃氏族对萨尔竭力驱逐的恶魔遗产有着多么深重的执念。消灭这里的邪教团对于维护杜隆塔尔岌岌可危的和平至关重要。"}},faq={{q="尘风洞穴在哪里？",a="尘风洞穴位于杜隆塔尔烈风峡谷的高处悬崖边，就在剃刀岭的东北方。",al={"尘风洞穴位置","尘风洞穴在哪里","如何找到尘风洞穴"}},{q="谁占据了尘风洞穴？",a="该洞穴被火刃氏族的邪教徒和新兵占据，这是一个致力于传播邪能腐化并破坏部落稳定的阴暗恶魔邪教。",al={"尘风洞穴里是谁","尘风洞穴敌人","尘风洞穴怪物"}},{q="火刃氏族为什么要在这里活动？",a="火刃氏族将尘风洞穴用作隐蔽的训练前哨，经验丰富的邪教徒在那里指导新兵学习恶魔艺术，以避开奥格瑞玛和剃刀岭守卫的直接监视。",al={"为什么邪教徒在尘风洞穴","火刃氏族杜隆塔尔目的"}},{q="为什么部落想要清除这个洞穴？",a="恶魔崇拜者潜伏在距离剃刀岭仅几步之遥的地方，这对往来新兵的安全以及整个杜隆塔尔的防御构成了不可接受的风险。",al={"为什么清理尘风洞穴","部落威胁尘风洞穴"}}},fx={["580d7a1c"]={q="尘风洞穴是什么地方？",a="尘风洞穴是一处小型洞窟，开凿在烈风峡谷上方的高耸峭壁中，位于剃刀岭东北方。它藏在奥格瑞玛步兵的监视之外，是崇拜暗影的火刃氏族邪教徒秘密训练和藏身之所。",al={"尘风洞穴是什么","尘风洞穴背景","关于尘风洞穴"}},c011eaae={q="尘风洞穴危险吗？",a="这里相当危险，尤其对经验不足的冒险者而言。洞穴里到处都是狂热的火刃氏族邪教徒及其热切的学徒。这些狂信徒不仅使用钢刃、擅长无情伏击，还掌握着腐化人心的暗影与恶魔魔法，企图将黑暗势力扩散到整个杜隆塔尔。",al={"尘风洞穴安全吗","尘风洞穴的威胁","尘风洞穴有多危险"}}},fp="13,245,22.435.0,18.354.0,31.116.0,27.158.0,40.198.0,42.166.0"}
P.entries["subzone:dwarven-district"] = {n="Dwarven District",s="Dwarven District坐落在暴风城北角，是一个繁华的工业区，到处是轰鸣的熔炉、清脆的打铁声和浓重的烟雾。这里居住着许多矮人工匠，是这座城市的机械之心。",h="Dwarven District坐落在暴风城北角，是一个繁华的工业区，到处是轰鸣的熔炉、清脆的打铁声和浓重的烟雾。这里居住着许多矮人工匠，是这座城市的机械之心。",kw={"矿道地铁","dwarven district","猎人协会","铁炉堡","potts' plates","暴风城"},ang={["profession:Blacksmithing"]="该区提供了暴风城最完备的锻造设施，配备了大型冶炼炉、坚固的铁砧以及经验丰富的教官。",["race:Dwarf"]="对于远离卡兹莫丹的矮人们来说，这个区域提供了一种熟悉的慰藉：轰鸣的鼓风炉，以及返回铁炉堡的便捷通道。"},sec={{t="远离卡兹莫丹的家园",b="暴风城的北区是城中矮人工匠、铁匠和工程师的聚居地。该区域保留了鲜明的铁炉堡特色，以厚重的石砌建筑、广阔的冶炼设施和繁忙的工艺作坊为主。Potts' Plates等商店为来自卡兹莫丹的工匠提供了一个熟悉的避风港。这里还设有暴风城通往矿道地铁的入口，将人类首都与铁炉堡直接相连。"}},faq={{q="为什么暴风城里会有矮人聚居区？",a="这个聚居区是如何建立的，在那个时代的编年史中并无记载。如今，这里居住着矮人铁匠、矿工和工程师，他们的熔炉和作坊赋予了该区独特的风貌，而矿道地铁则将其与铁炉堡直接相连。",al={"为什么暴风城有矮人","矮人区域起源","为什么叫dwarven district"}},{q="从这里如何前往铁炉堡？",a="在Dwarven District的东侧，有一条开放的拱形隧道直接通往矿道地铁站。这一地下工程奇迹能在几分钟内将暴风城与铁炉堡连接起来。",al={"如何前往铁炉堡","地铁在哪里","矿道地铁入口"}},{q="Dwarven District可以训练哪些专业？",a="鉴于其工业属性，该区是城中采矿、锻造和工程学的首要中心。这里配备了重型熔炉、铁砧，并设有专门针对这些专业技能的训练师。",al={"dwarven district专业技能","dwarven district训练师","暴风城锻造训练师"}},{q="猎人在暴风城哪里进行训练？",a="暴风城的猎人们将总部设在了Dwarven District的猎人协会，他们与矮人神射手共享营地和贸易物资，可谓相得益彰。",al={"暴风城猎人训练师","猎人小屋","暴风城猎人协会"}}},fx={e5d74eee={q="矮人区是什么地方？",al={"矮人区是什么","暴风城矮人区","介绍一下矮人区"}},["60b8a274"]={q="矮人区是如何建立的？",a="本时代的编年史并未记载矮人区的由来。如今，这里是暴风城矮人铁匠、矿工和工程师的居所与工作场所，已成为城市社区和工业中不可或缺的一部分，并由矿道地铁与铁炉堡相连。",al={"矮人区的历史","矮人区是如何形成的","矮人区历史"}},c66f318a={q="矮人区里住着谁？",a="这里主要居住着以铁匠、矿工、工程师和枪械师为生的矮人和侏儒。你还会遇到刚乘坐矿道地铁抵达的旅客、为工匠提供服务的本地商人，以及带着伙伴动物聚集于此的城市猎人工会成员。",al={"矮人区里住着谁","矮人区居民","矮人区的住民"}},ab83050b={q="矮人区危险吗？",a="在暴风城守卫森严的城墙内，矮人区通常不会遭受外敌入侵。不过，重工业也带来自己的危险：灼热的熔炉、不稳定的工程装置，以及呛人的浓烟。Cut-Throat Alley 这样的僻静角落也容易成为无赖出没和非法交易之地，避开城卫的耳目。",al={"矮人区安全吗","矮人区的危险","矮人区的威胁"}},["04c5fe8f"]={q="为什么叫矮人区？",a="这个名称源自居住和工作在这里的矮人。这里的铁匠铺、熔炉和石造建筑，让人联想到矮人山地故乡的景象、声响与工艺，也使它成为暴风城中专属于矮人文化和重工业的一隅。",al={"为什么叫矮人区","矮人区名称","矮人区的名字"}}},fp="16,267,27.461.0,44.244.0,38.177.0,53.200.0,37.159.0"}
P.entries["subzone:eastern-strand"] = {n="东部海滩",s="东部海滩是希尔斯布莱德丘陵南部的一段海岸线，位于东南方，靠近阿拉希高地边界。这片曾经平静的海岸，如今已被敌对的刺鳍纳迦占领，她们在这里建立了一个滩头阵地。",h="东部海滩是希尔斯布莱德丘陵南部的一段海岸线，位于东南方，靠近阿拉希高地边界。这片曾经平静的海岸，如今已被敌对的刺鳍纳迦占领，她们在这里建立了一个滩头阵地。",kw={"海滩","海岸","刺鳍","东部海滩","希尔斯布莱德丘陵","纳迦"},ang={["faction:Alliance"]="驻扎在东部海滩上的纳迦对南海镇的海上安全和附近的巡逻队构成了直接且缓慢渗透的侧翼威胁。",["faction:Horde"]="任何从海岸向内陆推进的纳迦有组织扩张，都可能动摇部落在希尔斯布莱德南部的行动和补给线。"},sec={{t="敌对海岸线",b="东部海滩沿着希尔斯布莱德丘陵的东南边缘延伸，与海湾对面的西部海岸相呼应。虽然该地区主要以人类农耕定居点以及南海镇和塔伦米尔之间的领土冲突而闻名，但这些沙滩和潮间带完全被刺鳍纳迦所控制。这些蛇人从无尽之海爬出，在沙洲上蜿蜒前行，栖息在岩石露头之间，密切注视着内陆。"},{t="刺鳍领地",b="刺鳍纳迦的存在使得南海镇东南方的海岸线变得十分危险。她们的战士和施法者在海滩和附近水域游荡，使得这片海岸对旅行者来说危机四伏。"}},faq={{q="东部海滩在哪里？",a="东部海滩包含希尔斯布莱德丘陵东南角的沿海沙滩和浅滩，沿着水域向东延伸至阿拉希高地边界。",al={"东部海滩位置","东部海滩在哪里","东部海滩地图"}},{q="什么生物栖息在东部海滩？",a="这片海滩和附近水域被刺鳍纳迦部族占领，包括在潮间带出没的步兵、掠夺者和施法者。",al={"东部海滩怪物","谁住在东部海滩","东部海滩敌人"}},{q="为什么纳迦会聚集在这片海滩上？",a="刺鳍纳迦占据了东部海滩的沙滩和水域。除了占据这片沿海领土外，她们的目的在经典怀旧服的记载中尚不明确。",al={"为什么纳迦在希尔斯布莱德","刺鳍攻击计划","纳迦在这里做什么"}},{q="东部海滩和西部海岸有什么区别？",a="两条海滩都与希尔斯布莱德的南部海岸接壤。西部海岸位于西南方，靠近银松森林，是撕鳍鱼人的家园；而东部海滩位于东南方，靠近阿拉希高地，被刺鳍纳迦所占据。",al={"西部海岸与东部海滩","希尔斯布莱德的两片海滩"}}},fx={["1e981837"]={q="东部海滩是什么地方？",a="东部海滩是希尔斯布莱德丘陵东南方迎风的海岸，面朝无尽之海的寒冷海水。它与该地区另一侧的西部海岸相映成趣，但这里的特色是遍布匕牙海岸纳迦；它们在浅滩和浪边徘徊聚集。",al={"东部海滩是什么","东部海滩背景","介绍一下东部海滩"}},["05c2d3e2"]={q="东部海滩危险吗？",a="这片海岸对旅人而言危机四伏。具有攻击性的匕牙海岸纳迦，包括战士和施法者，会在海滩和水域中徘徊，并攻击接近其领地的外来者。",al={"东部海滩的危险","东部海滩安全吗","东部海滩有多危险"}},a940bc43={q="为什么叫东部海滩？",a="这个名称只是源于地理位置。“Strand”是海岸或海滩的古称，而这片海滩构成了希尔斯布莱德丘陵海岸的东半部，与南海镇以西的西部海岸遥相对应。",al={"为何称为东部海滩","东部海滩名称由来","东部海滩的名称从何而来"}}},fp="14,270,19.474.0,21.188.1,36.189.0,42.147.0,41.157.0,59.222.0"}
P.entries["subzone:eastmoon-ruins"] = {n="东月废墟",s="东月废墟是一处古老的巨魔考古遗址，位于塔纳利斯东部，坐落在毗邻大裂口西侧的高地上。这些残破的石砌建筑曾由古老的沙漠帝国建造，如今被沙槌食人魔占据，他们将这些遗迹当作沙漠营地使用。",h="东月废墟是一处古老的巨魔考古遗址，位于塔纳利斯东部，坐落在毗邻大裂口西侧的高地上。这些残破的石砌建筑曾由古老的沙漠帝国建造，如今被沙槌食人魔占据，他们将这些遗迹当作沙漠营地使用。",kw={"沙槌","东月","东月废墟","大裂口","塔纳利斯","巨魔废墟"},ang={["class:Rogue"]="破碎的石柱和散落的石墙提供了许多视野盲区，可以让你悄悄溜过或者伏击在周边巡逻的沙槌食人魔。",["race:Troll"]="这些破败的石砌建筑静默地提醒着人们，在沙漠风沙吞没南方之前，你的先祖曾在卡利姆多拥有广袤的统治疆域。"},sec={{t="沙中石",b="东月废墟从虫群出没的大裂口西侧那炙热的沙漠地面上升起，保留了古老巨魔文明摇摇欲坠的建筑。腐朽的石柱、风化的石质广场和被烈日晒白的纪念碑，暗示着这片地区被沙海吞没前的久远年代。这里并没有学者或巨魔后裔在照料这些神龛，而是被沙槌食人魔牢牢控制，他们依靠残垣断壁作为掩体，并以此作为监视附近贸易路线的据点。"}},faq={{q="是谁建造了东月废墟？",a="这些建筑属于古代巨魔。早在塔纳利斯变成干旱的荒原之前，巨魔文明曾统治着卡利姆多南部，留下了诸如东月废墟中那些饱经风霜的石雕、寺庙和广场。",al={"谁建造了东月废墟","东月起源","巨魔建造了东月"}},{q="现在是谁控制着东月废墟？",a="这些废墟被塔纳利斯的沙槌食人魔占据。这些魁梧的沙漠野蛮人占据了古老的石墙，建立营地并监视着塔纳利斯东部。",al={"谁住在东月","东月废墟的怪物","东月的废土游民"}},{q="东月废墟在哪里？",a="你可以在塔纳利斯的东部边缘找到它们，位置就在希利苏斯虫群出没的大裂口的正西侧。",al={"东月废墟位置","东月在哪里","寻找东月废墟"}},{q="东月废墟有任务吗？",a="没有专门针对东月废墟的正式任务。这里主要作为沙槌食人魔的营地，以及供冒险者探索深层沙漠时的历史地标。",al={"东月任务","东月废墟的任务","这里有任务吗"}}},fp="14,273,18.492.0,29.225.0,32.174.0,37.130.0,39.192.0"}
P.entries["subzone:eastvale-logging-camp"] = {n="东谷伐木场",s="东谷伐木场是坐落在艾尔文森林东部林区、靠近赤脊山边界的一处重要伐木定居点。该伐木场为暴风城及其周边定居点提供重要的木材，但其运作却不断受到出没于周围森林的饥饿掠食者的阻碍。",h="东谷伐木场是坐落在艾尔文森林东部林区、靠近赤脊山边界的一处重要伐木定居点。该伐木场为暴风城及其周边定居点提供重要的木材，但其运作却不断受到出没于周围森林的饥饿掠食者的阻碍。",kw={"东谷","艾尔文","marshal haggard","马匹","伐木场","木材","莱琳","原木"},ang={["faction:Alliance"]="东谷伐木场是艾尔文森林中联盟成员可以购买可靠的暴风城战马的首选地点之一。",["race:Human"]="对于暴风城的人类来说，东谷提供了持续重建和维护王国定居点所必需的木材。"},sec={{t="陷入围困的重要行动",b="来自暴风王国各地的买家不断向东谷伐木场下达木材订单，但要在严格的截止日期前完成这些订单是一项艰巨的任务。伐木场周围茂密的荒野中挤满了凶猛的狼群和四处游荡的熊，它们经常将伐木工从工作地点驱赶走，导致珍贵的木材被遗弃在树林中。在管理员莱琳的指导下，伐木场经常依赖路过的冒险者来清除这些入侵的野兽，并在交付延期导致严重后果之前取回掉落的木材。"},{t="东部边境的生活",b="尽管地理位置偏远，东谷不仅仅是一个伐木前哨站。这里有几处住宅和繁忙的马厩，旅行者可以在此购买优质的坐骑。在俯瞰工作地点的一座附近小山上，坐落着退休的Marshal Haggard的宁静庄园，他是前暴风城卫队指挥官，为了远离首都的政治斗争，他退隐到了这个乡村前哨站安享晚年。"}},faq={{q="东谷伐木场的主要目的是什么？",a="东谷是暴风王国在艾尔文森林东部的主要木材来源。这里的伐木工在严格的截止日期下长时间工作，以满足王国各地建筑商和贵族对木材的巨大需求。",al={"东谷为何在此","什么是东谷","东谷的木材作用"}},{q="为什么伐木场总是雇佣冒险者？",a="茂密的树林环绕着营地，具有攻击性的野熊和游荡的狼群不断威胁着工人们。袭击经常迫使伐木工逃离，留下砍伐好的木材，使木材订单面临严重的延期交付风险。",al={"东谷的问题","伐木工为何需要帮助","东谷的狼"}},{q="Marshal Haggard是谁？",a="Marshal Haggard是退休的前暴风城卫队指挥官。他几年前卸任，现在居住在俯瞰东谷伐木场的悬崖上的一处宁静庄园里。",al={"marshal haggard","东谷附近的老人","marshal haggard 艾尔文"}},{q="可以在东谷伐木场购买坐骑吗？",a="可以。该伐木场设有一个活跃的马匹养殖场，联盟冒险者可以在这里购买战马并接受骑术训练。",al={"东谷马匹商人","东谷马匹","在艾尔文购买坐骑"}}},fx={["85f79eeb"]={q="东谷伐木场由谁居住或管理？",a="日常伐木事务由管理员莱琳负责，她管理工人，努力让木材运输按计划进行。营地里还有许多伐木工、当地马厩工，以及像哈格德元帅这样的退休人物；他住在繁忙锯木厂稍远处的庄园里。",al={"谁管理东谷伐木场","谁领导东谷伐木场","东谷伐木场主管"}},["6b46ecbb"]={q="东谷伐木场危险吗？",a="营地本身有人守卫，但周围的树林里到处都是捕食性狼群和凶猛的熊，它们经常追踪伐木工。工人们被赶离工作地点，废弃木材散落在灌木丛中，因此粗心的旅人若走到磨坊建筑之外，便会身处险境。",al={"东谷伐木场有多危险","东谷伐木场安全吗","东谷伐木场的威胁"}},ba9b781f={q="东谷伐木场是什么地方？",a="东谷伐木场是由众多锯木厂、马厩和工人住所组成的广阔区域，隐于艾尔文森林东部。它是暴风王国重要的经济支柱，不断加工木材，以满足王国各地严格的订单要求和建设期限。",al={"东谷是什么","东谷伐木场","关于东谷伐木场"}},c2c2b618={q="东谷伐木场发生过什么？",a="伐木场最初是为采伐艾尔文茂密的林木而建。随着时间推移，包括前暴风城卫队指挥官哈加德元帅在内的退役老兵来到此处，过起清静的生活。伐木场一直在稳定运转，但当地野生动物日益失控，威胁着木材运输和工人的安全，令这里的处境愈发艰难。",al={"东谷历史","东谷伐木场的历史","东谷的过往"}}},fp="21,317,29.561.0,28.409.0,50.232.0,50.259.0,23.203.0,44.137.0"}
P.entries["subzone:eastwall-gate"] = {n="东墙大门",s="东墙大门是位于陨落之城斯坦索姆外墙上的一处设防侧门。它坐落在东瘟疫之地的北部边缘，提供了一条进入斯坦索姆废墟内部的次要直达路径，从而避开了城市正门区域的混乱。",h="东墙大门是位于陨落之城斯坦索姆外墙上的一处设防侧门。它坐落在东瘟疫之地的北部边缘，提供了一条进入斯坦索姆废墟内部的次要直达路径，从而避开了城市正门区域的混乱。",kw={"阿隆索斯礼拜堂","东瘟疫之地","东墙大门","长老广场","key to the city","闸门","侧入口","斯坦索姆"},ang={["class:Paladin"]="穿过东墙大门后，十字军会立即到达阿隆索斯礼拜堂附近，这是一处如今被天灾军团的灰烬与恐怖所包围的神圣避难所。",["class:Rogue"]="东墙大门的坚固锁具要求具备极高水准的开锁技能，这使得一名大师级潜行者在没有Key to the City的情况下绕过正门入口时变得至关重要。"},sec={{t="通往废墟的后门",b="尽管斯坦索姆的正大门直通国王广场，但东墙大门则穿过了城市的东部防御工事。这扇大门被牢牢封死以阻挡入侵者，通过它可以直接进入长老广场，靠近阿隆索斯礼拜堂的台阶。对于那些深入天灾军团据点腹地的探险者来说，避开前线的路障，意味着是在对城市深处发动迅捷突袭，还是在亡灵前线进行绞肉机式的强攻，这二者之间有着天壤之别。"},{t="穿过铁栅栏",b="想要通过东墙大门并非易事。它被厚重的铁制品紧紧封死，需要使用从斯坦索姆内部回收的Key to the City，或者由一名技术极其精湛、能够开启大师级锁具的潜行者来开锁。一旦越过门槛，安装在内墙上的沉重机械杠杆允许旅行者从内部升起闸门，为盟友打开一条可靠的通行路径。"}},faq={{q="东墙大门通往哪里？",a="这扇大门通往斯坦索姆废墟内的长老广场。它毗邻历史悠久的阿隆索斯礼拜堂。",al={"东墙大门通往哪里","东墙大门目的地","东墙大门后面是什么"}},{q="如何开启这扇大门？",a="东墙大门处于牢固锁闭状态。它可以使用在斯坦索姆内找到的Key to the City来开启，或者由精通开锁的专家级潜行者撬开。一旦进入内部，可以通过一个内部杠杆手动升起大门。",al={"如何开启东墙大门","解锁东墙大门","东墙大门钥匙"}},{q="为什么冒险者会选择这个入口而不是正门？",a="通过东墙大门进入可以让突袭小队避开受灾严重的正面街道，直接在长老广场附近开始进攻，从而更快地到达城市的特定区域。",al={"为什么要用东墙大门","侧门的好处","为什么斯坦索姆侧门"}},{q="你能从内部打开大门吗？",a="可以。位于大门斯坦索姆内侧的一个杠杆允许身处内部的任何人升起大门，让其他人通过，而无需使用钥匙。",al={"东墙大门内部杠杆","从内部打开东墙大门"}}},fp="13,286,21.492.0,24.432.0,34.133.0,27.219.0,59.212.0,38.143.0"}
P.entries["subzone:eastwall-tower"] = {n="东墙哨塔",s="东墙哨塔是一座位于东瘟疫之地东侧道路旁的洛丹伦废弃侦查塔。它在第三次战争中天灾军团横扫王国时遭到洗劫，其残骸俯瞰着被天灾军团肆虐的荒野。",h="东墙哨塔是一座位于东瘟疫之地东侧道路旁的洛丹伦废弃侦查塔。它在第三次战争中天灾军团横扫王国时遭到洗劫，其残骸俯瞰着被天灾军团肆虐的荒野。",kw={"东瘟疫之地","东墙哨塔","洛丹伦","瘟疫之地塔楼","侦查塔"},ang={["faction:Alliance"]="对于联盟来说，收复东墙哨塔是为了纪念洛丹伦阵亡的士兵，并确保通往圣光之愿礼拜堂的路径不受天灾军团的侵扰。",["faction:Horde"]="这座废弃的侦查塔俯瞰着穿越北部敌对土地的道路。"},sec={{t="边境上的废墟岗哨",b="东墙哨塔最初是作为洛丹伦王国的边境哨兵塔而建，曾守护着前往王国远方的旅行者。当第三次战争中天灾军团入侵时，这座前哨站与周围的定居点一同被摧毁，只留下了破碎的石拱门和烧焦的木材。如今，随着巫妖王的军队依然盘踞在该地区，这座塔的高地势使其成为了不可或缺的前沿阵地。它破败的城墙俯瞰着穿越这片被天灾军团肆虐的乡村的道路。"}},faq={{q="东墙哨塔在陷落前是什么？",a="东墙哨塔最初是由洛丹伦王国建造的一座防御性侦查塔。它是区域边境监视网的一部分，在第三次战争导致洛丹伦陷落之前，负责保卫贸易路线和边远农场。",al={"东墙哨塔历史","谁建造了东墙哨塔","这里曾是什么地方"}},{q="是谁摧毁了这座塔？",a="这座塔是在阿尔萨斯·米奈希尔王子的征服战争以及随后的亡灵对洛丹伦的蹂躏中被天灾军团摧毁的。亡灵怪物粉碎了它的防御，使守军阵亡，建筑也沦为废墟。",al={"东墙哨塔是如何被毁的","东墙哨塔发生了什么"}},{q="为什么这座塔具有战略重要性？",a="即使已成废墟，这座塔依然占据着瘟疫之地东部道路沿线的高地，俯瞰着被天灾军团肆虐的乡村。",al={"东墙哨塔的重要性","东墙哨塔的位置"}},{q="在这里休息安全吗？",a="这座废弃的塔楼矗立在天灾军团肆虐的乡村中，无法提供安全的避难所。",al={"我可以在这里休息吗","友方卫兵"}}},fp="14,232,28.519.0,39.245.0,24.226.0,41.138.0,29.84.0"}
P.entries["subzone:echo-isles"] = {n="回音群岛",s="回音群岛是一片位于杜隆塔尔东南海岸外的热带岛屿群。暗矛巨魔在逃离他们祖先的岛屿后，最初在此定居。但目前该群岛已被叛变的巫医扎拉赞占领，他利用黑暗魔法和被奴役的爪牙将他的族人驱逐出了家园。",h="回音群岛是一片位于杜隆塔尔东南海岸外的热带岛屿群。暗矛巨魔在逃离他们祖先的岛屿后，最初在此定居。但目前该群岛已被叛变的巫医扎拉赞占领，他利用黑暗魔法和被奴役的爪牙将他的族人驱逐出了家园。",kw={"暗矛","杜隆塔尔","回音群岛","森金村","巨魔","沃金","巫毒","扎拉赞"},ang={["faction:Horde"]="确保回音群岛的安全对于稳固杜隆塔尔南部海岸、保护森金村，以及为了防御海军威胁和流氓秘术师而巩固年轻部落的边界至关重要。",["race:Troll"]="回音群岛既代表了暗矛巨魔在卡利姆多的许诺之地，也承载着扎拉赞背叛带来的痛苦刺痛。收复这些岛屿关乎部族的生存与个人的荣誉。"},sec={{t="支离破碎的避难所",b="在追随萨尔横跨无尽之海后，暗矛部族将回音群岛视为他们的新家。但他们的平静不断被打破：先是戴林·普罗德摩尔海军上将在库尔提拉斯入侵杜隆塔尔期间带来的海军力量，随后是来自内部的威胁。在巨魔们击退普罗德摩尔的舰队后不久，他们当中的一名巫医扎拉赞便利用黑暗巫术奴役了族人的心智。沃金酋长和自由的暗矛巨魔被迫再次放弃了这些岛屿，在狭窄海峡对岸的森金村寻求暂时的避难所。"},{t="扎拉赞的掌控",b="如今，这片热带群岛上充斥着极具攻击性的掠食者、受腐蚀的野生动物以及扎拉赞的奴仆。这名叛变的巫医在岛屿各处放置了邪恶的妖术、巫毒法器和祭坛，用以通过意志控制野兽和被俘的巨魔。沃金的斥候和战士们在暗矛海滩建立营地，不断向岛屿发动突袭，决心收回他们逝去同胞的遗骸，并击倒这个窃取了他们家园的疯狂秘术师。"}},faq={{q="为什么暗矛巨魔现在不住在那里？",a="巫医扎拉赞背叛了部族，利用黑暗魔法剥夺了同胞的自由意志，将他们变成了唯命是从的仆从。沃金酋长下令撤离到杜隆塔尔的大陆海岸，建立了森金村作为前哨基地，同时部族正在为收复家园而战斗。",al={"为什么废弃","巨魔为什么离开","巨魔家园"}},{q="扎拉赞是谁？",a="扎拉赞是一位背叛了部族的暗矛巫医。他利用强大的巫毒和黑暗魔法对岛屿施加了妖术，腐蚀了当地的野生动物，并将同胞巨魔奴役成了无脑的爪牙。",al={"谁是扎拉赞","回音群岛首领","巫医扎拉赞"}},{q="岛上有什么威胁？",a="群岛上到处都是野生的迅猛龙、老虎和受腐蚀的野兽，还有扎拉赞设置的巫毒祭坛，以及他通过精神控制奴役的巨魔爪牙，包括受过妖术的巨魔和巫毒巨魔。",al={"回音群岛怪物","岛上有什么","回音群岛危险"}},{q="暗矛部族最初是如何来到这些岛屿的？",a="在萨尔和部落将暗矛部族从沉没的岛屿和无尽之海的娜迦手中救出后，巨魔们前往了卡利姆多，并获准在回音群岛与他们的兽人盟友一同定居。",al={"巨魔如何来到这里","暗矛起源","回音群岛历史"}}},fx={["7222f2f6"]={q="回音群岛是什么地方？",a="回音群岛是一片热带群岛，位于杜隆塔尔东南海岸附近。暗矛部族最初将其据为己有，作为他们在卡利姆多的新家园；如今，这些岛屿争夺激烈，遍布野兽、被施咒的巨魔和黑暗魔法。",al={"回音群岛是什么地方","回音群岛","回音群岛在哪里"}},["2c6446a5"]={q="回音群岛发生过什么？",a="暗矛部族与萨尔的部落一起逃离沉没的故乡后，定居在回音群岛。不久，戴林·普罗德摩尔上将的舰队发动袭击，迫使他们撤离。普罗德摩尔最终战败，巨魔们也重返群岛，但巫医扎拉赞背叛了他们，施展黑暗巫术奴役同族，将沃金的族人赶到了杜隆塔尔海岸。",al={"回音群岛的历史","回音群岛的背景故事","回音群岛发生了什么"}}},fp="10,320,21.590.0,15.488.0,51.308.0,16.224.0,32.185.0,63.214.0"}
P.entries["subzone:echo-ridge-mine"] = {n="回音山矿洞",s="回音山矿洞是一处开凿在北郡山谷西北峭壁上的小型矿坑。这里蕴藏着丰富的石料和矿石，但最近落入了极具破坏性的狗头人手中，导致北郡当地的采掘作业被迫停工。",h="回音山矿洞是一处开凿在北郡山谷西北峭壁上的小型矿坑。这里蕴藏着丰富的石料和矿石，但最近落入了极具破坏性的狗头人手中，导致北郡当地的采掘作业被迫停工。",kw={"回音山","回音山矿洞","狗头人","治安官玛克布莱德","矿洞","北郡","北郡山谷"},ang={["profession:Mining"]="回音山矿洞的矿井中蕴藏着丰富的早期矿床，不过任何想要寻找矿石的勘探者都必须先杀出一条血路，穿过成群结队的、头顶蜡烛的狗头人。",["race:Human"]="对于响应暴风城征召的新兵来说，肃清回音山矿洞是保卫北郡修道院的一次至关重要的烈火试炼。"},sec={{t="害虫的立足点",b="回音山矿洞隐藏在北郡修道院上方的群山之中，原本应当为该山谷提供急需的石料和金属。然而，趁虚而入的狗头人成群结队地涌入隧道，赶走了当地的工人。治安官玛克布莱德认为，这次入侵对北郡的安全和新兵招募工作构成了不可接受的威胁，因此他直接派遣新兵进入隧道，以削减它们的数量并收复此地。"},{t="北郡地下的威胁",b="对回音山矿洞的占领，是狗头人不断向艾尔文森林扩张的更广泛趋势的一部分。如果不加遏制，这些盘踞在西北山脊的地下害虫将会威胁到北郡宁静的训练场，并切断输送往修道院的关键资源。"}},faq={{q="为什么狗头人会出现在回音山矿洞？",a="狗头人天生就是挖掘者，它们被黑暗、矿产丰富的隧道所吸引。由于察觉到防御薄弱，它们占领了回音山矿洞，试图在其中挖掘财宝并将这片领地据为己有。",al={"为什么这里有狗头人","回音山狗头人","是谁占领了矿洞"}},{q="是谁试图收复回音山矿洞？",a="北郡修道院的治安官玛克布莱德负责监督清理矿洞的工作。他招募刚到达的冒险者去侦察隧道，并在这些害虫进一步向山谷蔓延之前将其清除。",al={"谁想要回音山矿洞","回音山任务","玛克布莱德与回音山"}},{q="回音山矿洞位于何处？",a="矿洞入口位于北郡山谷的西北角，直接开凿在修道院葡萄园以北的岩石山坡上。",al={"回音山位置","回音山在哪里","寻找回音山矿洞"}}},fx={["7d0021d3"]={q="回音山矿洞是什么地方？",a="回音山矿洞是一处采矿洞穴，藏在北郡山谷西北部的山脊之中。矿洞原本是为山谷和修道院供应石料与矿石而建，最近却被四处搜刮的狗头人占据，陷入混乱。",al={"回音山是什么","回音山矿洞信息","介绍回音山矿洞"}},d8e2171b={q="回音山矿洞发生过什么？",a="当地的人类矿工一直在矿洞里工作，直到一群狗头人涌入矿道。入侵者赶走工人并占据隧道，迫使北郡当局撤回矿工，并寻求军事援助来清剿这些入侵者。",al={"回音山的历史","这里发生了什么","矿洞为什么关闭"}},["9fd09044"]={q="回音山矿洞为什么被遗弃？",a="狗头人压制矿工后，人类的采矿作业便戛然而止。由于没有足够的卫兵立即保障地下作业的安全，修道院暂停了常规采矿工作，同时依靠新抵达的招募人员驱逐这些害兽。",al={"回音山为什么被遗弃","回音山是否已成废墟","矿洞为什么关闭"}},df055836={q="回音山矿洞危险吗？",a="矿道里挤满了正在挖掘资源、守护烛光照亮的地盘的防御性狗头人。单只害兽相对弱小，但粗心的旅人很快就可能在蜿蜒狭窄的矿道中被逼入绝境。",al={"回音山矿洞危险吗","回音山的危险","回音山有多危险"}}},fp="15,235,21.427.0,29.298.0,35.177.0,41.203.0,33.146.0"}
P.entries["subzone:elder-rise"] = {n="长者高地",s="长者高地位于雷霆崖中央高地正东方，通过连接高地和中层的长条吊桥即可抵达。它是牛头人主城的精神中心，驻扎着塞纳里奥议会、牛头人德鲁伊与牧师，以及管理机构长老议会。",h="长者高地位于雷霆崖中央高地正东方，通过连接高地和中层的长条吊桥即可抵达。它是牛头人主城的精神中心，驻扎着塞纳里奥议会、牛头人德鲁伊与牧师，以及管理机构长老议会。",kw={"塞纳里奥议会","长者高地","长老大厅","哈缪尔·符文图腾","玛加萨·野性图腾","莫高雷","雷霆崖"},ang={["class:Druid"]="长者高地是部落德鲁伊最重要的家园，是大德鲁伊哈缪尔·符文图腾的圣所，也是塞纳里奥议会在卡利姆多的区域据点。",["race:Tauren"]="高地上驻扎着长老议会与精神向导，他们指引着各部落在和平、传统以及部落所面临的复杂现实中前行。"},sec={{t="信仰与议会圣所",b="长者高地通过摇晃的绳桥与主台地相连，是一个致力于静思、神圣智慧与市政管理的场所。牛头人德鲁伊与牧师们在此聚会，向学徒们传授自然的法则与精神信仰。在这座高地的顶端，住着大德鲁伊哈缪尔·符文图腾，这位受人尊敬的领袖将德鲁伊教义带回了牛头人族群，并与塞纳里奥议会建立了紧密的联系。在这些荒野圣所旁矗立着长老大厅，部落首领们在此集会，商讨这个新兴首都所面临的各种事务。"},{t="不稳定的存在",b="尽管这里是一片宁静的圣所，但政治紧张局势依然笼罩在高地上。秘密且傲慢的野性图腾氏族的年长女族长玛加萨·野性图腾，将她的住所设在两座桥之间的小屋里。虽然凯恩·血蹄向所有牛头人氏族展现了善意并给予了正式的议会席位，但她那警惕的目光时刻提醒着人们，并非每个氏族都认同血蹄的和平理念，或是对部落有着无条件的忠诚。"}},faq={{q="长者高地的用途是什么？",a="长者高地是雷霆崖精神学习与市政商议的中心。这里驻扎着塞纳里奥议会的德鲁伊、牛头人牧师、管理机构长老议会以及各部落首领。",al={"长者高地的用途","长者高地有什么","长者高地的建筑"}},{q="谁领导着长者高地上的德鲁伊？",a="大德鲁伊哈缪尔·符文图腾居住于此。作为凯恩·血蹄的挚友与顾问，哈缪尔是塞纳里奥议会中级别最高的牛头人，负责训练那些命中注定要踏上自然之道的人。",al={"雷霆崖大德鲁伊","牛头人德鲁伊领袖","哈缪尔的位置"}},{q="为什么玛加萨·野性图腾住在这里？",a="玛加萨·野性图腾住在桥之间的一个帐篷里。作为野性图腾氏族的年长女族长兼首领，她出席长老议会以代表她在雷霆崖的族人，尽管她的部族与凯恩的盟友之间存在着相互不信任。",al={"玛加萨在哪里","玛加萨·野性图腾的位置","长者高地上的野性图腾"}},{q="如何前往长者高地？",a="长者高地位于城市中央高地的正东方。可以通过连接High Rise和下层台地的大型木制绳桥抵达。",al={"如何前往长者高地","长者高地的桥梁","长者高地指引"}}},fx={f529ee1a={q="长者高地是什么地方？",a="长者高地是雷霆崖东侧的台地，由宽阔的绳桥与中央高地相连。这里是牛头人首都的精神与冥想中心，设有长者议会，也是塞纳里奥议会在当地的驻地。牧师、德鲁伊和睿智的长者聚集在这片风吹拂过的高地上冥想、训练神圣技艺的修习者，并讨论自然与部族事务。",al={"长者高地","长者高地是什么地方","长者高地介绍"}},bfedf1b8={q="谁住在长者高地？",a="长者高地是城中精神导师的居所，包括牛头人德鲁伊和牧师。大德鲁伊哈缪尔·符文图腾领导塞纳里奥议会在此的事务，训练学徒追求平衡与和谐。统治议会长者议会也在这片台地上召开会议，而野性图腾部族的族长玛加萨·野性图腾则居住在桥梁之间。",al={"谁在长者高地","长者高地的居民","谁住在长者高地"}},ea2405f4={q="长者高地危险吗？",a="长者高地十分宁静，坐落在莫高雷平原上方的高处，受到妥善保护，为部落成员和有礼的旅人提供庇护。你可能遇到的唯一真正危险，是不慎从台地边缘或在风中摇晃的高空绳桥上失足。",al={"长者高地安全吗","长者高地的危险","长者高地的敌人"}},["06c00c52"]={q="为什么叫长者高地？",a="这片高地因牛头人长者议会而得名。长者们在这里的长者大厅集会，为雷霆崖提供集体智慧和精神指引。这里的悬崖和帐篷专供这些受人尊敬的社区领袖与导师使用。",al={"长者高地为何得名","长者高地名称的由来","长者高地名称"}}},fp="10,292,30.550.0,21.480.0,28.204.0,35.201.0,37.258.0,28.163.0"}
P.entries["subzone:eldreth-row"] = {n="Eldreth Row",s="Eldreth Row 是位于菲拉斯厄运之槌西部入口处，由高耸的废弃外殿组成。这里曾是古代埃雷萨拉斯宏伟的门槛，如今却被杂草丛生所掩盖，并由戈多克食人魔严密巡逻。",h="Eldreth Row 是位于菲拉斯厄运之槌西部入口处，由高耸的废弃外殿组成。这里曾是古代埃雷萨拉斯宏伟的门槛，如今却被杂草丛生所掩盖，并由戈多克食人魔严密巡逻。",kw={"破碎的大厅","厄运之槌","dire pool","埃雷萨拉斯","eldreth row","菲拉斯","戈多克","warpwood quarter"},ang={["race:NightElf"]="看到古代埃雷萨拉斯宏伟的石雕被野蛮的食人魔亵渎，令人苦涩地想起了高等精灵的陨落和大分裂。"},sec={{t="埃雷萨拉斯的门槛",b="作为古代埃雷萨拉斯的最外围防线，Eldreth Row 是一条由高拱门组成的精灵建筑大道，位于更深处的区域和破碎的大厅之外。几个世纪的荒废使其石雕开裂，让菲拉斯蔓延的植物重新占据了它的柱廊。如今，高等精灵往昔的纯净壮丽已被戈多克食人魔粗鲁的统治所取代，他们将这些大厅作为外围的集结地，守护着通往东侧Warpwood Quarter和西侧Dire Pool的道路。"}},faq={{q="Eldreth Row 是什么地方？",a="Eldreth Row 是菲拉斯厄运之槌的外部入口大厅和外围区域，位于破碎的大厅和内部副本入口之前。",al={"eldreth row","这是什么地方","厄运之槌入口"}},{q="现在是谁控制着 Eldreth Row？",a="该区域被戈多克食人魔氏族占据并巡逻，他们加固了厄运之槌的废墟，并在其破碎的大道上徘徊。",al={"谁住在这里","谁控制了 eldreth row","eldreth row 的怪物"}},{q="Eldreth Row 通往哪里？",a="这条大道通向内部的破碎的大厅和厄运之槌的主要建筑群，其东侧边缘有通往Warpwood Quarter的入口，西侧则是Dire Pool。",al={"这个大厅通往哪里","eldreth row 出口","厄运之槌路径"}}},fp="11,236,29.554.0,20.148.0,35.133.0,28.191.0"}
P.entries["subzone:emerald-sanctuary"] = {n="翡翠圣地",s="翡翠圣地是塞纳里奥议会位于费伍德森林南入口的一处哨站。在这里，暗夜精灵和牛头人德鲁伊联合起来，研究蔓延的恶魔腐蚀，并尝试修复这片被腐蚀的林地的艰巨任务。",h="翡翠圣地是塞纳里奥议会位于费伍德森林南入口的一处哨站。在这里，暗夜精灵和牛头人德鲁伊联合起来，研究蔓延的恶魔腐蚀，并尝试修复这片被腐蚀的林地的艰巨任务。",kw={"塞纳里奥议会","腐蚀","德鲁伊","翡翠圣地","费伍德森林","加德纳尔"},ang={["class:Druid"]="对于达纳苏斯和雷霆崖的德鲁伊来说，翡翠圣地是一个关键的提醒，让他们铭记共同的使命，证明治愈大地的职责超越了世俗的阵营忠诚。"},sec={{t="枯萎中的灯塔",b="翡翠圣地坐落在费伍德森林的南缘，靠近灰谷边界，是塞纳里奥议会在这个荒芜之地进行行动的主要基地。与卡利姆多各地激烈的阵营冲突不同，这座圣地提供了一个中立的据点，德鲁伊们在此超越政治纷争，全心专注于生态恢复。研究人员从这里开始追踪被腐蚀的植物群，并引导对加德纳尔的调查，寻求任何可行的方法来净化受污染的土壤。"}},faq={{q="翡翠圣地的目的是什么？",a="塞纳里奥议会建立该营地是为了研究和对抗扼杀费伍德森林的恶魔腐蚀。驻扎在这里的德鲁伊调查受腐蚀的植物、野兽和水源，同时协调应对深处林中根深蒂固的暗影议会邪教徒的行动。",al={"为什么翡翠圣地会在这里","德鲁伊在这里做什么","翡翠圣地的目的"}},{q="联盟和部落的玩家都能访问翡翠圣地吗？",a="是的。塞纳里奥议会作为一个独立的、中立的组织运作。只要愿意协助净化费伍德森林的深度腐蚀，联盟和部落的冒险者都会受到欢迎。",al={"翡翠圣地是中立的吗","部落可以进入翡翠圣地吗","联盟玩家在圣地友好吗"}},{q="这里的德鲁伊最担心什么威胁？",a="虽然整个森林都被第三次战争后残留的恶魔能量所扭曲，但德鲁伊们尤其对加德纳尔感到警惕，那是一个位于北部的庞大洞穴群，暗影议会正活跃于此，滋生并扩散着腐蚀。",al={"费伍德森林最大的威胁","德鲁伊在对抗什么","加德纳尔的威胁"}}},fp="17,247,22.507.0,45.271.0,56.201.0,46.239.0"}
P.entries["subzone:engineering-labs"] = {n="Engineering Labs",s="Engineering Labs是位于诺莫瑞根深处的一座多层研究与制造设施。该设施连接着Workshop Entrance和Launch Bay，这片曾经繁忙的侏儒创新中心在城市遭遇放射性大灾变时被攻陷，如今到处都是疯狂的麻风侏儒和失控的机械装置。",h="Engineering Labs是位于诺莫瑞根深处的一座多层研究与制造设施。该设施连接着Workshop Entrance和Launch...",kw={"engineering labs","诺莫瑞根","launch bay","麻风侏儒","穿孔机","tinkers' court","workshop entrance"},ang={["profession:Engineering"]="Engineering Labs代表了侏儒自动化技术的巅峰，在废墟中依然保留着功能完好的自动穿孔机终端和废弃的设计图。",["race:Gnome"]="对于流亡的侏儒来说，这些实验室是一个悲惨的景象：曾经是他们种族科技成就的核心，如今却沦为被受腐蚀的同胞所占据的辐射废墟。"},sec={{t="没落的创新中心",b="Engineering Labs围绕一个核心机械结构而建，横跨两层主要区域，并由一座中央货运电梯相连。在诺莫瑞根的全盛时期，修补匠们在此开发设计图并改良发条装置。如今，辐射泄漏使得残留的研究人员发了疯，将他们变成了精神错乱的麻风侏儒，他们与失控的构造体一起，毫无目的地守护着那些故障的机器。"},{t="关键枢纽",b="除了作为实验室的历史角色外，该区域还是穿行于这座被毁城市下层区域的重要中转枢纽。通道蜿蜒通向Launch Bay、Tinkers' Court以及Workshop Entrance的后门。下层还安置着矩阵穿孔机3005-D终端，这是破译侏儒工程师携带的编码穿孔卡片所需的关键处理单元。"}},faq={{q="Engineering Labs最初的用途是什么？",a="在城市陷落前，Engineering Labs专门用于研究、组装和测试复杂的侏儒装置与自动化设备。侏儒工程师和技术员利用这个巨大的双层空间来绘制新技术蓝图。",al={"engineering labs的用途","这里制造什么","engineering labs背景故事"}},{q="现在Engineering Labs里游荡着哪些威胁？",a="受到辐射的麻风侏儒和失控的机械自动装置在实验室的两层区域内游荡。这些残留的居民在城市陷落时释放的辐射气体影响下彻底发了疯，会攻击任何见到的未受辐射的入侵者。",al={"里面有什么","engineering labs的敌人","这里的怪物"}},{q="什么是矩阵穿孔机3005-D机器？",a="这些自动化侏儒数据终端位于Engineering Labs的下层。它们允许工程师和冒险者对编码数据卡进行打孔，以提升他们的安全权限，并破译储存在城市内的技术档案。",al={"穿孔机d","矩阵穿孔机3005-d","黄色卡片机器"}},{q="这个区域如何连接到诺莫瑞根的其他部分？",a="上层直接连接到Workshop Entrance的后门，以及通往Launch Bay的通道。下层则通往连接Launch Bay和Tinkers' Court的主走廊。",al={"这里通往哪里","engineering labs出口","前往engineering labs的路线"}}},fx={["36276ef1"]={q="Engineering Labs 是什么地方？",a="Engineering Labs 是诺莫瑞根深处一片多层研究区域。这片区域由上层回路和下层组成，两者通过一座开放式升降平台相连。这里曾进行高阶科技实验，设有自动化系统和诊断设备，例如矩阵式打孔机 3005-D 型。",al={"engineering labs 是什么地方","诺莫瑞根的 engineering labs","engineering labs 介绍"}},a7c381fe={q="Engineering Labs 发生过什么？",a="穴居人攻破诺莫瑞根时，大工匠梅卡托克下令释放有毒辐射，以消灭入侵者。然而，辐射并未拯救这座城市，反而充斥了包括 Engineering Labs 在内的多个区域。这里工作的侏儒要么丧命，要么严重变异成受辐射感染的麻风侏儒，他们的机械装置也失控了。",al={"engineering labs 的历史","这里发生了什么","engineering labs 的陷落"}},["526db480"]={q="如今谁控制着 Engineering Labs？",a="这里已经没有神志清醒的侏儒负责管理。实验室里到处都是疯狂的麻风侏儒和失控的机械构造体，它们在上下两层不停巡逻，包括上层南侧那个庞大的群体碾压者 9-60。",al={"engineering labs 里住着谁","engineering labs 的居民","谁管理 engineering labs"}},["2ced7fd6"]={q="Engineering Labs 为什么毁坏并被遗弃？",a="诺莫瑞根陷落的悲剧中，放射性物质被释放，灌满大厅以对抗穴居人的入侵，实验室因此被遗弃。灾难性的辐射使整座设施不再适合未受污染的侏儒居住，留下的宝贵设备、蓝图和终端任由疯狂的幸存者与失控的自动机械摆布。",al={"engineering labs 为什么毁坏","engineering labs 为什么被遗弃","实验室的陷落"}},["620f0877"]={q="探索 Engineering Labs 危险吗？",a="实验室极其危险。除了诺莫瑞根各处残留的辐射污染，你还必须应对凶猛的麻风侏儒、故障机械，以及巡逻上层回路的敌对构造体，例如群体碾压者 9-60。",al={"engineering labs 危险吗","engineering labs 的危险因素","engineering labs 里的危险"}}},fp="16,323,29.404.0,16.387.0,51.240.0,43.246.0,48.255.0,53.198.0"}
P.entries["subzone:ethel-rethor"] = {n="艾瑟雷索",s="艾瑟雷索是一处位于凄凉之地崎岖西北海岸的古老暗夜精灵废墟。虽然一座孤零零的、被封印的塔楼依然耸立在波涛之上，但大部分沉没的定居点现在已经没入海中，并被充满敌意的纳迦所占据。",h="艾瑟雷索是一处位于凄凉之地崎岖西北海岸的古老暗夜精灵废墟。虽然一座孤零零的、被封印的塔楼依然耸立在波涛之上，但大部分沉没的定居点现在已经没入海中，并被充满敌意的纳迦所占据。",kw={"银色黎明","阿佐尔·奥达蒙特","凄凉之地","凄凉之地海岸","艾瑟雷索","卡多雷废墟","纳迦","沉没的废墟"},ang={["faction:Alliance"]="在凄凉之地那充满敌意的荒原中穿行的联盟旅行者，可以在废墟附近找到一位难得的、中立友善的面孔：银色黎明观察员阿佐尔·奥达蒙特。",["race:NightElf"]="对于暗夜精灵来说，艾瑟雷索是他们失落帝国的一座阴郁纪念碑，提醒着他们那场灾难性的大分裂，以及如今在沉没厅堂中潜行的突变同胞。"},sec={{t="一处沉没的遗迹",b="坐落在卡利姆多西部的荒凉海岸上，艾瑟雷索作为在大分裂前就已繁荣的古代暗夜精灵文明的凄凉遗迹，时刻提醒着人们曾经的历史。大部分宏伟的建筑都已崩塌沉入深海，只留下破碎的地基和一座孤零零、饱经风霜的塔楼伸出水面。一座小桥延伸向塔楼被封印的入口，但这座建筑紧闭着，抵御着风雨与入侵者。淹没的房间和周边的浅滩已成为沿海纳迦的据点，使得这片水域对于任何徘徊在附近的人来说都危机四伏。"},{t="海岸守望者",b="尽管位置偏远且被蛇形生物侵扰，艾瑟雷索依然吸引着那些对卡利姆多被遗忘的历史和持续存在的威胁感兴趣的旅行者。银色黎明的一名特工，阿佐尔·奥达蒙特，在废墟附近保持着警惕，监视着纳迦的威胁，并为那些愿意潜入沉没通道的勇敢冒险者提供帮助。在离岸的水域危险与内陆的荒原之间，这座废墟成为了一个孤独的海岸枢纽。"}},faq={{q="什么是艾瑟雷索？",a="艾瑟雷索是一处位于凄凉之地西北部的暗夜精灵沿海定居点遗迹。其原有的大部分建筑现已沉入海面之下，只留下一座孤立的近海塔楼和淹没在水中的石质建筑。",al={"艾瑟雷索背景知识","凄凉之地的这个地方是什么","艾瑟雷索废墟"}},{q="现在是谁控制着艾瑟雷索？",a="沉没的废墟和邻近的礁石被纳迦所占据。正如沿海的许多古代卡多雷遗迹一样，这些蛇形生物已经占领了这些淹没的厅堂，并积极巡逻着周边的浅滩。",al={"谁居住在艾瑟雷索","艾瑟雷索的怪物","艾瑟雷索的纳迦"}},{q="你能进入那座塔楼吗？",a="从海中升起的塔楼有一座小桥通向入口，但门口被牢牢封死。旅行者只能探索其外部，并潜入其下方沉没的废墟中。",al={"打开艾瑟雷索塔楼","艾瑟雷索的门","进入艾瑟雷索"}},{q="银色黎明为什么会在这里？",a="银色黎明的一名代表，阿佐尔·奥达蒙特，驻扎在废墟附近。虽然银色黎明的主要精力集中在东部的天灾军团身上，但他们遍布卡利姆多的特工会监测异常的魔法干扰、古代遗迹以及像纳迦这样新兴的威胁。",al={"凄凉之地的银色黎明","阿佐尔·奥达蒙特 艾瑟雷索","凄凉之地的银色黎明npc"}}},fp="12,258,15.616.0,21.466.0,21.210.0,30.219.0,28.204.0,28.258.0"}
P.entries["subzone:everlook"] = {n="永望镇",s="永望镇是热砂港在冬泉谷中部建立的一处风雪笼罩的贸易哨站。它坐落于这片雪谷道路的十字路口，是商人们、勘探者和研究者们抵御高海拔严寒的中立避风港。",h="永望镇是热砂港在冬泉谷中部建立的一处风雪笼罩的贸易哨站。它坐落于这片雪谷道路的十字路口，是商人们、勘探者和研究者们抵御高海拔严寒的中立避风港。",kw={"永望镇","地精","格雷格·石灰石","雪","热砂港","贸易哨站","冬泉谷"},ang={["profession:Engineering"]="永望镇是高级工程师们的主要枢纽，特别是那些专精于地精工程学的工程师们，他们可以在这里学习制造直接通往该定居点的空间撕裂器。"},sec={{t="世界边缘的贸易",b="永望镇代表了热砂港最北端的开拓尝试，宛如覆盖在永冻冰层下的加基森和藏宝海湾。这座城墙环绕的定居点矗立在冬泉谷的积雪交汇处，在严格执行的中立原则下运作。这里拥有该地区唯一可用的银行和共享拍卖行服务，吸引着联盟和部落的旅人们前来寻求温暖和庇护。在雇佣保镖的守卫下，这里为人们提供了躲避凶猛霜刃豹和雪人的避风港。"},{t="苔原上的齿轮",b="在冰冷的木质屋顶和奇特的企鹅壁纸之下，永望镇正涌动着对技术的热忱。这里设有专业的工程学车间和先进的炼金实验室，地精工匠们在这里远离窥探的目光，不断突破技艺的极限。外界的外交势力也开始敲响这座挂满冰霜的大门；银色黎明最近派出了格雷格·石灰石来到这里，直接与镇上的领导层进行谈判，密切关注着该地区的古代遗迹，并收集关于北方威胁的情报。"}},faq={{q="谁控制着永望镇？",a="永望镇由热砂港所有并运营，其地方管理机构负责镇上的事务。银色黎明正是派出了格雷格·石灰石作为代表前往那里。",al={"谁管理永望镇","永望镇首领","谁负责永望镇"}},{q="为什么永望镇对联盟和部落都是安全的？",a="热砂港强制执行严格的商业中立政策。地精保镖会迅速痛击任何在城墙内挑起暴力行为的人，确保所有阵营的旅人都能不受阻碍地进行贸易。",al={"永望镇是中立的吗","部落和联盟可以访问永望镇吗","永望镇pvp规则"}},{q="银色黎明为什么在永望镇？",a="银色黎明通过特使格雷格·石灰石维持着官方存在。他作为他们与地精商人的代表，确保获得区域补给并监视当地的威胁。",al={"银色黎明在这里做什么","永望镇的格雷格·石灰石","冬泉谷的银色黎明"}},{q="永望镇的贸易货物从哪里来？",a="永望镇位于冬泉谷主要贸易路线的十字路口，因此货物是通过沿着这些道路的贸易航班和地面商队运抵的。",al={"永望镇走私","冬泉谷贸易货物","永望镇的货物来自何处"}}},fp="8,266,33.520.0,19.526.0,22.176.0,49.214.0,35.205.0,40.145.0"}
P.entries["subzone:faldir-s-cove"] = {n="法迪尔海湾",s="法迪尔海湾是坐落在阿拉希高地南海岸的一处隐蔽的天然港口。这里有着深厚的人类历史，传统上被认为是早期定居者乘船南下建立暴风城的启航点。如今，这里成为了黑水海盗的避难所，他们的船队在遭遇当地险情后被迫在此搁浅。",h="法迪尔海湾是坐落在阿拉希高地南海岸的一处隐蔽的天然港口。这里有着深厚的人类历史，传统上被认为是早期定居者乘船南下建立暴风城的启航点。如今，这里成为了黑水海盗的避难所，他们的船队在遭遇当地险情后被迫在此搁浅。",kw={"黑水海盗","o'breen船长","斯迪加特船长","德拉克里格","水下暗礁","法迪尔","法迪尔海湾","先驱号","菲兹索普"},ang={["race:Gnome"]="营地里有德拉克里格博士和菲兹索普教授，他们部署了巧妙的工程装置，试图分析并提取钙化海岸礁石中的精灵宝石。",["race:Human"]="伫立在这片海岸上，能让人感受到人类与早期先祖的联系，这里是暴风城的先民告别古老帝国阿拉索的著名启航点。"},sec={{t="南方的门户与海盗避风港",b="法迪尔海湾隐藏在激流堡南部的崎岖峭壁之后，通过一条隐蔽的洞穴隧道与大陆相连。这个海湾是为了纪念古老的阿拉索探险家法迪尔，他的探险队正是从这里启航，横跨无尽之海，最终建立了南方的王国——暴风城。然而在今天，这里的宁静水域却迎来了另一群不速之客：一支由藏宝海湾出发的黑水海盗探险队，在斯迪加特船长和O'Breen船长的带领下，他们北上追寻古代精灵的宝藏，却最终被困在了海湾里。"},{t="黑水舰队的沉船",b="黑水海盗的探险在抵达阿拉希海岸后演变成了一场灾难。盘踞在近海“水下暗礁”的娜迦利用诡异且非自然的潮汐击碎了他们三艘船中的两艘。只有“先驱号”得以幸存，勉强驶入法迪尔海湾。随着娜迦在水下潜行，航海图也沉入海底，幸存的海盗和随行的侏儒研究员被困于此，不得不依赖中立的旅者来对抗水下的恐怖生物，并寻回沉船的残骸。"}},faq={{q="法迪尔是谁？",a="法迪尔是早期人类帝国阿拉索的一位先驱。他和追随者们从这处海岸港湾出发，横跨大海，一路向南航行，最终建立了后来成为暴风城的那些定居点。",al={"法迪尔背景故事","法迪尔是谁","法迪尔奠基人"}},{q="如何到达法迪尔海湾？",a="前往海湾需要找到一条隐藏的隧道，入口就在激流堡外墙东南侧。穿过这条地下隧道，旅行者就能直接到达这片僻静的海岸。",al={"如何去法迪尔海湾","法迪尔海湾入口","去往法迪尔海湾的洞穴"}},{q="为什么黑水海盗会在这里？",a="斯迪加特船长和O'Breen船长带领探险队从藏宝海湾一路北上，寻找沉没的精灵宝藏。随行的还有设计了宝石探测装置的侏儒发明家，他们的目标是打捞出埋藏在近海暗礁中的珍贵遗物。",al={"为什么海盗在这里","阿拉希的黑水海盗","海盗在做什么"}},{q="他们的船发生了什么事？",a="探险队的三艘船中有两艘被水下暗礁中充满敌意的娜迦所引发的非自然潮汐摧毁了。只有旗舰“先驱号”安全进入海湾港口，导致船员在丢失航海图的情况下被困在这里。",al={"船只为何沉没","阿拉希沉船","谁击沉了船只"}}},fp="13,356,34.569.0,33.529.0,15.243.0,31.221.0,36.256.0,29.240.0"}
P.entries["subzone:falfarren-river"] = {n="弗伦河",s="弗伦河自东北向西南流经灰谷的心脏地带，发源于海加尔山的山坡，随后潜入贫瘠之地北部山脉的地下。它构成了西侧阿斯特兰纳周边的暗夜精灵领地与东侧不断扩张的部落前哨站之间的天然边界。旅行者必须小心行事，因为河岸林荫深处和浅滩不仅潜伏着充满敌意的野生生物，也标志着公开冲突的前线。",h="弗伦河自东北向西南流经灰谷的心脏地带，发源于海加尔山的山坡，随后潜入贫瘠之地北部山脉的地下。它构成了西侧阿斯特兰纳周边的暗夜精灵领地与东侧不断扩张的部落前哨站之间的天然边界。旅行者必须小心行事，因为河岸林荫深处和浅滩不仅...",kw={"灰谷河流","阿斯特兰纳","弗伦","弗伦河","冥火岭","碎木","萨维亚"},ang={["faction:Alliance"]="对于暗夜精灵及其盟友来说，向东跨过弗伦河就意味着直接踏入了靠近碎木岗哨的部落前线。",["faction:Horde"]="弗伦河标志着部落从碎木岗哨向外扩张的西界，越过此河便是设防的暗夜精灵领地。"},sec={{t="一条有争议的天然边界",b="弗伦河的水流从海加尔山倾泻而下，经过萨维亚的瀑布，蜿蜒流经碎木岗哨和夜道谷之间。虽然在正常天气下它既不算特别深也不至于无法通行，但它却是灰谷中部实际上粗略的地缘政治分界线。西侧是阿斯特兰纳和卡多雷的核心领地；东侧则是部落的营地和伐木场。通过主路上的木桥，旅行者就会进入森林中充满争议的核心地带，巡逻队经常在河岸发生冲突。"},{t="浅滩中的危险",b="除了交战的哨兵和兽人士兵带来的紧张局势外，河面之下还隐藏着自然和非自然的危险。在下游靠近冥火岭的地方，受腐蚀的沼泽兽和极具攻击性的水生生物在泥泞的浅滩中徘徊。降雨会导致水流暴涨，但真正的危险在于河岸两侧茂密的树冠，埋伏和遭遇战经常会蔓延到河道中。"}},faq={{q="弗伦河的起点和终点在哪里？",a="弗伦河发源于海加尔山的高处，经瀑布倾泻而下，汇入萨维亚的湖泊。此后，它向西南蜿蜒穿过灰谷，最终潜入贫瘠之地北部山脉之下的地下河道。",al={"弗伦河源头","河流去向"}},{q="为什么弗伦河对灰谷的战争意义重大？",a="它是灰谷中部暗夜精灵和部落势力范围之间粗略的分界线。以阿斯特兰纳为中心的暗夜精灵领地位于西侧，而兽人的碎木岗哨和活跃的部落伐木场则位于东侧。",al={"弗伦河的重要性","灰谷河流边界"}},{q="旅行者在河岸边会遇到什么威胁？",a="极具攻击性的沼泽兽在浅滩游荡，特别是在冥火岭周边的受腐蚀区域。此外，联盟和部落的巡逻队都在监视着桥梁和渡口，使得无人看管的河岸成为了遭遇战和伏击的高发地带。",al={"弗伦河中的怪物","弗伦河的危险"}}},fx={["553b1115"]={q="弗伦河是什么？",a="弗伦河是贯穿灰谷中部的一条水道，流向由东北至西南。河水从海加尔山山坡流下，经过萨维亚，随后消失在贫瘠之地北部的山脉之下。它大致构成了一道天然边界，将阿斯特兰纳周边的暗夜精灵领地与部落在碎木岗哨的据点分隔开来。",al={"弗伦河是什么","弗伦河信息","弗伦河在哪里"}},["6238ff52"]={q="弗伦河危险吗？",a="是的。除了哨兵与部落沿河渡口持续发生军事冲突，河水本身也暗藏自然危险。冥火岭附近的水面下潜伏着凶猛的沼泽兽，任何试图涉过浅滩的人都可能遭遇致命突袭。",al={"弗伦河危险吗","弗伦河的危险","弗伦河的威胁"}}},fp="15,448,28.563.0,23.395.0,45.261.0,63.255.0,58.267.0"}
P.entries["subzone:fallen-sky-lake"] = {n="坠星湖",s="坠星湖是一处隐蔽的水域，坐落在东灰谷的丛林深处。它位于银翼哨站与步步紧逼的战歌劳工营地之间，宁静的水面下隐藏着危机——充满敌意的阴影灌木沼泽兽，它们正凶猛地守卫着湖泊及其中心的小岛。",h="坠星湖是一处隐蔽的水域，坐落在东灰谷的丛林深处。它位于银翼哨站与步步紧逼的战歌劳工营地之间，宁静的水面下隐藏着危机——充满敌意的阴影灌木沼泽兽，它们正凶猛地守卫着湖泊及其中心的小岛。",kw={"灰谷","坠星湖","先知","阴影灌木","银翼哨站","战歌劳工营地","沼泽兽"},ang={["class:Druid"]="暗夜精灵曾一度在坠星湖采集月亮石，但如今，敌对的阴影灌木沼泽兽占据了这片水域，使这片安静的林中角落也变得危险重重。",["race:NightElf"]="湖泊位于银翼哨站的正南方，这里是神圣的祖传森林的又一个角落，在部落战鼓声的逼近下，这里的野生动物变得越发狂躁。"},sec={{t="一片受争议的避风港",b="Tucked south of Silverwing Outpost and just west of the Warsong Labor Camp, Fallen Sky Lake offers a fleeting glimpse of Ashenvale's natural splendor before the Orcish axes took root nearby. The shores and the small islet rising from the middle of the lake are inhabited by shadethickets—hulking bog beasts that view any intruder as a threat. The heart of the island serves as the domain of a powerful Shadethicket Oracle, who hoards the fallen moonstones once gathered at the lake and keeps the local shadethickets bound to the waters and relentlessly vigilant against travelers passing through."}},faq={{q="坠星湖位于哪里？",a="坠星湖位于东灰谷，就在银翼哨站的正南方、战歌劳工营地的西边，以及银翼树林的东北方。",al={"坠星湖位置","坠星湖在哪里","如何找到坠星湖"}},{q="坠星湖周围生活着什么生物？",a="湖泊及其周围的河岸被阴影灌木所占据，这是一种具有攻击性的沼泽兽。它们由居住在中心岛屿上的一位强大的阴影灌木先知所领导。",al={"坠星湖的怪物","坠星湖有什么","坠星湖的敌人"}},{q="为什么阴影灌木先知很重要？",a="阴影灌木先知是聚集在湖边的阴影灌木的首领。它囤积着暗夜精灵曾经在这里采集的坠落月亮石，因此任何需要月亮石的人都必须在中央岛屿上击败它。",al={"坠星湖的先知","阴影灌木先知","岛上有什么人"}}},fx={["0e5e2d0e"]={q="坠星湖是什么地方？",a="坠星湖是一片小而隐蔽的水域，藏在灰谷中部，位于银翼哨站以南、战歌劳工营地以西。湖心有一座孤岛，四周环绕着宁静却令人不安的湖水，坐落在古老而争夺不断的林地之中。",al={"坠星湖","坠星湖介绍","这片湖是什么"}},["62a4135b"]={q="坠星湖危险吗？",a="是的，这里远非安宁。湖中及湖岸遍布敌对的影棘植物，笨重的沼泽兽在水中和岸边徘徊。湖心岛上潜伏着影棘先知，它是一种格外强大且敌对的生物，囤积着坠落在湖中的月亮石。",al={"坠星湖的危险","这里安全吗","坠星湖的威胁"}}},fp="15,306,21.598.0,33.153.0,43.163.0,41.215.0"}
P.entries["subzone:fallow-sanctuary"] = {n="农田避难所",s="农田避难所是一座隐藏在悲伤沼泽深处泥沼中的僻静村庄。它是被称作失落者的变异德莱尼部落的家园，这些德莱尼人因极度的悲伤和思乡之情而变得野性难驯。",h="农田避难所是一座隐藏在悲伤沼泽深处泥沼中的僻静村庄。它是被称作失落者的变异德莱尼部落的家园，这些德莱尼人因极度的悲伤和思乡之情而变得野性难驯。",kw={"农田避难所","失落者","棍棒手noboru","ongeku","悲伤沼泽"},ang={["class:Warlock"]="失落者扭曲的命运展示了黑暗能量是如何扭曲活体血肉并摧毁脆弱心灵的。"},sec={{t="被疯狂吞噬的避难所",b="农田避难所坐落在悲伤沼泽沉没的树木之间，由流离失所的失落者建立，他们在此寻求一处安身之所。与故土世界断绝联系，又被黑暗能量扭曲，这些可怜的流亡者在沼泽地中找不到安宁。随着时间流逝，无尽的悲伤与孤独摧毁了他们的理智，使整个部落陷入了一种敌对、野蛮的状态，疯狂攻击任何擅闯他们村庄的外来者。"},{t="失踪的领袖",b="这个定居点曾经由Ongeku和Noboru the Cudgel等人领导，但随着他们的离去和死亡，村庄的领导体系也随之瓦解。"}},faq={{q="什么是农田避难所？",a="它是位于悲伤沼泽中的一个定居点，居住着失落者，这是一群通过黑暗之门来到此地、经过严重变异且命运悲惨的德莱尼分支。",al={"农田避难所背景","这个村庄是什么","沼泽中的失落者营地"}},{q="为什么这里的失落者如此敌对？",a="因为被困在艾泽拉斯，并与他们所熟悉的一切隔绝，这里的失落者因悲伤和思乡之情而彻底疯狂，导致他们变得极其野蛮，对外来者充满攻击性。",al={"为什么失落者会攻击人","失落者是邪恶的吗","野性的失落者"}},{q="谁领导农田避难所？",a="该部落以前听命于Ongeku和Noboru the Cudgel等知名人物，但由于他们的失踪和死亡，部落的领导权分崩离析。",al={"谁在管理农田避难所","noboru","ongeku"}}},fp="16,237,24.457.0,16.153.0,29.162.0,35.205.0,31.162.0"}
P.entries["subzone:faol-s-rest"] = {n="法奥之墓",s="法奥之墓是一处宁静而被遗忘的墓地，位于提瑞斯法林地东部，就在血色修道院的西南方。它最初是作为大主教阿隆索斯·法奥的陵墓而建的，这位受人尊敬的精神领袖创立了白银之手骑士团。如今，在枯萎的林冠下，它无人照管，成了那些在修道院附近丧生之人的灵魂归宿地。",h="法奥之墓是一处宁静而被遗忘的墓地，位于提瑞斯法林地东部，就在血色修道院的西南方。它最初是作为大主教阿隆索斯·法奥的陵墓而建的，这位受人尊敬的精神领袖创立了白银之手骑士团。如今，在枯萎的林冠下，它无人照管，成了那些在修道院...",kw={"阿隆索斯·法奥","圣光教会","法奥之墓","墓地","血色修道院","白银之手","提瑞斯法林地"},ang={["class:Paladin"]="每一位圣骑士都归功于大主教法奥的感召，是他最初召集了乌瑟尔和他的同僚，将武艺与圣光结合在一起。站在他无人照料的墓前，令人清醒地回想起该教团的起源。",["class:Priest"]="作为第二次战争期间圣光教会的最高领袖，法奥是洛丹伦所有神职人员的牧者；看到他的纪念碑破败不堪，反映了教会在北方的悲剧性毁灭。"},sec={{t="大主教之墓",b="在第三次战争摧毁洛丹伦之前，这处幽静的山谷是人们虔诚朝圣的地方。这里安放着大主教阿隆索斯·法奥的石棺，他曾在第二次战争的黑暗时期领导圣光教会，并建立了圣骑士教团以保护人类。法奥在天灾军团到来之前安详离世，免于目睹王国陨落的凡世痛苦。在那些更为美好的岁月里，哀悼者们经常从洛丹伦王城沿着道路前来，向这位受人爱戴的先驱敬献贡品，表达敬意。"},{t="修道院阴影下的荒凉",b="当亡灵瘟疫席卷洛丹伦时，提瑞斯法凋零了，朝圣者们也随之消失。如今，这座纪念碑被遗弃在血色修道院高耸峭壁下的阴影中，碑体已然破裂。荒野的灌木重新覆盖了道路，墓穴本身静静地躺在潮湿的薄雾中。对于那些对抗血色十字军狂热者或提瑞斯法残留恐怖的冒险者来说，这处被遗忘的安息之所现在主要作为一个宁静的过渡地，让倒下的灵魂在重返战场前能在此短暂地重整旗鼓。"}},faq={{q="阿隆索斯·法奥是谁？",a="阿隆索斯·法奥是第二次战争期间圣光教会的大主教。他以智慧和仁慈著称，曾组织救援难民，并创立了白银之手骑士团，将神圣的牧师和虔诚的骑士转变为人类的第一批圣骑士，其中包括乌瑟尔·光明使者和图拉扬。",al={"阿隆索斯·法奥是谁","阿隆索斯·法奥背景故事","这里埋葬着谁"}},{q="为什么这座纪念碑会位于血色修道院附近？",a="血色修道院附近的土地曾是北洛丹伦圣光教会历史上重要的宗教资产。法奥在王国陨落前，也就是在那些身穿血色战袍的狂热者加固附近的修道院之前很久，就已经安息在了提瑞斯法林地的这片宁静角落里。",al={"为什么在修道院附近","与血色修道院的联系","地点含义"}},{q="现在有人维护这座墓穴吗？",a="没有。自洛丹伦被天灾军团攻陷以来，这里就彻底被遗弃了。血色十字军很少会来到这片山谷中进行打理，而被遗忘者对祭拜旧教会的神龛也没什么兴趣，任由石碑在风雨侵蚀和杂草丛生中荒废。",al={"谁在维护法奥之墓","是否被废弃","墓穴维护"}},{q="法奥之墓对旅行者有什么实际用途？",a="法奥之墓是周围荒野和血色修道院当地的灵魂归宿地。那些在试图闯入修道院或穿行于提瑞斯法东部时丧生的冒险者，其灵魂会回到这位大主教宁静的纪念碑前。",al={"灵魂归位","此地在游戏中的用途","修道院墓地"}}},fx={f2893c17={q="法奥之墓是什么地方？",a="法奥之墓是提瑞斯法林地东部丘陵中的一处僻静而庄严的墓地，位于血色修道院西南方不远处。这里是为纪念大主教阿隆苏斯·法奥而建。他是圣光最受尊崇的人物之一，也是白银之手骑士团的创始人。洛丹伦王国覆灭前，这里曾吸引着来自各地的虔诚信徒前来朝圣。",al={"法奥之墓是什么","法奥之墓的背景","法奥之墓"}},["02f08d97"]={q="法奥之墓发生过什么事？",a="大主教阿隆苏斯·法奥在第三次战争前逝世，随后在此安葬，葬礼规模盛大，哀悼者众多。朝圣者从王国各地赶来，在他的墓前表达敬意。然而，天灾席卷洛丹伦后，王国化为废墟，死者也纷纷复起，神圣的山坡就此遭到亵渎，变得荒废，无人照料。",al={"法奥之墓的历史","法奥之墓发生了什么"}},["7971c9da"]={q="法奥之墓为何荒废？",a="亡灵瘟疫肆虐洛丹伦时，曾经敬仰这位大主教的王国也遭到毁灭。血色十字军将自己封闭在附近的要塞中，与亡灵进行无休止的战争，再也没有人照看这处纪念地。于是墓地饱经风霜、杂草丛生，也渐渐被外界遗忘。",al={"法奥之墓为何被遗弃","法奥之墓为何荒废","谁照看法奥之墓"}},["3ebb89a0"]={q="法奥之墓危险吗？",a="墓地周围的空地静谧而庄严，但周边山坡危机四伏。血色十字军的狂热者在通往附近修道院的道路上巡逻，会攻击所有外来者；凶猛的野兽和游荡的天灾也出没于提瑞斯法林地东部雾气笼罩的丘陵中。",al={"法奥之墓危险吗","法奥之墓安全吗","法奥之墓的危险"}},bc843590={q="这里为什么叫法奥之墓？",a="这处遗址是为纪念大主教阿隆苏斯·法奥而命名的。他逝世后最初便葬在这里。圣光教会将他视为圣徒般的宗主，因此将这片纪念地奉献给这位深受爱戴的领袖，让他在此长眠。",al={"这里为什么叫法奥之墓","法奥之墓是为纪念谁而命名的","法奥之墓的名字"}}},fp="11,371,22.547.0,41.541.0,21.325.0,56.301.0,37.280.0,60.263.0"}
P.entries["subzone:far-watch-post"] = {n="前沿哨所",s="前沿哨所是部落的一处防御性哨站，坐落于连接杜隆塔尔与贫瘠之地的怒水河大桥西侧。作为兽人故乡的前线防御阵地，该哨所保护着重要的贸易商队，抵御好斗的野猪人族群和敌对的联盟入侵者。",h="前沿哨所是部落的一处防御性哨站，坐落于连接杜隆塔尔与贫瘠之地的怒水河大桥西侧。作为兽人故乡的前线防御阵地，该哨所保护着重要的贸易商队，抵御好斗的野猪人族群和敌对的联盟入侵者。",kw={"贫瘠之地","地洞","杜隆塔尔","前沿哨所","苦工","野猪人","怒水河","瞭望塔","狼"},ang={["faction:Alliance"]="前沿哨所正对着杜隆塔尔的大桥，宛如一道坚不可摧的路障，防止了侦察小队和破坏分子轻易接近这座兽人首都。",["faction:Horde"]="对于第一次走出杜隆塔尔的年轻勇士来说，前沿哨所是他们在进入卡利姆多崎岖且危险的中心地带前，最后的一处熟悉之地。"},sec={{t="边境守卫者",b="前沿哨所位于杜隆塔尔大桥的西侧桥头，是旅客进入广阔干旱的贫瘠之地萨瓦纳大草原时，首先看到的部落权威堡垒。这里的设施简朴但功能齐全，是为战术戒备而非舒适生活而建。哨所内设有一座坚固的兽人瞭望塔、一处地洞，以及预先瞄准尘土飞扬平原的攻城弩车。在大路的正南方，苦工们照料着成群的坐骑狼，随时准备搭载信使或援军。前沿哨所存在的主要目的是保障通往十字路口的补给路线安全，筛查过往交通，并击退游荡的野猪人部落和潜行的联盟斥候。"}},faq={{q="前沿哨所的目的是什么？",a="该哨所充当了杜隆塔尔与贫瘠之地之间的主要边境站。其守卫者负责保护部落关键的补给商队，并确保当地威胁（主要是好斗的野猪人部落和联盟越界者）不会越过怒水河进入杜隆塔尔。",al={"为什么前沿哨所会建在这里","前沿哨所的目的","前沿哨所的角色"}},{q="谁控制着这个哨站？",a="前沿哨所是一处由部落驻守的现役军事营地。兽人步兵驻扎在塔楼中并维护攻城器械，此外还有照看坐骑狼的苦工提供辅助。",al={"谁在管理前沿哨所","前沿哨所的阵营"}},{q="该哨站面临哪些威胁？",a="哨所面临着附近野猪人族群的频繁骚扰，这些野猪人与驻军争夺着周边布满荆棘的灌木丛地带。同时，它也时刻警惕着可能试图穿过贫瘠之地向奥格瑞玛发起突袭的联盟入侵者。",al={"前沿哨所的敌人","前沿哨所的危险"}}},fx={c35ec5b1={q="前沿哨所是什么地方？",a="前沿哨所是部落的一处设防据点，位于连接杜隆塔尔与贫瘠之地的桥梁以西不远处。这里有坚固的瞭望塔、兽人地穴、投石车，以及南边的狼栏，是守卫杜隆塔尔西部边境的主要门户，也负责确保旅人和补给车队能够通行，进入荒野平原。",al={"前沿哨所是什么","前沿哨所的背景","介绍一下前沿哨所"}},d7c9315a={q="前沿哨所危险吗？",a="对部落旅人而言，哨所本身在经验丰富的战士和苦工严密守卫下十分安全。但在其防线之外，周边仍然危机四伏。敌对的野猪人出没于附近的灌木丛生地带，联盟也可能发动突袭，因此旅人和哨兵都必须时刻保持警惕。",al={"前沿哨所安全吗","前沿哨所的危险"}}},fp="14,293,22.683.0,38.265.0,26.175.0,35.233.0"}
P.entries["subzone:fargodeep-mine"] = {n="法戈第矿洞",s="法戈第矿洞是一座废弃的金矿，位于艾尔文森林中部，闪金镇的南边。它曾经是暴风城王国的一处重要的财富来源，但最近却被一群好战的狗头人占领了。",h="法戈第矿洞是一座废弃的金矿，位于艾尔文森林中部，闪金镇的南边。它曾经是暴风城王国的一处重要的财富来源，但最近却被一群好战的狗头人占领了。",kw={"蜡烛","艾尔文","法戈第","法戈第矿洞","闪金镇","金牙","狗头人","治安官杜汉","“二倍”雷米"},ang={["faction:Alliance"]="清除法戈第矿洞中的害虫，对于确保闪金镇周边地区的补给线和农场安全至关重要。",["profession:Mining"]="尽管布满了害虫，但法戈第矿洞的岩石隧道中依然蕴藏着丰富的铜矿脉，适合新手矿工开采。"},sec={{t="失落的矿脉",b="法戈第矿洞曾经为暴风城的国库提供了稳定的黄金来源，但王国在艾尔文森林的军事力量日益减少，导致边远地区的资源变得不堪一击。狗头人迅速涌入黑暗的隧道中，在丘陵下方建立了一个熙熙攘攘的巢穴。治安官杜汉和闪金镇的当地官员对这种侵扰深感担忧，这不仅是因为矿石的流失，还因为这些变得胆大包天的生物如今威胁到了附近的农场，比如斯通菲尔德农场和马科伦农场。"},{t="巢穴深处",b="这座矿洞分为多层，下层的坑道在森林地表下蜿蜒延伸。狗头人劳工和害虫在木制脚手架上四处奔窜，凶猛地守卫着它们搜刮来的蜡烛和金砂。在主隧道上方的一个巢穴里潜伏着金牙，他是一个特别狡猾的狗头人首领，以囤积从粗心的旅行者和周围居民那里偷来的小饰品而闻名。"}},faq={{q="为什么暴风城会放弃法戈第矿洞？",a="由于暴风城的军事力量在南部各地的防线过于分散，矿洞遭到了忽视。城镇卫兵忙于保护闪金镇和主干道，导致这个地下挖掘点无人看守，狗头人趁机入驻并加固了隧道。",al={"为什么废弃","人类为什么离开法戈第","谁拥有法戈第矿洞"}},{q="这里的狗头人为什么对当地农民如此危险？",a="法戈第矿洞位于斯通菲尔德和马科伦家族的农场之间。狗头人从隧道中溜出来偷窃牲畜、工具和个人物品，骚扰任何在矿洞入口附近徘徊的人。",al={"狗头人为何是个问题","狗头人威胁","斯通菲尔德的狗头人"}},{q="金牙是谁？",a="金牙是一位显赫的狗头人，住在法戈第矿洞上层的一个巢穴里。他因偷走了伯尼斯·斯通菲尔德大婶珍贵的传家项链而臭名昭著。",al={"金牙","谁是金牙","金牙的位置"}},{q="为什么闪金镇的人想要矿洞里的物品？",a="当地商人和镇民认为清除害虫有利可图：“二倍”雷米会收购打捞上来的金砂，炼金师威廉·匹斯特需要狗头人的蜡烛蜡来制作试剂，而治安官杜汉则需要监控这种侵扰，以确保艾尔文森林的安全。",al={"法戈第任务","为什么要收集蜡烛","金砂"}}},fx={["7f063a4c"]={q="法戈第矿洞是什么地方？",a="法戈第矿洞是艾尔文森林中部、闪金镇以南的一座废弃金矿。它曾是为暴风城王国供应矿石的采掘场，如今已被弃置，地上洞室和地下矿道都被穴居的狗头人占据。",al={"法戈第矿洞是什么","法戈第矿洞概览","关于法戈第矿洞"}},e2f4f077={q="法戈第矿洞发生过什么事？",a="最初，暴风城的矿工在此开采艾尔文森林丰富的金脉。后来矿工撤离，矿洞也随之废弃。一群好斗的狗头人趁机搬入，挖掘隧道、建立巢穴，将旧矿道变成设防的巢窟，威胁着附近的定居点。",al={"法戈第矿洞的历史","这里发生了什么","法戈第矿洞的背景"}}},fp="14,222,11.492.0,20.379.0,41.252.0,55.222.0,17.178.0,52.251.0"}
P.entries["subzone:farstrider-lodge"] = {n="旅行者营地",s="旅行者营地是位于洛克莫丹东南部的一处狩猎前哨站。其建筑风格显然属于高等精灵，而居住在这里的人包括高等精灵维林·迅风、矮人和人类。猎人和旅行者来到这里寻求训练、补给以及周边荒野的工作。",h="旅行者营地是位于洛克莫丹东南部的一处狩猎前哨站。其建筑风格显然属于高等精灵，而居住在这里的人包括高等精灵维林·迅风、矮人和人类。猎人和旅行者来到这里寻求训练、补给以及周边荒野的工作。",kw={"旅行者营地","远行者","高等精灵","猎人营地","洛克莫丹","塞尔萨玛","维林·迅风"},ang={["class:Hunter"]="旅行者营地是猎人的绝佳庇护所，在洛克莫丹周边丘陵丰富的猎物环绕中，提供射击和野兽训练的指导。",["race:Dwarf"]="矮人猎人和商人与人类居民以及高等精灵维林·迅风共享这处营地。"},sec={{t="山中的精灵避风港",b="旅行者营地与卡兹莫丹典型的坚固石建筑截然不同。其建筑风格显示出高等精灵的工艺。维林·迅风是目前已知唯一仍居住在此处的高等精灵，与矮人和人类比邻而居。营地的建立者和建造日期尚未确定。"},{t="荒野的中转站",b="营地坐落在洛克莫丹东南部的山丘上，为探索周边荒野的猎人和旅行者提供服务。猎人训练师和宠物训练师在这里工作，还有商人和寻求解决当地野生动物问题的访客。"}},faq={{q="为什么卡兹莫丹会有精灵营地？",a="营地的建筑暗示其起源于高等精灵，而维林·迅风是目前在此居住的幸存高等精灵。其建立者、建造日期和最初的使命均未确定。",al={"为什么洛克莫丹有精灵建筑","谁建造了旅行者营地","为什么这里有高等精灵营地"}},{q="这里还有高等精灵居住吗？",a="目前只有一名高等精灵维林·迅风居住在营地中。其余的居住者是矮人山地猎人和人类猎人，他们维护着营地并与旅行者进行贸易。",al={"这里有高等精灵吗","谁住在旅行者营地","维林·迅风"}},{q="旅行者营地提供哪些服务？",a="营地提供猎人训练师、宠物训练师、商人，并受理涉及洛克莫丹荒野的当地请求。",al={"旅行者营地有什么","洛克莫丹的猎人训练师"}}},fx={ede1c062={q="旅行者营地是什么地方？",a="旅行者营地是一处狩猎据点，坐落在洛克莫丹东南岸边。这里的精致精灵建筑与崎岖的矮人丘陵形成鲜明对比，是追踪者、驯兽师和途经卡兹莫丹的旅人安歇的宁静之所。",al={"旅行者营地是什么","旅行者营地的背景","介绍一下旅行者营地"}},["048016ac"]={q="为什么叫旅行者营地？",a="这个名字让人想起奎尔萨拉斯的游侠——远行者，与营地的高等精灵建筑风格相得益彰。营地的确切建立历史尚无定论。",al={"为什么叫旅行者营地","旅行者营地名称的含义","洛克莫丹的远行者是谁"}},["65e56c06"]={q="旅行者营地危险吗？",a="旅行者营地本身是联盟成员的安全庇护所，提供休息和补给。但营地门外的荒野中有许多具有攻击性的野生动物，附近的洛克莫丹山谷中还有敌对的穴居人和豺狼人出没。",al={"旅行者营地安全吗","旅行者营地有敌意吗","旅行者营地的危险"}}},fp="16,278,31.296.0,26.225.0,42.185.0,39.191.0,48.113.0"}
P.entries["subzone:feathermoon-stronghold"] = {n="羽月要塞",s="羽月要塞是卡利姆多南部首屈一指的暗夜精灵军事基地，坐落在被遗忘的海岸外的萨尔多岛上，地理位置十分稳固。这座设防的前哨站由珊蒂斯·羽月将军指挥，向广袤的荒野森林投射哨兵部队的力量，并时刻监视着该地区的威胁。",h="羽月要塞是卡利姆多南部首屈一指的暗夜精灵军事基地，坐落在被遗忘的海岸外的萨尔多岛上，地理位置十分稳固。这座设防的前哨站由珊蒂斯·羽月将军指挥，向广袤的荒野森林投射哨兵部队的力量，并时刻监视着该地区的威胁。",kw={"羽月","羽月要塞","菲拉斯","被遗忘的海岸","卡多雷","月亮井","萨尔多岛","哨兵","珊蒂斯·羽月"},ang={["faction:Alliance"]="对于在卡利姆多南部历险的联盟勇士来说，羽月要塞在菲拉斯那充满敌意的荒野之中提供了宝贵的补给、飞行航线和任务总部。",["race:NightElf"]="作为灰谷以南主要的哨兵营地，这座要塞在珊蒂斯·羽月将军的领导下，代表了卡多雷守卫卡利姆多的坚定决心。"},sec={{t="南方的哨兵堡垒",b="羽月要塞矗立在菲拉斯大陆对岸的萨尔多岛上，是哨兵部队在卡利姆多南部的主要战略基地。这座要塞修建在古老的精灵树林之中，并配有一口神圣的月亮井，在珊蒂斯·羽月将军的直接监督下，驻扎着弓箭手、女猎手和后勤人员。在这座与世隔绝的避风港中，暗夜精灵不仅能够将他们的影响力投射到菲拉斯苍翠的腹地，还能防范恶魔的腐化、敌对的野生生物以及部落不断推进的远征部队。"},{t="荒野中的避风港",b="由于菲拉斯大陆上遍布着凶猛的野兽、戈杜尼食人魔以及厄运之槌那令人不安的阴影，萨尔多岛提供了一个至关重要的防御缓冲地带。联盟的旅行者依靠从被遗忘的海岸出发的渡轮抵达要塞码头，在那里修整装备并收集情报。珊蒂斯·羽月——哨兵将军兼泰兰德·语风大祭司最信任的副手——的坐镇，确保了这座要塞成为了卡多雷所有敌人无法攻破的堡垒。"}},faq={{q="羽月要塞位于何处？",a="羽月要塞位于萨尔多岛，这是一座位于菲拉斯西侧被遗忘的海岸外的小岛。旅行者必须向西穿过森林到达海岸，然后乘船渡水才能抵达这座岛屿要塞。",al={"羽月位置","羽月在哪里","如何前往羽月要塞"}},{q="谁在指挥羽月要塞？",a="这座要塞由哨兵部队的最高指挥官、泰兰德·语风大祭司的副手——珊蒂斯·羽月将军指挥。她在此前哨站统筹卡多雷在卡利姆多南部的一切军事行动。",al={"谁领导羽月","羽月领袖","珊蒂斯·羽月基地"}},{q="为什么要塞要建在岛上而不是大陆上？",a="萨尔多岛为菲拉斯大陆上的诸多危险提供了天然的海洋屏障，大陆上此时已被凶猛的野兽、戈杜尼食人魔以及挥之不去的奥术和恶魔威胁所侵扰。将要塞建在岛屿上不仅提供了一个能控制沿海水域的安全港口，还能将大陆上的威胁拒之门外。",al={"为什么是萨尔多岛","为什么羽月在岛上"}},{q="羽月要塞有月亮井吗？",a="是的，羽月要塞内确实有一口神圣的月亮井。它为远离北方故土、驻扎在此的暗夜精灵守军提供了精神寄托、补给以及圣水来源。",al={"羽月月亮井","羽月有月亮井吗"}}},fp="22,307,29.554.0,25.534.0,40.242.0,36.244.0,67.310.0,44.218.0"}
P.entries["subzone:feathermoon-stronghold-classic"] = {n="Feathermoon Stronghold (Classic)",s="羽月要塞是一座位于菲拉斯西海岸外萨尔多岛上的坚固暗夜精灵堡垒。它由珊蒂斯·羽月将军建立，是联盟在卡利姆多南部的主要集结地和军事据点。",h="羽月要塞是一座位于菲拉斯西海岸外萨尔多岛上的坚固暗夜精灵堡垒。它由珊蒂斯·羽月将军建立，是联盟在卡利姆多南部的主要集结地和军事据点。",kw={"联盟","羽月要塞","菲拉斯","被遗忘的海岸","萨尔多岛","哨兵部队","珊蒂斯·羽月"},ang={["faction:Alliance"]="羽月要塞是联盟在卡利姆多南部深处行动的主要避难所、商贸站和集结中心。",["race:NightElf"]="这座要塞是珊蒂斯·羽月将军和哨兵部队的南方军事总部，是这片古老荒野的重要守护者。"},sec={{t="南方的哨兵堡垒",b="羽月要塞坐落于被遗忘的海岸外的萨尔多岛上，是暗夜精灵乃至整个联盟的重要堡垒。这座要塞由泰兰德·语风最信任的副官、已追随她万年之久的珊蒂斯·羽月将军主持修建，将哨兵的力量投射至卡利姆多南部深处。它孤悬海外的地理位置使其免受菲拉斯原始丛林中潜伏的野兽、食人魔和部落入侵者的威胁。"},{t="跨越海浪的生命线",b="由于其孤悬海外的地理位置，羽月要塞在后勤保障上极度依赖海上和空中交通。一艘小型客船定期往返于萨尔多岛和被遗忘的海岸码头之间。为了方便远程旅行，要塞还设有专用的角鹰兽管理员，将要塞与联盟的主要枢纽直接相连，包括千针石林边缘的萨兰纳尔、凄凉之地高地的尼耶尔前哨站，以及北方的奥伯丁。"}},faq={{q="如何从菲拉斯大陆前往羽月要塞？",a="旅行者可以搭乘渡轮前往海峡对岸的被遗忘的海岸码头，也可以直接游过狭窄的海峡抵达萨尔多岛。一旦发现了飞行管理员，联盟成员还可以乘坐角鹰兽前往。",al={"前往羽月要塞的方法","羽月要塞船只","前往萨尔多岛"}},{q="谁指挥着羽月要塞？",a="该哨所由珊蒂斯·羽月将军指挥，她是哨兵部队的高级领导者，也是月之女祭司泰兰德·语风长期以来的军事下属。",al={"羽月要塞指挥官","羽月要塞领导者","珊蒂斯·羽月"}},{q="为什么这座要塞建在岛上而不是大陆上？",a="萨尔多岛提供了天然的隔离和安全屏障，使其免受菲拉斯荒野中密集的威胁（包括凶猛的野生生物、原始遗迹和敌对势力）影响，这使得哨兵部队能够维持一座坚不可摧的堡垒。",al={"为什么在萨尔多岛","为什么建造岛屿要塞","羽月要塞背景知识"}},{q="羽月要塞的飞行路线连接到哪里？",a="羽月要塞的角鹰兽管理员维持着连接卡利姆多西部的航线，包括黑海岸的奥伯丁、凄凉之地的尼耶尔前哨站、菲拉斯的萨兰纳尔，以及希利苏斯的塞纳里奥要塞。",al={"羽月要塞飞行管理员","羽月要塞角鹰兽航线"}}},fp="32,252,29.474.0,25.443.0,62.243.0,36.175.0,67.226.0,47.198.0"}
P.entries["subzone:fel-rock"] = {n="地狱石",s="地狱石是隐蔽在泰达希尔枝叶间，位于多兰纳尔以北森林中的一座被腐蚀的洞穴。这里曾是一处宁静的凹地，但在萨特梅兰纳斯领主和他手下凶残小鬼的腐化下，现已堕落。",h="地狱石是隐蔽在泰达希尔枝叶间，位于多兰纳尔以北森林中的一座被腐蚀的洞穴。这里曾是一处宁静的凹地，但在萨特梅兰纳斯领主和他手下凶残小鬼的腐化下，现已堕落。",kw={"多兰纳尔","地狱石","小鬼","梅兰纳斯领主","萨特","塔隆凯·捷根","泰达希尔"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊将地狱石视为年轻世界之树上的一处溃烂伤口，必须在恶魔腐蚀扩散前立即进行净化。",["race:NightElf"]="对于卡多雷来说，像梅兰纳斯领主这样的萨特竟然出现在离多兰纳尔如此之近的地方，是对泰达希尔令人震惊的冒犯，必须迅速予以惩戒。"},sec={{t="腐化之巢",b="地狱石藏在多兰纳尔北部的林地山丘中，曾经是一座普通的宁静洞穴，开凿在泰达希尔的木石之间。如今，它已成为世界之树上蔓延腐蚀的令人不安的象征。扭曲的根须和非自然的阴影占据了洞穴内部，到处都是成群的野生小鬼和幼年小鬼。"},{t="萨特的据点",b="地狱石内的腐蚀源于梅兰纳斯领主的存在，这是一个邪恶的萨特，他已将这处凹地据为己有，作为自己的据点。他在洞穴深处策划着恶意腐蚀的扩散，就在暗夜精灵哨兵的严密监视下。来自多兰纳尔的德鲁伊，特别是塔隆凯·捷根，正积极招募有能力的守卫来净化洞穴，并在他的邪恶枯萎病进一步蔓延到周围林地之前除掉梅兰纳斯。"}},faq={{q="地狱石位于何处？",a="地狱石位于泰达希尔中部，隐藏在多兰纳尔定居点正北方的山丘中。",al={"地狱石位置","地狱石在哪里","寻找地狱石"}},{q="谁统治着地狱石？",a="这座洞穴由梅兰纳斯领主指挥，这是一个邪恶的萨特，他将地狱石变成了自己的巢穴，并聚集了一群小鬼来听候他的差遣。",al={"地狱石里有什么","地狱石首领","梅兰纳斯领主位置"}},{q="为什么德鲁伊会对地狱石感到担忧？",a="在世界之树的枝干中出现萨特和受邪能腐蚀的小鬼，这对泰达希尔的自然平衡构成了直接威胁。像塔隆凯·捷根这样的德鲁伊会派遣冒险者去消灭梅兰纳斯领主，遏制这种腐蚀。",al={"为何清理地狱石","地狱石任务","塔隆凯·捷根任务"}},{q="洞穴内栖息着什么生物？",a="在地狱石内，你会遇到极具攻击性的小鬼、幼年小鬼，以及它们黑暗的主人，萨特梅兰纳斯领主。",al={"地狱石怪物","地狱石里面有什么","地狱石敌人"}}},fx={["32acb48e"]={q="地狱石是什么地方？",a="地狱石是泰达希尔枝干中一处黑暗、遭到腐化的洞穴，位于多兰纳尔以北不远处。它原本是一处天然纯净的洞窟，如今邪恶的恶魔腐化已深入洞穴深处，使其变成邪恶的格雷尔和萨特的巢穴。",al={"地狱石是什么","地狱石概览","地狱石的背景"}},["3eaad617"]={q="为什么叫地狱石？",a="这处洞穴的名字源于污秽的恶魔腐化，它污染了洞穴的岩石和深处。这里原本是泰达希尔上一处天然纯净的洞窟；萨特的到来和黑暗邪能的蔓延，让它得到了地狱石这个不祥的名字。",al={"为何叫地狱石","地狱石名称的由来","这里为什么叫地狱石"}}},fp="8,238,19.354.0,16.468.0,26.110.0,19.133.0,40.244.0,39.111.0"}
P.entries["subzone:felfire-hill"] = {n="冥火岭",s="冥火岭是一座位于东部灰谷的被腐蚀、被恶魔占据的山丘。在第三次战争期间，这里遭受了地狱火的坠落撞击，其被腐化的土地至今仍燃烧着恶魔之力。部落在通往山丘的桥梁上设置了坚固的哨所，以保卫附近的定居点。",h="冥火岭是一座位于东部灰谷的被腐蚀、被恶魔占据的山丘。在第三次战争期间，这里遭受了地狱火的坠落撞击，其被腐化的土地至今仍燃烧着恶魔之力。部落在通往山丘的桥梁上设置了坚固的哨所，以保卫附近的定居点。",kw={"灰谷","燃烧军团","恶魔","冥火岭","地狱火","碎木岗哨","战歌伐木营地"},ang={["class:Warlock"]="燃烧军团的地狱火坠落之处残留着原始的邪能，这使得这处伤痕累累的山脊成为了黑暗魔法研究者们眼中危险的好奇对象。",["faction:Horde"]="部落驻守在冥火岭周围的坚固桥梁上，是为了保护连接碎木岗哨与战歌伐木营地的运输道路，防止恶魔的袭击。"},sec={{t="燃烧军团留下的伤痕",b="在第三次战争那场大灾难般的入侵中，燃烧军团释放了可怕的地狱火，燃烧的陨石坠落在整个卡利姆多。其中几头炽热的庞然大物撞击了灰谷的这处山脊，摧毁了古老的林地，并腐化了这片大地。如今，这片焦灼的土地依然充斥着邪能，徘徊着在海加尔山战败后幸存下来的恶魔。"},{t="守卫通道",b="冥火岭位于碎木岗哨的东南方，战歌伐木营地的西南方，由于距离部落的重要据点过近，形势十分令人不安。因为残留的恶魔威胁着要冲出山丘，侵入周围的森林，部落军队在通往山丘的两座桥梁上修建了坚固的路障和哨塔，将这些邪恶的生物围困在它们被腐蚀的避难所内。"}},faq={{q="冥火岭为何会被腐蚀？",a="在第三次战争期间，燃烧军团的地狱火从天而降，重重地撞击在这座山丘上。撞击以及随之而来的邪能污染烧毁了原始的精灵森林，留下了伤痕累累的岩石，以及至今未曾消散的腐化恶魔能量。",al={"为什么冥火岭是绿色的","冥火岭背景故事","冥火岭发生了什么"}},{q="有哪些生物生活在冥火岭？",a="这座山丘被燃烧军团第三次战争入侵后残存的恶魔和地狱火构装体所占据。对于任何靠近它们腐化边缘的凡人，它们始终保持着敌意。",al={"冥火岭的怪物","冥火岭的敌对生物"}},{q="部落为什么要在此处加固桥梁？",a="冥火岭正好位于碎木岗哨和战歌伐木营地之间。部落指挥官加固了两座桥梁，以确保游荡的恶魔不会冲出来，从而威胁附近的营地、补给车队和伐木作业。",al={"部落在冥火岭守桥","为什么兽人在守卫冥火岭"}},{q="冥火岭与暗夜精灵有关联吗？",a="虽然这座山丘曾经是灰谷神圣森林的一部分，但它现在却以一种威胁的姿态坐落在朵丹尼尔兽穴的东北方。蔓延的邪能污染和游荡的恶魔对附近的沉睡之地及周边的荒野构成了长期的威胁。",al={"朵丹尼尔与冥火岭","兽穴恶魔"}}},fx={["1806e9cd"]={q="冥火岭是什么地方？",a="冥火岭是灰谷中部一处遭到污染的高地，位于碎木岗哨东南方、战歌伐木营地西南方。周围是葱郁的森林，这片伤痕累累的高地却成了恶魔在林中盘踞的滩头阵地。",al={"冥火岭是什么","冥火岭信息","冥火岭在哪里"}},["168acc03"]={q="冥火岭发生过什么事？",a="第三次战争期间，燃烧军团将毁灭倾泻在灰谷。冥火岭正是数个燃烧的地狱火从天而降的坠落地点。它们灼焦了大地，腐化了这片土地，使之成为残存恶魔至今盘踞的据点。",al={"冥火岭的历史","这里发生了什么","第三次战争期间的冥火岭"}},d9143043={q="冥火岭危险吗？",a="这里极其危险。敌对的恶魔遍布山岭，威胁着所有经过灰谷中部的旅人。危险之大，以至于部落积极加固通往该地区的两座桥梁，保护碎木岗哨等定居点免遭恶魔侵袭。",al={"冥火岭危险吗","冥火岭的危险","冥火岭带来的威胁"}},["4c2c069f"]={q="为什么叫冥火岭？",a="这座山岭因第三次战争期间燃烧军团的地狱火灾难性地降临而得名。地狱火带着恶魔的冥火从天而降，将地面炸得焦黑，使这片大地永久地沾染了腐化的燃烧能量。",al={"为何叫冥火岭","冥火岭名称的由来","冥火岭的名字"}}},fp="12,296,28.418.0,22.387.0,30.264.0,36.201.0,43.238.0,45.262.0"}
P.entries["subzone:felpaw-village"] = {n="魔爪村",s="魔爪村是一处位于费伍德森林最北端的腐化熊怪定居点，守卫着通往木喉要塞的山路。这里居住着堕落的死木部族，其村舍和聚集地已被恶魔的影响所玷污，对外来者怀有敌意。",h="魔爪村是一处位于费伍德森林最北端的腐化熊怪定居点，守卫着通往木喉要塞的山路。这里居住着堕落的死木部族，其村舍和聚集地已被恶魔的影响所玷污，对外来者怀有敌意。",kw={"腐化","死木","魔爪","魔爪村","费伍德森林","熊怪","木喉"},ang={["class:Druid"]="对于致力于恢复自然秩序的德鲁伊来说，魔爪村内堕落的死木熊怪是燃烧军团在神圣森林中残留剧毒的悲剧缩影。",["race:NightElf"]="暗夜精灵曾经将熊怪视为坚定的盟友，因此看到死木部族在魔爪村陷入疯狂并进行仪式性的堕落，令他们感到格外痛苦。"},sec={{t="腐化的据点",b="魔爪村位于费伍德森林的北缘，是堕落的死木熊怪主要的北部堡垒。这个部族曾经是温和的森林守护者，但在第三次战争中受到恶魔枯萎病的侵蚀，陷入了野蛮的疯狂。如今，这里已成为一处满目疮痍的飞地，到处是简陋的棚屋、祭祀图腾，以及会攻击任何在木喉要塞隧道入口附近徘徊者的敌对战士。"},{t="木喉要塞旁的荆棘",b="The proximity of Felpaw Village to the sacred entrance of Timbermaw Hold makes it a critical threat to the few uncorrupted furbolgs remaining in the region. The Timbermaw guards posted at the northern mouth of Felwood view their fallen cousins with a mixture of mourning and vigilance, frequently calling upon travelers to cull the Deadwood ranks, seize their ritual fetishes, and keep the corruption from spilling through the gates into Moonglade and Winterspring."}},faq={{q="谁住在魔爪村？",a="该定居点属于死木熊怪，这是一个完全被费伍德森林蔓延的恶魔腐化所控制的当地部族。",al={"魔爪村居民","魔爪村里有什么人","费伍德森林北部的死木熊怪"}},{q="为什么这里的熊怪怀有敌意？",a="死木熊怪被污染了费伍德森林土壤、水源和野生生物的恶魔能量彻底逼疯了。他们将所有外来者视为敌人，无法与之沟通。",al={"为什么死木熊怪会攻击","魔爪村的熊怪友好吗","为什么费伍德森林的熊怪很愤怒"}},{q="魔爪村在哪里？",a="它位于费伍德森林的最北端，就在通往木喉要塞主要南入口的道路旁。",al={"魔爪村地图位置","魔爪村在哪里","如何前往魔爪"}},{q="魔爪村与木喉要塞有何关联？",a="未受腐化的木喉部族从附近的大门密切监视着魔爪村。由于死木部族威胁到了费伍德森林、冬泉谷和月光林地之间通道的安全，木喉部族会奖励那些削减村内敌对势力并回收死木祭祀羽毛的旅行者。",al={"木喉要塞的联系","木喉要塞声望与魔爪","木喉与死木"}}},fp="14,293,26.455.0,29.465.0,28.152.0,34.187.0,32.124.0,49.295.0"}
P.entries["subzone:felstone-field"] = {n="费尔斯通农场",s="费尔斯通农场是一处位于西瘟疫之地西北部的荒废农庄。这里曾经是洛丹伦一片欣欣向荣的农田，后来被天灾军团占据，并在毁坏的土地上安放了一口不断散发着毒气的瘟疫大锅。",h="费尔斯通农场是一处位于西瘟疫之地西北部的荒废农庄。这里曾经是洛丹伦一片欣欣向荣的农田，后来被天灾军团占据，并在毁坏的土地上安放了一口不断散发着毒气的瘟疫大锅。",kw={"熔炉领主比莱莫","费尔斯通农场","詹妮斯·费尔斯通","杰瑞米·派森","洛丹伦","奥尔·艾玛","瘟疫大锅","血色十字军","西瘟疫之地"},ang={["faction:Alliance"]="对于暴风城的联盟幸存者来说，费尔斯通农场这样的地方代表着失去的祖传土地和流离失所的亲人，比如奥尔·艾玛，她一直执着于索回那份北方的破败遗产。",["race:Undead"]="这座荒废的农场不仅是一处废墟，更是被遗忘者曾经在洛丹伦生活的见证，由像杰瑞米·派森这样幸存下来的、以亡灵之躯苟活的亲属带回了记忆。"},sec={{t="荒废的农庄",b="在第三次战争之前，费尔斯通农场曾是一座和平且高产的家庭农场，为洛丹伦的公民提供粮食。当瘟疫横扫北方时，这座农庄迅速沦陷于The Cult of the Damned和天灾军团之手。如今，田地里长出的不再是庄稼，而是枯萎的杂草和蔓延的腐烂物。农场中心矗立着一口巨大的瘟疫大锅，在熔炉领主比莱莫和成群的骷髅剥皮者、巫师以及饥饿食尸鬼的看守下，不停地向天空喷吐着恶臭的烟雾。"},{t="游荡的幽灵与狂热者",b="尽管被亡灵占据，但在这个废墟中依然残留着活人的痕迹。东北边的农舍里徘徊着詹妮斯·费尔斯通的幽灵，她悲伤地游荡在她曾经的家园空壳之中。与此同时，附近的血色十字军巡逻队会在农场边界游荡，暴力清洗他们遇到的任何亡灵，同时攻击任何胆敢靠近他们势力范围的外来者。"}},faq={{q="农场中央的大锅在做什么？",a="这口大锅是天灾军团的瘟疫引擎，旨在让周围的土地和大气充满瘟疫，从而腐化土壤并复活死者。它由一名强大的天灾军团监工——熔炉领主比莱莫，以及成群的骷髅爪牙和食尸鬼看守。",al={"费尔斯通瘟疫大锅","为什么会有瘟疫大锅"}},{q="农舍里的幽灵是谁？",a="那个幽灵是詹妮斯·费尔斯通，她曾是这座农庄的女主人，在天灾军团占领此地时不幸丧生。由于不愿或无法安息，她的灵魂依然被束缚在她家族房产的废墟中。",al={"詹妮斯·费尔斯通","费尔斯通农舍的幽灵","农舍里是谁"}},{q="为什么血色十字军要在农场巡逻？",a="血色十字军经常派遣极具侵略性的突击队进入西瘟疫之地，以消灭天灾军团。他们将任何闯入的旅行者，无论是部落还是联盟，都视为潜在的瘟疫携带者或敌人，见到即展开攻击。",al={"费尔斯通的血色十字军","费尔斯通农场的十字军"}},{q="费尔斯通农场的所有权文书究竟在谁手中？",a="幽暗城的杰瑞米·派森和暴风城的奥尔·艾玛都声称他们收到了来自姐姐詹妮斯·费尔斯通的遗嘱。究竟是当初拟定了两份文书，还是瘟疫造成的混乱让这份遗产在生者与亡者亲属之间变得纠缠不清，这至今仍是一个谜。",al={"费尔斯通农场所有权文书","费尔斯通的主人","迟来总比不来好文书"}}},fp="14,254,20.508.0,28.408.1,54.264.0,38.204.0,52.246.0,45.291.1"}
P.entries["subzone:fenris-isle"] = {n="芬里斯岛",s="芬里斯岛是一座位于洛丹米尔湖中，被迷雾笼罩的大型岛屿，毗邻银松森林的东部边缘。这座岛屿曾经是洛丹伦军事要塞的所在地，如今却落入亡灵腐皮豺狼人和一名天灾军团亡灵法师的铁腕统治之下。",h="芬里斯岛是一座位于洛丹米尔湖中，被迷雾笼罩的大型岛屿，毗邻银松森林的东部边缘。这座岛屿曾经是洛丹伦军事要塞的所在地，如今却落入亡灵腐皮豺狼人和一名天灾军团亡灵法师的铁腕统治之下。",kw={"芬里斯岛","芬里斯城堡","洛丹米尔湖","腐皮豺狼人","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="被遗忘者的特工寻求协助，以调查腐皮豺狼人，并对他们在洛丹米尔湖对岸的据点发起攻击。",["race:Undead"]="对于被遗忘者而言，芬里斯岛就是自家后院中一个令人难以容忍的天灾军团堡垒，他们必须不断发动袭击，以防止图勒·鸦爪的腐皮爪牙侵占银松森林的东部水域。"},sec={{t="湖上的陷落要塞",b="在第三次战争摧毁北洛丹伦之前，芬里斯岛曾是王国的一个重要前哨站，其核心便是芬里斯城堡。当天灾军团横扫这片领域时，守军要么被屠杀，要么流亡他乡，岛屿自此荒废，沦为死者的领地。此后的岁月里，这座岛屿成为了腐皮豺狼人的据点——这群卑劣且身染瘟疫的生物在湖畔建立起了一个简陋的帝国。银松森林的被遗忘者对该岛保持着警惕，他们视这些盘踞于此的居民为对其北部领地的严重威胁。"},{t="芬里斯城堡的主人",b="腐皮豺狼人并非孤军奋战。在芬里斯城堡摇摇欲坠的石厅内，住着图勒·鸦爪，这是一名曾效力于肯瑞托的狡诈亡灵法师，后来转向了天灾军团的黑暗魔法。图勒将当地的豺狼人收归麾下，利用邪恶的巫术复活了它们死去的同类，并加固了岛屿以抵御外敌。从这个与世隔绝的避难所出发，图勒控制着湖上的渡船航线，这促使被遗忘者的侦察兵和部落部队发起先发制人的打击，以终结他对这片群岛的控制。"}},faq={{q="什么是芬里斯岛？",a="芬里斯岛是一座位于银松森林东海岸外，洛丹米尔湖中的岛屿。在第三次战争之前，它曾是洛丹伦王国的堡垒据点，但现在已经被身染瘟疫的豺狼人和天灾军团的仆从所占据。",al={"芬里斯岛在哪里","芬里斯岛背景故事","这座岛屿是什么"}},{q="目前是谁控制着芬里斯岛？",a="腐皮豺狼人占据了这座岛屿，并以芬里斯城堡为据点。被遗忘者的调查员正试图查明他们日益增长的威胁之源。",al={"谁在经营芬里斯岛","芬里斯岛首领","谁住在芬里斯岛"}},{q="过去住在这里的人类发生了什么事？",a="在第三次战争期间，随着天灾军团席卷洛丹伦，芬里斯城堡的人类守军和居民要么被杀，要么被迫驱离。这座堡垒自此荒废，直到豺狼人和亡灵法师占领了空荡荡的城墙。",al={"芬里斯城堡的人类发生了什么","谁建造了芬里斯城堡"}},{q="为什么部落有兴趣攻击这座岛屿？",a="被遗忘者认为盘踞于此的腐皮豺狼人对银松森林和附近的渡船航线构成了威胁。他们的特工正在寻求帮助，以调查并干扰岛上的敌对势力。",al={"芬里斯岛突袭背景故事","为什么部落攻击芬里斯岛","被遗忘者与芬里斯岛"}}},fx={["5a4e2fe3"]={q="芬里斯城堡为什么成了废墟？",a="芬里斯城堡曾是洛丹伦王国一处繁荣的军事要塞。第三次战争期间，天灾席卷北方诸地，城堡随之陷落。守军和居民或遭屠杀，或仓皇逃离，这座据点也因此荒废凋零，直到图勒·鸦爪和他的豺狼人占据了废墟。",al={"芬里斯岛为何被遗弃","芬里斯城堡为何成了废墟","是什么毁了芬里斯城堡"}},["115572ef"]={q="芬里斯岛危险吗？",a="芬里斯岛极其危险。岛上遍布腐皮豺狼人，由叛变法师 Thule Ravenclaw 统治。岛屿四面环绕着洛丹米尔湖阴暗浑浊的湖水，任何渡湖登岛的探险者都将面对凶猛的染病野兽，以及盘踞在破败城堡中的黑暗施法者。",al={"芬里斯岛安全吗","芬里斯岛的危险","芬里斯岛上的威胁"}}},fp="11,266,31.583.0,25.525.1,20.258.0,35.155.0,50.229.0,52.194.0"}
P.entries["subzone:fenris-keep"] = {n="芬里斯城堡",s="芬里斯城堡是一座孤立的石质要塞，坐落于洛丹米尔湖中心的芬里斯岛上。它曾经是驻扎洛丹伦军队的战略据点，如今已落入由叛变法师图勒·鸦爪领导的天灾军团手中。",h="芬里斯城堡是一座孤立的石质要塞，坐落于洛丹米尔湖中心的芬里斯岛上。它曾经是驻扎洛丹伦军队的战略据点，如今已落入由叛变法师图勒·鸦爪领导的天灾军团手中。",kw={"芬里斯岛","芬里斯城堡","洛丹伦","洛丹米尔湖","烂皮","天灾军团","银松森林","图勒·鸦爪"},ang={["class:Mage"]="芬里斯城堡的主人图勒·鸦爪是肯瑞托教义遭到背叛的阴森代表，他将达拉然的奥术知识扭曲成了天灾军团的黑暗技艺。",["faction:Horde"]="对于部落——尤其是被遗忘者来说——芬里斯城堡代表着一个必须被根除的残留天灾据点，以保卫银松森林和洛丹米尔湖的水域。"},sec={{t="洛丹米尔湖上的天灾军团",b="如今，芬里斯城堡是鸦爪权力的中心，也是对正在巩固银松森林的被遗忘者的迫切威胁。图勒从这座堡垒中指挥着大批烂皮豺狼人，凶残地攻击任何胆敢踏上该岛的人。由于芬里斯岛距离提瑞斯法林地的边界仅有几英里水路之隔，瑟伯切尔和幽暗城的被遗忘者们不断派遣勇士去摧毁城堡的防御，并终结这位叛变死灵法师的生命。"},{t="洛丹伦的一座陷落堡垒",b="在第三次战争之前，芬里斯城堡对洛丹伦王国具有战略重要性，驻扎着一支庞大的军队来保卫洛丹米尔湖。当亡灵天灾军团席卷大地时，这座岛屿要塞同王国其他地区一样被攻陷了。它没有沦为被遗忘的废墟，而是被前肯瑞托法师、叛徒图勒·鸦爪所占据。鸦爪与天灾军团结盟，利用邪恶的死灵法术奴役了当地的豺狼人，创造了贪婪的烂皮氏族，并固守在城堡的石厅深处。"}},faq={{q="什么是芬里斯城堡？",a="芬里斯城堡是一座位于洛丹米尔湖中芬里斯岛上的坚固石堡。它曾是陷落的洛丹伦王国的军事据点，目前由亡灵天灾军团把守。",al={"芬里斯城堡背景","什么是芬里斯城堡","芬里斯城堡"}},{q="谁现在统治着芬里斯城堡？",a="这座城堡由图勒·鸦爪统治，他曾是一名肯瑞托法师，背叛了生者转而效忠天灾军团。他在要塞内指挥着一支受亡灵瘟疫感染的烂皮豺狼人大军。",al={"谁控制着芬里斯城堡","芬里斯城堡首领","芬里斯岛主人"}},{q="为什么芬里斯城堡里有豺狼人？",a="当地的豺狼人种群被图勒·鸦爪通过黑暗魔法和疾病所奴役，被扭曲成了烂皮豺狼人。他们成为了鸦爪在城堡和周边岛屿上忠诚的突击部队和守卫。",al={"芬里斯烂皮豺狼人","为什么城堡里有豺狼人","芬里斯豺狼人"}},{q="为什么被遗忘者关心芬里斯城堡？",a="芬里斯城堡为天灾军团提供了洛丹米尔湖上的一个可防御基地，直接威胁到被遗忘者在银松森林东部和提瑞斯法林地的行动。希尔瓦娜斯的军队不能放任一位活跃的天灾指挥官在他们的边界附近而不加理会。",al={"为什么被遗忘者攻击芬里斯","被遗忘者芬里斯城堡","幽暗城芬里斯"}}},fx={c58313a0={q="芬里斯城堡发生了什么？",a="芬里斯城堡曾具有极高的战略价值，洛丹伦王国军队曾在洛丹米尔湖中的这座城堡驻扎了相当规模的守军。第三次战争席卷大地时，天灾军团攻占了这座要塞。它没有得到净化，反而落入 Thule Ravenclaw 手中。这位肯瑞托叛逃法师投靠了巫妖王，并将当地的豺狼人部族变成了贪婪嗜血的亡灵爪牙。",al={"芬里斯城堡历史","芬里斯城堡发生了什么","芬里斯城堡背景"}},["07ecc870"]={q="芬里斯城堡为何沦为废墟？",a="第三次战争期间，天灾军团摧毁了洛丹伦的防线，芬里斯城堡也因此沦为废墟。曾经维护这座要塞的守军惨遭屠戮，城堡建筑从此无人照料，逐渐腐朽。如今，这里已是一座衰败的据点，被通晓通灵魔法的势力和凶残食肉的豺狼人所盘踞。",al={"芬里斯城堡为何被遗弃","是谁摧毁了芬里斯城堡","芬里斯城堡废墟"}},["6ae37309"]={q="芬里斯城堡危险吗？",a="这里极其危险。城堡和周围的岛屿上爬满了腐皮豺狼人，它们会饥肠辘辘地袭击任何踏上岸边的人。城堡内部则盘踞着危险的通灵师 Thule Ravenclaw，他以黑暗魔法操纵着自己的怪物仆从。",al={"芬里斯城堡的危险","芬里斯城堡安全吗","芬里斯城堡有多危险"}}},fp="11,235,24.473.1,29.591.1,20.194.0,32.187.1,40.238.1,43.262.0"}
P.entries["subzone:feral-scar-vale"] = {n="深痕谷",s="深痕谷是一处坐落在菲拉斯西部高原荒野中的岩石峡谷。这里被领地意识极强的深痕雪人所占据，其洞穴隧道对于那些离开杂草丛生的森林小径的旅人来说，是出了名的危险之地。",h="深痕谷是一处坐落在菲拉斯西部高原荒野中的岩石峡谷。这里被领地意识极强的深痕雪人所占据，其洞穴隧道对于那些离开杂草丛生的森林小径的旅人来说，是出了名的危险之地。",kw={"深痕谷","菲拉斯","高原荒野","追踪机器人","oox-22/fe","雪人"},ang={["class:Hunter"]="在这些悬崖间潜行的庞大深痕雪人，对于在高原荒野茂密树冠下进行荒野追踪和大型猎物狩猎的探险者来说，是一项严峻的考验。",["profession:Engineering"]="在雪人的隧道深处藏着一个被困的侏儒追踪机器人，需要工程师的巧手和一个紧急信标才能将其安全送回文明世界。"},sec={{t="雪人之巢",b="深痕谷坐落在高原荒野茂密的植被和陡峭的悬崖之间，是野蛮的深痕雪人的主要巢穴。虽然雪人在奥特兰克和丹莫罗的雪山峰顶很常见，但这些原始的野兽已经完全适应了菲拉斯野外潮湿的气候。它们凶猛地保卫着山谷的洞穴网络，囤积着骨头作为战利品，并会积极驱逐任何误入它们狩猎区域的入侵者。"},{t="洞穴中的奇闻",b="除了雪人带来的原始危险外，深痕谷的深处还隐藏着意想不到的奇事。侏儒工程学的求救信号偶尔会被追踪到这些黑暗的洞穴中，迷失的勘探设备——比如被困的机械侦察鸡——最终被这些凶猛的野兽所困，等待着被激活和回收。"}},faq={{q="深痕谷里居住着什么样的生物？",a="深痕谷主要由深痕雪人统治，它们是体型巨大且领地意识极强的顶级掠食者，在岩石洞穴内筑巢并巡视周围的森林。",al={"深痕谷怪物","深痕谷里有什么","深痕谷生物"}},{q="深痕谷位于哪里？",a="深痕谷位于菲拉斯西部，坐落在被称为高原荒野的区域内，穿过雨林树冠的主干道南侧。",al={"深痕谷位置","深痕谷在哪里","如何找到深痕谷"}},{q="为什么茂密的雨林里会有雪人？",a="虽然雪人通常与雪山联系在一起，但卡利姆多古老而未被驯服的荒野中存在着独特的亚种，例如深痕雪人，它们已经在茂密的森林山谷中繁衍了数代。",al={"为什么菲拉斯有雪人","雨林雪人","菲拉斯雪人背景故事"}},{q="洞穴里的机械鸡是什么？",a="在山谷深处的一个洞穴中，躺着追踪机器人OOX-22/FE，这是一种由侏儒工程师制造的自动机械侦察鸡，它坠毁并被困在了雪人的防线后方。",al={"oox-22/fe","菲拉斯机械鸡","深痕谷追踪机器人"}}},fp="15,232,17.450.0,24.355.0,47.148.0,33.158.0,41.215.0,47.187.0"}
P.entries["subzone:field-of-giants"] = {n="巨人旷野",s="巨人旷野是一片广阔的平原，覆盖了贫瘠之地南部，位于陶拉祖营地和尘泥沼泽之间。这里因栖息着高大的科多兽、雷蜥以及其他在这片干旱灌木丛中游荡的巨型野兽而得名。最近，随着其希利苏丹虫群的入侵，该地区变得愈发危险。",h="巨人旷野是一片广阔的平原，覆盖了贫瘠之地南部，位于陶拉祖营地和尘泥沼泽之间。这里因栖息着高大的科多兽、雷蜥以及其他在这片干旱灌木丛中游荡的巨型野兽而得名。最近，随着其希利苏丹虫群的入侵，该地区变得愈发危险。",kw={"贫瘠之地","陶拉祖营地","巨人旷野","黄金之路","科多兽","科兰","鲁迦·狂暴图腾","希利苏丹","雷蜥"},ang={["class:Hunter"]="成群游荡的雷蜥和巨大的科多兽使巨人旷野成为贫瘠之地中寻求强大野兽的猎人们的首选狩猎场。",["faction:Horde"]="在陶拉祖营地和尘泥沼泽之间的道路附近出现的希利苏丹巢穴威胁到了旅行路线，促使贫瘠之地各处的领导者纷纷征召侦察兵。"},sec={{t="南方的荒野前线",b="巨人旷野沿着黄金之路的南段延伸，与北部的贫瘠之地相比，这里偏远、荒凉且防御薄弱。虽然道路上的木制岗哨大多已被废弃，但这片土地本身却生机勃勃。成群的卡利姆多巨型动物游荡在广阔的平原上，吸引了猎人和博物学家。然而，在这里安全是奢望：来自巴尔莫丹的矮人挖掘者正在南方大肆挖掘，而一种更加邪恶的威胁也开始在地底掘进。"},{t="蔓延的虫群",b="近来，昆虫般的希利苏丹巢穴在巨人旷野各处破土而出，这是人们在卡利姆多已知的最靠北的一次发现这种贪婪生物的踪迹。这些奇怪的土丘和极具攻击性的虫群引起了部落的警觉。来自十字路口的巨魔侦察兵科兰以及陶拉祖营地的牛头人战士鲁迦·狂暴图腾等人都敦促冒险者深入探查这些巢穴，试图找出是什么将这些地底恐怖生物吸引到距离深沙漠如此遥远的地方。"}},faq={{q="为什么这里被称为巨人旷野？",a="这片平原因其游荡的野生动物的巨大体型而得名。成群的高大科多兽和雷蜥在这里觅食，与巨大的卡利姆多野生动物一起统治着这片土地。",al={"巨人旷野名字由来","为何叫巨人旷野"}},{q="地里那些虫子堆是什么？",a="那是希利苏丹巢穴。这些昆虫捕食者从深层地下挖掘而出，形成了在卡利姆多发现的最靠北的巢穴。它们的突然出现对过往的旅行者和当地的野生动物构成了严重威胁。",al={"贫瘠之地的虫穴","南贫瘠之地的昆虫","希利苏丹是什么"}},{q="谁居住在巨人旷野附近？",a="平原本身几乎没有定居点，但有一些重要人物在监视着它的边界。牛头人萨满布莱恩住在一座南部的山脊上，而被放逐的流亡者加恩·石塔则在附近观察，密谋对抗巴尔莫丹的矮人挖掘场。",al={"谁住在这里","巨人旷野的非玩家角色"}},{q="为什么路边的岗哨被废弃了？",a="部落的军事力量主要集中在黄金之路北部围绕十字路口的区域。最南端的区域巡逻较少，使得这些岗哨在希利苏丹和具有攻击性的野生动物的威胁下被荒废了。",al={"黄金之路废弃塔楼","南贫瘠之地岗哨"}}},fx={c3e59f7c={q="什么是巨人旷野？",a="巨人旷野是南贫瘠之地的一片广阔区域，位于陶拉祖营地与通往尘泥沼泽的道路之间。黄金之路的南段横贯这片烈日炙烤的平原。这里以成群出没的雷霆蜥蜴、科多兽和其他卡利姆多巨兽而闻名。",al={"巨人旷野概况","巨人旷野是什么地方","关于巨人旷野"}},["2ebbbb7d"]={q="巨人旷野有什么历史？",a="巨人旷野长期以来一直是卡利姆多巨型野兽的荒野栖息地。过去，黄金之路南段沿线经常有人巡逻，后来防御塔逐渐失修。近来，硅酸虫群不断侵入，在地下挖掘出巨大的巢穴，使这片土地变得动荡不安。附近巴尔莫丹的矮人挖掘者还驱逐了加恩·石塔的族人等当地部族。",al={"巨人旷野历史","巨人旷野发生了什么","巨人旷野往事"}},b9c947c6={q="巨人旷野危险吗？",a="这里相当危险。除了在平原上横冲直撞的高大凶猛雷霆蜥蜴和成群科多兽，近期还有一处凶险的硅酸虫巢从红土之下涌现。沿黄金之路南段旅行的旅人几乎无处躲避，因为当地的瞭望塔空无一人，无人守卫。",al={"巨人旷野的危险","巨人旷野有多危险","这里安全吗"}}},fp="15,307,28.517.0,18.478.0,37.206.0,40.231.0,35.247.0,49.253.0"}
P.entries["subzone:fire-plume-ridge"] = {n="火羽山",s="火羽山是直接从安戈洛环形山中心耸起的一座活火山。它灼热的山坡和地下的岩浆通道为环形山的喷泉和蒸汽池提供了热源，同时这里也栖息着凶猛的火元素。",h="火羽山是直接从安戈洛环形山中心耸起的一座活火山。它灼热的山坡和地下的岩浆通道为环形山的喷泉和蒸汽池提供了热源，同时这里也栖息着凶猛的火元素。",kw={"布莱泽瑞恩","元素","火羽山","熔岩","林格","安戈洛","火山"},ang={["class:Shaman"]="火之精魂在山脊上狂暴地燃烧着，让我们得以一窥在卡利姆多地壳下涌动的躁动元素力量。",["profession:Mining"]="山脊的峭壁和经受过高温淬炼的山坡上富含裸露的矿石，尤其是由火山压力形成的致密瑟银矿脉。"},sec={{t="环形山之心",b="火羽山耸立在安戈洛原始盆地的上方，与周围郁郁葱葱的丛林形成了鲜明的对比。熔岩源源不断地从焦黑的岩壁上倾泻而下，雕刻出一片灰烬与玄武岩交织的地貌。地下的岩浆脉络从山脊下方像蜘蛛网一样向外延伸，为遍布盆地的喷泉和温泉提供热量。这里的酷热令人闻之色变——根据地精测量装置的记录，这里的温度远超普通火山——如果探险者没有充足的水源和遮蔽，贸然前往将会非常危险。"},{t="元素巢穴",b="这座火山是一座充满了活焰的元素熔炉。活体火花和游荡的火元素在灼热的岩浆流中巡逻，被纯粹的地底热能所吸引。在火山顶峰附近的一个洞穴深处，居住着布莱泽瑞恩，它是安戈洛元素生物中无可争议的主宰。登上山脊意味着既要应对致命的高温，又要面对那些拼死捍卫其炽热领地的狂暴元素之灵。"}},faq={{q="安戈洛环形山中央的火山是什么？",a="那是火羽山，一座位于安戈洛环形山中心地带的活火山。它的熔岩通道所产生的热量温暖了周围的丛林和蒸汽泉。",al={"安戈洛火山名称","安戈洛中央的火山","火羽山位置"}},{q="谁统治着火羽山的元素？",a="峰顶洞穴中居住着布莱泽瑞恩，它是安戈洛环形山中最强大的火元素。",al={"火羽山首领","布莱泽瑞恩位置","安戈洛火元素首领"}},{q="为什么有一名探险者被困在山脊里？",a="一名名为林格的地精盟友探险者在前往火山探险时，因严重的中暑昏倒在南部的一个洞穴中，无法在没有帮助的情况下逃脱。",al={"谁被困在火羽山","林格 安戈洛","火山中失踪的人"}},{q="这座火山是如何影响安戈洛其余地区的？",a="浅层的岩浆脉络从火羽山下方延伸至整个环形山底部，温暖了大地，并形成了遍布整个盆地的无数喷泉、热气孔和蒸汽池。",al={"为什么安戈洛这么热","环形山地热活动","安戈洛浅层岩浆脉"}}},fp="16,228,24.574.0,19.446.0,52.167.0,45.96.0,51.187.0,48.205.0"}
P.entries["subzone:fire-scar-shrine"] = {n="火痕神殿",s="火痕神殿是一座位于灰谷西南部森林中的受损暗夜精灵神殿。它曾经是一处宁静的礼拜场所，如今却已被恶魔力量腐化，变成了一个位于阿斯特兰纳家门口的邪能疮痍。",h="火痕神殿是一座位于灰谷西南部森林中的受损暗夜精灵神殿。它曾经是一处宁静的礼拜场所，如今却已被恶魔力量腐化，变成了一个位于阿斯特兰纳家门口的邪能疮痍。",kw={"阿克里鲁斯","灰谷","阿斯特兰纳","阿斯瑞克斯·纳拉辛","黑暗之潮教派","火痕神殿","伊尔库德·玛格鲁尔","暗影议会"},ang={["class:Warlock"]="此处的邪能伤痕和肆虐的恶魔召唤，清晰地标志着暗影议会在整个卡利姆多的隐秘渗透。",["race:NightElf"]="火痕神殿的亵渎是离阿斯特兰纳如此之近的一记苦涩耳光，必须对任何玷污森林的恶魔入侵者施以迅猛的报复。"},sec={{t="森林中的枯萎",b="火痕神殿位于阿斯特兰纳西南方、星尘废墟西侧，它是燃烧军团在灰谷遗留毒害的一个严酷警示。神殿已堕入恶魔腐化之中，在黑暗之潮教派和暗影议会仆从的滋养下越陷越深。邪能魔法将周围的土地扭曲成焦灼的岩石，游荡的恶魔在这里公然藐视森林的守卫者。"},{t="黑暗之潮的阴影",b="神殿坠入黑暗的始作俑者是诸如兽人术士伊尔库德·玛格鲁尔之类的代理人，他们听命于阿斯瑞克斯·纳拉辛。尽管凡人术士带来了腐化，但如今召唤出的恶魔正在毫无阻碍地巡视着祭坛石。位面裂隙的局部撕裂偶尔会引来更大的恐怖，包括高大的末日守卫阿克里鲁斯。"}},faq={{q="火痕神殿位于哪里？",a="火痕神殿位于灰谷西南部，就在暗夜精灵枢纽阿斯特兰纳的西南方、艾森娜神殿的南面，以及星尘废墟的正西面。",al={"火痕神殿位置","火痕神殿在哪里","火痕神殿地图"}},{q="为什么火痕神殿会有恶魔？",a="这座神殿受到了暗影议会和黑暗之潮教派代理人的渗透和腐化，尤其是兽人术士伊尔库德·玛格鲁尔。他们的黑暗仪式召唤了恶魔，并使这片神圣的土地充斥着挥之不去的邪能污秽。",al={"为什么有恶魔","是什么腐化了火痕神殿","谁召唤了恶魔"}},{q="阿克里鲁斯是谁？",a="阿克里鲁斯是一个强大的末日守卫，偶尔会出现在火痕神殿周围，被腐化的石头周围汇聚的强烈恶魔能量所吸引。",al={"阿克里鲁斯","火痕的末日守卫","火痕神殿稀有恶魔"}},{q="这个地方与黑暗之潮教派有什么联系？",a="在这里活动的兽人术士伊尔库德·玛格鲁尔效忠于黑暗之潮教派的首领阿斯瑞克斯·纳拉辛。他们将神殿作为据点，进行恶魔召唤并实施他们在灰谷的黑暗野心。",al={"火痕黑暗之潮教派","黑暗之潮联系","火痕阿斯瑞克斯·纳拉辛"}}},fx={["2cfd3821"]={q="什么是火痕神殿？",a="火痕神殿是一处遭到腐化的圣地，坐落在灰谷西南部，位于阿斯特兰纳西南方、星尘废墟正西方。它曾是古老森林中的宁静圣所，如今却在黑暗的恶魔势力影响下沦为邪恶废墟。",al={"火痕神殿背景","这座神殿是什么","灰谷的火痕神殿"}},["45677f07"]={q="火痕神殿为何沦为废墟并遭到腐化？",a="这座神殿落入了暗影议会及其凡人爪牙——黑暗海岸教派的邪恶阴谋之中。他们的仪式腐化了圣所，使其失去自然的祥和，变成了恶魔力量盘踞的疫病据点。",al={"火痕神殿为何沦为废墟","火痕神殿为何遭到腐化","是什么毁了火痕神殿"}},["81dc8561"]={q="火痕神殿有多危险？",a="这里极其危险。神殿区域遍布黑暗召唤者留下的凶猛恶魔；有时，恐惧魔王卫 Akkrilus 也会现身，猎杀任何胆敢靠近的旅人。",al={"火痕神殿危险吗","火痕神殿的威胁","火痕神殿的危险"}}},fp="16,241,22.447.0,26.372.0,34.181.0,41.238.0,16.163.0,68.226.1"}
P.entries["subzone:firewatch-ridge"] = {n="观火岭",s="观火岭是灼热峡谷北部的一处高耸火山悬崖，是黑铁矮人的主要营地。由于直接俯瞰着被称为大熔炉的巨大挖掘场，该山脊有着由矮人哨兵、机械傀儡和筑巢的火焰蜘蛛严密把守。在西北方，一个阴森的洞穴系统揭示了暮光之锤教派的根深蒂固。",h="观火岭是灼热峡谷北部的一处高耸火山悬崖，是黑铁矮人的主要营地。由于直接俯瞰着被称为大熔炉的巨大挖掘场，该山脊有着由矮人哨兵、机械傀儡和筑巢的火焰蜘蛛严密把守。在西北方，一个阴森的洞穴系统揭示了暮光之锤教派的根深蒂固。",kw={"大熔炉","黑铁部族","观火岭","火焰蜘蛛","傀儡","灼热峡谷","暮光之锤"},ang={["race:Dwarf"]="对于铁炉堡的矮人来说，观火岭冷酷地提醒着他们，黑铁部族的同胞在黑石山的阴影下，有着根深蒂固的恶意、钢铁工业和黑暗联盟。"},sec={{t="焦灼的制高点",b="Perched above the industrial devastation of the Cauldron, Firewatch Ridge functions as a critical staging ground for the Dark Iron clan's operations in Searing Gorge. Dwarven guards, engineers, and molten golem creations patrol the crags, fiercely defending their foothold alongside venomous flame spiders native to the smoldering rocks. Its elevation provides the Dark Irons an unobstructed view of the surrounding ash plains, ensuring early warning against rival incursions from Ironforge or the Thorium Brotherhood."},{t="邪教的阴影",b="隐藏在山脊西北部的是一个被暮光之锤占据的地下洞穴网络。这些邪教徒在黑铁营地的阴影下活动，在岩层下方进行黑暗仪式并藏匿着强大的精英狂热者。他们靠近黑铁矮人的基础设施和黑石山，反映出元素和末日教派在灼热峡谷这个火热核心地带无孔不入、阴险狡诈的触角。"}},faq={{q="观火岭是什么地方？",a="观火岭是灼热峡谷中一处隆起的山脊，黑铁矮人在此建立了主要营地，俯瞰着大熔炉挖掘场。",al={"这是什么地方","观火岭信息","观火岭概览"}},{q="观火岭有哪些敌人？",a="山脊上盘踞着敌对的黑铁矮人、机械傀儡和本土的火焰蜘蛛，而西北部的洞穴系统则被暮光之锤教派的精英成员所占据。",al={"这里有哪些怪物","观火岭敌人","观火岭威胁"}},{q="暮光之锤为什么在这里？",a="暮光之锤教派在山脊的西北洞穴中扎根，是为了在靠近黑石山和该地区被束缚的火元素的地方，进行他们的元素崇拜和末日仪式。",al={"观火岭的暮光之锤","洞穴里的邪教徒","观火岭西北洞穴"}},{q="观火岭与大熔炉有什么关系？",a="观火岭直接坐落在大熔炉之上，为黑铁矮人提供了一个坚固的有利位置，以监督采矿作业并防御针对他们矿场的潜在袭击。",al={"观火岭与大熔炉","俯瞰大熔炉","为什么俯瞰大熔炉"}}},fp="15,407,24.518.0,22.461.0,24.153.0,37.195.0,34.235.0,48.191.0"}
P.entries["subzone:flame-crest"] = {n="烈焰峰",s="烈焰峰是一处崎岖的中立哨站，坐落在燃烧平原火山荒地之上的一处岩架顶端。这座险要的营地只能通过一座简陋的桥梁进入，它是针对盘踞在黑石山中的黑石氏族的先遣阵地。它提供了至关重要的空中连接，也是侦察兵、野兽收集者和战略家的避风港。",h="烈焰峰是一处崎岖的中立哨站，坐落在燃烧平原火山荒地之上的一处岩架顶端。这座险要的营地只能通过一座简陋的桥梁进入，它是针对盘踞在黑石山中的黑石氏族的先遣阵地。它提供了至关重要的空中连接，也是侦察兵、野兽收集者和战略家的避风...",kw={"黑石氏族","燃烧平原","伊崔格","烈焰峰","飞行路线","基布勒","奥普斯","双足飞龙"},ang={["faction:Horde"]="烈焰峰为部落旅客提供了双足飞龙连接，以及燃烧平原北部的一个受保护的中立营地。",["race:Orc"]="对于效忠萨尔的兽人来说，这个营地是一个俯瞰黑石氏族的观测点，黑石氏族的出现玷污了这座山脉。"},sec={{t="险要的栖身之所",b="烈焰峰位于一处孤立的岩石突出部高处，可以俯瞰燃烧平原焦黑的灰烬和熔岩平原。这座哨站只能通过一座狭窄、摇摇欲坠的木桥到达，在对抗荒地中潜伏的野兽和游荡的兽人战帮时具有天然的防御优势。双足飞龙在峭壁上筑巢，将营地与穿过红脊山脉的卡加斯、斯通纳德、瑟银哨塔，以及河林的洛格玛连接起来。"},{t="黑石之影",b="烈焰峰不仅仅是一个双足飞龙栖息地，它还是监视盘踞在黑石塔内的黑石氏族的关键前哨站。在这里，深入敌方领地，侦察兵们收集情报，制定计划以击溃叛变的黑石氏族，并与附近的洞穴中像宠物训练师基布勒这样古怪的独行者进行交易。"}},faq={{q="什么是烈焰峰？",a="烈焰峰是燃烧平原的一处中立营地。它建在仅能通过一座简陋桥梁到达的狭窄岩石突出部之上，为这片致命的区域提供了飞行路线连接、侦察庇护所和补给。",al={"烈焰峰概览","什么是烈焰峰","燃烧平原部落营地"}},{q="烈焰峰的飞行管理员飞往哪里？",a="烈焰峰的双足飞龙栖息地维持着前往荒芜之地的卡加斯、悲伤沼泽的斯通纳德、灼热峡谷中瑟银哨塔的中立补给站，以及河林的洛格玛的直飞空中航线。",al={"烈焰峰飞行点","烈焰峰飞行路线","烈焰峰连接地点"}},{q="部落为什么要在燃烧平原维持一个哨站？",a="烈焰峰与其说是部落要塞，不如说是一个中立营地，尽管其双足飞龙搭载部落旅客。它的高处位置可以俯瞰盘踞在黑石山中的黑石氏族。黑石氏族公然藐视萨尔大酋长，对该地区构成了直接威胁，因此设立一个当地的观测点至关重要。",al={"部落为何在燃烧平原","烈焰峰的作用","部落在烈焰峰的任务"}},{q="谁住在烈焰峰的洞穴里？",a="岩架后方的洞穴是基布勒和他那只喋喋不休的鹦鹉奥普斯的家。基布勒是一位古怪的驯养师，对栖息在周围荒地和黑石塔中的稀有且危险的野生动物很感兴趣。",al={"基布勒的洞穴","谁在烈焰峰的洞穴里","烈焰峰的鹦鹉"}},{q="伊崔格在烈焰峰做什么？",a="伊崔格并不驻扎在烈焰峰。这位老兵兽人侍奉在奥格瑞玛的萨尔大酋长身边，而烈焰峰依然是供商人、侦察兵和监视黑石氏族的双足飞龙使用的中立中转站。",al={"燃烧平原的伊崔格","为什么伊崔格在烈焰峰","阿瑞克和伊崔格"}}},fp="11,376,18.464.0,19.328.0,20.229.0,48.223.0,63.309.0,37.222.0,37.216.0"}
P.entries["subzone:foothold-citadel"] = {n="塞拉摩堡垒",s="塞拉摩堡垒是塞拉摩岛上的中央军营和指挥所。它俯瞰着这座防御森严的定居点，驻扎着保卫联盟在卡利姆多南部主要堡垒的军官和卫兵。",h="塞拉摩堡垒是塞拉摩岛上的中央军营和指挥所。它俯瞰着这座防御森严的定居点，驻扎着保卫联盟在卡利姆多南部主要堡垒的军官和卫兵。",kw={"军营","戴林·普罗德摩尔","尘泥沼泽","塞拉摩堡垒","盖兰·维米斯","古斯塔夫·范沃森","samaul","塞拉摩"},ang={["faction:Alliance"]="这座堡垒是联盟在卡利姆多南部的首要军事支柱，负责协调针对沼泽野兽、恐怖图腾掠夺者和警惕的部落斥候的防御。",["faction:Horde"]="对于部落来说，塞拉摩堡垒被铭记为雷克萨和萨尔终结普罗德摩尔海军上将复仇远征的地方，这一战确保了杜隆塔尔的生存。"},sec={{t="塞拉摩卫队的中心",b="塞拉摩堡垒耸立在塞拉摩岛坚固的石墙之内，是当地联盟防御体系的核心。这座堡垒驻扎着塞拉摩卫队的高级指挥部，包括盖兰·维米斯队长和指挥官Samaul，以及野战军医、后勤军官和军需官。其实用的石质大厅里经常有巡逻队和演习，使吉安娜·普罗德摩尔的部队时刻准备着应对从周围沼泽地中潜出的威胁。"},{t="海军上将陨落的回响",b="这座堡垒承载着与塞拉摩建立初期相关的沉重历史。当戴林·普罗德摩尔海军上将夺取了城市的控制权，并对部落发动他个人的远征时，这座堡垒成为了他最后决战的战场。萨尔的联军突击队在半食人族战士雷克萨的带领下攻破了堡垒，并将这位海军上将击倒。今天，这座堡垒已经修复并屹立不倒，尽管那场血腥冲突的记忆仍笼罩在其石制城墙之上。"}},faq={{q="塞拉摩堡垒的用途是什么？",a="塞拉摩堡垒是塞拉摩卫队的指挥部和军营。它驻扎着指挥官、战术规划人员、训练设施以及像当地军饷官和医务人员这样的后勤人员。",al={"塞拉摩堡垒用途","塞拉摩军营","这是什么建筑"}},{q="戴林·普罗德摩尔海军上将在这里发生了什么？",a="在第三次战争后的冲突中，戴林·普罗德摩尔海军上将征用了塞拉摩，对年轻的部落发动了战争。由勇士雷克萨率领的联军突袭了这座堡垒，在海军上将自己的指挥部里将其击杀。",al={"戴林之死","戴林·普罗德摩尔的最后决战","谁杀死了戴林"}},{q="塞拉摩堡垒目前由谁负责？",a="驻军的作战指挥权由盖兰·维米斯队长和指挥官Samaul等军官负责，他们在吉安娜·普罗德摩尔的最高授权下监督日常巡逻和区域安全。",al={"谁领导堡垒","塞拉摩卫队指挥官","堡垒领导者"}},{q="我能在堡垒内获得医疗援助吗？",a="可以。古斯塔夫·范沃森医生居住在塞拉摩堡垒内，照料受伤的卫兵，并向联盟的旅行者传授先进的野战医疗和分诊知识。",al={"堡垒医生","塞拉摩军医","塞拉摩急救训练师"}}},fp="16,233,28.476.0,28.502.0,34.229.0,54.241.0,47.204.0,45.164.0"}
P.entries["subzone:forest-s-edge"] = {n="林边空地",s="林边空地是艾尔文森林西南部边界上的一块林地，两侧河流流向西部荒野。该地区北临西泉要塞，但这片蛮荒之地已变得极其危险，被臭名昭著的霍格率领的河爪豺狼人所占据。",h="林边空地是艾尔文森林西南部边界上的一块林地，两侧河流流向西部荒野。该地区北临西泉要塞，但这片蛮荒之地已变得极其危险，被臭名昭著的霍格率领的河爪豺狼人所占据。",kw={"艾尔文森林","林边空地","豺狼人","霍格","纳斯菲尔提河","河爪","西泉要塞"},ang={["faction:Alliance"]="对于驻扎在艾尔文森林的新兵来说，清理林边空地并击败霍格是证明其战斗力、效忠王国的首批重大考验之一。",["profession:Herbalism"]="林边空地宁静的河岸和阴凉的树林里盛产常见的林地草药，但采集它们往往需要躲避好斗的豺狼人巡逻队。"},sec={{t="充满纷争的边境",b="林边空地坐落在暴风城西南方，介于明镜湖果园与通往西部荒野的河流之间，形成了一片天然的林地半岛。尽管它毗邻西泉要塞，但暴风城军队兵力不足，使得该地区极易受到野兽和劫掠小队的侵扰。游荡的野猪在树林和河岸边徘徊，但真正的威胁是那些将此地作为据点的河爪豺狼人。"},{t="霍格的据点",b="林边空地的树林是霍格的狩猎场，他是一位体型巨大、残暴嗜血的豺狼人首领。暴风城军队为他悬赏了高额赏金，霍格指挥着他的爪牙骚扰路人、劫掠附近的农场，将这片原本宁静的林地变成了年轻的联盟冒险者们致命的试炼场。"}},faq={{q="林边空地具体在哪里？",a="林边空地位于艾尔文森林的西南角。它在西泉要塞的南面，毗邻明镜湖果园和通往西部荒野的水路。",al={"林边空地位置","林边空地在哪里","林边空地地图"}},{q="为什么这个地区如此危险？",a="一大群极具攻击性的河爪豺狼人占据了这片树林，威胁着西南边境的通行安全。最大的威胁是他们的首领霍格，这是一个在林间四处游荡、极其凶残的豺狼人。",al={"为什么林边空地危险","林边空地有什么","林边空地的威胁"}},{q="霍格是谁？",a="霍格是一位臭名昭著且强大的豺狼人领袖，应对艾尔文森林边界的暴力袭击负责。暴风城军队已悬赏巨额奖金征集他死亡的证明，并警告冒险者不要独自面对他。",al={"霍格背景故事","霍格是谁","霍格信息"}},{q="为什么西泉要塞没有清理该地区？",a="暴风城的兵力在王国各地捉襟见肘。随着西部荒野的动荡和四面八方涌来的威胁，要塞缺乏足够的人手来清理豺狼人营地，只能将这项任务留给志愿冒险者。",al={"为什么西泉要塞不进行清理","为什么暴风城卫兵不帮忙","西泉要塞卫兵"}}},fx={["898568c8"]={q="谁住在林边空地？",a="林边空地已完全落入凶恶豺狼人的手中。在怪物般的豺狼人霍格的残暴统治下，这些劫掠者占据了林地与河岸。当地的野生动物大多是四处游荡的野猪，如今也与这些徘徊的豺狼人群共享这片空地。",al={"这里住着谁","林边空地的居民","林边空地里有谁"}},["61fe669f"]={q="为什么这里叫林边空地？",a="这片区域构成了艾尔文森林的西南边界，茂密林地在此渐渐过渡为纳泽费提河，以及通往西部荒野的开阔平原。它紧邻河岸与果园，自然成为森林的边缘，也标志着旅人即将踏入更险恶的土地。",al={"为什么叫林边空地","林边空地名称含义","为何叫林边空地"}}},fp="13,287,20.464.0,19.341.0,31.181.0,30.221.0,14.212.0,47.232.0"}
P.entries["subzone:forest-song"] = {n="林歌神殿",s="林歌神殿是位于灰谷东北部的一处古老的暗夜精灵遗迹，靠近受腐蚀的萨提纳尔森林和大树荫处的宏伟传送门。目前，这里除了时刻保持警惕的德鲁伊凯内斯·静风外，几乎空无一人，他在此守卫着东部边境，抵御随时可能出现的威胁。",h="林歌神殿是位于灰谷东北部的一处古老的暗夜精灵遗迹，靠近受腐蚀的萨提纳尔森林和大树荫处的宏伟传送门。目前，这里除了时刻保持警惕的德鲁伊凯内斯·静风外，几乎空无一人，他在此守卫着东部边境，抵御随时可能出现的威胁。",kw={"灰谷","大树荫","灰谷东部","林歌神殿","卡多雷遗迹","凯内斯·静风","萨提纳尔"},ang={["class:Druid"]="凯内斯·静风的默默坚守，彰显了塞纳里奥议会在受腐蚀的边境地区那孤独的守望，他正位于大树荫的世界之树下，那片被阴影笼罩的树冠之下。",["faction:Alliance"]="林歌神殿是联盟冒险者穿越灰谷东北部前往艾萨拉或费伍德森林时的一处至关重要的孤立前哨站。"},sec={{t="灰谷东部的孤独守望",b="林歌神殿隐匿于灰谷东北部的茂密丛林中，曾是一处优雅的卡多雷定居点。如今，白色的石柱和坍塌的拱门上爬满了常春藤和野蕨。它位于萨提纳尔东北方，就在不断扩张的战歌伐木营地正北方，这些遗迹在通往艾萨拉和大树荫的东部小径上占据了一个宁静且具有战略意义的制高点。虽然周围的树林饱受恶魔腐蚀和部落入侵的困扰，但遗迹本身却保持着一种令人难忘的宁静。"},{t="边境守望者",b="林歌神殿目前仅有德鲁伊凯内斯·静风一人驻守。从这座摇摇欲坠的前哨站，静风时刻注视着进入这片荒野的敌人的险恶企图，包括东部森林中被遗忘者令人不安的踪迹。虽然这里远离阿斯特兰纳且缺乏防御工事，但这座避难所却是联盟旅行者的重要集结点，供他们前往费伍德森林的北行道路，或是调查蔓延至树冠之下的腐蚀。"}},faq={{q="谁住在林歌神殿？",a="目前，林歌神殿住着暗夜精灵德鲁伊凯内斯·静风，他在古老的遗迹中独自坚守。",al={"林歌神殿里有谁","林歌神殿的npc","林歌神殿的居民"}},{q="林歌神殿附近有什么威胁？",a="这些遗迹极其靠近西南方的萨提纳尔（那里爬满了堕落的萨特）以及南方的战歌伐木营地。东北方是大树荫，绿龙军团在那里守卫着通往翡翠梦境的世界之树。",al={"林歌神殿的危险","林歌神殿附近的敌人"}},{q="为什么凯内斯·静风驻扎在这里？",a="凯内斯负责监控整个东部森林的敌对动向，指导盟友对抗区域内的危险——包括在当地活动的被遗忘者所策划的阴谋以及散布的瘟疫。",al={"凯内斯为何在此","凯内斯·静风的目的"}},{q="林歌神殿是联盟的主要定居点吗？",a="不是。与阿斯特兰纳不同，林歌神殿大体上是一处未经加固的遗迹，没有现役驻军、商人或军事基础设施，仅作为一处孤立的前哨观察点。",al={"联盟城镇林歌神殿","林歌神殿是城镇吗"}}},fx={["3234d9c0"]={q="什么是林歌神殿？",a="林歌神殿是一处古老的暗夜精灵遗迹，位于灰谷东北部，坐落在萨提纳尔、战歌伐木营地与大树荫的绿色巨龙传送门之间。这里并非繁华的城市，而是在古树枝叶下静静伫立，充当一座孤立的哨站。",al={"什么是林歌神殿","灰谷的林歌神殿","介绍一下林歌神殿"}},["766b0515"]={q="林歌神殿发生了什么？",a="与散布在灰谷各处的许多古老卡多雷遗迹一样，林歌神殿在漫长岁月中逐渐荒废。如今，这处聚落已成残垣断壁，长期被主要文明遗弃，直到近来逼近的危险再度让人们重视起它的战略位置。",al={"林歌神殿历史","林歌神殿发生了什么","林歌神殿为何沦为废墟"}}},fp="11,297,35.537.0,21.515.0,25.126.0,34.252.0,40.197.0,43.177.0"}
P.entries["subzone:forgotten-coast"] = {n="被遗忘的海岸",s="被遗忘的海岸构成了菲拉斯荒野的西海岸，古老的雨林在此与迷雾之海交汇。笨重的海巨人与水元素徘徊在这片饱经风霜的海岸线上。",h="被遗忘的海岸构成了菲拉斯荒野的西海岸，古老的雨林在此与迷雾之海交汇。笨重的海巨人与水元素徘徊在这片饱经风霜的海岸线上。",kw={"菲拉斯","被遗忘的海岸","萨尔多岛","海巨人","迷雾之海"},ang={["faction:Alliance"]="这条海岸是卡利姆多大陆与萨尔多岛上的羽月要塞之间至关重要的通道，需要警惕游荡的海巨人。",["faction:Horde"]="接近海岸需要小心，因为南部的路径靠近暗夜精灵的渡口；沿着北部的森林小径可以提供更安全的通水路线。"},sec={{t="雨林边缘",b="被遗忘的海岸沿着菲拉斯的西侧边缘延伸，是一片迎接着迷雾之海广阔海域的被风吹拂的海岸线。与内陆茂密的树冠不同，这片前沿地带暴露在自然元素之下，并被高大的海巨人以及在浪花中踱步的游荡水元素所占据。从森林树冠中走出的旅行者必须在应对这些原始海岸守卫的同时，寻找前往大海的通道，那里的渡轮连接着暗夜精灵的堡垒萨尔多岛。"}},faq={{q="被遗忘的海岸有哪些威胁在游荡？",a="海岸线上巡逻着巨大的海巨人，以及从迷雾之海中涌出的不安分的水元素。",al={"被遗忘的海岸的怪物","被遗忘的海岸的危险","海岸上有什么"}},{q="如何从这里到达羽月要塞？",a="这片海岸是跨越海峡前往萨尔多岛的主要大陆出发点，暗夜精灵在岛上维持着羽月要塞。海岸上的一个小轮渡码头提供了一条穿过水域的安全通道，避开了危险的海巨人。",al={"如何前往羽月要塞","前往羽月要塞的船","羽月要塞渡轮"}},{q="部落可以进入被遗忘的海岸吗？",a="可以。虽然南部道路直接通往通往羽月要塞的暗夜精灵渡口，但一条次要路径在更北处切入海岸，允许部落旅行者在不进入联盟哨兵视线的情况下到达岸边。",al={"部落进入被遗忘的海岸","部落如何到达海岸","部落在被遗忘的海岸的安全路径"}}},fp="15,180,22.489.0,40.108.0,50.253.0,47.250.0"}
P.entries["subzone:forgotten-pool"] = {n="Forgotten Pool",s="Forgotten Pool是一处位于黑暗深渊被淹没的走廊深处的潜水洞穴。它位于Moonshrine Ruins之后，这处安静的死胡同是潜伏在地下黑暗中的深海巨兽的水下巢穴。",h="Forgotten Pool是一处位于黑暗深渊被淹没的走廊深处的潜水洞穴。它位于Moonshrine Ruins之后，这处安静的死胡同是潜伏在地下黑暗中的深海巨兽的水下巢穴。",kw={"黑暗深渊","洞穴","forgotten pool","moonshrine ruins","瑟拉吉斯","长吻鱼","水下"},ang={["faction:Horde"]="冒险进入黑暗深渊的部落侦察兵可能会发现Old Serra'kis潜伏在水潭被淹没的黑暗中，远离邪教徒的吟唱大厅。"},sec={{t="水下巢穴",b="要到达Forgotten Pool，需要潜入Moonshrine Ruins后方延伸出的地下水路。这里与陆地隔绝，是一处完全被黑暗水域淹没的孤立死水洞穴。远离暮光之锤教徒的吟唱和娜迦的巡逻，这处隐蔽的区域是被称为Old Serra'kis的古老水生恐怖生物的巢穴，这头野兽隐藏在被淹没的黑暗之中。"}},faq={{q="Forgotten Pool位于哪里？",a="Forgotten Pool是一处完全淹没在水下的洞穴，位于黑暗深渊的深处。探险者必须游过Moonshrine Ruins之后的分支淹没隧道才能到达这里。",al={"forgotten pool在哪里","forgotten pool位置","如何找到forgotten pool"}},{q="Forgotten Pool里潜伏着什么？",a="该洞穴是Old Serra'kis的隐藏巢穴，这是一种类似长吻鱼的古老深海野兽，它将这处隐蔽的死胡同作为自己的栖息地。",al={"forgotten pool怪物","谁住在forgotten pool","forgotten pool首领"}},{q="Forgotten Pool通往其他地方吗？",a="不通往任何地方。这处水潭是一个水下死胡同，没有任何后续通道，仅作为一处隐蔽的水生巢穴存在。",al={"forgotten pool是死胡同吗","forgotten pool通向哪里"}}},fx={["5f3c8292"]={q="什么是 Forgotten Pool？",a="Forgotten Pool 是黑暗深渊深处的一处被水淹没的地下洞穴，就在月神殿废墟之外。它被水下通道与神殿走廊隔开，形成一处死水遍布、与世隔绝的水域尽头，深藏于古老暗夜精灵圣所的废墟之下。",al={"什么是 forgotten pool","forgotten pool 背景","关于 forgotten pool"}},a4c2428d={q="Forgotten Pool 危险吗？",a="是的，游过这里黑暗而浸水的隧道十分危险。除了可能在水下通道中溺水，这座水池还是瑟拉吉斯——一头凶猛水生刃鳍龙的巢穴，附近还有其他潜伏的恐怖生物，任何贸然潜入深处的探险者都将面临险境。",al={"forgotten pool 危险吗","forgotten pool 的危险","forgotten pool 的威胁"}}},fp="14,254,16.435.0,36.203.0,37.147.0,43.112.0"}
P.entries["subzone:forgotten-pools"] = {n="遗忘之池",s="遗忘之池是散落在干旱的贫瘠之地中众多青翠绿洲里最靠北的一处，位于十字路口西北方。这片充满活力的葱郁植被和水域由地下泉水滋养，当地野生生物、游荡的考尔卡半人马和部落都在激烈争夺着此地的控制权。",h="遗忘之池是散落在干旱的贫瘠之地中众多青翠绿洲里最靠北的一处，位于十字路口西北方。这片充满活力的葱郁植被和水域由地下泉水滋养，当地野生生物、游荡的考尔卡半人马和部落都在激烈争夺着此地的控制权。",kw={"贫瘠之地","半人马","十字路口","变异鱼","遗忘之池","考尔卡","装满蘑菇","绿洲"},ang={["class:Druid"]="这些水池周围突变的植被和变异鱼的快速生长，为调查贫瘠之地反常变化的塞纳里奥研究人员提供了关键证据。",["faction:Horde"]="守住这些水池对于保障从十字路口辐射出去的贸易路线至关重要，能防止考尔卡人扼杀部落西部的补给线。"},sec={{t="荒原中的绿洲",b="遗忘之池坐落在从十字路口向西延伸的道路旁，与周围干渴的稀树草原形成了鲜明对比。茂密的芦苇、棕榈树以及像装满蘑菇（Laden Mushrooms）这样奇特的植物群簇拥在淡水湖岸边，吸引了从数里之外赶来的平原陆行鸟、钳嘴龟和斑马。然而，这片绿洲远非宁静之地。考尔卡半人马在岸边长期驻扎，嫉妒地守护着水源，不许旅行者靠近，这使他们与从十字路口出发的部落旅行者直接发生冲突。"},{t="生态之谜",b="除了作为饮水点的战略价值外，遗忘之池还具有独特的生态特征。这是该地区少数能让神秘的变异鱼生存的地表水域之一，暗示了此地与改变贫瘠之地地下水位的奇异转变能量之间存在更深层的地下联系。部落的博物学家和侦察兵密切关注着这片水域以及岸边独特的真菌生长，警惕着是否有某种东西渗入了土壤。"}},faq={{q="遗忘之池在哪里？",a="遗忘之池位于贫瘠之地北部，十字路口的正西北方，就在通往石爪山脉的西向道路以北。",al={"遗忘之池位置","遗忘之池在哪","寻找遗忘之池"}},{q="为什么考尔卡半人马会在这里？",a="在干旱的贫瘠之地，水就是生命。考尔卡人积极占领他们所能到达的每一处绿洲，以维持其战团的生存，并切断过往的部落商队和附近定居点的关键资源。",al={"遗忘之池的半人马","考尔卡人为何在此","遗忘之池考尔卡"}},{q="为什么这里的鱼和植物不寻常？",a="这片绿洲是为数不多可以在地表捕获变异鱼的地方之一，且生长着成簇的装满蘑菇。这些奇怪的变异表明地下扰动正在影响贫瘠之地的地下含水层。",al={"遗忘之池变异鱼","装满蘑菇","为什么这里的鱼很奇怪"}},{q="萨尔经过这个绿洲吗？",a="没有记录显示萨尔的部落在穿越贫瘠之地的漫长行军中曾在哪些绿洲休息过，因此遗忘之池是否在其列尚不可知。",al={"萨尔遗忘之池","兽人在此宿营过吗","魔兽争霸3绿洲"}}},fx={["670d71f6"]={q="什么是遗忘之池？",a="遗忘之池是北贫瘠之地的一片葱郁绿洲，位于十字路口西北方。与周围干旱的灌木荒地不同，这里的淡水滋养着繁茂的植被，岸边生长着奇异的硕大蘑菇，池水深处则游弋着变异鱼。",al={"什么是遗忘之池","贫瘠之地的遗忘之池","关于遗忘之池"}},a5a5def4={q="谁住在遗忘之池？",a="这片绿洲被敌对的科卡尔半人马占据，它们会与当地的鳄龟和野兽一起凶狠地守卫这片赖以生存的水源。",al={"谁控制着遗忘之池","遗忘之池里有谁","遗忘之池的居民"}},["62a6fb30"]={q="遗忘之池危险吗？",a="是的，前往此地需要格外小心。凶猛的科卡尔风暴巫师和驯兽师严密巡逻着岸边，会袭击任何靠近水源的人。除了半人马，凶残的掠食野兽也在周边游荡，绿洲水域中则栖息着变异生物。",al={"遗忘之池危险吗","遗忘之池的威胁","遗忘之池的危险"}}},fp="15,303,22.557.0,20.456.0,38.162.0,32.194.0,44.237.0,35.152.0"}
P.entries["subzone:forlorn-cavern"] = {n="Forlorn Cavern",s="Forlorn Cavern位于铁炉堡地下湖的北岸，是一个光线昏暗、远离喧嚣的Great Forge的隐蔽区域。这里是一处阴影中的避难所，盗贼、扒手和黑魔法的从业者们在此秘密行事，避开矮人守卫的窥探。",h="Forlorn Cavern位于铁炉堡地下湖的北岸，是一个光线昏暗、远离喧嚣的Great Forge的隐蔽区域。这里是一处阴影中的避难所，盗贼、扒手和黑魔法的从业者们在此秘密行事，避开矮人守卫的窥探。",kw={"bonegrip","forlorn cavern","hall of explorers","铁炉堡湖泊","mystic ward","盗贼训练师","stoneblade","术士训练师"},ang={["class:Rogue"]="该洞穴作为联盟在卡兹莫丹的主要盗贼中心，在潮湿的石径旁提供毒药、特制刀剑以及隐蔽的训练师。",["class:Warlock"]="术士们聚集在Bonegrip's Runes and Dooms里，在这个铁炉堡偏僻的角落进行训练并获取补给。"},sec={{t="铁炉堡的阴暗角落",b="当铁炉堡的其他地方充斥着铁砧的敲击声和来自Great Forge的热浪时，Forlorn Cavern却显得寒冷、潮湿而寂静。它沿着山脉地下湖的北缘蜿蜒延伸，其曲折的小径舒适地隐藏在Mystic Ward和Hall of Explorers之间。这里的阴暗使得它成为那些喜欢保持行事低调的人们的理想聚会场所。盗贼和术士们在这里训练，同时也聚集了为他们服务的商人，此外还有武器商和渔夫在湖边工作。"}},faq={{q="Forlorn Cavern在铁炉堡的什么位置？",a="该洞穴位于铁炉堡的北部，沿着地下湖延伸。你可以从Mystic Ward向东，或者从Hall of Explorers沿着隧道向西进入。",al={"forlorn cavern位置","如何前往forlorn cavern","forlorn cavern在哪里"}},{q="为什么盗贼和术士聚集在这里？",a="该洞穴自然黑暗且隐蔽，是一个理想的私密聚会场所。这里有盗贼和术士训练师，以及为这两个群体服务的商人。",al={"为什么术士在这里","为什么盗贼在forlorn cavern","铁炉堡阴暗区域"}},{q="在Forlorn Cavern可以找到哪些商店和服务？",a="除了盗贼和术士训练师外，洞穴里还有为黑魔法从业者服务的Bonegrip's Runes and Dooms，Stoneblade武器店，以及一个被称为The Traveling Fisherman的安静钓鱼用品店。",al={"forlorn cavern商人","forlorn cavern的商店"}}},fx={["15f7ff40"]={q="Forlorn Cavern危险吗？",a="这里属于铁炉堡的守卫范围，但仍应小心行事。洞穴昏暗的角落里藏着形迹可疑之人、窃贼、扒手，以及研习黑暗邪能的人。只要保持警惕，并尊重这里正在进行的隐秘活动，这片区域还算平静，旅人可以安然通过。",al={"forlorn cavern安全吗","forlorn cavern的危险","forlorn cavern的威胁"}},["307bd9d1"]={q="什么是 Forlorn Cavern？",a="Forlorn Cavern 是铁炉堡深处环绕地下湖的一片阴暗曲折的区域，位于秘法区与探险者大厅之间。这里僻静的阴影为铁炉堡中不那么光彩的居民提供了清静的藏身之所，其中包括当地的潜行者、隐秘的术士，以及偏爱避开矮人窥探、暗中经营的小众商贩。",al={"什么是 forlorn cavern","forlorn cavern 概况","关于 forlorn cavern"}}},fp="14,316,25.533.0,49.190.0,39.158.0,59.220.0"}
P.entries["subzone:forlorn-cloister"] = {n="Forlorn Cloister",s="Forlorn Cloister是血色修道院内被闹鬼的墓地区域。在这里，血色十字军的成员绝望地焚烧着阵亡兄弟的尸体，以防他们复活成为亡灵，而不安的灵魂和蹒跚的尸骸则在墓穴间游荡。",h="Forlorn Cloister是血色修道院内被闹鬼的墓地区域。在这里，血色十字军的成员绝望地焚烧着阵亡兄弟的尸体，以防他们复活成为亡灵，而不安的灵魂和蹒跚的尸骸则在墓穴间游荡。",kw={"forlorn cloister","墓地","血色十字军","血色修道院","萨尔诺斯","提瑞斯法林地"},ang={["class:Priest"]="走在Forlorn Cloister中，让人清醒地意识到当神圣的圣所堕入黑暗时会发生什么——神圣的仪式让位于疯狂的火堆和受折磨的幻影。",["race:Undead"]="被遗忘者在修道院中观察到了一种残酷的讽刺：这些将所有亡灵视为怪物的狂热十字军，竟然连阻止自己的兄弟在脚下复活都做不到。"},sec={{t="被玷污的圣地",b="Forlorn Cloister曾是一片宁静的圣所，洛丹伦的牧师和圣骑士们将他们受人尊敬的死者安葬于此，如今却已变成了一座阴森的停尸场。尽管血色十字军保持着狂热的警惕，但瘟疫的腐蚀已经深入大地。十字军们手持火炬在雾气笼罩的墓地中巡逻，疯狂地焚烧遗骸以阻止腐烂蔓延。即便如此，幽灵仍在墓穴间穿行，死者从坟墓中挣脱，并受到深藏于墓地之下的黑暗魔法的控制。"},{t="墓地的主人",b="在修道院的深处潜伏着血法师萨尔诺斯，这是一位骷髅法师，他的亡灵身躯体现了这座修道院的悲剧。萨尔诺斯渴望复仇，他挥舞着黑暗魔法，禁锢逝者的灵魂，并屠杀任何敢于闯入他那片被枯萎侵蚀的墓地的入侵者。"}},faq={{q="Forlorn Cloister位于哪里？",a="Forlorn Cloister是血色修道院的户外墓地区域，位于提瑞斯法林地的东北角。",al={"forlorn cloister位置","cloister在哪里","墓地区域"}},{q="为什么血色十字军要在这里焚烧尸体？",a="十字军焚烧死者是出于一种绝望的尝试，目的是阻止天灾瘟疫复活他们阵亡的同伴。由于墓地的土壤已经被腐蚀，未被焚烧的尸体很快就会复活成为无脑的僵尸。",al={"为什么要焚烧尸体","血色十字军焚烧尸体","十字军在做什么"}},{q="谁在统治Forlorn Cloister？",a="这片墓地由强大的亡灵施法者血法师萨尔诺斯统治，他指挥着游荡的亡者，并攻击任何活着的入侵者。",al={"cloister首领","这里由谁掌管","墓地首领"}},{q="既然血色十字军占据着修道院，为什么墓地还有闹鬼？",a="尽管拥有宗教狂热，但十字军已经失去了对自己墓地的控制。席卷洛丹伦的无尽死灵能量已经唤醒了埋葬的死者，使得驻守在此的活人被迫与他们昔日同袍的灵魂进行永无休止的战斗。",al={"为什么会有鬼魂","为什么修道院里有亡灵","墓地是天灾吗"}}},fx={["9a53d37e"]={q="Forlorn Cloister是什么地方？",a="Forlorn Cloister是血色修道院露天墓园的一部分。这里曾是修会阵亡者安息的宁静之地，如今却已衰败成一座荒凉庭院，土地与墓穴间爬满了不安的亡者。血色十字军竭力守卫修道院其他区域，而在这里，他们只能拼死进行一场永无休止的战斗，勉强遏制从土中涌出的恐怖之物。",al={"forlorn cloister是什么地方","血色修道院的forlorn cloister","关于forlorn cloister"}},a5f6d48a={q="Forlorn Cloister危险吗？",a="这座墓园十分危险。狂热的血色十字军焚烧尸体，而不安的怨灵和行尸则在墓碑间游荡。更深处住着血法师萨尔诺斯，这名亡灵法师会攻击闯入者。",al={"forlorn cloister危险吗","forlorn cloister的威胁","forlorn cloister的危险"}}},fp="16,270,23.503.0,23.275.0,38.138.0,50.217.0,36.144.0,72.281.0"}
P.entries["subzone:forlorn-ridge"] = {n="凄凉山",s="凄凉山是一座高耸的山脊，俯瞰着艾萨拉的西南部。其优越的战略高地和对海岸一览无余的视野吸引了联盟和部落的注意，双方都在其山坡上修筑了防御工事。",h="凄凉山是一座高耸的山脊，俯瞰着艾萨拉的西南部。其优越的战略高地和对海岸一览无余的视野吸引了联盟和部落的注意，双方都在其山坡上修筑了防御工事。",kw={"艾萨拉","凄凉山","防御工事","山","埃达拉斯废墟","火山"},ang={["faction:Alliance"]="占据凄凉山的高地可以提供预警和战术监视，以应对从贫瘠之地和灰谷向东蔓延的部落部队。",["faction:Horde"]="对于部落来说，在凄凉山上建立据点有助于巩固杜隆塔尔以北艾萨拉崎岖的边境地区，抵御联盟的入侵。"},sec={{t="一处必争的制高点",b="凄凉山陡峭地耸立在艾萨拉西部的秋色森林之上，俯瞰着周围的地形。它看起来像是一座古老且早已沉寂的火山，其高处的制高点可以一览海岸的动向以及下方废弃的精灵庄园。由于控制这些高地意味着在该地区的军事优势，联盟和部落的部队都在其山侧建立了营地和哨所，在崎岖的悬崖两端警惕地注视着对方。"}},faq={{q="凄凉山是什么？",a="凄凉山是位于艾萨拉西南部的一处显眼的山地地貌，高耸于当地的荒野和沿海道路之上。",al={"凄凉山在哪里","凄凉山 艾萨拉","这座山是什么"}},{q="为什么联盟和部落要争夺这座山脊？",a="这座山脊拥有整个艾萨拉西部无与伦比的视野。无论谁占据了高地，都能监视从海岸废墟到内陆通道之间的部队调动，这促使双方都在其山坡上加强了阵地。",al={"为什么这里有营地","谁控制了凄凉山","联盟与部落 凄凉山"}},{q="凄凉山最初是一座火山吗？",a="这座山独特的形状和崎岖的构成表明它在遥远的过去可能曾是一座火山地貌，尽管它早已沉寂并长满了植被。",al={"凄凉山是火山吗","艾萨拉的火山"}}},fp="13,256,19.496.0,22.133.0,56.230.0,39.176.0"}
P.entries["subzone:forlorn-rowe"] = {n="荒弃鬼屋",s="荒弃鬼屋是位于暮色森林乌鸦岭墓地北侧边界上一座阴森、晦暗的小山。这里因作为莫本·菲尔的黑暗巢穴而臭名昭著，这位死灵法师的邪恶魔法唤醒了森林中游荡的The Restless Dead。",h="荒弃鬼屋是位于暮色森林乌鸦岭墓地北侧边界上一座阴森、晦暗的小山。这里因作为莫本·菲尔的黑暗巢穴而臭名昭著，这位死灵法师的邪恶魔法唤醒了森林中游荡的The Restless Dead。",kw={"墓地","暮色森林","荒弃鬼屋","莫本·菲尔","死灵法师","乌鸦岭","亡灵"},ang={["class:Paladin"]="在荒弃鬼屋编织的黑暗仪式是对圣光的亵渎，需要经过祝圣的圣物和正义的愤怒才能穿透这位死灵法师的护盾。",["faction:Alliance"]="将莫本·菲尔从荒弃鬼屋中铲除，对于恢复暮色森林西部边境的安宁至关重要。"},sec={{t="死灵法术的据点",b="荒弃鬼屋坐落在乌鸦岭墓地的北缘，终年笼罩在阴霾之中。在这座高地的顶端坐落着莫本·菲尔的居所，这位酷似巫妖的死灵法师正是导致周围荒野中行尸走肉四处游荡的罪魁祸首。在邪恶奥术附魔的束缚下，这位高地的主人从此处指挥着他的骷髅仆从，使得暮色森林的整个西北角对于旅行者来说危机四伏。"},{t="净化高地",b="莫本·菲尔对荒弃鬼屋的掌控单凭普通的刀剑无法打破。在被神圣力量的特殊圣物削弱之前，他的黑暗附魔保护着他的肉身不受凡人武器的伤害。想要击倒这位死灵法师并打破他对这片森林的控制，探险者们必须获得经过祝圣的武器，直击笼罩墓地的诅咒核心。"}},faq={{q="荒弃鬼屋位于何处？",a="荒弃鬼屋位于暮色森林的西北部，直接坐落在俯瞰整个乌鸦岭墓地的北侧山脊上。",al={"荒弃鬼屋位置","荒弃鬼屋在哪里","寻找荒弃鬼屋"}},{q="谁居住在荒弃鬼屋？",a="那是莫本·菲尔的巢穴，他是一位强大而邪恶的死灵法师，利用黑暗奥术仪式来唤醒并指挥在暮色森林中游荡的亡灵军团。",al={"谁在荒弃鬼屋","荒弃鬼屋首领","暮色森林山上的房子"}},{q="为什么莫本·菲尔在这里如此难以对付？",a="莫本·菲尔用邪恶的法术保护着自己，在用专门制作的用于驱散他魔法的圣物剥去他的黑暗护盾之前，凡人的攻击几乎毫无用处。",al={"莫本·菲尔护盾","莫本·菲尔免疫","如何击败莫本·菲尔"}},{q="荒弃鬼屋是墓地的一部分吗？",a="是的，它作为乌鸦岭墓地北侧边界上一座隆起的高地，直接俯瞰着下方的坟墓和墓穴。",al={"荒弃鬼屋是乌鸦岭吗","乌鸦岭联系"}}},fx={aabdcca0={q="Forlorn Rowe是什么地方？",a="荒弃鬼屋是一座阴暗荒凉的山丘，坐落在暮色森林西北部乌鸦岭墓地北缘。这里笼罩在诡异的阴霾中，俯瞰着广阔的墓地，也是邪恶通灵师Morbent Fel的私人据点。他以污秽的巫术操纵森林中游荡的亡者。",al={"forlorn rowe是什么地方","forlorn rowe概况","关于forlorn rowe"}},e9789594={q="荒弃鬼屋危险吗？",a="这里极其危险。Morbent Fel在山顶的居所中施展致命的通灵魔法，积极束缚并操纵涌入北部墓地的亡灵。踏上这片阴影笼罩的山坡，便会招致他唤起的躁动尸骸以及这位强大术士本人的怒火。",al={"forlorn rowe的危险","forlorn rowe有多危险","这里安全吗"}}},fp="12,253,20.441.0,18.396.1,34.140.0,30.158.0,41.184.1,41.141.0"}
P.entries["subzone:fray-island"] = {n="勇士岛",s="勇士岛是一座饱受风吹、岩石嶙峋的小岛，位于贫瘠之地的商旅海岸外。这里有着一个粗犷的训练擂台，作为一处中立避难所而闻名，来自艾泽拉斯各地的战士都会来此磨砺技艺。",h="勇士岛是一座饱受风吹、岩石嶙峋的小岛，位于贫瘠之地的商旅海岸外。这里有着一个粗犷的训练擂台，作为一处中立避难所而闻名，来自艾泽拉斯各地的战士都会来此磨砺技艺。",kw={"乱斗","贫瘠之地","狂暴姿态","大个子威利","勇士岛","克兰诺克·马克雷德"},ang={["class:Warrior"]="勇士岛是你训练中的关键试炼场。克兰诺克·马克雷德和“乱斗”试炼将考验你是否具备掌握狂暴姿态所需的纪律与力量。",["race:Human"]="克兰诺克·马克雷德是个人类，但聚集在他擂台上的战士们却有着超越种族界限的战斗羁绊。"},sec={{t="格斗士的试炼场",b="勇士岛坐落于贫瘠之地东部的悬崖外，远离奥格瑞玛和塞拉摩的视线。这座岛屿是各族战士的训练场所。岛屿中心设有一座由克兰诺克·马克雷德监管的竞技场，老练的战士和新兵们在此聚集，进行残酷的格斗较量。"},{t="乱斗试炼",b="尽管周围的水域险象环生，但岛屿中央的擂台却遵循着简单的武斗法则。战士们在训练师的指引下远道而来，参加“乱斗”——这是一场艰苦的连番挑战，最终还要与冠军大个子威利进行对决。在这里，部落或联盟的阵营之分被抛诸脑后，唯有纯粹的力量与武道纪律才是关键。"}},faq={{q="勇士岛的用途是什么？",a="这座岛屿是战士的训练场，也是被称为“乱斗”的残酷格斗试炼之地。双方阵营的战士都会来到这里证明自己的耐力，并掌握高级姿态。",al={"为什么要去勇士岛","勇士岛的用途","勇士岛上有什么"}},{q="谁控制着勇士岛？",a="没有任何王国或派系统治这里。这座岛屿是各族战士的训练场所，其战斗擂台由战士训练师克兰诺克·马克雷德监管。",al={"谁管理勇士岛","谁住在勇士岛","勇士岛所属阵营"}},{q="我该如何前往勇士岛？",a="勇士岛位于无尽之海中，在贫瘠之地的东海岸外，棘齿城以南。要到达那里，需要从大陆海岸长距离游过去，途中还会经过鲨鱼和狂暴鱼群出没的水域。",al={"如何前往勇士岛","勇士岛在哪里","前往勇士岛的方法"}},{q="什么是乱斗？",a="“乱斗”是在岛上格斗铁笼中举行的一场耐力试炼。战士必须站在格栅上，击败一波又一波的挑战者，最后战胜格斗家大个子威利。",al={"乱斗","勇士岛竞技场","大个子威利之战"}}},fx={["0872188f"]={q="勇士岛是什么地方？",a="勇士岛是一座干旱的小岛，位于贫瘠之地东海岸外、棘齿城以南。这里是与世隔绝的试炼场和角斗场，各个种族、信仰的战士都会来此磨炼武艺。",al={"勇士岛传说","勇士岛是什么地方","贫瘠之地的勇士岛"}},["122aa5b5"]={q="勇士岛发生过什么事？",a="勇士岛由训练师克兰诺克·马克雷德主持，最初被设立为武艺试炼场。长久以来，这里一直置身于阵营纷争之外，吸引着艾泽拉斯各地的斗士和搏击者前来角逐，检验自己的战斗技巧。",al={"勇士岛的历史","勇士岛的往事","这里发生过什么事"}},d609582c={q="勇士岛危险吗？",a="对准备不足的人来说很危险。角斗场会让每位挑战者迎战一波又一波凶悍的搏击者，而要抵达岛上，你还得长途游泳，穿过满是敌对泥浆狂鱼的水域。",al={"勇士岛安全吗","勇士岛的威胁","勇士岛上的危险"}},b15eb391={q="勇士岛为何得名？",a="岛名源自当地举办的残酷格斗竞赛和角斗场“The Affray”。战士和斗士从远方赶来，在这些搏斗中交锋，因此整座岛都以好战闻名。",al={"勇士岛名称的含义","勇士岛为何得名","为什么叫勇士岛"}}},fp="11,225,29.347.0,23.411.0,29.202.0,25.188.0,27.190.0,19.194.0"}
P.entries["subzone:frayfeather-highlands"] = {n="乱羽高地",s="乱羽高地是菲拉斯茂密森林中一片海拔较高的荒野。这片偏远的高原是野生乱羽角鹰兽的祖居栖息地和筑巢地。无畏的拾荒者和博物学家常常为了寻找完整的角鹰兽蛋，而勇闯这片领地，直面凶猛的群兽。",h="乱羽高地是菲拉斯茂密森林中一片海拔较高的荒野。这片偏远的高原是野生乱羽角鹰兽的祖居栖息地和筑巢地。无畏的拾荒者和博物学家常常为了寻找完整的角鹰兽蛋，而勇闯这片领地，直面凶猛的群兽。",kw={"蛋","菲拉斯","乱羽","加基森","高地","角鹰兽","巢穴"},ang={["class:Druid"]="德鲁伊们高度重视卡利姆多的野生野兽，并将乱羽高地未受干扰的巢穴视为森林原始生命力的纯粹体现。",["race:NightElf"]="暗夜精灵将角鹰兽视为艾露恩的神圣伙伴，这使得菲拉斯的野生巢穴成为重要的自然栖息地，应当免受鲁莽的开发破坏。"},sec={{t="角鹰兽之巢",b="乱羽高地耸立在菲拉斯周围的林地之上，以陡峭的斜坡和嶙峋的岩石为主，野生角鹰兽便在那里繁育后代。当地的角鹰兽群以对入侵者极具攻击性而闻名，它们会激烈地保卫着散布在岩架之间的巢穴。由于这些野兽非常适应崎岖的悬崖，它们的筑巢地吸引了外界的极大兴趣——其中最引人注目的便是远在加基森的地精企业家，他们寻求未孵化的蛋以供研究和牟利。"}},faq={{q="乱羽高地生活着什么生物？",a="高地主要栖息着大量的野生乱羽角鹰兽，它们在高耸的岩面上筑巢，并积极防御领地，抵御入侵者。",al={"乱羽野生生物","这里有什么","乱羽野兽"}},{q="为什么旅行者对角鹰兽巢穴感兴趣？",a="巢穴中含有珍贵的角鹰兽蛋。冒险者们收集这些完好的蛋，并将其送到塔纳利斯的加基森，在那里的地精会利用超级蛋蛋机进行研究和牟利。",al={"角鹰兽蛋","蛋任务","为什么要偷蛋"}},{q="乱羽高地位于哪里？",a="高地位于菲拉斯的南部，海拔高于主要的丛林树冠，以崎岖的山坡和开阔的筑巢栖木为特色。",al={"乱羽位置","乱羽高地在哪里","如何找到乱羽"}}},fp="21,293,24.529.0,49.177.0,53.200.0,44.167.0"}
P.entries["subzone:freewind-post"] = {n="乱风岗",s="乱风岗是部落在千针石林的主要前哨站，坐落在峡谷中一座险峻的石质平顶山上。这里主要通过牛头人的升降梯和蜿蜒的绳桥进出，是防御半人马战团的避难所，也是一个至关重要的边境集结地。",h="乱风岗是部落在千针石林的主要前哨站，坐落在峡谷中一座险峻的石质平顶山上。这里主要通过牛头人的升降梯和蜿蜒的绳桥进出，是防御半人马战团的避难所，也是一个至关重要的边境集结地。",kw={"黑云峰","升降梯","乱风岗","加拉克","风巢","平顶山","牛头人","千针石林","双足飞龙"},ang={["faction:Horde"]="乱风岗是部落在南贫瘠之地和塔纳利斯之间唯一的主要避难所和飞行连接点，为整个卡利姆多中部提供了必要的后勤支持。",["race:Tauren"]="乱风岗展现了舒哈鲁的建筑智慧，他们利用平顶山的高度抵御传统的半人马劫掠者，同时照料悬崖上的祖传双足飞龙。"},sec={{t="云端的堡垒",b="乱风岗直接建在峡谷平顶山上，依靠巧思和高度来保卫其居民。加拉克半人马虽然在下方的干旱峡谷地带横行霸道，但他们无法有效地攀登这些高耸的悬崖，也无法攻破那些将部落旅行者运送到高空的重型木制升降梯。纵横交错的绳索和木板桥将乱风岗与邻近的尖塔连接起来，形成了一座稳固的空中要塞。除了抵御半人马劫掠者，前哨站还会处理在断崖上筑巢的尖啸鹰身人，并照看附近风巢的野生双足飞龙，这些双足飞龙的卵会被采集并孵化，训练成为部落忠诚的双足飞龙坐骑。"},{t="来自黑云峰的阴影",b="尽管乱风岗拥有易守难攻的地势，但它与西北方邻居的关系却日趋紧张：驻扎在黑云峰的恐怖图腾部族。恐怖图腾过去曾被视为固执的传统派而遭到容忍，但在酋长阿纳克的领导下，他们越来越频繁地诉诸暴力、绑架和谋杀。附近的山峰笼罩在可疑的仪式和黑暗力量的低语之中。当地的牛头人怀着越来越深的恐惧注视着天空和绳桥，他们意识到自己最危险的敌人并非潜伏在下方的盐碱平原，而是盘踞在峡谷风口对面。"}},faq={{q="乱风岗为什么要建在这么高的平顶山上？",a="这种垂直布局使定居点免受在峡谷底部巡逻的敌对加拉克半人马战团的侵扰。半人马擅长在平坦的地形上作战，但无法攀登陡峭的悬崖，也难以攻破牛头人使用的机械木制升降梯。",al={"乱风岗为什么在天上","为什么是平顶山","乱风岗海拔"}},{q="如何上下乱风岗？",a="大多数旅客使用安装在主平顶山底部的巨型机械木制升降梯。还有一条后路，由一系列蜿蜒在邻近岩柱之间、令人心惊肉跳的绳桥和木坡道组成，不过一旦失足，就意味着会坠入峡谷深渊，必死无疑。",al={"如何到达乱风岗","乱风岗升降梯","乱风岗入口"}},{q="乱风岗与恐怖图腾部族之间是什么关系？",a="关系极其紧张。占据乱风岗西北方黑云峰的恐怖图腾部族被指控犯有谋杀、绑架罪行，并对其他牛头人表现出无端的敌意，这使得前哨站的守卫者们不得不时刻对这些邻近的族人保持警惕。",al={"恐怖图腾与乱风岗","黑云峰与乱风岗","为什么恐怖图腾在这里是坏人"}},{q="风巢对乱风岗有什么重要性？",a="风巢是位于峡谷另一侧、野生双足飞龙的祖传巢穴。乱风岗的牛头人监视着这些野兽，并从巢穴中采集龙蛋，这些龙蛋会被精心孵化和喂养，长大后成为部落各地的双足飞龙坐骑。",al={"为什么风巢很重要","风巢的双足飞龙与乱风岗"}}},fx={["1f4dfdb3"]={q="乱风岗是什么地方？",a="乱风岗是部落的一座要塞哨站，位于千针石林中央高耸的石柱顶端。这里主要居住着忠于雷霆崖的牛头人，是旅人穿行于南贫瘠之地、菲拉斯和塔纳利斯之间的峡谷时，进行贸易、防御和通讯的重要枢纽。",al={"乱风岗是什么地方","乱风岗","关于乱风岗"}},["17ef52e2"]={q="乱风岗发生过什么事？",a="牛头人在高耸的台地上建立了乱风岗，建成一处易守难攻的据点，使其远离下方肆虐的加拉克半人马。随着时间推移，这里逐渐成为守卫峡谷的重要哨站，也负责研究并驯养附近风巢的双足飞龙坐骑，以及监视黑云峰日益敌对的蛮锤部族。",al={"乱风岗的历史","这里发生过什么事"}},["5739dc9d"]={q="谁居住在乱风岗，或负责管理这里？",a="这里居住并守卫着忠于大酋长凯恩·血蹄的部落牛头人。除了守护桥梁和升降梯的勇士外，这里还有商人、驭风者管理员和长者，他们负责协调巡逻，防范加拉克半人马、尖啸的 harpy，以及附近蛮锤部族的阴谋等地区威胁。",al={"谁管理乱风岗","乱风岗的居民","谁住在这里"}},["880e92a9"]={q="乱风岗危险吗？",a="哨站本身防卫严密，但地势极高，若从边缘或摇晃的绳桥上失足，便会丧命。越过外围后，周围的峡谷底部遍布敌对的加拉克半人马，凶暴的 harpy 在峡谷尖峰筑巢，而阴险的蛮锤部族则在邻近的黑云峰密谋对付镇子。",al={"乱风岗危险吗","乱风岗的危险","乱风岗面临的威胁"}}},fp="13,279,21.659.0,31.565.1,48.245.0,41.297.0,65.276.0,48.249.0"}
P.entries["subzone:frostfire-hot-springs"] = {n="冰火温泉",s="冰火温泉是一处位于冬泉谷西部雪堆中的奇异温泉群。尽管四周是刺骨的严寒，但这些池水却在不断沸腾，吸引着好奇的学者、坚韧的渔夫和充满敌意的熊怪。",h="冰火温泉是一处位于冬泉谷西部雪堆中的奇异温泉群。尽管四周是刺骨的严寒，但这些池水却在不断沸腾，吸引着好奇的学者、坚韧的渔夫和充满敌意的熊怪。",kw={"暗语峡谷","多诺瓦·雪山","冰火温泉","木喉要塞","冬泉熊怪","冬泉谷"},ang={["class:Druid"]="温泉难以解释的热量和异常特性引发了人们对冬泉谷地下力量的质疑。",["race:Dwarf"]="这些温泉展现了像多诺瓦·雪山一样的同胞们那种好奇的天性，她勇敢地面对冰天雪地，试图解开地质之谜。"},sec={{t="雪原中的热泉",b="冰火温泉位于通往木喉要塞的隧道附近，是卡利姆多北部最奇怪的自然异常现象之一。尽管来源不明，但在四周皑皑白雪中，这些池水依然保持着高温。当地的冬泉熊怪在水域附近出没，但它们领地意识极强，使得毫无防备的旅者很难靠近这些温暖的河岸。对于那些能够避开危险野生生物和严寒的旅者来说，这些未结冰的水域是鱼类罕见的栖息地。"},{t="地热之谜",b="在这片冰冻荒原中，这种强烈的热量展现出的奇异存在引起了许多好奇观察者的注意。附近，一位名叫多诺瓦·雪山的矮人正在孤独地守望着这些温泉，研究它们的起源和成分。雪山怀疑这些地热异常可能并非完全自然形成，她推测可能是有邪恶的魔法腐蚀从南方的恶魔据点暗语峡谷向北渗透，导致地下的水流沸腾。"}},faq={{q="为什么冰冻的冬泉谷会有温泉？",a="温泉热量的来源是一个谜。附近没有火山，多诺瓦·雪山正在调查暗语峡谷的恶魔影响是否与之有关。",al={"为什么水是热的","冰火温泉起源","冬泉谷热水"}},{q="多诺瓦·雪山是谁？",a="多诺瓦·雪山是一位驻扎在温泉附近的矮人研究员。她研究这些温泉的异常特性，并寻求旅者的帮助以了解冬泉谷的危险。",al={"温泉附近的矮人","多诺瓦·雪山背景故事","温泉任务发布者"}},{q="这些温泉会与恶魔魔法有关吗？",a="多诺瓦·雪山推测，远在南方暗语峡谷中滋生的恶魔污染可能深植于大地之中，加热或扭曲了涌向冰火温泉的地下水流。",al={"温泉恶魔","与暗语峡谷的联系","腐蚀之水"}},{q="谁居住在温泉周围？",a="极具攻击性的冬泉熊怪部落控制着温泉附近的领地，并将这些温暖的池塘视为宝贵的领土。旅者必须保持警惕，因为这些熊怪见到外来者就会发动攻击。",al={"冰火温泉敌人","谁控制着温泉","温泉熊怪"}}},fp="21,277,27.531.0,20.497.0,51.178.0,22.180.0,43.212.0,33.196.0"}
P.entries["subzone:frostmane-hold"] = {n="霜鬃巨魔要塞",s="霜鬃巨魔要塞是霜鬃冰巨魔在丹莫罗西部占据的一处设防营地和洞穴建筑群。它位于诺莫瑞根南部的岩架中，是巨魔劫掠者侵入矮人领地的中心集结地。铁炉堡卫队密切监视着这座要塞，以评估日益增长的巨魔威胁。",h="霜鬃巨魔要塞是霜鬃冰巨魔在丹莫罗西部占据的一处设防营地和洞穴建筑群。它位于诺莫瑞根南部的岩架中，是巨魔劫掠者侵入矮人领地的中心集结地。铁炉堡卫队密切监视着这座要塞，以评估日益增长的巨魔威胁。",kw={"丹莫罗","霜鬃","霜鬃巨魔要塞","猎头者","剥皮者","冰巨魔","卡拉诺斯","vejrek"},ang={["race:Dwarf"]="霜鬃部族几个世纪以来一直与矮人争夺丹莫罗，肃清霜鬃巨魔要塞是那些寻求保卫铁炉堡冰雪腹地的山地探险队员们的成年仪式。",["race:Gnome"]="该要塞坐落在诺莫瑞根南侧，构成了与饱受战火蹂躏的前侏儒首都接壤的又一条危险敌对防线。"},sec={{t="雪原中的巨魔堡垒",b="霜鬃巨魔要塞开凿在丹莫罗西部的冰冷峭壁之上，由粗糙的室外建筑和蜿蜒的洞穴系统组成。对于霜鬃部族来说，这里是他们的主要据点，由剥皮者和猎头者严密把守。巨魔从这里向周围的山谷发动突袭，试探卡拉诺斯等附近定居点的防御，并威胁着山路上的旅客。"},{t="卡拉诺斯的眼中钉",b="随着丹莫罗局势日益紧张，卡拉诺斯的矮人指挥官们对霜鬃部族集结的规模越来越担忧。年轻的山地探险队员和冒险者经常被派往洞穴内部进行侦察、绘制防御工事地图，并在部族组织起对矮人前哨站的进攻之前削减他们的兵力。"}},faq={{q="谁住在霜鬃巨魔要塞？",a="该据点由霜鬃部族的冰巨魔占据，具体包括他们的猎人、剥皮者和猎头者，以及他们的酋长和劫掠者。",al={"霜鬃巨魔要塞里的人","霜鬃巨魔要塞怪物","霜鬃巨魔要塞的巨魔"}},{q="霜鬃巨魔要塞位于何处？",a="它位于丹莫罗西部的群山之中，坐落在诺莫瑞根工业废墟以南，卡拉诺斯以西。",al={"霜鬃巨魔要塞位置","霜鬃巨魔要塞在哪里","寻找霜鬃巨魔要塞"}},{q="矮人为何对这个洞穴感兴趣？",a="卡拉诺斯的矮人首领们担心霜鬃部族聚集的人数足以发动严重突袭，这促使军事指挥官派遣侦察兵去绘制洞穴地图并削减敌人的数量。",al={"为何侦察霜鬃巨魔要塞","卡拉诺斯巨魔任务"}},{q="霜鬃巨魔要塞里有穴居人吗？",a="没有。在当前时代，该据点牢牢地掌握在霜鬃冰巨魔手中。丹莫罗的穴居人活动主要集中在他们自己的巢穴和诺莫瑞根的废墟周围。",al={"霜鬃巨魔要塞穴居人","石颚怪霜鬃"}}},fx={["81bf3a2c"]={q="霜鬃巨魔要塞是什么地方？",a="霜鬃巨魔要塞是一片庞大的洞穴群和营地，坐落在丹莫罗西部的寒冷山脉中，诺莫瑞根以南。这里由简陋建筑和深邃洞穴组成，是当地霜鬃冰巨魔的主要据点。",al={"霜鬃巨魔要塞是什么地方","丹莫罗的霜鬃巨魔要塞","关于霜鬃巨魔要塞"}},["406236bf"]={q="霜鬃巨魔要塞危险吗？",a="对任何联盟旅人来说，这里都极其危险。霜鬃巨魔要塞由霜鬃巨魔猎头者和剥皮者严密防守，他们对擅闯领地的外人绝不留情。",al={"霜鬃巨魔要塞危险吗","霜鬃巨魔要塞的危险","霜鬃巨魔要塞有多安全"}},["0c447a8f"]={q="霜鬃巨魔要塞为何得名？",a="这座据点直接以霜鬃部族命名。这个冰巨魔部族开凿了这些洞穴，并将冰封山脉视为祖先的家园。",al={"霜鬃巨魔要塞为何得名","霜鬃巨魔要塞名称的含义","霜鬃巨魔要塞的名称由来"}}},fp="14,338,28.417.0,25.349.0,28.164.0,32.122.0,44.207.0,35.189.0"}
P.entries["subzone:frostmane-hovel"] = {n="Frostmane Hovel",s="Frostmane Hovel是一处坐落在丹莫罗寒脊山谷南部峭壁中的崎岖洞穴。这里是好战的霜鬃巨魔直接突入矮人训练场的坚固避难所。",h="Frostmane Hovel是一处坐落在丹莫罗寒脊山谷南部峭壁中的崎岖洞穴。这里是好战的霜鬃巨魔直接突入矮人训练场的坚固避难所。",kw={"安威玛尔","寒脊山谷","丹莫罗","霜鬃","巢穴","巨魔"},ang={["faction:Alliance"]="Frostmane部族在安威玛尔外围的持续存在，突显了即使是铁炉堡的核心腹地，也必须时刻提防当地敌对势力的威胁。",["race:Dwarf"]="对于在寒脊山谷训练的铜须年轻新兵来说，在像这样的洞穴中清除敌对的霜鬃部族以确保周边安全，是他们成长路上的必经仪式。"},sec={{t="山谷中的巨魔巢穴",b="Frostmane Hovel开凿在寒脊山谷南侧的群山之中，收容着拒绝将高海拔雪域让给铁炉堡的原住民霜鬃巨魔。这些巨魔以这类粗陋的洞穴为基地，不断袭击当地的矮人营地，并切断通往山谷的补给线。"}},faq={{q="什么是Frostmane Hovel？",a="Frostmane Hovel是寒脊山谷南部的一个天然洞穴，被那些侵入矮人领地的霜鬃巨魔用作恶劣天气下的营地。",al={"frostmane hovel","这是什么洞穴","寒脊山谷巨魔洞穴"}},{q="为什么寒脊山谷里会有巨魔？",a="霜鬃部族已经在丹莫罗的雪峰上繁衍生息了数代。作为铜须矮人的死敌，他们不断从高耸的山脊向内渗透，袭击补给路线并挑战矮人的定居点。",al={"为什么这里有巨魔","丹莫罗巨魔","霜鬃部族的存在"}},{q="谁控制着这个洞穴？",a="这个洞穴被劫掠的霜鬃巨魔占据，他们利用这处隐蔽的裂隙作为向山谷南缘发动入侵的据点。",al={"谁控制了洞穴","谁住在frostmane hovel"}}},fp="15,218,25.313.0,28.167.0,41.227.0,23.139.0"}
P.entries["subzone:frostsaber-rock"] = {n="霜刀石",s="霜刀石是一座高耸的岩石岬角，屹立在冬泉谷北部冰雪覆盖的地区之上。它是该地区高贵的霜刃豹的主要栖息地和训练场。",h="霜刀石是一座高耸的岩石岬角，屹立在冬泉谷北部冰雪覆盖的地区之上。它是该地区高贵的霜刃豹的主要栖息地和训练场。",kw={"联盟坐骑","霜刃豹","霜刀石","雷沃·霜翼","冬泉霜刃豹","冬泉谷"},ang={["class:Hunter"]="这座岩石岬角及其周围的山坡为猎人们提供了一个令人向往的试炼场，他们可以在这里观察到卡利姆多北部最凶猛的掠食者。",["faction:Alliance"]="在山顶赢得雷沃·霜翼信任的联盟英雄，可以开始一段艰苦的训练之旅，最终骑上著名的冬泉霜刃豹。"},sec={{t="苔原上的栖木",b="霜刀石高耸于冬泉谷北部冰封的荒原之上，在此可以俯瞰广袤的雪原。这座岩石岬角得名于潜行在下方山坡和山谷中的凶猛且威严的掠食者——霜刃豹。在最高点居住着雷沃·霜翼，一位致力于饲养和照料这些野兽的孤独暗夜精灵。对于愿意在严酷环境中挑战自我并证明其忠诚的联盟勇士，雷沃提供了极其罕见的机会，教导他们如何饲养、驯服和骑乘这些传说中的雪地坐骑。"}},faq={{q="谁住在霜刀石顶上？",a="雷沃·霜翼在岩石的最高处安营扎寨。他是一位专门训练当地霜刃豹的训练师，并担任联盟成员的导师，指导他们获得霜刃豹伙伴。",al={"谁在霜刀石","霜刀石训练师","雷沃位置"}},{q="部落玩家可以在这里训练野兽吗？",a="不能。雷沃·霜翼仅向联盟值得信赖的盟友提供训练和伙伴野兽。部落旅行者在山顶上得不到欢迎。",al={"部落与霜刀石","部落能否获得霜刃豹","雷沃与部落"}},{q="岩石周围有哪些生物？",a="冰冷的岩石和周围的高原是野生霜刃豹的家园，它们与其它适应冬泉谷严酷气候的耐寒野兽一起潜行在雪地中。",al={"这里有什么生物","霜刀石野兽","冬泉谷的霜刃豹"}}},fp="15,204,21.551.0,31.203.0,36.160.0,41.172.0"}
P.entries["subzone:frostwhisper-gorge"] = {n="霜语峡谷",s="霜语峡谷是一道位于冬泉谷南部高地的寒冷峡谷，坐落在邪恶的暗语峡谷正北方。古老的暗夜精灵遗迹散布在冰冷的谷底和周围的悬崖上，高耸的霜槌巨人在峡谷中横行。在东侧边缘的高处，有一个孤独的矮人营地，俯瞰着下方通往海洋的悬崖。",h="霜语峡谷是一道位于冬泉谷南部高地的寒冷峡谷，坐落在邪恶的暗语峡谷正北方。古老的暗夜精灵遗迹散布在冰冷的谷底和周围的悬崖上，高耸的霜槌巨人在峡谷中横行。在东侧边缘的高处，有一个孤独的矮人营地，俯瞰着下方通往海洋的悬崖。",kw={"暗语峡谷","霜槌巨人","霜语峡谷","铁炉堡","冬泉谷"},ang={["race:Dwarf"]="在峡谷东侧边缘的高处，一位不知名的矮人旅行者安营扎寨，挂起了铁炉堡的旗帜，放着一把步枪和充足的麦芽酒，以此欣赏海洋的壮阔景色。",["race:NightElf"]="峡谷积雪的深处保留着古代暗夜精灵建筑的破碎残骸，如今霜槌巨人在其中徘徊。"},sec={{t="满布遗迹与巨人的冰封深渊",b="霜语峡谷开凿在冬泉谷南部的群山之中，是通往恶魔盘踞的暗语峡谷深处前的一道门槛。其积雪的谷底和崖壁上遍布着被遗忘的古代暗夜精灵定居点的石刻。如今，这座峡谷被巨大的霜槌巨人和它们的守护者所占据。进入峡谷的旅程十分危险，因为这些巨人会猛烈地保卫着冰封的岩架，抵御任何游荡的入侵者。"},{t="东侧瞭望台",b="在峡谷东侧悬崖顶端的一条狭窄、安静的小路旁，隐藏着一个奇特的哨所。骑乘双足飞龙或狮鹫往返于艾萨拉、奥格瑞玛和冬泉谷之间的飞行旅行者们常会从上方瞥见它：一个位于世界边缘的孤独矮人营地。营地插着铁炉堡的旗帜，摆放着补给箱、麦芽酒桶、一把舒适的椅子，还有一把靠在支架上的步枪，让人能在此处欣赏到下方无尽之海的绝美景色。"}},faq={{q="霜语峡谷中居住着哪些生物？",a="峡谷底部和周围的台地上居住着强大的霜槌巨人和霜槌守护者。",al={"霜语峡谷的怪物","霜语峡谷居住着什么","霜语峡谷怪物"}},{q="霜语峡谷位于哪里？",a="它位于冬泉谷南端，开凿在暗语峡谷以北的冰冷悬崖之中。",al={"霜语峡谷位置","霜语峡谷在哪里","霜语峡谷地图"}},{q="东侧悬崖上的那个小型矮人营地是什么？",a="隐藏在俯瞰峡谷的东侧山脊高处，有一个插着铁炉堡旗帜的宁静营地。它由一把椅子、一把步枪、补给箱和大量的酒组成，从这里可以俯瞰悬崖边缘，望向海洋。",al={"冬泉谷矮人营地","霜语峡谷铁炉堡旗帜","东侧悬崖营地"}},{q="峡谷下方有暗夜精灵遗迹吗？",a="是的。破碎的暗夜精灵柱子和石刻散布在峡谷底部和上方的崖壁上，那是古代卡多雷定居点的残迹。",al={"霜语峡谷精灵遗迹","冬泉谷峡谷的暗夜精灵建筑"}}},fp="18,371,34.477.0,20.511.0,42.110.0,36.110.0,51.231.0,44.167.0"}
P.entries["subzone:fungal-rock"] = {n="蘑菇石",s="蘑菇石是位于安戈洛环形山东北侧峭壁中一处潮湿的洞穴凹地。这里充斥着极具攻击性的灵长类生物和茂密的幽灵菇，是环形山中最危险的猿类巢穴之一。",h="蘑菇石是位于安戈洛环形山东北侧峭壁中一处潮湿的洞穴凹地。这里充斥着极具攻击性的灵长类生物和茂密的幽灵菇，是环形山中最危险的猿类巢穴之一。",kw={"a-me 01","环形山","蘑菇石","幽灵菇","大猩猩","乌卡","乌克洛克","安戈洛"},ang={["profession:Herbalism"]="蘑菇石是安戈洛环形山采集幽灵菇的主要地点之一，尽管采集者必须应对成群结队的领地大猩猩才能接近它们。",["race:Gnome"]="侏儒同胞们可能会被吸引到蘑菇石，调查A-Me 01的命运，这是卡娜·雷姆旅行者留下的雄心勃勃的机械猿原型机，就停在入口的水潭附近。"},sec={{t="猿穴",b="蘑菇石位于安戈洛环形山东北边缘的一处小瀑布和水潭后方，是该地区大型大猩猩的主要巢穴。在潮湿的地下通道内，高大的安戈洛践踏者和雷霆巨猩在稀有的幽灵菇丛中巡逻。洞穴的最深处盘踞着极具领地意识的巨兽，包括强大的银背大猩猩乌卡，以及难以捉摸的白化大猩猩乌克洛克。除了这些原始居民外，好奇的旅行者可能会在洞口附近发现一些人造的奇特之物，比如被侏儒研究员遗弃的受损机械猿A-Me 01。"}},faq={{q="什么是蘑菇石？",a="蘑菇石是一个位于安戈洛环形山东北侧岩壁内的大型洞穴系统。它以潮湿的环境、丰富的幽灵菇以及大量敌对大猩猩而闻名。",al={"蘑菇石在哪里","什么是蘑菇石洞穴"}},{q="谁统治着蘑菇石里的猿群？",a="该洞穴由乌卡统治，这只体型庞大且强大的银背大猩猩栖息在最深处的洞室中。罕见的白色大猩猩乌克洛克也常在这些洞穴中徘徊。",al={"谁是乌卡","蘑菇石首领","蘑菇石领袖"}},{q="为什么洞外有一只机械大猩猩？",a="在入口外水潭附近静静伫立着A-Me 01，这是一只由侏儒研究员卡娜·雷姆旅行者制造的工程机械猿。它在野外观察期间发生故障，目前正等待回收或维修。",al={"什么是a-me 01","安戈洛机器人大猩猩","a-me 01"}},{q="蘑菇石里生长着什么珍贵资源？",a="洞穴内部潮湿阴暗，为幽灵菇提供了理想的生长环境，使其成为卡利姆多南部为数不多可以采集这种珍贵真菌的地方之一。",al={"安戈洛幽灵菇","蘑菇石药草"}}},fp="11,221,11.593.0,20.195.0,38.177.0,51.195.0,44.194.0"}
P.entries["subzone:fungal-vale"] = {n="蘑菇谷",s="蘑菇谷是位于东瘟疫之地中南部的一处深陷的枯萎洼地，位于皇冠哨塔和玛瑞斯农场正北方。这里充斥着昏暗的薄雾，覆盖着深紫色的泥土，展现了亡灵瘟疫那原始且具有变异性的力量。到处徘徊着天灾军团的恐怖生物，以及侍奉The Cult of the Damned的凡人侍僧。",h="蘑菇谷是位于东瘟疫之地中南部的一处深陷的枯萎洼地，位于皇冠哨塔和玛瑞斯农场正北方。这里充斥着昏暗的薄雾，覆盖着深紫色的泥土，展现了亡灵瘟疫那原始且具有变异性的力量。到处徘徊着天灾军团的恐怖生物，以及侍奉The Cult...",kw={"枯萎","皇冠哨塔","the cult of the damned","东瘟疫之地","蘑菇谷","真菌","玛瑞斯农场","亡灵瘟疫","天灾军团"},ang={["class:Druid"]="蘑菇谷是对自然生命的终极嘲弄，在这里，自然的循环已被天灾军团所驱动的永恒、邪恶的腐朽所取代。",["profession:Herbalism"]="那片枯萎、被真菌窒息的土地，是对死灵法术给洛丹伦原生植物所造成影响的严酷警示。"},sec={{t="腐烂花园",b="蘑菇谷位于玛瑞斯农场以北，是洛丹伦受腐蚀最严重的区域之一。这里的地面呈现出病态的紫色，肿胀着异样的真菌生长物，淹没在死灵孢子产生的永恒阴霾之中。亡灵瘟疫并没有单纯地摧毁生态系统，而是扭曲了土壤以培育邪恶的植物，喂养着恐怖的食腐兽和行尸走肉。The Cult of the Damned的成员经常出没于此，照料那些枯萎的花朵，并在反自然的腐朽中进行邪恶的仪式。"}},faq={{q="什么是蘑菇谷？",a="这是一处位于东瘟疫之地南部边缘的被腐蚀的峡谷，位于皇冠哨塔和玛瑞斯农场正北方。该区域受到亡灵瘟疫的严重污染，使正常的植被转变成了过度生长的真菌枯萎物。",al={"蘑菇谷在哪里","蘑菇谷背景故事","蘑菇谷概览"}},{q="为什么这里的地面是紫色的？",a="土壤已经被亡灵瘟疫彻底浸透。坏死污染并没有让植物彻底死亡，而是将这片土地变异为滋生致命孢子的温床，使泥土变成了淤青般的紫色。",al={"为什么地面是紫色的","瘟疫之地紫色泥土","蘑菇谷地面"}},{q="谁控制着这片区域？",a="蘑菇谷由天灾军团和The Cult of the Damned的凡人邪教徒控制。亡灵怪物在薄雾中徘徊，与那些培育受腐蚀真菌生态系统的侍僧们为伍。",al={"谁在蘑菇谷","蘑菇谷敌人","蘑菇谷邪教徒"}},{q="相对于当地地标，它的位置在哪里？",a="它位于东瘟疫之地中南部，处于玛瑞斯农场和皇冠哨塔之间道路的正北方。",al={"如何前往蘑菇谷","蘑菇谷位置","靠近皇冠哨塔"}}},fp="11,374,15.564.0,24.254.0,30.234.0,23.177.0,48.131.0"}
P.entries["subzone:furlbrow-s-pumpkin-farm"] = {n="法布隆南瓜农场",s="法布隆南瓜农场是位于西部荒野北部的一处被占领的家园，就在从艾尔文森林通往这里的主干道旁边。这里曾经是一片由农夫法布隆和他的妻子弗娜·法布隆精心打理的繁茂农田，但现在农场和农舍已经被迪菲亚潜行者和四处徘徊的收割机傀儡强占了。",h="法布隆南瓜农场是位于西部荒野北部的一处被占领的家园，就在从艾尔文森林通往这里的主干道旁边。这里曾经是一片由农夫法布隆和他的妻子弗娜·法布隆精心打理的繁茂农田，但现在农场和农舍已经被迪菲亚潜行者和四处徘徊的收割机傀儡强占了...",kw={"迪菲亚","农场","法布隆","收割机傀儡","贾森","南瓜","弗娜","西部荒野"},ang={["faction:Alliance"]="这个被占领的农场有力地控诉了暴风城无力保护其核心领土，致使忠诚的纳税农民面对强盗时毫无防备。"},sec={{t="失落的收成",b="法布隆南瓜农场坐落在西部荒野的北部边界附近，曾经因出产能够供应王国的优质农作物而闻名。但随着迪菲亚潜行者横扫乡间，这一切都结束了。不法之徒将农夫法布隆和他的妻子弗娜赶出了家园，留下他们的农田被设定为攻击任何靠近者的机械收割机傀儡所占据。由于农场建筑被强盗占用，田野里到处是叛变的机械，合法的农场主人被迫在贾森农场附近的路边露宿，哀悼他们失去的家园和生计。"},{t="迪菲亚据点",b="农场的陷落凸显了整个西部荒野法律与秩序的全面崩溃。由于暴风城的驻军兵力薄弱，无力保护乡村的自由农户，迪菲亚潜行者轻易地占领了像法布隆农场这样的家园。强盗们将此地用作集结地和营地，并让致命的收割机卫兵守卫周边，使附近公路上的旅客极易遭到伏击。"}},faq={{q="谁拥有这个南瓜农场？",a="该农场属于农夫法布隆和他的妻子弗娜·法布隆。然而，当不法之徒占领该地区时，他们被迫离开了自己的房产，导致这对夫妇不得不前往贾森农场附近的路边避难。",al={"谁拥有法布隆农场","法布隆农场主","谁住在这里"}},{q="为什么农场被废弃了？",a="农场被迪菲亚潜行者暴力接管。他们赶走了法布隆一家，在建筑物中驻扎了暴徒，并利用失控的机械收割机傀儡守卫周围的南瓜地。",al={"为什么被废弃了","农场发生了什么","为什么强盗在这里"}},{q="法布隆一家现在在哪里？",a="农夫法布隆和他的妻子在农场东北方向的主路旁找到了栖身之所，靠近贾森农场，他们带着自己的马车和财物滞留在那儿。",al={"农夫法布隆在哪里","法布隆位置","寻找法布隆"}},{q="为什么这里的机械收割机傀儡会攻击人？",a="这些机械构装体被设定为攻击西部荒野的居民，并巡逻迪菲亚控制的土地。它们的确切起源尚不确定。",al={"收割机傀儡","为什么傀儡充满敌意","谁制造了傀儡"}}},fx={["3bec6795"]={q="法布隆南瓜农场是什么地方？",a="法布隆南瓜农场是西部荒野北部一处被占据的农庄，曾专为暴风王国种植南瓜。如今，它成了王国衰败的又一牺牲品，肥沃的田地无人照料，落入了亡命之徒手中。",al={"法布隆南瓜农场是什么地方","法布隆南瓜农场的传说","法布隆农场"}},["1ceb8202"]={q="法布隆南瓜农场发生过什么事？",a="迪菲亚潜行者在西部荒野兴起后，他们的强盗横扫当地，迫使农夫法布隆和他的妻子维尔娜仓皇逃命。迪菲亚潜行者占据了农场，在农舍里安插窃贼，还放出机械收割傀儡在南瓜田里巡逻。",al={"法布隆农场的历史","法布隆农场怎么了","法布隆家是如何败落的"}},["25362e80"]={q="法布隆南瓜农场危险吗？",a="危险。农场已成为迪菲亚的据点。敌对的强盗占据着建筑，失控的收割傀儡则在南瓜田里徘徊，攻击任何胆敢靠近的旅人或流离失所的农民。",al={"法布隆农场危险吗","法布隆农场的危险","法布隆农场的威胁"}}},fp="23,278,14.594.0,17.414.0,27.212.0,26.207.0,28.163.0,56.149.0"}
P.entries["subzone:gadgetzan"] = {n="加基森",s="加基森是热砂港在塔纳利斯北部的一座围墙沙漠枢纽，也是当地商业的中心。这座城镇向部落和联盟的旅行者开放，实行严格的地精中立政策，欢迎任何有钱消费或有工作可做的人。",h="加基森是热砂港在塔纳利斯北部的一座围墙沙漠枢纽，也是当地商业的中心。这座城镇向部落和联盟的旅行者开放，实行严格的地精中立政策，欢迎任何有钱消费或有工作可做的人。",kw={"拍卖行","加基森","地精","中立","热砂港","塔纳利斯","食沙者","清泉平原"},ang={["profession:Blacksmithing"]="镇上设有高级金属加工者青睐的重型锻炉和铁砧，是秘银会成员的重要补给点。",["profession:Engineering"]="加基森是技工们的重要十字路口，这里拥有高级训练师、专业图纸，以及专门为侏儒工程师校准的到达传送台。"},sec={{t="沙丘中的利润堡垒",b="加基森四周环绕着灼热的沙海，是热砂港在卡利姆多南部进行冒险活动的区域中心。这座城镇以典型的地精独创性和随意的建筑风格而建，拥有独立的拍卖行、银行、旅店，以及为工程师、锻造师和炼金术师提供的专业制造设施。它还设有服务于两大阵营的飞行管理员，确保了前往塔纳利斯、菲拉斯和安戈洛环形山未开发盆地的冒险者川流不息。最重要的是，商业至上：只要游客不拔出武器且慷慨解囊，他们在城内就是安全的。"},{t="沙漠危机与强力秩序",b="加基森的和平并非源于善意，而是靠全副武装的地精卫兵来维持，他们会迅速殴打任何威胁贸易或挑起阵营斗殴的人。然而，城门外的生活却岌岌可危。加基森水业公司不断与横行霸道的食沙者强盗进行战斗，这帮强盗占据了至关重要的清泉平原。水在塔纳利斯如同液态黄金，贸易财团经常雇佣外来的雇佣兵来铲除强盗首领，并收回至关重要的水袋，以维持城镇蓄水池的正常运转。"}},faq={{q="联盟和部落可以在加基森相互攻击吗？",a="不可以。加基森是由热砂港拥有的严格中立领土。地精卫兵会对城镇进行严密巡逻，并会立即攻击任何扰乱和平或对其他旅行者发起暴力行为的人。",al={"加基森安全吗","加基森pvp","部落和联盟可以在这里打架吗"}},{q="为什么水在这里如此重要？",a="加基森坐落于干旱的沙漠之中，完全依赖加基森水业公司在清泉平原的抽取塔。食沙者强盗占领了这些水井，切断了城镇的主要水源，迫使地精花钱悬赏回收被盗的水袋。",al={"加基森水业公司","为什么需要水袋","清泉平原冲突"}},{q="谁控制着加基森？",a="加基森由热砂港所有并管理，这是艾泽拉斯最大、最显赫的地精商业组织。",al={"谁在运营加基森","加基森阵营","哪个财团拥有加基森"}},{q="这里的拍卖行有什么特别之处？",a="与奥格瑞玛或暴风城中受阵营限制的市场不同，加基森设有一个中立拍卖行。在这里，联盟和部落玩家可以相互买卖商品，尽管地精会为此收取高得多的交易手续费。",al={"加基森拍卖行","中立拍卖行","跨阵营拍卖行"}}},fp="9,283,32.645.0,34.527.0,54.228.0,41.290.0,23.133.0,42.256.0"}
P.entries["subzone:gahrron-s-withering"] = {n="盖罗恩农场",s="盖罗恩农场是一处位于西瘟疫之地东侧边界，靠近前往东瘟疫之地路径的腐化农庄。它曾经是洛丹伦一片繁茂的农田，如今却被天灾军团占领，并且架设了一口巨大的大熔炉，不断向空气中散发着剧毒的瘟疫蒸汽。",h="盖罗恩农场是一处位于西瘟疫之地东侧边界，靠近前往东瘟疫之地路径的腐化农庄。它曾经是洛丹伦一片繁茂的农田，如今却被天灾军团占领，并且架设了一口巨大的大熔炉，不断向空气中散发着剧毒的瘟疫蒸汽。",kw={"大熔炉","达隆郡","盖罗恩","盖罗恩农场","约瑟夫·雷德帕斯","索拉兹"},ang={["class:Paladin"]="大熔炉领主索拉兹的大熔炉中喷出的恶臭毒雾，以及徘徊在荒废田野上的The Restless Dead，使得这座农场成为了圣光净化行动的首要目标。",["faction:Alliance"]="对于联盟的老兵来说，这座农场有着沉重的意义：达隆郡英雄约瑟夫·雷德帕斯队长那开裂的盾牌，仍躺在它被诅咒的土地上。"},sec={{t="从丰收走向凋零",b="在第三次战争摧毁洛丹伦王国之前，这座庄园还是一处耕作中的农场。在The Cult of the Damned和天灾军团席卷大地之前，它那肥沃的田野曾为王国出产谷物。如今，它被称为盖罗恩农场，宅邸已破碎荒废。萦绕的幻象、哀嚎的幽灵和The Restless Dead在破败的附属建筑中徘徊，受命于巫妖王的亡灵监工在此看守。"},{t="大熔炉与雷德帕斯的陨落",b="在这一片枯萎田野的中央，坐落着天灾军团的一口大型瘟疫大熔炉，由大熔炉领主索拉兹负责看管。这口大熔炉不断向周围的大气中喷吐着有害的毒雾，毒害土地并驱逐自然生命。除了传播瘟疫的作用外，这座农场也见证了附近达隆郡悲剧的高潮：正是在这里，联盟的保卫者们最终与屈服于黑暗腐化的约瑟夫·雷德帕斯队长进行了对决，并将他击倒。这位战士破碎的盾牌至今仍遗落在被诅咒的土地上。"}},faq={{q="盖罗恩农场在瘟疫爆发前叫什么名字？",a="该农场在瘟疫爆发前的名字并无记载；如今人们只知其名为盖罗恩农场。在天灾军团蹂躏这片乡村之前，它曾是洛丹伦一处活跃的农庄。",al={"最初的名字","旧名","盖罗恩急速"}},{q="为什么这里有一口巨大的大熔炉？",a="这口大熔炉是天灾军团部署的瘟疫装置，用于将瘟疫蒸汽散布到整个地区。大熔炉领主索拉兹守卫着这台设备，以确保它能持续不断地污染土壤和空气。",al={"瘟疫大熔炉","大熔炉的作用","田里的罐子"}},{q="谁是约瑟夫·雷德帕斯，他为什么在这里很重要？",a="约瑟夫·雷德帕斯队长是附近达隆郡的保卫者之一，也是记载于该镇史册中的英雄之一。他那开裂的盾牌至今仍躺在这座农庄的谷仓旁，那是达隆郡悲剧陨落的一件遗物。",al={"雷德帕斯的盾牌","雷德帕斯队长","与达隆郡的关系"}},{q="目前是谁控制着盖罗恩农场？",a="该农场目前被天灾军团牢牢控制。这里充满了幽灵怨灵、哀嚎的亡者和萦绕的幻象，全部由强大的通灵军官大熔炉领主索拉兹指挥。",al={"谁在这里","盖罗恩的怪物","天灾军团占领"}}},fp="19,305,21.416.0,36.567.1,54.180.0,35.205.0,51.207.1,43.187.0"}
P.entries["subzone:galardell-valley"] = {n="加拉德尔山谷",s="加拉德尔山谷是坐落在赤脊山东北部高地中的一处崎岖而危险的峡谷。该峡谷被充满侵略性的豺狼人族群所占据，并处于臭名昭著的伊尔加拉之塔的阴影之下。",h="加拉德尔山谷是坐落在赤脊山东北部高地中的一处崎岖而危险的峡谷。该峡谷被充满侵略性的豺狼人族群所占据，并处于臭名昭著的伊尔加拉之塔的阴影之下。",kw={"獠牙中尉","加拉德尔山谷","豺狼人","莫甘斯","赤脊山","伊尔加拉之塔"},ang={["faction:Alliance"]="只要豺狼人族群和莫甘斯的黑暗力量控制着加拉德尔山谷，湖畔镇捉襟见肘的城镇守卫就无法确保东北道路的安全。"},sec={{t="野兽与阴影的巢穴",b="加拉德尔山谷开凿在赤脊山的东北部峭壁之中，如今已完全脱离了湖畔镇守军的控制。凶猛的赤脊山豺狼人在低地游荡，并沿着峡谷底部扎营，在像獠牙中尉这样的残酷头目的组织下活动。在峡谷的高处耸立着黑暗的伊尔加拉之塔，那是叛逃法师莫甘斯的据点，使得整个山谷成为了周边定居点挥之不去的梦魇。"}},faq={{q="加拉德尔山谷位于哪里？",a="加拉德尔山谷位于赤脊山的极东北角，隐藏在止水湖北部道路后的高耸岩架之后。",al={"加拉德尔山谷位置","加拉德尔山谷在哪里","如何找到加拉德尔山谷"}},{q="山谷里居住着什么生物？",a="山谷被嗜血的豺狼人族群占据，它们在崎岖的小径上成群巡逻，由像獠牙中尉这样危险的暴徒所统领。",al={"加拉德尔山谷的怪物","谁住在加拉德尔山谷","加拉德尔的敌人"}},{q="俯瞰山谷的那座黑暗之塔是什么？",a="那是伊尔加拉之塔，一座巍峨的石制建筑，是叛逃术士莫甘斯的行动基地。",al={"加拉德尔山谷之塔","加拉德尔上方的尖塔","赤脊山豺狼人附近的塔"}},{q="獠牙中尉是谁？",a="獠牙中尉是一位驻扎在山谷内的强大豺狼人首领。他以狡诈和凶残着称，在受到挑战时会嚎叫召唤附近的豺狼人族群支援，迅速淹没毫无防备的旅人。",al={"獠牙中尉","加拉德尔山谷首领"}}},fx={["3f06acf8"]={q="加拉德尔山谷是什么地方？",a="加拉德尔山谷是一处崎岖的盆地，隐于赤脊山东北部。伊尔加拉之塔的巍峨剪影俯视着山谷；如今这里已落入敌手，被成群的凶暴豺狼人彻底占据，并笼罩在黑暗魔法之中。",al={"加拉德尔山谷是什么地方","加拉德尔山谷的传说","介绍一下加拉德尔山谷"}},eb0794a1={q="加拉德尔山谷有多危险？",a="这里极其危险。凶猛的豺狼人群在峭壁和茂密灌木丛间巡逻，彼此协作，围攻闯入者。更糟的是，它们的首领，Lieutenant Fangore，能迅速召来附近的援兵，击溃毫无防备的旅人；这一切都发生在黑暗术士 Morganth 的注视之下。",al={"加拉德尔山谷危险吗","加拉德尔山谷的危险","这里安全吗"}}},fp="16,218,26.483.0,34.167.0,34.139.0,46.128.0,26.213.0"}
P.entries["subzone:gallery-of-treasures"] = {n="Gallery of Treasures",s="Gallery of Treasures是血色修道院内一条装饰华丽且戒备森严的走廊，连接着猎犬训练室与图书馆。走廊两旁陈列着回收的画作、圣物和泥金装饰手抄本，展示了血色十字军在针对亡灵的狂热战争中，所保存的洛丹伦的财富与遗产。",h="Gallery of...",kw={"图书馆","gallery of treasures","图书馆区域","洛丹伦圣物","画作","血色修道院"},ang={["class:Paladin"]="画廊两旁陈列的文物和旗帜反映了白银之手和没落的洛丹伦曾经的荣耀，尽管现在被一群将正义信念扭曲为盲目狂热的狂徒所占据。",["race:Undead"]="这里保存的画作和历史传家宝曾属于被遗忘者的祖先，却被意图抹杀洛丹伦前公民的活着的十字军战士嫉妒地守卫着。"},sec={{t="失落遗产的宝库",b="Gallery of Treasures位于血色修道院图书馆区域的深处，是一座连接猎犬训练室的犬舍与神圣的图书馆档案室的大厅。与猎犬训练室不同，这条走廊两旁挂满了精美的画作和历史文物，并设有数间小室，里面摆放着从洛丹伦王国废墟中抢救出来的书籍。对血色十字军而言，这些圣物代表了他们誓死捍卫的人类纯净传承，他们严密地守卫着这些藏品，防止任何胆敢闯入其圣域的外来者。"}},faq={{q="Gallery of Treasures位于何处？",a="它位于血色修道院的图书馆区域内。该画廊紧邻猎犬训练室，是通往图书馆前的最后一条装饰走廊。",al={"画廊位置","gallery of treasures在哪里","如何找到gallery of treasures"}},{q="Gallery of Treasures里保存着什么？",a="画廊内存放着保存下来的艺术品、历史圣物、泥金装饰手抄本和从洛丹伦王国废墟中抢救出的画作，陈列在走廊和相邻的阅览室中。",al={"gallery of treasures里有什么","画廊掉落","画廊圣物"}},{q="为什么血色十字军要收集这些宝藏？",a="血色十字军视自己为洛丹伦真正的残部。通过搜集和囤积这些文化作品，他们得以保存祖国记忆与神圣遗产，同时清除这片土地上他们眼中所谓的污秽。",al={"为什么血色十字军有宝藏","十字军圣物用途"}},{q="谁在守卫画廊？",a="该走廊由各类血色十字军狂热者巡逻，包括守卫着通往奥法师杜安和修道院深处档案室道路的防御者和新兵。",al={"画廊怪物","谁在gallery of treasures里"}}},fx={a0f9e8c0={q="Gallery of Treasures 危险吗？",a="是的，危险重重。画廊由狂热的血色十字军守卫，他们将任何外来者都视为腐化势力或天灾军团的爪牙。想要穿过其中华丽的厅堂，就得击退纪律严明、随时准备当场屠杀擅闯者的十字军。",al={"gallery of treasures 危险吗","gallery of treasures 的危险","血色修道院画廊的危险"}}},fp="20,342,29.584.0,42.194.0,41.200.0,53.234.0,23.187.0"}
P.entries["subzone:gallows-end-tavern"] = {n="恐惧之末旅店",s="恐惧之末旅店是布瑞尔主要的旅店，也是提瑞斯法林地中被遗忘者好客精神的中心。除了为疲惫的旅人提供住所和烈酒外，它还是职业训练师、商业导师和秘密审讯的重要枢纽。",h="恐惧之末旅店是布瑞尔主要的旅店，也是提瑞斯法林地中被遗忘者好客精神的中心。除了为疲惫的旅人提供住所和烈酒外，它还是职业训练师、商业导师和秘密审讯的重要枢纽。",kw={"布瑞尔","被遗忘者","恐惧之末","恐惧之末旅店","旅店老板","血色十字军俘虏","提瑞斯法林地","亡灵"},ang={["faction:Alliance"]="在酒吧大厅的地板下，被遗忘者关押着俘虏的联盟侦察兵和血色十字军狂热者，以便获取情报并进行审讯。",["race:Undead"]="作为离开丧钟镇后遇到的第一个主要旅店，恐惧之末旅店是刚觉醒的被遗忘者进入广阔世界时的文化和功能十字路口。"},sec={{t="亡者的聚会之所",b="恐惧之末旅店坐落在布瑞尔的道路旁，十分显眼，是刚从丧钟镇觉醒并向南前往幽暗城的被遗忘者的主要聚集地。尽管身处不死之躯，被遗忘者们仍频繁出入于此，进行社交、贸易和寻求庇护。旅店里有各种职业训练师——指导年轻的战士、牧师、法师、潜行者和术士——此外还有商人和医疗从业者。"},{t="地窖中的秘密",b="在吱呀作响的地板和旅店的欢笑声之下，隐藏着一个更加阴森的目的。在地窖里，被遗忘者将战俘关押并严加看守，不让公众看到。其中包括一名血色十字军俘虏和一名矮人山地猎人，他们被关押在旅店下方接受审讯和实验，因为被遗忘者正奋力守卫他们的边界，抵御狂热的十字军和联盟侦察兵。"}},faq={{q="恐惧之末旅店位于哪里？",a="它位于布瑞尔的中心，这是幽暗城以北、提瑞斯法林地内主要的被遗忘者定居点。",al={"恐惧之末位置","恐惧之末旅店在哪里","布瑞尔旅店位置"}},{q="为什么亡灵需要旅店或酒馆？",a="虽然被遗忘者不需要睡眠或凡人的食物来生存，但像恐惧之末旅店这样的地方能够维持他们生前的社会联系和文化习惯。它同时也作为一个安全的市政中心，用于训练、商业和处理公务。",al={"为什么亡灵喝酒","为什么被遗忘者需要旅店","亡灵旅店背景故事"}},{q="谁被关押在地下室里？",a="在旅店下方的地窖里，被遗忘者关押着俘虏的敌人，其中包括来自敌对的血色十字军的一名血色十字军俘虏，以及一名联盟的矮人山地猎人。",al={"旅店囚犯","谁在地窖里","布瑞尔旅店地下室"}},{q="这里可以找到哪些服务和训练师？",a="旅店里有战士、牧师、法师、潜行者和术士的训练师，还有急救和附魔训练师、各类贸易商人以及旅店老板。",al={"恐惧之末训练师","布瑞尔旅店有哪些训练师","旅店商人"}}},fx={d83e4303={q="恐惧之末旅店是什么地方？",a="恐惧之末旅店是提瑞斯法林地布瑞尔的社交中心，也是重要的休憩之所。它坐落在洛丹伦染疫的废墟之中，是被遗忘者经营的首屈一指、设施齐全的旅店。旅人、药剂师助手和途经的冒险者聚集在歪斜的木梁下休息、寻求建议、交易补给，并在常驻导师的指导下学习黑暗与武技。",al={"什么是恐惧之末旅店","介绍一下恐惧之末旅店","恐惧之末旅店"}},ae373cb3={q="恐惧之末旅店危险吗？",a="对于被遗忘者和部落的忠诚盟友而言，这里是由布瑞尔亡灵卫兵守护的坚固庇护所。不过，危险潜伏在地板之下。地窖关押着被俘的敌人——其中有一名正待审讯的血色狂热者和一名铁炉堡山地矮人——提醒所有来客，与活着的狂热者和入侵者之间的战争就在家门口。",al={"恐惧之末危险吗","恐惧之末旅店的危险","恐惧之末安全吗"}}},fp="19,258,30.446.0,21.405.0,41.114.0,40.248.0,34.165.0,45.170.0"}
P.entries["subzone:gaping-chasm"] = {n="大裂口",s="大裂口是一座巨大的其拉虫人巢穴，深深刻入塔纳利斯东南部的沙地之中。这里被极具攻击性的哈扎里虫群所占据，它们作为一种严峻的警示，昭示着其拉虫人的威胁正越过西部荒漠不断蔓延。",h="大裂口是一座巨大的其拉虫人巢穴，深深刻入塔纳利斯东南部的沙地之中。这里被极具攻击性的哈扎里虫群所占据，它们作为一种严峻的警示，昭示着其拉虫人的威胁正越过西部荒漠不断蔓延。",kw={"菲兹杜瑟","大裂口","哈扎里","巢穴","掘沙者","斯克林山克","其拉虫人","塔纳利斯"},ang={["profession:Mining"]="暴露出来的地下裂隙和其拉虫人巢穴的塌陷处偶尔会露出丰富的矿藏，但挖掘它们需要抵御成群结队的凶猛穴居昆虫。",["race:Gnome"]="初级勘探员斯克林山克在大裂口中的不幸遇难，发人深省地提醒着人们：在卡利姆多进行实地考察，既需要科学的探索精神，也需要强大的火力。"},sec={{t="沙丘中的巢穴",b="在大裂口打破塔纳利斯起伏的广袤地表，直直坠入深处，那是纵横交错的地下通道、树脂堆积而成的土丘和不停颤动的几丁质甲壳所构成的拥挤迷宫。这座巢穴属于哈扎里——一种在荒漠地下掘洞的极具侵略性的其拉虫群。在充斥着地底蜇刺虫、虫群和庞大的掘沙者的情况下，任何胆敢深入裂口的旅行者或寻宝者，很快就会发现自己成为了猎物，或者被包裹在粘稠的虫茧中。"},{t="勘探员之墓",b="不断扩张的巢穴引起了加基森那些充满进取心的头脑的注意，高级勘探员菲兹杜瑟因此派遣了他的初级勘探员斯克林山克前往坑洞，测绘并评估由虫洞引发的地质变化。不出所料，这次探险以灾难告终。斯克林山克在吱吱作响的虫群中迎来了一个凄惨的结局，他遗落的装备和测量仪器至今仍在告诫人们，切勿低估其拉虫人的威胁。"}},faq={{q="大裂口里居住着什么生物？",a="裂口完全被哈扎里其拉虫人所占据。巢穴中包含了该昆虫物种的多个阶级，例如工蜂、带翅的蜇刺虫、铺天盖地的虫群，以及体型庞大、覆盖着几丁质甲壳的掘沙者。",al={"大裂口里住着什么","塔纳利斯裂口的虫子","大裂口的怪物"}},{q="大裂口位于哪里？",a="大裂口位于塔纳利斯东南部，它是在加基森以南、将塔纳利斯与西部荒野分隔开的山脊以东的沙漠沙地中凿出来的。",al={"大裂口在哪里","大裂口位置","如何找到大裂口"}},{q="为什么要派一名侏儒勘探员进入裂口？",a="加基森的高级勘探员菲兹杜瑟派遣初级勘探员斯克林山克去勘探洞穴并评估其地质活动。不幸的是，在完成任务之前，斯克林山克就被哈扎里其拉虫人压制并杀害了。",al={"斯克林山克是谁","菲兹杜瑟的勘探员任务","为什么斯克林山克要去那里"}},{q="这里的其拉虫人与卡利姆多其他地区的虫人有关联吗？",a="是的。塔纳利斯的哈扎里其拉虫人与在南贫瘠之地以及西部被腐蚀的希利苏斯荒原中发现的虫群拥有相同的昆虫本质和群体思维结构，这标志着一股危险的、协调一致的势力正在整个卡利姆多南部扩张。",al={"这些其拉虫人和希利苏斯有关联吗","为什么塔纳利斯有虫子"}}},fp="12,257,21.484.0,18.469.0,45.216.0,34.169.0,45.248.1,69.252.0"}
